const HTML = "<!doctype html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex, nofollow, noarchive\">\n<title>つむぎ 変更管理台帳</title>\n<style>:root{color-scheme:light dark}html,body{margin:0;padding:0}</style>\n<style>\n  :root{\n    --bg:#f7f8fb; --panel:#ffffff; --ink:#171a21; --ink-2:#5a6072; --ink-3:#8a90a2;\n    --line:#e7e9f0; --line-2:#eef0f6; --accent:#4b53c4; --accent-soft:#eceef9;\n    --bug:#d6455f; --bug-soft:#fbe9ec; --feat:#0f8f7e; --feat-soft:#e2f3ef;\n    --imp:#c07a15; --imp-soft:#f8efdd; --ops:#7b8194; --ops-soft:#eef0f4;\n    --crit:#c0392b; --focus:#4b53c4;\n    --mono:ui-monospace,\"SFMono-Regular\",Menlo,Consolas,monospace;\n    --jp:\"Hiragino Sans\",\"Hiragino Kaku Gothic ProN\",\"Yu Gothic\",\"Noto Sans JP\",\"Meiryo\",system-ui,sans-serif;\n  }\n  @media (prefers-color-scheme:dark){\n    :root{\n      --bg:#0f1116; --panel:#171a22; --ink:#e9ebf2; --ink-2:#a2a8bb; --ink-3:#71778a;\n      --line:#262a36; --line-2:#20242e; --accent:#8b93ee; --accent-soft:#20233a;\n      --bug:#f0879a; --bug-soft:#2c1a20; --feat:#5fcdb6; --feat-soft:#152621;\n      --imp:#e0ad5e; --imp-soft:#2a2213; --ops:#9aa0b3; --ops-soft:#21242d;\n      --crit:#f0879a; --focus:#8b93ee;\n    }\n  }\n  :root[data-theme=\"light\"]{\n    --bg:#f7f8fb; --panel:#ffffff; --ink:#171a21; --ink-2:#5a6072; --ink-3:#8a90a2;\n    --line:#e7e9f0; --line-2:#eef0f6; --accent:#4b53c4; --accent-soft:#eceef9;\n    --bug:#d6455f; --bug-soft:#fbe9ec; --feat:#0f8f7e; --feat-soft:#e2f3ef;\n    --imp:#c07a15; --imp-soft:#f8efdd; --ops:#7b8194; --ops-soft:#eef0f4; --crit:#c0392b; --focus:#4b53c4;\n  }\n  :root[data-theme=\"dark\"]{\n    --bg:#0f1116; --panel:#171a22; --ink:#e9ebf2; --ink-2:#a2a8bb; --ink-3:#71778a;\n    --line:#262a36; --line-2:#20242e; --accent:#8b93ee; --accent-soft:#20233a;\n    --bug:#f0879a; --bug-soft:#2c1a20; --feat:#5fcdb6; --feat-soft:#152621;\n    --imp:#e0ad5e; --imp-soft:#2a2213; --ops:#9aa0b3; --ops-soft:#21242d; --crit:#f0879a; --focus:#8b93ee;\n  }\n  *{box-sizing:border-box}\n  body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--jp);line-height:1.65;\n    -webkit-font-smoothing:antialiased;font-feature-settings:\"palt\" 1}\n  .wrap{max-width:1120px;margin:0 auto;padding:40px 22px 80px}\n  .tnum{font-variant-numeric:tabular-nums}\n\n  header.masthead{border-bottom:2px solid var(--ink);padding-bottom:18px;margin-bottom:26px}\n  .eyebrow{font-size:12px;letter-spacing:.22em;color:var(--accent);font-weight:700;margin:0 0 8px}\n  h1{font-size:clamp(26px,4vw,38px);margin:0 0 6px;letter-spacing:.01em;font-weight:800;text-wrap:balance}\n  .sub{color:var(--ink-2);font-size:15px;margin:0}\n  .meta{display:flex;flex-wrap:wrap;gap:8px 22px;margin-top:16px;font-size:12.5px;color:var(--ink-2)}\n  .meta b{color:var(--ink);font-weight:700}\n\n  .stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin:24px 0 28px}\n  .stat{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:15px 16px;position:relative;overflow:hidden}\n  .stat .k{font-size:12px;color:var(--ink-2);font-weight:600;letter-spacing:.02em}\n  .stat .v{font-size:30px;font-weight:800;margin-top:2px;line-height:1}\n  .stat .u{font-size:12px;color:var(--ink-3);margin-left:3px;font-weight:600}\n  .stat::before{content:\"\";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--sc,var(--accent))}\n\n  .toolbar{display:flex;flex-wrap:wrap;gap:10px 14px;align-items:center;margin-bottom:16px}\n  .chips{display:flex;flex-wrap:wrap;gap:7px}\n  .chip{font:inherit;font-size:12.5px;font-weight:600;padding:6px 13px;border-radius:999px;border:1px solid var(--line);\n    background:var(--panel);color:var(--ink-2);cursor:pointer;transition:.14s;display:inline-flex;align-items:center;gap:6px}\n  .chip:hover{border-color:var(--accent);color:var(--ink)}\n  .chip[aria-pressed=\"true\"]{background:var(--ink);color:var(--bg);border-color:var(--ink)}\n  .chip .dot{width:8px;height:8px;border-radius:50%}\n  .chip.k-bug .dot{background:var(--bug)} .chip.k-feat .dot{background:var(--feat)}\n  .chip.k-imp .dot{background:var(--imp)} .chip.k-ops .dot{background:var(--ops)}\n  .search{margin-left:auto;flex:1;min-width:190px;max-width:320px}\n  .search input{width:100%;font:inherit;font-size:13.5px;padding:8px 13px;border-radius:9px;border:1px solid var(--line);\n    background:var(--panel);color:var(--ink)}\n  .search input::placeholder{color:var(--ink-3)}\n  :focus-visible{outline:2px solid var(--focus);outline-offset:2px}\n\n  .count-line{font-size:12.5px;color:var(--ink-2);margin:0 2px 10px}\n\n  .ledger{display:flex;flex-direction:column;gap:9px}\n  .row{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:14px 16px 14px 18px;\n    position:relative;overflow:hidden}\n  .row::before{content:\"\";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--rc)}\n  .row.k-bug{--rc:var(--bug)} .row.k-feat{--rc:var(--feat)} .row.k-imp{--rc:var(--imp)} .row.k-ops{--rc:var(--ops)}\n  .row-top{display:flex;flex-wrap:wrap;align-items:center;gap:8px 10px;margin-bottom:7px}\n  .tag{font-size:11px;font-weight:700;padding:3px 9px;border-radius:6px;letter-spacing:.02em;white-space:nowrap}\n  .tag.k-bug{background:var(--bug-soft);color:var(--bug)} .tag.k-feat{background:var(--feat-soft);color:var(--feat)}\n  .tag.k-imp{background:var(--imp-soft);color:var(--imp)} .tag.k-ops{background:var(--ops-soft);color:var(--ops)}\n  .area{font-size:12px;color:var(--ink-2);font-weight:600;background:var(--line-2);padding:3px 9px;border-radius:6px}\n  .crit{font-size:11px;font-weight:800;color:#fff;background:var(--crit);padding:3px 8px;border-radius:6px;letter-spacing:.03em}\n  .date{margin-left:auto;font-size:12px;color:var(--ink-3);font-family:var(--mono)}\n  .cid{font-size:11.5px;color:var(--ink-3);font-family:var(--mono);background:var(--line-2);padding:2px 7px;border-radius:5px}\n  .title{font-size:15px;font-weight:700;margin:0 0 6px;letter-spacing:.01em}\n  .cf{display:grid;grid-template-columns:auto 1fr;gap:3px 12px;font-size:13px;color:var(--ink-2)}\n  .cf .lb{font-weight:700;color:var(--ink-3);font-size:11.5px;letter-spacing:.04em;padding-top:1px}\n  .cf .tx{color:var(--ink-2)}\n  .cf .tx b{color:var(--ink);font-weight:700}\n  .empty{text-align:center;color:var(--ink-3);padding:44px;font-size:14px}\n\n  section.block{margin-top:44px}\n  .block h2{font-size:18px;font-weight:800;margin:0 0 4px;display:flex;align-items:center;gap:9px}\n  .block h2::before{content:\"\";width:10px;height:20px;border-radius:3px;background:var(--accent)}\n  .block .lead{color:var(--ink-2);font-size:13.5px;margin:0 0 16px}\n  .todo{display:flex;flex-direction:column;gap:8px}\n  .titem{background:var(--panel);border:1px solid var(--line);border-radius:11px;padding:13px 15px;display:flex;gap:13px;align-items:flex-start}\n  .titem .st{font-size:11px;font-weight:800;padding:4px 9px;border-radius:6px;white-space:nowrap;margin-top:1px}\n  .st.plan{background:var(--accent-soft);color:var(--accent)}\n  .st.hold{background:var(--imp-soft);color:var(--imp)}\n  .st.done{background:var(--feat-soft);color:var(--feat)}\n  .titem .body b{display:block;font-size:14px;color:var(--ink);margin-bottom:2px;font-weight:700}\n  .titem .body span{font-size:12.5px;color:var(--ink-2)}\n  .titem .prio{margin-left:auto;font-size:11px;font-weight:700;color:var(--ink-3);white-space:nowrap}\n\n  .docs{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px}\n  .doc{background:var(--panel);border:1px solid var(--line);border-radius:11px;padding:15px 16px}\n  .doc .h{font-weight:700;font-size:14px;margin:0 0 8px;display:flex;align-items:center;gap:8px}\n  .doc .h .n{font-family:var(--mono);font-size:12px;color:#fff;background:var(--accent);border-radius:5px;padding:1px 7px}\n  .doc ul{margin:0;padding-left:18px;font-size:12.8px;color:var(--ink-2)}\n  .doc ul li{margin:4px 0}\n  .doc .note{font-size:11.5px;color:var(--ink-3);margin-top:9px;padding-top:9px;border-top:1px dashed var(--line)}\n\n  footer{margin-top:48px;padding-top:18px;border-top:1px solid var(--line);font-size:12px;color:var(--ink-3)}\n  @media (max-width:560px){\n    .cf{grid-template-columns:1fr;gap:2px} .cf .lb{margin-top:6px}\n    .date{width:100%;margin-left:0;order:5}\n  }\n</style>\n</head>\n<body>\n\n<style>\n  .stats .stat{cursor:pointer;font:inherit;text-align:left;width:100%;transition:.12s}\n  .stats button.stat{border:1px solid var(--line);background:var(--panel)}\n  .stats .stat:hover{border-color:var(--accent);transform:translateY(-1px)}\n  .stats .stat[aria-pressed=\"true\"]{outline:2px solid var(--sc);outline-offset:1px;box-shadow:0 2px 10px rgba(0,0,0,.08)}\n  .chip.k-crit .dot{background:var(--crit)}\n  .chip.k-crit[aria-pressed=\"true\"]{background:var(--crit);border-color:var(--crit);color:#fff}\n  .stat-note{font-size:11.5px;color:var(--ink-3);margin:-14px 2px 22px;line-height:1.5}\n</style>\n<div class=\"wrap\">\n  <header class=\"masthead\"><p class=\"eyebrow\">変更管理台帳 ／ CHANGE LOG</p><h1>つむぎ 修正・機能追加の記録</h1>\n    <p class=\"sub\">いつ・どこを・なぜ直したかを記録し、不具合対応の証跡として残す一覧です。</p>\n    <div class=\"meta\"><span>対象システム <b>つむぎ（通所介護 管理アプリ）</b></span><span>記録期間 <b class=\"tnum\">2026-07-16 〜 09-30</b></span><span>総件数 <b class=\"tnum\" id=\"m-total\">677</b> 件</span><span>版 <b>rev. 6fcf807</b></span></div>\n  </header>\n  <div class=\"stats\">\n    <button class=\"stat\" data-mode=\"bug\" aria-pressed=\"false\" style=\"--sc:var(--bug)\"><div class=\"k\">バグ修正</div><div class=\"v tnum\">237</div></button>\n    <button class=\"stat\" data-mode=\"feat\" aria-pressed=\"false\" style=\"--sc:var(--feat)\"><div class=\"k\">機能追加</div><div class=\"v tnum\">138</div></button>\n    <button class=\"stat\" data-mode=\"imp\" aria-pressed=\"false\" style=\"--sc:var(--imp)\"><div class=\"k\">改善・調整</div><div class=\"v tnum\">302</div></button>\n    <button class=\"stat\" data-mode=\"crit\" aria-pressed=\"false\" style=\"--sc:var(--crit)\"><div class=\"k\">重大な不具合</div><div class=\"v tnum\">71</div><span class=\"u\">再掲・データ保全</span></button>\n  </div>\n  <p class=\"stat-note\">※ <b>バグ修正 42 ＋ 機能追加 42 ＋ 改善・調整 39 ＝ 123 件（総件数）</b>です。「重大な不具合 16」は<b>この中で特に重要なものの再掲</b>なので、足しても総件数にはなりません。各カード／下のボタンを押すと、その種類だけに絞り込めます（もう一度押すと解除）。</p>\n<div class=\"toolbar\"><div class=\"chips\" id=\"kind-chips\"><button class=\"chip\" data-mode=\"all\" aria-pressed=\"true\">すべて</button><button class=\"chip k-bug\" data-mode=\"bug\" aria-pressed=\"false\"><span class=\"dot\"></span>バグ修正</button><button class=\"chip k-feat\" data-mode=\"feat\" aria-pressed=\"false\"><span class=\"dot\"></span>機能追加</button><button class=\"chip k-imp\" data-mode=\"imp\" aria-pressed=\"false\"><span class=\"dot\"></span>改善</button><button class=\"chip k-crit\" data-mode=\"crit\" aria-pressed=\"false\"><span class=\"dot\"></span>重大のみ</button></div>\n    <div class=\"search\"><input id=\"q\" type=\"search\" placeholder=\"キーワードで絞り込み（例: 連絡帳 / 同期 / 計画書）\" aria-label=\"キーワード検索\"></div></div>\n  <div class=\"chips\" id=\"area-chips\" style=\"margin-bottom:16px\"><button class=\"chip\" data-area=\"all\" aria-pressed=\"true\">全領域</button><button class=\"chip\" data-area=\"利用者マスタ\" aria-pressed=\"false\">利用者マスタ <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">52</span></button><button class=\"chip\" data-area=\"日誌\" aria-pressed=\"false\">日誌 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">24</span></button><button class=\"chip\" data-area=\"変更ログ\" aria-pressed=\"false\">変更ログ <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">2</span></button><button class=\"chip\" data-area=\"連絡帳\" aria-pressed=\"false\">連絡帳 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">46</span></button><button class=\"chip\" data-area=\"同期\" aria-pressed=\"false\">同期 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">30</span></button><button class=\"chip\" data-area=\"連絡\" aria-pressed=\"false\">連絡 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">7</span></button><button class=\"chip\" data-area=\"各種設定\" aria-pressed=\"false\">各種設定 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">18</span></button><button class=\"chip\" data-area=\"提供記録\" aria-pressed=\"false\">提供記録 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">68</span></button><button class=\"chip\" data-area=\"分析/提供記録\" aria-pressed=\"false\">分析/提供記録 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">2</span></button><button class=\"chip\" data-area=\"LIFE加算\" aria-pressed=\"false\">LIFE加算 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">12</span></button><button class=\"chip\" data-area=\"分析\" aria-pressed=\"false\">分析 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">17</span></button><button class=\"chip\" data-area=\"分析個人/LIFE加算\" aria-pressed=\"false\">分析個人/LIFE加算 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">1</span></button><button class=\"chip\" data-area=\"スケジュール/提供記録\" aria-pressed=\"false\">スケジュール/提供記録 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">3</span></button><button class=\"chip\" data-area=\"ケアマネ連携\" aria-pressed=\"false\">ケアマネ連携 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">13</span></button><button class=\"chip\" data-area=\"ホーム\" aria-pressed=\"false\">ホーム <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">8</span></button><button class=\"chip\" data-area=\"家族アプリ\" aria-pressed=\"false\">家族アプリ <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">34</span></button><button class=\"chip\" data-area=\"計画書\" aria-pressed=\"false\">計画書 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">10</span></button><button class=\"chip\" data-area=\"体力測定\" aria-pressed=\"false\">体力測定 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">3</span></button><button class=\"chip\" data-area=\"管理局\" aria-pressed=\"false\">管理局 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">5</span></button><button class=\"chip\" data-area=\"社外資料\" aria-pressed=\"false\">社外資料 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">13</span></button><button class=\"chip\" data-area=\"セキュリティ\" aria-pressed=\"false\">セキュリティ <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">3</span></button><button class=\"chip\" data-area=\"送迎表\" aria-pressed=\"false\">送迎表 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">86</span></button><button class=\"chip\" data-area=\"モニタリング\" aria-pressed=\"false\">モニタリング <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">13</span></button><button class=\"chip\" data-area=\"全体\" aria-pressed=\"false\">全体 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">13</span></button></div>\n  <p class=\"count-line\" id=\"count-line\">表示 677 件 ／ 全 677 件</p>\n  <div class=\"ledger\" id=\"ledger\">\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳 各種入力 項目 連絡事項 次回予定 まとめる 未入力 バナー 印刷ボタン 廃止 空印刷 ダウンロード trial201\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-10-05</span></div>\n      <p class=\"title\">【試験版】連絡帳: 「項目・連絡事項・次回予定」を「各種入力」1つに(次回予定の未入力バナー)・「印刷」ボタン廃止・空印刷はそのままダウンロード</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-05): 連絡帳の上部の項目・連絡事項・次回予定を「各種入力」で一つにまとめて、その中でバナーで予定の何人入力されてないかが分かればいい。ダウンロードも早く済んだので印刷ボタンも不要。空印刷も押したらプレビューじゃなくてダウンロードされるように。</span><span class=\"lb\">対処</span><span class=\"tx\">ツールバー: 各種入力(cb-input-hub・未入力人数バッジ) / 印刷設定 / 空印刷 / ダウンロード。各種入力のパネル: 上に次回予定の未入力バナー(人数・先頭4名・押すと次回予定を開く。全員入力済みなら緑)と連絡事項の状況、下に 次回予定・連絡事項・項目 の入口(既存のモーダルをそのまま開く)。「印刷」ボタン(cb-print)は廃止、対象選択の文言は「選択したn名をダウンロード」。空印刷: window.prompt をやめ、枚数(マイナス/プラス・最大20)を選ぶダイアログから doPrintBlank がサーバーPDFを直接ダウンロード(iPadはクリック時にタブを開く・印刷設定の用紙/面数/位置のまま)。検証: 印刷ボタン0・各入口で既存モーダル・バナー表示・空印刷2枚=PDF2ページ(B5横)・プレビュー0・ダウンロードでも cbPrintedAt の刻印2/2(送迎表の赤丸ルール維持)。vitest 23・Playwright 24。試験版 trial201。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6fcf807</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳 印刷位置 微調整 復活 印刷設定 用紙 図 目視 端 4mm 試し刷り 実際のサイズ renrakuSheetGeom trial201\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-10-05</span></div>\n      <p class=\"title\">【試験版】連絡帳の印刷設定に「印刷位置の微調整」を復活(用紙の図で位置が見える・端に近いと注意・試し刷り1枚ダウンロード)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-05): プレビューで調整(用紙の位置とか)できなくなったので、印刷設定のところで戻して、できれば印刷位置が目視でわかるようにできるとよりいい。</span><span class=\"lb\">対処</span><span class=\"tx\">印刷設定パネルに 上・左・右・下(1mm・最大10mm)と「戻す」、現在値(「左へ3mm・上へ2mm」)、RenrakuPositionDiagram(SVG・mm座標: 用紙・端4mmを赤・カット線・穴あけ目印・連絡帳の枠と中の欄の目安・調整前の位置を点線)を追加。端4mmにかかると赤枠と注意文。「試し刷り用(空の連絡帳1枚)をダウンロード」。保存値は従来の systemSettings.renrakuOffsetX/Y(店舗共通・ダウンロードPDFにもそのまま反映)。配置計算は module-level の renrakuSheetGeom(_layoutRenraku と同じ数値・変えるときは両方)。案内: PDFは「実際のサイズ(100%)」で印刷。パネルは画面の高さに合わせてスクロール。検証: 左3・上2で保存[-3,-2]・試し刷りのHTMLに translate(-3mm,-2mm)・注意表示・戻すで0。試験版 trial201。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6fcf807</span></span></div>\n    </article>\n    \n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"全体\" data-text=\"PDF ダウンロード できない 403 forbidden origin 独自ドメイン tsumugi.ones-style.co.jp api/pdf ALLOWED_HOSTS T-OPS-07 1005b\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-10-05</span></div>\n      <p class=\"title\">安定版で書類の「ダウンロード」(PDF)ができない: 独自ドメイン tsumugi.ones-style.co.jp からの依頼をPDFサーバーが403で拒否していた</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-05): 安定版でPDFのダウンロードができない。</span><span class=\"lb\">対処</span><span class=\"tx\">原因: 店舗は安定版を独自ドメイン tsumugi.ones-style.co.jp で使っているが、/api/pdf の Origin 許可が *.vercel.app と localhost だけだったため 403 forbidden origin(vercel の URL で行った配信前の確認では再現しなかった)。修正: ALLOWED_HOSTS に tsumugi.ones-style.co.jp、正規表現で ones-style.co.jp 配下を許可(evil-ones-style.co.jp・ones-style.co.jp.evil.com は不可を確認)。再発防止: run_tests.py に T-OPS-07(独自ドメイン/本番vercel/試験版の3 Origin から %PDF が返る)を追加し、テスト項目一覧にも追記。検証: 独自ドメインから 連絡帳B6=1ページ・分析個人=6ページ・クラス在籍表=1ページ(Noto埋め込み)、配信後テスト 20/20。安定版 1005b。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b3b668f</span></span></div>\n    </article>\n    \n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"社外資料\" data-text=\"営業資料 アカウント登録のお願い ケアマネ 居宅介護支援事業所 A4 表裏 メリット 招待コード QR lp-cm-touroku\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">社外資料</span><span class=\"date tnum\">2026-10-05</span></div>\n      <p class=\"title\">営業資料「つむぎ アカウント登録のお願い」(ケアマネジャー・居宅介護支援事業所向け・A4表裏)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-05): ケアマネと事業所用でアカウント登録のお願いとメリットなどを載せたA4表裏で印刷できる営業資料も作って。</span><span class=\"lb\">対処</span><span class=\"tx\">public/lp-cm-touroku.html → docs/マニュアル・public/manual「つむぎアカウント登録のお願い_ケアマネ・居宅事業所向け.pdf」。表=担当ケアマネジャー様へ(お願い文・メリット4つ・登録3ステップ・招待コード記入欄とQR貼付欄・デイサービス名/担当の記入欄)、裏=居宅介護支援事業所 管理者様へ(事業所としてのメリット3つ・導入後に変わること表・安心のしくみ・お願いしたいこと3つ・Q&A・問い合わせ欄)。lp_pdf.mjs の JOBS に追加(はみ出し検査つき・2ページとも収まり確認)。既存の「つむぎのご案内_ケアマネ向け」は機能紹介、本資料は登録依頼が目的。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">277bfb9</span></span></div>\n    </article>\n    \n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"社外資料\" data-text=\"マニュアル 事業所向け ご家族向け ケアマネ向け エリア担当者 説明資料 画像 撮り直し 1005a 送迎表 確定 クラス在籍表 ダウンロード 血圧再検 フェイスシート 一括確定\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">社外資料</span><span class=\"date tnum\">2026-10-05</span></div>\n      <p class=\"title\">マニュアル3種・エリア担当者説明資料を安定版1005aに合わせて更新(画像79枚を撮り直し・送迎表の確定/クラス在籍表/ダウンロード/血圧再検/フェイスシート/モニタリング一括確定/家族のフェイスシート編集)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-05): 次の作業に移って(安定版昇格後のマニュアル画像更新)。</span><span class=\"lb\">対処</span><span class=\"tx\">manual_shots.mjs に クラス在籍表・血圧の再検(テンキーで1回目→再→2回目の行)・フェイスシート(①から)・モニタリング全員選択・送迎表の確定済み一覧(今週の配車を投入して確定・確認ダイアログ自動OK)・家族/CMのモニタリングタブ を追加し、全79枚を撮り直し(sips 1366/780)。事業所向け: 7章 再検と備考/特記の文字数・8章 印刷/ダウンロードと連絡事項の使用量・10章 送迎表を全面改稿(確定/解除/一覧/赤丸/ダウンロード)・11章 BMI・12章 ダウンロードとマスク/送付履歴の扱い・14章 クラス在籍表・15章 一括確定/自動確定/ケアマネ宛ダウンロード・16章 フェイスシートの構成と更新履歴・18章 BMI/ダウンロード・23章「書類のダウンロード」・Q&A。ご家族向け: 7章に代表者のフェイスシート編集。ケアマネ向け: 8章 フェイスシート構成/更新履歴・10章 モニタリングを画面で閲覧(当月前月/月選択)。エリア担当者資料: 安定版=試験版の状態・日付一覧 10/5・機能一覧・一次回答集(ダウンロード/送付履歴)・学習チェック。PDF4本を docs/マニュアル と public/manual に再生成。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">122ed36</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"社外資料\" data-text=\"計画書 第6版 ガントチャート 達成済み グレー 現在線 送迎表 前倒し 10/5 技術直結ライン 撤回 第3陣 個別\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">社外資料</span><span class=\"date tnum\">2026-10-05</span></div>\n      <p class=\"title\">計画書 第6版(10/5 改訂): ガントチャートに達成済み(グレー)と現在線、送迎表の前倒し配信、9/24決定事項(店舗→本部直接・第3陣は個別)を反映</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-05): ガントチャートも更新して。</span><span class=\"lb\">対処</span><span class=\"tx\">第5版の本文を基に第6版を作成(Artifact https://claude.ai/artifact/VCMUjVS39MySt2sjvWSve1・PDF docs/計画/つむぎ計画書_第6版.pdf 6ページ)。ガント: 9月の4項目・V1.0・LIFE調査/実装・送迎表実装(計画10/1〜10/24)を達成=グレー、実績行「試験版で扇橋・江古田が先行試用(9/12〜10/4)」「送迎表 安定版へ前倒し配信(10/5)」「PDFダウンロード・クラス在籍表(計画外)」を追加、現在(10/5)の赤点線、進行中ラベル。第6版改訂欄・店舗展開の状況列・主要マイルストーンの達成印・リスク表を更新。生成は scratchpad/plan6/gen.py(日付→%換算)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">122ed36</span></span></div>\n    </article>\n    \n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳 次回お迎え時間 文字 大きく 36px 24px B6 QR 頃 1005a\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-10-05</span></div>\n      <p class=\"title\">連絡帳: 次回お迎え時間の文字を少し大きく(数字36px・単位24px)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-05): (B6ダウンロードの画像)もうちょいデカくてもいいかも。</span><span class=\"lb\">対処</span><span class=\"tx\">trial199 で 38→33 に縮めた数字を 36(単位 22→24)に。B6 のローカル PDF で「10月6日（火） 09時00分頃」が QR の手前(約 740/800px)に収まることを確認。試験版 trial200 → 同日 安定版 1005a。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">eb487dd</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡\" data-text=\"送付履歴 ダウンロード DL済 FAX のみ モニタリング faxHistory method pdf tsumugiFaxLog 1005a\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">連絡</span><span class=\"date tnum\">2026-10-05</span></div>\n      <p class=\"title\">ダウンロードしただけでは送付履歴に入れない(送付履歴に残るのは FAX 自動送信だけ)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-05): ダウンロードしただけで「送付履歴に保存した」って出るので、FAXしない限りは送付履歴に入れなくていい。</span><span class=\"lb\">対処</span><span class=\"tx\">(1) trial198 で入れた _recordPdfOutput の faxHistory 自動追加(「ダウンロード（DL済）」method:pdf)を廃止。(2) モニタリングの担当ケアマネ宛てダウンロード(一括 faxToCareManagers・1名 faxRowToCareManager)の faxHistory 追加と「送付履歴に記録しました」の文言を廃止(確認文も「1つのPDFにしてダウンロード」に)。FAX 自動送信(autoFax)の記録は従来通り。(3) 既に入った method:pdf の記録は tsumugiFaxLog(appData) で一覧・個人ファイル連絡タブ・ZIP出力から除外(データは残す)。休み連絡・各種連絡の送付状のダウンロード時の自動記録(連絡済/ダウンロード済)は FAX 送付状そのものなので据え置き。試験版 trial200 → 安定版 1005a。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">eb487dd</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"安定版 昇格 1005a trial167 trial200 ダウンロード統一 サーバーPDF クラス在籍表 送迎表 確定 提供記録 血圧再検 BMI モニタリング フェイスシート\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-10-05</span></div>\n      <p class=\"title\">試験版 trial167〜200 を安定版へ(1005a): 書類のダウンロード統一(サーバーPDF)・クラス在籍表・送迎表の確定/一覧/赤丸・連絡帳の収まり・提供記録レイアウト・血圧再検・BMI・モニタリング一括/自動確定・フェイスシート整理と更新履歴ほか</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-05): 安定版に入れて。</span><span class=\"lb\">対処</span><span class=\"tx\">試験版の src/App.jsx・index.css・lib/supabase.js・api/pdf.js(サーバーPDF)・public/fonts(Noto Sans JP)・package.json(@sparticuz/chromium 153・puppeteer-core 25・Node 22)・vercel.json(pdf 関数 60秒/1GB)を安定版へ。この時点で試験版と安定版のコードは同一(差分は update-notes.json のみ)。安定版のお知らせは 70件の試験版お知らせを 12件に要約(upd-2026-1005a)。検証: build・eslint no-undef 0・vitest 23・Playwright 24・配信後テスト。マニュアル3種とエリア担当者PDFの画像更新は別途。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">eb487dd</span></span></div>\n    </article>\n    \n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳 ダウンロード PDF 1面 B6 B5 次回お迎え時間 事業所名 切れる 改ページ align-items center transform scale trial199\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-10-04</span></div>\n      <p class=\"title\">連絡帳のダウンロード(1面・B6/B5)で下の「次回お迎え時間」「事業所名」が切れる</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-04): 連絡帳をダウンロードしたら次回のお迎え時間のところが見切れている(画像)。</span><span class=\"lb\">対処</span><span class=\"tx\">1面レイアウトが「182mm の用紙に 257mm の中身を align-items:center で置いてから transform:scale」だったため、サーバーの Chrome は配置上はみ出した中身を次ページへ分割し、1ページ目が途中で切れていた(ローカル再現: B6 で2ページ・下が欠ける)。2面と同じく「縮小後の実寸の箱(overflow:hidden)に左上基準で縮めて余白で中央寄せ」に変更し、用紙は 0.5mm 短く(末尾の空白ページ防止)。併せて /api/pdf の body>*{overflow:visible} 注入は 1面の箱の overflow:hidden を壊していたので撤去(html,body のみ)。検証: B6 1面=1ページで QR・事業所名まで表示、分析個人=6ページ維持。試験版 trial199。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8b3e446</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳 次回お迎え時間 頃 見切れ 項目 値 縮小 12文字 連絡事項 使用量 92% 保存不可 trial199\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-10-04</span></div>\n      <p class=\"title\">【試験版】連絡帳: 次回お迎え時間が「頃」まで収まる・項目の値は縮小(12文字まで)・連絡事項は欄に収まらないと保存できない</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-04): 文字の多さや形で「分頃」が見切れる。連絡事項に文字数制限を(太さでも変わる)。項目に文字を打つと見切れる→縮小+文字数制限。</span><span class=\"lb\">対処</span><span class=\"tx\">次回お迎え時間: 数字 38→33px・単位 26→22px・間隔 0.6→0.45em。項目の値: _valFs(値の文字数が4超なら縮小・最小7px)、利用者ごとの値の入力は maxLength 12 + CharCount。連絡事項の編集: 実測(RENRAKU_BOX_H)の比率を「欄の使用量 n%」で表示し、92%超は警告+保存ボタン無効(サーバーPDFの Noto Sans JP の字幅の余裕)。試験版 trial199。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8b3e446</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"クラス在籍表 休止中 グレー 斜体 凡例 共通スクロール 午前 午後 連動 trial199\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-10-04</span></div>\n      <p class=\"title\">【試験版】クラス在籍表: 休止中はグレーの斜体+凡例(行の高さは変えない)・午前と午後の横スクロールを連動</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-04): 休止の人の行が高くなっている。色を薄くして凡例で「グレーは休止」に。午前と午後が別々のスクロールなので同じスクロールで連動させて。</span><span class=\"lb\">対処</span><span class=\"tx\">名前の上の「休止中」ラベルを撤去し、休止者は #9ca3af の斜体のみ。ツールバーと印刷見出しに凡例。AM/PM の2表を1つの overflow-x:auto(cr-scroll)に入れて横スクロールを連動。検証: 行高 21px(変化なし)・凡例・同じ容器に2表。試験版 trial199。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8b3e446</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"家族 ケアマネ 利用者基本情報 編集 フェイスシート 一本化 二度手間 ホーム お知らせ モニタリング グループ化 trial199\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-10-04</span></div>\n      <p class=\"title\">【試験版】ご家族・ケアマネ画面の利用者基本情報は表示のみ・編集はフェイスシートに一本化／ホームの「お知らせ」もモニタリング配信を月ごとに1行に</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-04): 管理側で「フェイスシートを開いて編集」が見えない。押さなかった場合に今まで通り入力できると二度手間になるので、基本情報のところにフェイスシート情報を入れる形でもいい。ホームのお知らせもグループ化して。</span><span class=\"lb\">対処</span><span class=\"tx\">利用者基本情報タブ: 旧の編集フォームは表示のみ(保存ボタン廃止)、上部に「利用者情報を編集する（フェイスシート）」(プレビューでも表示)。ヘッダーの「フェイスシート」も代表者に表示。ホーム(DashboardView)の news は monann_ を月ごとに集約(「モニタリング（2026年9月）を n名のケアマネへ配信」・詳細本文に配信先一覧)。※管理側の家族・ケアマネ画面プレビューは記録の確認用で家族のヘッダーは出ないため、編集画面はログイン後の画面で確認。試験版 trial199。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8b3e446</span></span></div>\n    </article>\n    \n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"家族 フェイスシート 編集 かかりつけ医 更新履歴 家族画面 ケアマネ画面 supabaseMergeFaceSheetFromCM changes trial198\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-10-04</span></div>\n      <p class=\"title\">【試験版】ご家族(代表者)もフェイスシートで利用者情報を編集できるように(かかりつけ医の追加等)・ご家族/ケアマネ画面にも更新履歴</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-04): 家族とケアマネの画面の利用者情報のところをフェイスシートの内容をそのまま入力できるようにして、かかりつけ医も追加できるように。家族・ケアマネにも変更履歴が載るように。双方向に反映されるのは間違いない？</span><span class=\"lb\">対処</span><span class=\"tx\">家族アプリの cmFaceSheetOpen(FaceSheetForm)を代表者(canEditMyInfo)にも開放: ヘッダーの「フェイスシート」ボタンと、利用者・登録者情報→利用者基本情報の「フェイスシートを開いて編集」。保存は _kind(family/caremanager)で docUpdates(items+changes)を記録し、supabaseMergeFaceSheetFromCM(meta.source/items/changes)が雲側の docUpdates にも同じ changes を載せる(従来は雲側が items:[フェイスシート] だけを作り直していた)。利用者基本情報タブに「更新履歴(折りたたみ・20件)」を表示。双方向: ケアマネ/家族→事業所は雲側マージ、事業所→家族/ケアマネは app_state の patients.personalFile.faceSheet を読むため反映される(同時編集は後勝ち)。試験版 trial198。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f553ed6</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"フェイスシート 更新履歴 折りたたみ 年 月 200件 docUpdates 保持 trial198\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-10-04</span></div>\n      <p class=\"title\">【試験版】フェイスシートの更新履歴は折りたたみ・年→月でまとめ・200件まで保持</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-04): 最新30件で全て残す必要はない？折りたたみにして月ごと/年単位で分けてほしい。</span><span class=\"lb\">対処</span><span class=\"tx\">docUpdates の保持を 50→200件(画面側 appendDocUpdate・雲側 merge とも)。FaceSheetForm の履歴は <details>(既定で閉じる・見出しに最新の日時と更新者)→年(今年は開く)→月(今月は開く)→件の3段。試験版 trial198。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f553ed6</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"クラス在籍表 休止中 名前の上 行の高さ trial198\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-10-04</span></div>\n      <p class=\"title\">【試験版】クラス在籍表: 「休止中」は名前の上に小さく(行の高さはそのまま)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-04): 休止って名前の右じゃなくて名前の上に表示できる？セルの行の高さはそのままで。</span><span class=\"lb\">対処</span><span class=\"tx\">名前セルを position:relative にし、7px(印刷6px)の「休止中」を左上に絶対配置、名前は上に5〜6px の余白を取って表示。行の高さ 24px は変えない。試験版 trial198。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f553ed6</span></span></div>\n    </article>\n    \n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"更新履歴 docUpdates changes 変更前 変更後 更新者 日時 フェイスシート お知らせ 詳細 家族 ケアマネ 編集 trial197\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-10-04</span></div>\n      <p class=\"title\">【試験版】ご家族・ケアマネの編集に「更新履歴」(日時・更新者・項目ごとの変更前→変更後)を残し、お知らせの詳細とフェイスシートに表示</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-04): 10/4 11:31 に利用者の娘様が利用者情報を更新した。お知らせにも、フェイスシートにも更新履歴(日付・時間・更新者・どこをどう変更したか)を残してほしい。</span><span class=\"lb\">対処</span><span class=\"tx\">appendDocUpdate(patient, by, byName, items, changes) に changes=[{label,before,after}](各200字・40件まで)を追加。家族の利用者情報の編集は _changedKeys から before/after を作成、ケアマネのフェイスシート編集は diffFaceSheetChanges(prev,next)(配列/オブジェクトは件数・内容ありで表現)。ホームの「家族・ケアマネからの更新」の詳細に「【変更の内容】お名前: 旧 → 新」(docUpdateChangesText)。FaceSheetForm の添付の上に「更新履歴(最新30件)」(日時・ケアマネ/ご家族/事業所(氏名)・内容・変更表)。検証(Playwright): 家族編集の履歴→ホーム詳細に変更内容、フェイスシートに表が出る。試験版 trial197。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4881fae</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"お知らせ 閲覧管理 過去履歴 モニタリング monann グループ 月ごと 一覧 trial197\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-10-04</span></div>\n      <p class=\"title\">【試験版】お知らせ・閲覧管理の過去履歴: モニタリングの自動お知らせは月ごとに1行にまとめ、押すと配信先の一覧</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-04): モニタリングで一人一人「個人ファイルに適用しました」が並んでお知らせ画面が埋まる。月ごとにグループ化して、押せば何月分を誰の個人のお知らせに反映したか一覧が出るように。</span><span class=\"lb\">対処</span><span class=\"tx\">FamilyAdminView: id が monann_ のお知らせを period(タイトルの「モニタリング（…）」)で集約し「モニタリング（2026年9月）を n名の個人のお知らせに反映」の1行(人数バッジ)に。詳細は配信日・利用者・作成/更新の表。家族・ケアマネ画面側の個人お知らせはこれまでどおり1人ずつ届く。試験版 trial197。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4881fae</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"クラス在籍表 2列 列幅 揃え 休止 印 見切れ 組 区切り 横スクロール 印刷 介護度 幅 trial197\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-10-04</span></div>\n      <p class=\"title\">【試験版】クラス在籍表(2列): 左右の介護度の幅を揃え、「（休止）」は小さな印に、氏名+介護度の組を線で区切り、狭い画面は横スクロール</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-04): 左側と右側で介護度のセル幅が違う。休止が見切れている。左右で氏名と介護度がセットになっている感を出した方がいい。</span><span class=\"lb\">対処</span><span class=\"tx\">介護度の列幅を左右とも同じ(画面48px・印刷は2列時32px)、見出しは折り返さない。休止は名前の横の小バッジ(名前側を省略)。組の内側は薄い線、組と組の間は中線、曜日の境目は太線。2列時は table に minWidth(曜日数×2×150px)を与え、外側を overflow-x:auto(iPadの縦など狭い画面は横スクロール)。検証: 幅 [16,86,48,16,86,48]、休止バッジ、印刷A4横1枚。試験版 trial197。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4881fae</span></span></div>\n    </article>\n    \n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析\" data-text=\"ダウンロード PDF 1ページ 前半 overflow hidden 分析個人 複数ページ 名前付き @page 縦横混在 trial196\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-10-04</span></div>\n      <p class=\"title\">ダウンロードのPDFが1ページ目しか入らない(分析個人など複数ページの書類)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-04): 分析個人でダウンロードした時に最初の前半の記録しかダウンロードされていない気がする。</span><span class=\"lb\">対処</span><span class=\"tx\">原因: 送るHTMLにアプリ全体のCSS(html,body の overflow:hidden/height 固定)が含まれ、印刷メディアでも2ページ目以降が切り捨てられていた(ローカル再現: 6ページ分のHTML→PDF 1ページ。head のスタイルを外すと6ページ)。対処: /api/pdf が本文末尾に html,body{height:auto;max-height:none;overflow:visible}!important と body>* の overflow:visible を注入。併せて、既定サイズの @page を最後に注入すると名前付き @page(p/l)が負けて横ページが縦になったため、HTML内の名前付き @page を抽出して再掲。検証: 分析個人(1年・詳細含む)→6ページ・縦5+横1、連絡帳 B5横も維持。試験版 trial196。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">003035b</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"ダウンロード 名称統一 送迎表 日誌 休み連絡 各種連絡 モニタリング 統合 ダウンロード済 MaskToggle 氏名マスキング 配置 trial196\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-10-04</span></div>\n      <p class=\"title\">【試験版】「ダウンロード」への名称統一の残り(送迎表・日誌・休み連絡・各種連絡・分析・モニタリング統合)・休み連絡は「ダウンロード済」・氏名マスキングは必要な画面のボタン横</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-04): 送迎表も印刷になっている。プレビューがいろんな所に残っている。ヘッダーのマスキングは分からないので無し。マスキングが要るのは休み連絡・各種連絡・計画書と送付状・利用者実績・モニタリング・分析個人・フェイスシート。休み連絡でダウンロードしても連絡済になる。モニタリングの印刷/PDFをダウンロードに、プレビューは統合。全員選択で1人分しか出ない。</span><span class=\"lb\">対処</span><span class=\"tx\">ラベル: 送迎表「印刷」、日誌(AM/PM・両方)、休み連絡、各種連絡、分析個人、稼働分析の「プレビュー(表示)」→「ダウンロード」。モニタリングは previewSheets ボタンを撤去し faxToCareManagers を「ダウンロード」に(選択全員分を1PDF・検証3名→3ページ)。「先に枠だけ開いて後から setPrintHtml」の1回目(html も elementId も無い)はルーターで無視(エラー表示を出さない)。休み連絡: tsumugi:printed の method が pdf なら status 'pdf'=「ダウンロード済」(印刷は「連絡済」)。MaskToggle(画面ごとの state、ON の間だけ _tsumugiMaskOn)を 休み連絡/各種連絡/計画書3-3・通所(送付セット含む)/利用者実績/モニタリング/分析個人/個人ファイルのフェイスシート に設置。ヘッダーとプレビューのマスキングは撤去。試験版 trial196。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">003035b</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"クラス在籍表 2列 定員 15 左右 境目 太線 人数 見出し trial196\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-10-04</span></div>\n      <p class=\"title\">【試験版】クラス在籍表: 定員11名以上は各曜日を左右2列・曜日の境目は太線・見出しに人数</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-04): 15人定員だとPDFで下が詰まる。名前の右に余白があるので2列(8+8)に。曜日の境目が分かるように、人数もパッと見で分かるように。</span><span class=\"lb\">対処</span><span class=\"tx\">renderBlock: rows>11 なら per=ceil(rows/2) 行×2列(左=1〜per、右=per+1〜)。曜日見出しは colSpan 6(画面)/4(印刷)で「月曜日 10／15名」(超過は赤字)、各曜日の左端は 2px の太線、待ち・空きは曜日幅いっぱい。印刷は9pt。並べ替えは左右どちらの「⋮」でも可。検証: 定員15で 12行(見出し2+8+待ち+空き)・A4横1ページ。試験版 trial196。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">003035b</span></span></div>\n    </article>\n    \n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"ダウンロード 名称統一 プレビュー 廃止 直接PDF setPrintPreviewContent ルーター pdfJob iPad 新しいタブで開く 氏名マスキング ヘッダー trial195\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-10-04</span></div>\n      <p class=\"title\">【試験版】書類の出力ボタンを「ダウンロード」に統一・連絡帳以外はプレビューを出さず直接PDF・氏名マスキングはヘッダーの共通スイッチ</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-04): 名前がPDFやPDFをダウンロードなど様々なので1つに統一(プレビューじゃなくてダウンロード)。マスキングはプレビューの外に。</span><span class=\"lb\">対処</span><span class=\"tx\">App の setPrintPreviewContent をルーターに(生の setter は _setPrintPreviewContentRaw): title が「連絡帳」/autoPrint/adjust/forcePreview のときだけプレビューを表示、それ以外は directPdf(detail) で即サーバーPDF(elementId しか無い呼び出しは outerHTML を取得・マスキングは _maskRef(ヘッダーの printMaskNames)・連絡帳/日誌には効かせない)。進行は pdfJob オーバーレイ(作成中→PCは自動ダウンロード、iPad は「新しいタブで開く」ボタン=ユーザー操作で window.open・失敗時はエラー表示)。送付履歴の自動記録と tsumugi:printed は _recordPdfOutput に集約。ラベル統一: 在籍表/実績表/提供記録/計画書3-3・3-2・3-1・通所/稼働分析/個人ファイル(フェイスシート・月別・会議)/分析個人(ダウンロードの設定)/連絡帳の PDF → すべて「ダウンロード」。フェイスシートの html2canvas ダウンロードは廃止し同じ経路に。マスキングはヘッダー(変更ログの左・md以上)の共通スイッチで、開き直しても戻さない。検証(Playwright・/api/pdf モック): 在籍表=プレビュー無しで直接ダウンロード、マスキングON→提供記録のHTMLに○、連絡帳=プレビュー維持、フェイスシート=直接ダウンロード。試験版 trial195。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">06bc648</span></span></div>\n    </article>\n    \n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"PDF ダウンロード 連絡帳 A4縦 用紙サイズ @page preferCSSPageSize B5 B6 trial194\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-10-04</span></div>\n      <p class=\"title\">PDFをダウンロード: 連絡帳がA4縦で作られる(アプリ全体の @page{size:A4} が勝っていた)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-04): いやめちゃくちゃA4縦になってる(連絡帳のPDFの画像)。</span><span class=\"lb\">対処</span><span class=\"tx\">/api/pdf は preferCSSPageSize のため、送られたHTMLに含まれるアプリ全体のCSS @page{size:A4 portrait} が画面から渡した pageSize(257mm 182mm 等)より優先されていた。対処: 本文の最後に <style>@page{size:<pageSize>;margin:0}</style> を注入(後勝ち)。検証: ローカルで本文の @page が A4 のまま 257mm 182mm を要求→ MediaBox 729×516pt(B5横)。試験版 trial194。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8e7e393</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"印刷プレビュー 整理 連絡帳 ブラウザ印刷 氏名マスキング 範囲 送付履歴 自動記録 DL済 ウォームアップ warm trial194\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-10-04</span></div>\n      <p class=\"title\">【試験版】印刷プレビューの整理: ブラウザ印刷は連絡帳だけ・マスキングはケアマネ/家族向け書類だけ・PDF作成で送付履歴に自動記録・サーバーの先行起動</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-04): FAX送付履歴はダウンロードしたらDL済に。マスキングは連絡帳・日誌には不要(ケアマネ・家族宛の書類に)。微調整は連絡帳のみ。すぐ見たいのは連絡帳くらい。サーバーPDFをもっと早く見る方法は？ 連絡帳のみブラウザ印刷を残す。</span><span class=\"lb\">対処</span><span class=\"tx\">プレビューの _t(タイトル)から isRenrakuDoc/isNikkiDoc を判定: 「印刷・FAX・PDF」とⓘは連絡帳だけ、氏名マスキングは連絡帳・日誌以外、微調整は従来どおり adjust のある連絡帳だけ。PDF成功時、休み連絡/各種連絡/サービス提供記録は faxHistory に {method:\"pdf\", note:\"PDFをダウンロード（DL済）\"} を自動追加し tsumugi:printed も発火。速さ: /api/pdf に GET ?warm=1(Chrome起動+フォント取得だけ)を追加し、プレビューを開いた時とアプリ起動15秒後に呼ぶ(同じ実行環境が温まっていれば1〜2秒)。※Vercel Hobby の cron は1日1回までなので定期ウォームは画面側から。検証(Playwright・/api/pdf をモック): 在籍表=印刷ボタン無し/マスキング有/warm 1回/pageSize A4 landscape、連絡帳=印刷有/マスキング無/微調整有、休み連絡=PDF→faxHistory に自動記録。試験版 trial194。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8e7e393</span></span></div>\n    </article>\n    \n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"PDF ダウンロード iPad 新しいタブ window.open blob ボタン 並び 用紙サイズ B5 B6 tsumugiServerPdf trial193\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-10-03</span></div>\n      <p class=\"title\">【試験版】PDFをダウンロード: iPad/iPhoneは新しいタブで表示・プレビューのボタン並びを修正・用紙は印刷設定どおり</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-03): iPadでPDFにするとアプリの画面内でPDFになる。新しいタブを作ってそっちでPDFにできる？ ボタンがおかしい。連絡帳のPDFはB5/B6の設定に合わせられる？</span><span class=\"lb\">対処</span><span class=\"tx\">共通ヘルパー tsumugiBuildPrintSrcDoc/tsumugiServerPdf/tsumugiOpenPdfWindow。iPad は fetch 後の window.open が開けない(ユーザー操作の外)ため、クリック時に「PDFを作成中…」の空タブを先に開き、できた Blob の URL をそのタブに読み込む。PC は a[download]。失敗時はタブを閉じて表示。プレビューのボタンは [PDFをダウンロード][印刷・FAX・PDF|ⓘ] の並びに(ⓘとの連結を壊さない)。用紙は /api/pdf が pageSize(\"257mm 182mm\" 等・B5/B6 は JIS 寸法)と @page を優先するので印刷設定どおり。試験版 trial193。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b0439c4</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳 印刷 直行 autoPrint プレビュー省略 PDF ボタン 血圧 すぐ渡す trial193\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-10-03</span></div>\n      <p class=\"title\">【試験版】連絡帳: 「印刷」はプレビューを経由せず印刷へ(autoPrint)・「PDF」ボタン(サーバーPDF・iPadは新しいタブ)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-03): 連絡帳は血圧を測ってすぐ渡すこともあるのでタイムロスを作りたくない。ダウンロードと印刷で、まっすぐ印刷画面に行くように。</span><span class=\"lb\">対処</span><span class=\"tx\">ContactBookView: cbOut(print/pdf)。「印刷」→対象選択→ setPrintHtml に autoPrint:true → App 側の useEffect(_autoPrintRef)が 400ms 後に openPrintWindow(PC=隠しiframeで印刷ダイアログ、iPad Safari=印刷タブ、ホーム画面アプリ=印刷用の表示)を呼ぶ(プレビューは背面に残り、ブロック時はボタンで続行できる)。「PDF」→ doPrint が最初のクリックで tsumugiOpenPdfWindow を開き、隠しカード描画の再入(setTimeout)にも引き継いで tsumugiServerPdf(pageSize=印刷設定の \"257mm 182mm\" 等)。モーダルのボタン文言は「…をPDFに」。cbPrintedAt の記録は従来どおり。検証(Playwright): 印刷→プレビュー+隠し印刷iframe、PDFモードの文言、cbPrintedAt 2件。試験版 trial193。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b0439c4</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"分析\" data-text=\"ケアマネ 家族 モニタリング 当月 前月 月選択 前の月を見る 廃止 trial193\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-10-03</span></div>\n      <p class=\"title\">【試験版】家族・ケアマネ画面のモニタリング: 既定は当月・前月の2件、それ以前は「表示する月」で1件だけ</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-03): 前の月を見るで全部表示されるより、何月分かを選択する方がいい。数か月前は期間を絞って。当月と前月分だけ表示でいい。</span><span class=\"lb\">対処</span><span class=\"tx\">monShowOld → monPick(recent|period)。既定 recent=最新2件、select で月を選ぶと1件。試験版 trial193。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b0439c4</span></span></div>\n    </article>\n    \n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"全体\" data-text=\"PDF ダウンロード サーバー 生成 api/pdf chromium puppeteer Noto Sans JP 印刷プレビュー 文字PDF ヘッダー フッター trial192\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-10-03</span></div>\n      <p class=\"title\">【試験版】すべての印刷プレビューに「PDFをダウンロード」(サーバー側で作る文字のPDF)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-03): 他社SaaSはPDFダウンロードが主流。今なら着手してよい。PDFでダウンロードしてiPadで印刷すればヘッダー/フッターも無くなるよね？→はい。</span><span class=\"lb\">対処</span><span class=\"tx\">Vercel 関数 /api/pdf(POST {html,pageSize,title}): @sparticuz/chromium 153 + puppeteer-core 25(Node 22.x・maxDuration 60・memory 1024)。印刷メディアで描画し preferCSSPageSize(@page を優先)・余白0・背景印刷。日本語フォントは public/fonts の Noto Sans JP(Regular/Bold)を chromium.font(URL) で登録+@font-face 注入(関数に同梱すると Vercel でパスが見つからず文字化け・AL2023 では chromium 131 は libnss3 不足で起動不可→153に)。同一オリジン(vercel.app)のみ・本文3MBまで・保存しない。画面は印刷プレビューの「PDFをダウンロード」(pv-pdf-download): previewSrcDoc をそのまま送り Blob を a[download] で保存。失敗はボタンに表示。初回は数秒(コールドスタート)。検証: ローカル(Chrome)で A4横の日本語PDF、本番で Noto 埋め込みを確認。試験版 trial192。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4cb9ef5</span></span></div>\n    </article>\n    \n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"フェイスシート PDF ダウンロード 印刷 両方 SaaS trial191\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-10-03</span></div>\n      <p class=\"title\">【試験版】フェイスシートのPDFは「PDFをダウンロード」と「印刷 / PDF」の両方(他社SaaSはダウンロード形式のため)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-03): けど他のSaaS系はダウンロード形式じゃない？</span><span class=\"lb\">対処</span><span class=\"tx\">trial190 で廃止したダウンロード(html2canvas+jsPDF)を「PDFをダウンロード」として戻し、印刷プレビューと併置。他社のPDF出力はサーバー生成の文字PDFだが、つむぎはブラウザ内生成のため画像PDF(文字検索不可)。文字PDFにするなら日本語フォントを埋め込む jsPDF か印刷→PDF保存。試験版 trial191。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">784cd29</span></span></div>\n    </article>\n    \n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"フェイスシート 簡素化 見学日 見学方法 見学対応者 初回作成日 更新日 被保険者番号 備考 追記 印刷 PDF 統一 trial190\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-10-03</span></div>\n      <p class=\"title\">【試験版】フェイスシートの簡素化(見学日・初回作成日/更新日・項目の整理・備考/追記)と印刷/PDFの統一</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-03): 入力受付日→見学日・見学方法・見学対応者・作成者。作成日は初回作成日(固定)と更新日。家族連絡先情報/ジェノグラム/キーパーソン(緊急連絡先の1番目)/区分支給限度額/その他制度/服薬(お薬手帳)/アレルギー感染症(既往歴へ)/ADL・認知症自立度/現在の状況/他サービス(備考へ)/意向/その他(実務上あると便利)は不要。被保険者番号は基本情報へ、留意点は既往歴の下。一番下に追記。PDFがここだけダウンロードなのは統一した方がいい？</span><span class=\"lb\">対処</span><span class=\"tx\">FaceSheetForm: ①見学・作成情報(見学方法は来所/訪問/電話/オンライン/その他、既存値は保持)・初回作成日 firstCreatedDate(初回のみ設定・読み取り)・更新日 updatedDate(保存時に today)。②に被保険者番号+介護保険の表示。③連絡先(緊急連絡先・関係者)のみ。④医療・健康=主治医/医療機関/連絡先(複数可)+既往歴(300)+留意点(200)。⑤ケアマネ関連=担当ケアマネ+通所の経緯(400)。⑥備考(200・旧 他サービスを引き継ぐ)/追記(500)。⑦廃止(保存値は残す・添付は維持)。PDFプレビューも同じ構成に。「ダウンロード」(html2canvas画像PDF)をやめ、他の書類と同じ印刷プレビュー(印刷/PDF保存・余白12mm 14mm)に統一。注意: 計画書の自動読込が参照していた趣味/性格/送迎時の留意点/現在の状況/意向は入力欄が無くなった(保存済みの値は引き続き読む)。検証(Playwright): 見出し①〜⑥・文字数表示・PDF→印刷プレビュー。試験版 trial190。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9f0c626</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"文字数制限 文字数表示 CharCount maxLength 提供記録 特記 備考 モニタリング 計画書 KKField 在籍表 待ち フェイスシート 印刷 見切れ trial190\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-10-03</span></div>\n      <p class=\"title\">【試験版】印刷で見切れる恐れのある入力欄に文字数制限と「現在 / 最大」の表示(印刷時は非表示)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-03): 文字を打つ箇所全てに、印刷で見切れる恐れがあるものは文字数制限をして、入力中は 現在の文字数/最大文字数 を表示。印刷時は非表示。</span><span class=\"lb\">対処</span><span class=\"tx\">共通部品 CharCount({value,max})(no-print・上限で赤・90%で橙)と定数 MON_TEXT_MAX=200/TOKKI_MAX=100/ROSTER_WAIT_MAX=40。適用: 提供記録 特記(一覧・拡大)・備考(70・既存)、モニタリング(モーダルの各項目・一覧の直接編集 200)、計画書 KKField(max 省略時 1行60字・複数行=行数×60字、通所3-4/機能訓練3-3の42か所)、クラス在籍表の待ち(40)、フェイスシート(既往歴300/留意点200/経緯400/備考200/追記500)。ガードレール: 新しい自由入力欄は maxLength+CharCount を必ず付ける。試験版 trial190。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9f0c626</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"クラス在籍表 待ち 日本語入力 1文字 確定 コンポーネント 再生成 remount trial190\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-10-03</span></div>\n      <p class=\"title\">クラス在籍表の「待ち」に日本語を打つと1文字で確定してしまう</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-03): 待ちの箇所で文字を打とうとすると1文字で確定されてしまう。</span><span class=\"lb\">対処</span><span class=\"tx\">原因: 表(Block)を親コンポーネントの中で毎回作る関数コンポーネントとして定義していたため、1文字打つたびに別の型とみなされて textarea が作り直され、変換が切れていた。対処: コンポーネントではなく描画関数 renderBlock(sl,label,print) に変更(React の型が変わらない)。ガードレール: 入力欄を含む部品を親の中で定義しない。試験版 trial190。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9f0c626</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"クラス在籍表 NO列 廃止 つまみ 印刷 用紙いっぱい flex 空白 trial190\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-10-03</span></div>\n      <p class=\"title\">【試験版】クラス在籍表: NO列を廃止(並べ替えは「⋮」)・印刷は用紙いっぱいに広げて下に空白を残さない</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-03): 利用者NOは不要。プレビューで下部に空欄が生まれないように大きさを調整(16名でも空白)。その他の印刷も同様に。</span><span class=\"lb\">対処</span><span class=\"tx\">画面はつまみ列「⋮」(pointer ドラッグ)、印刷はつまみ列なし。印刷は2表を flex:1 1 0 で等分し table height:100%(行の高さ指定なし)で行を均等に伸ばす。文字サイズは行数で 10/9/8px。検証: 定員15で 794/794px ぴったり。試験版 trial190。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9f0c626</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 確定済み 一覧 名前 時間 距離 固定幅 trial190\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-03</span></div>\n      <p class=\"title\">【試験版】送迎表の確定済み一覧: 名前を固定幅(約7文字)にして時間をその直後に</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-03): 名前と時間の距離を近づけてもいい。</span><span class=\"lb\">対処</span><span class=\"tx\">名前 7.2em 固定(はみ出しは省略)→時間→送りタグ。開始位置はどの行も同じ。試験版 trial190。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9f0c626</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"分析\" data-text=\"個人ファイル 体力測定 BMI 列 自動 印刷 trial190\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-10-03</span></div>\n      <p class=\"title\">【試験版】個人ファイルの体力測定の記録に BMI 列(自動計算・印刷にも)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-03): 個人ファイルの体力測定の記録のところにBMIも追加して。</span><span class=\"lb\">対処</span><span class=\"tx\">PersonalFileModal の体力測定一覧: 体重の右に「BMI（自動）」。身長が空の回はそれ以前(新しい順なので後ろの行)の最新の身長で calcBmi。印刷(A4横)も同じ列構成。試験版 trial190。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9f0c626</span></span></div>\n    </article>\n    \n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"クラス在籍表 配色 定員 1か所 ドラッグ 並べ替え pointer 印刷 自動 行高 NO 利用者ID trial189\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-10-03</span></div>\n      <p class=\"title\">【試験版】クラス在籍表: つむぎの配色・定員は上に1か所・同じ枠の中をドラッグで並べ替え(iPad対応)・定員15名でもA4横1枚</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-03): NOは利用者マスタの番号に(=利用者IDで一致)。定員は月曜の左に1つあればよく詰めてよい。同じ曜日内でドラッグ並べ替え。色はつむぎに合わせて。15人定員だと下が見切れる。</span><span class=\"lb\">対処</span><span class=\"tx\">配色を slate/青見出し・支援はピンク文字に統一。定員はツールバーと印刷の見出しに1か所、各枠の下は「空き n（定員超過 m）」のみ。並べ替えは HTML5 drag が iPad・Playwright で動かないため pointer イベント(NOセルをつかむ・touch-action:none・elementFromPoint で落下先)で実装、順番は systemSettings.classRosterOrder[dow_sl](_fieldTs付き)・「並び順を戻す」で削除。印刷は行数から行高(620/(2×(定員+6)))と文字サイズを決め、line-height 1.1 で A4横に収める(定員15: 794/794px)。検証(Playwright): ドラッグで 51→3番目、順番保存、待ち保存、印刷2表が収まる。試験版 trial189。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4bf81ae</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 確定済み 一覧 名前 左 時間 右 固定幅 日付帯 省略 trial189\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-03</span></div>\n      <p class=\"title\">【試験版】送迎表の確定済み一覧: 左に名前・右に時間(固定幅で開始位置を揃える)、上部の黒い日付帯を省略</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-03): 運行表と同じで左に名前・右に時間の方が分かりやすい。時間の桁で名前の開始位置がガタガタしないように。一覧のときは上の黒い日付の帯は不要、上に詰めて。</span><span class=\"lb\">対処</span><span class=\"tx\">tp-final-board の行を 赤丸→名前(flex-1・省略)→時間(w-11 右寄せ tabular-nums) に変更。徒歩も同じ。_finalView のときは tp-date-strip を描画しない。試験版 trial189。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4bf81ae</span></span></div>\n    </article>\n    \n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"クラス在籍表 在籍 曜日 午前 午後 定員 +1 空き 待ち 介護度 ClassRosterView A4横 trial188\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-10-03</span></div>\n      <p class=\"title\">【試験版】クラス在籍表(曜日×午前/午後の在籍一覧・定員+1枠・待ち・空き)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-03): 1週間で午前と午後で誰がどの曜日のどのクラスに在籍しているかの表がパッと見れると空きが分かる。定員+1枠で。店舗のExcel 2枚を参考に。</span><span class=\"lb\">対処</span><span class=\"tx\">ClassRosterView(実績・モニタリング→クラス在籍表): 基本利用曜日 scheduleAmPm(1日は両方)から曜日×AM/PM の在籍者を 定員(facilityInfo.capacity)+1 行で表示。並び=介護度(事業対象者→要支援→要介護)→NO(id)。支援/事業はピンク、休止中は灰色+(休止)、予備行は薄黄。「待ち」は枠ごとの自由入力 systemSettings.classRosterWait[dow_sl](_fieldTs付き・blur で保存)。「空き n（定員超過 m）n/定員」。定休日(closedDays)は列から除外。印刷 A4横(外側=用紙・内側=余白div)。検証(Playwright): 画面2ブロック・待ち保存・印刷2表。試験版 trial188。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8dc60e1</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 確定済み 一覧 読み取り専用 午前 午後 編集する 一覧に戻る tpEdit trial188\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-03</span></div>\n      <p class=\"title\">【試験版】送迎表: 確定済みの週は午前・午後を一度に見渡せる一覧表示(編集する／一覧に戻る・解除で入力画面)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-03): 送迎表を開いたとき週が確定していたらプレビューを常に表示、解除したら入力画面に戻るのはどうか。ただプレビューは午前午後でスクロールが要るので一度に見たい。</span><span class=\"lb\">対処</span><span class=\"tx\">印刷プレビューの流用ではなく、確定済みの週は読み取り専用の一覧(tp-final-board: 曜日列×午前/午後、車ごとに 時刻・名前・送りタグ、徒歩・その他(理由)・未割当・休み、赤丸は _dotOf)を表示。「編集する」(tpEdit) で入力画面、ツールバー「一覧に戻る」、確定(更新)後は一覧へ、確定解除・週の移動で自動的に戻る。確定→プレビュー自動表示は維持。検証(Playwright): 確定→一覧・編集する→入力画面・一覧に戻る・解除→入力画面、赤丸ルールの回帰(chk_1002dot)も編集モード経由で合格。試験版 trial188。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8dc60e1</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳 印刷設定 微調整 廃止 プレビュー trial188\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-10-03</span></div>\n      <p class=\"title\">【試験版】連絡帳の印刷設定から「印刷位置の微調整」を外す(プレビュー側で調整できるため)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-03): プレビュー画面で印刷位置の微調整はできるので、印刷設定での微調整は不要。</span><span class=\"lb\">対処</span><span class=\"tx\">印刷設定モーダルの微調整ブロックを削除(保存値 renrakuOffsetX/Y はプレビューの調整と共用のまま)。試験版 trial188。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8dc60e1</span></span></div>\n    </article>\n    \n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"モニタリング\" data-text=\"モニタリング 一括確定 自動確定 締切 末日 18時 monConfirmInto monAutoConfirmDue 下書き 記入 trial187\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">モニタリング</span><span class=\"date tnum\">2026-10-03</span></div>\n      <p class=\"title\">【試験版】モニタリング: 一括確定ボタン／締切後は記入済みの下書きを自動で確定</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): モニタリングで全員選択した時に一括確定ボタンがあると楽。締切後は自動で確定されると尚いい。→(提案)空のままは自動で見せない・記入ありだけ自動確定、で「全て実装して」。</span><span class=\"lb\">対処</span><span class=\"tx\">共通処理 monConfirmInto(acc, rec, {auto}) = upsertSheet の確定分岐と同じ(implDate=確定日・monAnnId・ケアマネ向けお知らせ)。bulkConfirm: 選んだ方(未選択なら全員)の未確定を1回の onSave でまとめて確定(未作成は buildDefaultSheetFor)。自動確定: MonitoringView を開いたとき monAutoConfirmDue(末日18:00を過ぎた月・未確定・sheet に記入あり)を auto で確定(お知らせ id は monann_<id>_auto 固定で複数端末でも二重にならない・monAutoConfirmed=true)。締切の説明文も更新。検証(Playwright chk_1003mon): 9月の記入あり下書き→自動確定(お知らせ1件)、空の下書き→そのまま、一括確定で残りを確定(お知らせ2件)。単体23・画面24。試験版 trial187。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">020129d</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"閲覧管理 プレビュー 期間 当月以外 家族 ケアマネ 1ヶ月 3ヶ月 半年 1年 全期間 期間を指定 trial187\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-10-03</span></div>\n      <p class=\"title\">【試験版】お知らせ・閲覧管理のプレビューで家族・ケアマネの閲覧期間(当月以外)を選べるように</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): お知らせ・閲覧管理で家族やケアマネの閲覧期間(当月以外)も選べるといいかも。</span><span class=\"lb\">対処</span><span class=\"tx\">FamilyPreviewTab の「通所記録」に期間セレクト(日別: 1/3/6/12/全/指定、月平均: 6/12/全/指定)+期間指定の年月入力を追加し、PersonalDashboardView へ externalPeriod/externalDisplayMode/externalCustomFrom/To で渡す(家族・ケアマネ画面と同じ仕組み)。試験版 trial187。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">020129d</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"分析\" data-text=\"ケアマネ 家族 モニタリング 最新 確定分 前の月を見る 月 切替 trial187\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-10-03</span></div>\n      <p class=\"title\">【試験版】家族・ケアマネ画面のモニタリングは「最新の確定分」を常に表示し、前の月は「前の月を見る」で開く</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 9月分を9月末に確定した場合、10月になったらいちいち切り替えないと見れないのは面倒では。10月に9月分を載せるか、月を選べるようにするか。→(提案)最新の確定分を常に表示+前の月を見る、で了承。</span><span class=\"lb\">対処</span><span class=\"tx\">PersonalDashboardView の sec-monitoring: 見出しの右を期間ラベルから「最新：2026年9月分（10/1 確定）」(monConfirmedAt)に変更。一覧は最新1件だけ表示し、残りは「前の月を見る（n件）」で開閉(monShowOld)。もともと期間で絞っていなかったので、月をまたいでも最新分は常に見える。検証: バッジ・前の月を見る(1件)→9月/8月が並ぶ。試験版 trial187。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">020129d</span></span></div>\n    </article>\n    \n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 赤丸 連絡帳 出力時刻 cbPrintedAt _chgAt _noticeNeeded 確定 プレビュー 運行表 trial186\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】送迎表の赤丸は「前の来所の連絡帳を出した後に変えた分」だけ(連絡帳の出力時刻を記録)／確定したら運行表のプレビューへ</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 確定したらプレビューに切り替えられる？ 赤丸は、月曜に木曜を変えたら連絡帳に載るので不要、火曜に変えたら必要。水金の方は火曜に金曜を変えても水曜の連絡帳に載るので不要。当日は午前/午後で分けたい、血圧を測ったらすぐ印刷する店舗もある→「印刷した時刻を覚えてそれより後の変更だけ赤丸」で了承。</span><span class=\"lb\">対処</span><span class=\"tx\">連絡帳 doPrint で対象の記録に cbPrintedAt_AM/PM=syncNow()(+_fieldTs)を保存(区分は furikaeAmpm→表示中のAM/PM→基本曜日)。提供記録入力の再構築でも引き継ぐ。送迎表は savePlan/_saveBulk で _stampChg: 確定後に変わった人ごとに _chgAt[pid](位置が変わるたび更新・戻せば削除・確定し直しで白紙)。_noticeNeeded(送迎日,pid,chgAt): 変えた日〜前日に本人の来所(_attendees)があり、その回の cbPrintedAt が変更より後、または未出力で今日以降なら赤丸なし。それ以外・時刻不明(過去)は赤丸あり(安全側)。画面の●・印刷の●とも _dotOf 経由。確定(finalizeWeek)後は plans 更新後に doPrint(sheet) でプレビューを開く。検証(Playwright chk_1002dot): 月曜未出力に木曜変更→なし、月曜11時出力後12時変更→あり、火曜に金曜変更(水曜来所予定)→なし、火曜に水曜変更→あり、確定でプレビュー表示。連絡帳印刷で2件に cbPrintedAt 付与(chk_1002cbp)。試験版 trial186。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6ef03d3</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"提供記録 7日 1段 運動 10項目 trial186\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】提供記録: 運動が1行で収まる店舗は1ページ7日</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 運動項目が1行で収まった場合、6日分じゃなくて7日分いけるかも。</span><span class=\"lb\">対処</span><span class=\"tx\">_perPage: 運動≤10 → 7日(2段は5日のまま)。検証: 10項目+介護整体で7日・はみ出し0・行の縮み2px・縮尺0.92のまま。試験版 trial186。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6ef03d3</span></span></div>\n    </article>\n    \n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 時間 全角 PC 日本語入力 Enter 変換確定 229 8308:30 TpTimeInput その他 理由 1002f\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">送迎表の時間: パソコンの全角入力で「８３０」が「8308:30」になる(変換確定のEnterで欄を離れていた)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 「８３０」→「308:30」の件、PCの全角入力でなっている。</span><span class=\"lb\">対処</span><span class=\"tx\">1002e は「打っている間に整形しない」対策で iPad は直ったが、PC(Windows IME)は変換を確定する Enter(keyCode 229・変換中)で onKeyDown が blur → 整えた「8:30」の後ろに確定文字「830」が足され「8308:30」になっていた(CDP で再現: 変換中 Enter(229)+insertText → 8308:30)。変換中(isComposing / keyCode 229 / composing.current)の Enter は無視し、確定後の Enter だけで欄を離れる。送迎表「その他」の理由欄の Enter も同じ対策。検証: 同手順→ 8:30・保存 8:30、iPad手順も 8:30、画面24。安定版 1002f→試験版 trial185。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f4705eb</span></span></div>\n    </article>\n    \n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"分析\" data-text=\"BMI 推移 グラフ 体力測定 分析 個人 BmiTrendChart 普通体重 18.5 25 65歳以上 目標 21.5 24.9 trial184\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】BMIの推移グラフ(体力測定・分析(個人))</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 分析個人とか体力測定を見せられるところにBMI値をグラフ化して表示するようにしてほしい。</span><span class=\"lb\">対処</span><span class=\"tx\">共通部品 BmiTrendChart(points,age): 普通体重 18.5〜25 の帯・65歳以上は目標 21.5〜24.9 の帯・点の色は bmiJudge・値ラベル・年をまたぐ日付は年付き・ホバーで身長/体重。体力測定(FitnessView)は「過去の記録」の上に「BMIの推移」(入力中の今回も含む)。分析(個人)の体力測定は仮想項目 __bmi(身長が空の回はそれ以前の最新の身長)を項目ボタンに追加し、選ぶと同じグラフ+最新の判定・平均。検証(Playwright): 両画面でグラフ表示、単体23・画面24。試験版 trial184。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">bc50ab7</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"提供記録 運動 10項目 介護整体 段 6日 5日 試作店 9月 デモ 再検 3回 trial183\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】提供記録の段分け: 介護整体は10項目に数えず最後の段の右端(10項目+介護整体=1段・6日)／試作店に9月のデモ記録(再検3回の日あり)を投入</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 試作店に9月の提供記録を作成してほしい。9月の運動メニューが10個で、再検を3回行った利用者も。新しい再検の方式にした上で入力して。</span><span class=\"lb\">対処</span><span class=\"tx\">bands=運動を10個で折り返し、介護整体は最後の段の末尾(N=最大段長=10か11)。_perPage=運動≤10なら6日。試作店(store_shisaku): 2026年9月の基本利用日すべて(6名・79件)に状態/体温/血圧(開始・1回目の計測時刻 bpTSt)/脈/運動(基準値)/気分/特記を RPC upsert_ticket_records(全項目 _fieldTs=now)で投入。再検3回=bpRe に n=1〜3(時刻10分おき)+欄に最終値: 5日分(2名)、再検1回: 2日分。不要だった運動項目「f f」を「①ﾊﾞｲｸ(分)」に置換(systemSettings.exerciseItems・_fieldTs付きCAS v1253)。検証: 10項目→6日・1段、11/16項目→5日・2段、はみ出し0。試験版 trial183。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">bc50ab7</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 時間 全角 ８３０ 308:30 iPad 日本語入力 TpTimeInput 変換中 1002e\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">送迎表の時間に全角「８３０」と打つと「308:30」になる(iPadの日本語入力)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 送迎表で８３０と打ったら308:30になってしまう。</span><span class=\"lb\">対処</span><span class=\"tx\">TpTimeInput が打っている途中(onChange/compositionEnd)で全角→半角などの整形を行い、変換中の文字が残って二重になっていた(ImeSafeInput と同じ教訓)。打っている間は値を一切整えず、保存時(1.2秒後の自動保存・欄を離れたとき)にだけ _normTimeInput で「8:30」に整える。検証(CDP imeSetComposition): 全角「８３０」(まとめて確定/1文字ずつ)→欄を離れると 8:30・保存値 8:30、安定版ビルドでも同じ。安定版 1002e→試験版 trial182 にマージ。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">bc50ab7</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"再検 血圧 控える 欄を空に ポップアップ 廃止 1回目 計測時刻 移動 ボタン 名前 trial181\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】血圧の再検を「今の値を下に控えて欄を空にする」方式に(ポップアップ廃止)／右上「移動」ボタンから利用者名を外す</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 再検を押すと今のデータが一旦消えて、新しく入力すると2回目の値になる形で、下に1回目に測った時刻を表示する形にできる？→新方式で。右上の「移動」の括弧の名前は左に出ているので不要。</span><span class=\"lb\">対処</span><span class=\"tx\">applyBpRemeasure: 欄の値(上/下/脈)と bpT*(1回目の計測時刻)を bpRe に n=件数+1 として控え、欄を空に(updateRecord が bpT* も消す→次の入力で新しい時刻)。removeBpRemeasureAt: 欄が空なら控えを欄に戻す(押し間違い対策)、それ以外は削除して採番し直し。bpRe の at は同じ秒に2回押しても重ならないよう乱数付き(テストで同秒押下→別の控えが消える不具合を検出)。bpReModal/saveBpRemeasure とモーダルJSXを撤去。血圧セルに data-testid bp-cell-*。QuickNav の「移動（名前 様）▼」→「移動 ▼」。検証(Playwright chk_1002y): 160/95(10:05)→再→150/88(10:20)→再→132/80(10:35): 控え 1回目/2回目、欄 132(bpT 10:35)、再→削除で 132/80 が欄に戻る。試験版 trial181。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">bc50ab7</span></span></div>\n    </article>\n    \n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"サービス提供記録 印刷 備考 見切れ 余白 7mm 9mm tpZoom 自動縮小 trial180\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】提供記録: 印刷で備考欄が用紙の下に見切れる(画面の余白と印刷の余白の差)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 印刷をしようとすると備考欄が見切れちゃっているので、全体的にもう少し小さく縮小した方がいいかも(16項目・2段の店舗の印刷プレビュー画像)。</span><span class=\"lb\">対処</span><span class=\"tx\">原因: 用紙(.tp)の余白が画面では px-5 py-3(上下24px)、印刷では 7mm 9mm 6mm 9mm(上下約49px)で、画面の収まり判定(--tpShrink)が印刷より25px甘かった。対処: 画面の余白を印刷と同じ 7mm 9mm 6mm 9mm に統一。さらに fit() で行を縮めても収まらない用紙は中身全体の縮尺 --tpZoom(既定0.92・下限0.6)を clientHeight/scrollHeight 比で最大3回下げる(.tp>*{zoom:var(--tpZoom,0.92)} を画面・印刷の両方に)。検証(Playwright): 16項目+介護整体(2段)5日で はみ出し0(行縮み4px・zoom 0.92のまま)、12項目でも0、画面24。試験版 trial180。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4e26f9e</span></span></div>\n    </article>\n    \n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"サービス提供記録 運動 1行 10項目 2段目 6日 5日 備考 1行 70文字 特記 2行 血圧 1列 計測時刻 generateMonthlySchedule bpT trial179\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】提供記録: 運動は1行10項目(超えた分は2段目)・運動が1行なら6日/2段なら5日・備考1行70文字・特記2行・血圧欄1列(1回目の計測時刻を印刷に写す)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 運動メニューは1行に10項目でそれ以上は2段目。最低は1枚に5日分、運動が10以下で1行に収まったら6日分。備考は1行分でそれに合った文字数、特記は2行分でそれに合った行の高さに。</span><span class=\"lb\">対処</span><span class=\"tx\">TK_EX_PER_ROW=10(介護整体を含む)で bands を分割、_perPage(exLen)=運動+介護整体≤10なら6日・それ以外5日(期間モードも月ごとに同じ判定)。1段目は血圧(開始/終了)を各1列に(10px・脈は半角括弧・1回目の計測時刻は7pxで2行目)、再検は残り列。特記 tokki-row 30px(2行・AutoFitText wrap max10 min7)、備考 bikou-row 26px 1行 nowrap(84文字超7px/60超8px/44超9px)・入力欄 maxLength 70+文字数表示。generateMonthlySchedule が bpTSt/bpTEn を写していなかったため印刷に計測時刻が出ていなかった点も修正。検証(Playwright): 12項目→5日・2段、8項目→6日・1段、はみ出し0・内側スクロール0、100文字の特記が2行に収まる、単体23・画面24。試験版 trial179。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">94b52f4</span></span></div>\n    </article>\n    \n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"サービス提供記録 A4縦 5日 薄いグレー 見出し 黒 チカチカ 日付 隙間 上段 下段 11列 14列 血圧 1回目 計測時刻 自動 bpTSt bpTEn trial178\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】提供記録をA4縦・1ページ5日に(見出しは薄いグレー・日付ごとに隙間・運動は上段埋め優先)／血圧1回目の計測時刻を自動記録</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 1回目の記録の時間を覚えておくのは難しい？ 項目名が黒背景だと目がチカチカする。5日分を表示したいならA4縦で運動項目は2行にするとか。日付ごとに少しスペース。</span><span class=\"lb\">対処</span><span class=\"tx\">用紙を A4縦(210×297mm・@page portrait・プレビューも portrait・画面の縮小率は794px基準)。1ページ5日。各日=hd-row(16px・薄いグレー #e2e8f0)→data-row(28px)→運動のhd-row→ex-row(組ごと)→tokki-row(24px)、日ごとに5pxの隙間。列数 N=11〜14(運動項目+介護整体)、上段(N列)が埋まるまで上段・超えた分だけ下段(ユーザー指示)。1段目は血圧2列・再検は残り。画面にも印刷と同じ zoom 0.92。血圧(上)を空から最初に入れた時刻を bpTSt_AM/PM・bpTEn_AM/PM に保存(updateRecord・実編集として刻印・保存/再構築で引き継ぎ)、印刷の血圧欄に小さく表示。検証(Playwright): 5日・はみ出し0・内側スクロール0(7項目/12項目)、1回目 130/80 の時刻 10:05 が保存、単体23・画面24。試験版 trial178。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d099edc</span></span></div>\n    </article>\n    \n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"血圧 再検 再測定 ポップアップ テンキー 時刻 編集 2回目 3回目 1回目 通常欄 拡大 虫眼鏡 再検ボタン trial177\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】血圧の再検はポップアップで時刻・血圧・脈をテンキー入力(1回目は通常欄のまま・2回目以降として記録)／拡大画面に再検ボタン</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 再検ボタンを押すと1回目の時刻がボタンを押した時刻になる。再検を押したらポップアップで時刻(今の時刻を自動で入れて編集可)・血圧・脈をテンキーで入力し、1回目は通常欄に、2回目以降は小さく表示に。拡大(虫眼鏡)に再検ボタンが無い。</span><span class=\"lb\">対処</span><span class=\"tx\">applyBpRemeasure をモーダル(bpReModal: 時刻/血圧(上/下)/脈の3枠+テンキー・枠タップで入力先切替)に変更。記録すると bpRe に n=2,3…(時刻は入力値)で追加、通常欄が空なら1回目として通常欄へ。削除は単純削除(番号を振り直し)。拡大画面の開始/終了の血圧に「再検」ボタン。検証(Playwright): 1回目→通常欄 130/80、再検 150/88 脈72 時刻編集→「2回目 10:0 150/88 脈72」、拡大画面にボタン。試験版 trial177。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2277da4</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"サービス提供記録 各日 項目名 5行 1段目 2段目 記録者 個別 再検の右 日付 左 結合 4日 trial177\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】提供記録を各日5行(1段目の項目名/記録・2段目の項目名/記録・特記)に。記録者・個別は再検の右</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 1段目の次は1段目の記録、2段目の項目名、2段目の記録、特記の順に。再検の右に記録者と個別の枠。毎日項目名を載せないと分からない。日付は左結合のままか1行目の状態の前か(相談)。</span><span class=\"lb\">対処</span><span class=\"tx\">各日 hd-row(18px・項目名)→data-row→hd-row(運動名)→ex-row→tokki-row の5行。日付は左に rowSpan 5 で結合(日付+曜日のみ)。1段目に 記録者/個別（実施担当） を colSpan で追加(N≧16で2列)。血圧は N≧11 で2列。表の共通見出し(thead)は廃止、上の運動メニュー/設定数値の表は残す。1ページ4日(備考2行)。検証(Playwright): 4日・はみ出し0・内側スクロール0、値/再検/記録者/介護整体の表示。試験版 trial177。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2277da4</span></span></div>\n    </article>\n    \n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 振替 移動 振替の日 変更 元の休み 欠席 取り消し 理由 引き継ぎ trial176\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】送迎表: 振替で来る方を別の日へ動かすと「振替の日の変更」として扱う(元の休みは欠席のまま・理由を引き継ぐ)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 金曜休み→木曜振替の方を送迎表で木曜から水曜へ動かすと、月間スケジュールが金も木も休みで水曜振替になる。木曜は休みではなく移動した判定にして、水曜振替・金曜欠席に。理由も木曜で設定したものを自動で入れて。</span><span class=\"lb\">対処</span><span class=\"tx\">performFurikaeMove で動かす方がその日の振替(_attendees.furikae か記録が振替)なら、元の休み(月間セルの 振(M/D) か記録の「M月D日…分振替」)を求め、理由は元の休みの記録の「へ振替（理由）」から引き継ぐ。executeFurikaeMove: 振替日のセルを消し、記録は中身が無ければ削除(墓石+deleteRecordIds)、元の休みは欠席のまま「新しい日へ振替（理由）」、新しい日は 振(元M/D) と振替の記録。送迎表も元の日から外して新しい日へ。確認文も「振替の日を変更」。検証(Playwright): 10/9欠席・10/8振替→10/7へドラッグ: 月間 9=欠席・7=振(10/9)・8なし、記録 9=欠席(理由引継)・8削除・7=振替、送迎表も移動。試験版 trial176。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7bb1063</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"全体\" data-text=\"利用者マスタ管理 移動 個人ファイル 開かない 同じ画面 tsumugiReopenPF イベント trial176\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】利用者マスタ管理で「移動」→「個人ファイル」が開かない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 利用者マスタ管理で移動の個人ファイルを押しても移動しない。原因: 個人ファイルは sessionStorage に印を置いて画面の起動時に読む作りで、すでに利用者マスタ管理にいると画面が作り直されず読まれなかった。</span><span class=\"lb\">対処</span><span class=\"tx\">MasterView に tsumugiReopenPF イベントの受け口を追加し、QuickNav は同じ画面のときはイベントで合図する。試験版 trial176。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7bb1063</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"サービス提供記録 3行 バイタル 再検 運動 2段目 列 均等 1行 見出し 設定数値 縮小 5日 備考 用紙 スクロール trial176\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】提供記録を「バイタル(+再検)／運動すべて／特記」の3行構成に(列は均等・見出しは1行・5日/ページ)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 2段はそうではなく、1段目を体温・開始血圧・終了血圧などにして右の空きに再検の値、2段目にすべての運動項目(列幅はそこで調整)。項目名の行の高さを狭く、設定数値も1行、運動名が長ければ縮小して1行。</span><span class=\"lb\">対処</span><span class=\"tx\">表を作り直し。列 N=max(9, 運動項目+1)で均等割り。1段目は 状態/気分/体温/開始/終了 を colSpan で配置し、残りを「再検」欄(bpRe を「開始 2回目 10:30 150/88 脈70」で表示・多ければ縮小)。2段目は運動項目+介護整体、3段目は特記(100文字・2行)。見出し22px・設定数値22px・各行32/32/28px(--tpShrink で縮小可)。1ページ5日・備考2行。tc→N+1 の colSpan に統一。検証(Playwright): 見本で5日・はみ出し0・内側スクロール0、値/再検/特記の表示。試験版 trial176。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7bb1063</span></span></div>\n    </article>\n    \n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"自動ログアウト 20分 30分 無操作 1002d\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">自動ログアウトを20分→30分に</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 自動ログアウトの時間を30分に延長してほしい。</span><span class=\"lb\">対処</span><span class=\"tx\">IDLE_MS を 30分に(壁時計で判定・復帰時チェックは従来どおり)。安定版 1002d。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">dddee4e</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"サービス提供記録 用紙 収まる スクロールバー 介護整体 ずれ 運動項目 2段 折り返し 上下 列幅 5日 4日 自動 備考 2行 特記 100文字 制限 支援経過表 trial175\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】提供記録を用紙に必ず収める(運動項目9列超は上下2段・1ページ5日/4日・備考2行・内側のスクロール廃止)・特記は100文字まで</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 介護整体の右にスクロールバーが出ていて列がずれる。表外ではなく用紙の中にあるのはおかしい。A4に全て収まるサイズに。6日→5日にして備考を1行増やす。運動・個別が多い店舗は列幅が狭くなるので、一定数を超えたら折り返して下にもう1行。それで見切れるなら4日分に自動で。特記などは文字数制限にして、超える分は支援経過表へ。原因: 表を囲む div が overflow:auto で、用紙の高さを超えると表の中にスクロールが出ていた(前回の自動縮小は用紙側を測っていて効かず)。</span><span class=\"lb\">対処</span><span class=\"tx\">運動項目が EX_BAND=9 を超える月は上下2段(半分ずつ・列幅を確保)。設定数値の表・見出し(2行)・各日(データ行+「運動（続き）」行+特記行)を2段で描く。1ページの日数は 5日(1段)/4日(2段)で月ごとに自動(期間出力も同じ)。備考は2行(44px・折り返し)。内側の overflow:auto をやめ、用紙のはみ出し量(scrollHeight−clientHeight)を実測して各日の行を均等に低くする(--tpShrink・行数は data-rows)。特記の入力は maxLength 100(カード/表の両方)。検証(Playwright): 11項目=2段・4日・内側スクロール0・はみ出し0、7項目=1段・5日、単体23・画面24。試験版 trial175。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">514a34d</span></span></div>\n    </article>\n    \n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"サービス提供記録 縦スクロール 用紙 縦 はみ出し 行 自動縮小 --tpShrink 運行表 次回 文字 大きく trial174\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】提供記録の縦のはみ出しを各日の行の自動縮小で用紙内に／運行表の「次回」を大きく</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 提供記録の件は横ではなく縦スクロール(運動メニューが多いと見出し・設定数値の行が高くなり備考がはみ出す)。送迎表(運行表)の次回の時間(文字)をもう少し大きく。</span><span class=\"lb\">対処</span><span class=\"tx\">用紙(.tp)ごとに scrollHeight−clientHeight を実測し、はみ出し分÷(2行×6日)を --tpShrink として各日の行(46/36px→最小34/26px)から引く(useLayoutEffect・印刷も同じCSSで収まる)。運行表の次回の文字を 0.78→0.95 倍に。検証(Playwright): 個別運動7列で over=0、運行表1枚。試験版 trial174。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ced1806</span></span></div>\n    </article>\n    \n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳 次回お迎え時間 送迎表 連携 送迎表で変更 未定 空欄 優先順 頃 ご家族画面 trial173\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】連絡帳の次回お迎え時間は送迎表の時間を表示・「送迎表で変更」・「未定（空欄）」</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 基本は送迎表で変更できるように。振替の曜日やお迎え時間が未定で空欄で渡す場合にも対応したい。</span><span class=\"lb\">対処</span><span class=\"tx\">次回予定の時間欄(時/分の入力)を廃止し、送迎表の時間(getTransportTimeFor)を表示+「送迎表で変更」(その日に移動して送迎表を開く)+「未定（空欄）」チェック(nextTimeOverride=「未定」)。印刷の優先順を 未定 > 送迎表 > 以前の手入力(振替は対象日一致のみ) > 自動計算 に変更(以前は手入力が最優先)。未定は印刷・ご家族画面で空欄(「頃」も出さない)、未入力確認の対象外。検証(Playwright): 送迎表 8:40 が表示・未定で保存→印刷が空欄。試験版 trial173。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b3ac0b4</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"サービス提供記録 横スクロール 縮小 zoom 用紙 画面幅 運動メニュー 個別運動 多い 特記 長文 2行 縮小 連絡先一覧 電話 奥様 見切れ 幅 trial172\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】提供記録を画面幅に縮小(横スクロールなし)・長い特記は2行に折り返して縮小・運行表の連絡先一覧の電話欄を内容幅に</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02 店舗報告): 運動メニュー・個別運動が多い店舗でサービス提供記録が横スクロールになる(5日/4日表示にするか等の相談)。特記に長文を書く店舗で内容が入らない。西馬込で電話番号の前に「奥様」等を付けると運行表の利用者連絡先一覧の電話が見切れる。</span><span class=\"lb\">対処</span><span class=\"tx\">提供記録: 画面では用紙(A4横1123px)を画面幅に合わせて zoom で縮小(印刷は等倍。6日/ページは維持)。特記は AutoFitText(wrap)で2行まで折り返し10→7pxまで縮小。連絡先一覧の電話列は最長の電話(文字付き・最大20文字)に合わせ、収まらなければ縮小。検証(Playwright): iPad横幅で横スクロールなし(zoom 0.79)・長い特記・iPadの連絡先印刷。試験版 trial172。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c8a2d8b</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"移動 メニュー 背面 最前面 portal 利用者マスタ 送迎表 ポップアップ 文言 trial171\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】「移動」メニューが利用者マスタ管理で背面に隠れる不具合を修正・送迎表ポップアップの文言短縮</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 利用者マスタの画面で「移動」のポップアップが背面に行く。送迎表の名前ポップアップのボタン名は「月間スケジュールへ移動」に。</span><span class=\"lb\">対処</span><span class=\"tx\">QuickNav のメニューを document.body に最前面(zIndex 2000050・位置はボタンの右下)で描く。送迎表のボタンを「月間スケジュールへ移動（休み・振替・休止）」に。検証(Playwright): メニューが body 直下で覆われない。試験版 trial171。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1a7a20d</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"保存しました 電波 オフライン クラウド 保存できません 保存中 push 結果 rows upsert 待ち 1002c\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">「保存しました」はクラウドに保存できたときだけ出す(通信なし・失敗は「保存できませんでした」)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02 店舗報告): 電波をオフにして保存ボタンを押しても「保存しました」と出て、アプリを落として開き直すと保存されていない。原因: 手動保存のトーストはクラウドへの送信を待たずに出していた(送信は裏で再試行→失敗したら別のトースト)。</span><span class=\"lb\">対処</span><span class=\"tx\">手動保存は「クラウドに保存しています…」(回る輪)→店舗データ(CAS)と提供記録テーブルの両方に書けたときだけ元の「保存しました」。失敗・通信なしは「⚠ 保存できませんでした(入力は端末に控え、通信が戻ると自動送信)」。_pumpPush を呼び出しごとに結果を返す約束に(_pushWaitersRef)。トーストは ⚠=赤・…=回る輪・成功=チェック。検証: デモ(クラウドなし)の端末保存トースト・単体23・画面24。安定版 1002c(試験版 trial171 にも反映)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8ed48c8</span></span></div>\n    </article>\n    \n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 名前 ポップアップ 月間スケジュール 移動 提供記録入力 利用者マスタ フェイスシートで編集 住所 氏名 関係者 緊急連絡先 スクロール 初回 青 水色 前週コピー 臨時 振替 コピーしない trial170\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】送迎表・提供記録から月間スケジュールへ直接／「フェイスシートで編集」は項目の場所へ／前週コピーで初回の青が残らない・臨時もコピーしない</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): ①送迎表で名前を押したポップアップに「月間スケジュールへ移動」を。②提供記録入力の名前→「利用者マスタ」は休み・欠席の扱いが目的なので月間スケジュールが開いた状態に。③利用者マスタの各項目の「フェイスシートで編集」は押した項目(住所など)がすぐ出るように。④10/5が初回で青い方が、翌週にして前週コピーすると翌週も青くなる。初回は1回だけ。振替に加えて臨時もコピーに反映しないように。原因(④): _isFirstVisit は「その日より前の出席/振替の記録が無い」だけで判定していたため、まだ記録の無い先の週では毎週初回になっていた。</span><span class=\"lb\">対処</span><span class=\"tx\">①TransportView に navigateTo を渡し、ポップアップに「利用者マスタ管理の月間スケジュールへ移動（休み・振替・休止）」(既存の focus \\schedule\\=サービス提供内容タブ→月間スケジュールへスクロール・ハイライト)。②提供記録の名前モーダルの「利用者マスタ」を「月間スケジュール」にし同じ focus で開く。③focus \facesheet:name|address|related|contacts\\ を PersonalFileModal→FaceSheetForm(sectionFocus) へ渡し、data-fs-sec の場所へスクロール+2.5秒の枠(空の目印は次の要素を囲む)。④_isFirstVisit: 利用開始日まで最大120日さかのぼり、来る予定(基本曜日・月間スケジュールの〇/出席/臨時/振替・休止除く)か保存済みの送迎表に乗っている日があれば初回でない。_attendees に rinji を追加し、前週コピーは furikae/rinji の方を除外。検証(Playwright): 10/5初回=青・前週コピー後の10/12=青なし、送迎表→月間スケジュール、提供記録→月間スケジュール、住所の「フェイスシートで編集」で住所欄が画面内+枠。単体23・画面24。試験版 trial170。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">280fd85</span></span></div>\n    </article>\n    \n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 確定 完成 休み 休止 振替 反映 お知らせ 残っている 確定の解除 作成中 乗車順 範囲選択 長押し iPad data-tpdrag user-select 赤丸 赤枠 trial168 trial169\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】送迎表: 確定後に休み・休止になった方の反映／「完成」→「確定」と確定の解除／iPad長押しの範囲選択抑止／印はただの赤丸</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 確定後に月間スケジュール等で休み・休止にしても送迎表が変わらない(単なる休みにも切り替えられない)。確定を解除できるように。完成ではなく確定の方がいい。休みが増えたら注意かポップアップで「反映しますか」、間違えて反映しなくても後から変更できるように。iPadで長押しドラッグすると文字の範囲選択が出る。印の赤丸の中の白い点はいらない・時間の赤枠も不要。原因: 保存済みの送迎表は増えた方を未割当に補充する一方、来なくなった方(欠席・休止・振替で別日・休業日・利用曜日の変更)は外していなかった。</span><span class=\"lb\">対処</span><span class=\"tx\">_staleMembers(iso, sl)=保存済みの各欄に残るが _attendees に居ない方(利用期間内のみ)。週を開いたとき1回モーダル「休み・休止になった方が送迎表に残っています」(日時+名前・あとで/送迎表に反映する)、各コマにも注意+「反映」。reflectStale は車・徒歩・その他・未割当・送り別から外し _saveBulk(元に戻す対象)。外れた方は「休み」の欄と(確定後なら)「確定後に外れた」に出る。_chgOf の乗車順比較は今も乗っている方どうしの並びで(外れた分の詰まりを変更と数えない)。確定済ボタン→メニュー(確定を更新／確定を解除=_final/_finalAt を外して作成中へ)。文言を完成→確定(確定済・次週分未確定・確定後に外れた 等・ホームの案内も)。_dragHandlers に data-tpdrag、ドラッグ中 body.tsumugi-dragging、index.css で user-select/touch-callout を無効化(useLongPressReorder も)。印は中の白い点をやめ塗りの赤丸、時間の赤枠(border-red)を廃止。検証(Playwright): 確定後に月間スケジュールで欠席→モーダルに名前・あとで→各コマの注意→反映で車から外れ休み1名・変更1・元に戻す「休みの反映」、確定の解除で作成中、赤丸行の時間欄に赤枠なし、ドラッグ回帰。試験版 trial168・169。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">07f4e18 / ef22421</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"右上 ジャンプ ボタン 移動 メニュー 個人ファイル 利用者マスタ 分析 体力測定 モニタリング QuickNav trial167\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】画面右上のジャンプボタンを「移動」メニュー1つに(個人ファイルを含む6つの行き先)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 利用者マスタ管理・分析個人・体力測定などの右上の「サービス提供票／モニタリング／分析個人」等のジャンプは無くしてよい。代わりに「移動」など1つのボタンで、提供記録入力で名前を押したときと同じ行き先(個人ファイルなど)を一覧から選べるように。</span><span class=\"lb\">対処</span><span class=\"tx\">QuickNav を「移動（○○ 様）▼」ボタン1つに。押すと 利用者マスタ・個人ファイル・サービス提供記録・体力測定・分析（個人）・モニタリング(現在の画面は除く)。利用者を選んでいればその方の画面へ(個人ファイルは sessionStorage tsumugiReopenPF 経由で直接開く)、未選択なら画面だけ移る(個人ファイルは出さない)。外側タップで閉じる。検証(Playwright): 利用者マスタ管理で4件、利用者選択後は6件、個人ファイルがその方で開く。試験版 trial167。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9a9f585</span></span></div>\n    </article>\n    \n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"提供記録 欠席 出席に戻る Surface iPad 他端末 編集中 下書き 自動保存 seed-skip-dirty 空回り 版 version cas-conflict push-fail 1.8MB __clock _lastSync skipIfSame push-noop 受信停止 Realtime 再購読 abort 未同期 バナー 送迎表 時間 テンキー TpTimeInput mergeDraftRows reconcileRemoteRecords 1002b\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">提供記録: 他端末で付けた欠席が別の端末で出席に戻る／中身が同じ保存の空回り／iPadの受信停止 を修正(同期・重要)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02 扇橋): Surfaceで提供記録入力の上野様を欠席にしたあとiPadを開くと出席に戻っていた(月間スケジュールは欠席)。さらに、PC同士は同期するがiPadには途中から反映されなくなり、ホーム画面のアプリを落として再起動したら反映された。<b>調査</b>: サーバー(ticket_records)は欠席のまま(status の時刻 09:23:53)=端末内だけ食い違い。診断ログで (a) 2台の端末が互いの保存を受信→保存し直す空回り(版が20秒で27進む・cas-conflict 12回→push-fail、1.8MBの送受信を毎秒)、(b) iPad側は stall(受信20秒以上なし)152回・pull-error 90回。<b>真因</b>: ①提供記録入力は編集中(dirty)は画面の作り直しを丸ごと見送るため、他端末の欠席が画面に出ない。②自動保存は画面の全員分を再構築して書き戻すため、触っていない上野様の行が古い画面の値(出席)で端末内の記録を上書き(刻印はゲートで止まるので時刻は付かず、サーバーには届かない=端末だけ戻る)。③保存の土台(appData)より後に届いた受信は、保存の丸ごと置き換えで消える。④書き込み(CAS)は中身が同じでも __clock/_lastSync だけ変えて版を進めるため、2台で永久に空回り。⑤提供記録テーブルの受信(6秒ごと)は打ち切りも再購読も無く、iPadのスリープ後に止まったままでも「未同期」が出ない(店舗データのpullだけを見ていた)。⑥送迎表の時間は1文字ごとに店舗データ全体を保存。</span><span class=\"lb\">対処</span><span class=\"tx\">①mergeDraftRows: 編集中でも作り直し、この端末で変えた項目(前回作り直し時点との差)だけ下書きを残す(外した行・足した行も維持)。②保存で、提供記録入力が管理する項目(_REC_GATED)のうち30分以内に実編集していない項目は端末内の最新の値のまま(_fieldTs引き継ぎ・save-keep-untouched)。③handleSaveToCloud で土台より後に届いた記録の変更を取り込んでから置き換え(reconcileRemoteRecords・save-keep-remote)。④supabaseCasUpdate に skipIfSame: __clock/_lastSync 以外が同じなら書かない(push-noop)。⑤受信の20秒打ち切り(abortSignal)・重ねない・Realtime購読を CLOSED/CHANNEL_ERROR/TIMED_OUT で自動つなぎ直し(rt-resub)・45秒受信なしで「未同期(タップで再読み込み)」(stale-banner)。⑥TpTimeInput: 数字キーボード・打ち終わり1.2秒/blur/Enterで1回だけ保存。検証: 単体テスト23件(新規7件)、Playwright 24件、2端末の再現テスト(chk_1002j: 他端末の欠席を受信中に別の方を編集→自動保存→画面出入り)で修正前の安定版は出席に戻り、修正後は欠席が残る。送迎表の時間入力・元に戻す・徒歩時刻の回帰。安定版 1002b(試験版 trial166 にも反映)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">eab627b</span></span></div>\n    </article>\n    \n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"安定版へ 1002a 元に戻す 徒歩 到着時間 その他 理由 運行表 定員 送りの印 移動先 廃止 作成中 完成済 次週分未完成 運転者 到着目標 回る印 BusySpin trial159 trial160 trial161 trial163 trial164\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">送迎表の元に戻す・徒歩の到着時間・その他の理由・運行表の定員枠と送りの印・作成中/完成済表示・処理中の回る印を安定版へ(trial159〜164)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): そしたら安定版に反映。</span><span class=\"lb\">対処</span><span class=\"tx\">試験版の src/App.jsx・src/index.css を安定版へ(この時点で試験版と安定版のコードは同一。違いはこの2ファイルだけだった)。安定版のお知らせ upd-2026-1002a(元に戻す・徒歩の到着時間・その他の理由・運行表・長押しで移動・作成中/完成済・到着目標の既定・回る印の8件)。検証: ビルド・eslint no-undef 0・vitest 16・Playwright 24、徒歩の時刻(既定9:30→0945で9:45→空で戻る)、運行表(定員枠・送りの印・下部は休みのみ・日ごとの1枚/2枚)、元に戻す、時間だけの計算で未割当そのまま、作成中/完成済/計算中/運転者を数えない、iPad(WebKit)の週・日ごと印刷とPDF作成、配信後に安定版の中身と本番テスト。安定版 1002a。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">89245af</span></span></div>\n    </article>\n    \n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"処理中 読み込み中 回る 輪 スピナー アニメーション BusySpin 保存中 送信中 読込中 生成中 ログイン中 モニタリング AI下書き PDF 印刷データ準備中 送迎表 計算中 trial164\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-10-02</span></div>\n      <p class=\"title\">【試験版】処理中・読み込み中に共通の回る印(BusySpin)を付ける</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-02): 回る輪と点の点滅はどちらかでいい。モニタリングのAI下書きでもどちらかのアニメーションを。基本的に再読み込み中や何かの動作で画面が固まっている場合は分かりやすくアニメーションを追加してほしい。これまでは「保存中…」等の文字だけ(モニタリングは止まった ⟳)で、処理中か固まったのか分かりにくかった。</span><span class=\"lb\">対処</span><span class=\"tx\">共通の部品 BusySpin(src/index.css の .tsumugi-busy-spin=文字の大きさ・色に合わせて回る輪、tsumugiSpin、動きを減らす設定では遅く回す)を追加し、処理中の表示の文字の前に付けた: 保存中/送信中/読込中/確認中/登録中/作成中/変更中/ログイン中/アップロード中/掲載中/テスト中/更新中/確定処理中/生成中/読取中/自動送信中・ZIP出力とOCRの進捗・家族アプリのデータ取得中・傷病名マスタ読み込み中 など約50か所(三項演算子の文字列を一括変換し差分を目視確認)。モニタリングのAI下書きは一括の進捗ボタン(「AI下書き中 0/2（中止）」)・編集画面の「生成中…」・行の「AI生成中…」の ⟳ を回る輪に。iPadのPDF作成ボタン・印刷データ準備中の表示(画面に直接作る部分)にも回る輪。送迎表の計算中は回る輪だけにし、点の点滅は廃止。今後処理中の表示を作るときは文字の前に BusySpin を付ける(ガードレール)。検証(Playwright): 送迎表の計算中・モニタリングのAI下書き中に回る輪、ビルド・eslint no-undef 0・vitest 16・Playwright 24。試験版 trial164。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">633dea4</span></span></div>\n    </article>\n    \n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 作成中 完成済 次週分未完成 この週は完成されていません 1週間後の週 計算中 アニメーション 回る 点滅 完成後の変更 運転者 数えない trial163\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">【試験版】送迎表: 「作成中」「完成済」「次週分未完成」の短い表示・計算中のアニメーション・完成後の変更に運転者を数えない</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): 「この週は完成されていません」は長いので「作成中」、完成を押したら「完成済」。「1週間後の週が未完成」も長いので「次週分未完成」。自動計算中は・・・や回る印が動いていると分かりやすい。完成後の変更は利用者の時間をメインとして、運転者の変更は含まなくていい。</span><span class=\"lb\">対処</span><span class=\"tx\">上部の表示を短く: 未完成の週は「完成」ボタン+「作成中」、完成後は「完成済(変更N)」のボタンだけ(押すと今の内容で完成を更新・確認文に完成した日時)。「次週分未完成 ›」(対象の週は長押し説明)。ホームの案内は従来どおり。自動計算中のボタンは回る輪(tsumugiSpin)と「・・・」の点滅(tsumugiBlink)。絵文字は使わない(UI方針)。完成後の変更の件数(_chgCount)と各コマの「完成後の変更N件」から運転者の変更(_driverChg)を外す。車・順番・時間・徒歩/その他への移動・完成後に外れた は従来どおり数える。元に戻すボタンは操作名を出さず横幅を節約(確認文に操作名)。検証(Playwright): 作成中/次週分未完成/計算中の表示、完成後に完成済、運転者だけ変更=件数0・時間変更=変更1、1366px幅で1段、元に戻すの回帰。ビルド・eslint no-undef 0・vitest 16・Playwright 24。試験版 trial163。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4a29e3e</span></span></div>\n    </article>\n    \n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 自動計算 時間 だけ 未割当 配車 されてしまう 車に入る keepOrder 休止明け 1001d 1001i\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">送迎表: 「時間」だけの自動計算で未割当の方まで車に入っていた不具合を修正(今車にいる方だけ計算)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): 未割当の方がいて、車に1人でも入っている状態で自動計算の「時間」をすると配車までされてしまう。時間のときは今車にいる人だけで計算し、未割当はいじらないでほしい。原因: 休止明けの方が時間の計算の対象外になる件の対応(1001d)で、「時間」(keepOrder)のときに未割当の方を以前乗っていた車(最大8週前)か空きのある車へ入れてから計算していた。マスタ徒歩の方を徒歩枠へ寄せる処理も時間のときに動いていた。</span><span class=\"lb\">対処</span><span class=\"tx\">_autoRouteCore の keepOrder では未割当をそのまま残す(remainUn = pl.un)。マスタ徒歩の方を徒歩枠へ寄せる処理も配車のときだけ。未割当が残るコマは計算結果の知らせに「未割当のN名はそのまま」と出す。休止明けの方は下書きの時点で以前乗っていた車に入る(_histCarOf・1001d のまま)。検証(Playwright): 車2名+未割当ありで「時間」→車の2名だけ時間が入り、車の人数・未割当はそのまま。元に戻す(試験版)の回帰も確認。ビルド・eslint no-undef 0・vitest 16・Playwright 24。安定版 1001i(試験版 trial162 にも反映)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">02680d6</span></span></div>\n    </article>\n    \n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 元に戻す 取り消し アンドゥ 自動計算 間違えて 前週コピー 完成 手での変更 履歴 20回 振替 対象外 trial161\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">【試験版】送迎表に「元に戻す」ボタン(自動計算・前週コピー・完成・手での変更を20回まで)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): 送迎表にも戻るボタンが必要かな？間違えて自動計算し直しちゃった時用で。これまで送迎表には元に戻す手段が無く、自動計算は選んだ曜日・時間帯のコマをまとめて上書きするため、手で直した時間や組み合わせが失われると作り直すしかなかった。</span><span class=\"lb\">対処</span><span class=\"tx\">上部(自動計算の右)に「元に戻す(直前の操作名)」を追加。1回の操作で変わるコマ(日付_午前午後)の操作前の内容を控え(保存済みはそのまま・未保存は下書き)、戻すとその内容を新しい変更(_savedAt=今)として保存=他端末へも反映。対象=自動計算(runAutoCalc・週間一括・時間の計算・ルート計算)・前週コピー・完成・手での変更(savePlan経由の移動・並べ替え・時間・運転者・送りの別設定・理由・徒歩の時刻)。手での変更は同じコマを4秒以内に続けた分を1件にまとめる。履歴は20件・アプリを開いている間はほかの画面へ移っても残る(モジュール変数・事業所名ごと)。安全策: 控えの利用者が今の店舗にいなければ戻さない、操作後に別の変更(他端末など)があったコマは確認文で注意、振替の移動は提供記録・月間スケジュールも変えるため対象外で履歴を空にする。検証(Playwright): 自動計算→徒歩の時刻入力(1文字ずつ=1件)→元に戻す2回で計算前に戻る・確認文に誤った注意が出ない・日誌へ移って戻っても戻せる、ドラッグ移動の回帰、ビルド・eslint no-undef 0・vitest 16・Playwright 24。試験版 trial161。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">81df38e</span></span></div>\n    </article>\n    \n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"運行表 定員 枠 縮小 下部 休みのみ 初回 その他 枠 送り別 送りの印 送2号車 早退 日ごと 列見出し 午前 午後 別用紙 移動先 プルダウン 廃止 理由 家族送迎 途中参加 家族迎え 到着目標 事業所情報 開始時間 柴又 trial160\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">【試験版】運行表: 定員分の枠・下部は休みだけ・送りの違いは名前の横の印／移動先の選択を廃止／到着目標の既定表示</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): 理由は家族送迎・途中参加・家族迎え・早退・その他で。移動先プルダウンはドラッグできるので不要。送りを変えたとき下部の休みのところに入るのが微妙(人数が多いと入りきらない・文字が縮む)。下部は基本休みのみ。柴又で定員を設定しているのに午後の1号車が3枠なのはなぜ→定員が多いときは縮小して全体を表示。到着目標は事業所情報の1単位目・2単位目の開始時間を既定に。原因: 週の運行表の枠は「その週の最大乗車数+1行(定員が上限)」だった(2026-09-16f)。柴又は事業所情報の提供時間が未入力のため到着目標は予備値(8:55)になっていた。</span><span class=\"lb\">対処</span><span class=\"tx\">週の運行表: 定員設定ありの車は定員分の枠(上限10)、文字は1枚に収まるまで自動縮小(定員未設定は従来どおり)。その他を徒歩と同じ枠に1人1行(時間・次回の欄に理由)。下部は休み(と、まれな「完成後に外れた」)だけ=初回は水色の塗り・送り別の一覧は廃止。送りが迎えと違う方は名前の右に「送○号車」「送徒歩」「早退」などの小さな印(_dropTag・順番だけの違いは印なし)、凡例に「送○=送りが迎えと違う」。日ごとの運行表: その他の枠(住所の欄に理由)・送りの印・列見出しは時間帯ごと1か所(その他の枠は「理由」なので残す)。定員分の空欄で行20px未満になる日は空欄を「乗る人数+1行」に減らし、それでも収まらなければ午前・午後を別の用紙に分ける。画面: 未割当・徒歩・その他・送りの移動先プルダウンを廃止(長押しドラッグ)、送りの名前にも長押しメニュー抑止。理由=迎え 家族送迎・途中参加／送り 家族迎え・早退／その他(入力)。送迎表の設定: 到着目標が未設定なら事業所情報の開始時間を選択済みで表示し、同じまま保存すると空(=追従)で保存。未入力なら「事業所情報の1単位目の時間が未入力」と表示。検証(Playwright): 定員6/4/6・3台で週の運行表が1枚(満席の週も)、送りの印(送2号車・早退・送1号車)、下部に初回・送り別が無い、日ごと=空きのある日は1枚・満席の日は午前/午後の2枚、移動先の選択0件・ドラッグで徒歩/その他/車の移動、設定の既定表示9:30/13:40と空で保存。ビルド・eslint no-undef 0・vitest 16・Playwright 24。試験版 trial160。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d2f41c8</span></span></div>\n    </article>\n    \n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 徒歩 到着時間 開始時刻 クラス 編集 その他 理由 家族送迎 途中参加 遅れて来所 通院後 タクシー 早退 家族迎え 手入力 送り別 運行表 trial159\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">【試験版】送迎表: 徒歩の方に到着時間(既定=クラスの開始・個別に変更可)・「その他」に理由(迎え/送り)を選べるように</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): 徒歩にしたら自動で開始時間になるように・あとから編集も可能に。その他にしたら遅れて通所など選べるように(ほかに想定されるものも・短い言葉で)。送りのその他は早退など。</span><span class=\"lb\">対処</span><span class=\"tx\">徒歩: 保存値「徒歩」をクラスの開始時刻(各種設定の提供時間)として表示し、1人ずつ時刻を入れて変更可(IME対応の入力欄・0945→9:45)。空にして離れると「徒歩」(=開始時刻)に戻るので、提供時間を変えれば追従する。徒歩から車へ移すと時刻は空に。完成後の到着時間の変更も●で表示(完成時の控えに walkT を追加・旧い控えは比較しない)。その他: why 項目に理由を保存。迎え=家族送迎・途中参加(遅れて来所の短縮)・通院後・タクシー、送り=早退・家族迎え・通院・タクシー、ほかは「手入力」(12文字まで)。その他から出ると理由は消える。運行表(週)の徒歩の行に個別の時刻、その他・送り別に「名前(理由)」、日ごとの運行表にも送りの割り当てを1行で追加。検証(Playwright): 徒歩の表示 9:30→0945 入力で 9:45→空で「徒歩」に戻る・理由の選択と手入力の保存・徒歩→車で時刻が空・その他→未割当で理由が消える・送りのその他に早退・週/日ごとの印刷に反映、ビルド・eslint no-undef 0・vitest 16・Playwright 24。試験版 trial159。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">82b8fba</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 徒歩 その他 ドラッグ 変更できない iPad 長押し 選択メニュー 移動先 未割当 1001h\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">送迎表: 徒歩・その他に入れた方を変更できない不具合を修正(移動先の選択・長押しで選択メニューを出さない)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): 送迎表で徒歩やその他にドラッグして入れた人が変更できなくなっているそうなので、バグなら安定版でも修正を。原因: 車の欄の名前はボタンだが、徒歩・その他・未割当の名前は文字(span)で、iPad では文字の長押しで選択メニュー(コピー等)が出てドラッグが始まらない。徒歩・その他には「移動先」の選択も無かったため動かす手段が無かった(パソコンのマウス操作では動かせることを確認)。</span><span class=\"lb\">対処</span><span class=\"tx\">徒歩・その他・未割当の名前に user-select:none・-webkit-touch-callout:none・右クリックメニュー抑止を付け、長押しでドラッグが始まるように。徒歩・その他の方にも未割当と同じ「移動先…」(車・徒歩/その他・未割当)の選択を追加。検証(Playwright): ドラッグで徒歩→車・その他→車、選択で徒歩→1号車・その他→未割当、名前の欄の user-select が none。安定版 1001h。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳 B5 2面 穴あけ 上 目印 三角 ▼ 印刷 消える プレビュー 印字できない範囲 7mm 1001h\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">連絡帳: 穴あけの目印(▼)がプレビューでは出るのに印刷で消える不具合を修正(用紙の端から7mmへ)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): 連絡帳をB5で2枚印刷し穴あけを上に設定していると、プレビューでは三角の矢印が出るが印刷すると消える。原因: 目印を各面の上端から2mm(左綴じの◀は3.5mm)に置いていたため、プリンタの印字できない範囲(端から約4〜5mm)に入って印刷されなかった。</span><span class=\"lb\">対処</span><span class=\"tx\">目印を用紙の端から7mmへ(上綴じ▼・左綴じ◀とも)。連絡帳の中身は上綴じで14mmから・左は綴じ代の空白の中なので重ならない。検証: 印刷プレビューで ▼ の位置 7mm・連絡帳の枠と重ならないことを画像で確認。安定版 1001h。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"安定版へ 1001g 自動計算 車 選択 次回お迎え時間 頃 trial156\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">送迎表の自動計算の車の選択・次回お迎え時間の「頃」を安定版へ(trial156)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): 安定版に導入して。</span><span class=\"lb\">対処</span><span class=\"tx\">試験版の App.jsx を安定版へ(この時点で試験版と安定版のコードは同一)。安定版のお知らせ upd-2026-1001g。検証: ビルド・eslint no-undef 0・vitest 16・Playwright 24・車の選択(1号車だけ計算で2号車の時間が残る)・連絡帳の「頃」がはみ出さない、配信後に安定版の中身に新機能があること・本番テスト 16/16。安定版 1001g。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"残骸 曜日 減らす 利用終了日 退所 空の記録 出席 片付け 墓石 自動 1001f\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">曜日を減らした・利用終了日を入れたときに、合わなくなった空の出席記録を自動で片付け(残骸にしない)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01 残骸の検査の写真): 9/28より前に月曜を減らしていた方の 9/28 の記録が残骸に出る。曜日を減らした・退所した場合に残骸にならないようにできるか。原因: 提供記録入力の保存は、その日に来る予定の全員分の記録(中身が空の「出席」=来所の印)を作る。その後で曜日を減らす・終了日を入れると、合わなくなった日の空の記録が残っていた。</span><span class=\"lb\">対処</span><span class=\"tx\">cleanupStaleEmptyRecords: 利用者マスタの保存(通常・自動保存・基本利用日の変更)で、変更前は有効・変更後は合わなくなった(利用期間外、または基本利用日でなく月間スケジュールに出席/臨時/振替の印も無い)「中身が空の出席記録」だけを墓石付き(deletedIds＋deleteRecordIds)で削除。バイタル・特記のある記録、振替・臨時、欠席・休止は残す。保存の案内に件数を表示。検証(App.jsx の判定をそのまま取り出して実行): 月曜を9/22からやめる→9/28の空の記録だけ削除・バイタルありの月曜/変更前/水曜は残す、終了日9/29→9/30の空だけ、臨時の印がある日は残す、変更なしは削除しない。既に残っている分は「残骸を検査する」で削除。安定版 1001f／試験版 trial156。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"同じマンション 同じ建物 乗車時間 5分 合算 移動時間 1か所 地図 お迎え 早すぎる 1001f\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">送迎表: 同じマンションの方のお迎え時間が早すぎる不具合を修正(同じ建物は1か所として地図へ・乗車時間は最長の1回だけ)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01 送迎表の写真): 同じマンションの4名(まとまって5分ほど・それぞれ乗車5分に設定)が13:02で、5分だとしても10〜15分で到着するはず。同じ住所が連続すると時間がかかるなら、まとめて1つとしてマップに数えてほしい。原因: 逆算で4名それぞれの乗車5分(計20分)を足し、同じ住所の間にもGoogleの移動時間が入っていた。最後に同じ建物の方を同じ時刻にそろえていたため、全員が実際より早い時間になっていた。</span><span class=\"lb\">対処</span><span class=\"tx\">同じ建物(建物キー=部屋番号・建物名・丁目/番/号・全角の表記ゆれを吸収)の方を1か所にまとめ、Googleへは1地点として送る(時間だけ・配車とも)。逆算は1か所ごとに「乗車にかかる時間=その中で最長」＋次への移動。全員同じお迎え時間。検証(ルート計算はモック・区間3分): 同じ建物4名(各5分)＋1名(3分)で地点2か所・建物の4名は13:17(従来は20分分早くなっていた)。安定版 1001f／試験版 trial156。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"自動計算 車 選択 手入力 上書き ステップ タント trial156\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">【試験版のみ】送迎表の自動計算で車も選べる(選ばない車は時間・順番をそのまま)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): 自動計算が曜日ごとの午前・午後しか選べず、ステップとタントを手入力で変更したのに自動計算されてしまう。車も選択できるとよい。</span><span class=\"lb\">対処</span><span class=\"tx\">自動計算の画面に「車」の選択(初期は全車)。_autoRouteCore に carIds を渡し、選んだ車だけを計算対象に(選ばなかった車の乗車の方・順番・時間は保持。配車を選んだ場合も、選んだ車の方と未割当だけを選んだ車で組み直す。時間だけの計算で未割当の方を入れる先も選んだ車だけ)。検証(Playwright): 1号車だけ選ぶと2号車の手入力 13:00 が残る。試験版 trial156 のみ。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"次回お迎え時間 頃 連絡帳 分析個人 ご家族 ケアマネ 変更のお知らせ trial156\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">【試験版のみ】次回お迎え時間に「頃」(連絡帳・分析個人・ご家族/ケアマネ・変更のお知らせ)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): 連絡帳と分析個人など次回お迎え時間を記載している箇所で分の後に頃を追記してほしい。</span><span class=\"lb\">対処</span><span class=\"tx\">連絡帳カード(画面・印刷とも同じ部品)の次回お迎え時間を「○ 時 ○ 分頃」に(枠からはみ出さないことを確認)。分析個人・ご家族/ケアマネの「本日/次回のお迎え時間」は「9時15分 頃」→「9時15分頃」(間の空白をなくす)、お迎え時間の変更のお知らせも「（9時00分頃 → 9時15分頃）」に。試験版 trial156 のみ。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"体力測定\" data-text=\"体力測定 BMI 安定版へ 1001e\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">体力測定</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">体力測定の BMI 自動表示を安定版へ(trial154)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): 入れたら全て安定版に導入して。</span><span class=\"lb\">対処</span><span class=\"tx\">試験版 trial154 の BMI(判定の色分け・基準の凡例)を安定版へ。この時点で試験版と安定版のコードは同一。安定版 1001e。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"フェイスシート かかりつけ医 複数 追加 削除 主治医 医療機関 連絡先 PDF 計画書 自動読み込み extraDoctors 1001e\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">フェイスシート: かかりつけ医を複数登録できるように(＋かかりつけ医を追加・削除・PDF・計画書の自動読み込み)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): フェイスシートのかかりつけ医で、複数ある人もいるので追加ボタンで増やせるように。入れたら全て安定版に。</span><span class=\"lb\">対処</span><span class=\"tx\">フェイスシートに extraDoctors([{doctor, institution, contact}])を追加(1人目は従来の 主治医・医療機関・連絡先 のまま=利用者本体の doctor 等との双方向連携も従来どおり)。「⑤ 医療・健康情報」に「＋ かかりつけ医を追加」・各ブロックに削除(確認つき)。フェイスシートPDFに「かかりつけ医（2）…」の行、計画書のフェイスシート自動読み込み(合併症・健康状態)に全員分の主治医・医療機関を「、」でつなげて入れる。ケアマネへの更新通知の差分(diffFaceSheetFields)で追加分は中身まで比べる。保存はフェイスシートの1オブジェクトのまま(同期の扱いは変わらない)。検証(Playwright): 2件追加→1件削除→保存→開き直しで残る・PDFに表示。安定版 1001e(試験版 trial155 と同時)。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"体力測定\" data-text=\"体力測定 BMI 自動計算 身長 体重 肥満 やせ 低体重 普通体重 色分け 基準 65歳以上 目標 21.5 trial154\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">体力測定</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">【試験版のみ】体力測定に BMI を自動表示(やせ・普通・肥満を色分け・基準つき)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): 体力測定の欄に身長と体重から BMI を自動で算出して出してほしい。肥満・痩せ型などの基準値がわかるように、数値は色分けすると分かりやすい。</span><span class=\"lb\">対処</span><span class=\"tx\">calcBmi(体重kg÷身長m²・小数1桁・ありえない値は出さない)と bmiJudge(日本肥満学会: 18.5未満=低体重(やせ)青／18.5〜25未満=普通体重 緑／25〜30未満=肥満1度 オレンジ／30以上=肥満2度・3度・4度 赤。65歳以上は厚生労働省「日本人の食事摂取基準」の目標21.5〜24.9より低い普通体重を「目標より低め」黄)。体力測定の入力表で体重の下に「BMI(自動計算)」の行(今回・前回・平均)、過去の記録の表に BMI 列、表の下に基準の凡例。身長が空の回はそれ以前の最新の身長で計算(今回は「身長は前回の値」と表示)。保存データは変えない(表示だけの計算)。検証(見本データ): 150/46→20.4 普通体重(目標より低め・86歳)、152/75→32.5 肥満2度、152/62→26.8 肥満1度、152/41→17.7 低体重、平均25.7。eslint no-undef 0・vitest 16・Playwright 24。 試験版 trial154 のみ。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"iPad 第8世代 電話番号 FAX 郵便番号 数字 増える 03-306 日本語入力 変換中 IME ImeSafeInput 77か所 1001d\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">iPadで電話番号・FAX・郵便番号などを打つと押していない数字が入る不具合を修正(同じ作りの入力欄 77か所)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): フェイスシートの電話番号やFAXを iPad(第8世代)で 03-6 と打つと 03-306 のように押していない数値が入る。iPad Pro では普通に入力できた。他の電話番号や数値の入力箇所も丁寧に調査して修正。原因: 画面のキーボード(日本語入力)は数字も変換中(未確定)として持ち、入力中に欄の中身を書き換える(ハイフン付け・全角→半角・数字以外を消す)と iPad が変換中の文字をもう一度入れる(外付けキーボードの iPad Pro では変換中にならない)。</span><span class=\"lb\">対処</span><span class=\"tx\">入力欄の部品 ImeSafeInput を追加: フォーカス中は打ったままの文字を表示、変換中(compositionstart〜end)は親へ渡さず確定時に渡す、親が整えた値は欄を離れたとき表示(フォーカス中に親が値を入れた・空にした場合は追従)。onChange で値を整える／表示を整形する <input> を走査して 77か所を置換(フェイスシートの電話・FAX・郵便番号・緊急連絡先、利用者マスタのご家族の電話、各種設定の事業所情報・店舗/職員/ログイン、ケアマネ事業所・担当者、ご家族/ケアマネの登録・ログイン・パスワード再設定、招待コード、日付の分割入力、体力測定、保険者番号・疾病コード 等)。サービス提供記録のバイタル欄は打ったまま保存する作りのため対象外(問題なし)。検証(Chromium の IME 入力を CDP で再現・修正前の安定版と比較): 03-6640 → 修正前 03-6664-00／修正後 03-6640、全角 ０３６ → 修正前 003-036-036／修正後 03-6、郵便番号 1350001 → 修正前 135-0000／修正後 135-0001。eslint no-undef 0・vitest 16・Playwright 24。安定版 1001d。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"退所 利用終了日 南水元 日誌 出席 送迎表 実績 分析 残骸 9/30 1001d\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">利用終了日を過ぎた方が日誌に「出席」と出る(提供記録入力には出ない)不具合を修正・送迎表/実績表/分析でも扱わない</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01 南水元): 9/28に退所した方が提供記録入力には出ないが日誌には出席と出る。どこにも反映されないように。調査(件数のみ): 該当の方は状態「利用中」・利用終了日 9/28・9/30 に中身が記録者だけの「出席」記録が1件(終了日を入れる前に作られた)・9/28より後の送迎表2コマにも残っていた。日誌は「その日の記録がある方」を終了日を見ずに載せていた。</span><span class=\"lb\">対処</span><span class=\"tx\">共通の判定 recordWithinPatientPeriod(記録の日付が利用開始日〜終了日の内か)を追加し、日誌(本体・プレビュー)の記録がある方・利用者実績表(calcCell)・分析(稼働)の集計元・送迎表(保存済みの送迎表の車/徒歩/その他/未割当/送り別)で期間外を除外。残骸の検査に「利用終了日より後」「利用開始日より前」を追加(振替・臨時も対象・墓石付きで全端末から削除)。検証(Playwright): 終了日 9/28＋9/30 の記録で日誌・送迎表に出ない(終了日なしの対照では出る)・残骸の検査で検出。南水元の 9/30 の記録は店舗で「残骸を検査する」→削除で消せる。安定版 1001d。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"休止 終了日 休止明け 自動計算 時間 未割当 前週 履歴 8週 1001d\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">送迎表: 休止明けの方の時間が自動計算(時間だけ)で入らない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): 休止期間の終了が入力されている状態で、終了以降の送迎表で時間を自動入力しようとすると反映されない。調査(件数のみ): 扇橋に休止の終了日が10/4・10/5の方が2名(状態は休止のまま)。原因: 休止中だった前週の送迎表に居ないため翌週は未割当になり、「時間」だけの自動計算(配車は既定でチェックなし)は車に乗っている方しか計算しないため時間が入らなかった。休止の期間判定自体(_isPausedOn)は正しかった。</span><span class=\"lb\">対処</span><span class=\"tx\">下書き(_draftPlan)で前週に居ない方は同じ曜日・時間帯の送迎表を最大8週前までさかのぼって乗っていた車へ(徒歩・その他も)。「時間」モードでも未割当の方を、以前の車(定員に空き)→無ければ空きのある車のうち乗車が少ない車へ入れてから時間を計算し、入れた方を知らせる(住所未入力の方は未割当のまま)。検証(見本データで再現): 休止(9/20〜10/4)の方が 10/5 の時間だけの計算で 2号車 8:49 に入る。安定版 1001d。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 来週 日付 戻る 今日 提供記録入力 日誌 別ページ 1001d\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">送迎表から別の画面へ移ったら、日付を今日(定休日なら次の営業日)に戻す</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): 10月5日など来週の送迎表を開いた後に提供記録入力や日誌へ移ると10月5日のまま表示される。送迎表から他へ行く場合は今日の日付に戻してほしい。</span><span class=\"lb\">対処</span><span class=\"tx\">画面の切り替え(currentView)で、直前が送迎表で別の画面へ移ったときだけ共通の日付(selectedDate)を今日に戻す(今日が定休日・休業日なら起動時と同じく次の営業日)。検証(Playwright): 送迎表で2週先へ→提供記録入力の日付が 2026-10-01。安定版 1001d。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"欠席理由 ショートステイ 運行表 休み 大きく 安定版へ 1001d\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">欠席理由「ショートステイ」(trial149)と運行表の「休み」を大きく(trial151)を安定版へ</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): 欠席理由のショートステイと運行表の休みを大きくも安定版に。</span><span class=\"lb\">対処</span><span class=\"tx\">試験版の該当コードを安定版へ(この時点で試験版と安定版のコードは同一)。安定版 1001d。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 時間 入力 iPad 8:00 消せない 8033 :00 削除 4桁 自動 安定版 1001c trial150 trial152\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">送迎表の時間が「8:00」から消せない・「:00」を消して打つと「8033」になる不具合を修正(4桁の自動変換とあわせて安定版へ)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): 安定版で送迎時間をiPadで入力しようとしたら8:00から消せなくなり、:00を選択して削除して入力すると8033みたいにおかしくなる。試験版で直っているなら安定版に反映。原因: 時間の欄は表示のたびに 8:0 を 8:00 に整えていたため、1文字消してもすぐ 8:00 に戻った。「:00」をまとめて消すと「8」が残り、続けて打った数字がつながって 8033 になっていた。</span><span class=\"lb\">対処</span><span class=\"tx\">試験版 trial150 の時間入力の整え方(入力途中の 8:0・8: はそのまま表示／全角・半角の4桁を H:MM に／3桁は欄を離れたときに)を安定版へ。さらに「8」が残ったまま「033」と打った 8033(80時は無い)を 8:33 と読む規則を追加(試験版 trial152 にも)。検証(Playwright・WebKit で iPad を再現＋Chromium): 8:00 を1文字ずつ消すと 8:0→8:→8→空、「:00」を消して 033 を打つと 8:33、0810→8:10・１３２０→13:20・810→8:10。eslint no-undef 0・vitest 16・Playwright 24。 安定版 1001c／試験版 trial152b。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"運行表 休み 大きく 文字 8割 週 日ごと trial151\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">【試験版のみ】運行表(週・日ごと)の「休み」の文字を少し大きく(名前の約8割)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): 休みをもう少し大きく表示してほしい(同日 trial143 で名前の約2/3にしていた)。</span><span class=\"lb\">対処</span><span class=\"tx\">週の運行表・日ごとの運行表の「休み: ○○」だけを名前の約8割(週は最小9px・日ごとは最小10px)に、色を #64748b→#475569 に少し濃く。初回・その他・完成後に外れた・送り別は従来どおり約2/3。行数の見積り(1枚に収める計算)にも休みの大きさを反映。検証(見本データ): 週・日ごとの印刷プレビューで休みが大きくなり用紙に収まる、iPad(WebKit)のPDFも1枚に収まる。eslint no-undef 0・vitest 16・Playwright 24。 試験版 trial151 のみ。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 時間 入力 全角 半角 0810 1320 8:10 13:20 自動 変換 trial150\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">【試験版のみ】送迎表の時間入力: 全角・半角の「0810」「１３２０」を自動で 8:10・13:20 に</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): 送迎表の時間を入力するとき、全角でも半角でも0810や1320と入力したら自動で8:10や13:20となってほしい。</span><span class=\"lb\">対処</span><span class=\"tx\">時間の欄の入力を _normTimeInput で整える: 全角の数字・コロンを半角に、4桁(時が23以下・分が59以下)は入力した時点で H:MM に、3桁(810)は入力途中と区別できないため欄を離れたときに 8:10 に。あわせて入力途中の「8:1」が表示で「8:01」に変わり続けて打てなくなる問題も解消(1桁の分は入力中そのまま表示)。欄を離れただけで旧形式の保存値(8時30分 等)を書き換えないよう、変換が必要なときだけ保存。検証(Playwright): 0810→8:10・１３２０→13:20・810→(離れると)8:10・8:15→8:15。eslint no-undef 0・vitest 16・Playwright 24。 試験版 trial150 のみ。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"iPad 印刷 反応しない ホーム画面 アプリ window.print 無効 PDF 共有メニュー プリント ファイルに保存 運行表 下部 見切れ Safari height 100% 凡例 1001b\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">iPadで「印刷 / PDF保存」を押しても印刷画面が開かない・運行表の下部が見切れる不具合を修正(PDFを作って共有メニューから印刷)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): iPadで印刷しようとすると運行表の下部が見切れる。スマホやタブレットの印刷は工夫が必要。印刷/PDF保存をクリックしても反応せず印刷画面にいかない。原因: ホーム画面に追加したアプリ(全画面)では iOS の仕様で window.print() が何もしない(9/28 に重ねて表示する方式にしたが、その印刷ボタンが無効だった)。見切れは iPad が用紙の上下にURL・日付の欄を取るため、用紙いっぱい(297×209mm 等)の表が入り切らないこと。さらに Safari(WebKit)では運行表(週)の flex＋height:100% の表が親いっぱいになり題字・凡例の分(約50px)はみ出して凡例が切れ、連絡先一覧は表が伸びなかった。</span><span class=\"lb\">対処</span><span class=\"tx\">iPad/iPhone のホーム画面アプリでは、印刷表示の上部ボタンを「PDFにして印刷・保存」に: 用紙([data-page-break]/.l-page/.p-page、無ければ用紙の高さで区切る)ごとに SVG foreignObject でブラウザ自身に描かせて画像化(縦書き・表もそのまま・CSSは@media printを採用して印刷時の見た目に)→ JPEG だけで PDF を組み立て(外部ライブラリなし)→ もう一度押すと共有メニュー(navigator.share、iOS はタップ直後でないと開かないため2段階)。共有できない場合はPDFを開く。招待用紙などの重ね表示にも同じボタン。Safari で直接印刷する場合は用紙いっぱいの表を88%に縮めて中央に。運行表(週)と連絡先一覧の表の高さを px で指定、午前・午後の縦書きを折り返さない。検証(Playwright WebKit・iPadのUA・ホーム画面アプリを再現): 週1枚/日ごと5枚/連絡先2枚のPDFが0.2〜0.6秒で作成され、画像にして全ページ・凡例まで収まることを確認、Chrome側の印刷の見た目も変わらないことを確認。eslint no-undef 0・vitest 16・Playwright 24。 安定版 1001b／試験版 trial149b。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"欠席理由 大分類 冠婚葬祭 ショートステイ 変更 提供記録入力 月間スケジュール 送迎表 振替 分析 ランキング 過去データ trial149\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">【試験版のみ】欠席理由の選択肢「冠婚葬祭」を「ショートステイ」に変更(過去の冠婚葬祭は分析で従来どおり集計)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): サービス提供記録入力や月間スケジュールで欠席にしたときにタップで選べる中に冠婚葬祭があるが基本的に使わないので、ショートステイに変更して。</span><span class=\"lb\">対処</span><span class=\"tx\">欠席理由の大分類 ABS_REASON_CATS の「冠婚葬祭」を「ショートステイ」に(提供記録入力の欠席/振替・月間スケジュール・送迎表の振替理由で共通)。過去に「冠婚葬祭（…）」で記録した分は ABS_REASON_LEGACY_CATS として、分析の欠席理由ランキングの集計だけで大分類として認識(入力画面の引き継ぎでは全文を詳細欄へ)。旧自由文のキーワードに「ショートステイ/ショート/短期入所/お泊り」を追加。休止の理由(入院・介護施設入所等)は別の一覧のため対象外。事業所向けマニュアルの記載も更新。検証(見本データ): 選択肢=体調不良・通院・受診・入院・本人・家族の都合・ショートステイ・天候・その他、「冠婚葬祭（法事）」はランキングで冠婚葬祭1件(内訳 法事)、「ショート利用のため」はショートステイ1件。eslint no-undef 0・vitest 16・Playwright 24。 試験版 trial149 のみ。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"安定版へ移行 1001a 送迎表 画面整理 自動計算 完成 日付固定 リマインド 予定 確定 待ち合わせ場所 選択式 徒歩 オレンジ 送り ドラッグ 備考 廃止 運行表 週 日ごと 連絡先一覧 緊急連絡先 削除 日誌 兼務 モニタリング A4横 trial129 trial147\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">安定版へ移行(1001a): 試験版だけだった送迎表の画面整理・運行表/連絡先一覧の見直し・待ち合わせ場所の選択式・送りのドラッグ・緊急連絡先の削除・日誌の兼務記載・ケアマネ画面のモニタリング表A4横(trial129〜147)を全店へ</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): 「安定版へ」。扇橋店で確認していた試験版だけの機能を全店へ。</span><span class=\"lb\">対処</span><span class=\"tx\">試験版と安定版の差は src/App.jsx と update-notes.json だけだったため、試験版の App.jsx をそのまま安定版へ(git checkout trial -- src/App.jsx)。対象: trial129(日付の固定帯)・130(自動計算の選択式/完成と未完成の案内/来週リマインド/予定・確定表示/モニタリング表A4横)・132(緊急連絡先の削除とアカウント削除時の確認)・133(待ち合わせ場所の選択式/印刷の行分け/毎日のリマインド判定)・134(自動計算のチェック)・135(日誌の兼務記載/マンション入口外)・137(配車は既定オフ)・139(徒歩の色)・141〜147(週/日ごとの運行表・連絡先一覧・送りのドラッグ・備考欄廃止)。安定版のお知らせ upd-2026-1001a を1件にまとめて追加、試験版は trial148 に合流(試験版と安定版のコードは同一)。検証: 安定版の候補でビルド・eslint no-undef 0・vitest 16・Playwright 24・印刷の確認スクリプト、配信後に安定版の本番の中身に新機能の文言があることを確認、本番テスト 16/16。※車の定員は8店中2店だけ入力済み(日ごとの空欄行に使う)。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"日ごと 運行表 無駄 スペース 余白 名前 住所 電話 列幅 下部 大きく 徒歩 枠 trial147\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">【試験版のみ】日ごとの運行表: 列幅を中身に合わせ、行と文字を用紙の下まで使い切る(名前・住所・電話を大きく・下の余白を削減)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01 扇橋の日ごと印刷の写真): 名前も住所も電話も下部も無駄なスペースが多い。</span><span class=\"lb\">対処</span><span class=\"tx\">日ごとの運行表(A4縦)を作り直し: 氏名の列=その日いちばん長い名前(赤丸込み)の幅、時間=時刻の幅、電話=いちばん長い電話番号の幅、住所=残り。行の高さHを本文の高さ(約991px)に収まる最大値で求め(最大38px)、文字は名前=H由来で最大22px・住所=名前と同じ大きさまで(長い住所は幅に合わせて縮小、9px未満は折り返し)・電話=名前の0.9倍・休み等=約2/3。各車の枠は行数に比例して用紙の下まで伸ばし(見積りの余りを行へ)、1行は通常の約1.5倍までに制限(利用者が少ない日の間延び防止)。徒歩は週の運行表と同じく車と同じ枠(見出し「徒歩（到着 13:25）」・住所と電話つき)。検証(見本データ): 90名・定員8/7の日は用紙の下までぴったり、定員なし・少人数の日は22pxで行が伸びすぎない。eslint no-undef 0・vitest 16・Playwright 24。 試験版 trial147 のみ。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"日ごと 運行表 定員 空欄 行 手書き trial146\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">【試験版のみ】日ごとの運行表: 車の定員分の行を空欄でも表示</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01): 日ごとでも定員数分は空欄でも表示してみて。</span><span class=\"lb\">対処</span><span class=\"tx\">日ごとの運行表(A4縦)の各車の枠を「乗る人数」と「定員」の多い方の行数に(空席は名前・時間・住所・電話とも空欄で同じ高さ)。定員未設定の車は従来どおり乗る人数分(最低1行)。行数の見積りにも反映し1枚に収める。定員の入力状況(件数のみ): 車が登録されている8店のうち定員入力済みは2店(各3台)、他の6店は未入力のため人数分のまま。検証(見本データ・定員8/7): 乗車5名の車に空欄3行・90名の日も1枚に収まる。eslint no-undef 0・vitest 16・Playwright 24。 試験版 trial146 のみ。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"連絡先一覧 左から埋める 25人 日ごと 運行表 午前 午後 離す 車両 間隔 trial145\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">【試験版のみ】利用者連絡先一覧は左の段から25人ずつ埋める／日ごとの運行表で午前と午後・車と車の間をあける</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01 連絡先一覧2枚目の写真): 左右に半分ずつ(8人・7人)になっている→前半も後半も左側から埋めて。日ごと印刷で午前と午後をもう少し離して、車両もほんの気持ち離して。</span><span class=\"lb\">対処</span><span class=\"tx\">連絡先一覧: 25人以下のページも左右半分ずつにせず、左の段から25人→右の段に残り(空いた行は空欄)。日ごとの運行表(A4縦): 午後の見出しの上を3→11mm、各車の枠の上に2mm(従来は枠を上下に接していた)。あけた分(8mm＋車の数×2×2mm)を文字の大きさの見積りから差し引き、1枚に収まるように。検証(見本データ): 35名=左25・右10、90名の日ごと印刷が1枚に収まり午前午後・車の間があく。eslint no-undef 0・vitest 16・Playwright 24。 試験版 trial145 のみ。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"運行表 見出し 氏名 時間 次回 午前 午後 各曜日 空きセル 削除 運転者 青 車名 色 区別 連絡先一覧 左25人 右25人 余白 用紙いっぱい trial144\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">【試験版のみ】運行表: 各日の午前・午後に「氏名・時間・次回」の見出し・次回の右の空き欄を削除・運転者の欄を薄い青に／連絡先一覧: 左25人・右25人で用紙の下まで</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01 印刷の写真): 連絡先一覧は左25人・右25人で、下の空白をなくして。運行表の氏名・時間・次回の項目名が消えたので各曜日の午前・午後の上部に1か所ずつ。次回の右の無駄なセルを消して。車名と運転者の背景が同じ色でわかりづらい。</span><span class=\"lb\">対処</span><span class=\"tx\">運行表: 各日の午前・午後のセルの先頭に見出し行(氏名・時間・次回、文字は名前の約0.6倍)を1つ置き、左端の車名の列も同じ高さだけ下げて車の枠の位置をそろえる(行数の見積りにも加算)。右端の手書き用の空きセル(trial141で追加)を廃止し、余った幅の5割を氏名・3割を時間へ、次回は残り。運転者の細い欄は薄い青(#e6effa・文字は紺)、徒歩の枠の運転者欄は白。連絡先一覧: 1枚に左25人・右25人(25人以下は左右に半分ずつ)、表は高さ100%で用紙の下まで伸ばし行の高さを均等に、足りない行は空欄(1行おきのグレーは継続)。文字は本文÷25行に収まる大きさ(11〜18px)・住所は1行に収まるよう縮小(9px未満の長い住所のみ2行)。検証(見本データ): 90名=1枚目50名(左25・右25)で下の余白なし・2枚目40名、40名=左25・右15＋空欄10行、運行表の見出し・青い運転者欄・空きセルなし。eslint no-undef 0・vitest 16・Playwright 24。 試験版 trial144 のみ。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"運行表 徒歩 枠 1人1行 到着 13:25 次回 太字 やめる 午前 午後 車名 運転者 左寄り 中央 列幅 休み 3分の2 連絡先一覧 電話 見切れ 住所 狭める trial143\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">【試験版のみ】運行表: 徒歩を車と同じ枠に1人1行(氏名・到着・次回)・午前午後/車名/運転者を中央に・休みは名前の約2/3／連絡先一覧: 電話番号の見切れを修正</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01 印刷の写真): 連絡先一覧の電話番号が見切れる→住所欄を狭めて。午前・午後、車名、運転者名がセルの左に寄って違和感→列幅を広げて。徒歩は「山田 芳二郎 13:25 火」の形で枠で囲み車名の箇所に「徒歩」、1列で、太字不要。休みの名前は利用者名の3分の2くらい。</span><span class=\"lb\">対処</span><span class=\"tx\">縦書きの箱は外側に writing-mode を付けていたため幅が文字幅に縮み左に寄っていた→外側は横幅いっぱいのflexで中央寄せ、縦書きは内側の文字だけに。午前午後の列17→24px、車名の列・運転者の細い欄を各+8〜9px。徒歩: 週内の最大人数で行数をそろえた枠を車の下に追加し、左端に「徒歩」(1〜2行の低い枠は横書き)、1人1行で氏名・時間(=クラスの開始=到着)・次回。下部の「徒歩（到着…）: 名前」の行は廃止。下部情報の文字は名前の約2/3(最小8px)。連絡先一覧: 電話の列幅を(文字−1)×7.2+10→×8.4+12に広げ、住所は残りの幅。検証(見本データ): 車2台で徒歩の枠と「徒歩」の横書き・縦書きラベルの中央寄せ・電話の全桁表示。eslint no-undef 0・vitest 16・Playwright 24。 試験版 trial143 のみ。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"運行表 車名 左端 1回 縦書き 運転者 細い欄 縦中横 数字 横向き 1号車 休み 小さく 車2台 名前 大きく 上限20 連絡先一覧 五十音 頭文字 セル結合 行 グレー 最大 最小 2枚目 送り ドラッグ 別割り当て trial142\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">【試験版のみ】運行表: 車名は左端に1回だけ・運転者は細い欄・縦書きの数字を縦向きに・休み等を小さく／連絡先一覧: 五十音の頭文字(結合)・1行おきのグレー・文字の上限下限と2枚目／送りの割り当てもドラッグで移動</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01 車2台の店舗の運行表の写真): 下の休み欄を縮めればもっと大きくなる？／車2台の店舗はより名前を大きく／「1号車」の数字が横向き／送りもドラッグしたい／シエンタ等の位置は変わらないのに毎曜日出すべき？(推奨=左端に1回)。続けて連絡先一覧: 待ち合わせ場所の欄を狭めて行と文字を大きく・下の余白がもったいない・ただし人数が少ない店舗で拡大しすぎないよう最大と最小を・最悪2枚目でも可・1行おきに薄いグレー・氏名の左に五十音の頭文字(同じ頭文字は結合、段や次ページに分かれたら改めて表示)。</span><span class=\"lb\">対処</span><span class=\"tx\">週の運行表: 車名を表の左端の列に1回だけ縦書き(各車の枠の高さは週内で共通にして各日の枠と揃える)。運転者はその週に入力がある場合だけ各日の車の枠の左に細い縦書き欄。縦書きは text-orientation:upright＋数字2桁までを縦中横。下部情報(休み・初回・その他・完成後に外れた・送り別)は本文の約0.72倍・最大12px(2026-09-16fの「本文と同じ大きさ」から変更。徒歩は乗車の方と同じ大きさのまま=9/30の指示)。文字は高さ・幅の両方で決め上限20px(22pxは人数が少ない店舗で大きすぎた)。徒歩の名前は途中で改行しない。連絡先一覧: 頭文字の列(カナ1文字目・濁点/小書きを外す・かな無しは「他」)をrowspanで結合し左右の段・ページごとに改めて表示。1行おきに薄いグレー(印刷で行の背景が消えるためセルに塗る)。文字11〜18px・1枚に収まれば下の余白を行へ配分(文字の約2.6倍まで)・11pxでも入らなければ高さで詰めて2枚目以降へ(ページ番号つき)。住所の欄は残りの幅。送迎表の画面: 送りの別割り当ての名前を長押し→送りの車・順番・徒歩・その他へドロップ(迎え⇔送り・別の日へは動かさない)。検証(見本データ): 車2台で「1号車」が縦向き・名前約17px、送りのドラッグで送りだけ車が変わり迎えは不変・迎えの枠へ落としても変化なし、連絡先90名は11pxで2枚・22名は18pxで1枚(頭文字の結合とグレーを確認)。eslint no-undef 0・vitest 16・Playwright 24。 試験版 trial142 のみ。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"運行表 印刷 A4横 車名 運転者 左 縦書き 名前 大きく 時間 距離 詰める 見出し行 廃止 徒歩 到着 開始 住所 東京都江東区 省略 地域密着型 利用者連絡先一覧 備考欄 廃止 trial141\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-10-01</span></div>\n      <p class=\"title\">【試験版のみ】運行表の印刷: 車名・運転者を左側に縦書きにして名前を大きく・名前と時間を近づける／徒歩は「到着 13:25」表示／住所は事業所と同じ都道府県・区市町村を省略／送迎表の備考欄を廃止</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-10-01 扇橋の運行表の写真): 地域密着型は事業所と同じ区の方しか来ないので「東京都江東区」は省いてよい。徒歩は（開始 13:25）より（到着 13:25）。送迎表の備考欄は不要。その分、利用者名と時間の距離を短くして名前を大きく、車名や運転者は上ではなく左側に置けばもっと大きくできるのでは。あわせて「他社の送迎ソフトは送りも入力できるか」の質問(回答のみ・実装なし)。</span><span class=\"lb\">対処</span><span class=\"tx\">週の運行表: 各車の見出し行(車名＋運転者、氏名/時間/次回)をやめ、車名(太字)と運転者を左の縦書き欄へ(枠の高さに合わせて文字を縮める)。文字の大きさは高さ(行数＋下部情報の折り返し見積り)と幅(その週の最長の名前＋時間＋次回＋車名欄が1日の列に収まる)で決め、上限を14→18pxに。氏名の欄は名前が収まる幅にして時間をすぐ右へ、余った幅は右端の空き(手書き用)。凡例に「左の縦書き=車名・運転者　時間=お迎え」。徒歩の表示を「開始」→「到着」(画面・週・日ごと印刷)。住所は表示専用の関数で、事業所と同じ都道府県＋区市町村を先頭から省く(別の区市町村はそのまま・Googleへは完全な住所)。備考は全店の送迎表で0件(件数のみ確認)だったため、入力欄と印刷の「備考:」行を削除。検証: 見本データで印刷プレビュー(1台4名までの週は名前約14px・1台8名の週も1枚に収まる)・連絡先一覧で「東京都江東区」「江東区」が省かれ「東京都墨田区…」は残る・備考欄なし・徒歩（到着 13:25）。eslint no-undef 0・vitest 16・Playwright 24。 試験版 trial141 のみ。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"社外資料\" data-text=\"エリア担当者 10月からの新機能 PDF A4縦 11ページ スクリーンショット 見本データ 送迎表 お迎え時間 提供記録 再測定 個別機能訓練 グループ 日誌 必須職員 兼務 減算 連絡帳 空印刷 モニタリング ケアマネ閲覧済 招待コード 各種設定 試験版 不具合修正 Q&amp;A oct-new-features\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">社外資料</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">エリア担当者向け資料「つむぎ 10月からの新機能」(A4縦11ページのPDF・9/29〜9/30の新機能と不具合修正・画面の写真つき)を作成</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): 昨日と今日で追加した機能を「10月からの新機能」としてエリア担当者に送るA4のPDFで。写真・スクリーンショットも付けてほしい。</span><span class=\"lb\">対処</span><span class=\"tx\">台帳の9/29・9/30の記事(79件)から最終仕様だけを抜き出し、全店(安定版)と試験版を分けて構成: 表紙・使い方・一覧 → 送迎表 → お迎え時間/災害速報/分析 → 提供記録入力(再測定・個別機能訓練の実施担当とグループ) → 日誌 → 連絡帳 → モニタリング → ご家族・ケアマネの登録/各種設定 → 試験版で確認中 → 不具合修正の表 → Q&amp;A。スクリーンショット16枚は安定版・試験版それぞれのデモ版(架空の利用者・職員・事業所名、ルート計算はモック)からPlaywrightで撮影し切り抜き。PDFは印刷用CSSでページからのはみ出し・画像の読み込み切れがないことを確認。置き場所: docs/マニュアル と public/manual の「つむぎ_10月からの新機能_エリア担当者向け.pdf」、元HTML public/oct-new-features.html、画像 public/manual/img/oct_*.jpg。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 お迎え時間 早すぎる 8:31 上野 移動時間 24分 2分 待ち合わせ場所 玄関前 Google 地名 取り違え 住所だけ 都道府県 補う 扇橋 0930s\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">送迎表: 待ち合わせ場所が入っている方の移動時間が大きく狂い、お迎え時間が早すぎる不具合を修正(Googleへは住所だけを送る・都道府県の無い住所は補う)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30 スクショ): タントの上野さんから施設までGoogleで2分、乗車に5分なのに、なぜ8:31なのか(8:52〜53になるはず)。調査(所要時間のみ): 本番のルート計算で 上野様→施設 は住所だけなら147秒(約2.5分)、アプリが送っていた「住所＋待ち合わせ場所(玄関前)」だと1,433秒(約24分)。Googleが「玄関前」を地名として別の場所を探していた。9:00−乗車5分−24分=8:31。扇橋では待ち合わせ場所の入った方が63名、都道府県の無い住所が4名。</span><span class=\"lb\">対処</span><span class=\"tx\">ルート・時間の自動計算でGoogleへ送る住所から待ち合わせ場所を外し(待ち合わせ場所は表示・印刷用)、都道府県の無い住所は事業所の都道府県(区市町村が無ければ区市町村も)を補う。店舗には待ち合わせ場所のある車の時間の計算を押し直すよう案内。検証(Playwright・送信内容を確認): 送る住所に「玄関前」が含まれない・「住吉1-1-1」→「東京都江東区住吉1-1-1」・「江東区住吉2-1-1」→「東京都江東区住吉2-1-1」。※試験版への取り込みで一度コンフリクトの印が残ったままのコミットを作ったが、公開前に気づいて解消・作り直した(公開版には影響なし)。 安定版 0930s／試験版 trial140。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 徒歩 色 オレンジ 振替 緑 見分け 自動計算 配車 既定 試験版のみ trial139\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">【試験版のみ】送迎表: 徒歩の枠の色をオレンジに(振替の緑と見分けやすく)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): 徒歩と振替の色が似ているので徒歩を他の色にしてほしい。</span><span class=\"lb\">対処</span><span class=\"tx\">徒歩の枠(画面・送り別の徒歩表示)を緑→オレンジ(振替=緑・初回=水色・その他=紫と区別)。検証(Playwright): 徒歩の枠の背景・見出しがオレンジ。 試験版 trial139 のみ。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 出発時刻 廃止 到着目標 逆算 戻す 大幅に遅れる 0930r\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">送迎表: 出発時刻の設定を廃止し、お迎え時間は到着目標から逆算する方式に戻す(0930qの「出発から順に計算」を取りやめ)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): 出発時間を設定すると到着目標から時間が大幅に遅れてしまうため、出発時刻は設定しない(廃止)でお願い。</span><span class=\"lb\">対処</span><span class=\"tx\">送迎表の設定から「午前/午後の出発時刻」を削除(保存時に空にする)。計算は到着目標から逆算(お迎え時間=家に着く時間・次の方=前の方＋乗車にかかる時間＋移動)のみ。交通予測に使う時刻は到着目標の45分前。遅れの通知も削除。検証(Playwright・固定の移動時間): 出発8:30が保存されていても 8:27/8:34/8:40(9:00着)・設定画面に出発時刻なし・試験版の自動計算も同じ。 安定版 0930r／試験版 trial138。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 自動計算 配車 既定 チェックなし 時間のみ 試験版のみ trial137\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">【試験版のみ】送迎表の「自動計算」: 「配車」は最初はチェックを外した状態に(時間だけ計算が既定)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): 自動計算で配車は基本的に最初しか使わないので、デフォルトではチェックを外すようにして。</span><span class=\"lb\">対処</span><span class=\"tx\">自動計算の選択画面を開いたときの既定を「配車=なし・時間=あり」に変更し、説明文も「配車は最初に組むとき用」に。検証(Playwright): 開いた直後の状態が 配車=外れ・時間=入り。 試験版 trial137 のみ。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 お迎え時間 自動計算 7時台 12時台 出発時刻 到着目標 逆算 順算 ピンポン 乗車にかかる時間 遅れ 通知 扇橋 0930q\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">送迎表: お迎え時間の自動計算が出発時刻より前(午前7時台・午後12時台など)になる不具合を修正(出発時刻があれば出発から順に計算・到着目標を過ぎる車は通知)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30 スクショ): 乗車までにかかる時間は、お迎えしてから乗車までの時間。お迎え時間はピンポンの時間にして、次の利用者は乗車までの時間を含めた時間を表示してほしい。午前は7時台・午後は12時台にならないように配車しているのに、7:55・12:47 などが出ておかしい。調査: 扇橋の設定は 出発8:30/到着目標9:00(午後13:00/13:25)。計算は「到着目標から逆算」だけで、出発時刻は「早く出る必要があります」の案内にしか使っておらず、長いルートでは出発前のお迎え時間が出ていた(お迎え時間=家に着く時間・次の方=前＋乗車時間＋移動 という考え方自体は従来どおり)。</span><span class=\"lb\">対処</span><span class=\"tx\">_autoRouteCore: 出発時刻の設定がある店舗は、1人目=出発＋施設→1人目の移動、次の方=前の方＋その方の乗車にかかる時間＋移動、で順に計算(お迎え時間=家に着く時間)。施設到着が到着目標を過ぎる車は「出発8:30で回ると施設到着は9:13の見込みで、到着目標(9:00)より13分遅れます」と通知。出発時刻の設定が無い店舗は従来どおり到着目標から逆算。設定画面の説明も更新。既存の時間は自動では変えない(時間の計算を押し直すと反映)。検証(Playwright・Googleの移動時間は固定値に差し替え: 施設→1人目10分・人と人5分・最後→施設15分・乗車2/1/5分): 出発8:30→8:40/8:47/8:53と13分遅れの通知・出発なし→8:27/8:34/8:40(9:00着)・試験版の自動計算でも同じ。 安定版 0930q／試験版 trial136。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌 兼務 印刷 担当職員欄 記載 待ち合わせ場所 マンション入口外 試験版のみ trial135\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">【試験版のみ】日誌で兼務した場合は日誌本体(印刷)の担当職員欄にも記載／待ち合わせ場所の「マンション入口」を「マンション入口外」に</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): 日誌で兼務した場合は日誌に残しておいた方がいいかも。マンション入口外にした方がわかりやすいかな。</span><span class=\"lb\">対処</span><span class=\"tx\">日誌の担当職員欄の下に「兼務: 氏名（役職）が○○を兼務」(担当職員に選ばれている人の兼務だけ・印刷にも出る)。編集画面の注記も「印刷にも記載」に。待ち合わせ場所の選択肢を「マンション入口外」にし、旧表記で保存済みの値は画面・印刷とも新表記で表示。検証(Playwright): 日誌に「兼務: 佐藤 健一（管理者）が介護職員を兼務」・旧表記の方の選択欄が「マンション入口外」。 試験版 trial135 のみ。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳 体温 36. 35.9 午前 午後 まとめ値 午前優先 来た時間帯 振替 _cbSlot _PLAIN_VITALS _fieldTs 印刷 ずれ 脈拍 はみ出し グリッド 扇橋 浅野 0930p\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">連絡帳: 午後の方の体温・血圧に午前の値(入力途中の「36.」など)が出る不具合を修正／バイタル欄で1行目が右にずれ脈拍が枠からはみ出す印刷のずれを修正</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30 スクショ): 連絡帳の印刷がずれている。浅野さんの体温が35.9なのに連絡帳は36.になっている。調査(ID・一致の有無のみ): 9/30の記録は 午前=「36.」(時刻なしの古い値)・午後=35.9(時刻あり)。基本利用は水曜午後。旧来のまとめ値(temp 等)は同期のたびに「午前が空でなければ午前」で作り直しており、午後の方に午前の入力途中の値が出ていた(扇橋の9月で午前・午後の両方に値がある記録は12件)。</span><span class=\"lb\">対処</span><span class=\"tx\">①連絡帳は来た時間帯(振替・臨時の furikaeAmpm → 基本利用の時間帯)の値を表示(体温・開始/終了の血圧/脈拍)。時間帯が分からない時は従来のまとめ値。②同期でのまとめ値の作り直しは、両方に値がある時 振替の時間帯 → 後から入力した方(_fieldTs が新しい方) → 午前 の順に(分析・ご家族画面・印刷にも効く)。③バイタル欄の1行目と2行目を同じ列幅のグリッド(体温｜余白｜開始時/終了時｜血圧｜脈拍｜値)に(従来は空白文字で位置合わせしており約20pxずれ、1行目が枠を5pxはみ出していた)。検証(Playwright): 午前「36.」午後35.9の午後利用者→連絡帳35.9、2行の各列のx座標が一致・右端が枠内、血圧の表示3方式(開始＋終了/開始のみ/旧方式)も従来どおり。 安定版 0930p／試験版 trial135。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"自動計算 チェックボックス 大きく 配車 時間 両方 独立 配車のみ 時間維持 曜日 縦 試験版のみ trial134\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">【試験版のみ】送迎表の「自動計算」: チェックを大きく・配車と時間をそれぞれ選べるように(配車だけ=今の時間はそのまま)・曜日を縦に並べる</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30 スクショ): 日付は縦に表示。チェックボックスを大きくして。両方いっぺんに行いたい時もあるため両方チェックできるようにして(配車にチェックすると時間が固定で外せなかった)。</span><span class=\"lb\">対処</span><span class=\"tx\">チェックを約26pxに・配車/時間を独立に(既定は両方)。配車だけのときは組み直し後に各利用者の元の時間を戻す。曜日は1日1行のボタン(チェック印つき)。画面が縦長になるため選択画面は画面内でスクロール。検証(Playwright): 両方→配車のみ→時間のみ→両方 が切り替わる・曜日が縦並び。 試験版 trial134 のみ。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"待ち合わせ場所 選択式 自宅前 玄関前 マンション入口 エントランス ロビー その他 自由記述 PickupPlaceField 印刷 徒歩 その他 休み 行分け 太字 開始時間 リマインド 1週間後 毎日 試験版のみ trial133\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">【試験版のみ】送迎の待ち合わせ場所を選択式に(その他は自由記述)／印刷の徒歩・その他・休みを行で分け、徒歩は乗車の方と同じ大きさ・名前太字・クラスの開始時間つき／未完成のお知らせを「今日から1週間後の日を含む週」で毎日判定</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30 スクショ): 待ち合わせ場所を自宅前・玄関前・マンション入口・エントランス・ロビー・その他(自由記述)で選択式に。徒歩はそのクラスの開始時間を記載する。印刷時は徒歩とその他・休みは改行して分け、徒歩の文字の大きさと太さは通所される利用者と同じ・名前は太字。未完成の表示は木〜日ではなく、その日から1週間後の送迎表が完成されていなかったら。</span><span class=\"lb\">対処</span><span class=\"tx\">共通部品 PickupPlaceField(選択+その他の自由記述・保存は従来どおり文字列 pickupPlace・既存の入力は「その他」として表示)を利用者マスタと送迎表の名前タップ画面に。印刷(週間・日ごと)の下部を1項目1行に、徒歩は乗車行と同じ文字サイズ・太さ・名前を太字、「徒歩（開始 9:15）」(各種設定の提供時間の開始・画面の徒歩欄も同じ)。tpNextWeekReminder を曜日条件なし・今日+7日を含む週の完成で判定に変更(ホーム・送迎表の文言も「1週間後（M/D）の週」)。検証(Playwright・時計9/30水): ホームに案内・画面の「徒歩（開始 9:15）」・選択肢6つ・その他「裏の駐車場」で保存・週間印刷で徒歩/その他/初回/休みが別行。 試験版 trial133 のみ。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 自動計算 配車 時間 チェック 曜日 午前 午後 選択 日付 固定 中央揃え 詰める 午前午後 縦 左 枠 分離 完成 未完成 注意 来週 リマインド ホーム 予定 確定 お迎え時間 モニタリング表 A4横 試験版のみ trial130\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">【試験版のみ】送迎表の画面整理(自動計算の選択式・日付を詰めて固定/中央揃え・午前午後を左に縦表示/枠分離・「完成」ボタンと未完成の注意・来週未完成の案内・各コマの計算ボタン/この日を印刷を廃止)／お迎え時間の「予定(確定前)/確定」表示とホームのリマインド／ケアマネ画面のモニタリング表をA4横に</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): 次回のお迎え時間は提案(2週分作成+来週未完成の注意+予定/確定表示)で進めて。ホームにもお知らせを。日付を固定して隙間なく。週間の配車＋時間計算を自動計算に(配車/時間をチェック・曜日や午前午後も選択)、各コマの計算ボタンとこの日を印刷は削除、日付は中央、午前と午後の枠を離す、午前午後は左に縦まとめ、完成ボタンと未完成の注意。ケアマネ用モニタリング画面をA4横サイズに。</span><span class=\"lb\">対処</span><span class=\"tx\">送迎表: 上部「自動計算」→選択画面(配車[時間も計算]/時間のみ・曜日・午前午後)でまとめて計算(_autoRouteCore)。日付の行は上の帯に隙間なく固定・中央揃え。表は左端に午前/午後の縦見出し列・午前と午後を別の枠に。「この週を完成にする」→「完成」/「完成済」、未完成の週は「この週は完成されていません」、木〜日で来週が未完成なら「来週（M/D〜）が未完成」(押すと来週へ)。共通関数 tpWeekFinalAt/tpNextWeekReminder/tpStoreUsesTransport(直近4週に送迎表の保存がある店舗のみ)。ホームに「来週の送迎表がまだ完成していません」(送迎表を開く=来週へ)。ご家族・ケアマネ・分析個人のお迎え時間に、その日の送迎表が完成なら「確定」・未完成は「予定（確定前）」。モニタリング表: プレビューは1123×794px(A4横)の用紙・拡大は297mm幅。検証(Playwright・時計を10/1木に固定): ホームの案内→来週を開く・旧ボタン無し・完成ボタン/未完成表示・午前午後の縦見出し・日付中央/帯との隙間0/固定・自動計算の選択画面(チェック2・曜日6・午前午後2)・確定/予定バッジ・拡大の用紙幅1123px。 試験版 trial130 のみ。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"フェイスシート 緊急連絡先 削除ボタン アカウント管理 登録者 削除 緊急連絡先からも削除 確認 contactRemovalPatch 代表 繰り上げ 墓石 試験版のみ trial132\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">【試験版のみ】フェイスシートから緊急連絡先を削除できるように／アカウント管理で登録者を削除するとき、フェイスシートの緊急連絡先からも消すか確認</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): フェイスシートから削除できるようにしてほしい。アカウント管理から登録者を削除したときに、フェイスシートの緊急連絡先からも消すかどうか問われてほしい。</span><span class=\"lb\">対処</span><span class=\"tx\">フェイスシートの連絡先ごとに「削除」(確認つき・保存で基本情報からも削除・墓石あり)。共通関数 contactRemovalPatch(代表を消したら次の方を代表へ繰り上げ・同名の重複も外す・墓石・ケアマネ/本人は対象外)を追加し、アカウント削除時に「登録したアカウント」か「同じ氏名」の連絡先があれば「緊急連絡先からも削除しますか？」→OKで同時に削除。検証(Playwright): 家族 二郎のアカウント削除→確認→緊急連絡先から二郎が消え墓石1件／フェイスシートで代表を削除→保存→代表・重複とも消える。 試験版 trial132 のみ。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"緊急連絡先 重複 被っている 代表家族 同名 まとめて表示 空欄補完 getAllContacts getAllContactsRaw 墓石 フェイスシート 0930o\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">緊急連絡先で同じ方が2回表示される不具合を修正(氏名で1件にまとめて表示・空欄は補完)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): 緊急連絡先が被ってしまっている。全店の点検(件数・パターンのみ): 1店1名で、代表家族と同じ氏名の方が緊急連絡先にも入り、メールだけ違っていた(端末ごとに内容が少し違うと同期で別の連絡先として両方残る)。</span><span class=\"lb\">対処</span><span class=\"tx\">getAllContacts(基本情報・フェイスシート・ご家族画面・印刷の共通)で、氏名(空白・全角半角を無視)が同じ連絡先を1件にまとめ、空欄の項目は後の方の値で補う。まとめる前の一覧 getAllContactsRaw を用意し、フェイスシート保存の墓石(_deletedEC)はそこから作る(重複の片方が他端末から復活しないように)。検証(Playwright): 代表家族と同名(全角空白・メール違い)の連絡先 → フェイスシートは2件(家族 一子[メール補完]・家族 二郎)。 安定版 0930o／試験版 trial132。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 前週コピー 振替 コピーされる お休み 除外 _attendees 未割当 0930n\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">送迎表: 「前週コピー」で前の週に振替で来た方までコピーされる不具合を修正(コピー先の日・時間帯に来る方だけを残す)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): 送迎表で前週のコピーをすると振替をした人も反映されてしまうので、振替の人は反映されないようにして。</span><span class=\"lb\">対処</span><span class=\"tx\">前週コピーで、コピー先の日・時間帯の来所者(_attendees: 基本曜日・月間スケジュール・提供記録)に含まれない方を車・徒歩・その他・未割当・送り別割り当てから外す(この週にお休みの方も外れて「休み」へ・この週に振替で来る方は未割当に補充)。確認文と完了メッセージに除外人数。検証(Playwright): 前週(月曜AM)に基本利用の方と振替の方 → 修正前=両方コピー／修正後=基本利用の方だけ。 安定版 0930n／試験版 trial131。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 日付 常に表示 スクロール 固定 sticky 横スクロール 連動 この日を印刷 試験版のみ trial129\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">【試験版のみ】送迎表: 下へスクロールしても日付(と「この日を印刷」)を常に表示</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): 下にスクロールしても送迎表の日付は常に表示しておいてほしい。日付は日ごとの列の1行目で、表全体が横スクロールの枠の中にあるため、単純な固定では画面上部に残らなかった。</span><span class=\"lb\">対処</span><span class=\"tx\">日付の行を、週切替の帯と同じ上部の固定エリアへ移し、表の横スクロールに合わせて日付の行も動かす(列幅は表と同じ指定)。検証(Playwright): 1500px/1024px で下へスクロールしても日付の位置が変わらない・横に200pxスクロールすると日付も200px。 試験版 trial129 のみ。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 試験版 表示 削除 バッジ 0930m\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">送迎表の上部に残っていた「試験版」の表示を削除</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">安定版へ移行(0930k)した後も、送迎表の上部に「試験版」のバッジが出ていた(画面確認で発見)。</span><span class=\"lb\">対処</span><span class=\"tx\">バッジを削除(他に画面に出る「試験版」表示は無いことを確認)。 安定版 0930m／試験版 trial129。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"モニタリング\" data-text=\"モニタリング表 実施日 確定した日 下書きの日 implDate 9/7 ケアマネ画面 日付 0930l\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">モニタリング</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">モニタリング表の「実施日」を確定した日にする(従来は下書きを作った日のまま)／ケアマネ画面のモニタリング欄の日付も実施日を表示</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30 スクショ): モニタリングで実施日が9/7になっているが、ここは確定した日にして。</span><span class=\"lb\">対処</span><span class=\"tx\">確定(未確定→確定)のときに sheet.implDate をその日に更新。確定済みの表は、解除→再確定で更新される(過去の確定日は記録が無いため自動では変えない)。分析個人/ケアマネ画面の見出しの日付を「実施日 年/月/日」に。検証(Playwright): 確定→implDate が今日。 安定版 0930l／試験版 trial129。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 振替 提供記録 月間スケジュール 印なし 表示されない 扇橋 9/28 午後 臨時 欠席 _attendees _recByDay furikaeAmpm 未割当 0930l\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">送迎表: サービス提供記録で振替・臨時にした方が、月間スケジュールに印が無いと送迎表に出ない不具合を修正(提供記録の欠席・休止も反映)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): 28日の午後の細野さんが振り替えているのに送迎表に反映されていない。調査(ID・状態のみ): 提供記録には 9/28「振替・午後」があるが、月間スケジュールの28日に印が無かった。送迎表は来る人を月間スケジュールと基本曜日だけで判定していた。</span><span class=\"lb\">対処</span><span class=\"tx\">送迎表に日付→提供記録の索引を追加。月間スケジュールに印が無い時は、当日の記録の振替/臨時をその時間帯(furikaeAmpm→特記の午前/午後→午前=日誌と同じ)に出し、欠席/休止/休業の記録があれば基本の時間帯から外して「休み」に出す(印がある時は従来どおり印を優先)。保存済みの日は既存の仕組みで「未割当」に追加。検証(Playwright): 基本利用日でない月曜に記録だけの振替(午後)→送迎表に出る(記録を外すと出ない)。 安定版 0930l／試験版 trial129。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"安定版 移行 送迎表 運行表 未割当プルダウン 完成 赤丸 送迎表取込 お迎え時間が変更されました 日誌ボタン 個別機能訓練 グループ リセット モニタリング 即時反映 ケアマネ閲覧済 FAX省略 家族・ケアマネ画面プレビュー 登録メール 招待コード 総当たり 0930k\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">安定版へ移行(0930k): 送迎表一式・お迎え時間の変更表示・日誌ボタンの並び・個別機能訓練グループのリセット・モニタリングの即時反映/表表示/ケアマネへのお知らせ・ケアマネ閲覧済/FAX省略・家族/ケアマネ画面プレビュー・登録メールの反映・招待コードの総当たり対策</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): 安定版に移行して(今夜予定の送迎表一式・未割当プルダウン・グループのリセット・お迎え時間の変更表示)。続けて: 招待コード対策・メール反映・モニタリング・閲覧済み/プレビューも安定版へ。</span><span class=\"lb\">対処</span><span class=\"tx\">試験版だけにあった変更は52件(うち送迎表が約45件)で、試験版と安定版の差分は7ファイル(App.jsx・supabase.js・api/family-invite.js・api/route-plan.js・docs/sql/family_invites_rls.sql・e2e/transport.spec.js・update-notes)だけ・試験版専用の切り替えは無いことを確認し、安定版のコードを試験版と同一にした(安定版のお知らせは機能ごとの9件に要約)。検査: no-undef 0・vitest 16・Playwright 24(送迎表の2件が加わった)・画面確認7本(日誌の車グレーアウト・モニタリング→ケアマネ・プレビュー切替・ケアマネのメール反映・新端末登録・前任ケアマネ/お知らせ未読・日誌ボタン順)全て合格。本番で /api/family-invite(未ログイン=401)・/api/route-plan(地図キー設定済み)・トップページ応答を確認。残作業: 全店の端末が0930k以降になったら docs/sql/family_invites_rls.sql を本部で実行。 安定版 0930k(試験版とコード同一)。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌 上部 ボタン 二重 迎え 送り 担当者追加 プレビュー 保存 送迎表取込 並び順 試験版 trial128\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">【試験版】日誌の上部で「迎え・送り・担当者追加・プレビュー・保存」が2組表示されていた不具合を修正し、「担当者追加 → 送迎表取込 → 迎え → 送り → プレビュー → 保存」の順に</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30 スクショ): 日誌のプレビューと保存が被っている。迎え・送り・担当者追加も被っている。順番は担当者追加、送迎表取込、迎え、送り、プレビュー、保存に。原因: 9/29 に安定版を試験版へ取り込んだ際(trial97)、ボタン行の結合で安定版側の1組と試験版側の1組が両方残っていた(安定版は1組のみ)。</span><span class=\"lb\">対処</span><span class=\"tx\">1組目を削除し、残りを指定の順に並べ替え(プレビュー・保存は右寄せのまま・狭い画面では次の行へ)。検証(Playwright): 1400px/1024px とも 担当者追加 > 送迎表取込 > 迎え > 送り > プレビュー > 保存 の1組。安定版は送迎表取込が無いため、今夜の送迎表の安定版移行時にこの並びで入れる。 試験版 trial128 のみ。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌 送り 出発 送迎者 グレーアウト 未使用の車 未完成 欠席 休止 割り当て残り 扇橋 9/29 午後 タント diaryCarUsed diaryAbsentPids 0930j\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">日誌: 欠席・休止の方に車の割り当てが残っていると、送りに誰も乗らない車がグレーアウトされず、送迎者・出発時間が未入力で「未完成」になる不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30 スクショ): 扇橋店 9/29午後の日誌で、送りの出発・担当がどこも選択されていない車(タント)が入力できるようになっていて、その影響で日誌が未完成。以前は送りで選択されていない車はグレーアウトだったはず。調査(IDと状態のみ): その日 欠席の利用者1名に「迎え=シエンタ・送り=タント」の割り当てが残っていた。表の迎え/送り欄は欠席の方を「—」にしていたが、車を使うかの判定(グレーアウト・未完成バッジ・ホーム/カレンダーの未完成)は全員の割り当てを数えていた。</span><span class=\"lb\">対処</span><span class=\"tx\">共通ヘルパー diaryCarUsed / diaryAbsentPids を追加。日誌画面は当日の一覧で送迎する方(欠席・休業・休止以外)の割り当てだけで車の使用を判定し、グレーアウト・未完成バッジ(送迎者・到着/出発時間)に使う。ホーム・カレンダーの未完成判定(diaryPendingItems)は提供記録で当日 欠席/休止/休業 の方の割り当てを除いて判定(ID化以降の日誌)。表の迎え/送り欄は休止の方も「—」。検証(Playwright): 欠席の方にだけ2号車を割り当てた場面を作り、修正前=2号車の時刻が入力でき未完成に「迎えの送迎者・送りの送迎者・到着時間・出発時間」、修正後=2号車はグレーアウト(—)でそれらは未完成に出ない。 安定版 0930j／試験版 trial128。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"家族画面プレビュー ケアマネ画面プレビュー 切替 ご家族 ケアマネ お知らせ 対象 audience モニタリング表 アカウント管理 別タブ ログイン画面 プレビューへ移動 試験版のみ trial127\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">【試験版のみ】「家族画面プレビュー」を「家族・ケアマネ画面プレビュー」に(ご家族/ケアマネの切り替え)／利用者マスタのアカウント管理の「家族画面のプレビューを開く（別タブ）」を「ご家族の画面を見る」「ケアマネの画面を見る」に</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): 家族画面プレビューにケアマネ画面プレビューも一緒にあるといい。そもそもプレビューは必要か。調査: お知らせのプレビューは対象(ご家族/ケアマネ)で絞っておらず、ケアマネ向けのお知らせもご家族の画面に出るように見えていた。アカウント管理の「家族画面のプレビューを開く（別タブ）」は実際にはログイン画面を開くだけだった。</span><span class=\"lb\">対処</span><span class=\"tx\">FamilyPreviewTab に見る人の切り替え(ご家族/ケアマネ)を追加。お知らせは audience で絞り、通所記録はケアマネならケアマネ画面(モニタリング表あり)、ご家族ならモニタリング欄なし。アカウント管理のボタンは sessionStorage(tsumugiPreviewJump)で利用者と見る人を渡し、お知らせ・閲覧管理のプレビューを直接開く。検証(Playwright): アカウント管理→ケアマネの画面を見る→ケアマネ向けお知らせ(モニタリング)・モニタリング表あり／ご家族に切替→表なし・モニタリングのお知らせなし。 試験版 trial127 のみ(安定版は未反映)。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"モニタリング\" data-text=\"ケアマネ閲覧済 FAX 省略 閲覧記録 docUpdates monView IntersectionObserver 拡大 担当ケアマネへFAX 自動FAX 確認 monConfirmedAt 試験版のみ trial127\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">モニタリング</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">【試験版のみ】ケアマネがつむぎでモニタリング表を見たら、モニタリング画面に「ケアマネ閲覧済 月/日 時:分」を表示／「担当ケアマネへFAX」「自動FAX送信」で閲覧済みの方を省くか確認</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): (FAXの手間を減らすため)ファックス閲覧済みをお願いします。</span><span class=\"lb\">対処</span><span class=\"tx\">ケアマネ画面のモニタリング表(MonSheetPreview)が画面に半分以上1.5秒表示されるか拡大されたら、事業所へ閲覧記録を送る(supabaseAppendDocUpdate・kind=monView・readOffice=true=新着にはしない・id=記録id+確定時刻+アカウントで1回だけ)。プレビュー・その他関係者・事業所の画面では送らない。supabaseAppendDocUpdate は kind/monRecId/period と readOffice 指定を通すよう拡張。確定のたびに monConfirmedAt を記録し、閲覧はそれ以降のものだけ有効(解除→修正→再確定なら見直すまで未閲覧)。モニタリング画面の確定ボタン下に「ケアマネ閲覧済」、FAX2種は閲覧済みがいれば「省きますか？(OK=省く)」、全員閲覧済みなら送らない。閲覧記録は支援経過にも残る。検証(Playwright): 確定→閲覧記録あり→「ケアマネ閲覧済 9/30 16:02」表示。 試験版 trial127 のみ(安定版は未反映)。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"災害速報 津波 津波予報 若干の海面変動 与那国島近海 全店 避難 地域 市区町村 予報区 地震 震度4 警報 伊豆諸島 八丈町 area.json class20 alerts 0930i\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">災害速報: 事業所の地域に関係のない速報(遠い地域の「津波予報(若干の海面変動)」・他地域の地震・都内の島しょ部の警報など)が全店に出ていた不具合を修正(市区町村・沿岸の予報区で絞り込み)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30 14時過ぎ): 緊急災害速報で津波のやつが来たが、ちゃんとその地域の住所にあった速報になっているか。調査: 14:00 与那国島近海の地震(M6.0・最大震度3)で気象庁が「津波予報（若干の海面変動）」を宮古島・八重山地方に発表。api/alerts.js は津波一覧を地域で絞らず、被害の心配がない予報まで全店に「高い場所へ避難してください」と表示していた。地震も全国どこでも震度5弱以上なら全店に表示、警報は都道府県内のどこか(東京都なら伊豆諸島)に出ていれば表示で、警報の地域名も空だった。</span><span class=\"lb\">対処</span><span class=\"tx\">api/alerts.js: 事業所住所(addr)を受け取り、気象庁 area.json で市区町村(class20)を特定(住所の先頭一致→郡名・島名付き住所→政令市の区域)。①津波: 最新報ごとに詳細JSONを読み、事業所の都道府県の沿岸の予報区に「津波注意報」以上がある時だけ(予報・解除は出さない)。東京都は23区=東京湾内湾、島しょ=伊豆諸島/小笠原、多摩=対象外。予報区ごとに種類を分けて表示。②地震: 事業所の市区町村で震度4以上(特定できない時は都道府県内で震度4以上・5弱以上)。③警報: 事業所の市区町村に発表中のものだけ・地域名を表示。アプリは住所も送る。検証: 実データ(江東区・八丈町・横浜市港北区・与那国町・大阪市・さいたま市)で速報0件=今回の津波予報は出ない／模擬データで 江東区=震度4と東京湾内湾の津波注意報のみ・八丈町=伊豆諸島の津波警報と町の大雨警報・大阪/埼玉=なし。本番で江東区と判定され0件を確認。 安定版 0930i／試験版 trial127。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"モニタリング\" data-text=\"モニタリング 確定 即時反映 月末18時 廃止 ケアマネ 通所記録 モニタリング表 プレビュー 用紙 PDF 印刷 拡大 お知らせ 配信 作成しました 更新しました 取り下げ 墓石 その他関係者 要約 monitoringReflectable MonSheetPreview 試験版のみ trial126\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">モニタリング</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">【試験版のみ】モニタリングを「確定」した時点で分析個人・ケアマネ画面に反映(従来は対象月最終日18時以降)／ケアマネにはFAXと同じモニタリング表を用紙の見た目のまま表示(タップで拡大・印刷・PDF保存)／確定で担当ケアマネのお知らせに「モニタリング（○月）を作成しました」を配信・解除で取り下げ</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): 確定したらその時点でその月のものが反映されるようにしたい。今は要約をモニタリング欄に出しているが、FAXの手間を減らせるよう通所記録にモニタリングのデータをPDFの状態でプレビュー表示したい。確定して登録されたらお知らせにも「モニタリングが作成されました、ご確認ください」を送るとよい。(経緯: 2026-08 店舗要望で「確定しても対象月内は出さず月末最終日18時以降に反映」にしていた)</span><span class=\"lb\">対処</span><span class=\"tx\">①<code>monitoringReflectable</code> を「確定済みなら反映」に変更。②<code>MonSheetPreview</code> を新設: <code>buildMonitoringTableHtml</code>(FAX・個人ファイルの印刷と同じ表)を幅1000pxの用紙として描き、画面幅に合わせて縮小(ResizeObserver)。タップで画面内に重ねて拡大(横向きレイアウトのまま・スマホは横スクロール)・印刷/PDF保存(A4横)。ケアマネ(続柄=ケアマネージャー)と事業所の分析個人に表示、その他関係者は従来どおり要約のみ、ご本人・ご家族には従来どおり非表示。③確定時(upsertSheet で未確定→確定)に個別お知らせ(audience=caremanager・「モニタリング表を見る」ボタンで通所記録のモニタリング欄へ移動)を追加し、記録に monAnnId/monNotifiedAt を控える。解除時はお知らせを削除して墓石を記録。お知らせidは確定ごとに新しくし、再確定は「更新しました」。確定/解除のメッセージにもケアマネへの反映を明記。検証(Playwright): 職員が確定→記録確定・お知らせ1件(ケアマネ宛)、解除→お知らせ0件・墓石1件、再確定→「更新しました」、ケアマネ画面=お知らせ表示→ボタンで表のプレビュー表示→拡大表示、その他関係者=お知らせなし・表なし(要約)。 試験版 trial126 のみ(安定版は未反映)。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"フェイスシート 緊急連絡先 メール 続柄 登録 自動反映 ケアマネ事業所・担当者 メール欄 担当者マスタ 空欄のみ _emailTs 同期 unionBy 表記ゆれ 全角空白 重複 自動補完 試験版のみ trial125\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">【試験版のみ】ご家族が登録したメールをフェイスシートの連絡先に表示(入力・表示・印刷)／ケアマネが登録したメールを「ケアマネ事業所・担当者」のメール欄へ自動反映(空欄のときだけ)・登録済みのケアマネもスタッフ端末が自動補完</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-26): 登録してもらったメールアドレスや続柄が自動でフェイスシートや、ケアマネの方だとケアマネ事業所担当者のメールアドレスに登録されるとよりいい。(2026-09-30) 試験版で導入して。調査: 続柄と電話はフェイスシートに出ていたが、メールは入力・表示・印刷のどこにも無かった。ケアマネは担当者マスタに同じ人がいると(紙・メールで招待した人は必ず該当)何も書き込まず、登録メールがマスタに入らなかった。</span><span class=\"lb\">対処</span><span class=\"tx\">①フェイスシートの連絡先にメール欄(編集は代表・追加連絡先ごと、表示/印刷は「メール:」)。保存は従来どおり基本情報(familyEmail/emergencyContacts)へ書き戻し。②ケアマネ登録: 担当者マスタを空白の違い(全角/半角)を無視して照合し、同じ人のメールが空なら登録メールを入れる(重複追加しない)。クラウド側の統合(supabaseMergePatientFromFamily)も同じ照合で補う。③スタッフ端末の自動付け替えで担当者を特定できたとき、マスタのメールが空なら登録アカウントのメールで補う(<code>supabaseFillCareManagerEmails</code>・CAS)。④同期: 同じ担当者は従来どおり端末側優先だが、メールだけは書いた時刻 <code>_emailTs</code> の新しい方を採る(画面でメールを変更・削除したときも persistCm で時刻を刻む)。古い端末の保存で自動反映したメールが消えない。検証: 抜き出した実コードでマージ5場面(古い端末×登録メール=残る/新しい変更=端末/新しい削除=消える/時刻なし=従来/別人=両方)合格、Playwright でマスタ「架空　花子」(メール空)にケアマネ登録→1名のままメール入り・時刻あり、フェイスシートに代表家族のメールが表示。 試験版 trial125 のみ(安定版は未反映)。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"お迎え時間が変更されました 送迎表 完成 _final 差分 乗車時間 徒歩 車 変更前 変更後 ご家族 ケアマネ 分析個人 本日のお迎え 次回のお迎え 試験版のみ trial124\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">【試験版のみ】送迎表を「完成」にした後でお迎え時間・送迎方法(車/徒歩)が変わったら、ご家族・ケアマネ・ご本人・分析個人の「本日／次回のお迎え時間」に赤字で「お迎え時間が変更されました（13時10分 → 13時30分）」を表示</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 送迎表を安定版に導入したらそこを元に反映させる。確定後の変更はお迎え時間が変更されました的な文も必要。(2026-09-30) 送迎表の安定版導入と「お迎え時間が変更されました」表示は今日の夜に安定版へ反映予定。</span><span class=\"lb\">対処</span><span class=\"tx\">分析個人(ご家族画面と共通)に <code>_pickupChgOf</code> を追加: 送迎表の完成時の控え(<code>_final</code>)と今の配置を比べ、この方の乗車時間(8:30/8:--/8時30分を同じ表記にそろえて比較)または車⇔徒歩が変わっていれば {変更前, 変更後}。乗車順だけの変更・完成後の追加・送迎表から外れた場合は出さない。表示は「お迎え時間が変更されました（前 → 後）」「送迎が変更されました（13時10分のお迎え → 徒歩でご来所）」。時刻は途中で改行しない。検証(Playwright): 13:10→13:30、13:10→徒歩、完成なし(表示なし)。 試験版 trial124 のみ(今夜の安定版反映予定に含む)。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"お迎え時間 分 未設定 空欄 8:-- 13時 頃 誤解 13時　分 送迎表 _pickupOf ご家族 ケアマネ 分析個人 0930h\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">送迎表で「分」が空欄(13:--)のお迎え時間が、ご家族・ケアマネ・分析個人で「13時 頃」と表示される不具合を修正(「13時　分」＋前日・当日は「分が未設定です」の案内)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー決定(2026-09-29): 「13時　分」は「13時」と表示すると13時ちょうどと勘違いされるため「13時　分」のままにする。調査で、送迎表(乗車時間)から読む経路だけ分が空欄のとき「13時」になっていたことが判明(安定版も試験版の送迎表データを読むため両方に影響)。</span><span class=\"lb\">対処</span><span class=\"tx\"><code>_pickupOf</code> の送迎表経路で 8:-- を「8時　分」に変換(従来は「8時」)。これで <code>_minUnset</code> が働き、前日・当日は「お迎え時間の『分』が未設定です。事業所にお問い合わせください」を表示。検証(Playwright): 送迎表に 13:-- → 次回のお迎え「13時　分 頃」＋案内。 安定版 0930h／試験版 trial124。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"セキュリティ\" data-text=\"招待コード 総当たり 対策 サーバー api family-invite 回数制限 IP 15分 24時間 全体停止 偽造 トークン フォールバック 廃止 family_invites RLS 閉鎖 SQL 職員トークン ご家族アカウント 紙の招待 beforeprint 試験版のみ trial123\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">セキュリティ</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">【試験版のみ】招待コードの総当たり対策: 照合・登録をサーバー(/api/family-invite)で行い、同じ回線で15分に5回失敗→15分停止・1日20回→24時間停止・全体で1時間150回失敗→一時停止／URLの中身(トークン)から招待を作り直す処理を廃止(偽造URLで任意の利用者の招待を作れた)／招待の作成・一覧・削除も職員トークン(ご家族はアカウント)で確認／family_invites をブラウザから閉じるSQLを用意(全店配信後に実行)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): 招待コードの総当たり対策を試験版で導入して。調査で判明: 招待コード(数字8桁)の照合は公開キーでの直接検索で、端末単位のロック(localStorage)は別端末で回避可能。さらに family_invites は公開キーで全件読める・書ける状態で、登録時に招待が無いとURLトークンから招待を作る処理があり、トークンを偽造すれば任意の利用者の招待を作れた。</span><span class=\"lb\">対処</span><span class=\"tx\">api/family-invite.js(service_role)を新設: lookup/signup は回数制限つき(試行は開始時に予約→結果で確定。予約は app_secrets の1行 guard_family_invite に updated_at 条件の楽観ロックで書くため、同時大量送信でも予約済み件数で止まる。IPは鍵付きハッシュ16文字のみ保存。表が使えない時はメモリで代用)。signup はクラウドに実在し未使用・期限内の招待だけで登録し、使用済み化は used_by が空のときだけ(取り合い時はアカウントを取り消し)。パスワードはブラウザでハッシュ化して送り、返すアカウントからハッシュを除く。create/list_patient/list_cm_store/delete は職員トークン(店舗一致・本部は全店)またはご家族アカウントID(同じ利用者・店舗のみ)で確認。有効期限はサーバーで最長14日。クライアント: 登録画面は端末の中身を書き換える前にサーバーで招待を確認し、偽造・未登録・使用済み・期限切れはここで止める。サーバーが無い環境(開発)とトークンの無い古いログインだけ従来の直接アクセス(RLS閉鎖後は失敗=安全側)。紙の案内用紙はブラウザのメニューで印刷しても有効化(beforeprint)。docs/sql/family_invites_rls.sql(RLS有効・ポリシー全削除・anon権限剥奪・戻し方つき)。検証: 偽のPostgRESTにつないだ単体検証33項目合格(偽造コード登録不可・5回失敗で停止・並列20件で失敗5件まで・他店/他利用者は403・生IP非保存・全体上限)／試験版の本番サーバーで架空コード5回→6回目429・未ログインの作成/一覧は401。残課題: family_accounts(ログインID・ハッシュ)も公開キーで読めるため、ログイン等をサーバー化してから閉じる。 試験版 trial123 のみ(安定版は未反映)。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"お知らせ 未読 バッジ 3 初回ログイン 新しい端末 既読 familyReadAt 過去のお知らせ ケアマネ ご家族 0930g\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">ご家族・ケアマネが初めてログインした端末で、登録前の過去のお知らせまで未読として「お知らせ 3」のように表示される不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): ケアマネや利用者家族などが初回ログインした時にお知らせに3と通知が来ているのを無くしてほしい。</span><span class=\"lb\">対処</span><span class=\"tx\">原因: 未読数は「この端末で最後にお知らせを開いた時刻(familyReadAt_利用者ID)」より新しいものを数えるが、初めての端末では記録が空のため全件が未読になっていた。対処: 記録が無いときは「今」を既読時刻として保存し、以降の新着だけを数える。表示中の利用者を切り替えたときもその利用者の記録に読み替える。検証(Playwright): 過去のお知らせ3件で初回表示=バッジ・ポップアップなし、その後に新着1件を追加=バッジ1。 安定版 0930g／試験版 trial123。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"ケアマネ連携\" data-text=\"ケアマネ 担当替え 前任 アカウント管理 登録済アカウント 残る 共有メール 同じメール 取り違え 自動付け替え 閲覧停止 担当者マスタ 氏名 優先 cm-auto reconcile 0930g\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">ケアマネが変わった後も前任ケアマネのアカウントが「アカウント管理」に残る不具合を修正(今の担当ケアマネだけ表示・前任は件数のみ)／同じメールを使うケアマネ同士で担当者を取り違え、前任者の閲覧が残り現任者の担当利用者まで前任者に付与されていた不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30 スクショ): 利用者マスタ管理のアカウント管理でケアマネが変わった時に昔の人の登録情報が残っている。ケアマネはケアマネ事業所・担当者の箇所にのみ出てくるようにするか、担当が変わったら消えるようにしてほしい。</span><span class=\"lb\">対処</span><span class=\"tx\">原因(試作運用店の該当利用者で件数・一致の有無のみ確認): 前任・現任のケアマネが同じメールアドレスで、担当者マスタでは現任者にだけメールが入っていた。スタッフ端末の自動付け替え(担当者マスタ基準でケアマネの利用者別アカウントを付与・停止)は、担当者をメールだけで特定していたため、前任者のログイン(メール+パスワード単位)を現任者と判定し、前任者の行を残したうえ現任者の担当利用者ぶんの閲覧まで前任者に付与していた。対処: ①担当者の特定を「メールと氏名が両方一致」→「氏名が1人だけ一致」→「アカウントに氏名が無いときだけメール」の順に変更。②担当者マスタで特定できないケアマネ(マスタから消えた前任者など)は、利用者の今の担当ケアマネと氏名が違う行の閲覧を停止(氏名なし・担当未設定・その他関係者は触らない)。③アカウント管理の一覧は、続柄=ケアマネージャーのうち今の担当ケアマネと氏名が一致するものだけを表示し、前任者は「表示していません(閲覧は自動で止まります)」と件数を表示。ご家族・その他関係者は従来どおり表示。検証(Playwright): 今の担当・前任・家族・その他関係者の4件→3件表示・前任のみ非表示・注記あり。 安定版 0930g／試験版 trial123。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"ご家族 登録後 データを取得中 進まない 店舗ID 空 招待トークン s 紙で招待 メール 再発行 アカウント管理 store_id null 新しい端末 連絡先 事業所に届かない 利用者を取り寄せ 事業所を確認できませんでした 0930f\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">ご家族の登録: 利用者マスタの「アカウント管理」から出した招待のQRに店舗IDが入っておらず、登録後に「データを取得中」から進まない不具合を修正／新しい端末から登録すると続柄・電話などが事業所側に届かない不具合を修正／店舗不明のアカウントは「事業所を確認できませんでした」と案内</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30 スクショ): ご家族の方で登録はできたが、そこからデータ取得中がずっとなっていて、一回アプリを閉じて再ログインしても変わらない。他にもこういったバグがあったら見つけて修正して。</span><span class=\"lb\">対処</span><span class=\"tx\">原因(クラウドの件数・有無のみで確認): 今日登録されたご家族アカウントの店舗IDが空だった。アカウント管理の紙・メール・再発行の招待トークンに店舗ID(s)が無く、紙の招待は用紙の「印刷」で初めてクラウドに登録される仕組みのため、クラウドに招待が無い状態でQR登録されると、トークンだけで招待を作り直して店舗不明のアカウントになる。店舗不明だと全店舗から利用者IDで探すが、IDは店舗ごとの連番で重複するため特定できず「取得中」のままだった。対処: ①2か所の招待トークンに店舗ID(招待の店舗→スタッフのログイン店舗)を追加 ②登録時、端末に利用者が無ければ招待の店舗から利用者・事業所一覧・既存アカウントを取り寄せて処理(新しい端末でも連絡先が事業所側の利用者情報に反映される。従来は反映されていなかった) ③アカウントの事業所名を招待の事業所名で記録 ④店舗を特定できない場合は「ご利用の事業所を確認できませんでした…招待を発行し直して」と表示。点検: 有効なアカウント29件中、店舗IDが空は2件(うち1件が今日の分)、その他は全件が店舗の利用者と一致。店舗IDが空の2件は招待の再発行・再登録が必要。検証(Playwright): 新しい端末でご家族登録→ログイン状態・店舗ID保存、紙で招待のQRトークンに店舗IDが入る。 安定版 0930f／試験版 trial122。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"ケアマネ連携\" data-text=\"ケアマネ 登録 事業所を選択してください 招待 事業所 固定 自動入力 新しい端末 cmOffices localStorage 空 _invOffice 紙 メール 0930f\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">ケアマネの登録: 招待で事業所が決まっている(画面で変更不可)のに「登録する」で「事業所を選択してください」になり登録できなかった不具合を修正(紙・メールとも)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30 スクショ): サイドバーのケアマネ事業所・担当者から紙で招待し、QRで登録しようとすると、事業所は自動入力されているのに登録するを押すと「事業所を選択してください」になる。メールで送っても同じ。</span><span class=\"lb\">対処</span><span class=\"tx\">原因: 登録画面は店舗から読み込んだ事業所一覧を画面の state(data)にだけ持ち、登録ボタンの確認は端末の保存領域(localStorage)の一覧を見ていた。ケアマネのスマホなど新しい端末では保存領域が空のため、固定表示の事業所が「一覧に無い」と判定されていた。対処: 招待で事業所が決まっている場合(<code>_inviteInfo.cmOffice</code>)はその名前をそのまま使い、電話/FAXは state と保存領域の両方の一覧から補う。選択式のときも両方の一覧を見る。事業所一覧への書き戻しは従来どおり追加のみ(既存を消さない)。検証(Playwright・新しい端末を再現): 事業所固定のケアマネ招待で登録が完了し、アカウントに事業所名・店舗IDが入る。 安定版 0930f／試験版 trial122。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"ケアマネ連携\" data-text=\"iPad ホーム画面に追加 全画面 スタンドアロン window.open 別画面 戻れない アプリを閉じる 招待用紙 紙で招待 家族用ログイン情報 共通URL 支援経過表 初回利用報告 体力測定 モニタリング表 画像 PDF 重ねて表示 閉じる tsumugiDocWindow tsumugiShowHtmlInPage tsumugiOpenImage 0930e\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">ホーム画面に追加したアプリ(URLバーの無い全画面)で、招待用紙などの印刷画面へ行くと元の画面に戻れずアプリを閉じるしかなかった不具合を修正。別画面を開かず今の画面の上に重ねて表示し「← 閉じる（元の画面に戻る）」で戻れるように</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): ケアマネや家族用の招待を紙で印刷するとパソコンはタブが切り替わるだけだが、iPadでホーム画面に追加して全画面表示にしているとそっちの画面に行ったら戻れなくなる。一回アプリ自体を閉じないと戻れないので、アプリを閉じなくても戻れる工夫をしてほしい。</span><span class=\"lb\">対処</span><span class=\"tx\">原因: window.open で開いた別画面は、ホーム画面アプリではタブもURLバーも無いため戻る手段がない。共通部品を追加: <code>_tsumugiInPageMode</code>(navigator.standalone / display-mode: standalone)、<code>tsumugiShowHtmlInPage</code>(用紙HTMLの body と style を取り出し、html/body 向けの指定を重ねた表示の中に限定して #tsumugi-ios-print に描画。上部に「← 閉じる」「印刷 / PDF保存」バー。印刷時は @media print で本体を隠し用紙だけ印刷)、<code>tsumugiDocWindow</code>(window.open('','_blank') の代わり。ホーム画面アプリでは document.write を受けて重ねて表示する窓もどき)、<code>tsumugiOpenImage</code>(画像の重ね表示)。適用: 招待用紙(紙で招待・共通の案内。印刷ボタンで「紙で招待済み」に)、家族用ログイン情報、家族共通URL、支援経過表、初回利用報告、体力測定の記録、モニタリング表、印刷プレビューの例外時フォールバック、写真の拡大表示6か所。家族画面のPDF「別タブで開く」はホーム画面アプリでは非表示(ビューア内で表示済み)。PC・通常ブラウザは従来どおり別タブ。検証(Playwright・ホーム画面アプリを模擬): 別画面0件・重ねて表示・印刷で紙で招待済み1件・閉じるで元のアカウント管理に戻る・印刷モードでアプリ画面とバーが消え用紙だけ。通常ブラウザでは別タブ1件。 安定版 0930e／試験版 trial121。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"個別機能訓練 グループ リセット ボタン グループなしに戻す 試験版のみ trial120\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">【試験版のみ】個別機能訓練のグループ画面に「リセット」ボタン(表示中の午前/午後のグループ分けを確認のうえ全員「グループなし」に戻す・実施担当はそのまま)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): グループ分けでリセットボタンを追加してください。</span><span class=\"lb\">対処</span><span class=\"tx\"><code>resetKinouGroups</code>: 表示中の区分でグループに入っている方の kinouGroup を空にし、追加した空グループも消す。確認ダイアログあり。配信ルール(小さな変更はまず試験版)により試験版のみ。検証(Playwright): A3名・B2名→リセットで全員グループなし。 試験版 trial120。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"モニタリング\" data-text=\"モニタリング 休止中 通所なし 今月来ていない 茂木 常に表示 休止中の印 _monPaused 0930d\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">モニタリング</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">モニタリング: 休止中の方は、その月に通所がなくても「通所なし」の一覧に表示(氏名の横に「休止中」の印)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): 茂木さんも休止中ですが、今月来ていなくても今月の通所なしには表示しておくように。</span><span class=\"lb\">対処</span><span class=\"tx\">対象条件に「休止中(status=休止/一時中止、または表示上の休止)」を追加(<code>_monPaused</code>)。退所済み・利用開始前は従来どおり対象外。氏名の横に橙の「休止中」バッジ。検証(Playwright): 休止＋通所なしの方が通所なしの一覧に表示・休止＋通所ありの方は通所ありに表示。 安定版 0930d／試験版 trial119。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"個別機能訓練 グループ 安定版へ 先週の割り振りをコピー 同じ曜日 4週 cherry-pick 0930d trial118\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">個別機能訓練のグループ分けを安定版へ(trial114/115/118)。あわせて「先週の割り振りをコピー」(同じ曜日・同じ午前/午後。先週が休みなら最大4週前まで)を追加</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): 次の週のグループ分け画面に先週分のコピーボタンを追加して毎週同じ割り振りでもすぐ対応できるように。そしたらこれを安定版にも入れて。</span><span class=\"lb\">対処</span><span class=\"tx\"><code>copyKinouGroupsFromLastWeek</code>: 7日前→14日前→…28日前の同じ区分の記録から kinouGroup_{AM/PM} と kinouStaff を探し、最初に見つかった日を採用。表示中の利用者に割り当て(1グループ5名まで)、その日にグループが無かった方は「グループなし」。既にグループがある場合は置き換えの確認。trial の3コミット(グループ・ドラッグボード・コピー)の App.jsx を stable へ cherry-pick(update-notes の競合のみ解消)。検証(Playwright): 先週なし→2週前の A3名(蛯名)/B2名(長峰)が再現・担当も一致。ユーザー指示により安定版 0930d へ。 安定版 0930d／試験版 trial119。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"個別機能訓練 グループ ドラッグ 長押し 振り分け ボード 最前面 ポップアップ 下に隠れる グループ追加 D E 利用者ごと 廃止 上に表示 短く タップ移動 試験版のみ trial115\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">【試験版のみ】個別機能訓練のグループ: 画面最前面の振り分けボード(グループなし／A・B・C／＋グループ追加)で、名前の長押しドラッグ(またはタップ→グループをタップ)で移動。「＋グループ追加」に入れるとD・E…を自動作成。「利用者ごと」は廃止してグループに一本化。「上に表示」を「上に: A（5）」に短縮</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30 スクショ2枚): ポップアップが項目の下に来てしまっている。グループ数は後で自由に変えられるように(D・E…を提供記録入力で増やせる)。グループで分けるなら利用者ごとは不要。既定でA・B・Cがあり利用者を長押しでドラッグ移動、下の方にグループ追加がありそこにドラッグすると自動でグループDが作られて入る。上に表示: グループA（5名）が長いので短く。</span><span class=\"lb\">対処</span><span class=\"tx\">①重なり: パネルを見出し行と同じ重ね順(z-40)の中に置いていたため、表の固定見出しの下に潜っていた。ReactDOM.createPortal で body 直下・z-index 10050 の全面パネルにした。②ボード: 列=グループなし・A/B/C(既定)・追加済みグループ・「＋グループ追加」。名前カードは長押し250ms(タッチ)/5px移動(マウス)でドラッグ開始、離した位置の列(data-kgdrop)へ移動。タップで選択→列をタップでも移動。5名の列には入れない(警告)。空の追加グループは×で削除。各列の「実施」で担当を選ぶとその列の全員に反映し、後から入った人にも列の担当を付ける(表示と保存のずれを防止)。③「利用者ごと」ボタン/パネルを削除。④「上に」＋select(なし／A（5）…)。検証(Playwright・マウスドラッグ): 6人目はA満員で拒否・「＋グループ追加」でD作成・タップでA→B・各列の表示担当と保存値が一致・パネルが表の見出しより前面。 試験版 trial115。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"モニタリング\" data-text=\"モニタリング 休止 表示されない 成田 小松崎 下田 その月 通所 1回でも 対象 hasAttendance 年 0930c\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">モニタリング</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">モニタリング: 休止中の方(月の途中で休止にした方)が一覧に出なかったのを修正。その月に1回でも出席・振替・臨時があれば通所ありの一覧に表示</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): モニタリングで休止にしている人(過去に休止にしていた人(成田さん、小松崎さん、下田さん))が表示されない。その月に1回でも通所していたら表示するように。</span><span class=\"lb\">対処</span><span class=\"tx\">原因: 対象を「status=利用中」に限っていた。対象条件を「退所済みでない・利用開始済み・(利用中 または その月に通所あり)」に変更。あわせて通所ありの判定に年の一致を追加(別の年の同じ月の記録を数えない)。検証(Playwright): 休止＋当月出席ありの方は表示、休止＋通所なしの方は非表示。バグ修正のため安定版にも即時配信。<b>試験版への取り込みで一度マージが「stash failed」で止まり版数だけ上がった(trial116)ため、やり直して trial117 で反映</b>。 安定版 0930c／試験版 trial117。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"個別機能訓練 グループ 5名 最大 グループ分け 上に表示 一番上 グループ単位 実施担当 kinouGroup_AM kinouGroup_PM 15人定員 試験版のみ trial114\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">【試験版のみ】個別機能訓練のグループ: 利用者をグループA・B・C…(1グループ最大5名)に分け、グループごとに実施担当を選択。「上に表示」で選んだグループを表の一番上にまとめる。氏名の横にグループ印</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): 15人定員以上の店舗ではグループで個別機能訓練を実施するので、利用者をグループ分けして選択したグループが一番上に出るように。個別機能訓練は5人までのグループで実施できるので最大5人のグループをいくつか作れるように。実施担当は利用者ごとだけでなくグループごとでも選べるように。</span><span class=\"lb\">対処</span><span class=\"tx\">記録に <code>kinouGroup_AM/PM</code>(A〜J)を追加(読込/保存)。提供記録入力の「個別機能訓練 実施」の横に「グループ」パネル(利用者ごとのグループ選択・満員の枠は選べない・5名超は警告)とグループ一覧(各グループの実施担当 select=そのグループの表示中区分の全員の kinouStaff を更新)。「上に表示」select で選んだグループの行を displayRecords の先頭に並べ替え(当日モードのみ)、氏名セルに A/B 印(選択中は濃い緑)。午前・午後は別。検証(Playwright): 6名をBに入れると6人目は拒否・A2名/B5名・Bの実施を蛯名に→Bの5名の kinouStaff=蛯名・上に表示B で先頭5行がB。<b>2026-09-30 の配信ルール変更により試験版のみ</b>(安定版は店舗確認後)。 試験版 trial114。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"個別機能訓練 実施担当 利用者ごと 午前 午後 表示中の区分 対象外 表示 _kinouShownIds 0930b\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">個別機能訓練の実施担当: 「利用者ごと」の一覧に表示中でない時間帯(午前表示なのに午後)の利用者が出ていた不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): 利用者ごとで訓練実施の選択をできる箇所で、午前中のクラスなのに午後の人も選択できるようになっている。午前中なら午前中のみ表示で。</span><span class=\"lb\">対処</span><span class=\"tx\">原因: 対象を localPatients(当日の全員)にしていた。AM/PM 絞り込み後の displayRecords を対象にし(_kinouRows)、上部の多数値・全員適用・保存時の既定の付与も表示中の区分の人だけ(_kinouShownIds)に限定。検証(Playwright): AM/PM それぞれで一覧の全員が表に出ている人。バグ修正のため安定版にも即時配信。 安定版 0930b／試験版 trial113。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳 血圧 開始時のみ startOnly 終了時 表示される 再測定 西馬込 江古田 小岩 1回目 最新 3回 bpRe 体温 折返し 0930a\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">連絡帳: 血圧の設定が「開始時のみ」の店舗は2行目を「終了時」ではなく「再測定」に。開始時=1回目の測定値、再測定=最新の値(3回測ったら3回目・再測定なしは空欄)。「開始時＋終了時」は開始/終了とも最新値。体温の文字の折返しを修正</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30): 西馬込店は開始時のみの血圧にしたのに連絡帳が終了時も表示される。江古田や小岩店は終了時ではなく再測定になっている。西馬込もそうして。開始時＋終了時の事業所は最新の数値を反映。開始時のみの事業所は開始時を1回目の測定数値で再測定を最新の数値に。3回測っている場合は開始時は1回目、再測定は3回目。</span><span class=\"lb\">対処</span><span class=\"tx\">ContactBookCard に <code>_cbBp</code> を追加。end: 行1=最新の開始(bpUpSt)・行2「終了時」=最新の終了。startOnly: bpRe の phase=St(区分が複数なら現在値と一致する区分)の n 最小を行1「開始時」、現在の開始値(=最新)を行2「再測定」。ログが無い日は行2に旧方式の2列目(bpUpEn)を出し、無ければ空欄。recheckStart(旧方式・江古田/小岩)は従来どおり行2=2列目を「再測定」。体温ラベルに nowrap。検証(Playwright・1回目160/95脈80→2回目150/90→最新138/84脈72): startOnly「開始時 160/95 脈80」「再測定 138/84 脈72」、end「開始時 138/84」「終了時 128/80」、recheckStart「再測定 130/80」。 安定版 0930a／試験版 trial112。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"分析\" data-text=\"欠席理由ランキング 見切れ 全文 折返し 内訳 全件 省略しない 0930a\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-09-30</span></div>\n      <p class=\"title\">分析(稼働)の欠席理由ランキング: 理由名と内訳を省略(…)せず全部表示(折返し)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-30 スクショ): 「本人・家…」「ショートス…」「通所日の勘…」が見切れている。全部の文字が表示されるようにして。</span><span class=\"lb\">対処</span><span class=\"tx\">理由名の span を nowrap/ellipsis から whiteSpace normal・break-all に。内訳は上位3件＋「…」をやめて全件を折返し表示。検証(Playwright): 「ショートステイ利用中のため（長期入所の準備）」が見切れずに表示。 安定版 0930a／試験版 trial112。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"提供記録入力 人数 チップ 出席 欠席 振替 臨時 休止 休業 2行 優先順位 氏名で検索 非表示 attCountChips 0929u\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">提供記録入力: 上部の人数表示を出席→欠席→振替→臨時→休止→休業の順で2行に詰めて表示／「氏名で検索」欄を非表示</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): ここは1列ではなく2行ずつ記載して。優先順位は出席、欠席、振替、臨時、休止、休業で。氏名で検索は使わないから無くしていいかも。</span><span class=\"lb\">対処</span><span class=\"tx\">attCountChips を CSS grid(2行・列方向に流す)に変更し、並び順を指定の優先順位に。チップは 11px・padding 1px 7px に詰めて高さを抑える。検索ボックスは非表示(searchQuery の検索ロジック自体は残し、必要なら戻せる)。 安定版 0929u／試験版 trial111。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"提供記録 戻る 1つ前の画面 提供記録入力 個人ファイル 利用者マスタ navigateBack prevViewRef tsumugiPFOrigin 印刷 日付欄 記録 個別 左詰め 詰める 0929t\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">サービス提供記録(印刷)の「戻る」は1つ前の画面へ(提供記録入力→個人ファイル→提供記録 と来たら提供記録入力へ。利用者マスタから来たら利用者マスタへ)／印刷の日付欄「記録:」「個別:」を左詰め・行間を詰めて行の高さを変えない</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 提供記録入力から利用者名を選択して提供記録画面にいって戻るをクリックすると利用者マスタ管理画面に行くので提供記録入力画面に戻ってほしい。他でも同様なら1つ前の画面に戻るように統一。名前の行を詰めて行の高さが変わらないように、名前は左詰めで。</span><span class=\"lb\">対処</span><span class=\"tx\">App に <code>prevViewRef</code>(直前の画面)と <code>navigateBack(fallback)</code> を追加し、TicketView に onBack で渡す。個人ファイル経由(fromPF)の場合は、提供記録入力の利用者モーダルから個人ファイルを開くときに sessionStorage <code>tsumugiPFOrigin='record'</code> を置き、戻るでそれを消費して提供記録入力へ(他の画面へ移ったら navigateTo で破棄)。それ以外の fromPF は従来どおり利用者マスタ(個人ファイル再表示)。印刷の日付欄は textAlign left・lineHeight 1・marginTop 1/0。検証(Playwright): 提供記録入力→提供記録→戻る=提供記録入力(#record-table あり)、利用者マスタ→提供記録→戻る=利用者名簿。 安定版 0929t／試験版 trial110。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"個別機能訓練 実施担当 上部 全員 利用者ごと パネル 特記の横 廃止 kinouStaff_AM kinouStaff_PM AM PM 別 他画面から戻る デフォルトに戻る 変わらない 不具合 多数値 0929t\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">個別機能訓練の実施担当: 上部の選択=表示中区分(AM/PM)の全員に適用、隣の「利用者ごと」パネルで個別に変更(特記欄の横の選択は廃止)。値は記録に AM/PM 別で保存し、上部の表示は記録から求める(他画面から戻っても選んだ人のまま・AM/PM を切り替えるとその区分の値)。一度変えた後に別の人を選んでも変わらなかった不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 個々の個別は特記の右側ではなく上部の実施の横で各選択で選べるように。上部の実施者を変更して他の画面から戻るとデフォルトに戻ってしまう。AMで変更してPMに行ったらPMはデフォルトに。変更した後にまた他を選択しても最初に変更した人から変わらない。</span><span class=\"lb\">対処</span><span class=\"tx\">原因: 上部の値を画面の state(kinouDefault)で持ち、行には保存時に「行の値 or 既定」を書いていたため、①他画面から戻ると state が消え既定表示、②2回目の変更では行に1回目の名前が保存済みで上書きされず印刷も変わらなかった。対処: state を廃止し、上部の onChange で表示中区分の全行に <code>kinouStaff_AM/PM</code> を書く(updateRecord→自動保存)。上部の表示値=行の多数値(無ければ最初の機能訓練指導員)。「利用者ごと」ボタンで名前＋select のパネル(既定は「（上部の値）」)。読込は kinouStaff_AM/PM(旧 plain 値をフォールバック)、保存は AM/PM 両方＋plain は表示中区分優先、印刷(generateMonthlySchedule)は plain→AM→PM。検証(Playwright): 変更1→2→3 で上部が都度変わる・自動保存後も保持・パネルで1名を未算定にすると その記録だけ未算定(PM欄)・AM に切替で既定(長峰)→PM に戻すと蛯名・ホームへ行って戻っても蛯名。 安定版 0929t／試験版 trial110。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"個別機能訓練 実施担当 自動保存 保存ボタン不要 kinouDefault dirtyRef 自動保存 1.2秒 印刷 欠席 未来 個別 出さない 0929s\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">提供記録入力: 「個別機能訓練 実施」の既定を変えたときも血圧などと同じく約1.2秒後に自動保存(保存ボタン不要)。印刷では欠席日・未来の予定日に「個別: ○○」を出さない</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 保存を押さなくても自動で反映できない？ 血圧とかの数値みたいに。</span><span class=\"lb\">対処</span><span class=\"tx\">提供記録入力には元々「入力が止まって1.2秒後に自動保存」がある(dirty のときだけ)。行ごとの「個別: ○○」は updateRecord 経由で dirty になり自動保存されていたが、上部の既定(kinouDefault)は画面の state だけで dirty にならず保存されなかった。onChange で dirtyRef=true にし、自動保存 effect の依存に kinouDefault を追加。検証(Playwright): 上部を「見本 看護」に変えて2.5秒待つと保存ボタンなしで当日30件の記録に kinouStaff=見本 看護。印刷は欠席(isA)・未来の予定(mt)の行では「個別:」を表示しない。 安定版 0929s／試験版 trial109。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 未割当 未割り当て 自由に選べる プルダウン 移動先 車 徒歩 その他 moveMember 長押し ドラッグ 試験版 trial108\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">【試験版】送迎表: 未割当の方の右に「移動先…」プルダウン(車・徒歩・その他)を付け、ドラッグしなくても選んで移せるように</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 送迎表で未割り当ての人も自由に選べるようにしてほしい。</span><span class=\"lb\">対処</span><span class=\"tx\">未割当の各行に select(移動先… / 各車 / 徒歩 / その他)を追加し、選ぶと既存の <code>moveMember(iso, sl, pid, dest)</code>(定員超過は確認)で移動。見出しの案内文を「右の「移動先」で車・徒歩を選ぶか、名前を長押しして移動」に。検証(Playwright・未割当10名): 1号車を選ぶと未割当9名に。試験版のみ(安定版には送迎表なし)。 試験版 trial108。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"提供記録 印刷 日付欄 記録: 個別: 1行 縮小 長い名前 AutoFitText 中河内 0929r\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">サービス提供記録の印刷: 日付欄の「記録: ○○」「個別: ○○」を1行に(長い名前は幅に合わせて縮小)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 「記録: 中河内 薫子」が2行になる。1行で表示されるように縮小して。</span><span class=\"lb\">対処</span><span class=\"tx\">日付欄の記録者・実施担当の行を折返し div から <code>AutoFitText</code>(nowrap・max 9px・min 5px)に変更し、日付列の幅に収まるまで縮小して1行にする。検証(Playwright・「記録: 中河内 薫子」): 1行(高さ9px)で表示。 安定版 0929r／試験版 trial107。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"担当職員 役職ごと 枠 グループ 管理者 生活相談員 機能訓練指導員 看護師 介護職員 ○○を追加 役職自動 副の役職 日誌 担当者追加 この日だけ チェック不要 _tempHelp 0929q\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">各種設定の担当職員を役職ごとの枠(管理者・生活相談員・機能訓練指導員・看護師・介護職員＋店舗追加役職)に分け、枠の「○○を追加」で役職を自動設定(副の役職だけ選ぶ)／日誌の「担当者追加」は常に「この日だけ」(チェックを廃止。恒常スタッフは各種設定で登録)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 日誌の担当職員も管理者、生活相談員、機能訓練指導員、看護師、介護職員で分けられているといい。役職をいちいち選択しなくても職員追加でなるから副職だけ選べるように。サイドバーの日誌で担当追加した場合はその日だけ反映にして、常に追加する場合は各種設定から。この日だけのチェックは不要。</span><span class=\"lb\">対処</span><span class=\"tx\">担当職員カードを STAFF_BASE_ROLES＋customRoles の順に枠表示(人数付き)。行の主役職 select を表示のみのラベルに置き換え(役職を変えるときは別の枠で追加し直す)。どの枠にも入らない役職の行は「その他の役職」枠で従来の select を出して選び直せる。日誌の担当者追加モーダルはチェックボックスを外し、常に _tempHelp/_helpDate 付き(その日の日誌だけ・スタッフ切替や各種設定には出ない)。検証(Playwright): 5枠が表示され各枠の人数一致、モーダルに「この日の日誌だけ」の案内・チェック無し。 安定版 0929q／試験版 trial106。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"個別機能訓練 実施担当 機能訓練指導員 記録者 スタッフ切替 フロア担当 kinouStaff 既定 最初の機能訓練指導員 利用者ごと 未算定 印刷 記録: 個別: 警告 提供記録印刷 運動メニュー名 2行 折返し AutoFitText wrap 拡大表示 再測定 大きく 0929q\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">提供記録入力に「個別機能訓練 実施担当」を追加(既定=担当職員で最初の機能訓練指導員・利用者ごとに変更／未算定可)。印刷の日付欄は「記録: 記録者」「個別: 実施担当」の2段。記録者が機能訓練指導員でなくても警告しない／提供記録印刷の運動メニュー名を最大2行で表示／拡大表示の再測定ログを大きく</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 全店共通で運動を回すフロア担当がスタッフ切替で入力している。提供記録入力に個別機能訓練実施担当者を選ぶ箇所を設置して提供記録に反映。2人同時に別の利用者に実施する可能性もあるため全員か個別かも選べると。担当の箇所は「記録」に変更してその下に「個別：〇〇」。警告は個別が選ばれていなければ。未算定も必要。デフォルトで日誌の最初に登録された機能訓練指導員。拡大表示の再測定ログが小さすぎる。提供記録の運動メニュー名が見切れるので最大2行で。</span><span class=\"lb\">対処</span><span class=\"tx\">記録に <code>kinouStaff</code>(氏名 or 「未算定」)を追加。提供記録入力の上部(検索欄の右)に「個別機能訓練 実施」select(候補=担当職員の role/role2 が機能訓練指導員・既定=最初の1人・「未算定」)。行ごとには特記欄の横(表)/下(カード)に「個別: ○○」select(空=画面の既定)。保存時 kinouStaff = 行の選択 → 画面既定(欠席/休業/休止は既存値のまま)。加算なしの店舗(facilityInfo.kobetsuKinouAddon=false)では出さない。従来の「担当者が機能訓練指導員でない」警告を廃止し、加算ありで実施担当が空(機能訓練指導員が未登録)のときだけ確認。generateMonthlySchedule に kinouStaff を追加し、印刷の日付欄を「記録: ○○」「個別: ○○」に(曜日を12px・行間を詰めて82pxに収める)。印刷の運動メニュー名: AutoFitText に wrap(2行に収まるまで縮小・display:block のため高さだけで判定・ResizeObserver で親幅確定後に再測定)を追加し、設定数値行(30px)と日付表の見出し(36px)に適用。文字列版HTMLも白抜き折返し＋長さで7〜9px。拡大表示の再測定ログは15px(削除13px)。検証(Playwright): 既定「見本 訓練」・行の選択肢「個別: 見本 訓練／見本 看護／未算定」・1行を未算定にして保存→その記録だけ未算定、他は既定名・印刷「29（火） 記録: 見本 管理 個別: 未算定」・見出し「②ヒップアブダクションマシン」が2行に収まる。 安定版 0929q／試験版 trial106。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"提供記録 印刷 開始時のみ 終了列 非表示 気分OFF 空行 列ズレ 表が崩れる filler tc colspan 特記 再測定 記載 bpRe generateMonthlySchedule 拡大表示 虫眼鏡 終了 非表示 再測定ログ BpReMini 0929p\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">サービス提供記録の印刷: 「開始時のみ」の店舗は終了時の列を出さない／気分OFFのとき空行の列が1つ多く表が右にずれていたのを修正／特記に再測定の値(「開始 1回目 時刻 上/下 脈」)を記載／拡大表示(虫眼鏡)も「開始時のみ」で終了バイタルを出さず、血圧の下に再測定の記録を表示</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29 スクショ3枚): サービス提供記録で開始時のみの店舗は終了時を消して。2枚目の提供記録がおかしくなっている。提供記録のみに再測定時の値を特記に記載してほしい。虫眼鏡で拡大表示したときも開始時のみは終了時を消して。再測定値はここでも表示して。</span><span class=\"lb\">対処</span><span class=\"tx\">①崩れの原因: React版印刷の「空行」が状態/気分/体温/開始/終了の5セルを固定で出していたため、気分OFFで見出しより1列多くなり表全体が右に伸びていた。空行も見出しと同じ条件(気分 <code>_kOnR</code>・終了 <code>_showEnT</code>)に。②終了列: React版は <code>_showEnT=secondBpVisible(appData, その月の行)</code>、文字列版は <code>_showEnP</code> で th/td を省き、特記行の colspan(tc・${5+…})も連動。③特記の再測定: 印刷行は generateMonthlySchedule が項目を明示コピーしており bpRe が落ちていたため <code>bpRe</code> を追加(bpReLines は既に特記へ連結済み)。④拡大表示: 終了バイタルのブロックを <code>_showEn</code> で条件表示、開始/終了の血圧セルの下に BpReMini(削除も可)。検証(Playwright): 開始時のみ＋気分OFF=見出し16列・全データ行16セル・表幅1081/最終セル右端1080(はみ出しなし)・特記「開始 1回目 16:03 158/92 脈－」、標準＋気分ON=18列/18セル。拡大表示: 開始時のみで「バイタル（終了）」なし・再測定ログ表示。 安定版 0929p／試験版 trial105。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"気分OFF 印刷 気分列 提供記録 印刷 colspan kibunDisabled _kOnP _kOnR 個別運動 基準値 文字サイズ 大きく 幅いっぱい _exFitFs 全角 半角 概算 0929o\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">気分OFFのときはサービス提供記録の印刷(プレビュー・印刷HTML)からも気分列を外す／提供記録入力の運動・個別運動の値と基準値を列幅に収まる最大の文字サイズで表示(「15秒×2セット」7px→10px)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 提供記録の印刷の気分列も消しちゃっていいかな。個別運動の基準値はもう少し大きく表示できる気もするけど？</span><span class=\"lb\">対処</span><span class=\"tx\">印刷は2系統(React版プレビュー: 見出し th と気分 td を <code>_kOnR</code> で条件表示・特記行の colSpan 用 tc を 6→5 に／文字列版 HTML: <code>_kOnP</code> で th・td を省き colspan を 5→4 に)。文字サイズは <code>_exFitFs(文字列, 上限, 下限, 幅px)</code>=全角1・半角0.55で文字幅を概算し、幅に収まる最大(上限15/下限8)を返す。個別運動の値・基準値(72px)、種目名 select(74px)、通常の運動セル(70px)に適用。検証(Playwright): 個別運動の基準値「15秒×2セット」10px・「10回」15px・種目名「タオル引き」14px・「上腕三頭筋トレーニング」8px。印刷プレビュー: 気分ON=見出し9列・特記 colspan 7、OFF=8列・colspan 6。 安定版 0929o／試験版 trial104。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"再測定 ログ 血圧セルの下 折りたたみ 他N件 最新1件 開始 終了 文字なし 詰める BpReMini 気分OFF 分析個人 ご家族画面 記録カード 一覧 kibunDisabled 運動メニュー 列幅 84px 0929n\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">提供記録入力: 再測定の記録を特記ではなく開始・終了それぞれの血圧セルの下に「1回目 14:29 130/73 脈60 [削除]」と詰めて表示(2件以上は最新1件＋「他N件」で展開)／各種設定の気分OFFを分析（個人）・ご家族・ケアマネ画面の記録カード・一覧にも反映／運動メニューの列幅を個別運動と同じ84pxに</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 気分OFFにしたら分析や家族画面からもその項目が消えるようにできる？ 運動メニューの列幅も個別運動と同じに。1回目と2回目の距離を縮められる？ 特記ではなく利用者の血圧の下に出した方がいいのか？ そうすれば開始とか終了の文字が必要なくなる。増えると下に伸びるから折り畳んでおけると。どう思う？</span><span class=\"lb\">対処</span><span class=\"tx\"><code>BpReMini</code>(entries, canEdit, onDelete): 行間1.1・9pxで「n回目 時刻 上/下 脈 [削除]」を縦に。既定は最新1件だけ表示し、2件以上は「他N件」ボタンで展開/「閉じる」。開始セル・終了セルそれぞれの下に置くので「開始/終了」の文字は不要。カード表示では各「○○時を再測定」ボタンの下。特記の上のログ表示は撤去(印刷・分析個人の文字列 bpReLines は従来どおり)。気分OFF: PersonalDashboardView の <code>_kibunOn2</code> で記録カードの気分ブロックと一覧の気分(通)/(帰)列を非表示(ご家族・ケアマネ・ご本人も同じ部品)。運動メニューの col を 84px(入力欄 78px)、列見出し maxWidth 84。検証(Playwright): 2回再測定で折りたたみ「2回目 … 他1件」→展開で2行→最後を削除で 150/88 に戻る、行高 75px(展開 88px)。気分OFFで分析個人に「気分(通)」見出し・気分カードなし。 安定版 0929n／試験版 trial103。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"気分 通所時 帰宅時 入力 ON OFF kibunDisabled 各種設定 事業所ごと 自己判断 ケアマネ 提供記録入力 一覧 カード 拡大表示 0929m\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">各種設定に「気分の入力（通所時・帰宅時）」のON/OFFを追加。OFFにすると提供記録入力(一覧・カード・拡大表示)から気分の欄と列が消える(入力済みの気分は消えない)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 各種設定に気分欄の入力をするかしないかを選択できるようにしてほしい。ケアマネにはあるとわかりやすいと言われたが事業所によってはいらないという声もあるため自己判断型に。</span><span class=\"lb\">対処</span><span class=\"tx\"><code>systemSettings.kibunDisabled</code>(既定 false=表示)。提供記録入力の <code>_kibunOn</code> で一覧の th/td/colgroup・カードの通所/帰宅ボタン・拡大入力ビューの気分ボタンを条件表示。分析・連絡帳・ご家族画面の表示は変えていない(未入力なら「—」)。各種設定の「テンキー」の下に「気分の入力（通所時・帰宅時）」カード(チェックボックス)。検証(Playwright): OFF で列見出しが「利用者名｜状態｜体温｜開始…」になり気分列が消える。 安定版 0929m／試験版 trial102。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"再測定 復活 削除 同期 bpRe 空配列 省略 マージ 1件ずつ 削除 縦に並べる 開始 1回目 時間 血圧 脈 旧方式 再測定列 再ボタン 非表示 列ズレ ①チェストプレス 広い 終了列 colgroup 個別運動 列幅 84px 0929m\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">提供記録入力: 再測定の記録を「開始 1回目 14:05 158/92 脈78 [削除]」で縦に並べ1件ずつ削除／削除しても復活する不具合を修正／旧方式「再測定」列の店舗では「再」ボタンを出さない／終了列を隠したとき①の運動列だけ広がる列ズレを修正／個別運動の列幅を60→84pxに</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29 スクショ3枚): 再測定の項目と「再」で内容が被っている。①チェストプレスだけ長い。個別運動の運動メニュー名が見切れているので列幅を広げて。再測定は「開始 1回目 時間 血圧 脈」で表示してその隣に削除。削除を押しても復活してしまう。2回目などは右ではなく下方向に増やして。</span><span class=\"lb\">対処</span><span class=\"tx\">①復活の原因: 保存時に bpRe が空配列だとキー自体を省略していたため、端末間マージ(欠けているキーは変更なし扱い)で削除前のログが戻っていた。空でも <code>bpRe: []</code> を必ず書く。②ログ表示は行ごと(「開始 1回目 時刻 上/下 脈○ [削除]」)を縦に並べ、削除は <code>removeBpRemeasureAt(id, at)</code> で1件ずつ(最後の1件なら入力欄をその前の値に戻す・途中の1件なら記録だけ削除して回数を振り直す)。③旧方式 recheckStart の店舗は <code>_reOn=false</code> で「再」ボタンを出さない(2列目=再測定の運用と重なるため)。④列ズレ: 終了列(th/td)を隠しても colgroup の col が残っていたため、145px の col が①の運動列に当たっていた。col も条件付きに(2つの表)。⑤個別運動の col を 84px(旧58/60)、種目名フォントは≤3字15px…≥10字9px。検証(Playwright): startOnly で「①チェストプレス:70｜個別運動①:84」、recheckStart で再ボタン0、2回再測定で2行(flex-direction column)、最後を削除で 150/88 に戻る、全削除→保存→再読込でログ0。 安定版 0929m／試験版 trial102。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"再測定 再ボタン テンキー 通常と同じ入力 / スラッシュ 再測定削除 取消 前の値に戻す removeBpRemeasure applyBpRemeasure data-bp-input 0929l\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">提供記録入力の「再」ボタン: 専用の小窓をやめ、今の値を○回目に残して欄を空にし、通常と同じテンキー（キーボード）入力で「158/92」と打つ方式に。特記の上に「開始時（終了時）の再測定を削除」ボタンを追加（最後の再測定を取り消して前の値に戻す）</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 再測定の入力方法は通常と同じでテンキーが出てきて自分で / をつける形にしてほしい。間違えて再測定した場合も考えて再測定削除ボタンも追加して。</span><span class=\"lb\">対処</span><span class=\"tx\">BpRemeasureModal を撤去。<code>applyBpRemeasure(id, phase)</code>=今の上/下/脈を bpRe に n回目(時刻は現在時刻)として積み、3欄を空にして血圧の統合セル(bp{St|En}_combo)にテンキーを開く(テンキーOFFの店舗は表示中の入力欄に data-bp-input でフォーカス)。<code>removeBpRemeasure(id, phase)</code>=その区分の最後のログを確認のうえ削除し、ログに残っていた値を欄に戻す。ボタンは特記の上のログ表示に「開始時の再測定を削除」「終了時の再測定を削除」(表・カード両方)。検証(Playwright): キーボード入力 158/92→再→欄が空＋フォーカス・ログ「開始時1回目 158/92（再測定 14:05）」→142/86 入力→削除→158/92 に戻りログ消滅。テンキー入力でも 再→テンキーが開き欄が空になる。 安定版 0929l／試験版 trial101。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"個別運動 単位 二重 500gg 15回回 規定値 見切れ 種目名 見切れ マシン名 長い 横に伸びる 列見出し 折返し 拡大表示 虫眼鏡 種目名 基準値 利用者マスタ 運動メニュー (k… 0929k\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">提供記録入力: 個別運動の規定値に単位が二重に付く(500gg・15回回)を修正／規定値・種目名の見切れ／長いマシン名で表が横に伸びるのを列見出しの折返しで防止／拡大表示(虫眼鏡)に個別運動の種目名と規定値／利用者マスタの運動メニューの単位「(k…」見切れ</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29 スクショ6枚): 個別運動の単位がダブっている。基準値の単位が見切れて消えている。提供記録入力の基準値も見切れている。マシンの名前が長いと横に伸びまくる。虫眼鏡で拡大表示した時に個別運動の種目名と基準値を表示してほしい。個別運動の名前も見切れている。</span><span class=\"lb\">対処</span><span class=\"tx\">①二重単位: 個別運動セルのプレースホルダーが「規定値＋単位」を組み立てていたが、規定値は利用者マスタで保存する時点で applyExUnits により単位付き(500g)になっているため g が二重になっていた。プレースホルダーを applyExUnits(規定値, 種目)(冪等・末尾が単位なら付けない)に統一。②値が空のときはプレースホルダーの長さで文字サイズを決める(15秒×2セット が見切れない)。③種目名は7〜8文字=9px・9文字以上=8px。④運動メニューの列見出し(2つの表)を truncate/nowrap から折返し(maxWidth 76px・break-all)に変更し、長いマシン名でも列幅が伸びない。⑤拡大入力ビューの個別運動は「個別運動①／ー」ではなく「個別運動① ／ 種目名 ／ 値(空なら規定値をグレー)」を表示し、タップでテンキー入力(スロット既定の種目を自動セット)。⑥利用者マスタの運動メニューカードのラベルは truncate をやめて折返し、単位は nowrap。検証(Playwright・規定値 15秒×2セット): プレースホルダー「15秒×2セット」(二重なし)、拡大表示「個別運動① タオル引き 15秒×2セット」。 安定版 0929k／試験版 trial100。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"お迎え時間 13時　分 分未設定 事業所にお問い合わせください 13時 誤解 当日 翌日 注意書き 0929j\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">ご家族・ケアマネ画面: 分が未定のお迎え時間は「13時　分」のまま表示(「13時」にしない)。当日・翌日で分が未設定なら「お迎え時間の「分」が未設定です。事業所にお問い合わせください」を添える</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 「13時　分」を「13時」と表示すると13時にお迎えと勘違いする可能性があるためそのままで。1日前になっても分が更新されない場合は「分が未設定です。事業所に問い合わせてみてください」的な表示にしてもいいかも。</span><span class=\"lb\">対処</span><span class=\"tx\">0929i で入れた「13時　　分→13時」の整形を撤回し、「時」の後の全角空白を1つに揃えるだけにした(「　時　分」=全部未定だけ空にして「事業所にご確認ください」)。本日の枠は常に、次回の枠は次回日付が今日か明日のときに、分が未設定(「○時　分」)なら注意書きを表示。検証(Playwright・送迎時間 13:--): 「お迎え 13時　分 頃」＋注意書き。 安定版 0929k／試験版 trial100。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"血圧 設定 開始時＋終了時 開始時のみ secondBpMode startOnly recheckStart 旧方式 再測定 2列目 非表示 過去データ secondBpLegacyRecheck 0929j\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">各種設定「血圧・脈の測定」: 「開始時＋終了時」「開始時のみ」の2択に。開始時のみの店舗は提供記録入力・分析の終了時の列を隠す(過去に値がある日は表示)。旧方式「開始時＋再測定」の店舗は選び直すまで従来どおり</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 設定は開始時＋終了時と開始時のみで選べるようにしたらいいんじゃないかな。</span><span class=\"lb\">対処</span><span class=\"tx\"><code>secondBpMode</code>: end／startOnly。旧値 recheckStart の店舗にだけ3つ目「開始時＋再測定（旧方式）」を選択済みとして表示し、startOnly に切り替えると secondBpLegacyRecheck=true を保存して過去記録の2列目を「再測定」ラベルのまま見せる。<code>secondBpVisible(appData, 記録)</code>=startOnly でも表示中の記録に2列目の値があれば列を出す(データを隠さない)。提供記録入力の表(2種類)・カード表示・Tab巡回・分析個人の一覧と記録カードに適用。印刷(提供記録)は列を残したまま(空欄)。 安定版 0929k／試験版 trial100。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"血圧 脈 再測定 再ボタン 開始時 終了時 1回目 2回目 上書き bpRe ログ 特記に書かない 印刷 分析個人 連絡帳 （再測定） BpRemeasureModal 0929j\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">提供記録入力: 開始時・終了時の血圧の横に「再」ボタン。再測定の値を入れると、それまでの値は「開始時1回目 158/92 脈78（再測定 10:05）」として記録に残り(特記の下・提供記録の印刷・分析個人に表示)、入力欄は再測定の値に置き換わる。連絡帳は再測定後の値に「（再測定）」</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 再測定ボタンではなく「再」ボタンを開始時と終了時の横に置き、タップすればそれぞれの再測定値を入力できるようにして元の値を特記に「開始時1回目」と値・時間を記載して入力画面には上書き。また測れば2回目。理由は必要？ 連絡帳には再測定値が通常の血圧の箇所に記録されると思うが1回目も記載した方がいい？</span><span class=\"lb\">対処</span><span class=\"tx\">記録に <code>bpRe</code>=[{phase:St|En, ampm, n, up, dn, pl, time, at}] を追加(読込 pData.bpRe／保存 newRecord.bpRe)。「再」ボタン(表・カード両方)→ BpRemeasureModal(上/下/脈と時刻・理由欄なし・外側タップで閉じない)→ applyBpRemeasure が今の値を n回目 としてログに積み、入力欄を置換。ログは<b>特記には書かない</b>(特記はご家族画面の「今回の様子」に出るため)。表示: 入力画面の特記の上(黄色)・提供記録の印刷の特記欄(文字列版/React版)・分析個人の記録カード(スタッフのみ)。連絡帳カードは再測定後の値の横に小さく「（再測定）」(1回目の値は出さない)。「開始時のみ」設定では終了時の「再」を出さない。検証(Playwright): 158/92→再(142/86 脈74)で入力欄 142/86・ボタン「再1」・特記上に「開始時1回目 158/92（再測定 13:10）」・保存後 bpRe に1件、bpUpSt=142。 安定版 0929k／試験版 trial100。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"分析\" data-text=\"分析個人 スタッフ 次回のお迎え時間 本日のお迎え時間 枠 compactMode 同じ表示 0929i\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">分析（個人）にもご家族画面と同じ「本日のお迎え時間／次回のお迎え時間」の枠を表示</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 分析個人にも次回のお迎え時間を表示した方がいいのかな？ 次回お迎え時間は本人、家族、ケアマネなど登録している人は全員見れるようになってるんだよね？</span><span class=\"lb\">対処</span><span class=\"tx\">todayVisit/nextVisit の compactMode 条件を外し、スタッフ側の分析（個人）でも利用者を選ぶと同じ枠(基本情報の下)が出る。ご本人・ご家族・ケアマネは家族アプリの「通所記録」タブで同じ PersonalDashboardView を使っており(ご本人は familyMode=true・ケアマネは cmViewerMode=true)、登録している人は全員見られる。 安定版 0929i／試験版 trial99。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"お迎え時間 連絡帳 次回予定 nextTimeOverride nextDateOverride 送迎表 優先順位 13時　分 13時 分未定 _cbNextTime _normT 0929i\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">ご家族・ケアマネ・ご本人画面のお迎え時間: 送迎表の乗車時間 → 前回来所時に連絡帳の「次回予定」に書いたお迎え時間 → 曜日の送迎時間 の順に採用。分が未定の「13時　分」は「13時」に整形</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 本日のお迎え時間が9月29日は13時10分なのに「13時　分」となっている。9月25日に通所した際の連絡帳には13時10分と記載しているのでそれを反映させてほしい。送迎表を安定版に導入したらそこを元に反映させた方がいい？</span><span class=\"lb\">対処</span><span class=\"tx\"><code>_cbNextTime(info)</code>: その利用者の対象日より前(45日以内)の記録のうち、nextTimeOverride に数字があり、次回日付(nextDateOverride の「M月D日」／未入力なら記録日からの自動計算)が対象日と一致する最新の記録の値を使う。<code>_pickupOf</code> の優先順位は ①送迎表(transportPlans・試験版で確定した乗車時間) ②連絡帳の次回予定 ③曜日の送迎時間(→提供開始10分前)。<code>_normT</code> で「13時　　分」→「13時」、「　時　分」→空(「お迎え時間は事業所にご確認ください」)。検証(Playwright・見本・4日前の記録に次回 9/29 13時10分): 「本日のお迎え時間 9月29日（火） お迎え 13時10分 頃」、記録なし＋送迎時間 13:-- で「お迎え 13時 頃」、送迎表 8:55 があれば「8時55分」。「確定後にお迎え時間が変更されました」の表示は送迎表を安定版に入れるときに合わせて実装(未来の修正点に記載)。 安定版 0929i／試験版 trial99。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"家族画面プレビュー 利用者 切替 変わらない 会田 青地 targetPatientId selectedPatientId useEffect PersonalDashboardView お知らせ 閲覧管理 0929i\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">お知らせ・閲覧管理の家族画面プレビューで利用者を切り替えても画面が最初の利用者のままだったのを修正</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): お知らせの家族画面プレビューで利用者を変更しても画面自体が切り替わらない。会田さんから青地さんに変更しても、ずっと会田さんの情報しか表示されない。</span><span class=\"lb\">対処</span><span class=\"tx\">原因: PersonalDashboardView は親から渡る targetPatientId を useState の初期値でしか見ておらず、プレビュー側で利用者を変えても内部の selectedPatientId が更新されなかった(通常の分析画面は内部の選択で切り替えるため気付かなかった)。対処: targetPatientId が変わったら追従する useEffect を追加(null=選択解除は追従しない)。検証(Playwright): 例示 清 → 試作 節子 に切り替えると通所記録タブが試作 節子の記録(9/16・1件)に変わる。 安定版 0929i／試験版 trial99。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌 兼務 生活相談員 2人 介護職員 必須 充足 kenmu 必須職員未選択 兼務ボタン 担当職員 印刷に載せない 人員基準 0929h\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">日誌: 「必須職員未選択」の警告に「兼務」ボタンを追加。担当職員の中から別の役職の人を選ぶとその役職を充足したことになり警告が消える(例: 生活相談員が介護職員を兼務)。記録は日誌の外の青い帯に表示し印刷には載せない</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 日誌でもし生活相談員が2人出勤した場合でも介護職員が必須？ 必須ならその対応もしないといけない。</span><span class=\"lb\">対処</span><span class=\"tx\">人員基準では生活相談員が2人いても介護職員は別に必要(単位ごと・利用者15人まで1人以上)。ただし生活相談員が介護職員の業務を兼務することは認められている(同じ時間帯に1人1役)ため、日誌にその日限りの兼務を記録できるようにした。<code>log.kenmu[役職]=職員id</code>、<code>diaryStaffMissing</code> は「その職員が担当職員に選ばれていて kenmu で指定されている」場合も充足とみなす(担当から外れたら自動的に無効)。チップの「兼務」→その日の担当職員(本来の役職が該当役職以外の人)から選ぶ小さなモーダル。記録は未完成バナーの下の青い帯「兼務の記録: ○○（生活相談員）が 介護職員 を兼務 [取消]」で、日誌本体(#diary-print-content)の外なので印刷・プレビューには出ない。恒常的に兼務する人は職員設定の副役職(role2)でも可。検証(Playwright・生活相談員2名を選択・介護職員未選択): チップ「必須職員未選択: 介護職員 [兼務][減算]」→兼務で相談員2人目を選ぶとチップが消え青い帯に表示・印刷内容に「兼務」を含まない・取消で警告に戻る。 安定版 0929h／試験版 trial98。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"個人ファイル 表示領域 拡大 画面いっぱい 左右 上下 max-w-5xl 1700px 100vh モーダル 0929h\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">個人ファイルのモーダルを画面いっぱい(横 最大1700px・縦 ほぼ全高)に拡大</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 個人ファイルって結構確認したりするので表示領域をもっと拡大したい。左右と上下で拡大できる？</span><span class=\"lb\">対処</span><span class=\"tx\">PersonalFileModal の外枠 max-w-5xl(1024px)・h-[90vh] を max-w-[1700px]・h-[calc(100vh-24px)](スマホは 16px)に、外側の余白 p-4 → p-2/p-3 に変更。1366×900 の画面で 1342×876px(以前は 1024×810)。中身のレイアウトは変えていない。 安定版 0929h／試験版 trial98。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡\" data-text=\"休み連絡 連絡済 印刷 PDF FAX 複合機 カレンダー 編集済 printed status プレビュー tsumugi:printed 手動 連絡済にする 取消 0929h\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">休み連絡: プレビューから「印刷・FAX・PDF」を実行してもカレンダーが「連絡済」にならなかったのを修正。送付状に「連絡済にする／取消」ボタンも追加</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 休み連絡で複合機からFAXをしたり印刷しても連絡済にならない。</span><span class=\"lb\">対処</span><span class=\"tx\">原因: 送付状のツールバーは「プレビュー」と「保存」だけで、status を printed にする handlePrint/handleSavePdf はどこからも呼ばれていなかった(プレビューを開くと送付履歴には記録されるが、カレンダーの色は「編集済」のまま)。対処: 印刷プレビューの「印刷・FAX・PDF」(openPrintWindow)で window に <code>tsumugi:printed</code>(detail.title) を発火し、休み連絡画面は開いている送付状(selectedEntry)の status を printed(PDF済なら both)にして自動保存(faxed/both は維持)。加えて、アプリから印刷せずに連絡した場合のために送付状のツールバーに「連絡済にする」(連絡済のときは「✓ 連絡済（取消）」→確認して編集済へ)ボタンを追加。検証(Playwright): プレビュー→印刷・FAX・PDF→閉じる→カレンダーに戻ると「例示 花子 連絡済」、ボタンが「✓ 連絡済（取消）」、取消で「連絡済にする」に戻る。 安定版 0929h／試験版 trial98。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"ご家族 ケアマネ 本日のお迎え時間 次回のお迎え時間 からご利用予定 送迎表 乗車時間 transportPlans 徒歩 _pickupOf 0929h\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">ご家族・ケアマネ画面: 本日が利用日で開始前は「本日のお迎え時間 ○月○日 お迎え ○時○分 頃」、それ以外は「次回のお迎え時間」に(前回の「○時○分からご利用予定」を置き換え)。送迎表に乗車時間があればそれを優先</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): ここはご利用予定ではなくて本日のお迎え時間が表示されないといけないのか。本日より前は次回のお迎え時間って表記にしてほしい。</span><span class=\"lb\">対処</span><span class=\"tx\"><code>_pickupOf(info)</code>(送迎表 transportPlans のその日の乗車時間→無ければ getNextVisitInfo の時間=曜日の送迎時間→提供開始10分前・徒歩は「徒歩でご来所」)を todayVisit/nextVisit で共用。開始前の青い枠は「本日のお迎え時間 9月29日（火） お迎え 8時55分 頃 記録は利用後に表示されます」、緑の枠の見出しは「次回のお迎え時間」。切替の基準(各種設定の提供開始時刻)は変えていない。検証(Playwright・見本・送迎表に 8:55): 開始前「本日のお迎え時間 … お迎え 8時55分 頃」、開始後「次回のお迎え時間 10月6日（火） お迎え 9時 頃」。 安定版 0929h／試験版 trial98。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳 項目設定 利用者ごと ON OFF 利用者ごとの値を設定 一覧 入力 contactBookValues どの利用者 0929g\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">連絡帳の項目設定: 「利用者ごと」をONにした項目に「利用者ごとの値を設定」を追加し、この画面で利用者一覧に直接入力できるように(空欄は共通の表示文字)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 利用者ごとで表示をONにしたらどの利用者に表示されるとかはどこで設定するの？</span><span class=\"lb\">対処</span><span class=\"tx\">「利用者ごと」は「表示する/しない」ではなく「値を利用者ごとに変えられる」設定(項目自体は全員に表示・空欄の人は共通の表示文字)。従来は各利用者の連絡帳カードのセルをタップして入力する方式だけで分かりにくかったため、ContactBookConfigModal に patients を渡し、ON の項目の下に「▼ 利用者ごとの値を設定（N名 設定済）」→ 氏名で絞り込みつきの一覧(氏名｜入力欄・placeholder=共通の表示文字)を展開。保存時に変更分だけ patients[].contactBookValues[itemId] へ反映(handleSaveConfig(newConfig, pv))。カードのセルをタップして入力する従来の方法も残る。検証(Playwright): OFF→ON、展開して1名に「週2回」→保存→その利用者の contactBookValues に保存。 安定版 0929g／試験版 trial97。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"ご家族 ケアマネ 本日のご利用予定 開始前 提供時間 開始時刻 serviceTimeAM serviceTimePM からご利用予定 空の記録 前回の記録 次回 切り替え todayVisit _recHasData 0929g\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">ご家族・ケアマネ画面: 本日が利用日で開始時刻(各種設定の午前/午後の提供時間)前は「本日のご利用予定 ○時○分からご利用予定」を表示し、当日の空の記録は出さず前回の記録を表示。開始時刻を過ぎたら次回のご利用予定に切り替え</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 5枚目、午前や午後で日付は変わったがまだ利用時間になっていない場合は各種設定の時間に応じて「開始前は午前だと9時00分から、午後なら13時25分からご利用予定」のような表示にできるか。次回のご利用予定日時も開始時間になったら表示されるように。</span><span class=\"lb\">対処</span><span class=\"tx\"><code>todayVisit</code>: getNextVisitInfo を「前日」基準で呼んで今日が利用日か判定し、区分(AM/PM)の提供開始時刻(facilityInfo.serviceTimeAM/PM の先頭「9:00」等。未設定は AM 9:00／PM 13:20)と現在時刻を比較して before を決める。before なら青い枠「本日のご利用予定 9月29日（火） 9時00分 からご利用予定 記録は利用後に表示されます」を出し、緑の「次回のご利用予定」は隠す。「今回の様子」「今回の記録」は当日分がまだ空(体温・血圧・気分・特記・運動が全て未入力=_recHasData false)なら候補から外して前回の記録を表示。開始時刻を過ぎると従来どおり(当日の記録＋次回の予定)。検証(Playwright・見本): 開始を現在+1時間にすると「本日のご利用予定 … 12時00分 からご利用予定」・次回カード無し、開始を−1時間にすると次回「10月6日（火） お迎え 9時 頃」と当日記録。 安定版 0929g／試験版 trial97。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"家族画面プレビュー 利用者を選択 検索 ログイン画面を開く 同じ行 過去履歴 絞り込み 全体 個別 写真 PDF 添付 キーワード 検索 ハイライト mark 0929g\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">お知らせ・閲覧管理: 家族画面プレビューの「利用者を選択」「検索」「ログイン画面を開く」を同じ行に／過去履歴に「全体＋個別／全体のみ／個別のみ」「全て／お知らせ／写真・PDF」とキーワード検索(タイトル・本文・キャプション・黄色ハイライト)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 4枚目の利用者を選択とログイン画面を開くはその下の検索と同じ列に(順番は 利用者を選択・検索・ログイン画面を開く)。6枚目の過去履歴は全体と個別、お知らせ、写真で選べるように。写真で絞ると何も出ない→写真・PDFが出るように。キーワードでタイトルや本文を検索し、ハイライトで分かりやすく。</span><span class=\"lb\">対処</span><span class=\"tx\">①プレビュー: 検索欄を一覧カードからヘッダー行(ドロップダウンの右・ログイン画面を開くの左・flex-1)へ移動(利用者選択中は非表示)。②過去履歴: historyFilter に scope(all/all_only/personal)と q を追加。「写真・PDF」は写真の投稿(familyPhotos)に加えて写真/PDF が添付されたお知らせ(e.photos.length>0)も対象(店舗の写真は「お知らせに添付」で投稿されるため、従来の「写真」だけの絞り込みでは0件だった)。キーワードは NFKC＋小文字で title/body/content/caption/name/添付名を部分一致、行のタイトル・キャプションに <mark>(黄色)、本文だけが一致する場合は該当箇所の抜粋(前後60字)をタイトル下に表示。検証(Playwright・お知らせ2＋個別1・添付1): 全て3／写真・PDF 1／個別のみ1／「お弁当」1件で mark 1個。 安定版 0929g／試験版 trial97。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌 減算 日誌の外 印刷に出さない 加算なし 機能訓練指導員 看護師 介護職員 管理者 生活相談員 人員基準欠如 DIARY_GENSAN_ROLES ボタン AM PM 同じ行 未完成バナー 注意文 削除 0929g\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">日誌: 減算の記録を日誌の外(未完成バナーの下の赤い帯)へ移し印刷に出さない・減算ボタンは看護師/介護職員(減算)と機能訓練指導員(加算なし)だけ・担当職員欄の注意文を削除・迎え/送り/担当者追加/プレビュー/保存を日付・AM/PMと同じ行に</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 管理者が不在だと減算になるのか？ 1枚目の注意文(必須:…)は不要。2枚目の「不在のため減算」は日誌内ではなく外に表示してプレビューでは見えないように。3枚目の送迎表取込や迎えなどのボタンをAM/PM切替と同じ行に。</span><span class=\"lb\">対処</span><span class=\"tx\">①減算になるのは人員基準欠如の看護職員・介護職員(所定単位数の30%減)と、機能訓練指導員不在で個別機能訓練加算が算定できないケース。管理者・生活相談員は減算の仕組みが無く運営基準の問題なので、<code>DIARY_GENSAN_ROLES</code>=機能訓練指導員・看護師・介護職員 に限定し、ボタンの文言は機能訓練指導員だけ「加算なし」、注記は <code>diaryGensanLabel</code>(「機能訓練指導員が不在（個別機能訓練加算は算定不可）」／「○○が不在のため減算」)。管理者・生活相談員は警告チップのみ(必ず選ぶ)。②担当職員欄の見出しを「担当職員」だけに戻し、必須役職の注記と減算表示を外した。③未完成バナー(flexBasis 100%)をボタン群の後ろへ移動して、日付・AM/PM・迎え・送り・担当者追加・プレビュー・保存が1行、警告はその下。その下に「減算の記録: …[取消] …日誌の印刷には載りません」の赤い帯(日誌本体 #diary-print-content の外)。検証(Playwright): AM/迎え/送り/担当者追加/プレビューの y=60-61・バナー y=124、チップは管理者/生活相談員にボタン無し・機能訓練指導員「加算なし」・介護職員/看護師「減算」、加算なしを押すと赤い帯に表示され印刷内容に「減算」「必須:」を含まない。 安定版 0929g／試験版 trial97。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳 連絡事項 入力済み 件数 バッジ 個別 全員 プルダウン 入力済 ● 先頭 削除忘れ カードのタップ 項目設定 利用者ごと ON OFF ボタン iPad 反応しない 0929f\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">連絡帳: 「連絡事項」ボタンに入力済み人数(個別N名／全員)を表示・個別連絡事項の利用者プルダウンで入力済みを先頭に「● 氏名（入力済）」・連絡事項の枠のタップで編集を開かない・項目設定の「利用者ごと」を ON/OFF ボタンに</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 連絡帳の項目で「利用者ごと」をタップしても何も起こらない(設定も新しくしないといけない)。連絡事項が入力されている場合、下の方の人は入力されているのを忘れて削除忘れが起きそうなので「入力済み○件」と表示してほしい。個別の連絡事項の利用者プルダウンで記載されている利用者を分かりやすく。連絡事項もタップではなく上部の「連絡事項」をタップした時のみ反応で。</span><span class=\"lb\">対処</span><span class=\"tx\">①連絡事項ボタン: その日の連絡帳に出る利用者のうち contactBookRenraku に文字があり表示期間内の人数を「個別N名」、全員共通(renrakuAll)が有効なら「全員」を緑バッジで表示。②RenrakuModal の利用者プルダウン: 入力済みを先頭に並べ「● 氏名（入力済）」、未入力は全角空白でインデント。③ContactBookCard の連絡事項の枠から onClick(onEditRenraku)と cursor/hover を撤去(title で案内)。④項目設定の「利用者ごと」: Chromium では label＋checkbox が反応していた(Playwright で true→false 確認)が iPad で反応しない報告のため、label に依存しない明示的な ON/OFF ボタン(紫=ON)に変更。「保存後に各利用者のカードの値をタップして入力」の説明を title に。検証(Playwright): バッジ「個別1名」、プルダウン「● 試作 節子（入力済）」。安定版 0929f／試験版 trial96。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌 必須職員 定員 看護師 管理者 生活相談員 機能訓練指導員 介護職員 人員基準 未完成 未選択 減算 gensan カレンダー 減 印 diaryRequiredRoles diaryStaffMissing diaryPendingItems DIARY_STAFF_CUTOFF 0929f\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">日誌: 必須職員(定員連動)が未選択なら「日誌が未完成です」に「必須職員未選択: ○○」を表示。不在時は「減算」ボタンで記録し警告を消す(担当職員欄に「○○が不在のため減算」＝画面のみ・カレンダーに赤い「減」印)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 日誌が未完成ですの箇所で必須職員が選択されていなければ未選択に追加して。15人定員だと看護師が必須など、各種設定の定員に応じて自動判定してほしい。機能訓練指導員など必須職員が不在で減算する場合は減算ボタンを設置し、タップすれば警告が消えるように。どこかに「〇〇が不在のため減算」と表示(日誌の中か外かは任せる)。日誌のカレンダーにはわかりやすく表示。</span><span class=\"lb\">対処</span><span class=\"tx\">通所介護の人員基準に合わせ <code>diaryRequiredRoles(appData)</code>=管理者・生活相談員・機能訓練指導員・介護職員＋(定員&gt;10なら看護師)。<code>diaryStaffMissing(log, iso, appData)</code>=担当職員(主役職 role／副役職 role2)で該当者が1人も選ばれていない役職(log.gensan[役職]=true は除外・職員一覧が空の店は判定しない・<code>DIARY_STAFF_CUTOFF</code>=2026-09-29 より前の日誌には遡って適用しない)。<code>diaryPendingItems</code> に第4引数 appData を追加して「必須職員:○○」を未完成項目に含め、ホームの日誌バッジ・カレンダーの完了印・日誌画面の3か所すべてで同じ判定。日誌画面のバナーは「必須職員未選択: ○○」チップの横に赤い「減算」ボタン(押すと log.gensan に記録・警告が消える)。担当職員欄の見出しに「○○が不在のため減算 [取消]」(className no-print=印刷・日誌本体には載せない)と「必須: …（定員N名・看護師必須／任意）」の注記。カレンダー(2種類)の日付に赤い「減」印(_gensanDays)。検証(Playwright・定員15・職員5役職): 必須注記「…看護師（定員15名・看護師必須）」、未選択チップ5→「減算」で管理者のチップが消え「管理者が不在のため減算」表示→保存後カレンダーに「減」1件。vitest 16/Playwright 22/run_tests 16 PASS。安定版 0929f／試験版 trial96。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳 印刷位置 微調整 プレビュー 矢印 左 右 上 下 1mm 保存 即時 組み直し adjust _mkAdjust _layoutRenraku setPrintHtml 0929e\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">連絡帳の印刷位置の微調整を印刷プレビューの画面で(横 ←左／右→・縦 ↑上／↓下・1押し=1mm・押すと設定に保存されプレビューが即時に組み直される)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 印刷設定の微調整をプレビュー内で操作できるか。設定画面でやるとどれくらい移動しているかが分からない。</span><span class=\"lb\">対処</span><span class=\"tx\"><code>_layoutRenraku(htmlParts, ov)</code> に位置の上書き引数を追加。doPrint／doPrintBlank は setPrintHtml の detail に <code>adjust</code>(現在の x/y と apply(nx,ny))を同梱し、apply は systemSettings.renrakuOffsetX/Y を保存(silent)→同じ htmlParts を新しい位置で組み直して setPrintHtml を再発火(adjust も更新)。プレビューのヘッダー(App 直下)は detail.adjust がある時だけ「印刷位置 横 ←左 [値] 右→ 縦 ↑上 [値] ↓下 0に戻す」を表示(±10mm・カット線と穴あけ目印は動かない・従来の印刷設定画面の微調整も併存)。検証(Playwright・空印刷): 右→×2・↓下×1 で表示 +2/+1、iframe 内の translate(2mm,1mm)、保存値 [2,1]、0に戻すで translate 無し。vitest 16/Playwright 22/run_tests 16 PASS。安定版 0929e／試験版 trial95。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析\" data-text=\"分析 稼働 利用者属性 介護度内訳 円グラフ 合計 100% 98% 四捨五入 最大剰余法 未設定 介護度 未入力 事業対象者 要支援 要介護 計 0929e\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">分析(稼働)の介護度内訳が合計100%にならない(98%) → 介護度が未入力の方を「未設定」として表示し、割合は最大剰余法で合計100%に(要支援計・要介護計は項目%の合計)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29・スクショ): 介護度内訳で100%にならない原因は？(要支援1 15%・要支援2 34%・要介護1 19%・要介護2 22%・要介護3 7%・要介護4 1%＝98%、計36名49%＋36名49%)。</span><span class=\"lb\">原因</span><span class=\"tx\">①各項目の%を個別に四捨五入していたため合計が98〜102%になる(73名なら 15.07→15、34.2→34、19.2→19、21.9→22、6.8→7、1.4→1＝98)。②対象73名のうち1名は介護度が未入力(または一覧外)で、円グラフにも表にも出ず、その1.4%が合計から欠けていた(36＋36＝72≠73)。</span><span class=\"lb\">対処</span><span class=\"tx\">careLevelOrder に無い介護度の方を「未設定（介護度が未入力）」として円と表の最後に追加(clCountsAll)。割合は clPct(最大剰余法: 各項目を切り捨て→余りを小数部の大きい順に1%ずつ配分)で合計100%に固定し、円の内側%・外側の要支援%/要介護%・表の各行・「計」の%を全てそこから取る(計＝項目%の合計)。検証(Playwright・見本100名で1名を未設定に): 各行の%合計=100、計36名36%／63名63%、未設定1名1%。vitest 16/Playwright 22/run_tests 16 PASS。安定版 0929e／試験版 trial95。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳 ボタン 並び順 項目 連絡事項 次回予定 印刷設定 空印刷 プレビュー 全角 枚数 toHankaku 誤タップ 項目設定 カード onOpenConfig 0929d\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">連絡帳: ボタンの並びを「項目→連絡事項→次回予定→印刷設定→空印刷→プレビュー」に／空印刷の枚数は全角数字でも可／連絡帳カード(運動項目の表・事業所名)のタップで項目設定を開かない(誤タップ防止)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 空印刷の枚数設定を全角でも反映されるように(全角→半角でも可)。並び順を 項目・連絡事項・次回予定・印刷設定・空印刷・プレビュー に。項目はカードの項目の箇所をタップしても設定できたが誤タップが多いので「項目」ボタンだけで設定できるようにした方がよいか。</span><span class=\"lb\">対処</span><span class=\"tx\">①並び順を指示どおりに(「提供記録」への相互ジャンプは先頭のまま)。②空印刷の枚数 prompt を toHankaku→数字以外除去で全角対応(「３」→3枚を確認)。③ContactBookCard の運動項目の表(exBoxRef)と下部の事業所名から onClick={onOpenConfig}・cursor-pointer・hover を撤去し、項目設定は上部の「項目」ボタンからのみ(表の title に案内)。検証(Playwright): ボタン順「提供記録 > 項目 > 連絡事項 > 次回予定 > 印刷設定 > 空印刷 > プレビュー」、カードの表をクリックしても項目設定が開かない、空印刷で全角「３」→3ページ。vitest 16/Playwright 22/run_tests 16 PASS。安定版 0929d／試験版 trial94。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"サービス提供記録 月間表 印刷 見切れ 上 左右 縮小 余白 A4横 .tp zoom 0.92 印字不能域 複合機 TicketView 0929c\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">サービス提供記録(利用者ごとの月間表・A4横)の印刷で上と左右が見切れる → 用紙の内側に余白(上7／左右9／下6mm)を取り中身を0.92倍に縮小</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 提供記録を印刷しようとした時に上側と左右がちょっと見切れているので、全体的に縮小して全てが印刷されるように。</span><span class=\"lb\">原因</span><span class=\"tx\">TicketView の印刷CSSは用紙(.tp=297×210mm)に対して padding 2mm 4mm・@page margin 0 で、複合機の印字不能域(周囲4〜5mm)より内側に入っていなかった。</span><span class=\"lb\">対処</span><span class=\"tx\">印刷時(@media print)の .tp padding を 7mm 9mm 6mm 9mm に広げ、直下の中身に zoom:0.92 を掛けて用紙内に収める(印刷ルール: 外側=用紙要素・内側=余白)。画面のプレビュー表示は変えていない。検証(Playwright・print media): 用紙 297×210、中身の余白 左9／上7／右9／下17.8mm、2ページ。vitest 16/Playwright 22/run_tests 16 PASS。安定版 0929c／試験版 trial93。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳 空印刷 空の連絡帳 手書き 白紙 印刷設定 B5 B6 2面 1面 枚数 _layoutRenraku doPrintBlank 振替 表示されない アクシデント 備え 0929b\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">連絡帳に「空印刷」ボタン — 氏名・記録・次回予定が空欄の連絡帳を、印刷設定の用紙(B5横2面／B6縦／B5横1面)と位置の設定どおりに指定枚数印刷(表示されない方がいた時の手書き用)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 連絡帳に振替の方が表示されないアクシデントがあり今後も想定されるので、空の連絡帳を印刷できる空印刷ボタンを設置してほしい。B6かB5かは連絡帳の印刷設定を参照。</span><span class=\"lb\">対処</span><span class=\"tx\">ContactBookView の doPrint にあった用紙組み(2面: B5横257×182に2面・縮率0.64/0.62・穴あけ目印・カット線・微調整／1面: B6縦128×182 or B5横に縮率0.70/0.66・微調整)を <code>_layoutRenraku(htmlParts)</code> に切り出し、通常印刷と空印刷で共用。<code>doPrintBlank(sheets)</code>= 既存の余り面用カード <code>#print-content-cb-blank</code>(氏名/次回/連動/自由入力が空の ContactBookCard)を印刷カードとして描画→用紙の枚数×面数(2面なら1枚に2面)ぶん複製して同じ組みで setPrintHtml(題名「連絡帳(空)_日付」)。ボタン「空印刷」はプレビューの右(枚数は prompt・1〜20)。検証(Playwright): B5横2面で2枚→用紙2ページ(257×182)・B6縦1面で2枚→2ページ(128×182)、いずれも利用者名を含まない。マニュアル8章に追記しPDF再生成。vitest 16/Playwright 22/run_tests 16 PASS。安定版 0929b／試験版 trial92。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"提供記録\" data-text=\"月間スケジュール 提供記録入力 連動 総当たり 検証 振替 臨時 欠席 どちらで設定しても 反映 連絡帳 日誌 chk_sync_matrix 振替先 出席表記 記録だけの臨時 _matchesAmpm furikaeAmpm 0929a\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-29</span></div>\n      <p class=\"title\">月間スケジュール⇔提供記録入力の連動を総当たりで検証(振替・臨時・欠席 × 設定元2通り × 提供記録入力/連絡帳/日誌 × 午前/午後)。残っていた2件を修正: 月間の振替先が提供記録入力で「出席」表記／記録だけの臨時が提供記録入力・日誌に出ない</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-29): 提供記録入力で振替にしたら反映されるが月間スケジュールで振替にしたら反映されない、のようなことが起きないという認識でよいか。臨時も欠席も、どちらで設定しても反映されるようになったか。</span><span class=\"lb\">検証</span><span class=\"tx\"><code>scripts/chk_sync_matrix.mjs</code>(Playwright・見本): 同じ日に S1=月間だけ振替(AM・基本曜日外)／S2=月間だけ臨時(PM)／S3=月間だけ欠席(基本AM)／S4=記録だけ欠席(基本AM)／S5=記録だけ振替(AM・シフト無し)／S6=記録だけ臨時(PM・シフト無し)を仕込み、提供記録入力(検索して状態ボタン)・連絡帳・日誌の AM/PM で突き合わせ。修正前: S1 が提供記録入力で「出席」表記、S6 が提供記録入力 PM と日誌 PM に出ない(連絡帳は 0928p で対応済み)。他は一致。</span><span class=\"lb\">対処</span><span class=\"tx\">①提供記録入力の表示状態: 月間セルが '振替'(振替先)なら記録が無くても「振替」と表記(臨時と同じ位置。振替元の「振(M/D)」タグは欠席なので対象外)。②提供記録入力の AM/PM 絞り込み(rec.status==='振替' の furikaeAmpm 判定)と日誌の <code>_matchesAmpm</code> に臨時を追加(記録だけの臨時も区分で表示)。修正後の結果: 提供記録入力 AM=S1振替・S3欠席・S4欠席・S5振替／PM=S2臨時・S6臨時、連絡帳 AM=S1,S5／PM=S2,S6(欠席は非表示)、日誌 AM=S1,S3(欠席),S4(欠席),S5／PM=S2,S6。=どちらで設定しても同じ結果。検証スクリプトはリポジトリに常設(scripts/chk_sync_matrix.mjs・デモ build を 4173 で配信して実行)。vitest 16/Playwright 22/run_tests 16 PASS。安定版 0929a／試験版 trial91。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"提供記録\" data-text=\"出席 振替 臨時 3値 統一 連動 同期 提供記録入力 月間スケジュール 連絡帳 日誌 送迎表 体力測定 計画書 モニタリング 災害時 分析 個人ファイル 初回利用 isPlannedRec computeAttendingNow OperationDashboard 印刷 クレーム 0928q\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-28</span></div>\n      <p class=\"title\">出席判定を「出席・振替・臨時」の3値に全画面で統一 — 提供記録入力／月間スケジュールで振替・臨時にした人が、連絡帳以外(日誌の送迎コピー・災害時の通所中・稼働分析・個人の通所率と最新記録・初回利用日・計画書の予定件数)でも出席として連動するよう総点検</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-28): 提供記録入力と月間スケジュールをしっかり同期し、連絡帳以外でも日誌・送迎表・体力測定・計画書など諸々がちゃんと連動するよう改めて修正して。最後に印刷するときに慌ててバタバタし、クレームにもつながる。</span><span class=\"lb\">調査</span><span class=\"tx\">「振替を含むが臨時を含まない」出席判定(grep: '振替' あり・'臨時' なし)と「出席だけを見る」判定を全件洗い出し、画面ごとに扱いを確認。すでに3値対応済み: 提供記録入力の一覧(0928d)・日誌の載せる判定と出席数・体力測定の当日出席・送迎表(試験版)の _attendees・実績表(JissekiView)・個人ダッシュボードの通所率(validRecs/furikaeAtt)・月間スケジュールのセル保持(臨時は保持)・getNextVisitInfo・連絡帳(0928p)。未対応が残っていた箇所: ①isPlannedRec(計画書の予定件数) ②computeAttendingNow(災害時の通所中判定: 臨時の furikaeAmpm を見ていない) ③提供記録入力の並び順 rank・日付候補(schedAM/PM の状態配列・shiftComes・recComes) ④個人ダッシュボードの cValid(通所日の抽出)と showFullData(最新記録の全表示) ⑤稼働分析(OperationDashboardView)の _recWeight・planned/attended・AM/PM 別・利用者別の集計 12 箇所 ⑥連絡帳の補完(extraPats)の月間シフト「臨時」 ⑦個人ファイルの初回利用日・利用回数(通所/出席のみ) ⑧日誌の先週送迎コピーの対応付け(_matchG: 臨時の furikaeAmpm)と並び順。</span><span class=\"lb\">対処</span><span class=\"tx\">上記 ①〜⑧を全て 出席・振替・臨時 の3値に統一(振替と臨時は furikaeAmpm で午前/午後を判定、無ければ曜日・シフト→両方)。稼働分析は正規表現で `r.status==='出席'||r.status==='振替'` に臨時を一括追加(12箇所・既に臨時がある行は除外)。検証: 見本で A=月間振替(AM)、B=基本PMの人が状態=振替、C=月間臨時(PM)を仕込み、提供記録入力 PM の集計チップ「臨時1・振替1」、連絡帳 AM=A／PM=B,C を確認。esbuild/eslint no-undef 0/vitest 16/Playwright 22/run_tests 16 PASS。安定版 0928q／試験版 trial90。ガードレール: 出席判定は必ず3値。新しい一覧を作るときは isPlannedRec／computeAttendingNow と同じ判定を使う。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"連絡帳\" data-text=\"連絡帳 振替 臨時 表示されない 提供記録入力 午前 午後 絞り込み furikaeAmpm 基本利用曜日 月間シフト ContactBookView displayRecords ampmFilter 0928p\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-09-28</span></div>\n      <p class=\"title\">提供記録入力で「振替」「臨時」にした人の連絡帳が表示されない → 午前／午後の絞り込みを記録の区分(furikaeAmpm)で判定するよう修正・臨時も連絡帳の対象に</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-28): 提供記録入力で振替などに設定している人の連絡帳が表示されていない。</span><span class=\"lb\">原因</span><span class=\"tx\">ContactBookView の displayRecords は、記録を集めた後の午前／午後の絞り込み(filteredRecs)で「基本利用曜日(getScheduleOnDate)と月間シフト」だけを見ていた。基本曜日以外の日に振替・臨時で来た人は月間シフトが無ければ AM/PM とも「空欄」になり、絞り込みで落ちて連絡帳に出なかった(絞り込み無し=「全て」のときだけ出る)。さらに記録の収集(_rawRecs)は「出席」と「振〜」だけで、「臨時」は最初から対象外だった。</span><span class=\"lb\">対処</span><span class=\"tx\">①_rawRecs に status '臨時' を追加。②filteredRecs: 記録が振替/臨時で <code>furikaeAmpm</code>(または ampm)が AM/PM なら、その区分だけで判定(基本曜日・シフトは見ない)。区分の無い振替/臨時(基本利用日の人が状態だけ振替にした等)は従来どおり基本曜日・月間シフト(臨時の印も可)で判定し、どちらにも当たらなければ午前・午後の両方に出す(消えるよりは出す)。③並び順の rank で 臨時 を 振替 と同じ位置に。検証(Playwright・見本・9/28): A=月間で振替(AM)＋記録振替(AM)、B=基本利用日(PM)の人が状態=振替、C=月間で臨時(PM)＋記録臨時(PM)を仕込み、連絡帳 AM=A（Bは基本PMなので出ない）／PM=B,C／絞り込み無し=A,B,C を確認(修正前は A が AM でも出なかった)。vitest 16/Playwright 22/run_tests 16 PASS。安定版 0928p／試験版 trial89。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"モニタリング\" data-text=\"モニタリング 退所済み 対処済み 一度も来ていない 利用開始前 表示しない isPatientListable isPatientStartedByToday status 利用中 endDate LIFE 計画書 ご家族プレビュー 全画面 自動 PC Windows Mac 担当者選択 tsumugiAutoFullscreen 既定ON 0928o\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">モニタリング</span><span class=\"date tnum\">2026-09-28</span></div>\n      <p class=\"title\">退所済みの利用者がモニタリングの「一度も来ていない」欄に残る → 退所済みは利用者マスタ「退所済み」タブ以外の一覧に出さない(共通判定)・モニタリングは利用開始前も対象外／PC は担当者選択で自動全画面を既定ON</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-28): モニタリングで対処済み(=退所済み)の利用者が一番下の「一度も出席していない」欄にいるので表示しないで。まだ利用開始していない人も表示しなくていい。休止は表示して大丈夫。対処済みにしたら利用者マスタの「対処済み」以外に表示されないように。あと Windows/Mac の PC でログイン→担当者を選んだ後に自動で全画面にならない。</span><span class=\"lb\">原因</span><span class=\"tx\">退所は「利用終了日(endDate)を過ぎたか」で判定され status は '利用中' のまま残るため、<code>p.status === '利用中'</code> だけで絞る一覧(モニタリング・LIFE ハブ・機能訓練/生活機能/興味関心/通所介護計画・ご家族登録完了プレビュー・家族管理・計画期限集計)に退所済みが混ざっていた。自動全画面は端末設定 <code>tsumugiAutoFullscreen</code> が既定 OFF で、ON にしないと動かない仕様だった。</span><span class=\"lb\">対処</span><span class=\"tx\">共通判定 <code>isPatientListable(p)</code>(= !isPatientResigned && status が退所/終了でない)と <code>isPatientStartedByToday(p)</code>(startDate ≤ 今日)を追加。上記 11 箇所の一覧に <code>&& isPatientListable(p)</code> を付与し、モニタリングの対象(allActive)はさらに <code>isPatientStartedByToday</code> で利用開始前を除外(休止は従来どおりモニタリング対象外のまま)。自動全画面は <code>isAutoFullscreenOn()</code> を「'1'=ON／'0'=OFF／未設定=iOS 以外 ON」に変更し、設定画面の OFF は '0' を保存(iPad/iPhone は「ホーム画面に追加」で代替のため既定 OFF)。検証(Playwright・見本): 例示 花子に endDate=8/31、試作 清に startDate=12/1 を仕込むとモニタリング一覧のどちらにも出ない(デモは担当者選択ゲートが無いため全画面の呼び出しはコード確認のみ)。vitest 16/Playwright 22/run_tests 16 PASS。安定版 0928o／試験版 trial88。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"社外資料\" data-text=\"LP 事業所向け 紹介ページ lp.html 記録 連絡 共有 主な機能 提供記録 連絡帳 日誌 送迎表 モニタリング LIFE 災害時 導入の流れ ご家族向け ケアマネ向け A4 PDF lp-kazoku lp-kankeisha つむぎのご案内 lp_pdf.mjs\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">社外資料</span><span class=\"date tnum\">2026-09-28</span></div>\n      <p class=\"title\">紹介ページ /lp.html を通所介護事業所向けに作り直し、ご家族向け・ケアマネ向けは A4 表裏の案内 PDF(つむぎのご案内_ご家族向け／_ケアマネ向け)に</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-28): LP は事業所用のページに作り直して、利用者(ご家族)とケアマネは A4 PDF で作成して。</span><span class=\"lb\">対処</span><span class=\"tx\">①<code>public/lp.html</code>(事業所向け・レスポンシブ): ヒーロー「記録・連絡・共有を、ひとつに。」＋ホーム画面＋4指標／現場の手間3つ＋「提供記録→連絡帳・日誌→ご家族・ケアマネ→モニタリング・LIFE」の流れ／主な機能(提供記録・連絡帳・日誌・送迎表の4大画面＋モニタリング/計画書・LIFE提出支援・分析)／ご家族・ケアマネ連携(専用ページの内容と見本画面3枚・招待の方法)／災害時(速報バナー→安否と避難先→一斉送信、災害時画面)／導入の流れ4ステップ／データと運用の安心／FAQ5／お問い合わせ(support@ones-style.co.jp・ご家族/ケアマネ PDF へのリンク)。画像は既存の staff_*.jpg と sales_*.jpg。PC 1280px・iPhone13 で横スクロール無し。②<code>public/lp-kazoku.html</code>(A4×2・緑): 表=ヒーロー(イラスト枠)＋こんな思い3＋できること4(画面つき)、裏=災害時(イラスト枠＋3手順)＋スマホが苦手でも3＋登録3ステップ＋FAQ6＋安心＋CTA。③<code>public/lp-kankeisha.html</code>(A4×2・青): 表=ヒーロー(書類共有画面)＋役立つ場面3＋できること4、裏=事業所との情報のやりとり3＋災害時＋閲覧のしくみ3＋登録3ステップ＋FAQ6＋CTA。④<code>scripts/lp_pdf.mjs</code>(3資料を一括PDF化・A4超過チェック)。初回は 3ページが 6〜116px 超過→見出し余白・画像高さを調整して全ページ h=1123 に。横長スクショの切り出しは <code>object-position:left top</code>(中央だと左端の文字が切れる)。イラスト依頼プロンプト(docs/LP_イラスト依頼プロンプト.md)はご家族向け A4 用に更新。update-notes 0928n／trial87。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"次回のご利用予定 お迎え時間 大きく 日付の横 今回の記録 基本情報 折りたたみ タップで開く sec-next PersonalDashboardView nextVisit 0928m\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-28</span></div>\n      <p class=\"title\">ご家族・ケアマネ画面: 次回のご利用予定を「今回の記録」の上の緑枠に、日付の横に時間を大きく表示。基本情報は折りたたみ(タップで開く)に</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-28・スクショ): 時間は日付の横に表示して大きく。基本情報は常に折りたたんで展開したら見えるように。基本情報とは別に「今回の記録」の箇所に次回送迎日時を表示して。</span><span class=\"lb\">対処</span><span class=\"tx\">PersonalDashboardView に <code>basicOpen</code>(既定 false)を追加し、compactMode(ご家族・ケアマネ)では「基本情報」見出しをボタン(▼ タップで開く／▲ 閉じる)にして中身を折りたたみ(事業所モードは従来どおり常時表示)。次回の計算(<code>nextVisit</code>)は基本情報の内側から component レベル(main return の直前)へ移し、「今回の記録」枠の直前に <code>#sec-next</code> カード(緑枠・「次回のご利用予定」13px＋日付22px＋「お迎え <b>9時15分</b>(26px) 頃」・振替バッジ・徒歩は「徒歩でご来所」・未定は案内文)を表示。最初の移動先が Sparkline 内部関数の return に当たり ReferenceError(nextVisit is not defined)でご家族画面が ErrorBoundary に落ちたため、インデント最小の return を選ぶ方式に修正して再検証(家族: 9/30(水) お迎え 9時15分 頃・22px以上の文字3つ・基本情報は閉→クリックで開く／ケアマネ: 8時40分)。ガイド2種の文言も「通所記録の上部(緑の枠)」に更新。vitest 16/Playwright 22/run_tests 16 PASS。安定版 0928m／試験版 trial86。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"社外資料\" data-text=\"LP 紹介ページ lp.html ご家族 ケアマネ 50代 60代 スマホが苦手 離れていても グラフ 災害時 安否 避難先 登録3ステップ イラスト プロンプト ChatGPT 見本スクショ\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">社外資料</span><span class=\"date tnum\">2026-09-28</span></div>\n      <p class=\"title\">ご家族・ケアマネ向け紹介ページ(LP) /lp.html を作成 — 「離れていても、今日の様子がわかる。」を軸に、できること・災害時・スマホが苦手でも・登録3ステップ・ケアマネ向け・安心・FAQ。イラスト差し替え用プロンプト付き</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-28): マニュアル的な資料は登録後に見られるので、つむぎがどういうアプリで登録すると何が見られるかをイラストや実画面で視覚的に伝え、「使ってみたい・登録してみたい」と思わせる資料(LP)がほしい。血圧や気分がグラフで見える・距離が離れていても確認できる・災害時の避難状況も確認できる点を入れる。主な読み手は50〜60代のご家族なので「操作が難しそう・スマホに慣れていない」という抵抗を払拭する内容に。ケアマネにも状況が随時わかる・モニタリング・災害時を。イラストが難しければ ChatGPT 用のプロンプトを。</span><span class=\"lb\">対処</span><span class=\"tx\"><code>public/lp.html</code>(レスポンシブ・本文17px・見出し40px・つむぎ緑と生成り)。構成: ①ヒーロー「離れていても、今日の様子がわかる。」＋CTA「登録は3分・料金はかかりません」 ②こんな思いはありませんか(遠くて様子がわからない／血圧の変化が気になる／災害時に無事か知りたい) ③つむぎがあるとこう変わる(その日の様子・体調の変化がグラフ・お知らせと写真・ご家族3名で共有、各実画面つき。次回のご利用日とお迎え時間も明記) ④災害時(事業所が安否登録→ご家族へメールとお知らせ→在宅日は安否確認のお願い) ⑤スマホが苦手でも(操作は2ボタン・ホーム画面に追加・パスワード再設定、スマホ見本) ⑥登録は3ステップ ⑦ケアマネジャー向け6項目＋フェイスシート/保険証の画面 ⑧安心(同意・ID・閲覧専用/暗号化) ⑨FAQ5 ⑩CTA＋事業所名/電話の記入欄。イラストは2か所(ヒーロー・災害時)に簡易SVGを仮置きし、<code>docs/LP_イラスト依頼プロンプト.md</code> に ChatGPT 用プロンプト4本(hero/saigai/easy/cm・サイズ・配色・差し替え手順)を用意。Playwright で PC 1280px／iPhone13 とも横スクロール無しを確認。モーダル切り出し画像は <code>img{max-width:100%}</code> に阻まれて右が白くなっていたため <code>max-width:none</code>。update-notes 0928l／trial85。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"ご家族 ケアマネ 次回のご利用予定 お迎え時間 送迎時間 transportPlans getNextVisitInfo iso ampm 基本情報 徒歩 振替 0928k\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-28</span></div>\n      <p class=\"title\">ご家族・ケアマネ画面の「基本情報」に次回のご利用予定日とお迎え時間を表示(送迎表を保存済みの日はその時刻・徒歩は「徒歩でご来所」)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-28): 利用者家族やケアマネの画面に次回の送迎時間も添付させて。</span><span class=\"lb\">対処</span><span class=\"tx\"><code>getNextVisitInfo</code> の戻り値に <code>iso</code>(YYYY-MM-DD)と <code>ampm</code>(AM/PM)を追加(既存の呼び出しは date/time/isFurikae のみ使用のため影響なし)。PersonalDashboardView の compactMode(ご家族・ケアマネ)の基本情報の先頭に「次回のご利用予定」行: 日付(振替なら緑の「振替」印)＋「お迎え 9時15分 頃」。時刻は <code>appData.transportPlans[iso_ampm]</code> にその利用者の車の行があれば m.t(「9:15」→「9時15分」、「8:--」→「8時」)、徒歩欄なら「徒歩でご来所」、無ければ getNextVisitInfo の time(マスタの送迎時間→未設定曜日は施設のサービス提供時間の10分前→既定 8時/13時)。「　時　分」(柔軟)は「お迎え時間は事業所にご確認ください」。ご家族ポータルは app_state 全体を購読しているため transportPlans/monthlyShifts/holidays も参照可。検証(Playwright・見本): 月水金利用の見本で次回=9/30(水)、送迎表に 9:15 を仕込んだ家族側=「お迎え 9時15分 頃」、仕込まないケアマネ側=マスタ 8:40→「お迎え 8時40分 頃」。ご家族/ケアマネ向けガイドの「画面の見方」に追記しPDF再生成。vitest 16/Playwright 22/run_tests 16 PASS。安定版 0928k／試験版 trial84。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"iPad ホーム画面に追加 スタンドアロン PWA 開いた直後 ログイン画面 押せない 入力できない キーボード 出ない WebKit 279904 iOS 18 autoFocus タッチ検知 診断 Safari ツールバーを非表示 再現せず\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-09-28</span></div>\n      <p class=\"title\">iPad「ホーム画面に追加」で開いた直後からログイン画面のID・パスワードが押せない(Safariでは正常) → WebKit 既知不具合(PWAでキーボードが出ない)の可能性が高い。切り分け用にiOSの自動フォーカス停止＋タッチ検知表示を追加、当面はSafari＋ツールバー非表示を案内</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-28 追加報告): Safari のお気に入り/URL からは普通に使えている。その状態で共有→ホーム画面に追加し、ホーム画面から開くと、その時点で(最初のログイン画面から)何も入力できない。※前回の「担当者会議の後に固まった」報告の続報。</span><span class=\"lb\">調査</span><span class=\"tx\">①Playwright の WebKit(iPad 第7世代エミュレーション・navigator.standalone=true)で本番ログイン画面を開き、入力欄の中心の elementFromPoint=INPUT・大きな fixed 要素なし・reload ループなし・タップ→フォーカス→入力 \"abc\" 成功。=Web 側にオーバーレイやループは無く、エミュレーションでは再現しない。②ホーム画面アプリは Safari と保存領域が別なのでログイン画面から始まる(=Safari で「使えている」のはログイン済みだから。両者の差はスタンドアロン起動そのもの)。③既知不具合: WebKit Bug 279904「iOS 18 にすると、ホーム画面のWebアプリでテキスト入力をフォーカスしてもキーボードが出ない」(iOS/iPadOS 18.0〜18.1.1 で報告・散発的・Stage Manager との関連示唆・WebKit 側で再現できず未解決)、Apple Developer Forums 700736「iPad Home Screen Web App no keyboard」(iPadOS 15.5〜15.6.1・複数のPWAを開くと以後キーボードが出ない・端末再起動か Safari を開いて戻ると一時回復)。症状(入力欄が反応しない・パスキー/自動入力が出ない)が一致。</span><span class=\"lb\">対処</span><span class=\"tx\">安定版 0928i／試験版 trial82: (a) iPad/iPhone ではログイン画面の <code>autoFocus</code> を止める(起動直後のプログラム的フォーカスが WKWebView で固着する事例があるため。PC は従来どおり)。(b) スタンドアロン起動時だけログイン画面最下部に「アプリ版(ホーム画面) iOS x.y ／ タッチ検知 N回」を表示(document の pointerdown/touchstart をカウント)。画面をタップして回数が増えれば「タッチはJSに届いている(=Web側の問題)」、増えなければ「OS/WebKit 側でタッチ/キーボードが止まっている(=既知不具合)」と切り分けられる。(c) 案内: 当面は Safari で開き「ぁあ」メニュー→「ツールバーを非表示」でほぼ全画面にする。ホーム画面アプリを使う場合は iPad を再起動→一度 Safari を開いてからアプリを開く、直らなければホーム画面から削除して再追加。ユーザーへ iPadOS のバージョン・タッチ検知の増減を確認依頼。</span><span class=\"lb\">結果</span><span class=\"tx\"><b>ユーザー確認(同日): iPadOS 18.7.8。0928i 配信後「治った・タップ件数は増えている」</b>=ホーム画面アプリでログイン画面から入力できるようになった。決め手は iOS での起動直後 autoFocus 停止と判断(タッチ自体は届いていたため OS 側のタッチ不達ではなく、起動直後のプログラム的フォーカスで WKWebView の入力状態が固着していた)。同じ対策を 0928j／trial83 でご家族・ケアマネ向けのログイン画面と招待コード入力(?family の起動画面)にも適用。ガードレール: <b>iOS では画面を開いた直後の autoFocus を使わない</b>(<code>autoFocus={!_tsumugiIsIOSLike()}</code>)。残る autoFocus 19箇所は操作後に開くモーダル内のため対象外だが、iPad で「入力できない」報告があればまずここを疑う。診断表示(タッチ検知)は常設。vitest 16/Playwright 22/run_tests 16 PASS。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"社外資料\" data-text=\"営業用資料 A4 表裏 2ページ ご家族向け ケアマネ向け 画面の見方 よくある質問 ご利用にあたって 画像 大きく 省略 sales-onepager 4ページ 両面印刷\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">社外資料</span><span class=\"date tnum\">2026-09-28</span></div>\n      <p class=\"title\">営業用資料を A4 表裏(ご家族向け・ケアマネジャー向け 各2ページ)に拡充 — 表=大きな実画面＋できること＋はじめかた／裏=画面の見方＋よくある質問＋ご利用にあたって</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-28): 1枚だと画像が小さく情報も省略されすぎて見づらい。A4 の表裏で印刷する想定で、ご家族向けとケアマネ向けをそれぞれ作成してほしい。</span><span class=\"lb\">対処</span><span class=\"tx\"><code>public/sales-onepager.html</code> を4ページ(ご家族 表/裏・ケアマネ 表/裏)に。本文 12.5px・カード 11px・見出し 20.5px に拡大。ご家族 表=スマホ縦長(46mm幅)＋「今回の様子」47mm＋血圧グラフ 41mm＋できること6＋はじめかた3、裏=気分トレンド(全幅)・体温・お知らせ・家族一覧＋よくある質問8(マニュアル11章から)＋個人情報の取り扱い／困ったときは。ケアマネ 表=保険証・アセスメント／フェイスシート(モーダル中央を160%で切り出し 64mm)＋気分トレンド＋上部メニュー＋できること6＋はじめかた3、裏=通所記録・血圧・気分・関係者一覧＋「事業所との情報のやりとり」(ケアマネ→事業所／事業所→ケアマネ／担当の切り替え)＋よくある質問6＋守秘と同意／困ったときは。追加スクショ: 家族一覧・利用者/登録者情報・体力測定(sales_shots.mjs)。横長のカード画像は fixed-height＋cover だと左右が切れるため <code>.shot.nat</code>(自然な高さ)にし、モーダルは <code>object-position:center 42%</code>。<code>scripts/sales_pdf.mjs</code> の1ページ超過チェックで4ページとも h=1123=A4 に収めた(初回は 4ページ全て 44〜124px 超過→画像高さ・余白を段階調整)。PDF は4ページ(両面印刷で2枚)。update-notes 0928h／trial81。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"ホーム\" data-text=\"iPad ホーム画面に追加 スタンドアロン PWA 固まる 押せない 反応しない ログイン画面 パスキー 背景 自動リロード visibilitychange reload window.open 印刷 オーバーレイ 担当者会議 完全終了 アプリスイッチャー\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-09-28</span></div>\n      <p class=\"title\">iPad「ホーム画面に追加」で開いたつむぎが、担当者会議で使った後に画面のどこも押せなくなる(開き直してもログイン画面のID・パスワードが押せない)→ 背景中の自動リロードを復帰時に変更・印刷は別窓を開かず画面内で行うよう対策</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-28・iPad): ホーム画面に追加して最初は操作できたが、担当者会議で使った後に閉じようとしたらどこも押せなくなった。一度閉じて再起動しても反応せず、ログイン画面のID・パスワードが押せずパスキーの自動表示も出ない。サポートのメールアドレス(mailto)だけ押せた。</span><span class=\"lb\">原因(推定)</span><span class=\"tx\">実機ログが無いため断定はできないが、コード上で「背景中にページ遷移を起こす」経路が2つあり、いずれも iOS のスタンドアロン(ホーム画面)アプリでは固まる既知の挙動に該当する。①新しい版が配信されている時(当日は 0928d→e→f を配信中)、<code>visibilitychange=hidden</code> の1.8秒後に <code>window.location.reload()</code> していた(19795行)。iOS は背景化直後にページを一時停止するため、reload が途中で止まったまま復帰し、タッチが効かない画面になる。②iPad/iPhone の印刷は <code>window.open('', '_blank')</code> で別画面を開き、そこで印刷する方式(21083行)。スタンドアロンでは別画面がアプリ内ブラウザとして開き、閉じて戻った後に元画面が反応しなくなる報告が WebKit にある。mailto だけ押せたのは、リンクの遷移はネイティブ処理でJSのタッチ処理が止まっていても動くため。</span><span class=\"lb\">対処</span><span class=\"tx\">①iOS(iPadOS 13+ の MacIntel+タッチ判定含む)またはスタンドアロン(<code>navigator.standalone</code>／display-mode: standalone)では、背景化時は「更新待ちフラグ」を立てるだけにし、<code>visible</code> に戻った0.4秒後・編集中でない時に reload する(PC は従来どおり背景中に更新)。②iOS かつスタンドアロンの印刷は、別窓を開かず <code>#tsumugi-ios-print</code>(fixed・z 2000001)を body に追加し、印刷文書の body を <code>.tsumugi-ios-doc</code>(用紙幅)に入れて上部バーの「印刷 / PDF保存」で <code>window.print()</code>、「閉じる」で除去。印刷文書側の style は <code>html,body→.tsumugi-ios-doc</code>・<code>*{→#tsumugi-ios-print *{</code> に書き換えて画面全体へ漏らさず、<code>@media print{ body>*:not(#tsumugi-ios-print){display:none} }</code> でプレビュー画面や #root を印刷に写さない。Safari(非スタンドアロン)は従来の別タブ方式のまま。検証(Playwright・iPad UA＋standalone 疑似): 送迎表の印刷→オーバーレイ表示(用紙幅 1123px=297mm)・popup 0・print media で #root が none／バー非表示／文書表示・閉じるで除去・アプリ操作可。vitest 16/Playwright 22/run_tests 16 PASS。安定版 0928g／試験版 trial80。<b>固まった時の復旧</b>: iPad の画面下から上へスワイプしてアプリ一覧を出し、つむぎを上へ払って完全終了→開き直す(開き直しただけでは止まった画面が復元される)。再発時は「何をした直後か(印刷・別画面・閉じる)」を教えてもらう。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"社外資料\" data-text=\"営業用 1枚資料 ご家族向け ケアマネ向け sales-onepager スクショ 見本データ 血圧グラフ 気分トレンド 通所率 フェイスシート 保険証 アセスメント はじめかた 招待 PDF sales_shots sales_pdf\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">社外資料</span><span class=\"date tnum\">2026-09-28</span></div>\n      <p class=\"title\">営業用1枚資料(ご家族向け・ケアマネジャー向け・A4縦各1枚)を作成 — 見本データの実画面スクショ(グラフ入り)＋できること6項目＋はじめかた3ステップ</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-26 要望・9/28「次いこう」で着手): 「つむぎを使うとこれが見られる・できる」を実画面スクショで示す営業用1枚資料(ご家族向け・ケアマネ向け)。グラフが無ければグラフ画像も入れる。各1枚でも可。</span><span class=\"lb\">対処</span><span class=\"tx\"><code>public/sales-onepager.html</code>(A4縦2ページ・@page margin 0・つむぎ緑の配色)と PDF <code>docs/マニュアル・public/manual/つむぎご案内_ご家族向け・ケアマネ向け.pdf</code>。既存のマニュアル用スクショは見本の記録が期間外(6月)で「記録なし・通所率0%」だったため、<code>scripts/sales_shots.mjs</code> で直近34日の月水金に見本記録(体温・血圧・脈拍・気分・運動メニュー・特記)とお知らせ3件を投入して撮り直し(ご家族=スマホ(iPhone13)の「今回の記録」・PC の「今回の様子/今回の記録」カード・血圧(日別)グラフ・気分トレンド・通所率・お知らせ一覧／ケアマネ=保険証・アセスメント共有モーダル・フェイスシートモーダル・関係者一覧)。カード単位の要素撮影は「文字を含む末端要素から角丸の祖先まで遡って data-shot を付ける」方式。<code>public/manual/img/sales_*.jpg</code>(14枚・1400px)。ご家族面=見出し「デイサービスでの様子を、その日のうちにスマホで。」＋スマホ縦長1枚＋PC3枚＋できること6(その日の様子/グラフ/お知らせ/家族共有(代表者+2名)/どこでも(ホーム画面に追加)/安心(同意・ID・暗号化・閲覧専用))＋はじめかた3(招待メールか紙の案内→登録3分・コード3日有効→ログイン)＋事業所名・電話の記入欄。ケアマネ面=「担当のご利用者の通所状況を、電話をかけずに確認。」＋書類共有/フェイスシート/通所率/血圧グラフ＋できること6(記録閲覧/複数利用者切替/フェイスシート→マスタ反映/保険証・認定期間→自動反映/モニタリング表・休み連絡FAX/お知らせ・関係者管理)＋はじめかた3。1ページ収まりは <code>scripts/sales_pdf.mjs</code> が print media で .page の scrollHeight を検査(初回はご家族面が132px超過→画像高さを 41/35/25mm に固定・スマホは幅基準で切れ無し)。update-notes 0928f(安定)／trial79 へマージ。</span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 完成 確定 週 スナップショット _final 変更箇所 自動 赤丸 車 乗車順 時間 運転者 外れた 差分 印刷 週間 日別 再確定 前週コピー 付箋 手書き trial78\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-28</span></div>\n      <p class=\"title\">【試験版】送迎表: 週の「完成」確定と、完成後に変えた箇所(車・乗車順・時間・運転者・外れた人)の自動赤丸(画面・週間/日別印刷)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-26 要望・9/28「次進めて」で着手): 運用は週初め/週末に翌週分を印刷→手書き修正＋付箋。紙なら変更箇所が一目で分かるがアプリでは分からない。今は変更時の赤丸(TEL印)を手でタップしている。→ 週(または日)を「これで完成」として確定保存し、その後に変えた箇所に赤丸を自動で付けたい。</span><span class=\"lb\">対処</span><span class=\"tx\">ヘッダーに「この週を完成にする」ボタン(確認つき)。押すと表示中の週の全コマ(午前/午後×曜日)を保存し、各コマに <code>_final</code>(車ごとの pid と整形済み時刻・徒歩・その他・運転者のスナップショット)と <code>_finalAt</code> を控える。差分判定は <code>_chgOf(pl,pid)</code>(完成後に追加／車が変更／徒歩⇄車／時間が変更(旧→新)／乗車順が変更)・<code>_removedSince</code>(完成後に外れた人)・<code>_driverChg</code>(運転者変更)の3関数に集約し、画面は行の●(手動 m.mark と OR・ツールチップに理由)、徒歩/その他行の●、コマ見出しの「完成」「完成後の変更 N件」バッジ、コマ下の「完成後に外れた: 氏名」帯、ヘッダーの「完成 M/D HH:MM [変更N]」で表示。週間印刷(cellRow・徒歩行・完成後に外れた)と日別印刷(row・徒歩行・完成後に外れた)にも同じ●を出す(印刷側は plans を直接参照)。再度押すと今の内容で完成を更新(赤丸を付け直し)。前週コピーでは _final を引き継がない。ボタンは text-xs・nowrap にして 1366px でツールバーが2段にならないことを確認(高さ51px)。検証(Playwright): 2人を車に入れて完成→控え {cars:[2,0]}・バッジ「完成」12個・赤丸0→時間変更/徒歩へ移動/運転者変更で「変更3」・車行●1(理由「時間が変更（09:00→10:15）」)・徒歩●1→未割当へ戻すと「完成後に外れた」帯1→週間印刷に●2と「完成後に外れた」→再確定で赤丸0・帯0。vitest 16/Playwright 22/run_tests 16 PASS。trial78。</span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"データ一括エクスポート ZIP 説明文 提供記録 連絡帳 モニタリング 体力測定 含まれない 利用者基本情報のみ ケアマネ データ管理 ee36a79\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-09-28</span></div>\n      <p class=\"title\">各種設定→データ管理「データ一括エクスポート(ZIP)」の説明文が実態と不一致(提供記録・連絡帳・モニタリング等が入ると書かれているが、実際は利用者基本情報＋ケアマネのCSVのみ)→説明文を修正</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-28・急ぎではない): 一括エクスポートの ZIP に提供記録・連絡帳・モニタリング・体力測定などと書いてあるが、実際にダウンロードすると利用者の情報とケアマネの情報のみ。</span><span class=\"lb\">原因</span><span class=\"tx\">2026-06-28 の ee36a79 で一括エクスポートを「利用者基本情報＋ケアマネ事業所/担当者の CSV のみ」に意図的に簡素化(記録類は各画面から出力)した際、パネル冒頭の説明文「利用者情報・提供記録・連絡帳・モニタリング・体力測定・日誌・お知らせ・写真などを1つの ZIP に」が直されず残っていた(「含める項目」欄には「含まれません」と小さく書かれていた)。include.tickets 等のコードは残っているが UI から選べない。</span><span class=\"lb\">対処</span><span class=\"tx\">説明文を「利用者基本情報(緊急連絡先・ケアマネ事業所/担当者)を CSV で ZIP に」「記録類は各画面の印刷・PDF から」に修正(安定版 0928e・試験版 trial77 へマージ)。記録類込みの一括エクスポートは Obsidian 未来の修正点「実装予定」に登録(UI のチェック復活＋連絡帳/モニタリング/お知らせ/写真の追加、PDF 形式の重さ対策)。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 印刷 アイコン 週間 運行表のみ 連絡先一覧 待ち合わせ場所 日ごと チェックボックス 縦一列 プレビュー 用紙 分離 data-page-break くっついて 乗車にかかる時間 徒歩 walk 徒歩欄 自動 pickupMinutes trial76\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-28</span></div>\n      <p class=\"title\">【試験版】送迎表: 印刷ボタンのアイコン削除・週間は「運行表のみ／運行表＋連絡先一覧／連絡先一覧のみ」を選択・日ごとのチェックは縦1列・プレビューで用紙を1枚ずつ分離・乗車にかかる時間に「徒歩」(運行表の徒歩欄へ自動)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-28): ①印刷ボタンのアイコンは不要 ②日ごとのチェックボックスは縦一列に ③週間と日ごとの運行表で枚数が変わるごとに用紙を切り離してプレビュー(今はくっついている) ④週間を選んだら「運行表のみ／名前・住所・待ち合わせ場所も一緒／住所だけ」を選べるように ⑤乗車にかかる時間の一番下に「徒歩」を追加し、選んだ人は運行表でも自動的に徒歩へ。</span><span class=\"lb\">対処</span><span class=\"tx\">①Printer アイコン削除。②days のチェックを flex-col に。③プレビュー(previewSrcDoc の _pageSepCss)は <code>[data-page-break]</code> 等にしか白紙＋影＋間隔を付けないため、page-break-before だけで組んだ送迎表の用紙が繋がって見えていた→週間 _wrap／日ごと doPrintDays／単日 doPrintDay の用紙 div 全てに <code>data-page-break=\"1\"</code> を付与(印刷結果は不変)。④printModal に weekContent(sheet/both/contacts)のラジオを追加し doPrint(content) へ。従来の window.confirm は廃止。連絡先一覧(buildContactsPageHtml)の住所列に待ち合わせ場所（…）と［徒歩］を併記し見出しを「住所（待ち合わせ場所）」に。「連絡先一覧のみ」は題名「利用者連絡先一覧_週」で1枚。⑤送迎表の名前タップ編集と利用者マスタの「乗車にかかる時間」select に <code>value=\"walk\"</code>「徒歩（車を使わない・運行表は徒歩欄へ）」を追加。savePatientPickup は 'walk' を文字列のまま保存(数値計算は Number()||1 で従来どおり1分)し、今日以降の保存済み transportPlans で車・未割当にいれば徒歩欄へ移動(過去は不変)。下書き _attendees の _isWalk と getPlan の補充にも pickupMinutes==='walk' を追加。検証(Playwright): アイコン0・ラジオ3・チェック6件が同一x座標・日ごと2日で用紙2枚(top 14/1153・影あり)・週間＋連絡先で2枚(top 14/824)・連絡先のみ1枚(運行表なし)・車に入れた人を徒歩にすると徒歩欄へ移り車から消える・localStorage で徒歩にした人は再読込後の下書きで徒歩欄(未割当0)。vitest 16/Playwright 22/run_tests 16 PASS。trial76。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"送迎表 運転者 車名 右側 1行 同名 役職違い 重複 集約 normalizeName 印刷 週間 日ごと チェックボックス 選択した日 まとめて印刷 この日を印刷 氏名 6文字 セル幅 縮小 AutoFitLine 未割当 徒歩 マニュアル Android ホーム画面に追加 アプリをインストール 全画面 trial75\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-28</span></div>\n      <p class=\"title\">【試験版】送迎表: 運転者を車名の右に1行配置・同名(役職違い)は1件に・印刷を「週間／日ごと(チェックした日だけ)」で選択・氏名欄は約6文字幅で長い名前は縮小 ＋ マニュアルの全画面手順に Android を明記</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-28): ①全画面の説明が iPad 中心なので Android の手順も書く ②送迎表で車の名前の右側に運転者を配置 ③「この日を印刷」を5回押すのが手間なので、週間か日ごとかを選び、日ごとはチェックした曜日の分だけ印刷 ④氏名欄は6文字くらいが入るセル幅にし、超えたら縮小表示 ⑤運転者の候補に役職違いの同名が2件出るので1人分だけに。</span><span class=\"lb\">対処</span><span class=\"tx\">①事業所向けマニュアル1章の全画面 tip を「iPad・iPhone=Safari 共有→ホーム画面に追加」「Android=Chrome 右上メニュー(︙)→ホーム画面に追加／アプリをインストール」の具体手順に(安定版 c5cd9a6。家族/ケアマネ向けとアプリ内ヘルプは既に両方記載済み)。②【試験版】TransportView の車ヘッダを「車名｜運転者 select｜ナビ」の1行に(車名は max-w 45%・truncate、定員超過バッジ維持、高さ 27px)。⑤運転者候補は <code>_driverNames</code>(useMemo・日誌の担当職員から normalizeName+空白除去のキーで重複排除・臨時ヘルプ除外)。保存値は氏名文字列のままなので既存データ互換。③ヘッダーの印刷ボタンをモーダル「送迎表を印刷」に: 週間(A4横・1枚=従来の doPrint)／日ごと(A4縦・1日1枚)を選び、日ごとは表示中の曜日のチェックボックス(すべて／解除つき)で選んだ日だけ <code>doPrintDays</code> が buildDailyPrintHtml(iso) を page-break で連結(余白2段 210×296/188×275mm を踏襲・題名「運行表_日付_他N日」)。各日の「この日を印刷」も従来どおり残す。④車内・徒歩・その他・未割当の氏名を AutoFitLine(maxWidth 6.6em・約6文字)に置き換え、超える名前は1行のまま縮小(overflowWrap による折り返しを廃止)。検証: デモで同名3件(管理者/生活相談員/介護職員・全角空白違い)→候補1件、4文字名は等倍(幅106px)、13文字名は 0.54 倍で1行・行高19px、日ごと印刷で2日選択→2ページ(page-break 1)。esbuild/eslint no-undef 0/vitest 16/Playwright 22/デプロイ後 run_tests 16 PASS。trial75。</span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"PWA manifest standalone ホーム画面に追加 全画面 自動全画面 iPad スワイプ 日誌 担当職員 氏名のみ 不在時 撤回 各種設定 職員行 区切り 資格 右側 通常表示に戻る サイドバー INP 送迎表 行間\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-09-28</span></div>\n      <p class=\"title\">「ホーム画面に追加」で全画面のアプリとして起動（PWA化）＋担当者選択での自動全画面（端末設定）＋日誌は氏名のみ・設定の職員行を区切り表示・提供記録の「通常表示に戻る」でサイドバーを開かない</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー(2026-09-28): ①Chrome の「INP Issue」表示は何か(=送迎表の配車計算ボタンの処理が1.3秒画面を止めたという開発者向け通知。エラーではない) ②日誌の小さな四角(不在時印)と資格は不要、不在時は撤回 ③送迎表の行間をもっと詰める ④各種設定→日誌の役職・氏名・資格を区切り、資格は右側に ⑤提供記録入力の全画面から「元に戻す」でサイドバーが出るのは不要 ⑥ログイン時から全画面にしておくべきか、毎回押すのは面倒 ⑦iPad の全画面が下スワイプで終了してしまうのを止められるか。</span><span class=\"lb\">対処</span><span class=\"tx\">②日誌の StaffBox は氏名のみに戻し(不在時バッジ・資格・区切り線を除去)、副役職の人の掲載と画面での高さ可変は維持。④各種設定→日誌の職員行を「役職(主・副)｜姓・名｜資格1・2」の縦線(border-r-2)区切りで1行に(幅を 122/116/84/84/150/150px に調整し1000px幅で折り返さないことを確認)。⑤RecordView の全画面解除時に setIsSidebarOpen(false)。⑥⑦<b>PWA化</b>: public/manifest.json(display:standalone・start_url /・アイコン既存512px)と index.html に link rel=manifest／apple-mobile-web-app-capable／mobile-web-app-capable／status-bar-style／theme-color を追加。iPad・iPhone・Android は「ホーム画面に追加」で起動するとブラウザUIの無い全画面になり、Safari の全画面APIと違って下スワイプで終了しない(Web側からスワイプ終了は止められないため、これが正解)。PC は「ページ読込時の自動全画面」がブラウザ制約(ユーザー操作内でのみ可)で不可のため、各種設定→システム→「この端末の表示」に端末設定 <code>tsumugiAutoFullscreen</code> を追加し、担当者選択のクリック内で requestFullscreen(既定OFF)。③【試験版】送迎表の利用者行 min-h 34→28px・py 0。①INP は Chrome DevTools/Web Vitals 拡張の通知で店舗には出ない。計算処理の分割は未来の修正点に記録。マニュアル(1章・9章・各種設定)更新・PDF再生成。vitest 16/Playwright 22/run_tests --deployed 16/16。安定版0928d/試験版trial74。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f71a397</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"日誌\" data-text=\"担当職員 役職 資格 追加 customRoles customQuals 不在時 副役職 日誌 表示 区切り線 全画面 フルスクリーン 送迎表 行間 免許 除外\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-28</span></div>\n      <p class=\"title\">担当職員の続き: 役職・資格の店舗追加／副役職の人を日誌の該当欄に「不在時」印で表示／資格は画面で氏名の下・区切り線／「全画面」ボタン／送迎表の行間（試験版）</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー指摘(2026-09-28): ①送迎の免許は資格に不要 ②役職と資格を店舗で追加できる画面が欲しい ③副役職で管理者を選んだ人は日誌の管理者欄にも載せ、2名並ぶ場合は「不在時」等の記載で区別 ④PC表示では資格を名前の右に、役職・名前・資格の区切りを分かりやすく ⑤送迎表の利用者名の行間が広い ⑥動画の全画面のようにタブ・URL欄・タスクバーを隠して画面を広く使いたい。</span><span class=\"lb\">対処</span><span class=\"tx\">①STAFF_QUALS_COMMON から普通自動車免許を除外。②各種設定→日誌→担当職員の下に「役職・資格の追加」(diarySettings.customRoles[]／customQuals[{name,role}]、保存の _dsKeep 対象に追加)。役職プルダウンは3か所(日誌設定・サイドバー追加/編集・ログイン追加)とも <code>staffRoleChoices(appData)</code> で店舗追加分を含める(ログイン追加フォームには roleChoices prop)。資格候補は <code>staffQualOptions(role, role2, customQuals)</code>。追加した役職はログイン/スタッフ切替では「その他」枠。③日誌の役職欄は <code>_byRole(role)</code> で主役職＋副役職(role2)の人を集め、副で載る人は _sub=true→「不在時」バッジ(画面・印刷とも)。④画面(PC)は氏名の右…は枠が狭く氏名が折れたため、最終的に「氏名の行は折り返さず、資格は氏名の下に小さく(className=no-print・印刷には出さない)」に。職員ごとに縦の区切り線。枠の高さは画面では内容に合わせて伸ばし(isPrintPreview のときだけ従来の30px固定)、管理者2名時は管理者枠を広く。⑥ヘッダーに「全画面」ボタン(document.documentElement.requestFullscreen／もう一度押すかEscで戻る。非対応(iPad Safari等)は「ホーム画面に追加」を案内)。マニュアル1章にも記載。⑤【試験版】送迎表の利用者行 min-h 44→34px・py 1→0.5、未割当行 py 0。デモで Playwright: 日誌に「不在時」と資格が出る／設定に追加役職・資格チップ／役職プルダウンに追加役職／全画面ボタン。vitest 16/Playwright 22/run_tests --deployed 16/16。安定版0928b→0928c/試験版trial72→73。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a50a6b7</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"日誌\" data-text=\"担当職員 副役職 保有資格 2つ 職種別 介護福祉士 社会福祉士 理学療法士 看護師 STAFF_QUALS_BY_ROLE 勤務体制一覧表 スタッフ切替\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-28</span></div>\n      <p class=\"title\">日誌の担当職員に「副の役職（2つ目）」と「保有資格（役職に合った候補から2つまで）」を追加</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー要望(2026-09-28): 日誌の担当職員で役職・名前・保有資格を2つまで選べるように。資格は介護職で使えるものを全て調べてプルダウンに、ただし介護職員に看護師資格は出ないなど役職に合ったものだけ。管理者不在時に別の人が管理者や生活相談員を務めることがあるので役職も2つまで。区提出の勤務体制一覧表を自動作成する下準備。</span><span class=\"lb\">対処</span><span class=\"tx\">データ: diarySettings.staff に role2(副役職)・quals[2](資格)。資格候補は役職別 <code>STAFF_QUALS_BY_ROLE</code>(管理者: 介護福祉士/社会福祉士/精神保健福祉士/社会福祉主事/実務者研修/初任者研修/看護師/准看護師/PT/OT/ST/柔道整復師、生活相談員: 社会福祉士/精神保健福祉士/社会福祉主事/介護福祉士/実務者/初任者/保育士(自治体要件)、機能訓練指導員: PT/OT/ST/看護師/准看護師/柔道整復師/あん摩マッサージ指圧師/はり師/きゅう師(実務6か月)、看護職員: 看護師/准看護師/保健師/助産師/認定看護師/特定行為研修、介護職員: 介護福祉士/認定介護福祉士/実務者/初任者/旧ヘルパー1・2級/旧基礎研修/生活援助従事者研修/喀痰吸引等研修1・2号/3号/介護事務)＋全役職共通 <code>STAFF_QUALS_COMMON</code>(介護支援専門員/主任介護支援専門員/認知症介護 基礎・実践者・実践リーダー・指導者/認知症ケア専門士/福祉用具専門相談員/介護予防運動指導員/レクリエーション介護士/防火管理者/普通自動車免許)。候補は主＋副の役職の和集合(<code>staffQualOptions</code>)、同じ資格を2つ選べない。UI: 各種設定→日誌→担当職員の行を「主役職／副役職／姓／名」＋「保有資格1・2」の2段に。保存時に role2===role は空へ。storeMembers 同期(管理者の再生成分含む)へ role2/quals を乗せ、ログインの担当者選択とスタッフ切替に <code>staffRoleText</code>「管理者／生活相談員」で併記。デモで「介護職員の候補に看護師が無い・介護福祉士がある」「副=生活相談員・資格2件が保存され storeMembers にも反映」を確認。マニュアル各種設定章に追記・スクショ再撮影・PDF。vitest 16/Playwright 22/run_tests --deployed 16/16。安定版0928a/試験版trial71。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e6f0d66</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"ログイン どなたですか スタッフ切替 職種別 管理者 機能訓練指導員 生活相談員 介護職員 看護職員 groupStaffByRole\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-09-27</span></div>\n      <p class=\"title\">ログインの「こんにちは、どなたですか」とサイドバーのスタッフ切替を職種別に表示</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー要望(2026-09-26 まとめ): 今は登録順に並んでいるので、管理者・機能訓練指導員・生活相談員・介護職員・看護職員のように分けて表示すると見やすい。サイドバーのスタッフ切替も同様に。</span><span class=\"lb\">対処</span><span class=\"tx\">モジュール共通の <code>groupStaffByRole(members)</code>(並び: 管理者→機能訓練指導員→生活相談員→介護職員→看護職員(内部値は看護師)→その他。isAdmin で roleLabel 未設定の人は管理者扱い)を追加し、RecorderPickerGate(ログイン後の担当者選択)は職種ごとの見出し＋人数＋カード群、サイドバーの切替ドロップダウンは職種の見出し行を挟んで表示。各グループ内の順序は従来どおり。デモで見本職員6名を投入し、ドロップダウンの並びが「管理者→機能訓練指導員→生活相談員→介護職員→…」になることを確認。マニュアル5章にスクショと説明を追加(manual_shots は担当者選択済みの状態をシード)。vitest 16/Playwright 22/run_tests --deployed 16/16。安定版0927g/試験版trial70。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f84ffe8</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"絵文字 除去 フリガナ 表記統一 ケアマネ カレンダー 週表示 sticky 日付固定 余白\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-09-27</span></div>\n      <p class=\"title\">装飾絵文字の全面除去（タップして使うもの以外）＋ ケアマネ画面の「フリガナ」表記統一 ＋ 週表示の日付行を固定</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー指摘(2026-09-27): 新機能追加のたびに「印刷などのボタンに絵文字は要らない」と伝えていたのに入っている箇所がある。タップして使うもの以外の不要な絵文字は全て取り除く。ケアマネ画面の「ふりがな」は「フリガナ」に。週表示はスクロールしても日付が固定されるように、2段目(終日)の隙間は詰めてよい。</span><span class=\"lb\">対処</span><span class=\"tx\">App.jsx の絵文字を機械的に洗い出し(モジュール全体・コメント除外)、装飾用を除去: 📱❓(ヘルプ見出し/ボタン)・⏳(送信中/保存中/見出し)・❌✅(結果表示/alert/大アイコン)・📣🚨📜📎📋🔔⛶⏰🆕(見出し/option/ボタン)。通知の重要度アイコンは文字ラベル(重要/注意/お知らせ)、誕生月の👑は文字バッジ(「誕」「誕生月」)、FAX結果の✅❌は「成功/失敗」。残したのは操作対象のみ: 気分選択(😊😐😞😫🤩)とカレンダーの誕生日/注意アイコン(タップで一覧)。記号(✓✕⚠)は維持。マニュアル3種の装飾絵文字(58個)も除去しPDF再生成。ケアマネ事業所・担当者の「ふりがな」表記(編集/追加モーダル・並び順の注記・未登録表示)を「フリガナ」に。週表示は日付＋終日の行を position:sticky(top:0)で固定(横スクロールの入れ物を外した)、日付行の padding と終日行の最小高を詰めた(デモで400pxスクロール後も行が画面上部に残ることを確認)。ガードレールに「絵文字はタップして使うもの以外入れない・締めに新規行の絵文字チェック」を追記。追記(6d5fcc4・ユーザー報告): 固定した日付行に予定が透けて見えた→sticky の top を「ヘッダー下端−スクロール領域の上端−内側余白」の実測(ref＋resize/scroll)にし、Chrome がスクロール領域の padding 分だけ sticky を下げる挙動を補正(デモで header bottom=110px と行 top=110px の一致を確認)。カレンダーの誕生日👑・要注意⚠️も文字バッジ(誕/誕生日・注/要注意・タップ機能は維持)に、⚠️ の見出し/メッセージ9箇所も除去。安定版0927f/試験版trial69。vitest 16/Playwright 22/run_tests --deployed 16/16。安定版0927e/試験版trial68。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a57237e</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"スケジュール/提供記録\" data-text=\"カレンダー 週表示 区切り線 時間 日付 終日 折り返し 月表示 横幅 1480 2行 4件\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">スケジュール/提供記録</span><span class=\"date tnum\">2026-09-27</span></div>\n      <p class=\"title\">カレンダー: 週表示に時間・日付の区切り線、終日の予定は折り返して全文表示、月表示を横に広げて内容が読めるように</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー要望(2026-09-27): 週表示で時間と日付を区切る薄い線を足す。終日の予定は内容が全て見えるよう折り返す。月表示はもう少し横を伸ばして予定の内容が見えるように。</span><span class=\"lb\">対処</span><span class=\"tx\">ScheduleView: 週表示の各日列に1時間ごとの横線(#e2e8f0・pointerEvents:none)と列の縦線(#f1f5f9→#e2e8f0)、時刻列に右罫線。終日行の予定は nowrap/ellipsis をやめ whiteSpace:normal＋overflowWrap:anywhere で全文表示(高さは内容に応じて伸びる)。月表示はコンテナ maxWidth 1000→1480、セル minHeight 78→96、予定は -webkit-line-clamp:2 で2行まで折り返し・4件まで(5件目以降は「他N件」)。追記(74bafc2・ユーザー指摘): 30分の予定(担当者会議)で利用者名の2行目が切れていた→週表示の1時間の高さを42→64px、予定の最小高を28pxに(デモで17:10〜17:40の予定に「／利用者名」まで表示されることを確認)。安定版0927d/試験版trial67。デモで見本予定を入れて週/月のスクショと折り返し(whiteSpace:normal・高さ41px)を確認。vitest 16/Playwright 22/run_tests --deployed 16/16。安定版0927c/試験版trial66。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">636582f</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"アカウント管理 招待一覧 チラつき familyInvites code 和集合 ポーリング storage 紙で招待 印刷する postMessage 印刷待ち 印刷済 取り消し 担当者タグ patient_name 再読み込み ポップアップ 外側\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-27</span></div>\n      <p class=\"title\">アカウント管理の招待一覧がチラつく／紙の招待は「印刷する」で有効化・「紙で招待済み」表示・再読み込み後も残る・取り消しボタン</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">店舗報告(2026-09-27・画面写真): 招待を出した後、アカウント管理の一覧が「招待あり」と「未発行」を交互に表示し続ける(以前からあり、メール送信後に始まる)。紙で招待を押しただけでケアマネの担当者カードが「招待メール済み」になる。再読み込みすると「登録待ち」が消える。間違えて印刷した時の取り消しが欲しい。</span><span class=\"lb\">対処</span><span class=\"tx\"><b>チラつきの真因</b>: familyInvites は app_state に保存されない(sanitizeForSync で除外)ためローカル＋family_invites テーブルの二本立て。アカウント管理の10秒ポーリングはクラウド行を id で突き合わせていたが id 体系が別(ローカル inv_xxx／クラウド uuid)で毎回「不一致」→ローカルの招待を消す→次の取得で復活…を繰り返していた。別タブからの storage 同期も一覧を丸ごと置換していた。修正: ポーリングは <b>code</b> で突き合わせてローカルの id・経路・印刷済み等を保持し、クラウドに無いローカル招待(発行直後・印刷待ち・登録失敗)は消さない(_localOnlyInv)。storage 同期は code の和集合。<b>紙の招待</b>: クラウド登録を用紙の「印刷する」(postMessage tsumugiInvitePrinted・モジュール共通の受け口)まで遅らせ(deferCloud)、押した時点で printedAt/channel=paper を刻む。一覧に「紙（印刷待ち）／紙（印刷済）／メール／コード」バッジ。<b>ケアマネ担当者カード</b>: 「紙で招待済み／招待メール済み／コード発行済み・登録待ち」を区別、「取り消し」(ローカル＋クラウドの未使用招待を削除)、再読み込み後も残るようクラウド行の patient_name に「担当者招待: 事業所/氏名」タグを入れて照合(列追加なし)、supabaseListCmInvitesForStore の select に code/patient_name。印刷通知は後から届くため最新 appData の ref で保存(古い閉包で発行直後の招待を落としていた不具合をデモで検出・修正)。用紙の onclick 属性内で JSON.stringify を使うと属性が壊れる→単引用符に。あわせてカレンダー予定入力／休止履歴編集／休業日編集／職員追加のポップアップを外側タップで閉じないように(ユーザー指示)。検証: デモで Playwright(印刷待ち→印刷済／CM なし→紙で招待済み→取り消し→なし／カレンダー外側クリック)、vitest 16/Playwright 22/run_tests --deployed 16/16。安定版0927b/試験版trial65。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2910424</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"招待 紙で招待 印刷 案内用紙 共通の登録用紙 招待コード 数字8桁 有効期限3日 ロック 5回 15分 再発行 ログイン画面 招待コードをお持ちの方 join=1 セキュリティ\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-27</span></div>\n      <p class=\"title\">ご家族・ケアマネ招待の刷新: 紙で招待（A4案内用紙）・共通の登録用紙・数字8桁コード・有効期限3日・連続失敗ロック・再発行・ログイン画面からのコード入力</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー決定(2026-09-27): エリア担当者会議で「メールを聞いて送るより、招待QR/コードを印刷して渡す方が楽」との意見。承認制(氏名＋生年月日で自己申請)も検討したが「個人情報のセキュリティを第一」に、現行の「招待コード＝秘密」方式を維持して印刷を足す方針に決定。あわせて有効期限は14日→3日(メールも)、コードは打ちやすい数字8桁に、共通の用紙はコードを職員が手書きし、ログイン画面に新規登録の入口を置く。</span><span class=\"lb\">対処</span><span class=\"tx\">①<code>generateOneTimeInviteCode</code> を数字8桁(先頭1〜9・4-4区切り)に。<code>normalizeInviteCode</code>(logic.js)は数字だけの入力を 1234-5678 に整形、旧 FAM 形式は従来どおり(テスト5件追加)。②<code>INVITE_VALID_DAYS=3</code>／<code>inviteExpiresAtIso()</code> に統一(家族招待・ケアマネ招待・家族側の家族追加招待・API既定文言・mailto本文・マニュアル3種・エリア担当者資料)。③端末側ロック <code>inviteLock*</code>(localStorage・5回失敗で15分。5回目の失敗時点でロック文言)。サーバー側(family_invites の anon SELECT)の総当たり対策は未着手→未来の修正点。④ログイン画面に「招待コードをお持ちの方（新規登録）はこちら」。押すと<b>コード確認ステップ</b>(joinStep='code')→この端末の familyInvites にあれば登録フォームへ(email/続柄を引継ぎ)、無ければ <code>supabaseGetInviteByCode</code> で照合し、見つかれば <code>encodeInviteToken</code> で招待URLを組み立てて遷移(店舗データ取得・自動入力・登録処理は既存の招待URLフローに合流＝登録処理を二重に作らない)。patient_id は文字列なので Number 化。共通用紙のQRは <code>?family&join=1</code> でこのステップから開始。⑤<b>紙で招待(印刷)</b>: <code>openInviteSheet(kind: family|cm|common)</code> でA4案内用紙(事業所名・宛名・QR・招待コード大表示・有効期限・手順3つ・「1人・1回」「第三者に渡さない」の注意枠・ログインID/PW/登録日/登録者名の手書き欄・店舗TEL)。利用者マスタ アカウント管理に「紙で招待（印刷）」と各招待行の「印刷」、共通ログインURLの横に「共通の登録用紙」(コード欄は空白)。ケアマネ事業所・担当者の担当者カードに「紙で招待（印刷）」(招待発行を <code>_issueCmInvite</code> に共通化しメール送信と共用)。⑥期限切れ・未使用の招待に「再発行」(旧コードを Supabase からも削除→新コード3日→メール宛先があれば再送、無ければ用紙印刷)。期限切れ/不明のエラーに店舗TEL(<code>_facTel</code>)。⑦マニュアル: 事業所向け19章に「紙で招待する／共通の登録用紙／再発行／安全のための仕組み」、ご家族・ケアマネ向けに「紙の案内用紙をもらった場合」、有効期限の記述を3日に。スクショ(staff_master_account/staff_cm_invite)再撮影・PDF4本再生成。検証: esbuild/eslint no-undef 0/vitest 16/Playwright 22/デモで Playwright(用紙生成にコード・注意書き・控え欄・期限、共通用紙に join=1、入口ボタン、誤コード5回でロック文言、手入力→フォームにコード/続柄が入る、join=1で確認ステップ開始)/run_tests --deployed 16/16。安定版0927a/試験版trial64。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ad258aa</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳 印刷位置の微調整 矢印 左右上下 表記 左 −3 下 +2\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-09-25</span></div>\n      <p class=\"title\">連絡帳の印刷位置微調整: ボタンを「← 左／右 →」「↑ 上／↓ 下」に、現在値を方向つきで表示</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー指摘(2026-09-25): 横−/＋・縦−/＋ではどちらへ動くか分からない。方向名と符号つき数値の方が分かりやすい。</span><span class=\"lb\">対処</span><span class=\"tx\">印刷設定の微調整ボタンを「← 左」「右 →」「↑ 上」「↓ 下」(1押し=1mm)にし、現在値は「0（中央）」「左 −3」「右 +3」「上 −2」「下 +2」と表示。「0に戻す」ボタン。内部値(renrakuOffsetX 右+/Y 下+)は不変。案内文とマニュアル8章を更新。安定版0925c。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">048d55c</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】送迎表 列幅 236px 月〜金1画面 日付ジャンプ削除 8:-- _fmtT 8時　分 扇橋 連絡帳への反映 getTransportTimeFor\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-25</span></div>\n      <p class=\"title\">【試験版】送迎表: 列を詰めて月〜金を1画面に・上部の日付ボタン削除・「8時　分」を「8:--」に統一（扇橋だけ違って見えた原因）</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー指摘(2026-09-25): ①扇橋の送迎表だけ「8時　分」で \"8:\" 形式になっていない ②名前とお迎え時間の間を詰めてサイドバーを閉じたら月〜金が1画面に ③上部の日付選択は不要 ④送迎表を設定したら連絡帳に自動反映される認識で合っているか。</span><span class=\"lb\">対処</span><span class=\"tx\">①原因: 利用者マスタのお迎え時間が他店は \"8:00\" 形式なのに対し扇橋は \"8:--\"(時のみ登録・98/102件)。getPickupTimeForDow が「8時　　分」に変換して送迎表へ渡すが、_fmtT の正規表現が空白入りを認識せず生表示していた(扇橋固有ではなく「分が未入力」固有)。_fmtT を空白除去して解釈する形に(「8時30分」→8:30／「8時　分」「8:--」→8:--／自動算出の「8時」→8:00／空欄→空)、_tMin も \"--\" 対応。②グリッド列 minmax(280→236px)・隙間12→8・外周 p-3→p-2・印ボタン w-8→w-6・時刻入力 w-16→58px。デモ(1366px・サイドバー閉・月〜金)で scrollWidth==clientWidth(横スクロール無し)を機械確認。③日付ジャンプ行(9/21〜9/25ボタン)を削除。④確認結果: 反映は getTransportTimeFor(appData.transportPlans)経由で、その日の運行表を一度でも操作して保存(silent onSave)した場合のみ。未操作の自動下書きは反映されない(マニュアル 送迎表章に追記)。検証: esbuild/eslint no-undef 0/vitest 15/Playwright 24/run_tests --deployed 16/16。試験版trial62→trial63。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">76b00b2（trial）</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"臨時利用 提供記録入力 日誌 状態を臨時と表記 statusOptions 臨時 水色 休止残骸の正規化順 連絡帳 氏名 1行 AutoFitLine 様 折り返し\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-25</span></div>\n      <p class=\"title\">臨時利用の方は提供記録入力・日誌で「臨時」と表記（扱いは出席のまま）＋ 連絡帳の長い氏名を1行に</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー指示(2026-09-25): 臨時利用した場合は提供記録入力や日誌で「出席」ではなく「臨時」と表記してほしい(扱いは出席のまま)。連絡帳の氏名が長いと「様」が折り返して2行になる→1行に。</span><span class=\"lb\">対処</span><span class=\"tx\">①appSettings.statusOptions に 臨時(cyan)を追加(状態セレクト・色・getStatusConfig が使う)。提供記録入力の seed(filtered.map)で月間セルが '臨時' なら status を '臨時' に。<b>落とし穴</b>: 最初は existingRecord 反映の直後に置いたが、見本データでは当日に '休止' の残骸記録があり「休止残骸→出席」の正規化が後で走って 出席 に戻された(デモで select 値が 出席 のままなのを RINJI-DBG ログで特定)→ 正規化の後(休業日処理の前)へ移動。人数チップ attCounts に 臨時、日誌の状態色に 臨時(#0e7490)、日誌の休業上書き(_applyKyugyo)にも 臨時。デモで「今日を臨時利用→提供記録入力の select 値が 臨時(選択肢 出席/臨時/欠席)・日誌の行が 臨時」を Playwright で確認。②ContactBookCard のヘッダーを flex+nowrap にし氏名を AutoFitLine(幅に合わせ縮小)、「様」と日付は shrink-0。マニュアル8・16章追記・PDF再生成。検証: esbuild/eslint no-undef 0/vitest 15/Playwright 22/run_tests --deployed 16/16。安定版0925b/試験版trial61。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">225d16e</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"臨時利用が提供記録入力・日誌に出ない その場で保存 displayRecords AM/PM絞り込み 臨時 日誌 _monthlyComingKind 日誌の氏名 AutoFitLine 上綴じ目印1つ カット線固定\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-09-25</span></div>\n      <p class=\"title\">「臨時利用」が提供記録入力・日誌に出ない（その場保存＋絞り込み2箇所）／日誌の長い氏名を縮小全文表示／上綴じ目印1つ・カット線を用紙中央に固定</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">店舗報告(2026-09-25): 月間スケジュールで11日を臨時にしたが、サービス提供記録入力にも日誌にも出ない。あわせて①日誌の氏名が長いと「…」になる→縮小して全文表示、②上綴じの穴あけ目印が上部2箇所→各面の真ん中に1つ、③位置を微調整しても中央の点線が用紙の真ん中に来るように(印刷で点線が左に寄った)。</span><span class=\"lb\">対処</span><span class=\"tx\">原因は3つ: (a)applyShiftStatus の臨時(出席)経路は markDirty だけで「保存」を押すまでクラウドに乗らない(振替・欠席は即保存)。(b)提供記録入力の表示絞り込み displayRecords(AM/PM)の comingAM/PM が '〇'/'出席'/'振…' だけで '臨時' を見ていない(前日の修正は上流 filtered 側のみ)。(c)日誌の scheduledExtras は基本曜日だけで作り、月間セルの 臨時/振/出席 を見ていない。修正: (a)_forceRinji のとき setPendingShifts(null)→onSave(monthlyShifts, manual:true「✓ 臨時利用を保存しました」)で即保存。(b)displayRecords の comingAM/PM に stateXX==='臨時' を追加。(c)日誌に _monthlyComingKind(pid)(表示中の時間帯のセルが 臨時/振…/出席/〇 なら種別)を追加し、基本曜日でなくてもその人を載せ、状態は 臨時/振替/出席、_statusRank に臨時。デモ(VITE_E2E_DEMO)で「今日(非基本日)AMを臨時利用→提供記録入力に表示・日誌に表示」を Playwright で確認(保存前は未保存ダイアログで遷移が止まることも確認=店舗の症状の再現)。②日誌の氏名セルを AutoFitLine(枠幅に合わせ transform:scale)に。③上綴じの目印は各面上中央に▼1つ、位置微調整(renrakuOffsetX/Y)は各面の中身ラッパーだけを translate し、page容器(カット線・目印)は固定。マニュアル8・9・16章更新・PDF再生成。検証: esbuild/eslint no-undef 0/vitest 15/Playwright 22/run_tests --deployed 16/16。安定版0925a/試験版trial60。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9d7c98a</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"振替・臨時で来た方が出席に数えられない箇所を一斉修正 日誌の出席数 体力測定 分析個人 各種連絡 利用者実績 個人ファイル 次回予定 提供記録入力 臨時\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-24</span></div>\n      <p class=\"title\">振替・臨時利用で来た方を「出席」として扱う（日誌の出席数ほか7箇所を調査して統一）</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー指摘(2026-09-24): 日誌で振替で利用した人が出席に関連付けられていない。「他で反映されていないところがあったら調査して直して」。App.jsx 全体で status==='出席' の判定のうち 振替/臨時 を含まない箇所を機械的に洗い出し(20箇所)、意味を確認して修正対象を特定。</span><span class=\"lb\">対処</span><span class=\"tx\">修正: ①日誌 DailyLogView の出席数(attended)に 振替・臨時 を含める(実出席者数 actualAttendees と一致) ②体力測定 FitnessView の当日出席者一覧(2箇所)とサイドバーの体力測定バッジ(StaffLoginGate内の当日出席者)に 振替・臨時 ③分析個人 PersonalDashboardView: validRecs/出席扱い(furikaeAtt)/月別集計に 臨時 を追加(振替は元々出席扱い) ④各種連絡 GeneralFaxView の通所者一覧に 振替・臨時 ⑤利用者実績: 非基本日の「出席」記録でも月間スケジュールに 振/臨時 の印があれば 振替/臨時 として実績に載せる(従来はバイタル等が無いと非表示) ⑥個人ファイルの履歴「特記」を 振替・臨時 でも記録 ⑦getNextVisitInfo(次回予定)と提供記録入力の来所判定に 月間セル '臨時' を追加(振の前方一致のみだった)。変更しなかった箇所: 月間セル表示の予定/出席の色分け・変更ログの差分判定・PersonalFile の休止/休業ブロック(意味が異なる)。検証: esbuild/eslint no-undef 0/vitest 15/Playwright 22/run_tests --deployed 16/16。安定版0924d/試験版trial59。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">77190c1</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"月間スケジュール 状態を選択 臨時利用 shiftStatusModal applyShiftStatus 休み連絡 マスキング廃止 連絡済 faxed statusLabels\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-09-24</span></div>\n      <p class=\"title\">月間スケジュールの状態選択に「臨時利用」 ＋ 休み連絡は氏名をそのまま表示・印刷/PDF/FAX後は「連絡済」</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー要望(2026-09-24): ①店舗によっては臨時利用する人がいるので、月間スケジュールの日付を押したポップアップに臨時利用を追加。②休み連絡のマスキングは無しに。編集で「編集済」になるが、そこからPDF・複合機で印刷したら「連絡済」に変えてほしい。今後のAPI FAX送信も同様。</span><span class=\"lb\">対処</span><span class=\"tx\">①shiftStatusModal の選択肢 ALL を「基本利用日でない日」だけ [出席, 臨時, 欠席, 振替, 休止, 休業] にし、ボタン表示は「臨時利用（基本利用日以外の来所）」(cyan)。applyShiftStatus は '臨時' を出席の一種として処理し(_forceRinji)、月間セル値は '臨時'、欠席等の記録クリアは出席と同じ経路。現在値が臨時なら選択肢から除外。②AbsenceFaxView の maskName を恒等関数に(送付状・見出しとも氏名そのまま。印刷プレビューの「氏名を伏せる」は従来どおり)。statusLabels を printed/pdf/both/faxed → 「連絡済」、凡例を「連絡済（印刷・PDF・FAX）」に。内部状態(printed/pdf/both)は履歴互換のため維持し、将来の FAX API 送信後は updateFax(key,{status:'faxed'},{autoSave:true}) を呼ぶ旨をコードに明記。マニュアル12章・16章に追記、月間ポップアップのスクショ(staff_master_shift_modal)を追加。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">77190c1</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳 B5横2面 右下にずれ 見切れ 中央寄せ 印刷位置の微調整 renrakuOffsetX renrakuOffsetY 穴あけ位置 上綴じ renrakuPunchPos QRコード renrakuShowQr 印刷設定\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-09-24</span></div>\n      <p class=\"title\">連絡帳の印刷: B5右下ずれ対策（各面中央寄せ＋位置の微調整）・穴あけ位置「左／上」・ご家族QRの印字ON/OFF</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー要望(2026-09-24): ①B5で印刷すると用紙に対して右下にずれ、右側の連絡帳の日付や下の事業所名が見切れる。②穴あけパンチの印が左にあるが、上に穴をあける店舗もあるので横/上を選べるように。③連絡帳のQRコードを表示し、使わない店舗は非表示にできるように。</span><span class=\"lb\">対処</span><span class=\"tx\">①2面レイアウト: 各面の連絡帳を横中央寄せ(marginLeft 8mm固定→(半面幅−縮小幅)/2≈6mm、右端の余白4mm→6mm。複合機の印字不能域≈4mm対策)。「印刷設定」に<b>印刷位置の微調整</b>(横・縦 −10〜+10mm、systemSettings.renrakuOffsetX/Y、page容器に transform:translate)を追加し、1面モードにも適用。右下にずれる複合機は「−」に。②穴あけの目印に位置選択(renrakuPunchPos: left=既定の◀／top=各面上部に▼×2(中央±40mm))。上綴じは上余白14mm・縮率0.62で下の見切れも防ぐ。③ContactBookCard の「ご家族専用」QRブロックを systemSettings.renrakuShowQr!==false で表示(既定ON)、印刷設定にチェックボックス。マニュアル8章に「印刷設定」の節とスクショ(staff_renraku_print_settings)を追加。複合機側の注意点(用紙B5・横向き・倍率100%・余白なし・試し刷り)は返信で案内。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">77190c1</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"モニタリング\" data-text=\"モニタリング 折りたたみ中でも各項目のコピーボタンを常時表示 copyText monExpanded\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">モニタリング</span><span class=\"date tnum\">2026-09-24</span></div>\n      <p class=\"title\">モニタリング: 折りたたんだ状態でも各項目を「コピー」ボタンでワンクリックコピー</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー要望(2026-09-24): 一覧を折りたたんでいる状態でもワンクリックでコピーしたい。従来は各項目(①〜⑤)のコピーボタンが展開時(monExpanded / 編集中)だけ描画されていた。</span><span class=\"lb\">対処</span><span class=\"tx\">MonitoringView の項目行のコピーボタンから <code>_exp &&</code> 条件を外して常時表示(コンパクト行でも選択プルダウンの右に小さく出る。押すと ✓ 表示・copyText 経由でクリップボードへ)。マニュアル(モニタリング章)に「折りたたんだままでもコピーできる」を追記し、事業所向けスクショ40枚を再撮影・PDF再生成。検証: esbuild/eslint no-undef 0/vitest 15/Playwright 22/run_tests --deployed 16/16。安定版0924c/試験版trial58。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">111de9b</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"各種設定の後にケアマネ事業所・担当者を押しても事業所情報のまま SettingsView 使い回し activeTab 残留 cmOnly useEffect\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-09-24</span></div>\n      <p class=\"title\">各種設定を開いた後に「ケアマネ事業所・担当者」を押しても中身が事業所情報のまま</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">扇橋報告(2026-09-24・画面写真): 見出しは「ケアマネ事業所・担当者」に変わるのに、本文が各種設定の事業所情報のまま。原因= 'settings' と 'cmmaster' の両ビューが同じ位置で同じ SettingsView を描画するため React がインスタンスを使い回し、useState(cmOnly?'cm':'facility') の初期値が再評価されず activeTab='facility' が残留(cmOnly ではタブ一覧が 'cm' だけなので本文だけ食い違う)。</span><span class=\"lb\">対処</span><span class=\"tx\">SettingsView に useEffect([cmOnly]) を追加し、cmOnly なら 'cm'、通常で 'cm' のままなら 'facility' へ activeTab を同期。検証: esbuild/eslint no-undef 0/vitest 15/Playwright 22/run_tests --deployed 16/16。安定版0924b/試験版trial57。教訓(ガードレール): 同じコンポーネントを props 違いで別ビューとして使い回すとき、props で決まる初期state は useEffect で追従させる(または key を変えて別インスタンスにする)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c12f2f5</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"社外資料\" data-text=\"エリア担当者説明資料 改訂 連絡方針 店舗から髙橋へ直接 送迎表10月中旬前倒し 安定版利用中5店舗 未導入3店舗 経営層向け 導入状況と計画改訂のご報告 exec-briefing マニュアル ご家族はアカウント管理 ケアマネはケアマネ事業所・担当者\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">社外資料</span><span class=\"date tnum\">2026-09-24</span></div>\n      <p class=\"title\">エリア担当者説明資料の改訂（連絡は当面 店舗→髙橋直接・送迎表前倒し・店舗の現状）＋ 社長・コンサル向け「導入状況と計画改訂のご報告」新設 ＋ マニュアルの登録入口2本化</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー指示(2026-09-24): ①不具合はエリア担当者を介さず髙橋へ直接の方が迅速。今はその方針、FC店舗が増えたら任せる可能性。②送迎表は扇橋でもうすぐ使い、良ければ10月中旬(第2陣 西馬込・水元の運用開始頃)に安定版へ。③南水元・東小岩・江古田・西馬込・水元は既に安定版で利用中。柴又・立石・池上は意欲が低いのでそれを踏まえたスケジュールに。ガントも変わるので社長・コンサルに送れる資料を。④ご家族=利用者マスタ→アカウント管理、ケアマネ=ケアマネ事業所・担当者、をスクショ入りで分かりやすく。⑤資料の利用者名を匿名に。</span><span class=\"lb\">対処</span><span class=\"tx\"><b>エリア担当者資料</b>(area-briefing.html・9/24改訂): p2 役割表を「髙橋=全店の不具合・要望の窓口(当面)」「エリア担当=伝達・研修・相談役・未導入店の意欲づくり」「将来の移管=FC拡大時」に、p3 上りの流れを「店舗管理者→髙橋(直接)・エリア担当はCC」に、p4 試験版の説明を「送迎表は扇橋で近日試用→良ければ10月中旬に安定版へ」に、p5 ガント/日付一覧を「現在: 安定版利用中5店舗・試験版扇橋・未導入3店舗」「10月中旬 送迎表を安定版へ」「第3陣は意欲を見て個別に」「移管はFC拡大時」に、p9 を<b>ご家族(利用者マスタ→アカウント管理)／ケアマネ(ケアマネ事業所・担当者→招待メール)の2入口</b>に新スクショ(staff_master_account / staff_cm_invite)付きで再構成、一次回答集に「登録はどこから？」を追加。全11ページの高さ・画像重なりを機械確認(deck_check2.mjs)。<b>経営層向け資料</b> <code>public/exec-briefing.html</code>(A4縦5ページ・PDF「つむぎ導入状況と計画改訂のご報告.pdf」): 要旨3点／店舗別の導入状況表(9店舗)と直近1か月の主な改善／体制と連絡の流れ(当面直接・移管条件)／スケジュール改訂(ガント＋第5版との変更点表＋変わらない日付)／ご相談・依頼事項(未導入3店舗の進め方・送迎表の判断・LIFE・費用)。<b>事業所向けマニュアル</b>: 各種設定にLIFE連携タブの図と説明、19章冒頭に「入口は2つ」の注意枠＋2枚の図、17章にポップアップ/カタカナ/招待メールと図2枚。全69枚のスクショを架空名で再撮影(manual_shots.mjs に LIFE連携・アカウント管理・CM招待カード・担当者追加を追加、manual_pdf.mjs は --extra を;区切りで複数対応)。PDF5本を docs/マニュアル と public/manual に配置。URL: /area-briefing.html /exec-briefing.html /manual/つむぎ導入状況と計画改訂のご報告.pdf 。追記(2b94470・ユーザー指摘): PDF/印刷でガントチャートの帯が消えていた(背景色は印刷で省かれる)→ 両資料に <code>print-color-adjust:exact</code> と帯の薄い枠線を追加し、ラベル列を広げて「…」省略を解消。印刷メディアでの描画を機械確認してPDF再生成。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2c3d69a</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"各種設定にLIFE連携タブ新設 ケアマネ事業所・担当者の追加ポップアップは外側タップで閉じない ふりがなカタカナ統一 KanaInput toKatakana 見本データ利用者90名を架空名に差替 initialData\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-09-24</span></div>\n      <p class=\"title\">「LIFE連携」タブ新設 ＋ ケアマネ担当者の追加ポップアップが外側タップで消えない・ふりがなカタカナ統一 ＋ 見本データの利用者名を架空名に全面差替</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー要望(2026-09-24): ①各種設定→事業所情報の下にあるLIFE設定は別タブ「LIFE連携」にした方が分かりやすい。②ケアマネ事業所・担当者で「事業所を追加」「担当者を追加」のポップアップの外側を押すと閉じて入力が全部消える。③担当者のふりがながひらがな表示で、利用者マスタ・ご家族(カタカナ)と不揃い。④マニュアル・資料に登録済みの実在利用者の名前が入っている気がする(=見本データの姓が実在者と重なる)。</span><span class=\"lb\">対処</span><span class=\"tx\">①SettingsView の tabs に {id:'life', label:'LIFE連携'} を追加し、事業所情報タブ内のLIFEブロック(事業所番号・保険者番号・サービス種類コード・CSVバージョン・一体的取組・記入者職種)をそのまま新タブへ移動。保存先は従来どおり systemSettings.facilityInfo なので登録済みの値・LIFE画面の読込元(lifeOfficeCfg)は不変。LIFE画面の案内文「各種設定→事業所情報で登録」を「LIFE連携」に修正。②addOfficeModal/addPersonModal の背景 div から onClick={close} を撤去(キャンセルボタンのみで閉じる。cmEditModal は元々閉じない)。③追加・編集モーダルの姓/名ふりがな入力を <code>KanaInput</code>(IME確定時にtoKatakana)に置換、保存時(persistCm 新規/編集)も toKatakana、一覧の表示(p.kana)も toKatakana で既存のひらがな登録者もカタカナ表示。CM側の自己登録フォームは元からKanaInput。④実店舗10店の利用者名と見本データ90名の<b>完全一致は0件</b>(件数のみ集計)だったが、姓の重なりが各店8〜16件あり実名に見えるため、initialData の90名を「見本/架空/仮名/例示/試作/模擬/参考/標本/雛形/練習 × 太郎/花子/…」の明らかな架空名(性別に合わせた名・かな)に差替(提供記録等の同名参照も同時置換・置換漏れ0を確認)。manual_shots.mjs の対象名も更新し全スクショを再撮影。追記(77190c1): キー順が違う10名(kana無し等)が正規表現に掛からず旧名のまま休み連絡カレンダー等に残っていた→検出して差替(initialData 内の非架空名 0 を確認)。検証: esbuild/eslint no-undef 0/vitest 15/Playwright 22/run_tests --deployed。安定版0924a/試験版trial56。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2c3d69a</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"基本利用曜日の誤変更対策(ユーザー報告): 変更モーダルに「その日だけの変更は月間スケジュールで」の案内と移動ボタン+枠ハイライト、同日往復のnet-zero判定で履歴を残さない、変更履歴一覧と「削除」で過去表示を復旧、適用開始日が60日以上前なら確認 scheduleChangeHistory getScheduleOnDate applySchedChange removeSchedHistory _cleanSchedOverrides monthlyHl\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-09-23</span></div>\n      <p class=\"title\">基本利用曜日の誤変更対策 — 「その日だけの変更は月間スケジュールで」の案内・自動取り消し・変更履歴の削除で復旧</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー報告(扇橋): 振替のつもりで利用者マスタの基本利用曜日を 水PM→木PM に変えてしまい、店舗が手で戻した後も過去の提供記録一覧に木曜が入り続けた。原因= applySchedChange が「同じ曜日で適用開始日以降の旧履歴を除去して新履歴を追加」するため、戻す操作(木 PM→無)の履歴だけが残り、getScheduleOnDate がその日より前を「木=PM」に巻き戻していた(実データ: 該当者の履歴に 2026-09-23「木曜日 PM→無」が残存)。あわせて「月間スケジュールへ飛んだらそこをハイライトし基本利用日を触らせない」「休業・休止も同様」の要望。</span><span class=\"lb\">対処</span><span class=\"tx\">①<b>案内と誘導</b>: 基本利用日の変更モーダル上部に「毎週の決まった利用日を変えるときだけ使います／振替・欠席・休業・休止など“その日だけ”の変更は月間スケジュールで」の注意と「その日だけの変更なので、月間スケジュールへ移動する」ボタン。押すとモーダルを閉じて月間スケジュール枠へスクロールし、6秒間 ring-4 amber + 説明バナーでハイライト(<code>monthlyHl</code>/<code>focusMonthlySchedule</code>)。提供記録の振替・休止からのジャンプ(navFocus='schedule')でも同じハイライト。基本利用曜日の下にも一文で案内。②<b>自動取り消し(net-zero)</b>: applySchedChange で除去対象の旧履歴を新しい順に巻き戻した“変更前の値”が今回の newVal と一致すれば履歴を追加せず、その曜日の算法override('〇'/'空欄'/'出席')を全月から掃除(<code>_cleanSchedOverrides</code>・欠席/休業/臨時/振替は保持)。純粋関数で「水PM→無・木無→PM・木PM→無・水無→PM」の往復後に履歴が元の1件に戻ることを確認。③<b>変更履歴一覧と削除</b>: 基本利用曜日の下に scheduleChangeHistory の最新5件を表示し、各行「削除」(confirm付き)で今の基本利用曜日はそのまま履歴だけ除去+override掃除+変更ログに「基本利用日の履歴削除」を記録し即保存(<code>removeSchedHistory</code>・<code>_saveSchedResult</code> に保存処理を共通化)。④適用開始日が60日以上前なら「過去の表示が変わる／その日だけならキャンセルして月間スケジュールで」の確認。⑤マニュアル(事業所向け16章に注意枠+スクショ2枚+手順、Q&A追加)・エリア担当者資料の一次回答集に1行・scripts/manual_shots.mjs に撮影手順を追加(staff_master_sched_modal / staff_master_monthly_hl / staff_master_sched_history)。検証: esbuild/eslint no-undef 0/vitest 15/Playwright 22/デモ版でモーダル→移動→ハイライト→適用→履歴表示→往復で履歴消滅→削除ボタンで履歴消滅を実機確認/run_tests --deployed 16/16。安定版0923b/試験版trial55。<b>該当者の復旧</b>: 配信後に利用者マスタ→サービス提供内容→変更履歴の「木曜日 PM→無（2026-09-23〜）」を「削除」。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d78f434</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"社外資料\" data-text=\"マニュアル全面改訂(ユーザー依頼): 事業所/ご家族/ケアマネ向けの3種を実画面スクリーンショット方式(scripts/manual_shots.mjs で見本データから自動撮影・61枚)に作り直し、サイドバー順に全機能を網羅・台帳由来のQ&A追加・PDF化(scripts/manual_pdf.mjs)。エリア担当者向け説明資料(area-briefing.html・A4横11ページ)\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">社外資料</span><span class=\"date tnum\">2026-09-23</span></div>\n      <p class=\"title\">マニュアル3種を実画面スクリーンショットで全面改訂 ＋ エリア担当者向け説明資料（役割・流れ・スケジュール・一次回答集）</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー依頼: 事業所用・ご家族用・ケアマネ用のマニュアルをイラストではなく実際のスクリーンショットで作り直し、全機能・操作方法を網羅、過去の修正内容(Obsidian/台帳)をQ&Aに。機能追加で画面が変わったら都度更新できる形に。あわせて髙橋・エリア担当(山口=葛飾4店舗／山田=江戸川・大田・練馬4店舗)の3人ミーティング用に、今後の流れ・役割(新機能の伝達／不具合・要望の集約／店舗の相談役)・安定版と試験版の2本立て・スケジュール(いつ・どの店舗に)・各画面と設定の説明・ご家族/ケアマネ登録の手順と届くメール文面、をPDF印刷できる資料で。</span><span class=\"lb\">対処</span><span class=\"tx\">①<b>撮影の自動化</b> <code>scripts/manual_shots.mjs</code>(Playwright): デモ版(VITE_E2E_DEMO=1・見本データ)を配信し、サイドバー全画面(グループは開いてから)・各種設定タブ・利用者マスタ詳細/各タブ・災害時タブ、ご家族(スマホ幅/PC)・ケアマネ(PC)のログイン/招待URLからの登録画面/ホーム/お知らせ/通所記録/書類/フェイスシート を撮影(家族側は localStorage に架空データ+招待コードを投入してローカルログイン・規約改定ゲートも自動同意)。61枚を <code>public/manual/img</code> に保存(sipsで縮小・7.3MB)。②<b>事業所向け</b>(25章・51KB): 既存の説明文を残しつつサイドバー順に再構成。新設=つむぎとは・安定版/試験版/更新の仕組み、管理者パスワード、画面一覧表、送迎表(試験版)、体力測定、勤務表、利用者実績、モニタリング(独立章)、ケアマネ事業所・担当者、お知らせ・閲覧管理(登録の流れ・招待メール原文・登録画面)、災害時、計画書・LIFE、複数端末の決まりごと、<b>こんなときは(Q&A・台帳の店舗指摘18件から)</b>、本部への報告のしかた。③<b>ご家族向け</b>(12章)・<b>ケアマネ向け</b>(13章): 招待メール文面・登録手順・スマホ/PC画面・パスワード再設定・災害時連絡・担当者単位アカウント・FAX(モニタリング/休み連絡)・Q&A。④<b>PDF</b> <code>scripts/manual_pdf.mjs</code>(A4縦・ページ番号)で <code>docs/マニュアル</code> と <code>public/manual</code> に4本。⑤<b>エリア担当者説明資料</b> <code>public/area-briefing.html</code>(A4横11ページ・全ページ210mm以内を機械確認): 目的と役割／情報の流れ(下り・上り・緊急直通)と報告テンプレ／安定版と試験版／スケジュール(第5版ガント＋日付一覧＋1か月のやること)／機能一覧／1日の流れの主要画面／各種設定と新店舗立ち上げ順／ご家族・ケアマネ登録とメール原文／店舗から必ず聞かれる一次回答集／学習チェックリスト(3週間)。⑥更新手順を memory(tsumugi-manuals)と always-update-manuals に記録。⑦(d78f434)エリア担当者資料p9「ご家族・ケアマネの登録」で右列のスマホ画面2枚が列幅(540px)を超えて左の文章と重なっていた(ユーザー指摘)→ <code>.shot.sp</code> に max-width:calc(50% - 4px)・列に min-width:0 を追加、deck_check で全11ページ794px以内・重なり無しを機械確認しPDF再生成。安定版0923a/試験版trial54。URL: /manual-jigyosho.html /manual-kazoku.html /manual-kankeisha.html /area-briefing.html /manual/*.pdf</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8e2524e</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】送迎表の時刻表示を「13時25分」→「13:25」に統一(画面の入力欄・週間運行表・印刷)。保存値は従来形式のままで表示だけ変換(_fmtT)、車内の並び替えは分換算(_tMin)\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-22</span></div>\n      <p class=\"title\">【試験版】送迎表の時刻を「13:25」形式で表示</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">店舗要望(スクリーンショット): 送迎表の時間欄が「13時25分」で幅を取り、入力欄で末尾が切れる。「13:25」にしてほしい。時刻はマスタの送迎時間(getPickupTimeForDow=「H時M分」形式)や手入力から来るため形式が混在していた。</span><span class=\"lb\">対処</span><span class=\"tx\">TransportView に <code>_fmtT</code>(「13時25分」「13時」→「13:25」「13:00」、それ以外はそのまま)を追加し、車内の入力欄・週間運行表の時刻・印刷(A4横/連絡先付き)の時刻セルに適用。保存値は変換せず表示のみ統一(既存プランと互換)。手入力で「13:25」と入れてもそのまま保存・表示。車内の並び替えは文字列比較から分換算(<code>_tMin</code>・徒歩や未設定は末尾)に変更し、形式混在でも時刻順になる。試験版のみの画面のため安定版の変更なし。検査: esbuild/eslint no-undef 0件。試験版trial53。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">923d11d</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"提供記録入力・次回予定の変更に休止中の方(小糸様)が出る: displayRecords が生statusの出席記録を拾い、休止設定(9/17)前に seed が基本利用日(火・木)に先行作成した空の出席枠(9/22・10/1)がそのまま表示されていた → 休止期間・退所・利用期間外の方は記録があっても除外(e7a5c97)\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-22</span></div>\n      <p class=\"title\">休止中の方が「次回予定の変更」に出る — 休止前に先行作成された空の出席枠を拾っていた</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">店舗指摘: 小糸様は休止中なのに「次回予定の変更」に1人だけ表示される(他の休止の方は出ない)。実データ確認: 小糸様は火・木が基本利用日で、休止(9/17〜・終了日なし)を設定する前の 9/11・9/15 に、提供記録の seed が 9/22(火)・10/1(木) の空の出席枠(ticket_records)を先に作っていた。TicketView の <code>displayRecords</code> は記録の生 status(出席/振替)だけで行を拾い、休止期間の判定(<code>getPauseReasonOnDate</code>)は表示用の seed 側でしか掛けていなかったため、先行枠を持つ方だけ休止中でも表示された(茂木様など他の休止の方は先行枠が無いので出ない)。</span><span class=\"lb\">対処</span><span class=\"tx\"><code>displayRecords</code> の記録抽出で、利用者を引いて 休止期間中(getPauseReasonOnDate)／退所済み(isPatientResigned)／利用開始前・終了後(isPatientActiveOnDate) の方は記録があっても除外。提供記録入力の一覧・次回予定の変更・連絡帳印刷の対象が揃う。ガードレール「statusは表示用・判定は期間ベース」の再適用。検査: esbuild/eslint no-undef 0件。安定版0922a/試験版trial51。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e7a5c97</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳: 次回お迎え時間の日付が未定/空のとき「未定」を印字せず手書き用の「　月　日（　）」に(店舗要望)\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-09-22</span></div>\n      <p class=\"title\">連絡帳の次回お迎え時間に「未定」を印字しない — 空欄「　月　日（　）」で手書きできるように</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">店舗要望(スクリーンショット): 次回の日付が決まらないとき「未定　時　分」と印字される。未定と出さず「○月○日（○）」の○を空白にしてほしい。<code>getNextVisitInfo</code> が次回を決められない(休止中など)と date=\"未定\" を返し、それをそのまま印字していた。</span><span class=\"lb\">対処</span><span class=\"tx\">連絡帳の印字値 <code>nextDateDisplay</code> を決めた後に、未定・空・数字を含まない値なら手書き用テンプレ「　月　日（　）」に置き換える(空き面と同じ扱い)。時刻側は従来どおり「　時　分」。画面側の「未定」判定(次回予定の変更の意図的な未定入力)には触れていない。検査: esbuild/eslint no-undef 0件。安定版0922b/試験版trial52。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">be61000</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"1\" data-area=\"同期\" data-text=\"同期の軽量化(ユーザー指示・即時): テーブルが正の凍結キー ticketRecords を app_state の push で空配列に。7/30凍結スナップショット(扇橋734件=1.37MB)が push/pull のたびに往復していた死荷重を除去。tableFailed端末は従来マージ・家族アプリはテーブル重ね読みで影響なし\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"tag k-crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-21</span></div>\n      <p class=\"title\">同期の軽量化 — app_state から凍結済みの提供記録スナップショット(扇橋1.37MB)を外す</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">450件目で判明した「同期に失敗」頻発の根本原因(扇橋の app_state 2.5MB)に対し、ユーザー指示「軽量化はすぐにした方がいい」。読み込みの経路を確認: 提供記録は 7/30 のテーブル方式カットオーバー以降 <code>OPLOG_FROZEN_KEYS=['ticketRecords']</code> で「巨大JSON側は凍結スナップショット」となり、pull は提供記録に触らず(pull-keep-tbl)、CAS マージも <code>isOplogFrozen</code> で cloud の凍結コピーをそのまま merged に載せて push し返していた。つまり扇橋の app_state 内の734件(1.37MB)は<b>どの端末も読まない死荷重</b>なのに、保存のたび(読む→書く)と60秒ごとの pull で毎回往復していた。</span><span class=\"lb\">対処</span><span class=\"tx\"><code>supabaseMergeAndSyncStateForStore</code> の凍結分岐で <code>ticketRecords</code> は <b>空配列</b>で保存する(他の凍結キーが将来増えても従来どおり)。安全性の確認: ①テーブルが読めた端末は pull で提供記録に触らないため影響なし ②テーブル読込に失敗した端末(tableFailed)は凍結が外れ従来の id/項目マージに戻る(cloud側が空でも「片方にしか無い id は残す」でローカル行は保持) ③家族アプリは app_state 読込後に <code>fetchTicketRecordsSince(1970)</code> でテーブルの行を重ねるため影響なし ④端末ローカル控え(daycareAppData_v3)は元々 _slimTickets で直近45日。効果: 扇橋 2.5MB→約1.1MB(次回 push から)。残る大物は diaryLogs 0.32MB・patients 0.26MB。検査: esbuild/eslint no-undef 0件。安定版0921k/試験版trial50。<b>確認事項</b>: 翌営業日に app_state サイズと diag の push-give-up 件数を再計測。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e096bdf</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌: 様子・欠席理由を状態に関係なく黒字に統一、休止の理由は「休止理由:」の前置き無しで理由のみ(店舗指摘)\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-21</span></div>\n      <p class=\"title\">日誌の様子・欠席理由を黒字に統一、休止は理由だけを表示</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">店舗指摘(451件目の直後): 「休止理由:」の前置きは不要で「入院」だけでよい。様子・欠席理由の欄は全て黒で。</span><span class=\"lb\">対処</span><span class=\"tx\">日誌の行生成2か所で休止の理由を前置き無しに、セルの文字色を欠席でも赤にせず inherit(#333)に。検査: esbuild/eslint no-undef 0件。安定版0921k/試験版trial50。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e096bdf</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"「同期に失敗しました」後の再読み込みで振替が消える: app_state push が3回失敗(扇橋は app_state 2.5MB・20秒固定タイムアウト・give-up 124回)すると端末に控えが無く消失。IndexedDB 再送キュー(_pendIdb・再読み込み後/オンライン復帰後に自動再送)+容量連動タイムアウト(20秒+1MBあたり15秒・上限80秒)+月間スケジュールは振替の提供記録から表示(自己修復)\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"tag k-crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-21</span></div>\n      <p class=\"title\">「同期に失敗しました」の後に再読み込みすると振替が消える — 失敗した保存を端末に控えて自動再送、タイムアウトを容量連動に</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">店舗指摘: 欠席→別日を振替にすると、その場では月間スケジュールに反映されるが「同期に失敗しました」が出て、再読み込みすると振替のセルだけ消える(欠席理由には「○月○日へ振替」が残る)。保存は2経路で、提供記録の行(ticket_records テーブル・行単位RPC)は成功し、月間スケジュール(app_state・CAS)だけが失敗していた。扇橋の診断ログには push-give-up が累計124回・push-timeout 13回。app_state の実サイズを計測すると扇橋 <b>2.5MB</b>(ticketRecords 1.37MB・diaryLogs 0.32MB・patients 0.26MB)、南水元1.3MB。push は「読む→マージ→書く」で往復5MB、タイムアウトは20秒固定のため遅いWi-Fiでは毎回時間切れ→3回失敗→give-up。give-up 後は端末に控えが無く(スタッフアプリは app データを localStorage に持たない)、再読み込みで失われていた。</span><span class=\"lb\">対処</span><span class=\"tx\">①<b>再送キュー</b>: モジュールレベル <code>_pendIdb</code>(IndexedDB 'tsumugi-pending'/'push'・店舗IDキー)。<code>_pumpPush</code> で give-up したデータを put し、トースト文言を「変更は端末に控えました。通信が回復すると自動で送信します（再読み込みしても消えません）」に。成功時に控えを削除。App の effect(staffSession.storeId 決定の5秒後と online 復帰時)で控えを読み <code>supabaseMergeAndSyncStateForStore</code> で再送(時刻ベースのマージなので古い控えでも新しい入力を壊さない・_sbStoreId 不一致の控えは破棄)。成功で「前回保存できなかった変更をクラウドへ送信しました」・ログ pend-resend/ok/fail。②<b>タイムアウト</b>を 20秒 + 1MBあたり15秒(上限80秒)に。③<b>表示の自己修復</b>: 月間スケジュールは <code>_mSchedRecFuri</code>(振替の提供記録の特記「○月○日分振替」と furikaeAmpm から「振(m/d)」)を作り、monthlyShifts に印が無くても表示。<b>根本課題(未対応)</b>: app_state に ticketRecords(734件・1.37MB)が同居しており push が重い。テーブルを正とする設計に合わせて app_state 側の記録を直近数か月に絞る／除外する改修を検討(同期の中核のため複数端末シナリオ精査が必要)。検査: esbuild/eslint no-undef 0件。安定版0921j/試験版trial49。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">813f912</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌: 休止の方の理由欄が空 → 提供記録の特記が空なら利用者マスタの休止履歴(getPauseReasonOnDate)の理由を「休止理由: …」で表示(記録あり/予定の両経路)\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-21</span></div>\n      <p class=\"title\">日誌の「休止」の方に休止理由を表示</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">店舗指摘: 日誌の利用者一覧で欠席は理由(私用・怪我など)が出るのに、休止は理由欄が空。休止は利用者マスタの休止履歴(理由・期間)で管理され、提供記録の特記には理由が入らないため。</span><span class=\"lb\">対処</span><span class=\"tx\">日誌の行生成(記録から作る行・予定から作る行の2か所)で、状態が休止かつ特記が空なら <code>getPauseReasonOnDate(p, selectedDate)</code> の理由を「休止理由: …」として理由欄に表示。検査: esbuild/eslint no-undef 0件。安定版0921j/試験版trial49。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">813f912</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"利用者マスタ振替: 振替先セルから「振替元」(欠席済み)を選んでも欠席理由・詳細が未選択のまま → 振替元を選んだ時点でその日の欠席記録から大分類/詳細を自動セット(_furiSrcReason/_pickFuriFrom・backwardモード)\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-09-21</span></div>\n      <p class=\"title\">振替先から「振替元」を選んだとき、その日の欠席理由・詳細が自動で入るように</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">店舗指摘(スクリーンショット): 9/30を「本人・家族の都合（会合）」で欠席にした後、9/28のセルから振替を選び、振替元に9/30を選択しても「欠席理由（大分類）」「詳細」が未選択のまま。448件目の理由引き継ぎは、欠席済みのセル自体を「振替」にする流れ(forward)だけに効いていて、振替先のセルから振替元を後から選ぶ流れ(backward)ではモーダルを開いた時点で振替元が未定のため引き継げなかった。</span><span class=\"lb\">対処</span><span class=\"tx\"><code>_furiSrcReason(isoDate)</code>(振替元の日付から、その日の欠席記録の特記を <code>absReasonFromTokki</code>→<code>parseAbsReason</code> で大分類/詳細に分解)と <code>_pickFuriFrom(patch)</code>(fromDate/furikaeAmpm を更新し、backwardモードなら理由を自動セット)を追加し、振替元の候補ボタンと日付入力の両方から呼ぶ。理由が無い日を選んだ場合は入力中の値をそのまま残す。検査: esbuild/eslint no-undef 0件。安定版0921i/試験版trial48。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8f3e690</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"利用者マスタ\" data-text=\"【真因】月間スケジュールから続けて2人を欠席にすると2人目に1人目の理由・1人目が空欄: 新規記録IDを Math.max(既存ID)+1 で採番していたが既存IDは文字列(tr_…)のため NaN → 2人とも id=NaN で互いに上書き。tr_<pid>_<y>_<m>_<d> 形式・year/_savedAt・即クラウド保存に。振替時の理由引き継ぎを「○月○日へ振替（理由）」形式にも対応。セルのツールチップと状態モーダルに欠席/休業/振替(振替元の欠席理由)を表示\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"tag k-crit\">重大</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-09-21</span></div>\n      <p class=\"title\">【真因】月間スケジュールの欠席で2人目に1人目の理由が入る／1人目が空欄になる — 記録IDの採番がNaNで衝突していた</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">店舗指摘: 提供記録入力で欠席にすると特記事項に理由が入るが、利用者マスタの月間スケジュールから欠席にすると、1人目は反映されるのに続けて2人目を行うと2人目に1人目の欠席理由が入ったり、1人目の欠席箇所が空欄になる。あわせて、月間スケジュールで欠席・振替のセルを押しても理由が見えない、提供記録で「振替予定」の欠席にしておいた方を後から別日に振り替えると理由が引き継がれない。</span><span class=\"lb\">原因</span><span class=\"tx\">MasterView <code>applyAbsenceWithReason</code> が新規の提供記録を作るとき <code>id = Math.max(0, ...effTickets.map(t=>t.id||0)) + 1</code> で採番していた。実データの記録IDは全件が文字列(<code>tr_…</code> 649件・数字文字列85件)で、<code>Math.max</code> に 'tr_…' が混ざると結果は <b>NaN</b>。よって月間スケジュール経由の新規欠席は全員 <code>id: NaN</code> となり、続けて2人目を登録するとIDが同じため差分送信・マージで互いに上書き(2人目に1人目の理由／1人目の記録が消えて空欄)。さらに year・_savedAt も無く、下書き(pendingTickets)止まりだったため利用者を切り替えると「破棄」で消えることもあった。振替の理由引き継ぎは <code>!/へ振替/.test(tokki)</code> で除外していたため、提供記録入力の「振替予定」(特記=「○月○日へ振替（理由）」)の欠席からは引き継がれなかった。実データ点検: app_state に id=null の記録が 南水元4件・東小岩1件(8月の振替)残存(別経路の旧不具合の残骸・要修理)。</span><span class=\"lb\">対処</span><span class=\"tx\">①採番を振替と同じ <code>tr_&lt;利用者ID&gt;_&lt;年&gt;_&lt;月&gt;_&lt;日&gt;</code> に統一し、year・dayOfWeek・kana・空のバイタル項目・_savedAt を付与。既存記録の照合も <code>recMatchesDateYear</code> で年つきに。②欠席/休業は下書きに留めず即 <code>onSave(manual)</code>(振替と同じ)。③<code>absReasonFromTokki</code>(「○月○日(AM|PM)へ振替(予定)」の印と外側の（）を外す)を新設し、振替モーダルの理由プリセットに使用。④<code>_mSchedRecReason</code>(日→理由文)を作り、月間スケジュールのセル title(PCはホバー・タブレットは長押し)と「状態を選択」モーダルに表示: 欠席/休業=「欠席理由: …　※○月○日へ振替」、振替先=「○月○日分の振替　欠席理由: …」(振替元の欠席記録から取得)。検査: esbuild/eslint no-undef 0件。安定版0921h/試験版trial47。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5596631</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"新LIFE検証の方針変更(まるっとLIFE/カイポケ共用アカウントへの影響回避): 本番に取り込まず見るだけ。まるっとLIFEの実CSV(xlsx CSVシート)と機械照合→TIFI/AINT/IDUAは列・Data type名・管理番号方式・ゼロ埋め・コード値が一致、FUNCのみjob_category(3.10版)差。カイポケの利用者情報管理番号=64hexハッシュ→既登録利用者に利用者情報CSVを入れない注意をUIに追加。ベンダ向け検証環境の申請文\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-09-21</span></div>\n      <p class=\"title\">新LIFE検証は「本番に触れない」方針に — まるっとLIFEの実CSVとの機械照合で構造を確認、利用者情報CSVの二重登録注意</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ユーザー懸念: 新LIFEへ取り込むと、現在使っているまるっとLIFE(カイポケRPA経由で提出)に影響しないか。つむぎの中で完結して確かめたい。新LIFEの事業所アカウントはまるっとLIFEと共用で、まるっとLIFEのxlsx「カイポケ」シートを確認すると、カイポケは利用者情報を<b>64桁hexハッシュ</b>の外部システム管理番号で登録している(つむぎは被保険者番号)。同じ方を取り込むと二重登録の恐れがある。一方、様式CSVの管理番号はまるっとLIFEも「被保番10桁+YYYYMM+様式ID」でつむぎと同一方式のため、同じ方・同じ月は上書きになる(二重にはならないが、まるっとLIFE提出済みの月を上書きし得る)。</span><span class=\"lb\">対処</span><span class=\"tx\">①<b>本番への取込は行わず</b>、当日は「見るだけ」(利用者一覧の登録有無・外部システム管理番号の形式・CSV取込画面・提出済み様式)に変更。②<b>つむぎ内で完結する照合</b>: まるっとLIFEが実際に提出成功したCSV(xlsx「CSV」シート・4様式)とつむぎの列定義・出力規則を機械照合 → 科学的介護推進114/ADL維持等23/個別機能訓練103は列名・順序・1行目Data type名・管理番号方式・insured_noの先頭ゼロ埋め10桁・Barthel段階コードが一致。<b>ADL_MAINTENANCE_ADDITION_2024 で確定</b>(まるっとLIFEも同名で提出成功、仕様書§4.2例の _INFO_ 表記は誤記側)。生活機能チェックはまるっとLIFEが52列(3.00)・つむぎは公式3.10版の53列(No.8 job_category)で、新LIFEが53列を要求するかだけ未確認。まるっとLIFEは様式CSVの事業所番号/サービス種類/保険者番号を空欄で提出し受理されている(つむぎも空欄は要確認止まり)。③LIFE・加算の利用者情報カードに「他ソフト(カイポケ等)で登録済みの利用者には取り込まない(二重登録)」の注意を追加。④手順書(docs/つむぎ新LIFE取込検証手順.html・Artifact c18da46b)を改訂: 方針・照合結果・介護ソフトベンダ向け検証環境の申請手順と申請文例(問い合わせフォーム→「介護ソフトベンダ向け環境 申し込み専用」)。<b>運用方針</b>: 既存利用者の利用者情報はカイポケ登録を使い、つむぎからは新規利用者のみ。様式は月単位で切り替え、同じ月を両方から出さない。検査: esbuild/eslint no-undef 0件。安定版0921g/試験版trial46。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7103b0c</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"新LIFE取込検証の準備: 被保険者番号が10桁未満(先頭ゼロ落ち)の方に要確認表示。docs/つむぎ新LIFE取込検証手順.html(検証当日の手順書・Artifact c18da46b)。全店の事前点検: 事業所番号/サービス種類/保険者番号は全店未設定、被保険者番号は扇橋10桁36名/6〜7桁37名/未登録2名・他店はほぼ未登録、評価記録は全店0件\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-09-21</span></div>\n      <p class=\"title\">新LIFE取込検証の準備 — 手順書の作成、全店の事前点検、被保険者番号の桁数の要確認表示</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">Windows 11＋電子証明書のPCが今日か明日使えるとのことで、検証当日に迷わない手順書が必要。仕様書§6の「介護ソフトベンダ向け検証環境」は問い合わせフォームからの申請制(ヘルプデスクがアカウント発行)で当日は使えないため、新LIFE本番へ「利用者情報だけ→1名分の様式」の順で少しずつ入れて確かめる方針にした(利用者情報の登録は移行に必須の作業・同じ管理番号なら上書きでやり直し可)。公開キーで読める app_state から各店の LIFE設定と利用者マスタの充足を集計(個人情報は出力せず件数のみ): 事業所番号・サービス種類コード・保険者番号は<b>全店未設定</b>、被保険者番号は扇橋75名中 10桁36名／6〜7桁37名(Excel取込の先頭ゼロ落ちが濃厚)／未登録2名、他店はほぼ全員未登録(江古田のみ6名未登録)、評価記録(ADL/生活機能/機能訓練)は全店0件。</span><span class=\"lb\">対処</span><span class=\"tx\">①<code>validateLifeUserInfo</code> に「被保険者番号がマスタではN桁のため先頭ゼロで10桁にして出力（被保険者証と照合）」の要確認を追加(従来は無言でゼロ埋め)。②<b>docs/つむぎ新LIFE取込検証手順.html</b>(Artifact c18da46b): 前日まで(事業所情報3項目の入れ方=サービス種類15/78の判断・保険者番号の出所、マスタ不足の直し方、様式テスト用に1名の一括評価)、当日(つむぎでの出力→新LIFEでの取込順・スクショ)、結果の見方と私に送るもの(正確性チェック／利用者情報不存在／データ種別／コード値／事業所番号のエラー別対応)、成功後の全員分展開、他店の状況。③更新お知らせ。検査: esbuild/eslint no-undef 0件。安定版0921f/試験版trial45。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1cc138f</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"1\" data-area=\"セキュリティ\" data-text=\"職員認証をサーバー経由に: staff テーブル(ログインID・パスワードハッシュ)が公開キーで誰でも読めていた → api/staff-auth.js(login/list/create/change_password/delete_store_staff・service_role・HMAC署名トークン30日)に移し、docs/sql/staff_rls.sql(RLS有効化・ポリシー全削除・anon revoke)で閉じる。run_tests T-SEC-03 追加(SQL適用まで FAIL)\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"tag k-crit\">重大</span><span class=\"area\">セキュリティ</span><span class=\"date tnum\">2026-09-21</span></div>\n      <p class=\"title\">職員ログインをサーバー経由の認証に — staff テーブルをブラウザから閉じられる状態に（SQL適用は本部作業）</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">9/17の外部サービス設定の整理で判明していた未対応事項: staff テーブル(username・password_hash・メール等)は公開キー(publishable key)で誰でも SELECT できる(本日も curl で3行取得できることを確認)。ログイン・職員作成・パスワード変更・職員一覧・店舗削除時のスタッフ削除の5経路がブラウザから supabase-js で staff を直接読み書きしていたため、RLS で閉じるとアプリが動かなくなり、対応を先送りしていた。ユーザー判断(2026-09-21)で着手。</span><span class=\"lb\">対処</span><span class=\"tx\">①<b>api/staff-auth.js</b>(新規・service_role): <code>login</code>(username+password_hash で照合→last_login更新→password_hash を除いた行と <b>HMAC-SHA256署名トークン</b>(sid/role/store_id/exp=30日・鍵=service_roleキー派生・DB列不要)を返す)、<code>list</code>(本部=全店/店舗管理者=自店・SAFE_COLSのみ)、<code>create</code>(本部 or 自店の管理者・super_adminは本部のみ・重複ID 409)、<code>change_password</code>(本人 or 本部)、<code>delete_store_staff</code>(本部のみ)。トークンは timingSafeEqual で検証・期限切れは expired:true。②<b>src/lib/supabase.js</b>: 5関数を <code>staffApi()</code> 経由に置換。サーバーが無い(fetch失敗/404)ときだけ従来の直接アクセスに落ちる(ローカル開発用・RLS適用後は直接経路は空になる)。login の戻りに <code>_token</code> を付け、App の staffSession に <code>token</code> を保持(既存の session 更新箇所はスプレッドなので維持される)。ハッシュ方式(SHA-256+固定ソルト)は従来どおりブラウザで計算し平文は送らない。③<b>docs/sql/staff_rls.sql</b>: RLS有効化→既存ポリシー全削除(do $$ loop)→anon/authenticated から revoke all。実行順(アプリ配信確認→SQL→curlで[]確認)と戻し方(create policy)を明記。④<b>scripts/run_tests.py に T-SEC-03</b>「staff が公開キーで読めない」を追加(SQL適用まで FAIL 表示=適用の催促)。<b>本部作業</b>: 全店に0921eが配信された後、Supabase SQL Editor で docs/sql/staff_rls.sql を実行(ガードレール: pg_policies の控えを取ってから)。<b>→ 2026-09-21 適用済み</b>(policies=0・公開キーでの staff 読取は 401 permission denied・サーバー経由ログインは正常・T-SEC-03 PASS 16/16)。残: family_accounts も同様に公開キーで読める(ケアマネ/家族のハッシュ)ため次の対象。検査: esbuild/eslint no-undef 0件。安定版0921e/試験版trial44。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4662602</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"新LIFE対応 T4/T5+入力補正: 各種設定→事業所情報に 一体的取組(trinity_attempt 0/1)と記入者職種の既定値(lifeDefaultJob)、FUNC2024/IDUA2024 に反映(job_category は記録→既定値の順)、ADL維持等の経過措置案内(R9/3提供分まで)、利用者ごとの保険者番号入力を NFKC 補正\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-09-21</span></div>\n      <p class=\"title\">新LIFE対応 T4/T5 — 一体的取組の設定、記入者職種の既定値、ADL維持等の経過措置案内、保険者番号の入力補正</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">442件目で残した小タスク。生活機能チェック/個別機能訓練の <code>trinity_attempt</code>(リハ・個別機能／栄養／口腔の一体的取組・◎必須・0無し/1有り)が固定「0」だった(T4)。442件目で追加した「記入者の職種」は記録ごとの選択で、過去の3-2記録は全部「要確認」になる。ADL維持等加算の経過措置(移管Q&A問7〜9)の案内が画面に無かった(T5)。利用者ごとの保険者番号は全角入力が弾かれるだけで補正されなかった。</span><span class=\"lb\">対処</span><span class=\"tx\">各種設定→事業所情報のLIFE欄に「一体的取組(0/1)」と「記入者の職種の既定値(公式23職種)」のセレクトを追加(<code>facilityInfo.lifeTrinity / lifeDefaultJob</code>・項目別刻印 fi:* で同期保護)。<code>lifeOfficeCfg</code> に trinity/defaultJob を載せ、<code>buildFunc2024Row/buildIdua2024Row</code> の trinity_attempt に反映、FUNC の job_category は「記録の職種→既定値」の順で解決し要確認文言も更新。ADL維持等(AINT2024)の様式カード注記に経過措置(令和9年3月提供分まで従前区分継続可・旧LIFEで7か月以上の評価がある場合等・適用中もADL値の新LIFE登録は継続)を追記。保険者番号入力は <code>normalize('NFKC')</code> 後に数字6桁へ。検査: esbuild/eslint no-undef 0件。安定版0921e/試験版trial44。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4662602</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"新LIFE対応 T1/T2/T3: 利用者情報CSV(SERVICE_USER_INFO 22列)の一括出力+基本4項目(保険者/被保険者/性別/生年月日)の検証と補正+利用者情報＋様式のまとめ出力。様式CSVを3.10版に: 1行目Data type・version 0310・要介護度コード表修正(要支援1=12/2=13)・被保険者番号の英字対応・FUNC2024 job_category列追加・取込でData type行を読み飛ばし\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-09-21</span></div>\n      <p class=\"title\">新LIFE対応 — 利用者情報CSV(SERVICE_USER_INFO)の一括出力、基本4項目の検証、様式CSVを3.10版の形式に修正</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">9/6の新LIFE調査で確定したTODO(T1〜T3・9/30必達)。新LIFE(国保中央会)には事業所アカウントしか移行されず、利用者情報(SERVICE_USER_INFO)を先に取り込まないと様式CSVを一切取り込めない。また基本4項目が介護情報基盤と不一致だと紐づく様式も連鎖エラーになる(§4.7)。着手時に公式資料(外部IF項目一覧v0310 xlsx・CSV連携仕様書3.10版PDF)を機械的に照合したところ、既存の様式CSVに新LIFEで通らない差異が4点見つかった: (1)<b>1行目のData type行(IF物理名)が無い</b>(§4.2: 1行目Data type/2行目列名/3行目〜データ) (2)version が 0300(公式は「0310」固定) (3)<b>要介護度コード表が1つずれていた</b>(要支援1=11/要支援2=12 → 公式は 11=要支援(経過的要介護)/12=要支援1/13=要支援2。TIFI/AINT/FUNC/IDUA全様式共通) (4)生活機能チェックFUNC2024が52列で、公式53列のNo.8 <code>job_category</code>(記入者職種・原則必須)が欠落し以降の列がずれていた。TIFI(114)/AINT(23)/IDUA(103)の列名・順序は公式と完全一致を確認。</span><span class=\"lb\">対処</span><span class=\"tx\"><b>T1</b> <code>LIFE_USERINFO_COLUMNS</code>(22列)/<code>buildLifeUserInfoRow</code>: 事業所番号・サービス種類・外部システム管理番号(=被保険者番号。事業所×サービス種類内で利用者ごとに一意・再出力で同一利用者に上書き)・保険者番号(利用者個別→事業所既定)・被保険者番号(<code>lifeZero10</code>を英字対応: NFKC→英数以外除去→大文字→10桁ゼロ埋め)・姓/名(「姓 名」の空白で分割、全角化、空白無しは名を公式備考どおりダミー「００」)・半角カナ(<code>lifeHalfKana</code>: ひらがな/全角カナ→半角・濁点分離)・性別・生年月日(<code>lifeDateYmd</code>: ISO/スラッシュ/和暦/全角対応)・認定日(マスタに無く空欄)・認定有効期間(careLevelFrom/To)・要介護度・自立度2種・利用開始/終了日・version。<b>T2</b> <code>validateLifeUserInfo</code>: 4項目の桁数/形式/範囲(1900年〜今日)・被保険者番号の重複・日付の前後関係・利用開始日の未来日付をエラー、ダミー名/期間未登録/自立度未設定/全角補正を要確認として表示。「LIFE・加算」に利用者情報カード(出力可/エラー件数・利用者ごとの4項目と状態・確認事項・「利用者情報CSV出力」=エラー行は除外し確認ダイアログで列挙)。<b>T3</b> 提出ダッシュボードに「利用者情報＋様式をまとめて出力」(様式が提出可かつ利用者情報も出力可の方を 利用者情報_YYYYMM.csv → 様式CSV の順に連続保存。利用者情報エラーの方は両方から除外し理由を表示)。<b>様式側の修正</b>: <code>LIFE_FORMS[].dataType</code>(SCIENTIFIC_NURSING_CARE_PROMOTION_2024/ADL_MAINTENANCE_ADDITION_2024/LIFE_FUNCTION_CHECK_SHEET_2024/INDIVIDUAL_FUNCTION_TRAINING_PLAN_2024)を <code>lifeToCsvText</code> の1行目に出力、<code>LIFE_VERSION_DEFAULT='0310'</code>、<code>lifeCareLevelCode</code>(NFKC・全角括弧正規化、非該当01/事業対象者06追加)、FUNC2024に job_category を挿入し 3-2 基本情報に「記入者の職種」セレクト(LIFE_STAFF_JOBS=公式23職種と一致を確認)・未選択は要確認、CSV取込(移行)は1行目がData type行なら読み飛ばす。node で架空3名の自己検証(22列・1行目SERVICE_USER_INFO・重複/未来日/全角補正の判定・半角カナ変換・要介護度コード)OK。<b>要検証</b>: ADLのData type名は一覧・シート見出し「ADL_MAINTENANCE_ADDITION_2024」を採用(仕様書§4.2の例は「…_INFO_2024」表記で不一致)→新LIFE検証環境で確認。既出力済みCSVは再出力が必要。検査: esbuild/eslint no-undef 0件。安定版0921d/試験版trial43。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">211f840</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"災害時 連絡先一覧の印刷で余白が無い: 印刷ホスト(buildDocHtml)の @media print body>*{margin:0;padding:0} で用紙要素のpaddingが消えていた→外側=用紙要素・内側=余白div の2段にし、18名ごとにページ分割して各ページに余白と見出し。ユーザー指示: 印刷余白は毎回言わなくても付ける(ガードレール化)\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-21</span></div>\n      <p class=\"title\">災害時 連絡先一覧の印刷に余白が無い — 用紙要素の中に余白divを置き、18名ごとにページ分割</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">店舗指摘(印刷ダイアログのスクリーンショット2枚): 表が用紙の端に付いて印刷される。441件目で用紙要素(297×210mm)に padding を付けたが、印刷側 <code>buildDocHtml</code> の <code>@media print{ body>*{margin:0!important;padding:0!important} }</code>(既存帳票がA4を使い切るための共通ルール)で最外周の padding が消えていた。プレビューでは消えないため気づけなかった。あわせてユーザー指示「印刷の余白は毎回言わなくても付けてほしい」。</span><span class=\"lb\">対処</span><span class=\"tx\">印刷HTMLを「外側=用紙要素(白・297×210mm・overflow hidden・page-break-after)／内側=余白div(padding 10mm 12mm)」の2段に変更。63名など複数ページになる一覧は <code>PER_PAGE=18</code> で行を分割し、ページごとに見出し・列見出し・注記・「n/mページ」を付けて各ページに余白が付くようにした(1つの長い表を流すと2ページ目以降の上余白が無くなるため)。ガードレール「印刷HTMLは必ずページ要素で包む」に「外側に padding を書いても消える・内側divに書く・長い一覧はページ分割」を追記し、memory(tsumugi-print-margins)にも保存。検査: esbuild/eslint no-undef 0件。安定版0921d/試験版trial43。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">211f840</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"災害時: 連絡先一覧の印刷プレビューが全面グレー: 印刷HTMLをページ要素(page-break-after/data-page-break)で包んでいなかったため、プレビューの白紙+影(_pageSepCss)が付かずキャンバス色のまま→A4横297×210mm・白背景・data-page-break のページ要素で包む。名前も電話も空の緊急連絡先行を除外\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-21</span></div>\n      <p class=\"title\">災害時 連絡先一覧の印刷プレビューが全面グレー — A4横の用紙要素で包む</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">店舗指摘(スクリーンショット): 安否・連絡先一覧の印刷プレビューが、用紙の白が無くグレーの背景に表が直接載って見える。プレビュー(previewSrcDoc)は 2026-09-08 以降、<code>page-break-after</code>/<code>data-page-break</code> を持つページ要素にだけ白紙+影を付け、キャンバスは #525659 にする仕様。436件目で作った印刷HTMLは幅275mmの素の div だけでページ要素の印が無かったため、白紙が付かなかった。あわせて緊急連絡先の欄が空なのは、実データを確認した結果 該当の方の利用者マスタに緊急連絡先が未登録(家族欄がケアマネ名の方はケアマネ除外ルールで非表示)のためで、表示側の不具合ではない。</span><span class=\"lb\">対処</span><span class=\"tx\">印刷HTMLの外側を <code>&lt;div data-page-break=\"1\" style=\"background:white;width:297mm;min-height:210mm;padding:8mm 10mm;box-sizing:border-box;page-break-after:always\"&gt;</code> に変更(他帳票と同じ扱いでプレビューに白紙+影・印刷はA4横1枚)。緊急連絡先は名前も電話も空の行(登録途中の空エントリ)を一覧・印刷から除外。注記に「安否の欄は空欄のときは手書きで」を追記。更新お知らせで「空欄の方はマスタの緊急連絡先が未登録」を案内。検査: esbuild/eslint no-undef 0件。安定版0921c/試験版trial42。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4661190</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"災害時: 退所済みの方が安否一覧・通所中判定・緊急連絡の宛先に含まれていた: p.status==='利用中' の生status判定(終了日を過ぎても status は変わらない)→disasterTargetPatients(isPatientResigned/getPatientDisplayStatus/isPatientActiveOnDate の期間判定)に統一。休止中は在宅として残す\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-21</span></div>\n      <p class=\"title\">災害時の対象者に退所済みの方が含まれていた — 生の status ではなく利用期間で判定</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">店舗指摘: 災害時画面の安否・連絡先一覧に退所済みの方まで出る。安否一覧・通所中判定(computeAttendingNow)・緊急連絡の宛先・家族未登録数の4か所が <code>p.status === '利用中'</code> で対象者を選んでいた。利用終了日を過ぎても status は '利用中' のまま残る(退所済みは <code>isPatientResigned</code>/<code>getPatientDisplayStatus</code> が終了日から判定する)ため、退所した方が残り、逆に休止中(status='休止')の方は在宅の安否確認から漏れていた。ガードレール「status は今の表示用、判定は期間ベース」(2026-09-16)の再発。</span><span class=\"lb\">対処</span><span class=\"tx\">共通関数 <code>disasterTargetPatients(appData)</code> を新設: 利用終了日経過(isPatientResigned)・表示ステータス退所済み・status に「退所/終了」を含む・本日が利用開始前(isPatientActiveOnDate) の方を除外し、休止中の方は在宅として残す。4か所をこの関数に置換(緊急連絡の家族未登録数は activePats を再利用)。検査: esbuild/eslint no-undef 0件。安定版0921b/試験版trial41。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">de73460</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"災害時: 通所中(午前)に午後の方まで含まれ18名表示: computeAttendingNow が本日の提供記録(日単位・AM/PM無し)の出席を見ただけで通所中にしていた→月間スケジュール→基本利用曜日('1日'は両方)・振替は furikaeAmpm で時間帯所属を判定してから記録を見る(日誌 _matchG と同じ考え方)\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-21</span></div>\n      <p class=\"title\">災害時の「通所中（午前）」に午後の方まで含まれていた — 時間帯の所属を先に判定してから提供記録を見る</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">店舗指摘: 災害時画面で「通所中（午前）」なのに18名(午前+午後の全員)が表示される。原因は <code>computeAttendingNow</code>(緊急連絡・安否一覧で共用)が、本日の提供記録に出席/振替/臨時があれば無条件に通所中にしていたこと。提供記録は<b>日単位</b>で午前/午後を持たないため、午後の方も(その日の記録が出席なら)午前に数えられていた。月間スケジュール→基本利用曜日の判定は記録が無い方にしか使われていなかった。</span><span class=\"lb\">対処</span><span class=\"tx\">判定順を変更: ①今の時間帯への所属 <code>inSlot</code> を 月間スケジュールの上書き(`${day}_${slot}`)→基本利用曜日(getScheduleOnDate・'1日'は両方)で決め、振替記録に furikaeAmpm があればそれを優先(日誌の <code>_matchG</code> と同じ考え方) ②所属していなければ除外 ③所属していれば、提供記録の欠席/休業/休止で除外・出席/振替/臨時で確定・記録が無ければ休止期間でなければ通所中。これで午前は午前の方(+1日の方)だけ、午後は午後の方(+1日の方)だけ。緊急連絡の送信先範囲・安否一覧の「通所中/在宅」の人数も同じ関数のため同時に直る。検査: esbuild/eslint no-undef 0件。安定版0921a/試験版trial40。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8311e79</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】送迎表に利用開始日より前の方が表示される: _attendees/_absentees が isPatientResigned(退所)だけを見て利用開始日を見ていなかった→isPatientActiveOnDate(開始前・終了後を除外)を追加。月間スケジュール・日誌と同じ判定に統一\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-19</span></div>\n      <p class=\"title\">【試験版】送迎表に「まだ利用開始日前の方」が出ていた — 開始日より前・終了日より後は表示しない</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">店舗指摘: 送迎表(週間運行表)に、利用開始日がまだ先の方が表示されている。原因は TransportView の <code>_attendees</code>(その日のスロットに来る予定の方)と <code>_absentees</code>(休み欄)が <code>isPatientResigned</code>(退所)だけで除外していて、利用開始日(startDate)を見ていなかったこと。基本利用曜日を登録した時点で、開始前の週にも出てしまう。月間スケジュール(開始前は空欄)・日誌(<code>isPatientActiveOnDate</code>で除外)とは判定が食い違っていた。</span><span class=\"lb\">対処</span><span class=\"tx\">両関数の先頭に <code>if (!isPatientActiveOnDate(p, iso)) return;</code> を追加(既存の共通関数: 開始日当日と終了日当日は含む・文字列比較でタイムゾーン誤差なし)。これで開始日より前は運行表にも休み欄にも出ず、開始日当日から通常どおり表示。終了日を過ぎた方(退所処理前)も同時に消える。試験版のみの画面のため安定版の変更なし。検査: esbuild/eslint no-undef 0件。試験版trial39。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">bfb357a</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ケアマネ連携\" data-text=\"ケアマネ事業所・担当者: 担当ケアマネがあいうえお順にならない(52名中ふりがな登録3名・漢字のlocaleCompare)→登録ふりがな→姓の一般的な読み辞書(_SURNAME_KANA 約330姓)→末尾に漢字順。事業所はカナで五十音順。法人名が1件も無い店舗で全事業所が「（法人名なし）」見出しに入っていた→見出し省略(混在時は「法人名 未登録」)\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-09-19</span></div>\n      <p class=\"title\">担当ケアマネを五十音順に（ふりがな未登録でも姓の読みで並べる）／「（法人名なし）」見出しの整理</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">店舗指摘2点: (1)各種設定→ケアマネ事業所・担当者の「担当ケアマネジャー」が「あいうえお順」と表示しているのに順序がばらばら。実データ(扇橋)で確認すると52名中ふりがな登録は3名だけで、残りは漢字の名前を localeCompare('ja') していた(漢字は読みでは並ばない)。(2)事業所一覧の見出し「（法人名なし）」の意味が分からない。法人名(corporateName)はCSV取り込みでのみ入る項目で、登録・編集モーダルには欄が無いため、扇橋では85事業所すべてが空→全件が「（法人名なし）」グループに入っていた。</span><span class=\"lb\">対処</span><span class=\"tx\">①並び替えキー <code>_cmSortKana</code>: 登録ふりがな(kana) → 姓の一般的な読み辞書 <code>_SURNAME_KANA</code>(約330姓。髙木/髙村/櫻田/手呂内/的野/溝上/渡井など店舗の実在姓を含む) → どちらも無ければ末尾に漢字順。辞書は<b>並び替え専用</b>で表示には使わない(清野=きよの/せいの のように読みが複数ある姓があるため)。カードには「ふりがな未登録」を琥珀色で表示し、件数行に「ふりがな未登録 N名は姓の一般的な読みで並べています」と案内。扇橋の52名は全員が辞書で並び替え可能(シミュレーション確認)。②事業所は kana→name で五十音順。<code>hasAnyCorp</code>(法人名を持つ事業所が1件でもあるか)が偽なら法人見出しを出さず平坦に表示、混在時の空グループ名は「法人名 未登録」に変更。件数行を「あいうえお順(・法人ごと)」に。検査: esbuild/eslint no-undef 0件。安定版0919c/試験版trial38。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2e61d87</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"災害時ハブ画面(店舗提案): サイドバー「緊急連絡（災害時）」を「災害時」に改め 安否・連絡先一覧(住所/電話/緊急連絡先/ケアマネ+安否タップ・通所中/在宅/全員・印刷・電話発信)／緊急連絡(避難先は登録済みから選択+自由記述)／避難場所・ハザードマップ(一時避難場所=公園等・指定避難所=開設後・手順メモ)／備蓄(品名/数量/保管場所/期限)の4タブ。systemSettings.bcpに保存\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-19</span></div>\n      <p class=\"title\">サイドバー「災害時」ハブ — 安否・連絡先一覧／緊急連絡／避難場所（一時・指定）／備蓄を1画面に</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">435件目(緊急連絡v2)への店舗提案: 速報バナーが出なくても対応できるよう、サイドバーを「災害時」にして緊急連絡・ハザードマップ・安否確認をその中に置きたい。避難場所はBCPで登録した場所から選び、その他は自由記述に。民生委員の助言で「学校等の指定避難所は開設後でないと使えないため、一時避難場所(近くの公園)も決めておく」。緊急時は利用者の電話・住所・緊急連絡先・ケアマネを一括で見られる表がほしく、そこでも安否を選べるように。備蓄と保管場所も表示したい。</span><span class=\"lb\">対処</span><span class=\"tx\">新設 <b>DisasterView</b>(4タブ)。①<b>安否・連絡先一覧</b>: 利用中の方を五十音順に、住所(建物・部屋含む)/電話(tel:リンク)/緊急連絡先(getAllContacts 上位2件)/担当ケアマネ(事業所・氏名・電話)を表で表示し、行ごとに安否チップ(無事/避難済み/ケガ・体調不良/未確認)をタップ選択。対象=通所中(AM/PM)/在宅/全員、「全員 無事」「全員 避難済み」「クリア」、A4横印刷(setPrintHtml)。安否・避難先の状態はハブ側の state で持ち、「この安否でご家族へ連絡」で緊急連絡タブへ引き継ぐ(EmergencyNoticeView は props 優先・単体でも動く後方互換)。②<b>緊急連絡</b>: 避難先は登録済みの一時避難場所/指定避難所のプルダウン＋その他は自由入力。③<b>避難場所・ハザードマップ</b>: 一時避難場所(公園等)と指定避難所(開設後)を名称/住所/備考で複数登録、ハザードマップURL(既定=国土地理院ポータル)、避難の手順・役割分担メモ、事業所住所で「近くの避難所を地図で探す」。④<b>備蓄</b>: 品名/数量/単位/保管場所/期限の表と保管場所の説明。期限が60日以内は赤で「要確認」。保存先は <code>systemSettings.bcp</code>(既存の _stampFieldTs により bcp キー単位で刻印→他端末の別項目編集で巻き戻らない)。通所中判定を <code>computeAttendingNow(appData)</code> に共通化(緊急連絡と同一ロジック)。速報バナーの「安否確認」は一覧タブへ、「緊急連絡」は連絡タブへ遷移(sessionStorage tsumugiDisasterTab)。検査: esbuild構文/eslint no-undef 0件。安定版0919b/試験版trial37。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ef2dbcc</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"緊急連絡の強化(店舗提案): ①安否を氏名一覧のタップ選択式(無事/避難済み/ケガ/未確認・全員一括)にし家族ごとの文面と利用者別お知らせを自動生成 ②送信先範囲=通所中(提供記録→月間→基本曜日)/在宅/全員を定型文で自動選択・ケアマネは担当利用者で絞込 ③災害速報バナー(api/alerts.js: 気象庁 地震/津波/警報JSON・1分ポーリング・ハザードマップ/緊急連絡/安否確認/解除・?alerttestで見本)\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-19</span></div>\n      <p class=\"title\">緊急連絡を強化 — 安否はタップ選択・通所中の方だけに送信・気象庁データの災害速報バナー</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">434件目(緊急連絡v1)への店舗提案3点: (1)避難完了は「今の時間帯に通所中の方」のご家族・ケアマネだけに送るべき(在宅の方の無事は事業所が保証できない) (2)安否は文章を直す時間がないので氏名を見てタップで選ぶ方式に (3)地震・津波・洪水の速報をつむぎの画面にポップアップし、ハザードマップ/緊急連絡/安否確認へ遷移・解除ボタン付きに。</span><span class=\"lb\">対処</span><span class=\"tx\">①<b>安否の選択式入力</b>: 対象利用者の氏名一覧に「無事/避難済み(無事)/ケガ・体調不良/未確認」チップ、「全員 無事」「全員 避難済み」「クリア」。選択結果から宛先ごとに『○○様: 無事（避難先: △△）』の行を本文先頭へ自動挿入(家族=自分の家族分・ケアマネ=担当分の一覧)。notify-batch.jsは recipients[].text(宛先別本文)に対応。お知らせは安否のある利用者ごとに familyPersonalAnnouncements(個別)へ、無ければ familyAnnouncements(全体)へ。②<b>送信先範囲</b>: 「今の時間帯(AM/PM=13時境界)に通所中」を 本日の提供記録(出席/振替/臨時=通所・欠席/休業/休止=不在)→月間スケジュール→基本利用曜日(休止期間除外)の順で判定。範囲=通所中/在宅/全員のラジオ、定型文(避難完了→通所中・安否確認→在宅・営業状況→全員)で自動選択。ケアマネは範囲内の利用者を担当する方(閲覧アカウント=patient_id、マスタ=事業所名+氏名で照合)に絞る。③<b>災害速報</b>: api/alerts.js が気象庁の公開JSON(quake/list・tsunami/list・warning/&lt;都道府県&gt;.json)を60秒キャッシュで集約(地震=直近90分・当該県で震度4以上 or 全国震度5弱以上、津波=直近12時間・取消除く、警報=警報/特別警報のみ)。App側は店舗ログイン中1分ごとに取得し最前面(z100000)に赤バナー(特別警報/震度5弱以上は深紅)。ハザードマップ(国土地理院ポータル)・緊急連絡/安否確認(sessionStorageのpresetで定型文・範囲を先に入れて遷移)・解除(IDをlocalStorageに記憶し再表示しない)。都道府県は事業所住所の先頭から判定(47都道府県表・既定=東京)。`?alerttest`で見本表示。実データで取得動作を確認(現在は発表なし=空応答)。<b>制約</b>: EEW(揺れる前)は含まれず発生1〜2分後の情報。安定版0919a/試験版trial36。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e793ed9</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"緊急連絡（災害時）画面を新設(運営推進会議の要望): 定型文3種・避難場所差し込み・宛先=利用中の家族アカウント+担当ケアマネのメール(重複集約)・確認ダイアログ・結果表示。api/notify-batch.js(Brevo 1件ずつ・5並列・300件上限)。家族画面のお知らせにも同時掲載。LINEは費用で見送りメール+Webの2経路\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-18</span></div>\n      <p class=\"title\">「緊急連絡（災害時）」画面を新設 — ご家族・担当ケアマネへ一斉メール＋家族画面お知らせ</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">運営推進会議(9/18)で「災害時の安否・避難場所をご家族・ケアマネへ通知したい」との要望。LINE通知は無料枠(月200通)では店舗数×家族数で足りず有料になるため、本部判断で<b>メール(Brevo・設定済み)＋Webお知らせ</b>の2経路で当日実装。</span><span class=\"lb\">対処</span><span class=\"tx\">①<b>EmergencyNoticeView</b>をサイドバー「緊急連絡（災害時）」に追加(全職員が開ける・送信前に件数付きconfirm)。定型文3種(避難完了・全員無事／営業状況／安否確認のお願い)、避難場所欄は文面に差し込み、事業所名・電話は設定から自動。②宛先: 家族アカウントはクラウド同期対象外のため <code>supabaseListFamilyAccountsForStore(storeId)</code> で店舗単位に取得し、利用中の利用者に紐づく家族(kind≠caremanager)のメール＋担当ケアマネ(careManagers[].email とCMアカウント)を集約。同一メールは1件にまとめ、ラベルに「○○様ご家族・△△様ご家族」を連結。メール登録が無い利用者の人数を表示(電話での補完を促す)。③<b>api/notify-batch.js</b>新設: Brevo経由で1件ずつ(宛先は互いに見えない)・5並列・300件/回上限(無料枠=300通/日)・件名100字/本文4000字・HTMLエスケープ・replyTo=事業所メール・結果 {sent, failed[], skipped[]}。④同時に familyAnnouncements の先頭へ {audience:['family','caremanager','related'], emergency:true} で掲載(既存の家族画面お知らせ表示・未読バッジをそのまま利用)。⑤送信結果(成功件数・届かなかった宛先と理由)を画面に表示。安定版0918f/試験版trial35。<b>残課題</b>: 利用者ごとの安否ステータス入力(無事/要確認/避難先)と災害モードUI・LINE経路は未来の修正点に継続。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ffe3574</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"【本番障害・自責】提供記録RPC v2.0の適用で全店の記録書き込みが約20分失敗(COALESCE types text and integer: patient_id整数列を文字型で扱った)。端末の再送キュー(_pendingRows・7秒再送)が保持し復旧時に一括送信、データ損失なし。v2.1で修正・本番適用・probe OK(項目別時刻比較が有効化)\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"tag crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-18</span></div>\n      <p class=\"title\">【本番障害】提供記録RPC差し替え(v2.0)で書き込みが約20分停止 → v2.1で復旧・項目別時刻比較が有効に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">432件目のサーバー側対策として用意した upsert_ticket_records v2.0 を本部がSupabaseで実行(16:0x)。ticket_recordsのpatient_id列は<b>整数型</b>だが、SQLがtextとして扱っており(<code>coalesce(v_pid, patient_id)</code>)、全ての書き込みが「COALESCE types text and integer cannot be matched」(HTTP 400)で失敗。店舗には「同期に失敗しました」が表示され、iPad/PC間で反映されない状態が約20分続いた。<b>私の確認不足</b>: 列型を実データで確認せず、本番関数を差し替える前に試作店舗で実行検証をしていなかった。</span><span class=\"lb\">対処</span><span class=\"tx\">エラー文から即特定し v2.1(v_pidをintegerに変換・例外時null)を作成→本部が16:26に適用。<b>データ損失なし</b>: 端末側の再送キュー(_pendingRows・localStorage永続化・7秒再送)が保持しており、扇橋iPadは失敗8回(pend=21)の直後16:26:28に21行を一括送信成功、Surfaceも以後全送信成功、テーブルに16:27〜の更新を確認。適用後の検証(scripts/probe_ticket_rpc.py)=OK: 同時刻/古い時刻/時刻なしの空では既存値が消えず、新しい時刻の明示クリアと新しい値だけ反映。<b>再発防止</b>(ガードレール追記): 本番DB関数の差し替えは①列型を information_schema/実データで確認 ②試作店舗の架空行で実行検証 ③失敗時の戻し(pg_get_functiondefの控え)を用意、の3点を必須化。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">62cc856</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"他端末で入れた気分がPCの血圧入力で消える(店舗指摘・真因): ①テーブル差分送信が「この端末の直前appData」比較のため、pullで届いた他端末の気分と古い下書き('')の差が「''への変更」として送られる ②サーバーRPC upsert_ticket_recordsは項目時刻を無視し空で上書き(試作店舗の架空行で実証: 同時刻/古い時刻/時刻なしの空すべてで既存値が消えた)。クライアントは未編集の空を差分から除外、サーバーは項目別時刻比較のSQLを用意\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"tag crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-18</span></div>\n      <p class=\"title\">タブレットの気分がPCの血圧入力で消える — 差分送信とサーバー合成の二重の穴を特定・対策</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">「PCで血圧・タブレットで気分を入れると気分が反映されないことが多い」の再調査。診断ログで送信失敗はゼロ、行IDは決定的で重複なし、保存は同期的で\"保存中の押下\"窓もほぼ無し、と一つずつ潰した結果、残ったのが差分送信の経路。①<b>diffRecordRowsは「この端末の直前のappData」との比較</b>で送る項目を決めるため、タブレットの気分(good)がpullで届いたあとにPCの古い下書き(気分='')を自動保存すると、触っていない気分が「''への変更」として差分に載る(刻印はstamp-gateで止めていたが<b>値そのものは送られていた</b>)。②<b>サーバーRPC upsert_ticket_records は項目ごとの_fieldTsを一切比較せず、jsonb連結(data||excluded)の後勝ち</b>。試作店舗に架空の行(tr_999999_2020_1_1)を作って実証: 気分goodをT時刻で保存後、空を「同時刻T」「古いT-1000」「時刻なし」で送るといずれも<b>既存の気分が消え、_fieldTsまで古い値に戻る</b>。受信側(端末)は非空優先・時刻比較で守っていたため、\"消えた\"のはサーバーとPC側だけ=「タブレットには残っているのにPCに出ない」という報告と一致。</span><span class=\"lb\">対処</span><span class=\"tx\">①<b>クライアント(本rev)</b>: handleSaveToCloudの差分送信で、既存行の提供記録管理項目(_REC_GATED)のうち「この端末が30分以内に実編集していない」かつ「空(未入力)」のものを差分と_fieldTsから除外(rows-gateログ)。実編集済み・非空の値は従来どおり送るので正規の変更は止めない。新規行は従来どおり。②<b>サーバー(要適用)</b>: RPCを項目別に「受信の_fieldTsが既存より新しい時だけ上書き、既存に時刻がなく受信が非空なら採用」へ書き換えるSQLを docs/sql/upsert_ticket_records_v2.sql に用意(本部がSupabase SQL Editorで実行)。①だけでも報告事象は止まるが、②で他の経路(リロード直後の初回保存など)も含めて根本を塞ぐ。実験行は削除済み(deleted_at)。安定版0918e/試験版trial34。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">418fb9e</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"日誌の職員体温ON/OFFチェックの配置を「送迎車両」枠から「担当職員」枠へ移動(店舗指摘: 職員に関する設定なので送迎車両とは無関係の場所に出ていた)\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-09-18</span></div>\n      <p class=\"title\">「日誌に職員の体温を表示・入力する」を各種設定→日誌の「担当職員」枠へ移動</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">430件目で追加したチェックを既存の「1週間前の送迎を自動コピー」の直下に置いたため、送迎車両の枠に表示されていた。店舗から「職員の設定なので担当職員の方にあるべき」と指摘。</span><span class=\"lb\">対処</span><span class=\"tx\">DiarySettingsPanelの「担当職員」カード末尾(職員一覧の下)へ移動。保存先(diarySettings.hideStaffTemp)・動作は変更なし。安定版0918d/試験版trial33。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">03aedec</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"各種設定\" data-text=\"ケアマネ事業所の電話/FAXを編集しても一覧に保存されない(店舗指摘・真因): saveCmEditが編集対象をo===origの同一性で探すが、渡しているのは{...o,origIdx}のコピーで決して一致せず一覧側が無変更(担当者・利用者側だけ更新)。担当者の直通番号も編集中の同期で配列が差し替わると消失。FAX自動送信は利用者側FAXが空だと送信対象外(扇橋61名)→事業所一覧へフォールバック\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"tag crit\">重大</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-09-18</span></div>\n      <p class=\"title\">ケアマネ事業所の電話・FAX、担当者の直通番号が保存されない不具合を修正(FAX送信先の補完も)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">実データ監査で、扇橋の事業所一覧85件の同期タイムスタンプが<b>7/30で停止</b>していることを確認。コードを追うと、各種設定→ケアマネの編集保存(saveCmEdit)が編集対象を <code>o===orig</code> の同一オブジェクト判定で探しているのに、編集画面へ渡す orig は一覧描画時に作った <code>{...o, origIdx}</code> の<b>コピー</b>のため一致せず、<b>事業所一覧は一切書き換わらない</b>(電話は完全に消失、FAXは担当者・利用者側だけ更新され一覧は旧番号のまま=「直したのに反映されない」の正体)。改名時は旧名の墓石だけ刻まれ新名が作られない危険も。担当者側は同一性判定が通常は成立するが、編集小窓を開いている間は未保存フラグが立たないため<b>同期の再取得で配列が差し替わると c===orig が外れ直通番号が消える</b>(間欠)。保存後に未保存判定の基準も更新しておらず「未保存があります」が出続けていた。さらにモニタリング表のFAX自動送信は <b>利用者側の cmFax しか見ず</b>、空の利用者は黙って送信対象外(扇橋73名中61名が該当。印刷用送付状は事業所一覧へフォールバックしており不整合)。</span><span class=\"lb\">対処</span><span class=\"tx\">①事業所は origIdx(無ければ名前)で照合、担当者は同一性に加え事業所+氏名でも照合。②保存後に _dirtyBaseRef/_setBaseRef を更新し dirtyRef を解除(persistCmと同じ)。③再同期エフェクトは cmEditModal が開いている間スキップ。④FAX自動送信の宛先を「利用者のcmFax → 無ければ事業所一覧のFAX」に(送付状と同じ優先順位・未登録メッセージも両方を案内)。<b>実データ影響</b>: 扇橋は一覧にFAXがあるため61名が送信可能に。他店は一覧にもFAXが無いため引き続き要登録(南水元のみ利用者側に全員分あり)。一覧に残っている旧番号は店舗で確認・修正が必要(東砂長寿サポートセンターは利用者側と一覧でFAX末尾が不一致: 8550/8240)。安定版0918c/試験版trial32。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7ab198b</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌の職員体温を店舗ごとにON/OFF(店舗要望): 各種設定→日誌に「日誌に職員の体温を表示・入力する」チェック(diarySettings.hideStaffTemp)。OFFでは担当職員チェック時の体温入力小窓が開かず、℃表示も画面・印刷とも非表示。既定はON(従来どおり)\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-18</span></div>\n      <p class=\"title\">日誌の職員体温の表示・入力を店舗ごとに切り替え可能に(各種設定→日誌)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">「体温を入力している店舗としていない店舗があるので、表示するかどうかを設定で切り替えたい」との要望。調査の結果、日誌の体温は<b>利用者ではなく職員の検温</b>(担当職員にチェックを入れると体温入力の小窓が自動で開き、氏名の下に℃表示)であることを確認。</span><span class=\"lb\">対処</span><span class=\"tx\">各種設定→日誌の「1週間前の送迎を自動コピー」の下に「<b>日誌に職員の体温を表示・入力する</b>」チェックを追加(即時保存・diarySettings.hideStaffTemp・既定ON)。OFFの店舗はチェック時の小窓が開かず、℃表示も出ない。日誌の画面・印刷プレビュー・A4印刷は同じ描画関数(DiarySheet)のため1箇所の条件で全て反映。過去に入力済みの体温データは消さない(ONに戻せば再表示)。diarySettingsは項目別の同期保護(_fieldTs)が自動で効く。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7ab198b</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"未定義識別子の潜在バグ3系統(eslint no-undefで全体検査・店舗依頼「他のAIやGoogleでも同じ現象が起きないか検証」): MasterViewのsetShowToast×3(URL/招待コードのコピー)・FamilyPatientViewのauthAccId×2・同appData×2。共通トーストイベントtsumugi-toastを新設。検査後0件\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-09-18</span></div>\n      <p class=\"title\">「その画面に無い変数を呼ぶ」型の潜在バグをアプリ全体から機械検査し3系統を修正</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">staffSession未定義(427件目)と同じ現象が「他のAIやGoogleでも起きないか検証して直してほしい」との依頼。目視ではなくeslintの<b>no-undef</b>(未定義識別子検出)を安定版・試験版のApp.jsx全体(約49k行)に掛けた。外部サービス呼び出し(AI/Googleマップ/FAX/メール等 24箇所)は問題なし。代わりに<b>別の3系統</b>が見つかった。</span><span class=\"lb\">対処</span><span class=\"tx\">①<b>MasterView</b>: ログインURL・招待URL・招待コードの「コピー」3箇所が、この画面に無い<code>setShowToast(true)</code>を呼んで止まっていた(コピー自体は成功するが通知が出ず例外)。App側に共通イベント<code>tsumugi-toast</code>のリスナー(既存トーストに文言を流し2.5秒で消える)を追加し、MasterViewは<code>_copyToast()</code>で発火。②<b>FamilyPatientView</b>(ご家族アプリ)のオフライン時パスワード変更で<code>authAccId</code>×2→prop<code>accountId</code>。③同・招待トークン生成で<code>appData</code>×2→prop<code>data</code>(事業所名・電話がトークンに入らずReferenceErrorで招待が止まる)。修正後の再検査で<b>no-undef 0件</b>。<b>運用</b>: 一時ディレクトリのeslint(scratchpad/lintwork・eslint.config.mjs)を締めの検査に組み込む(ガードレール追記)。安定版0918b/試験版trial31。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">228054b</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"提供記録\" data-text=\"AI下書きで「staffSession is not defined」(店舗指摘): MonitoringViewがstaffSessionを受け取っていないのにtsumugiCallAiへstoreIdを渡す2箇所で参照→ReferenceErrorで全員失敗。2026-09-08プロキシ化で混入し別の不具合に隠れていた。propとして渡すよう修正\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"tag crit\">重大</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-18</span></div>\n      <p class=\"title\">AI下書きが「staffSession is not defined」で全員失敗する不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">前rev(6405408)で失敗理由を画面に出すようにした結果、店舗から「浅見様: staffSession is not defined」の報告が届き即特定。MonitoringViewのpropsは{ appData, onSave, dirtyRef, saveFnRef, onShowPrintPreview }のみで、2026-09-08のAIプロキシ化で追加した<b>tsumugiCallAi(…, staffSession?.storeId)</b>の2箇所(generateOne/aiDraftSheet)がスコープ外の識別子を参照しReferenceErrorになっていた。それまでは「キー未設定」の例外が先に出る/例外が握りつぶされる、の二重で表面化していなかった。</span><span class=\"lb\">対処</span><span class=\"tx\">MonitoringViewの引数に staffSession(既定null)を追加し、App側の描画箇所で staffSession を渡す。参照はoptional chainingのためnullでも安全。<b>教訓</b>: 例外を握りつぶすと1つ直しても次の潜在バグが順に出る(9/8混入→9/17に2段階で露見)。前revで入れた「失敗者と理由の表示」が正しく機能して1往復で真因に到達した。安定版0918a/試験版trial30。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5501e0b</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"提供記録\" data-text=\"AI下書きが「0名作成しました」で何も作られない(店舗指摘・真因): tsumugiServerAiAvailableが起動時のfalse判定を恒久キャッシュし、管理局でキー登録後もリロードまでAI未設定扱い→true判定のみ保持・falseは30秒で再確認・登録/削除時に即リセット。例外の握りつぶしも改め失敗者と理由を表示。JSON解析の頑健化+max_tokens1500\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"tag crit\">重大</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-17</span></div>\n      <p class=\"title\">AI下書きが「0名のモニタリング表を作成」で終わり何も作られない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">本部キーを管理局で登録した直後、店舗画面のモニタリングで1名選択→AI下書きを押すと「✓ 0名のモニタリング表を作成・保存しました」とだけ出て作られない。サーバー経由でAIは応答する(実測: 入力627/出力407トークン・stop_reason=end_turn・JSON解析成功)ため、原因はクライアント側。tsumugiServerAiAvailable()が<b>起動時に一度「未設定(false)」と判定するとそれを恒久キャッシュ</b>しており、同じタブで管理局からキーを登録しても、ページを再読み込みするまで「AI未設定」扱いのまま。generateAllSheetsのcatchが例外を黙って捨てていたため、失敗理由が画面に一切出ず「0名」としか分からなかった(既存の設計上の欠陥)。</span><span class=\"lb\">対処</span><span class=\"tx\">①判定キャッシュを「trueだけ保持・falseは30秒で捨てて再確認」に変更(_tsumugiSrvAiProbeAt)。notConfigured受信時も時刻を記録。②tsumugiResetAiProbe()を新設し、管理局の外部サービス設定でキーを登録/削除した瞬間に判定をリセット(店舗画面へ移っても待たずに使える)。③generateAllSheetsの例外を_errsに集約し、終了時にmonAlertで「失敗した方の氏名: 理由」を最大5件表示(それ以上は件数)。ok=0のときは保存もsetResultsも行わない。④aiDraftSheetのJSON解析を頑健化: content全ブロック連結(先頭ブロックのみ読むと取りこぼす)・```json フェンス除去・最初の{〜最後の}を抽出・失敗時は応答先頭60字を含むエラー。空応答はstop_reason付きで報告。max_tokensを1000→1500へ。安定版0917c/試験版trial29。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6405408</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"管理局\" data-text=\"外部サービス設定を管理局に集約(店舗要望): _services.js(サービス定義10件)と_secrets.js(環境変数→app_secretsの順で解決・60秒キャッシュ)を新設。admin-secrets.jsで一覧/登録/削除/接続テスト。既存9エンドポイント(Brevo系6・InterFAX・Googleマップ・AI)を共通ヘルパー経由へ移行\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">管理局</span><span class=\"date tnum\">2026-09-17</span></div>\n      <p class=\"title\">外部サービス設定を管理局に集約（AI / マップ / メール / FAX を1画面で一括管理）</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">AIキーの本部一元化に続き、「Google・FAXなど、今後入れる予定のものや既に入っているAPI・他社サービスの設定もまとめてほしい」との指示。設定が環境変数・店舗設定に散在しており、何がどこで設定済みかを俯瞰できなかった。</span><span class=\"lb\">対処</span><span class=\"tx\">①<b>api/_services.js</b>にサービス定義を集約(稼働中7: Claude/Googleマップ/Brevo/InterFAX/管理局の合言葉/台帳認証/Supabase ＋ 導入予定3: LINE通知/国保連請求/電子同意書)。<b>新サービスはこの配列に1件足すだけで管理局の画面に出る</b>。②<b>api/_secrets.js</b>(共通ヘルパー)を新設し、資格情報を<b>Vercel環境変数 → app_secrets の順</b>で解決(60秒キャッシュ=画面での差し替えが最大1分で全店反映)。環境変数があれば従来どおり優先されるため既存運用に影響なし。③<b>api/admin-secrets.js</b>で一覧・登録・削除・接続テストを提供(ADMIN_API_SECRETで認証・timingSafeEqual)。接続テストはサービスごとに実装(Claude=メッセージ1往復/Googleマップ=Geocoding/Brevo=アカウント照会/InterFAX=残高照会)。④<b>既存9エンドポイントを共通ヘルパー経由へ移行</b>(admin-reset・brevo-keepalive・family-reset・report・send-invite・send-password・send-store-welcome・send-fax・route-plan)。⑤管理局UIをAI設定から<b>外部サービス設定</b>へ拡張(サービスごとに設定済み/未設定(要対応)/導入予定のバッジ・環境変数管理の項目は編集不可と明示・導入予定は折りたたみ)。⑥admin-ai-key.jsはadmin-secrets.jsへ統合し削除。⑦設定手順書(Artifact)を作成。安定版0917b/試験版trial28。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2163d46</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"管理局\" data-text=\"AIキーを本部一括管理へ(社長承認): 管理局に「AI設定」カード新設(登録/変更/削除/接続テスト/状態表示)。キーはSupabase app_secrets(RLSでservice_roleのみ)に保存しブラウザへは末尾マスクのみ。api/admin-ai-key.js新設(ADMIN_API_SECRET認証・timingSafeEqual)。各店のanthropicApiKeyは全13経路から除去\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">管理局</span><span class=\"date tnum\">2026-09-17</span></div>\n      <p class=\"title\">AIキーを本部で一括管理(管理局に「AI設定」新設・各店のAPIキー欄は廃止)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">社長承認によりAIはClaude APIで進めることが決定。各店が個別にAPIキーを設定する運用をやめ、本部で1つ登録すれば全店に反映される形にしたいとの指示。</span><span class=\"lb\">対処</span><span class=\"tx\">①<b>管理局に「AI設定」カード</b>を新設(GlobalAiPanel・セクションジャンプにも追加)。キーの登録・変更・削除、実際にAIを1回呼ぶ接続テスト、稼働状態(環境変数/画面登録の別)の表示ができる。②<b>api/admin-ai-key.js</b>を新設。認証は環境変数ADMIN_API_SECRETとの照合(crypto.timingSafeEqualで比較)。保存先はSupabaseの<b>app_secrets</b>テーブル(RLS有効・ポリシー無し=service_roleのみ読み書き可)で、<b>ブラウザへはキーを一切返さず末尾マスクのみ</b>。③<b>api/ai-draft.js</b>を改修し、ANTHROPIC_API_KEY(環境変数)→app_secretsの順でキーを解決(60秒キャッシュ=管理局での差し替えが最大1分で全店反映)。④各店のanthropicApiKeyを設定UI・state・dirty判定・保存/同期経路・利用箇所の<b>全13経路から除去</b>。⑤<b>潜在バグ修正</b>: aiDraftSheetが本部キーの使える状態でもキー必須で例外を投げていた(モニタリング表の一括生成が使えない)。⑥docs/sql/app_secrets.sqlを同梱(Supabaseで1回実行)。<b>キーはapp_stateに置かない方針を明文化</b>(app_stateは公開キーで誰でも読めるため)。安定版0917a/試験版trial26。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9175787</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"セキュリティ\" data-text=\"【要対応】実データ監査で2件の露出を確認: ①扇橋のapp_stateにClaude APIキーが平文保存され公開キーで読み取り可能 ②staffテーブルがpassword_hash込みで公開キーから全件読み取り可能(ソルト固定)。①はキー無効化+本部一括管理へ移行、②はRLS是正が必要\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"tag crit\">重大</span><span class=\"area\">セキュリティ</span><span class=\"date tnum\">2026-09-17</span></div>\n      <p class=\"title\">【要対応】実データ監査でクラウド上の情報露出を2件確認(APIキー・職員パスワード)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">AIキーの本部一括管理を実装するにあたり実データを確認したところ、2件の露出が判明。①<b>Claude APIキーの平文保存</b>: 扇橋店のapp_state.systemSettings.anthropicApiKeyに108文字のキーが平文で保存され、<b>公開キー(publishable key)で誰でも取得できる</b>状態だった(実際に取得できることを確認)。漏れた場合、第三者が本部の課金でAIを使い放題になる。②<b>staffテーブルの露出</b>: 公開キーで staff テーブルの全行が<b>password_hash・role込みで読み取れる</b>(実際に2件取得して確認)。ハッシュはSHA-256でソルトが全ユーザー共通の固定値(tsumugi_v1_)のため、総当たり・辞書攻撃でパスワードを逆算できる。いずれもRLS(行レベルセキュリティ)が緩いことが根本原因。</span><span class=\"lb\">対処</span><span class=\"tx\">①<b>本rev</b>: 店舗側でキーを保存する経路を全廃し、本部の1キーをサーバー(app_secrets・RLSでservice_roleのみ)で保管する方式へ移行。既存の平文キーを全店から削除するスクリプト(purge_store_apikey.py・CAS対応)を用意。<b>既に外部から取得可能だった以上、Anthropicコンソールでの当該キーの無効化(Revoke)が必須</b>である旨を本部へ報告。②<b>未対応</b>: staffテーブルのRLS是正は、現在のログイン処理(supabaseStaffLoginが公開キーでusername+password_hashを直接検索)がRLSに依存しているため、ログインをサーバー経由(/api/staff-login)へ移す改修とセットで行う必要がある。全店のログインに影響する変更のため、計画を立てて別途実施する(ユーザーへ報告済み・未来の修正点に記録)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">監査</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】送りの下書きを「迎えの逆順」に(店舗要望): toggleDropModeで各車の並びをreverse()・その他(others)も引き継ぐ。ボタン文言も動作が分かる表記へ\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-17</span></div>\n      <p class=\"title\">【試験版】「送りを別に設定」で迎えの逆順の下書きが入るように</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">「送りも表にすべきか」の相談に対し、送りは当日の欠席・早退で変わるため前日に作り切る運用は現実的でなく、他社SaaSも『迎えから自動生成して当日手直し』が標準であることを回答。つむぎの既存機能(dropMode)を活かし、下書きの精度を上げる方針で合意。</span><span class=\"lb\">対処</span><span class=\"tx\">toggleDropModeで送りを作る際、各車の乗車順をreverse()した並びを下書きにする。迎えは遠い方から乗せる(最後が最寄り)ため、送りは近い方から降ろす逆順が実態に近く手直しが減る。あわせて徒歩に加えその他(others)も引き継ぐよう修正(従来は欠落)。ボタン文言を「送り: 迎えと同じ（タップで別に・迎えの逆順で下書き）」「送り: 別に設定中（タップで迎えと同じに戻す）」に変更し動作を明示。順番は長押しドラッグで変更可。試験版trial25。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6a8c967</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"社外資料\" data-text=\"ご紹介資料: 8枚目にページ番号が無く以降が1ズレ→全12枚を1/12〜12/12で振り直し。右上ロゴが96x41の横長画像を26x26の正方形指定で左右に潰れていた→height基準+width:autoへ(12箇所)\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">社外資料</span><span class=\"date tnum\">2026-09-17</span></div>\n      <p class=\"title\">ご紹介資料のページ番号ズレと、右上ロゴの縦横比つぶれを修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①8枚目「数字が見える — 分析・グラフ」にpageno要素が無く、以降のスライドの番号が1つずつ繰り上がってズレていた(最終12枚目が「12」表示にならない)。②右上のつむぎマークは原寸96×41の横長画像なのにstyle=\"width:26px;height:26px\"と正方形で指定しており、左右に圧縮されて表示されていた(全12スライド)。</span><span class=\"lb\">対処</span><span class=\"tx\">①表紙・裏表紙を除く本文12枚へ通し番号を機械的に振り直し(「n / 12」表記に統一)。番号の無いスライドには自動で付与、表紙・裏表紙に番号があれば除去する方式にしたため、今後スライドを増減しても再実行で整合する。②style=\"height:26px;width:auto\"へ変更し原寸比2.34を維持(headless chromiumで描画実測60.9×26.0px・比2.34を確認)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">資料</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"社外資料\" data-text=\"運営推進会議 ご報告資料(全10枚)を新規作成: ご紹介資料から料金/他社比較/売上の映る分析を除外し、個人情報の取り扱いと安全管理スライドを追加。表紙・裏表紙の文言も会議向けに\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">社外資料</span><span class=\"date tnum\">2026-09-17</span></div>\n      <p class=\"title\">運営推進会議 ご報告資料(全10枚)を新規作成</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">ご紹介資料(営業用)とは別に、運営推進会議で配れる報告版を作成。<b>除外</b>=「料金のめやす」「よくある介護ソフトとのちがい」(店舗指示)に加え「分析・グラフ」(稼働率・売上の画面が映るため会議には不適と判断)。<b>追加</b>=「個人情報の取り扱いと安全管理」1枚。会議では必ず問われる論点のため、アプリ内の同意ポリシー(プライバシーポリシー1〜11項)の記載に厳密に沿って、記録の保管(毎日バックアップ・通信暗号化・退所後5年)/見られる人の限定(職員は個別ID・操作ログ、家族は自分の家族のみ、本人同意のうえで共有、法令以外の第三者提供なし)/外部サービス・AIの利用(委託・国外処理の可能性・AIは補助で最終確認は職員・同意取得済)/ご本人ご家族の権利(開示訂正利用停止削除・アカウント停止・改定通知)の4区画で構成。<b>表紙</b>は「記録のICT化について（ご報告）」「運営推進会議 ご報告資料」に、<b>裏表紙</b>は問い合わせ誘導からご意見募集の文言に変更。ページ番号は生成スクリプトで自動採番(1/10〜10/10)。生成は make_kaigi.py で、紹介資料の更新後に再実行すれば作り直せる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">資料</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"設定リストの並べ替えを▲▼ボタンから長押しドラッグへ(店舗要望): 汎用フックuseLongPressReorder新設(0.2秒長押し・行の上半分=前/下半分=後ろ・入力欄からの長押しは除外)。連絡帳フォーマットの表示項目リスト/運動メニュー/個別運動メニューの3リストに適用\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-09-16</span></div>\n      <p class=\"title\">設定リストの並べ替えを長押しドラッグに(▲▼ボタン廃止・3リスト共通)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">送迎表の長押しドラッグが好評で、設定画面の並べ替えも同じ操作にしたいとの要望。▲▼は1回に1つずつしか動かせず、離れた位置への移動が手間だった。</span><span class=\"lb\">対処</span><span class=\"tx\">汎用フックuseLongPressReorder(items, onReorder)を新設。0.2秒長押しでドラッグ開始→elementFromPointで行を特定し、行の上半分=その前/下半分=その後ろへ挿入(送迎表と同じ判定)。ドラッグ中は元行を半透明化+挿入位置に青線。input/select/textarea/button/label上から始めた長押しは除外(文字入力・削除を妨げない)。touchAction/userSelect/contextMenuもドラッグ中のみ制御。適用先=連絡帳フォーマット設定の表示項目リスト(ContactBookConfigModal)・各種設定の運動メニューの項目(exerciseItems)・個別運動メニューの項目(individualExerciseItems)。▲▼ボタンとmoveItemは削除し、GripVerticalのつまみアイコン+操作ヒントを表示。安定版0916c。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2941a81</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】週間運行表の文字拡大(店舗指摘): 空席枠を定員固定→週最大乗車数+1行(定員上限)・有効高の見積りを実測630pxへ補正・見出し行間圧縮・休み/徒歩/備考を本文と同サイズ。headless実測で3ケース1枚収まりを検証(空きの多い週は9→12px)\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-16</span></div>\n      <p class=\"title\">【試験版】1週間分の運行表の文字を拡大(空席枠の見直し+有効高の実測補正)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">「名前や時間が小さくて見づらい・休みの字も大きく」との指摘。①空席行を常に定員数分(扇橋は5+6+3=14席×午前午後)確保していたため、実際は2〜3名しか乗らない週でも28行分の高さを使い、フォント自動計算が9pxまで縮んでいた。②有効高の見積りが590pxで実測(約630px)より小さく、その分も無駄に縮んでいた。③下部情報(休み/徒歩/備考)がfz-1で本文より小さかった。</span><span class=\"lb\">対処</span><span class=\"tx\">①空席枠を「その週の最大乗車数+1行(手書き用)・ただし定員を超えない」に変更。行数は週内で一定なので曜日間の位置ズレ(当初要望のガタつき防止)は維持したまま、空きのある週ほど文字が大きくなる。②有効高を実測値630pxへ、行高の式も実測(1.25×fz+3)へ補正。③車名ヘッダ/列見出しの行間を1.35→1.2/1.1に圧縮。④休み・徒歩・その他・初回・送り別・備考を本文と同じ大きさへ。<b>検証</b>: headless chromiumで満席週/通常週(9/21週の実配車)/空き週の3ケースをレンダリングし、各日セルの必要高と割当高を実測。全て275×190mm1枚に収まり余裕12〜27px(空き週=9→12px、満席週は幾何学的限界で9px維持)。満席週をさらに拡大するには午前/午後を別紙にする必要があり、要望を待って対応。試験版trial24。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">302474b</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"送迎表\" data-text=\"【試験版・真因】休止期間が終わった利用者が送迎表に出ず休み欄に回り続ける: patient.statusは再開操作まで'休止'のまま残る仕様なのに送迎表だけが生statusで判定していた。_isPausedOn(期間ベース)へ一本化し利用者マスタ/月間スケジュールと整合。扇橋実データで復帰2名・休止維持1名を検証\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"tag crit\">重大</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-16</span></div>\n      <p class=\"title\">【試験版】休止期間が終わった利用者が送迎表に出てこない(休み欄に回る)真因を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">店舗指摘「成田様は出席なのに休み欄にいる」の再調査で真因を特定。休止は期間(pauseHistory: fromDate〜toDate)で管理し、patient.statusは再開操作をするまで'休止'のまま残る仕様。利用者マスタ・月間スケジュールはgetPatientDisplayStatus(終了日を過ぎた休止は「利用中」)で正しく出席表示していたが、送迎表の_attendees/_absenteesだけが生のp.status==='休止'で判定していたため、期間終了後も送迎表から除外され休み欄に回り続けていた(前revで入れた提供記録チェックは休み欄から消すだけで、送迎表本体には出ないままだった)。</span><span class=\"lb\">対処</span><span class=\"tx\">日付指定の休止判定_isPausedOn(p,iso)=getPauseReasonOnDate(期間内 or 無期限休止中)+履歴なし休止の保険、を新設し_attendees/_absenteesの生status判定を全廃して一本化。保存済みプランにも「予定に居るのにプランに居ない人」を未割当へ補充する既存機構があるため、保存済みの日でも未割当に出る。実データ検証(扇橋)=送迎表に復帰2名(成田様・小松崎様=休止期間終了済)/引き続き休止1名(茂木様=無期限休止中)で意図通り。ガードレール追記「statusは表示用・判定は必ず期間/日付ベースで」。試験版trial23。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1017b23</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】操作性3点: ①出席しているのに休み欄に出る(休み判定が月間スケジュールのみで当日の提供記録を見ていない)→出席/振替/臨時の記録があれば除外 ②長押しドラッグ開始0.35→0.2秒 ③ドロップ位置=行の上半分は前/下半分は後ろ(末尾ドロップ容易化)\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-16</span></div>\n      <p class=\"title\">【試験版】出席者が「休み」に出る食い違いを修正+長押し0.2秒化+末尾ドロップ改善</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①休み欄の判定が基本利用日+月間スケジュールの記号のみで、当日の提供記録を参照していなかった。予定上は欠席・休止のまま実際に来所した方(記録=出席)が休み欄に残る。②長押し0.35秒が遅く感じる。③ドロップは「行の上=その行の前に割込み/行以外の余白=末尾」の仕様で、行が詰まった車では末尾用の余白がほぼ無く、末尾に入れるのに細かい位置調整が必要だった。</span><span class=\"lb\">対処</span><span class=\"tx\">①_absenteesに当日の提供記録チェック(_recAttendsOnDate: 出席/振替/臨時)を追加し、記録がある方は休み欄から除外(画面・週間/日別印刷とも同関数)。②ドラッグ開始の長押しを0.2秒へ短縮(スクロール等で指が動けばタイマー解除は従来通り)。③ドロップ先判定を共通化(_dropTarget)し、行の上半分=その行の前/下半分=その行の後ろへ挿入。最後の行の下半分=末尾になり狙いやすく、ドラッグ中のハイライトも同じ判定で追従。表示・操作のみの変更でデータ構造は無変更。試験版trial22。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9269a66</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】印刷が左上に寄る: 印刷ホストのbody>*{margin:0!important}でラッパーのmargin:auto中央寄せが無効化されていた→ページ全面ラッパー+flexで上下左右中央配置(週間/日別/連絡先)\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-16</span></div>\n      <p class=\"title\">【試験版】印刷が左上に寄る問題を修正 — 用紙の上下左右中央へ配置</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">印字可能域への縮小(275×190/188×275mm)ラッパーを margin:4mm auto 0 で中央寄せしていたが、共通の印刷ホストが印刷時CSSで body直下要素の margin/padding を 0!important に強制するため中央寄せが無効化され、内容が左上に寄って右下に余白が偏っていた。</span><span class=\"lb\">対処</span><span class=\"tx\">marginに依存せず、ページ全面(297×209/210×296mm)のラッパー div+flex(align-items/justify-content:center)で内側の印字可能域ボックスを上下左右中央に配置する方式へ変更。週間・日別・連絡先一覧の3種すべて適用。共通印刷ホスト側は他帳票への影響を避けるため無変更。試験版trial21。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">adf7c59</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】連絡先一覧の列幅・フォント再調整(店舗指摘): 下余白が大きい割に文字8pxまで縮小→行高見積りを実態に合わせフォント自動拡大(上限16px)。氏名fz×7.5/電話fz×9.5に拡幅・住所列を相対的に圧縮\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-16</span></div>\n      <p class=\"title\">【試験版】連絡先一覧の文字を1枚に収まる範囲で自動拡大+氏名・電話を拡幅、住所を圧縮</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">フォント自動計算の行高見積りが過大(×1.35+5px・行数も1.3倍換算)で、実際は下に大きく余白が残るのに約60名時で8pxまで縮小していた。また氏名・電話列がギリギリで住所列だけ余っていた。</span><span class=\"lb\">対処</span><span class=\"tx\">①見積りを実態(行数+見出し1行×(fz×1.3+5px)・有効高640px)に修正し、収まる範囲で最大16pxまで自動拡大(約60名の週で8→11px)。②氏名列fz×6.5→7.5・電話列fz×8.8→9.5に拡幅し、余りがちな住所列(可変)を相対的に圧縮(住所フォントはfz-2で折返し許容)。表示/印刷のみの変更。試験版trial20。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1a0ac46</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】週間印刷の空席行だけ太る(2・3列目フォント未指定で既定16px)→全体が計算より膨らみ下が見切れる問題を修正。列見出し幅の不整合(61/25/14→71/18/11%)・連絡先電話列のはみ出し・日別空席行の高さも統一\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-16</span></div>\n      <p class=\"title\">【試験版】印刷の「空席行だけ太い・全体が広がる・電話がはみ出す」を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①週間印刷の空席行(emptyRow)は1列目のみフォント指定があり、2・3列目が未指定でブラウザ既定の16pxで描画。名前入り行(9〜14px自動計算)より空席行が太り、空席が多い週ほど各車の枠が高さ計算より膨らんで全体が広がり、ページ下端(午後のタント等)が見切れていた。②車内の「氏名/時間/次回」見出しがv3.3の列幅変更(71/18/11%)前の61/25/14%のままで列とズレ。③連絡先一覧の電話列が固定幅fz×7.8pxでは余白・罫線込みで携帯番号13桁に数px不足しはみ出し。</span><span class=\"lb\">対処</span><span class=\"tx\">①空席行の全セルへ名前入り行と同じfont-size/line-height/paddingを指定(手書き追記用に同高のまま)。②見出し幅を71/18/11%へ整合。③電話列をfz×8.8pxへ拡幅+padding縮小+overflow:hiddenの保険。④日別印刷の空席行も名前入り行と同じ高さ(fz・padding2px6px)に統一。表示/印刷のみの変更でデータ・保存系は無変更。試験版trial19。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">54fbf95</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"気分理由の特記転記を廃止(店舗指示)し、モニタリングAIへ理由(kibunDetail: 日付つき通所時/帰宅時の気分+理由)を直接渡す方式へ変更。2文報告とモニタリング表の両プロンプトに追加\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-16</span></div>\n      <p class=\"title\">気分の理由は特記へ転記せず、モニタリングAIが気分欄から直接読む方式へ変更</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">前rev(4bd4101)で理由を特記へ自動転記する仕様にしたが、店舗判断で「特記は職員の記録専用のままにしたい。転記しなくても理由がモニタリング要約に反映されればよい」と方針変更。</span><span class=\"lb\">対処</span><span class=\"tx\">①決定時の特記転記(【気分・通所/帰宅】行)を廃止(記録クリア時の同行削除は過去転記分の移行掃除として残置)。②モニタリングAIの集計(buildPatientData)に kibunDetail=出席日の日付つき『通所時いまいち（眠れなかった）／帰宅時良い（…）』一覧を追加し、2文の月次報告文とモニタリング表本体の両プロンプトへ「気分の理由(本人の様子・日付つき・同日の通所→帰宅の変化に注目)」として渡す。これで転記なしでも『◯日は眠れず気分がすぐれなかったが帰宅時は改善』のような要約が可能。絵文字のみの入力は従来通り平均+内訳で反映。③update-notesの気分刷新noteの②を新仕様の説明へ差し替え(安定版0916b/試験版trial18)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">eeb8481</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"気分入力の刷新(店舗要望): 既定理由チップを大分類4つへ縮減+自由入力をtextarea化(OSマイクの音声入力ヒント付き)+理由入力時は特記へ【気分・通所/帰宅】行を置換方式で自動転記(クリア連動)\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-16</span></div>\n      <p class=\"title\">気分入力の刷新 — 理由チップは大分類4つ+自由欄(音声入力ヒント)+特記へ自動転記</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">「チップだと毎回同じものしか選ばれず本当の理由が分からない」との相談。気分は絵文字5種のまま、理由を『大まかな分類4つ+自由欄』へ再設計し、自由欄はOSキーボードのマイク(音声入力)で埋める運用に(開発不要・iPad/スマホで今日から使える)。</span><span class=\"lb\">対処</span><span class=\"tx\">①既定の理由チップ(DEFAULT_KIBUN_REASONS)を通所時/帰宅時×気分5種の全組み合わせで大分類4つへ縮減(例: 通所時×いまいち=体調不良/痛みがある/眠れなかった/気分の落ち込み)。カスタム設定(systemSettings.kibunReasons)がある店舗はそちら優先で従来通り。②理由の自由入力を1行入力→textarea(2行)へ変更し「ヒント: iPad・スマホはキーボードのマイクボタンで音声入力できます」を常時表示。③理由を入れて決定すると特記へ『【気分・通所】いまいち（理由）』形式の行を自動転記。同じマーカー行は置換方式なので押し直しても増殖せず、「記録をクリア」でも該当行を削除(連動)。④いまいち系以外(とてもいい/いい/ふつう/絶不調)でも理由ステップを表示(既存挙動を維持しチップ文言を気分別に刷新)。updateRecordはfunctional setState化済みで気分+特記の連続更新も安全。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4bd4101</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】v3.3: 実機印刷の見切れ修正(印字可能域275×190/188×275mmへ縮小)+空席セル同高(手書き追記用)+週間から未割当削除・氏名列71%で文字拡大+連絡先一覧2段組(電話=携帯優先)+画面未割当コンパクト化\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-16</span></div>\n      <p class=\"title\">【試験版】v3.3: 実機印刷フィードバック対応(見切れ・空席セル・連絡先2段組)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">実機印刷で週間の右端(金曜)・日別の左右・連絡先一覧の右側が見切れ。ラッパーをA4実寸(297/210mm)で組んでいたため、プリンタの物理余白(印字不能域)分がはみ出していた。</span><span class=\"lb\">対処</span><span class=\"tx\">①全印刷を印字可能域(週間・連絡先=275×190mm/日別=188×275mm)へ縮小し中央配置。②空席セルを名前入りセルと同じ高さに戻す(後から手書きで追記する運用のため)。行数増はフォント自動計算が吸収。③週間印刷から未割当を削除(店舗指定・画面には表示)+時間/次回列を25/14%→18/11%に詰め氏名列71%化で文字拡大。④連絡先一覧を左右2段組(氏名/住所/電話の3列・住所は折返し・電話は携帯優先で1列)にし全員を1枚に。⑤画面の未割当枠の余白を縮小。※連絡先の優先(固定/携帯)を利用者ごとに選べる設定は要望として記録(未来の修正点)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f0a75a7</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】v3.2: 日別印刷(A4縦・大きな字・氏名/時間/住所(待ち合わせ)/電話の4列・各日ヘッダ「この日を印刷」)+週間印刷2枚目に利用者連絡先一覧(五十音順・選択式)+個人情報取扱注意\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-16</span></div>\n      <p class=\"title\">【試験版】v3.2: 1日分印刷(住所・電話つき大判)と連絡先一覧(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①各日付ヘッダに「この日を印刷」ボタン=A4縦1枚に午前/午後の乗車表を大きな字(行数→9〜15px自動計算)で印刷。列=氏名/時間/住所(待ち合わせ場所併記)/電話(固定優先)。徒歩/その他/未割当/休み/備考も記載。毎日1日分を刷る店舗向けで、週間だと文字が小さくなる問題(Excel比)への回答。②週間印刷はconfirmで「2枚目に利用者連絡先一覧(その週の乗車者・五十音順・氏名/住所/固定/携帯/待ち合わせ場所・行数でフォント自動調整)」を付けるか選択可。③両者に個人情報取扱注意の脚注。データ・保存系は無変更(表示/印刷のみ)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9586c46</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"再pushループの本修正(第3段) — 真犯人=pick/drop等オブジェクトのキー並び順違いによる偽差分(実ログ2026-09-15_PM df=pick,drop,staff,driver,_fieldTs)。pull-preserveの差分判定をキーソート安定比較へ+同一キー保持5回連続で再push10分停止の保険\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"tag crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-15</span></div>\n      <p class=\"title\">「同期に失敗しました」の元凶=同期の空回りループを本修正(証拠ログで真犯人特定)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">第1段の診断が17:14に決定的証拠を記録: 扇橋iPadで当日PM日誌(2026-09-15_PM)の差分フィールド=pick,drop,staff,driver,_fieldTs。これらは全てオブジェクト型で、pull-preserveのdiffers判定(JSON.stringify比較)が**キーの並び順の違いだけで差分と誤認**→保持→再push→サーバー再構成で並びが変わる→受信でまた差分…の無限往復。この渋滞(1〜2秒間隔のpush/pull・27秒で版数+11)中に大きな保存が20秒×3回超過すると「同期に失敗しました」が表示されていた。</span><span class=\"lb\">対処</span><span class=\"tx\">①differs判定とdf診断をキーソートの安定シリアライズ(_stb/_stb2)による比較へ変更(設定系18134とdiaryLogs系の両方・値が同じなら並び順が違っても差分なし)。②保険として同一キーの保持が5回連続したら再pushを10分停止(preserve-loop-stop/preserve-mutedログ・ローカルの保持=画面保護と通常pushはそのまま)。安定版0915c/試験版trial14へ配信。翌朝ログでループ消滅とpersist-fail解消を確認予定。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">515bf55</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"同期\" data-text=\"端末控えQuotaの真犯人=スナップショット(tsumugiRecSnap_v1)の無掃除肥大(Surface5.1MB/iPad2.5MB)を特定・修正 — 直近7日+1.5MB上限の自動掃除+Quota時のスナップ縮小で本命控えを優先確保(第1段診断が即日で犯人を特定)\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-15</span></div>\n      <p class=\"title\">端末控えが保存できない真犯人=「元に戻す」スナップショットの肥大を特定・修正(同期調査第2段)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">第1段の診断(persist-quota)が即日で特定: localStorage占拠の犯人はtsumugiRecSnap_v1(「元に戻す」用スナップショット)で、Surface 5,111KB/iPad 2,528KB。日付ごとのキー(店舗|日付)を作るのに古い日付の掃除が無く、25件/日×数ヶ月分が蓄積。このため本命の控え(daycareAppData_v3)が0KB=軽量版すら保存不能になっていた(9/10の35日トリム対策は控え側のみでスナップは対象外だった)。</span><span class=\"lb\">対処</span><span class=\"tx\">①スナップ保存時に直近7日より古い日付キーを自動削除+全体を約1.5MBに制限(超過時は古いキー→当日の古い件数の順に間引き)。それでも入らなければ当日最新5件のみで再試行。②Quota発生時(persist-fail)はスナップを直近2日×3件へ縮小(recsnap-shrinkログ)してから本命の控えを保存=本命優先。※再pushループ(別件)は0915a更新後の午後は再発なし・発生時に犯人フィールド(ks/df)が自動記録される仕込み済みで、証拠が取れ次第第3段(遮断・正規化)を実施。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3a1567f</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"同期\" data-text=\"扇橋「同期に失敗しました」の遠隔調査(真因=Wi-Fiでなく再pushループ+payload過大+Quota再発)と診断強化第1段(保持キー/差分フィールド/localStorageサイズの記録)\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-15</span></div>\n      <p class=\"title\">扇橋「同期に失敗しました」の再調査 — 真因特定と診断強化第1段(店舗報告)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">遠隔診断でWi-Fi断を否定(表示直後もpush-ok連発・online:true)。真因=①pull-preserve(diaryLogs kept:2)→自己修復re-push→版数上昇→再pull→また保持…の非収束ループ(Surfaceで27秒にv+11・1〜2秒間隔のpush/pull)。②この渋滞+提供記録1263件入りapp_state全体pushの重さで、稀に20秒×3連続超過→push-give-upの表示。③Surface/iPadはQuotaExceededが再発しpersist-slimすら失敗(端末控えが機能せず、トースト文言と実態が不一致)。</span><span class=\"lb\">対処</span><span class=\"tx\">第1段(本rev・読み取りのみ低リスク): pull-preserve(diaryLogs)ログに保持キー名(m:=クラウド欠落/無印=差分)と最初の差分キーのフィールド名一覧(df)を追加。persist-fail時にlocalStorageキー別サイズ上位5件+合計KBを記録(10分に1回・キー名とサイズのみ)。翌日ログでループの真犯人フィールドと容量犯を特定→第2段(ループ遮断・偽差分正規化)は複数端末シナリオ精査の上で実施予定。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a049a22</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌: 利用者行の迎え/送り欄の車名2段重複も解消(getSelectedCarの車種返却を車名と同一なら空に) — 前修正(4ad539a)は車両行のみで利用者行が残っていた\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-14</span></div>\n      <p class=\"title\">日誌の車名2段重複の残り(利用者行の迎え/送り欄)を解消(西馬込再報告)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">前修正(4ad539a)は車両行のセルと車プルダウンのみで、利用者ごとの迎え/送り欄(CarCell)はgetSelectedCarが常に{label:車名, name:車種}を返し2段表示のままだった。同一画面に車名表示が3箇所あることの確認漏れ。</span><span class=\"lb\">対処</span><span class=\"tx\">getSelectedCarで車種が車名と同一または空なら2段目を返さないよう修正(異なる場合は従来どおり2段)。これで日誌内の車名表示3箇所すべてが統一。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">95efca5</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"初回ご利用報告: 運動の○を初回日時点の運動基準値(実施量)に置き換えて表示 — ケアマネがどれくらい実施したか分かるように(数値・自由文入力はそのまま)\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-09-14</span></div>\n      <p class=\"title\">初回ご利用報告の運動欄: ○表示を実施量(基準値)表示へ(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">対処</span><span class=\"tx\">初回報告の運動テキスト生成(_exText)で、記録値が記号のみ(○/◯/〇)の場合はgetPlannedExercisesForDate(初回通所日時点)の基準値(例: 15分・50回)へ置き換え。数値・自由文はそのまま。基準値未設定なら従来どおり○。保存済みの報告は不変(新規作成時の初期文面のみ・保存前に編集可)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">95efca5</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌: 送迎車名の2段重複表示(シエンタ/シエンタ)を修正 — 旧車種欄が車名と同一/空なら1段のみ表示(帳票セル+車プルダウン)\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-14</span></div>\n      <p class=\"title\">日誌の送迎車名が2段に重なって表示される(西馬込報告・安定版)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">各種設定の送迎車は車名+車種の2欄で、日誌帳票の迎え/送りセルと車プルダウンは常に「車名+車種」の2段/併記で表示していた。車名を車種と同じ名前(シエンタ等)に変更した店舗では同じ名前が2行重なって表示された。</span><span class=\"lb\">対処</span><span class=\"tx\">車種が車名と同一または空の場合は1段のみ表示(異なる場合は従来どおり2段)。帳票セルとプルダウンの両方に適用。安定版0914b+試験版trial10へ配信。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4ad539a</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"フェイスシート: 郵便番号→住所検索ボタン(zipcloud)・部屋番号欄の新設(patient.addressRoom)・郵便番号/電話/FAXの全角→半角+自動ハイフン整形\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-09-14</span></div>\n      <p class=\"title\">フェイスシート: 郵便番号検索・部屋番号欄・電話番号等の自動整形(店舗要望・安定版)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①郵便番号欄の横に「検索」ボタン(既存lookupZipAddress=zipcloud)を追加し、町名までの住所を自動入力。②「部屋番号」欄を建物名の隣に新設(patient.addressRoomとして保存。初期値/保存patch/CM側ミラー(_mir)/FS_FIELD_LABELS/利用者マスタの住所表示/フェイスシートPDFプレビューの全経路に追加)。③郵便番号=formatJpZip(全角→半角対応を追加)・電話(固定/携帯)/FAX=formatJpPhone(既存・全角対応済み)を入力時に適用し、全角入力でも自動で半角+ハイフン整形。lookupZipAddressも全角郵便番号を受付。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">31625aa</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】v3.1: 未割当を従来どおり下部へ/印刷文字拡大(上限14px)/空席セルの高さを午前午後で統一/下部情報を1行圧縮+文字拡大\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-14</span></div>\n      <p class=\"title\">【試験版】v3.1: v3.0への店舗フィードバック4点(未割当位置・印刷文字・空席セル統一)</p>\n      <div class=\"cf\"><span class=\"lb\">対処</span><span class=\"tx\">①未割当ボックスをv3.0の最上部配置から従来どおり下部(車の下)へ戻す(件数+「車へ移動してください」の案内は維持)。②印刷のフォント自動計算の上限を12→14px・下限8pxへ引き上げ。③空席行の「週間最大乗車数までは通常高・それ以降は低背」の2段構えを廃止し、全曜日・午前午後で同一高さ(fz×0.95)に統一(午前だけ細い/午後だけ太いのバラつき解消)。④下部情報(徒歩/その他/初回/未割当/休み)を1行に連結してスペース圧縮しつつ、文字はfz-2→fz-1へ拡大。破線区切りを廃止し余白も削減。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">789914b</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】v3.0: デザイン刷新(他AIの試作を仕様書ベースで採用) — 車名・運転者を列見出しの上へ/人数・定員表示廃止/文字拡大/未割当を上部へ/日付ジャンプ/凡例・休みの開閉/ボタン名変更/印刷=車ごと列見出し・薄罫線・空席行低背化\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-14</span></div>\n      <p class=\"title\">【試験版】v3.0: 見た目の刷新 — 仕様書を渡した他AIのデザイン試作を本番へ移植</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">仕様書(v2.5)を基に他AIが作成したデザイン試作(実装依頼書+PDF見本)から、表示差分のみを本番コンポーネントへ適用。確定2点=①各車で「車名(太字)+運転者」を先頭にし直下に列見出し(画面=氏名/時間・印刷=氏名/時間/次回) ②人数/定員・空席数の常時表示を廃止(定員設定・自動配車の定員厳守・超過時の赤警告チップは維持)。参考仕様の採用=氏名16px/時刻17px(桁揃え)/行44px/赤丸のタッチ範囲8×8/未割当を時間帯最上部へ(「車へ移動してください」)/ツールバーに日付ジャンプ(タップで該当列へ横スクロール)/凡例「＋」開閉(●=要TELは常時)/休み◯名の開閉(details)/「＋備考を追加」/列min幅250→280px/操作名称=配車＋時間計算・時間のみ計算・週間の配車＋時間計算(処理は不変)。印刷=薄罫線の帳票調(車の枠のみ濃)・車ごと列見出し(61/25/14%)・空席行は週間最大乗車数より下を低背化(曜日間の位置揃え維持)・午前/午後ラベルに琥珀/藍の地色・店舗名+週範囲ヘッダ・凡例に空欄=空席。保存・同期・振替・ルート計算・データ構造は無変更。試作の架空データ/デモ処理は移植せず。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e94a98d</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】v2.5: 同一建物判定の本修正 — 部屋番号/建物名/丁目・番・号/全角の表記ゆれを正規化した建物キー+座標30m以内のOR判定。千石1-7-10の4名(315/504/514/615号室・全角混在)の実データで検証\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-13</span></div>\n      <p class=\"title\">【試験版】同じマンションの方が同じ車にならない問題の本修正(実データで真因特定)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">v2.4のグループ化は住所文字列の完全一致(NFKC+空白除去のみ)だった。Supabaseの実データを確認すると、千石1-7-10の4名は全員「1-7-10-315 / １－７－１０－５１４(全角) / 1-7-10-504 / 1－7－10－６１５(混在)」と部屋番号付き・表記バラバラで、1件も一致していなかった。時間統一(v2.3)も同じ比較だったため効かず。</span><span class=\"lb\">対処</span><span class=\"tx\">建物キーを新設: NFKC→空白除去→全角/長音ダッシュ→ハイフン→丁目/番地/号室/番/号→ハイフン→数字ブロック3つ(丁目-番-号)までで打ち切り=部屋番号・建物名を除去。加えてGoogleの座標が約30m以内なら同一地点とみなすOR判定(番地の書式が想定外でも座標で救済)。車のグループ化と時間統一の両方に適用。実住所10パターン(丁目表記・建物名付き含む)でキー一致をnodeで検証済み。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">399ffe3</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】v2.4: 同一住所の方(千石1-7-10の4名の事例)を必ず同じ車に(住所グループを塊としてクラスタリング・定員超過時のみ分割)+お休みの方を各コマ下部に表示\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-13</span></div>\n      <p class=\"title\">【試験版】v2.4: 同じ住所の方は必ず同じ車に・お休みの方の下部表示(店舗指摘)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">貪欲クラスタリングが1人単位+車ごとの均等割り人数(sizes)で区切るため、同じ住所の4名(千石1-7-10)が枠の境目で別々の車に割れていた。v2.3の時間統一は「同じ車の中」でのみ効くため、ルートを押し直しても解消しなかった。</span><span class=\"lb\">対処</span><span class=\"tx\">住所(NFKC正規化・住所未入力は個人扱い)でグループ化し、グループを1つの塊として車に割り当てる方式へ変更。各車の枠=残り人数÷残り台数(定員上限・最後の車は乗れるだけ)とし、種=施設から最も遠い「枠に収まる」グループ→重心(人数重み付き)に近いグループを枠に収まる範囲で追加。収まらず残ったグループは空きの大きい車へ(定員に入り切らない場合のみ分割)。あわせて基本利用日なのに欠席・振替・休止でお休みの方を_absenteesで算出し、画面の各コマ下部(グレー)と印刷の各日下部に「休み: ◯◯」を表示(印刷の自動フィット行数にも算入)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7597e3e</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】v2.3: 印刷の1枚自動フィット(行数→フォント自動計算・車2台/3台どちらも見切れない)+車名ヘッダ簡素化(定員表記廃止)+同一住所判定修正(住所のみ・NFKC正規化)\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-13</span></div>\n      <p class=\"title\">【試験版】v2.3: 印刷の見切れ解消(1枚自動フィット)・車名簡素化・同一住所判定の修正(店舗指摘)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①v2.2の定員分固定行で行数が増え、固定50/50の高さ配分+overflow:hiddenの枠を超えて印刷下部が見切れた。②同一住所の時間統一が_addrOf(住所+待ち合わせ場所)で比較していたため、待ち合わせ場所の入力差や全角/半角・スペースの表記ゆれで一致せず効かないケースがあった(加えて統一は再計算時に効く仕様のため保存済みデータには未反映)。</span><span class=\"lb\">対処</span><span class=\"tx\">①行数(車台数×定員行+徒歩/その他/備考等)を週内最大で算出し、フォントサイズ(7〜12px)を自動計算して必ずA4横1枚に収める方式へ。午前/午後の高さも50/50固定をやめ行数比で配分。行が少ない店舗・週は逆に文字が大きくなる。②車名ヘッダの「（定員◯名）」を廃止(定員=枠の行数で表現)し運転者は細字表示でシンプルに。③同一住所判定を住所のみ+NFKC正規化(空白除去・小文字化)へ修正。保存済み週は「時間」or「ルート」再実行で統一反映(案内済み)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8c9e32a</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】v2.2: 画面整理(重複タイトル削除・週切替左詰め・バーをヘッダー直下固定・凡例常時表示・説明を?に格納)+午前/午後の段揃え+同一住所の時間統一+印刷様式改善(列見出し・定員固定行・文字拡大)\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-13</span></div>\n      <p class=\"title\">【試験版】v2.2: 画面の整理と印刷様式の改善(店舗要望7点)</p>\n      <div class=\"cf\"><span class=\"lb\">対処</span><span class=\"tx\">①カード内の重複タイトル「送迎表（運行表）」を削除し、週切替(前週/翌週)を左端へ。ツールバーは画面タイトル帯の直下に密着して固定(sticky)。②●=時間変更(要TEL)/緑=振替/水色=初回の凡例を同じバーに常時表示し、長文の操作説明は「?」ボタン(タップ/カーソル合わせ)へ格納。③週間グリッドを日付/午前/午後の3行グリッド(gridAutoFlow:column+display:contents)へ変更し、全曜日で午後の開始位置が同じ高さに揃うように。④ルート計算の時刻逆算後、同一住所(_addrOf一致)の利用者は早い方の時間に統一(同じ建物・ご夫婦など)。⑤印刷: 各日の先頭に氏名/時間/次回の列見出しを追加し、車の枠は定員分の行を常に確保(上限8行・車名横に定員表示)して日をまたいでも車の位置が揃うように。名前/時間の文字を9→11pxへ拡大し右側の余白を削減。凡例の「（）内=次回利用曜日」を「次回=次の利用曜日」へ更新。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e067802</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"送迎表\" data-text=\"【試験版】送迎表クラッシュ(ReferenceError: routing): v2.0のスライス置換で6宣言が巻き込み消失。復元+送迎表E2E常設化で再発防止\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"tag crit\">重大</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-13</span></div>\n      <p class=\"title\">【試験版】送迎表を開くと全画面エラー — v2.0改修の巻き込み消失(店舗報告・即日修正)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">v2.0のドラッグ振替改修で範囲スライス置換を行った際、置換範囲に含まれていた6つの宣言(routing/tpSettings/_facilityAddr/_targetArrive/_fmtHM/savePatientPickup)が新コードに含まれず消失。構文チェック(esbuild)は通過するが実行時にReferenceError: routingで送迎表がクラッシュ。既存E2Eは送迎表画面を開いておらず検知できなかった。</span><span class=\"lb\">対処</span><span class=\"tx\">6宣言を最新仕様のまま復元。送迎表を開く専用E2E(transport.spec.js)をローカルPlaywright実行で再現→修正確認し、リポジトリに常設(以後全デプロイで検査・chromium/ipad両プロファイルで24件に)。教訓=スライス置換は範囲内の全宣言を新コードへ引き継ぐこと・新画面はE2Eに遷移テストを即追加。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">06959ae</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】v2.1: ドラッグ振替に理由入力モーダル(ABS_REASON_CATSチップ+詳細)。元の日の欠席理由を自動引き継ぎプレフィル=入力済みならスキップ可\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-13</span></div>\n      <p class=\"title\">【試験版】ドラッグ振替の理由入力(既存理由は引き継ぎでスキップ可・店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">対処</span><span class=\"tx\">別日/別帯へのドロップ時、window.confirmを理由入力モーダルへ置換。大分類チップ(ABS_REASON_CATS)+詳細入力+記録プレビュー。元の日の欠席理由(振替リンク以外)が入力済みならparseAbsReasonで分解して自動プレフィル=そのまま登録で再入力不要。理由は欠席側特記へ「◯月◯日◯◯へ振替（理由）」形式で記録(月間スケジュール/提供記録の既存表示と互換)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">de7359a</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】v2.0: 午前+午後の1枚化・別日/別帯ドラッグ=振替登録(3点反映)・行UI簡素化・徒歩既定の自動振り分け・運転者欄拡大・未設定1分\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-12</span></div>\n      <p class=\"title\">【試験版】送迎表v2.0 — 1枚化とドラッグ振替(店舗要望8件)</p>\n      <div class=\"cf\"><span class=\"lb\">対処</span><span class=\"tx\">①日カードを印刷と同じ午前+午後の縦並びへ(タブ廃止・ルート/時間ボタンは帯ヘッダ)。②長押しドラッグで別日/別時間帯へ落とすと確認のうえ振替登録(monthlyShifts=欠席/振替・ticketRecords=欠席tokki振替リンク+振替rec・transportPlans=元から除去し先のドロップ位置へ、を1回のonSaveで)。③行から▲▼/車プルダウン/次回曜日を撤去(印刷の次回列は存置)。walk/other/un行も長押し可・ドラッグ中は空でも受け皿表示。④マスタ「徒歩」の方はwalkフラグで最初から徒歩枠(自動配車対象外)。⑤運転者select拡大。⑥乗車時間の未設定=1分に変更。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">74946d8</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】v1.10: 乗車時間を1-15分プルダウン化。複数曜日利用者のドラッグで他曜日の行も持ち上がって見える問題(pidのみ比較)をiso併用で修正\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-12</span></div>\n      <p class=\"title\">【試験版】乗車時間プルダウン化+ドラッグ表示の曜日混線修正(店舗指摘)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">ドラッグ中の半透明表示・挿入線・車枠強調が利用者IDのみで判定されており、月曜と木曜など複数日に利用がある方は他の曜日の行にも見た目が連動していた(実際の移動は押した日のみ)。</span><span class=\"lb\">対処</span><span class=\"tx\">全ての表示判定に日付(iso)を併用し押した日だけに限定。乗車にかかる時間は1〜15分のプルダウン(未設定=2分)へ変更(利用者マスタ・名前タップの両方)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">62bf43a</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】v1.9: ドロップ位置の青線+隙間モーション・近所まとめクラスタリング(方角輪切り廃止)・出発時間帯の交通状況で計算(departure_time)・出発警告文の明確化・計算中表示の日別化\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-12</span></div>\n      <p class=\"title\">【試験版】送迎表v1.9 — ドラッグの見える化・組み分け精度・交通予測(店舗指摘5件)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">①ドロップ位置が見えない ②澤栗/飯塚のような近所が別の車になる(方角輪切りの境目問題) ③ルートが押した時刻(深夜)の交通で計算される ④「8:30に間に合いません」の意味が読み取れない(実はお迎え時刻でなく出発時刻の話) ⑤1日のルートを押すと全日のボタンが計算中になる。</span><span class=\"lb\">対処</span><span class=\"tx\">①ドラッグ中に入る位置へ青線+行間が開くモーション、対象の車枠を強調。②組み分けを貪欲近傍法(最遠を種に重心から近い順に集める・均等・定員厳守)へ。③Directionsにdeparture_time(対象日の出発時刻・過去なら次の同曜日)+traffic_model=best_guess、duration_in_traffic採用。④警告文を「◯◯様のお迎え(8:35)に向かうには8:25に出る必要(設定より5分早め)」へ。⑤routingキー化で押した日だけ計算中表示。※duration_in_traffic利用はDirections Advanced SKU(無料枠別・使用量は微小)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0b3f41c</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】v1.7-1.8: 方角クラスタ均等配車・時間のみ再計算・長押しドラッグ移動(車またぎ)・出発時刻設定・時刻プルダウン・到着既定=単位開始時間・片道方式(最遠直行→帰りながら拾う)\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-12</span></div>\n      <p class=\"title\">【試験版】送迎表v1.7-1.8 — 方角均等配車・長押しドラッグ・片道ルート方式(店舗要望7件)</p>\n      <div class=\"cf\"><span class=\"lb\">対処</span><span class=\"tx\">①「ルート」=施設から見た方角で全乗車者をソート→最大の空き角で切って台数で均等分割(定員厳守)→同じ方向は同じ車に。②新設「時間」=手で組んだ車・順番のまま時刻のみ再計算。③名前を0.35秒長押し→ドラッグで車/徒歩/その他/未割当へ移動(行上ドロップで割り込み・車またぎ可・スクロール優先キャンセル)。④設定に出発時刻AM/PM(不足時「◯:◯◯出発が必要」報告)・時刻は時分プルダウン・到着既定=事業所情報の1/2単位目開始時間。⑤ルートを輪から片道方式へ: 最遠者(座標の直線距離)へ直行→origin=最遠宅/destination=施設で残りを最適化。「近い人が先頭に来る」「途中で拾う」を根絶。APIはdestination/keepOrder/停留23/座標返却対応。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">785d0bb</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】v1.6: 利用者名の…見切れ→折返し全文表示。1名乗車の車がルート計算対象外(2名以上条件)で時間が入らない→1名から計算\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-12</span></div>\n      <p class=\"title\">【試験版】名前見切れ+1名の車に時間が入らない問題を修正(店舗指摘)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①行の氏名がtruncateで「…」に省略。②ルート計算が「2名以上乗る車」だけを対象にしており、1名だけの車(3号車など)はスキップされて時間が空欄のままだった。</span><span class=\"lb\">対処</span><span class=\"tx\">①氏名を折返し全文表示(overflow-wrap:anywhere・メンバー行/徒歩/その他/未割当/送り別の全箇所)+日列の最小幅230→250px。②carIdsフィルタを1名以上に変更(単独停留でもDirections計算は正常動作)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1111e81</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】v1.5: 車両名を1枠に統一・セレクトに設定名フル表示・その他(家族送迎等)区分を送迎表+日誌両対応・可読性改善\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-12</span></div>\n      <p class=\"title\">【試験版】送迎表v1.5 — 車両名1枠化・「その他」区分・見やすさ改善(店舗要望4件)</p>\n      <div class=\"cf\"><span class=\"lb\">対処</span><span class=\"tx\">①各種設定の送迎車両を「名前1枠」(自由記載: シエンタ/1号車など)に統一し旧・車種欄を廃止(既存データ互換)。②送迎表・送り別・設定モーダルのセレクトへ設定名をフル表示(「1」等の省略を廃止)。③「その他」区分(家族送迎・遅れて来所など)を追加: 送迎表=紫枠・印刷/初回判定/前週コピー対応・ルート対象外。日誌側もpick_other/drop_otherとして割り当てモーダル選択肢・帳票セル・週間コピー・保留/未完了判定・送迎表取込に対応。連絡帳の未入力チェックはその他=時間不要扱い。④行文字13px・余白/セレクト幅拡大の可読性改善。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">fb4d447</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】印刷が左上寄り+灰色地: ラッパー白背景なし+高さ設計なしが原因。A4横全面(午前/午後50%配分・四辺余白・白背景)へ修正\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-12</span></div>\n      <p class=\"title\">【試験版】運行表の印刷レイアウト修正 — 左上寄り・灰色地(店舗指摘)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">印刷HTMLのラッパーに背景色が無くプレビューの灰色地(#525659)が透過。またA4横に対する高さ・余白の設計が無く、内容量ぶんだけ左上に描画されて大量の空白が出ていた。</span><span class=\"lb\">対処</span><span class=\"tx\">ラッパーを297×209mmの実寸枠(白背景・padding 6/8mm)にし、内側をflex縦組みで表をflex:1に。午前/午後の行に高さ50%ずつを配分(セルは上詰め)し、人数が少ない日も枠が用紙全面に広がる形へ。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">26e0890</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】v1.4: 連絡帳連動・送り別割り当て・初回水色+備考自動・前週コピー・町名グループ配車・赤丸家族通知・遠→近の回り順。週間一括の上書き消失バグも修正\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-12</span></div>\n      <p class=\"title\">【試験版】送迎表v1.4 — 提案6機能を一括実装(全採用のユーザー指示)+週間一括の重大バグ修正</p>\n      <div class=\"cf\"><span class=\"lb\">対処</span><span class=\"tx\">①連絡帳連動(手入力>送迎表>自動計算の優先順・印刷/入力モーダル/未入力判定へgetTransportTimeForを挿入)。②送り(帰り)の別割り当てトグル(迎え複製→自由編集・日誌取込は迎え/送り別・印刷に送り別行)。③初回利用=水色(グレーは休み印象のため変更)+備考へ「初回:○○様」自動記入。④前週まるごとコピー(赤丸は引き継がず)。⑤町名グループ配車(同じ町は同じ車を優先)。⑥赤丸ONで家族アプリへお迎え時間変更のお知らせ配信(確認付き・同一保存)。ルートは最短ループを「遠くから施設へ近づく」回りに統一(店舗要望)。</span><span class=\"lb\">原因</span><span class=\"tx\">【重大修正】週間一括・前週コピーが日ごとに古いプラン一覧を土台に保存し、後の日の保存が前の日の結果を消す構造だった→累積して1回のonSaveへ統一(実害前に検出)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">bf505c5</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】v1.3: ルート実行時に未割当を空き定員の多い車へ自動割り当て(定員厳守・乗り切らない分は報告)。車ごとの運転者欄(印刷にも)。乗車順ナビ起動(無料)\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-12</span></div>\n      <p class=\"title\">【試験版】送迎表v1.3 — 未割当の自動割り当て・運転者欄・ナビ起動(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">対処</span><span class=\"tx\">①_autoRouteCore冒頭で未割当を空き定員の多い車へ自動配車(定員(運転者除く)は超えない・乗り切らない分は未割当に残し人数と氏名を報告)してからルート計算。②車ヘッダに運転者select(日誌の担当職員リストから・plan.driver)を追加し印刷の車名にも「運転: ○○」。③「ナビ」=乗車順どおりのGoogleマップ経路案内URL(maps.google.com/dir)を開く(APIコスト0・運転者のスマホ道案内用)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">08039af</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】Googleマップ連携開通: GOOGLE_MAPS_API_KEY設定(Prod+Preview)・接続確認・実ルート計算テスト成功。ルート自動作成が本稼働\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-12</span></div>\n      <p class=\"title\">【試験版】Googleマップ連携が開通 — ルート自動作成が本稼働(本部作業完了)</p>\n      <div class=\"cf\"><span class=\"lb\">対処</span><span class=\"tx\">本部がDirections API限定のAPIキーを発行しVercelへ登録(Production+Preview・Secret・アプリ制限なし=サーバー経由のため)。試験版を再デプロイし configured:true を確認、実住所での経路計算テスト(扇橋施設→江東区内3停留)で最短順・区間所要時間の応答を確認。試験版へ開通のお知らせ(upd-2026-0912-trial5)を配信。料金=無料トライアル90日/約4.8万円クレジット、恒常はDirections月1万コール無料枠内で運用0円見込み(週間一括=約36リクエスト/週)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">278592e</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】設定モーダルの車名見切れを折返し表示に修正(w-28 truncate→flex-1 break-words)\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-12</span></div>\n      <p class=\"title\">【試験版】設定画面の車名見切れ修正(店舗指摘)</p>\n      <div class=\"cf\"><span class=\"lb\">対処</span><span class=\"tx\">「1号車（シエン…」と切れていた車名表示を、幅固定+truncateから可変幅+折返しへ変更し全文表示に。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a107e6c</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】v1.2: PM振替に午前の8時が出るバグ修正(1日=AMのみ・帯違いは空欄)。到着目標時刻設定+定員編集・週間ルート一括・乗車時間を人別バッファ化\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-12</span></div>\n      <p class=\"title\">【試験版】送迎表v1.2 — 午後振替に午前の時間が出るバグ修正+設定・週間一括(店舗指摘6件)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">初期時間をマスタのお迎え時間(曜日単位)からそのまま取っていたため、午後へ振替した方に基本利用(午前)の8時が表示されていた。「1日」の方が午後のお迎えにも並ぶ問題も同根。</span><span class=\"lb\">対処</span><span class=\"tx\">①初期時間は基本の時間帯が一致する時のみ採用(振替・帯違いは空欄=手入力かルート自動)。1日の方はAMのみに掲載。②送迎表「設定」モーダル=到着目標時刻AM/PM(逆算基準)+車の定員(各種設定と共通)をその場で編集。③「週間ルート一括」=表示週の全営業日×AM/PMを一括計算(コア関数化・スキップと失敗はまとめて報告)。④pickupMinutes=「停車→お迎え→乗せ終わるまで」の人別時間としてラベル整理し、逆算バッファに個別反映(未入力2分)。⑤定員に「運転者を除く」を明記。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6a699ab</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】送迎表v1.1: 振替=緑・車両定員+超過警告・待ち合わせ場所/所要時間(マスタ+名前タップ共通)・Googleマップ最短ルート+時間自動割り振り(api/route-plan)\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-12</span></div>\n      <p class=\"title\">【試験版】送迎表v1.1 — 定員・待ち合わせ場所・Googleマップルート自動作成(店舗要望5件)</p>\n      <div class=\"cf\"><span class=\"lb\">対処</span><span class=\"tx\">①振替ハイライトを日誌と同色の緑へ(画面・印刷)。②各種設定の送迎車両に定員入力を追加し、送迎表で「n名/定員名」表示・超過は赤字警告+移動時confirm。③利用者マスタのお迎え時間下に「待ち合わせ場所」「送迎の所要時間(片道分)」を追加、送迎表の利用者名タップでも同じ項目を編集(共通保存)。④api/route-plan.js=GOOGLE_MAPS_API_KEYのDirections APIプロキシ(waypoints最適化・最大10停留)。⑤日付カード「ルート」ボタン=車ごとに最短順を計算し、到着目標(スケジュール先頭-5分)から区間所要+乗車バッファ2分/人を逆算してお迎え時間を自動割り振り。住所未入力はスキップ案内・キー未設定時は本部作業(GOOGLE_MAPS_API_KEY設定)の案内。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8ea5b76</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"送迎表\" data-text=\"【試験版】送迎表(運行表)基本版v1: 週間×AM/PM×車ごと乗車表。自動下書き・自由編集・赤丸TEL目印・A4横印刷・日誌取込。transportPlans同期3点セット\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">送迎表</span><span class=\"date tnum\">2026-09-12</span></div>\n      <p class=\"title\">【試験版】送迎表(運行表)基本版 v1 — 現行の手書き運行表を踏襲(店舗要望多数・LIFEより先行)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">店舗の手書き運行表(週間×午前/午後×シエンタ/ステップ/タント・氏名/時間/次回曜日/備考・振替は黄色・時間変更は赤丸+TEL運用)のPDFを受領し様式を踏襲。安全のため試験版(trial)のみに実装。</span><span class=\"lb\">対処</span><span class=\"tx\">①自動下書き=月間スケジュール+基本利用日から乗車者抽出・時間は送迎時間マスタ・車割りは前週同曜日をコピー(徒歩も引き継ぎ)。②編集=車の移動/並べ替え/時間手入力/赤丸トグル/備考/徒歩・未割当プール(編集した日だけtransportPlansへ自動保存・保存後に増えた振替者は未割当へ自動補充)。③同期=日誌と同型の日付キー+_savedAtマージをpush/pull両側に実装。④A4横印刷(週間・午前+午後・黄=振替/●=時間変更/次回曜日)。⑤日誌に「送迎表取込」ボタン(迎え/送りへ一括反映)。第2段=連絡帳お迎え時間反映・AI割り当て。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3f48b5b</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"管理局\" data-text=\"2本立てセットアップ完了: 試験版URL確定(tsumugi-git-trial-ones-style.vercel.app)・保護なし確認・Supabase/API稼働確認・run_testsにT-OPS-06追加\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">管理局</span><span class=\"date tnum\">2026-09-12</span></div>\n      <p class=\"title\">2本立てセットアップ完了 — 試験版URL確定・毎回検査に組込</p>\n      <div class=\"cf\"><span class=\"lb\">対処</span><span class=\"tx\">試験版URL=tsumugi-git-trial-ones-style.vercel.app(trialブランチ固定・Vercel認証保護OFF確認済み)。トップ200/update-notes応答/Supabase接続(バンドル内確認)/APIファンクション稼働を検証。run_tests.pyにT-OPS-06(試験版生存確認)を追加し毎デプロイの締めで検査(計16項目)。テスト項目一覧にも登録。運用: 新機能はtrialのみ・安定版修正はsync_trial.shで必ずtrialへ同期。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f52e295</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"管理局\" data-text=\"2本立て(安定版/試験版)セットアップ開始: trialブランチ+sync_trial.sh(stable→trial同期を締めに組込)。VercelプレビューURL確定は本部作業待ち\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">管理局</span><span class=\"date tnum\">2026-09-12</span></div>\n      <p class=\"title\">2本立て(安定版/試験版)セットアップ開始 — 送迎表を試験版で先行開発するため(ユーザー指示)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">送迎表の要望が多く、LIFEより先に着手するとユーザー決定。大型機能はエラーの可能性があるため、安定版(全店)と試験版(試験運用店+扇橋)の2本立てで進める。</span><span class=\"lb\">対処</span><span class=\"tx\">trialブランチを作成・push(開始時点は安定版と同一)。scripts/sync_trial.sh=安定版のバグ修正デプロイの締めでstable→trialへ必ずマージ+試験中機能の差分を表示。残作業=VercelダッシュボードでtrialブランチのプレビューURL確認とDeployment Protection解除(本部作業1回・手順案内済み)。以降の送迎表実装はtrialのみに入る。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d31be1e</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"旧iPadで画面が引っ張られたままずれる固着の最終対策: メインラッパ(インラインoverflow)へ直指定+タッチ端末の全スクロール枠でラバーバンド無効化\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-11</span></div>\n      <p class=\"title\">旧iPadの画面ずれ固着 — メインラッパの引っ張り対策漏れが真因(スクショで特定)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">スクショ検証で、メイン領域全体が下方向へ引っ張られたまま固着していると判明。メインのスクロールラッパはインラインstyleのoverflow:autoのため、前回のTailwindクラス向け一括CSSが当たっておらず、旧iPad Safariのラバーバンド固着バグがそのまま残っていた(サイドバー等でも同様)。</span><span class=\"lb\">対処</span><span class=\"tx\">メインラッパへ提供記録の表と同じ WebkitOverflowScrolling:'auto'(旧OSのみ慣性無効・新OSでは無視)+overscrollBehavior:'none' を直指定。加えてタッチ端末では全スクロール枠(.overflow-auto等)のラバーバンドを無効化するCSSを追加。新しいiPadの操作感には影響なし。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8a5bca3</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"シェル常時fixed化(全画面と同じ固定を全画面ボタン無しで)。日誌/体力測定の全画面トグルは指示で撤去。連絡帳バイタル行高px固定(iOS印刷空白対策)\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-11</span></div>\n      <p class=\"title\">アプリ全体を常時固定表示に — 全画面ボタン無しで旧iPadの表ずれを解消(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">全画面表示なら旧iPadでも表が固定されると店舗確認。ただし画面ごとの全画面ボタンは不要とのことで、0911eで追加した日誌/体力測定のトグルは廃止指示。</span><span class=\"lb\">対処</span><span class=\"tx\">ルートシェル(h-screen/100dvh)へposition:fixed inset-0を常時適用。中身は元々すべて内部スクロールのためレイアウト影響なしで、全画面と同じ文書バウンス抑止がどの画面・サイドバー表示中でも効く。日誌/体力測定のトグルは撤去(提供記録の全画面ボタンは存置)。あわせて連絡帳バイタル2行の高さを3.6rem→58px固定(iOS印刷で開始時と終了時の間に空白が出る事象のrem解釈差対策・実機確認待ち)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5b6713e</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌・体力測定に全画面表示トグル(旧iPad表ずれ対策)。印刷プレビューヘッダを折返し対応(iPhoneで閉じる見切れ)\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-11</span></div>\n      <p class=\"title\">日誌・体力測定の全画面ボタン追加+印刷プレビューヘッダのiPhone見切れ修正(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">無印iPad第8世代はCSS対策(user-select等)でも表ずれが残るが、提供記録の全画面表示(fixedで覆う方式)なら固定されると店舗が確認。またiPhoneの印刷プレビューは右上の「閉じる」がヘッダのボタン群に押し出され画面外に見切れていた。</span><span class=\"lb\">対処</span><span class=\"tx\">①日誌・体力測定に提供記録と同じ「全画面」トグルを追加(fixed inset-0 z9999+100dvh・各モーダル/テンキーはz10万級で影響なし)。他画面への展開は要望に応じて順次。②印刷プレビューヘッダをflex-wrap化(タイトルはellipsis・ボタン群は右寄せで2段折返し)し、どの画面幅でも閉じるが必ず見える。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">95af255</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"無印iPad第8世代で表が長押しでずれる: 長押しの文字選択(ルーペ)が原因。タッチ端末のみ表内user-select無効化+touch-action指定\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-11</span></div>\n      <p class=\"title\">古めのiPadで表が長押しでずれる — タッチ端末の表内文字選択を無効化(店舗報告)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">iPad Pro 11では固定されるが無印iPad第8世代では長押し+ドラッグで表全体がずれる。旧世代Safariでは長押しで文字選択(ルーペ)が始まり、そのままの指の移動が選択ドラッグとして扱われ表が動いて見える。overscroll-behavior非対応の旧OSでは前回の対策も効かない。</span><span class=\"lb\">対処</span><span class=\"tx\">@media (hover:none) and (pointer:coarse)でタッチ端末に限り表内のuser-selectを無効化し、touch-action: pan-x pan-y pinch-zoomを指定(指の動きはスクロール/ピンチのみ)。PC・マウス環境は従来どおり選択・コピー可。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1fd1c9c</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"拡大ビューの血圧を上下別色分け(getBpUp/DnColorClass)。全画面の表に長押しドラッグずれ防止CSS(user-drag none+overscroll contain)\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-11</span></div>\n      <p class=\"title\">拡大ビュー血圧の上下別色分け+全画面の表ずれ防止(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">対処</span><span class=\"tx\">①拡大ビューの血圧セルを通常一覧と同じ「上=getBpUpColorClass/下=getBpDnColorClass」の分割表示に(スラッシュはグレー)。②提供記録の.record-view-scrollで実績のある長押しドラッグ対策(user-drag/touch-callout無効)を全画面のtableへ、内側スクロールの連鎖防止(overscroll-behavior:contain)を汎用overflowクラスへ、index.cssで一括適用。文字選択は温存。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0b16a58</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"全画面表示で拡大ビューが開かない(z9999の裏に隠れる)→z10000。バイタルを厚労省基準色に。運動○×ーは黒特太\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-11</span></div>\n      <p class=\"title\">拡大ビュー: 全画面表示で開かない+色分け未適用(店舗報告)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①全画面表示はCSSのfixed+z-index 9999のコンテナで実装されており、body直下にポータルされる拡大ビュー(z9980)がその裏に隠れてボタンが「反応しない」ように見えていた。②拡大ビューのバイタル・運動は一律の青字で、通常一覧の厚労省基準色分けが未適用だった。</span><span class=\"lb\">対処</span><span class=\"tx\">①拡大ビューをz10000へ(テンキーz99999・気分等のモーダルはDOM順で上)。②体温=getTempColorClass/血圧=getBpColorClass/脈拍=getPulseColorClassを適用(正常=黒・III度/高熱=赤特太・I度/微熱=橙・低血圧/徐脈/低体温=青)。③運動メニューの値は黒、○×ー記号はfontWeight900+32pxの黒特太に。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e4ddf54</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"スケジュール/提供記録\" data-text=\"状態変更時の理由整理: 出席戻しで理由クリア・休止は理由上書き・欠席→振替で理由自動引き継ぎ。提供記録+月間グリッド両系統\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">スケジュール/提供記録</span><span class=\"date tnum\">2026-09-11</span></div>\n      <p class=\"title\">状態変更時の欠席理由の扱いを整理 — 出席戻しクリア/休止上書き/振替への引き継ぎ(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">①欠席→急遽出席に戻すと特記に休み理由が残る(休業も同様)。②休止にしても古い欠席理由が特記に残る。③欠席(理由入力済み)→急遽振替にすると理由を打ち直す必要があった。</span><span class=\"lb\">対処</span><span class=\"tx\">①欠席/休業/休止→出席で特記の理由を自動クリア(「へ振替」リンクは取り消しフロー用に温存)。②休止適用時は特記を休止理由で上書き(出席戻しクリアの導入で残留しない設計に変更)。③振替モーダルを開く時、元の欠席理由をparseAbsReasonで大分類+詳細に分解して自動プレフィル。RecordViewと月間グリッド(出席戻し/振替/休止セル)の両系統・計6箇所。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6fe17c5</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"厳格チェック(車ごと時間・送迎者・車未選択)が過去の完成済み日誌へ遡及し完成印が消える。境界日2026-09-10を導入し過去日は旧基準\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-10</span></div>\n      <p class=\"title\">厳格チェックの遡及で過去の完成済み日誌が未完成扱いに — 境界日を導入(店舗報告起点)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">同日導入の厳格チェック(迎え/送りで使う車ごとの到着・出発時間、送迎者チェック、利用者ごとの車未選択)に導入日の境界がなく、過去の完成済み日誌にも適用されてカレンダーの完成印(●)が消え「入力したのに未完成」と見える。実データ検証(扇橋9/8-9/9)では判定自体は割り当てどおりで正しく、遡及だけが問題。</span><span class=\"lb\">対処</span><span class=\"tx\">DIARY_STRICT_CUTOFF='2026-09-10'を導入し、厳格チェックは境界日以降の日誌のみ。過去日はバッジ・diaryPendingItems(ホーム/カレンダー)とも旧基準で判定(_sougeiPendingの8/28境界と同じ設計)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2caaea9</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"iPadのツールバー/ブックマークバーで設定モーダル下端の保存ボタンが隠れる。dvh対応(tsu-cap-dvh/tsu-h-dvh)で29か所一括修正\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-09-10</span></div>\n      <p class=\"title\">設定モーダルの保存ボタンが画面外に隠れる — iPadツールバー分のvhズレを一括修正(店舗報告)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">iPad Safari等はvh(ビューポート高)がツールバー/ブックマークバーの裏側まで含むため、高さ85〜95vh指定のモーダルは実表示域をはみ出し、下端固定の保存ボタンが隠れて押せない。連絡帳フォーマット設定(h-95vh)で報告、同構造は全体で29か所。</span><span class=\"lb\">対処</span><span class=\"tx\">index.cssに@supports(100dvh)ユーティリティを追加し、dvh対応ブラウザでは実表示域基準の上限を!importantで上書き(インラインstyleのvhに勝たせる)。連絡帳フォーマット設定にtsu-h-dvh、maxHeight 85〜95vhの28モーダルにtsu-cap-dvhを一括付与。非対応の古いブラウザは従来のvhのまま(悪化なし)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c338626</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"日誌\" data-text=\"到着/出発時間の必須を方向別に。迎えで使う車=到着必須・送りで使う車=出発必須・使わない方向は必須解除。ホーム/カレンダーも同基準\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-10</span></div>\n      <p class=\"title\">到着・出発時間の必須判定を「車の使い方」に連動(店舗フィードバック)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">送り(または迎え)で車を使っていないのに時間の必須表示が消えないとの指摘。従来は「どこかの車に何かの時間があればOK」の一括判定だった。</span><span class=\"lb\">対処</span><span class=\"tx\">「送迎時間」チップを「到着時間」「出発時間」に分割。到着=迎えで使う車すべてに必須、出発=送りで使う車すべてに必須。使わない方向は未入力でも必須解除。diaryPendingItems(ホーム・カレンダー完成印)も同基準。車を1台も登録していない店は時間チェック自体を行わない。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">11b496d</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"同期\" data-text=\"端末控えの提供記録を直近35日に常時トリム(店舗承認)。正本はテーブル・起動時全量取得。QuotaExceeded恒久対策\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-10</span></div>\n      <p class=\"title\">端末控えの提供記録を直近1か月(35日)に常時トリム — 容量8割超の恒久対策(店舗承認)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">扇橋実測: 全データ2.1M文字≈localStorage上限5MBの8割超(UTF-16換算4.2MB)で、うち65%が提供記録(3か月分1.4MB・1日約36KB)。1年で4〜5MB相当に育ち破綻確実。「控えは過去1か月分・それ以前は読込中表示でよい」とユーザー承認。</span><span class=\"lb\">対処</span><span class=\"tx\">_slimTicketsを45→35日にし、テーブル方式では通常保存・写真分離パスでも常時適用(従来は容量超過時のみ)。過去分は起動時のticket_records全量取得(完了まで既存の読込中オーバーレイ)が担う。安全性: app_stateマージは和集合+明示墓石のみ削除のため、35日控えの押し戻しで古い記録は消えない。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0b23bff</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"日誌\" data-text=\"未完了バッジ刷新: 迎え/送り未選択人数に一本化・送迎者チェック追加・括弧ヒント廃止・日誌が未完成です表記。送迎欄は方向別グレー。写真残骸キー削除\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-10</span></div>\n      <p class=\"title\">未完了バッジ刷新+送迎者チェック+方向別グレーアウト(店舗フィードバック)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">前日追加の「迎えの車/送りの車」は既存の「迎え/送り」と情報重複との指摘。本当に欲しいのは運転する送迎者チェックの漏れ検知。またグレーアウトは迎え3台/送り2台のような日で方向別にしてほしい、（未入力）等の括弧書き不要、「要確認」より「完成しない」ニュアンスの文言に、との要望。</span><span class=\"lb\">対処</span><span class=\"tx\">①チップを「迎え 未選択◯名」に一本化(重複項目・括弧ヒント廃止)。②使う車に運転者チェックが無いと「迎えの送迎者」「送りの送迎者」を表示(diaryPendingItemsにも追加しカレンダー完成印・ホームと同基準)。③見出しを「日誌が未完成です」+末尾「すべて入力・確認すると完成します」。④下部送迎表は迎え未使用=到着+迎え送迎者のみ/送り未使用=出発+送り送迎者のみ/両方未使用=車両名もグレー(時間入力済み側はロックしない)。⑤控え保存フォールバック時に旧写真キーdaycarePhotos_v1を削除(数MBの残骸が軽量版まで失敗させる要因)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4929eb4</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"日誌\" data-text=\"日誌が他端末で未入力: QuotaExceededで端末控え全滅+push同時多発のCAS競合詰まりで1件も完了せず。push単一キュー+20秒タイムアウト+控え第3段\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"tag crit\">重大</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-09</span></div>\n      <p class=\"title\">日誌が他端末で未入力になる — 容量超過×push渋滞の複合原因(扇橋・遠隔診断で実測特定)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">遠隔診断(diag_store_ogibashi)で実測: ①persist-fail(QuotaExceededError)24回に対しpersist-slim 0回=軽量版保存2段とも失敗し外側catchが握り潰して端末に何も残らない。②16:31〜33にiPadで23回のsave(canPush:true)に対しpush-ok/fail/errorが0件=自動保存のたびに巨大JSONのCAS pushが同時多発し、遅いWi-Fiで互いに競合して1件も完了しないままセッション終了。両方が重なりクラウドにも端末にも残らなかった。自動保存機構自体は正常動作。</span><span class=\"lb\">対処</span><span class=\"tx\">①端末控えに第3段フォールバック(faxDataStore等の重量データを除去・日誌/設定/利用者は保持)を追加し必ず残す(persist-slim2ログ)。②pushを単一実行キュー化(実行中は最新だけ控えて直列)+20秒タイムアウトで必ず決着→失敗は「同期に失敗」通知に必ず到達。根本の容量ダイエット(FAXデータのapp_state分離)は残課題として記録。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9a25de4</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"日誌\" data-text=\"要確認に迎え/送りの車未選択(人数付き)を追加。迎え送りとも未割当の車は送迎欄グレー+入力不可\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-09</span></div>\n      <p class=\"title\">要確認に「迎え/送りの車未選択◯名」追加+未割当車の送迎欄グレーアウト(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">先週欠席だった方は前週コピーで車が入らず、スタッフが素通りして未選択のままになる。また誰も乗らない車の到着/出発欄が押せてしまい誤タップの元だった。</span><span class=\"lb\">対処</span><span class=\"tx\">要確認バッジに「迎えの車(未選択◯名)」「送りの車(未選択◯名)」を追加(判定は割り当てモーダルと同一・徒歩は選択済み扱い・欠席/休止/休業は対象外・クリックで割り当てモーダル)。下部送迎表は迎え/送りとも割り当てゼロ+時間未入力の車をグレー表示+入力不可に(割り当てると解除)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9a25de4</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"未入力判定を時+分両方必須に。空き面の未定→手書き用空欄。様を5文字分右へ。長い運動メニュー名は自動縮小で全文字表示\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-09-09</span></div>\n      <p class=\"title\">未入力判定の厳格化+2面印刷の空き面レイアウト3件(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">対処</span><span class=\"tx\">①お迎え時間の入力済み判定を「時と分の両方に数字」に厳格化(_fullTime)。「8時 分」の片入力や分なしの自動計算時間は未入力バッジ・プレビュー前確認の対象に。②B5 2面印刷で奇数人数時の手書き用の面は次回日付の自動計算(「未定」表示)をやめ「月 日( )」の空欄に。③空き面の「様」が左に寄っていたため、名前領域に5文字分(5.5em)の最小幅を確保して右へ。④運動メニュー名が7文字超は「…」で切らず文字数比で自動縮小(最小7px)して全文字を印字。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8cc7872</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"次回予定の未入力人数バッジ+プレビュー前の確認ダイアログ(入力しに戻る/このまま進む)。残骸チェックボタン撤去\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-09-09</span></div>\n      <p class=\"title\">次回予定の未入力チェック(バッジ+プレビュー前確認)・残骸チェックボタン撤去(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">対処</span><span class=\"tx\">①「次回予定」ボタンに印刷時に空欄になる人数を赤バッジ「未入力◯名」で表示(判定は印刷表示と同条件・「未定」は意図的入力として除外・振替は対象日付き手入力のみ有効)。②プレビュー押下時に未入力者がいれば名前一覧と「入力しに戻る」(次回予定モーダルを開く)/「このまま進む」の確認を表示。③生成源を全て封じ振替も空欄化したため役目を終えた「残骸チェック」ボタンをヘッダから撤去(_scanOvZansai等の機能コードは温存・必要時に復活可)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6e0fa9e</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"振替のお迎え時間: 入力欄に自動の8時が出るのに印刷は空欄の食い違い。振替時は自動で埋めず空欄+振替バッジ+要入力表示。印刷も手入力のみ\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-09-09</span></div>\n      <p class=\"title\">振替の次回お迎え時間 — 入力欄と印刷の食い違いを解消(空欄+要入力方式・店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">「次回予定の変更」は振替でも表示日付の曜日から自動時間(8時等)を初期表示していたが、印刷側は振替時「その振替日向けの手入力(nextTimeOverrideFor一致)」のみ採用のため、入力欄=8時/印刷=空欄の食い違いが発生(細野様の事例)。</span><span class=\"lb\">対処</span><span class=\"tx\">①入力欄も振替時は自動で埋めず空欄(nextTimeOverrideFor一致の手入力のみ表示)。②行の名前上に緑の「振替」バッジ、時間欄に「要入力」+琥珀の注意枠で入力必要と分かるように。③印刷側の振替時の自動時間フォールバックも廃止し、手入力のみ印字。通常(振替以外)の自動計算は従来どおり。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6fff928</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"気分タップ時にテンキーが残留/自由入力欄へ誤フォーカスしキーボードが出る(Surface)。openKibunModalでテンキー必ず閉鎖+ゴーストクリックblur\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-09</span></div>\n      <p class=\"title\">気分入力でテンキー残留・自由入力欄への誤フォーカス(Windows Surface報告)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①DigitalKeypad(z99999)が気分モーダル(z10000)より上のため、血圧等で開いたテンキーがモーダル上に残留。②気分ボタンはpointerUpで発火するが、その後のネイティブclickが画面切替後の同座標にある自由入力欄に着弾しフォーカス(Surfaceではスクリーンキーボードも表示)。</span><span class=\"lb\">対処</span><span class=\"tx\">①openKibunModalで開いているテンキーを必ず閉じる(バイタル範囲チェックも通常クローズと同様に実施)。②自由入力欄のonFocusで、気分ボタン発火(_lpLastFireAt)から600ms以内のフォーカスをblurして弾く。理由ボタン群は既存のclickガードで保護済み。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">06aa28b</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"拡大ビューに状態(色分け表示)と通所時/帰宅時の気分(タップで全画面気分モーダル)を追加\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-09</span></div>\n      <p class=\"title\">拡大ビューに「状態」「通所時・帰宅時の気分」を追加(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">対処</span><span class=\"tx\">バイタルの上に3枚のカードを追加。状態=表示のみ(出席青/欠席赤/振替緑/休止橙/休業灰・変更は一覧画面で)。気分=現在の気分を大きく表示し、タップで既存の全画面気分モーダル(z10000&gt;拡大ビュー9980)がそのまま開く。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">06aa28b</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"介護整体吹き出しのコンパクト化。幅230→186px・文字/余白縮小・担当リスト3列。画面に収まらないとの店舗フィードバック対応\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-09</span></div>\n      <p class=\"title\">介護整体の吹き出しをコンパクト化 — 画面に収まらない問題(店舗フィードバック)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">案2導入直後、吹き出しの文字が大きすぎて全体が画面に収まりきらないとの指摘(スクショ付き)。</span><span class=\"lb\">対処</span><span class=\"tx\">幅230→186px・履歴行/担当ボタン/操作ボタンの文字と余白を縮小・担当者リストを2列→3列化。操作フロー(タップ選択・2タップ実施)は不変。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">527b27e</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"介護整体セルを大タップ領域+吹き出しメニューに刷新(案2)。過去3回選択・2タップ実施・取り消し/担当変更。極小ボタン廃止\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-09</span></div>\n      <p class=\"title\">介護整体セルを大タップ領域+吹き出しメニューに刷新 — 2タップ実施(案2・店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">「確認」「✓実施」が8pxの極小ボタンで押しづらいとの指摘。ユーザーと設計相談し、誤タップ耐性の高い案2(セルタップ→吹き出し内の大きなボタンで2タップ目)を採用。</span><span class=\"lb\">対処</span><span class=\"tx\">セル全体を1つのタップ領域化。空欄タップ=直近3回(日付+担当)と担当者リストを大ボタン表示→タップ選択。選択済みタップ=「✓実施にする」大ボタン(セル2回タップだけでは実施にならない)。実施済みタップ=取り消し/担当変更。空欄に戻すも同吹き出し内。上端付近の行は下側表示。保存経路(updateRecord/massage/done)は不変。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b54ac5d</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"体温テンキーの35./36./37.クイックボタンを7・8・9の真上へ移動し大型化。視線移動なしで先頭値→下1桁の流れに\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-09</span></div>\n      <p class=\"title\">体温テンキーの「35. 36. 37.」を7・8・9の真上へ移動+大型化(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">クイックボタンはテンキー最下部にあり、数字キーと視線が往復して押しづらかった。数字グリッドと同じ4列グリッドで7・8・9の真上に配置し、高さ・文字サイズを数字キーに近い大きさへ拡大。</span><span class=\"lb\">対処</span><span class=\"tx\">DigitalKeypadのprefixButtonsブロックを数字グリッド直前へ移動(4列グリッド・btnSize*0.9・fontSize*1.05)。動作(先頭値セット→下1桁入力)は不変。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">86529c7</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"拡大ボタンを名前横の虫めがねアイコン(SVG)に変更。行高が増えて見づらいとの店舗フィードバック対応。絵文字不使用方針のためSVGアイコン\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-09</span></div>\n      <p class=\"title\">拡大ボタンを名前横の虫めがねアイコンに変更 — 行の高さを増やさない(店舗フィードバック)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">PC表では「拡大」文字ボタンを名前の下に積んでいたため行幅(高さ)が増えて見づらいとの指摘。絵文字は使わないUI方針のため、ⓘと同系の小さなSVG虫めがねアイコン(＋付き)を名前と同じ行に置く形へ変更。スマホカード側も同アイコンに統一。</span><span class=\"lb\">対処</span><span class=\"tx\">PC表=名前の行内にアイコン(クリックはstopPropagationで利用者情報モーダルと分離)。スマホ=文字ボタンをアイコンへ置換。機能・保存経路は不変。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a20dd83</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"利用者名横に拡大ボタン。1名分のバイタル・運動・特記を大きな字と濃い色で全画面表示しそのまま入力。テンキー共通。高齢スタッフの見づらさ対策\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-09-09</span></div>\n      <p class=\"title\">提供記録に「拡大」ボタン — 1名分を大きな字で入力できる全画面ビュー(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">50〜60代のスタッフから「基準値の字が薄い・小さくて見づらい」との声。一覧表は情報量が多く文字を大きくできないため、利用者名の横に「拡大」ボタンを設け、押した方だけの入力画面を全画面で表示する方式にした。</span><span class=\"lb\">対処</span><span class=\"tx\">体温/血圧/脈拍(開始・終了)・運動メニュー(本日の目安を併記)・特記を大きな文字と濃い色で表示。タップで既存のテンキーが開き、保存経路(血圧の上下分割・運動の単位付与)は通常入力と完全共通。テンキーを無効化している店でも拡大ビュー内はテンキー入力可。スマホカード/PC表の両方に設置。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0fa4e08</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡\" data-text=\"印刷プレビューの白い縦/横線を解消(縮小スケールの丸め誤差でiframe土台の白が1px露出→html/iframe背景を#525659に)。スタンドアロン再現で修正確認済み\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡</span><span class=\"date tnum\">2026-09-08</span></div>\n      <p class=\"title\">印刷プレビューの白い線(右端・ページ下)を解消 — 縮小表示の丸め誤差(店舗報告)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">プレビューはiframeをtransform:scaleで縮小表示しており、丸め誤差でラッパーの切り抜きとiframe描画が1px弱ズレると、iframeの土台(html背景とiframe要素背景=白)が細い線として露出していた。スクロールバー説(前2回の修正)は誤りで、実プレビュー構造のスタンドアロン再現で本原因を特定。</span><span class=\"lb\">対処</span><span class=\"tx\">プレビュー用srcDocのhtml背景とiframe要素背景を周囲と同じ#525659に変更(露出しても見えない)。再現ページで白線消失を確認。印刷出力は別経路のため影響なし。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">fddacbd</span></span></div>\n    </article>\n    <article class=\"row k-improve\" data-kind=\"improve\" data-crit=\"0\" data-area=\"運用\" data-text=\"AI APIキーの本部一括管理(api/ai-draftプロキシ・店舗キー不要化・料金プラン別AI可否のフック内蔵)+プレビュー内側スクロールバー完全除去\">\n      <div class=\"row-top\"><span class=\"tag k-improve\">改善</span><span class=\"area\">運用</span><span class=\"date tnum\">2026-09-08</span></div>\n      <p class=\"title\">AIのAPIキーを本部一括管理に — 各店の設定不要化(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①api/ai-draftプロキシを新設し、Vercel環境変数ANTHROPIC_API_KEYを本部が1回設定すれば全店でAIが使える構成に(各店の「各種設定→モニタリング」のキー設定は不要・設定済みキーはフォールバックとして残る)。キーが端末に出ないためセキュリティも向上。POSTにstoreIdを受けるため、将来「料金プランごとのAI可否・上限」をサーバー側だけで追加可能。②印刷プレビューの内側スクロールバーをdisplay:none+overflow:hiddenで完全除去(前版のscrolling=noで残るケースがあった)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1cb28d2</span></span></div>\n    </article>\n    <article class=\"row k-improve\" data-kind=\"improve\" data-crit=\"0\" data-area=\"連絡\" data-text=\"印刷プレビューの内側スクロールバーを廃止(scrolling=no+遅延再測定で高さ自動追従・スクロールは外側1本に)\">\n      <div class=\"row-top\"><span class=\"tag k-improve\">改善</span><span class=\"area\">連絡</span><span class=\"date tnum\">2026-09-08</span></div>\n      <p class=\"title\">印刷プレビューの二重スクロールバーを解消(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">プレビューの書類すぐ横に内側(iframe)のスクロールバーが出て、右端の画面スクロールバーと二重になっていた。iframeをscrolling=no化し、高さはフォント読込後の遅延再測定(0.7秒/2秒)で内容に自動追従させ、スクロールを外側1本に統一。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2409f62</span></span></div>\n    </article>\n    <article class=\"row k-improve\" data-kind=\"improve\" data-crit=\"0\" data-area=\"計画書\" data-text=\"改善5件: 1日の流れ午前の部/午後の部化・取り込み先の説明明示・一括自動生成ボタン・作成予定の未作成既定表示・プレビュースクロールバー背景色化\">\n      <div class=\"row-top\"><span class=\"tag k-improve\">改善</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-09-08</span></div>\n      <p class=\"title\">通所介護計画書の取り込み・作成予定など改善5件(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①1日の流れ: 午前・午後とも通所の場合は「午前の部」「午後の部」の見出し行で区切る(前版のAM/PMプレフィクスは廃止)。②取り込みボタンに反映先の説明を追記(個別機能訓練→希望/目標/提供内容・興味関心→ご本人の希望)しフェイスシート補完も同カードへ。③「一括自動生成」ボタン新設: フェイスシート/基本利用日/個別機能訓練/興味関心を一度に空欄へ取り込み(quietパラメータ化・興味関心の重複追記防止)。④作成予定は未作成の方を既定で表示。⑤印刷プレビュー右端の白い縦線=iframeスクロールバーを背景色化。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f741c0d</span></span></div>\n    </article>\n    <article class=\"row k-improve\" data-kind=\"improve\" data-crit=\"0\" data-area=\"計画書\" data-text=\"改善6件: 1日の流れAM/PM区分・日誌スケジュール午前→午後複製・作成予定の月別ブラウズ・送付セットのページ分離表示・氏名マスキング1文字おき化・マスキングUI拡大\">\n      <div class=\"row-top\"><span class=\"tag k-improve\">改善</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-09-08</span></div>\n      <p class=\"title\">計画書・日誌・マスキングの改善6件(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①計画書の1日の流れ: 午前のみ/午後のみの利用者は該当時間帯のみ(既存)、両方利用の場合は時間に「AM9:00/PM13:00」の区分を付与。②各種設定→日誌の午後スケジュールに「午前の内容を複製」ボタン(行数・内容コピー、時間だけ調整)。③作成予定に「直近/1〜12月」切替(月選択でその月が期日の人を表示・過ぎた月は翌年扱い)。④印刷プレビューのページ分離CSSを入れ子対応にし、ケアマネ送付セットの送付状と計画書を1枚ずつ表示。⑤氏名マスキングを全伏せ→1文字おき(髙橋正樹→髙○正○)に全箇所統一。⑥マスキングのチェックUIを印刷ボタン横へ拡大移動。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">76a0480</span></span></div>\n    </article>\n    <article class=\"row k-improve\" data-kind=\"improve\" data-crit=\"0\" data-area=\"計画書\" data-text=\"通所介護計画書: 目標日付のクイック入力(今日/+3・6・12か月・令和自動)・①〜⑤期間の和暦化・印刷の短期目標潰れ修正(高さ配分38へ)\">\n      <div class=\"row-top\"><span class=\"tag k-improve\">改善</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-09-08</span></div>\n      <p class=\"title\">通所介護計画書の日付入力と印刷レイアウトを改善(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①長期・短期目標の設定日に「今日」、達成予定日に「+3か月/+6か月/+1年」ボタンを追加(設定日基点・令和表記で自動入力。相場は短期=3か月・長期=6か月〜1年)。②サービス提供内容①〜⑤の期間をカレンダー選択で「令和◯年◯月◯日」の和暦込みに(従来は月日のみ)。③印刷A4で設定日の折り返しにより短期目標行が潰れていたため、利用目標欄の高さ配分を28→38に拡大(基本情報88・提供内容146へ微調整)・日付列14%化。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a7b9934</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"計画書\" data-text=\"通所介護計画書の削除が復活する(墓石漏れ)。addTombstoneヘルパーで計画書4種+FAX履歴の削除7箇所に墓石追加。一時保存はdraftフラグで作成予定から再開可能に\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-09-08</span></div>\n      <p class=\"title\">計画書の「削除しても復活する」を修正・一時保存を作成予定から再開可能に(店舗報告)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"lb\"></span><span class=\"tx\">①削除復活: id単位マージ(和集合)対象の配列は、削除の墓石(deletedIds)を積まないとクラウド/他端末との同期で削除済み行が復活する。通所介護計画書の削除が墓石なしのfilterのみで、同型の穴が個別機能訓練・生活機能・興味関心・FAX履歴(休み連絡/各種連絡/モニタリング送付)にもあった。②一時保存: draft区別が無く、一時保存でも「作成済み」扱いになり作成予定から消え、開き直すと複製から始まっていた。</span><span class=\"lb\">対処</span><span class=\"tx\">addTombstoneヘルパーを新設し削除7箇所に墓石を追加。4画面のsaveRecordにdraftフラグを追加し、computePlanDuesは完成版のみで期日計算・最新が下書きなら「一時保存中(続きから作成)」として作成予定に表示、start_edit遷移は下書きを再開。upd-2026-0908c。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b0f2cad</span></span></div>\n    </article>\n    <article class=\"row k-improve\" data-kind=\"improve\" data-crit=\"0\" data-area=\"個人ファイル\" data-text=\"支援経過表に提供記録の状態を自動記載(欠席=理由付き・休止/休業=期間開始日のみ・出席=特記あり時)。休み連絡FAX行とは重複排除\">\n      <div class=\"row-top\"><span class=\"tag k-improve\">改善</span><span class=\"area\">個人ファイル</span><span class=\"date tnum\">2026-09-08</span></div>\n      <p class=\"title\">支援経過表に欠席・休止・休業・特記を自動記載(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">個人ファイルの支援経過表(自動生成)に提供記録由来の行を追加。①欠席=理由(特記)付きで記載し、休み連絡FAXを送った日は従来の休み連絡行に理由が載るため重複させない ②休止・休業=8日以内に続く同状態は同一期間とみなし開始日のみ記載(週1利用でも期間がつながる) ③出席=特記(様子)に記入がある日だけ「特記：…」として記載。過去分も遡って自動反映され、既存の行編集・削除(非表示)機構がそのまま使える。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">de5e550</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"次回が振替の方のお迎え時間を入力しても表示されない。振替時は手入力を常に無視する残骸対策が原因→対象日(nextTimeOverrideFor)併記方式で正当な入力のみ表示\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-09-08</span></div>\n      <p class=\"title\">次回が振替の方のお迎え時間が連絡帳に表示されない — 対象日併記方式で修正(店舗報告)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">連絡帳の次回お迎え時間は、次回が振替の場合「過去の手入力残骸(通常日向けの時刻)が区分に合わない時刻を出す」対策として nextTimeOverride を常に無視し自動計算(8時/13時)を表示していた。この結果、振替日向けに新しく入力した正当な時間まで「時 分」と空欄で印刷されていた。</span><span class=\"lb\">対処</span><span class=\"tx\">お迎え時間の保存時に対象の次回日付(nextTimeOverrideFor)を併記し、表示側は振替でも「対象日が表示中の次回日付と一致する手入力」のみ採用(残骸保護は維持)。値が同じ再確定でも対象日未記録なら書き直して既存入力を救済。提供記録再構築の引き継ぎ・FIELDTS_EXCLUDEにも追加。upd-2026-0908a。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6a9a2c1</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"モニタリング\" data-text=\"AI下書き等で画面が薄暗くなり操作不能(ブラウザ確認ダイアログが裏に隠れる)。confirm/alert計21箇所をアプリ内モーダルに全置換+syncLog容量超過の自動復旧\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">モニタリング</span><span class=\"date tnum\">2026-09-07</span></div>\n      <p class=\"title\">AI下書き等で画面が薄暗くなったまま操作不能 — ブラウザ標準ダイアログのアプリ内モーダル化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">遠隔診断で暗転中も端末のJS・同期は稼働中と確認→アプリ内エラーではなく、window.confirm/alertのダイアログ本体が環境(Surface/Edge等)によってウィンドウの裏に隠れ、ページ側の暗転だけが見える事象と判断(Enter/Escで解除可能)。</span><span class=\"lb\">対処</span><span class=\"tx\">MonitoringView内のconfirm7箇所・alert14箇所をアプリ内モーダル(monConfirm/monAlert)に全置換し、この事象クラスを根絶。あわせて遠隔診断で発見した扇橋iPad/PCのlocalStorage容量超過(QuotaExceeded)によるsyncLog凍結に自動復旧(20件へ切り詰め再試行)を実装。appData本体の容量削減は残課題として記録。upd-2026-0907f。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">18754f0</span></span></div>\n    </article>\n    <article class=\"row k-improve\" data-kind=\"improve\" data-crit=\"0\" data-area=\"モニタリング\" data-text=\"15日制限撤廃・AI上限を対象月ごとの集計に(月越しリセット是正)・①〜⑤の入力位置を固定幅で統一\">\n      <div class=\"row-top\"><span class=\"tag k-improve\">改善</span><span class=\"area\">モニタリング</span><span class=\"date tnum\">2026-09-07</span></div>\n      <p class=\"title\">モニタリング改善3点 — いつでも記入可・AI利用条件の月越し是正・入力位置の統一(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①「毎月15日以降のみ作成・記入可」の制限を撤廃(月内いつでも可。ゲートは残しfalse固定)。②AI下書き上限(利用者数×2回)の集計キーを「現在の月」→「表示中の対象月」に変更。従来は月が変わるとカウンタがリセットされ、過去月(8月・7月)を開くとまたAIが使えてしまっていた。今後は月を越しても各月の残数は不変(上限未達の月はいつでも利用可)。③一覧の①〜⑤の項目名ラベル(212px)と選択欄(150px)を固定幅にし、本文の入力・表示位置を全行で統一(文字数による凹凸を解消)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">976cc37</span></span></div>\n    </article>\n    <article class=\"row k-improve\" data-kind=\"improve\" data-crit=\"0\" data-area=\"分析\" data-text=\"振替理由にも大分類+詳細の2段入力(月間スケジュール/提供記録)。日誌の状態色を月間スケジュール配色に統一(振替=緑/休止=オレンジ/休業=グレー)\">\n      <div class=\"row-top\"><span class=\"tag k-improve\">改善</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-09-07</span></div>\n      <p class=\"title\">振替の理由も大分類から選択可能に・日誌の状態色を月間スケジュールと統一(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①月間スケジュールの振替モーダルと提供記録の状態変更(振替)の理由入力に、欠席と同じ大分類チップ+詳細記入+プレビューを追加。確定時に「大分類（詳細）」形式で欠席側の特記(◯月◯日へ振替（理由）)に入り、欠席理由ランキングに大分類で集計される。②日誌の状態列の色が出席=青・欠席=赤以外は黒だったため、月間スケジュールの配色(振替=緑・休止=オレンジ・休業=グレー)に統一。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7ac7477</span></span></div>\n    </article>\n    <article class=\"row k-improve\" data-kind=\"improve\" data-crit=\"0\" data-area=\"連絡\" data-text=\"定型文一覧をタイトルのみ+タップ展開に。編集画面のボタン配置を左キャンセル右保存に統一(店舗要望)\">\n      <div class=\"row-top\"><span class=\"tag k-improve\">改善</span><span class=\"area\">連絡</span><span class=\"date tnum\">2026-09-07</span></div>\n      <p class=\"title\">各種連絡の定型文一覧をタイトルのみ+タップ展開に — ボタン配置もアプリ標準に統一(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①定型文一覧は本文が常時表示され画面領域を圧迫していたため、タイトルのみの折りたたみ表示にし、タップで本文と操作ボタン(挿入・編集・削除)を展開する方式に変更。②編集画面の「保存(左)・キャンセル(右)」がアプリ標準(左=キャンセル・右=保存)と逆だったため統一。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">37b5db6</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"同期\" data-text=\"各種連絡の定型文が保存直後に消える(同期保護リストの漏れ)。網羅監査で定型文/ADL評価/お知らせ3種/休み連絡状態/下書き/勤務表を保護に追加+削除復活防止の墓石\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-07</span></div>\n      <p class=\"title\">各種連絡の定型文が保存直後に消える — 同期保護リストの漏れを網羅監査で一括是正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">定型文(generalFaxTemplates)がpull保持・push側idマージ・_savedAt刻印の全てから漏れており、保存直後のpull(クラウド丸ごと採用)で端末から消え、その状態の次のpushでクラウドからも消えていた(日誌データ消失と同構造)。</span><span class=\"lb\">対処</span><span class=\"tx\">網羅監査を実施し、刻印+push側マージ+pull保持に generalFaxTemplates/adlRecords/trashedAnnouncements を、pull保持に お知らせ3種(全体/個別/写真)を、pullオブジェクト保持に faxDataStore(キー単位_updatedAt)/generalFaxDraft(_updatedAt)/workSchedule(月×スタッフ_wsTs) を追加。idマージは和集合のため、定型文削除とADL評価削除に復活防止の墓石を追加。storeMembersは削除経路に墓石が無く対象外のまま(従来挙動)。upd-2026-0907b。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5a9763c</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"【恒久対策】全保存を即時クラウド送信に統一。options無しonSave 77箇所(削除・設定変更等)が端末内のみ保存だった穴を根絶(日誌真因の水平展開)\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-07</span></div>\n      <p class=\"title\">【恒久対策】「端末内にだけ保存されクラウドに送信されない保存」をアプリ全体で根絶</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">handleSaveToCloudはoptions.manual/silent指定時のみクラウド送信し、無指定のonSave呼び出しが全画面に77箇所(削除・設定変更・記録操作等)。これらは端末内のみ保存で、次のmanual/silent保存に相乗りするまでクラウドに届かず、再読み込みやpullのタイミング次第で消える=前日の日誌データ消失(5a52c5e)と同型の穴。</span><span class=\"lb\">対処</span><span class=\"tx\">push条件を撤廃し全保存を即時クラウド送信に統一。成功トーストはmanualのみ(silent/無指定は静かに送信)・失敗通知は全保存で表示・_lastSyncも全保存で刻印。CASは直列化済みのため保存頻度増の自己衝突なし。upd-2026-0907a。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">be408d5</span></span></div>\n    </article>\n    <article class=\"row k-improve\" data-kind=\"improve\" data-crit=\"0\" data-area=\"分析\" data-text=\"欠席理由を大分類+詳細の2段入力に(体調不良/通院・受診/入院/本人・家族の都合/冠婚葬祭/天候/その他)。特記=「大分類（詳細）」形式・ランキングは大分類集計+詳細内訳表示\">\n      <div class=\"row-top\"><span class=\"tag k-improve\">改善</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-09-07</span></div>\n      <p class=\"title\">欠席理由を「大分類を選択→詳細を記入」の2段入力に — 欠席理由ランキングの分類精度向上(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">従来は自由文のため「発熱、咳がひどいから」等が1つずつ別枠で集計され、体調不良として括れなかった。欠席時の理由入力を大分類(体調不良/通院・受診/入院/本人・家族の都合/冠婚葬祭/天候/その他)の選択+詳細の自由記入に変更し、特記には「体調不良（咳がひどい）」形式で記録。提供記録の状態変更モーダルと月間スケジュールの欠席理由モーダルの両方に適用。分析の欠席理由ランキングは大分類で集計し、詳細は件数付き内訳(上位3件・ホバーで全件)を表示。過去の自由文もキーワード表で大分類に寄せて集計(複数分類にまたがる文は原文維持)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">be408d5</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"日誌\" data-text=\"【重大・真因】日誌の自動保存5経路がoptions無しでonSaveを呼び、クラウドへ一度も送信されていなかった(manual/silent指定時のみpushする仕様)。全てにsilent付与で即時送信に\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-06</span></div>\n      <p class=\"title\">【重大・真因】日誌の自動保存がクラウドに一度も送信されていなかった — 「まだ消える」の最終回答</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">handleSaveToCloudは options.manual(手動保存)/options.silent(自動保存) 指定時のみ即時クラウド送信し、無指定の保存は端末内のみ(旧debounce送信経路は撤去済みで存在しない)。日誌の自動保存5経路(編集1.5秒後・AM/PM切替時・日付移動時・自己修復再送・1日モードの送迎車適用)が全てoptions無しで呼んでおり、クラウドへ一度も送信されていなかった。遠隔診断ログ(diag_店舗行)で裏付け: 日誌編集中にsaveログが皆無・silent保存はsave→push-okが正常記録・手動保存ボタンの3件だけが16:08に着弾。</span><span class=\"lb\">対処</span><span class=\"tx\">5経路全てに{silent:true}を付与し即時クラウド送信に変更(silent=成功トースト無し・失敗時のみ通知)。upd-2026-0906d。なお同型のoptions無しonSaveは全画面で77箇所あり、既定でも送信する恒久対策を次で実施予定(未来の修正点に記録)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5a52c5e</span></span></div>\n    </article>\n    <article class=\"row k-improve\" data-kind=\"improve\" data-crit=\"0\" data-area=\"運用\" data-text=\"遠隔調査基盤: 稼働版数の画面表示+同期診断ログ(syncLog)のクラウド自動送信(diag_店舗行)+push不許可理由の記録\">\n      <div class=\"row-top\"><span class=\"tag k-improve\">改善</span><span class=\"area\">運用</span><span class=\"date tnum\">2026-09-06</span></div>\n      <p class=\"title\">遠隔調査基盤を追加 — 稼働中アプリ版の常時表示+同期診断ログのクラウド送信</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">「保存が届かない」端末を遠隔調査できるよう、①スタッフ画面左下にビルド焼き込みのアプリ版数を常時表示(今すぐ更新が効いたかスクショで確認可能) ②localStorageのみだった同期診断ログ(syncLog)の末尾60件を60秒ごとにapp_stateの別行(diag_店舗)へベストエフォート送信(端末タグ=端末名|版数・本体データと完全分離で失敗無害) ③保存時にpush不許可の理由(店舗切替中/読込未完/店舗不一致/実データ無し)を必ず記録。この基盤により本件の真因を配信から数分で特定できた。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6f060c3</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"日誌\" data-text=\"【重大・根本対策】日誌データ消失の根本原因=pullのdiaryLogs保持漏れ。15秒pullが日誌だけ古いクラウド値で丸ごと置換していた。保持マージ+再pushを追加\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-06</span></div>\n      <p class=\"title\">【重大・根本対策】日誌の入力が消える根本原因 — 15秒同期(pull)の日誌保持漏れ</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">15秒pullはクラウドを丸ごと採用する際、提供記録・他の記録配列・設定・利用者・月間シフトには「端末内が新しい分(push未達)を保持」する処理があるが、diaryLogs(日誌オブジェクト)だけ保持リストから漏れていた。保存のpush完了前にpullが重なると日誌がappDataごと古いクラウド値に巻き戻り、以後の自動保存が巻き戻った内容を保存し続ける。クラウド実データで裏付け: 8/28_AMは同セッションのdriver/carTimes/managerConfirmedのみ当日刻印で、直前に設定したpick/drop(送迎車)は8/28のまま=巻き戻り後の状態が保存された痕跡。8/21_PMの_savedAtは8/21 09:26のままで、当日の入力が同じ穴で消えていた(9/4報告の「AM/PM切替で入力が戻る」も同根)。自動保存の導入で保存頻度が上がり、露出が急増して顕在化した。</span><span class=\"lb\">対処</span><span class=\"tx\">pullにdiaryLogs保持を追加: push側(mergeStates)と同じ「キー単位_savedAt+項目単位_fieldTsで新しい方を採用」でマージし、保持が発生したら_mergedForPushで再pushしてクラウドへ追いつかせる。syncLogにpull-preserve(diaryLogs)を記録し発生を観測可能に。消えた過去の入力は復元不可(再入力を依頼)。upd-2026-0906b。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9de4b30</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"日誌\" data-text=\"【重大】日誌の入力が消える(自動保存の古いスナップショット保存+dirtyガード消失による同期巻き戻り)。appDataRef土台化+_savedAt比較ガード+自己修復re-pushで修正\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-06</span></div>\n      <p class=\"title\">【重大】日誌で送迎時間を入力したら入力済みデータが消えた — 前日導入の自動保存と同期の競合</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">前日(9/4)導入の自動保存に2つの穴があった。①setTimeout発火時のappDataは最大1.5秒古いクロージャで、その間に15秒同期(pull)が届いていると、届いたばかりのデータを古い状態で上書き保存し得た。②自動保存で「未保存(dirty)」状態がほぼ無くなり、「編集中は同期で画面を上書きしない」既存ガードが機能しなくなった。保存の直後に古いクラウドスナップショットのpullが届くと、入力済みの画面ごと古い内容に巻き戻り「消えた」ように見えた。</span><span class=\"lb\">対処</span><span class=\"tx\">①自動保存の土台をappDataRef(常に最新)に変更。②リモート適用ガードを追加: リモートの_savedAtがローカルの_savedAtより古い/保存済みログに対して空の場合は適用せず、画面を保持したまま最新内容を自動で再保存してクラウドに追いつかせる(自己修復)。約1日で修正(upd-2026-0906a)。ガードレールに「dirtyフラグの意味を変える変更は、dirtyを前提にした既存ガードを全て洗い出す」を追記。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e3dfbbc</span></span></div>\n    </article>\n    <article class=\"row k-improve\" data-kind=\"improve\" data-crit=\"0\" data-area=\"日誌\" data-text=\"送迎時間キーパッド3桁の時優先判定(132→13:2、859→08:59)。先頭2桁が23以下なら時と解釈\">\n      <div class=\"row-top\"><span class=\"tag k-improve\">改善</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-06</span></div>\n      <p class=\"title\">送迎時間キーパッド: 「132」が「01:32」になる — 時として成立する読み方を自動判定に</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">前日の「下2桁=分」固定の整形では、13:24を打つ途中の「132」が「01:32」と表示され誤解を招いた(扇橋指摘)。3桁入力は先頭2桁が時として成立(23以下)すれば時優先=「132」→「13:2」、成立しなければ時1桁+分2桁=「859」→「08:59」と判定。決定時の解釈も同じ判定に統一。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e3dfbbc</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"送迎車の割り当てが別の利用者に表示される(丸山様が徒歩・吉岡様に車)。行番号フォールバックが他人のIDキーを誤読。ID化以降は行番号フォールバック禁止(表示・モーダル・1週間前コピー)\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-04</span></div>\n      <p class=\"title\">送迎車の割り当てが別の利用者に表示される場合がある(徒歩の方に車が付く等) — 扇橋実地テスト指摘</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">送迎キーは2026-07-14に行番号→利用者IDへ変更済みだが、キーの無い利用者は行番号で読むフォールバックが残っていた。利用者IDは連番の小さい整数のため、行番号が別の利用者のIDと衝突し、他人の車/徒歩を誤読・誤表示していた(例: キー未保存の丸山様の行番号=徒歩設定のある別利用者のID)。1週間前コピーの解決処理にも同種の誤解釈があり、コピー先で別人に車が付き得た。</span><span class=\"lb\">対処</span><span class=\"tx\">ID化(7/15)以降の日付の日誌では行番号フォールバックを禁止(帳票表示 getSelectedCar・割り当てモーダル・1週間前コピー _resolvePrevPid の3箇所)。行番号解釈は7/14以前の旧データとマスタ未登録の手書き行のみに限定。過去日の表示ずれは割り当てを開いて設定し直せば解消(IDキーで上書き保存される)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c5f4407</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"カレンダーの緑●/AM/PM印を「要確認が全て解消した日」基準に変更。空ログの印残り・8/27以前保存分のコピー未確認残骸で印が付かない問題を修正\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-04</span></div>\n      <p class=\"title\">カレンダーの印が「入力して消しただけの日」に残り、「入力済みの日」(8/3・8/6等)に付かない</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">印の判定が「ログに何かキーがあれば入力済み」だったため、入力して消した日誌(空値のキーだけ残る)にも印が付いた。逆に8/27以前に保存した日誌は、当時「手動保存してもコピー未確認フラグ(_sougeiPending)が消えない」仕様だったため残骸が保存されており、全部入力済みでも印が永久に付かなかった。</span><span class=\"lb\">対処</span><span class=\"tx\">印の基準を「要確認バッジが全て解消した日」(迎え/送り・送迎時間・記録者・管理者確認まで完了)に変更し、要確認判定と完全に一致させた。8/27以前の日付では_sougeiPending残骸を無視する。凡例も「AM+PM完了」等に更新。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c5f4407</span></span></div>\n    </article>\n    <article class=\"row k-improve\" data-kind=\"improve\" data-crit=\"0\" data-area=\"日誌\" data-text=\"休業日・半日休業のスロットは要確認バッジ/ホームお知らせ/サイドバーバッジの対象外。半日休業は営業側完了で緑●\">\n      <div class=\"row-top\"><span class=\"tag k-improve\">改善</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-04</span></div>\n      <p class=\"title\">休業に設定した日は日誌の「要確認」を出さない — 扇橋実地テスト指摘</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">休業日は担当職員も送迎も無いため、要確認バッジ・ホームの日誌お知らせ・サイドバーの日誌バッジを表示しない。半日休業(AM/PM指定)は休業側スロットだけを対象外にし、営業側が完了すればカレンダーに緑●が付く。判定はスロット別休業ヘルパー(diarySlotKyugyo)に共通化。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c5f4407</span></span></div>\n    </article>\n    <article class=\"row k-improve\" data-kind=\"improve\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌の全自動保存(編集停止1.5秒)。AM/PM切替・日付移動で入力が戻る事故を防止。保存ボタン=コピー確認の意味は維持\">\n      <div class=\"row-top\"><span class=\"tag k-improve\">改善</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-04</span></div>\n      <p class=\"title\">日誌を全自動保存に — 保存ボタンを押さずにAM/PM切替すると入力前に戻る事故の防止</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">編集の手が1.5秒止まったら自動保存する。従来もAM/PM切替時・日付移動時に個別の自動保存はあったが、保存前の切替タイミングや同期の競合で入力が戻るケースが残っていたため、常時保存に変更。自動保存はコピー未確認フラグを消さない(=「内容を確認した」の意味は保存ボタン/該当欄の編集のみが持つ。カレンダー印・要確認バッジの意味を壊さない)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c5f4407</span></span></div>\n    </article>\n    <article class=\"row k-improve\" data-kind=\"improve\" data-crit=\"0\" data-area=\"日誌\" data-text=\"送迎時間キーパッドの入力中表示を確定後と同じに(859→08:59)。旧表示は85:9で分かりにくかった\">\n      <div class=\"row-top\"><span class=\"tag k-improve\">改善</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-04</span></div>\n      <p class=\"title\">送迎時間キーパッド: 入力中も「08:59」のように確定後と同じ表示に — 扇橋実地テスト指摘</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">「859」と押すと入力中は「85:9」と表示され、決定後に「08:59」になっていた。決定時の整形(下2桁=分・残り=時)と同じ解釈で入力中から表示するよう変更(2桁までは時を入力中なのでそのまま表示)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c5f4407</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡\" data-text=\"各種連絡がReferenceErrorでクラッシュ(フックの宣言前pageCount参照・TDZ)。宣言後へ移動+連絡FAX2画面をE2E遷移テストに追加。緊急修正\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡</span><span class=\"date tnum\">2026-09-04</span></div>\n      <p class=\"title\">【緊急】各種連絡が開けない(画面エラー) — 0904aの自動縮小フックの実装ミス</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">同日朝の修正(f07b9d0)で入れた連絡事項の実測縮小フックを、依存する pageCount の宣言より前に配置したため、初期化前参照(TDZ)の ReferenceError で GeneralFaxView 全体がクラッシュしていた。休み連絡/各種連絡は画面遷移E2Eの対象外で、デプロイ前検査をすり抜けた。</span><span class=\"lb\">対処</span><span class=\"tx\">フックを宣言後へ移動して即日修正(約1時間で復旧)。再発防止として休み連絡・各種連絡をE2E画面遷移テストに追加(chromium+iPadの22件PASS)。「新しい画面ロジックを足すときは、その画面がE2E遷移テストに含まれているかを確認する」をガードレールに追記。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">84f056f</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡\" data-text=\"振替の休み連絡が振替先(出席日)にも表示・理由欄に振替表記。元日側のみ表示・理由は休み理由・振替日は連絡事項に時制つき自動記載。連絡事項の実測自動縮小。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡</span><span class=\"date tnum\">2026-09-04</span></div>\n      <p class=\"title\">振替の休み連絡の是正(元日側のみ表示・理由欄は休み理由)+連絡事項の実測自動縮小</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">前日の「振替も休み連絡に表示」対応で、status=振替のレコード(=振替で出席する日)までカレンダーに載り、出席日にも休み連絡が表示され、開くと理由欄に「◯月◯日AM分振替」が出ていた。また連絡事項の自動縮小が文字数推定で、実際の枠寸法とズレてスクロールが残っていた。</span><span class=\"lb\">対処</span><span class=\"tx\">表示は欠席(基本利用日で休んだ側)のみに戻し、振替の有無は欠席記録の「◯月◯日へ振替」表記から判定して「振替あり」バッジ表示。理由欄は休み理由のみ(未記入なら空欄)、振替日は連絡事項に「◯月◯日に振替予定です/振替いたしました」(現在基準で時制切替)を自動記載。連絡事項の縮小はscrollHeight実測で収まるまで自動調整に変更(休み連絡・各種連絡とも)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f07b9d0</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ケアマネ連携\" data-text=\"招待メール済みバッジをクラウド招待参照に。送信端末以外でも表示。supabaseListCmInvitesForStore。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-09-04</span></div>\n      <p class=\"title\">担当者カードに「招待メール済み・登録待ち(送信日)」を全端末で表示</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">招待メールの送信記録が送信した端末のローカルにしか残らず、他の端末では「閲覧登録なし」に見えていた。クラウドの招待テーブル(family_invites・メールアドレス一致・未使用・期限内)も参照して判定するようにし、どの端末でも「招待メール済み・登録待ち(◯月◯日 送信)」が表示される。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f07b9d0</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"同期\" data-text=\"店舗ログイン/切替直後に前店舗の利用者名が一瞬見える(個人情報)。_sbStoreId不一致の間はオーバーレイでゲート。スタッフ選択画面の空表示も読み込み中表示に。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-03</span></div>\n      <p class=\"title\">ログイン直後に別店舗の利用者名が一瞬見える(扇橋で報告・個人情報) — 読込完了までのゲートを追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">店舗ログイン/切替の直後、端末に残っていた前店舗のデータ(daycareAppData_v3)が新店舗の読込完了までの0.数秒だけ描画されていた。スタッフ選択画面も同様に、読込前は「メンバーなし」空画面→数秒後に突然スタッフが現れていた。</span><span class=\"lb\">対処</span><span class=\"tx\">手元データの店舗ID(_sbStoreId)がログイン中の店舗と一致しない間は「最新のデータを取得しています…」オーバーレイで全面ゲートし、前店舗の情報を画面に出さない。スタッフ選択画面には読み込み中スピナーを追加。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">377fd1c</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"日誌\" data-text=\"スタッフ削除×修正・編集から削除・1日ヘルプ・送迎車リセット・時刻検証・振替あり表示・連絡事項自動縮小。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-03</span></div>\n      <p class=\"title\">スタッフ管理・日誌・休み連絡の改善7件(実地テストのフィードバック反映)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①スタッフ選択の×で日誌由来のスタッフが削除できなかった問題を修正(id直一致・同名同役職も連動削除)。②スタッフ切替の「編集」からも削除可能に(選択中スタッフは削除不可)。③日誌の「担当者を追加」は既定で「この日だけ(ヘルプ)」になり、その日の日誌にのみ表示・スタッフ切替や各種設定には出ない(35日で自動掃除)。恒常スタッフはチェックを外して追加。④送迎車割り当てに「全員を未設定にする(リセット)」(1週間前コピー後の作り直し用・適用まで未保存)。⑤到着/出発時間は00:00〜23:59のみ保存可。⑥「振替」も休み連絡カレンダーに表示(振替ありバッジ)+連絡文面に振替日を自動記載。⑦休み連絡/各種連絡の連絡事項は文量に応じて自動縮小し印刷と同じ見た目で入力できる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">377fd1c</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"データ取得中の自動リカバリ(3秒ごと再取得)・同一店舗の利用者切替は即表示・空データ上書き禁止ガード。手動再読み込み不要化。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-03</span></div>\n      <p class=\"title\">「データを取得中」で手動の再読み込みが必要 — 自動リカバリ化と切替の即時表示</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①「データを取得中」画面の間は3秒ごとにクラウドから自動で取り直す(従来は15秒の定期取得待ちで、手動の「再読み込み」を押させていた)。②利用者切替は同一店舗内ならデータをクリアせず即表示(従来は切替のたびに空にして最大15秒待たせていた)。③localStorage取り込みに「利用者が入っている状態を空データで潰さない」ガードを追加(別タブのログイン初期化を拾って表示中の画面が取得中に落ちる穴)。④取得中画面の文言を「自動で取得しています(操作は不要)」に変更。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3ba3298</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"PCでデータ取得中ループ・一瞬表示・チカつき・重い。スタッフ画面と同一localStorageキーの取り込み合いが原因。ポータル専用キーに分離。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-03</span></div>\n      <p class=\"title\">PCでケアマネページが「データを取得中」のまま進まない — スタッフ画面との端末保存の衝突が原因</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">家族/ケアマネポータルはスタッフ画面と同じ端末保存キー(daycareAppData_v3)を1.5秒ごとに読み直す設計で、同じブラウザにスタッフ画面のタブが開いていると、スタッフ側の保存(別店舗のデータ・別形状)を取り込み続けて閲覧中の利用者が見つからなくなり「データを取得中」ループ・一瞬だけ表示されて戻る・チカつき・巨大JSONの毎秒解析でブラウザが重い、が発生(Windows/Macで実害。ポータル単独のスマホでは起きない)。</span><span class=\"lb\">対処</span><span class=\"tx\">ポータルの端末保存を専用キー(tsumugiFamilyAppData_v1)へ完全分離(24箇所)。1.5秒ポーリングは中身が変わった時だけJSON解析する方式に軽量化。「データを取得中」画面のログアウトが利用者選択画面に化ける問題(セッション消去漏れ)も修正。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">09a3865</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"ケアマネ連携\" data-text=\"担当変更で旧担当の閲覧が残り新担当に付与されない。ログイン時完全整合(失効+基点repoint+残骸グループ掃除+重複排除)。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-09-03</span></div>\n      <p class=\"title\">担当を変更しても「前の担当者に見え続け・新しい担当者に付与されない」 — ログイン時の完全整合を実装</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①自己付与は「追加」のみで、担当から外れた分の失効は行っていなかった。②担当から外れた基点行(ログインIDの行)を停止するとログイン自体が死ぬ設計欠陥があった。③削除済みの旧テストアカウント(同一メール)のグループから複製が誤生成される穴が実際に発生(asaasa由来で境様担当3名分が旧パスワードのまま生成)。④同一利用者を指す行が併存すると切替に2回表示されうる。</span><span class=\"lb\">対処</span><span class=\"tx\">api/cm-provisionを完全整合化: 不足分の付与+担当外れ複製の停止+基点行は現担当利用者へ付け替え(担当0なら停止)+生きた基点の無い同メール別パスワードグループの複製を自動停止。スタッフ側エンジンにも同ルールを実装し、linkedAccountsは利用者id単位で重複排除。閲覧中の利用者が担当外れになった場合はログイン行の利用者へ自動移動。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">58de26b</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"ケアマネ連携\" data-text=\"複製アカウントのinsertがrole値の制約で全滅していた真因。role=member統一・多段再試行・サーバー側付与API cm-provision 新設・アプリ版表示。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-09-03</span></div>\n      <p class=\"title\">利用者切替が出ない真の原因が判明 — 複製アカウントの作成が一度も成功していなかった(roleの値制約)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">クラウドの実データ精査で「登録フォーム経由のアカウント作成(role=member)は全て成功、自動同期エンジン/自己付与の複製作成(role=caremanager)は導入以来一度も成功していない」ことを確認。DB側のrole列の許容値制約に弾かれ、担当変更でエンジンに明確なトリガーがあった時刻(11:50)ですら複製が作られていなかった。前日までに直した「古いタブ」「5分tick」「担当欄の巻き戻り」は実在した別問題だが、これが最後の関門だった。</span><span class=\"lb\">対処</span><span class=\"tx\">①複製もrole='member'に統一(種別判定はkind/relation)。②insertをDB制約差異吸収の多段再試行に(role許容値→記号なしID→role列default)。③サービスキーで確実に付与するサーバーAPI(/api/cm-provision)を新設し、ログイン時/起動時はAPI優先・不達時のみクライアント処理。④起動時付与用の認証情報をsessionStorage保持(15秒pullで平文パスワードが失われる穴)。⑤ポータルに「アプリ版」表示を追加し、今後のスクショで実行中の版を即断できるように。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">22e970f</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"担当を変更で設定した担当ケアマネが他端末の保存で巻き戻り消失(項目保護なし)。cm系を_fieldTs保護に追加。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-03</span><span class=\"tag k-crit\">重大</span></div>\n      <p class=\"title\">「担当を変更」で設定した担当ケアマネが消える — 項目単位保護の対象外だった(試作店で実例)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">利用者の担当ケアマネ欄(cmOffice/cmName等)は項目単位時刻(_fieldTs)の保護対象外で、別端末(家族/ケアマネポータル含む)が古いスナップショットでその利用者を保存すると担当情報だけ巻き戻って消えた。試作店では大和田様の担当欄がクラウド上から完全に消失しており、担当一致で決まるケアマネの閲覧付与も1名分作られなかった。</span><span class=\"lb\">対処</span><span class=\"tx\">cmOffice/cmName/cmPhone/cmFax/cmHistoryを保存時刻印(_PT_FL)とマージ保護(PATIENT_FIELDLEVEL)の両方に追加。家族側マージ(supabaseMergePatientFromFamily)のcm系更新にも刻印。既に消えた分はスタッフ端末の次回保存の空欄補完で復元される見込み(表示されない場合は「担当を変更」で再設定)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0fb622f</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"ポータルの開きっぱなしタブが旧JSのまま動き修正が反映されない→ログイン画面で自動再読み込み。起動時自己付与。切替ボタンが一度で消えるバグ。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-03</span></div>\n      <p class=\"title\">修正を配信してもケアマネの利用者切替が出ない — ポータルの「古いタブ」問題と切替ボタンの消失を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①家族/ケアマネポータルにはスタッフ画面の「今すぐ更新」バナーが無く、開きっぱなしのタブはログアウト/ログインを繰り返しても配信前の古いJSのまま動く。前日配信の「ログイン時自己付与」が本人の端末で一度も実行されていなかった(クラウド実データの精査で、担当2名分のうち1名分のアカウントが未作成のままと確認)。②さらに利用者切替で一度選択するとリンク一覧を消す実装で、2回目以降の切替ボタンが消える既存バグもあった。</span><span class=\"lb\">対処</span><span class=\"tx\">①ログイン画面表示中にupdate-notes.jsonのversionをバンドル焼き込み値と比較し、違えば一度だけ自動再読み込み(ループ防止ガード付き・入力中データの無い画面のみ)。②ログイン済みケアマネの起動時にも自己付与を実行し、増えた担当をその場で利用者切替に反映。③切替の選択後もリンク一覧を保持(ログアウト時に消去)。④自己付与のinsert失敗をconsole.warnで可視化。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0fb622f</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"パスワード変更後も旧パスワードでログインできた(mac/ipad)。認証エラー時のローカルフォールバック禁止。セキュリティ\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-02</span></div>\n      <p class=\"title\">パスワード変更後も以前のパスワードでログインできてしまう(Mac/iPadで確認) — 認証の抜け道を閉鎖</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">家族/ケアマネのログインはSupabase照合が本線だが、照合に失敗すると端末内に残る古い控え(平文パスワード時代のアカウント情報)で通すフォールバックがあった。パスワード変更は他端末の控えまで書き換えないため、変更前に一度でもログインした端末では旧パスワードが通り続けた(Macでの「ログイン後もデータ取得中のまま・切替なし」も、この控えログインが原因で正規の閲覧付与が走らなかったもの)。</span><span class=\"lb\">対処</span><span class=\"tx\">Supabaseが「IDまたはパスワードが違います」と明確に判定した場合はローカルの控えでのログインを禁止し、そのままエラー表示(本部管理者のプレビューはSupabaseスタッフ認証を先に確認する形で維持)。控えでのログインは通信障害でSupabaseに到達できない場合のみに限定。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3716101</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"ケアマネ連携\" data-text=\"複数利用者の切替が出ない: ログイン時自己付与supabaseSelfProvisionCm。新規登録のサービス提供内容タブ遷移漏れ。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-09-02</span></div>\n      <p class=\"title\">ケアマネの複数利用者切替が登録後も出ない — ログイン時の閲覧自己付与を新設(+新規登録のタブ遷移漏れ)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">閲覧付与を作る自動同期エンジンは店舗スタッフの端末が開いているときしか動かず、5分定期tickを足しても「店舗端末が閉じている夜間などに登録したケアマネ」には付与されない穴が残っていた。</span><span class=\"lb\">対処</span><span class=\"tx\">ケアマネ本人のログイン成功時に、店舗データから担当利用者を特定して不足分の閲覧アカウントをその場で自動付与する supabaseSelfProvisionCm を新設(メール一致または事業所+氏名一致1名のみ・退所済み除外・担当外れ分は復活させない)。付与後は自動で再ログインし、初回ログインから利用者切替に全員が表示される。あわせて利用者マスタの新規登録で「登録してサービス提供内容へ」を押しても画面が移動しない問題(タブ切替の指定漏れ)を修正。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3716101</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"自己リセット3回化・ID+メール不一致表示・新パスワード表示切替・招待経由の事業所固定。パスワード\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-02</span></div>\n      <p class=\"title\">パスワード自己リセットと登録フォームの改善4点(実地テストのフィードバック反映)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①確認コードの試行上限を5回→3回に変更(メール文面・画面表記も統一)。②ログインIDとメールアドレスの組み合わせが登録と一致しない場合、次の画面へ進めず「どちらかが間違っています」をその場に表示(送信の成否フラグを応答に追加。第三者への情報漏えいには当たらない範囲で利便性を優先)。③パスワード変更画面の新しいパスワードに「表示/非表示」切替を追加。④招待メール経由のケアマネ登録は事業所をデイサービス側の登録内容で固定表示に変更(誤りは店舗で修正のうえ再招待する運用)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3716101</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"同期\" data-text=\"アカウント管理10秒更新の不一致ループで全画面チカチカ(家族/ケアマネポータル含む)。射影比較+保持マージで修正。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-02</span></div>\n      <p class=\"title\">画面が10秒ごとにチカチカする(ケアマネからクレーム) — アカウント管理の更新ループが原因</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">アカウント管理モーダルの10秒ポーリングが「現在値とSupabase取得値のJSON丸ごと比較」で、(1)取得順が毎回変わる (2)ローカル側だけが持つ項目(cm招待のcmOffice/cmName・実パスワード等)がある、の2点により毎回不一致→10秒ごとにonSave(全体保存)→全画面再描画+クラウド書込→他端末・家族/ケアマネポータルのpull→再描画、というループ。副作用としてcm招待の追跡情報と実パスワードがサーバー形(****)で上書きされる問題も併発。</span><span class=\"lb\">対処</span><span class=\"tx\">共有項目のみをid昇順に射影して比較し、同一ならスキップ。保存時はローカル項目を保持したままサーバー値を重ねるマージに変更(実パスワードは****で潰さない)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8bd889e</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ケアマネ\" data-text=\"担当者招待の登録フォーム自動入力(氏名/かな/事業所)・閲覧自動同期の5分定期起動。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">ケアマネ</span><span class=\"date tnum\">2026-09-02</span></div>\n      <p class=\"title\">担当者招待の登録フォームに氏名・ふりがな・事業所を自動入力/閲覧自動同期に5分定期起動を追加</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①招待トークンに担当者マスタの姓名/ふりがな/事業所を同梱(cl/cf/kl/kf/co)し、登録フォームのご登録者情報と事業所選択を自動入力(ローカル招待レコードのcmName/cmOfficeからも復元)。②閲覧自動同期エンジンは担当データの署名変化でしか起動せず、ケアマネ登録直後(Supabase側のみ変化)に動かない穴があった→5分間隔の定期tickで強制再評価。複数担当の付与は登録後最大5分+再ログインで反映。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8bd889e</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"同期\" data-text=\"メモリクラッシュ(コード5)再発対策: pull由来の端末保存を10秒間引き。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-02</span></div>\n      <p class=\"title\">長時間使用でブラウザがクラッシュ(エラーコード5)する再発への対策 — 端末保存の間引き</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">pullでappDataが更新されるたびに写真込みの巨大JSONを全量JSON.stringifyしてlocalStorageへ保存しており、数秒おきの直列化によるGC負荷が長時間で蓄積しレンダラークラッシュを誘発(8/30のメタ先読み対策後も、保存側の負荷が残っていた)。</span><span class=\"lb\">対処</span><span class=\"tx\">ローカル編集は従来どおり即保存のまま、pull由来の端末保存だけ10秒に1回へ間引き(クラウドが正のため控えの鮮度低下は無害)。ビルド+E2E9件PASS確認の上デプロイ。経過観察: 発生端末で?syncdebug=1を外した通常URLでも再発するかを確認。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ff88214</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"サイドバーのホームに未読なしでも1が常時表示(江古田)。お知らせ母集合のズレを一覧と統一。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-09-02</span></div>\n      <p class=\"title\">未読が無いのにサイドバー「ホーム」に1が表示され続ける(江古田店で報告)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">サイドバーの未読数(_homeUnreadCount)の運営お知らせ分が、ホームの一覧(本部+ライブ更新+組み込みを重複排除→日付降順→上位50件)と別の母集合(ライブ抜き・50件制限なし)で計算されていた。お知らせ総数が50件を超えると、一覧から溢れた古い組み込み告知が「画面から読む手段が無いのに未読として数え続けられる」状態になり、既読にしていなかった店舗で1が固定表示された。</span><span class=\"lb\">対処</span><span class=\"tx\">バッジの母集合を一覧と完全に同一へ統一(同じ重複排除・降順・50件制限・isNoticeRead基準)。devUpdateNotes(ライブ更新)定義後に計算を移動。ホームのお知らせで「新着なし」ならバッジも0になる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a6e5dab</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"個別運動×でも割当ありだと○表示。CI初回の単体テストが検出した実バグ。E2E基盤の初回赤も修正。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-09-02</span></div>\n      <p class=\"title\">連絡帳向け表示: 個別運動が「×(実施しなかった)」でも○と表示される — CI初回実行の単体テストが検出</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">resolveIndividualExerciseValueのcircleモードが、項目割当(itemId)がある枠は×でも○を返していた。既存の単体テスト(logic.test.js)は正しい仕様(×→非表示)を主張していたが、ローカルにnode環境が無くこれまで一度も実行されていなかった。E2E基盤構築で初めてCIが回り検出。</span><span class=\"lb\">対処</span><span class=\"tx\">×/✕/xは割当の有無に関わらず非表示(null)へ修正(空欄/ーは従来どおり割当あり=規定値実施の○を維持)。単体テスト15件PASS。あわせてCI初回赤の他要因も修正: vitestの対象をsrcに限定(e2e/の誤検出防止)・Supabase未設定時の起動ブロックにVITE_E2E_DEMO=1(CI専用)例外を追加しローカルモードで画面テスト可能に・CIにwebkit(iPad)取得を追加。手元検証でchromium/iPadとも9件全PASS。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a6e5dab</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"システム\" data-text=\"自動E2Eテスト基盤(Playwright+GitHub Actions・ローカルモード・毎push実行)。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">システム</span><span class=\"date tnum\">2026-09-01</span></div>\n      <p class=\"title\">自動E2Eテスト基盤 — pushのたびにCIでブラウザ操作テストを無人実行(Playwright+GitHub Actions)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">.github/workflows/e2e.yml: push(stable-rebuild)ごとに vitest単体テスト→Supabase環境変数なしでビルド(=ローカルモード・ログイン不要・実データゼロ)→vite preview起動→Playwrightスモーク実行。テスト内容(第1弾): 起動白画面/未捕捉エラー検知・主要6画面(提供記録/連絡帳/日誌/利用者マスタ/ケアマネ/各種設定)の遷移クラッシュ検知・日誌AM/PM切替・ケアマネ追加ポップアップ開閉。Chrome+iPad横持ちの2プロファイル。失敗時はHTMLレポート保存+GitHub通知メール。今後テスト項目一覧の画面操作系を段階的に自動化しスモークの大半を毎デプロイ自動に。手動で残るのは同期異常系(2端末/通信断)と実機系(印刷/FAX/実メール)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6263a31</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"同期\" data-text=\"起動2段階取得: 直近75日を先行表示・全量は裏で統合。データ増加への恒久耐性。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-01</span></div>\n      <p class=\"title\">起動(再読み込み)を2段階取得に — 直近75日分を先に表示し、過去分は裏で統合</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">fetchTicketRecordsRecent(rec_date>=今日-75日・最大5000件)を新設し、boot冒頭で直近分を取得→applyRows(項目時刻つき冪等マージ)で即反映→操作可(オーバーレイ解除)。その後従来の全量取得(1970〜)で過去分を統合(直近分はマージで保持)。「再読み込み直後の空欄時間」への恒久対策で、記録が何年分に増えても初期表示の待ちは直近分の件数(店舗あたり数百行)で一定。直近先行取得の失敗は全量取得でリカバリーされ致命的でない。将来の課題(V3候補): 全量の裏取得も月別オンデマンド化すれば通信量も一定化できる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8331fbf</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"同期\" data-text=\"再読み込み直後に提供記録が空欄→数秒後復活(容量超過店舗の軽量保存が記録を丸ごと除外)。直近45日保持+オーバーレイ20秒。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-01</span></div>\n      <p class=\"title\">再読み込み直後に提供記録が全欄空→数秒後に復活(扇橋店・容量超過時の軽量保存が原因)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">localStorage容量超過の店舗は軽量保存(persist-slim)で提供記録を丸ごと除外していたため、再読み込みのたびに boot-merge prev:0 = 手元0件で画面が構築され、テーブル全量(997行)の取得完了まで空欄。読込中オーバーレイの保険タイマー(8秒)が取得より先に切れ、空欄のまま操作できてしまっていた(「消えた」誤解と危険入力の温床。同期ログのrows-apply連発の見え方も再読み込み+全量再取得の繰り返しによるもので、受信マージは冪等でデータ影響なし)。</span><span class=\"lb\">対処</span><span class=\"tx\">①軽量保存でも直近45日(上限1200行)の提供記録を保持(容量に入らない場合のみ従来の記録なし版へ段階フォールバック)→再読み込み後すぐ当月画面を表示。②オーバーレイの保険を20秒に延長(正常時はtable-initial完了で即時消える)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4e63be3</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"同期\" data-text=\"rows-apply診断強化(行id・サーバー更新時刻)。同一行受信連発の調査用。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-01</span></div>\n      <p class=\"title\">同期ログ診断強化: rows-applyに行idとサーバー更新時刻を記録(受信連発の特定用)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">店舗報告「1箇所編集のたびにrows-apply n:1が同一秒に多数」の調査用。rows-applyは受信反映ログで、反映は項目時刻つき冪等マージのためデータ影響なし(無駄な通信の可能性のみ)。原因特定のため先頭行のid末尾14桁とサーバーupdated_at時刻をログに追加。次回発生時のログで「同一行の連続受信(=どこかの端末の再送ループ)」か「複数行の正常受信」かを判別する。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0fcd298</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"扇橋9/1午前のマシン運動記録消失: 未送信保留行が非永続で再読み込みにより喪失。localStorage退避+復元再送で恒久対策。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"tag crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-01</span></div>\n      <p class=\"title\">通信不良時の未送信入力が再読み込みで失われる(扇橋9/1午前のマシン運動記録消失)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">調査: クラウド(ticket_records)を精査した結果、7〜8月は全営業日の運動入力が完全に残存。9/1のみ午前入力の大半が未着で、各行の exercises 刻印は14:24〜14:40(午後の別入力)のみ。書込経路(diffRecordRows→RPC upsert_ticket_records)はキー単位部分送信+サーバー統合で他端末の値を潰さない設計のため、消えたのではなく「届いていない」。送信失敗の自動再送キュー(_pendingRows)がメモリ上のみで、失敗保留中の再読み込み/タブ強制終了(iPadのメモリ回収)で未送信入力が完全に失われる穴だった。</span><span class=\"lb\">対処</span><span class=\"tx\">保留行を失敗時に localStorage(tsumugiPendingTicketRows_v1・最大500行)へ退避し、起動時に restorePendingTicketRows で復元→即再送(診断ログ pending-rows-restored)。送信成功時はキューを掃除。9/1午前分は復旧不能のため店舗で再入力を依頼(まばらに残存・不足分のみ)。あわせて調査で判明した副知見: 扇橋の①バイクは6月にID重複→旧削除の形跡があるが7月以降は新IDで一貫しており実害なし。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5b76a82</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"システム\" data-text=\"テスト体制整備: 自動テストランナー・テスト項目一覧(正常/準正常/異常×16分類)・運用ルール。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">システム</span><span class=\"date tnum\">2026-09-01</span></div>\n      <p class=\"title\">テスト体制の整備 — 自動テストランナー+テスト項目一覧(約70項目)+定期実施ルール</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①scripts/run_tests.py新設(毎デプロイの締めで実行): 括弧バランス・競合マーカー・update-notes整合(version/一意id/prompt)・台帳整合(総件数=記事数・内訳合計)・実利用者データのコミット禁止(restore/まるっとLIFE)・本番生存確認(トップ/お知らせ/台帳API=401許容)・デプロイ完了確認(--deployed)。初回実行14項目ALL PASS。②「つむぎ テスト項目一覧」ノート新設(Obsidian第4ノート・NotebookLM同期対象): 同期系/提供記録/日誌/マスタ/モニタリング/計画書/アカウント/ケアマネ自動化/印刷/分析/運用/外部連携/セキュリティ/性能の16分類×正常系・準正常系・異常系で約70項目。運用ルール=項目は機能廃止まで削除しない(回帰テスト標準)・毎デプロイ自動/月次スモーク26項目(扇橋)/四半期全量/新機能は項目追加後にスイッチON・厳しさは厳しめ(同期系とアカウント系は異常系必須)。③導入窓口=各店舗の管理者を計画書第4版に明記。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">61326b2</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"ケアマネ\" data-text=\"ケアマネ閲覧の自動化: 担当割当への閲覧アカウント自動同期エンジン(V1目玉)。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">ケアマネ</span><span class=\"date tnum\">2026-09-01</span></div>\n      <p class=\"title\">ケアマネ閲覧の自動化 — 1回の登録で担当利用者を自動閲覧・担当変更で自動切替(V1組込み)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">スタッフアプリ内の同期エンジンが、利用者マスタの担当(事業所+氏名の正規化一致)と担当者マスタの変化を署名検知(5秒デバウンス)し、登録済みケアマネの利用者別閲覧アカウントを自動同期する。仕組み: family_accountsをメール+パスワードハッシュでグループ化(=リンクログイン単位)→担当者マスタへ特定(メール一致優先・氏名包含一致が1名のみの場合)→あるべき利用者集合(退所済み除外・休止含む)と比較し、担当外れは停止(deleted_atソフト削除・supabaseDeleteFamilyAccountの物理削除とは別経路)、新担当は停止中の復活を優先しなければハッシュ複製で新規作成(username=基点-p利用者id・ログインはリンク機構が束ねるため非表示)。特定できないアカウントは一切触らない安全装置。supabase.jsにsupabaseListCmAccountsAll/supabaseInsertCmAccount/supabaseSetFamilyAccountDeletedを新設。ケアマネ画面の登録済み担当者に「閲覧は担当割当に自動同期」を表示。扇橋店で検証後、V1(10/1)に同梱。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6469162</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"システム\" data-text=\"更新バナーの表示範囲制御(prompt: all/silent/店舗限定)。V1/V2運用の前提整備。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">システム</span><span class=\"date tnum\">2026-09-01</span></div>\n      <p class=\"title\">更新バナーの表示範囲を制御(全店/無音/店舗限定) — V2先行デプロイで他店に通知を出さない</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">update-notes.json にトップレベル \"prompt\" を追加: 'all'(既定・全店にバナー) / 'silent'(バナーなし・タブ背景化時の自動リロードだけで静かに配信) / [\"storeId\",...](指定店舗のみバナー)。V1/V2を1本のコード+店舗フラグで運用する際、扇橋だけのV2先行デプロイで他店に「新しいバージョンがあります」を出さないための仕組み。運用ルール: 扇橋向けデプロイは prompt を silent か扇橋storeIdに、全店に関わる修正(同期変更含む)は必ず all にする。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c9e0582</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"システム\" data-text=\"Brevo APIキーの2ヶ月おき自動キープアライブメール(Vercel Cron)。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">システム</span><span class=\"date tnum\">2026-09-01</span></div>\n      <p class=\"title\">Brevo APIキーの自動キープアライブ(2ヶ月おきのテストメール自動送信)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">BrevoがAPIキーを「3ヶ月未使用」で自動非アクティブ化する対策(2026-09-01に警告メールあり・当日のテスト送信で使用実績を回復済み)。api/brevo-keepalive.js新設+vercel.jsonのcronsで奇数月1日06:00(JST)に本部メール(BREVO_KEEPALIVE_EMAILで変更可・既定honbu@ones-style.co.jp)へ「メール送信の定期テスト(自動)」を送信し、招待/PW再設定メールの生存確認と使用実績を兼ねる。CRON_SECRET設定時は外部からの手動実行を拒否。デプロイ後の手動実行で送信成功を確認済み。アプリ本体の変更はなし(今すぐ更新は不要)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">92c2ea3</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"分析\" data-text=\"稼働カードの休業を日数表示・自己リセットのID+メール二重確認・ログイン画面サポート案内の文字色修正。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-09-01</span></div>\n      <p class=\"title\">稼働カードの休業を日数表示・パスワード自己リセットをID+メールの二重確認に・ログイン画面の文字色修正</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①分析(稼働)の内訳チップ「休業」を、提供記録の休業件数(利用者数依存で0件になりがち)から各種設定の休業日数(kyugyoDays+半日0.5換算)に変更し「N日」表示に。②api/family-reset request にemail必須化: ログインIDと登録メールの両方一致時のみコード送信(不一致・不存在でも応答同一の列挙対策は維持)。ログイン画面のUIにメール入力欄を追加し案内文を更新。③ログイン画面下部のサポート案内(白字・薄緑背景で不可読)を白パネル+濃色テキスト+緑リンクに変更。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">41f333c</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"アカウント\" data-text=\"パスワードのメール自己リセット(10分有効・5回制限・登録メール宛のみ)。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">アカウント</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">パスワードのメール自己リセット(家族/本人/ケアマネがログイン画面から自分で再設定)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">api/family-reset.js新設(SERVICE_ROLE使用・admin-resetと同方式)。request: usernameからアカウント特定→登録メール宛にのみ6桁コード送信(宛先入力不可)。コードのsha256を店舗app_stateのsystemSettings.familyPwResetsに保存(有効10分・試行5回で無効化・ID不存在でも同一応答=列挙対策)。reset: コード照合→password_hash更新+同メール+同旧ハッシュのリンクアカウントも一括更新(複数利用者切替を維持)。ログイン画面に「パスワードをお忘れですか？」→ID入力→コード+新PW(英数6文字以上)の2ステップUI(送信先はマスク表示)。ご利用ガイドFAQも自己リセット案内へ更新。有効期限/試行回数は店舗決定(2026-08-31)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">241616a</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"分析\" data-text=\"稼働率を定員×2コマ×営業日の枠数ベースへ刷新・休業日除外・半日休業対応。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">分析(稼働): 稼働率を定員ベース(定員×AM/PM2コマ×営業日)へ刷新・休業日除外・半日休業対応</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">業界標準「稼働率=延べ利用者数÷(営業日数×定員)」の半日型版として、稼働率=延べ利用コマ数÷(定員×営業コマ数)に刷新(1営業日=AM+PMの2コマ・1日利用=2コマ換算・振替は出席扱い)。定員(capacity)と定休日(closedDays)は各店舗の設定から自動取得し、店舗ごとの週稼働日数/定員の違いに自動対応。休業日(各種設定)は稼働日数から除外し「休業日N日」を表示、当月は今日までで算出。従来の予定比は「出席率」として併記。月別複合グラフ・前月比/前期比/前年比も定員ベース+年考慮に統一。枠数の内訳(定員×コマ・営業日数)をカードに表示。半日休業: 休業日設定に1日/午前のみ/午後のみを追加し、稼働率は該当1コマのみ除外・日誌の休業連動(_dayIsKyugyo)も該当時間帯のみ・日誌バッジは全日休業のみ非表示。提供記録の休業自動連動は従来どおり全日休業のみ。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">241616a</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"アカウント\" data-text=\"家族画面のパスワード変更機能・PW再設定の登録メール自動送信(api/send-password)。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">アカウント</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">家族/ケアマネ画面に「パスワードの変更」・PW再設定の新ログイン情報をメール自動送信</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①家族ポータルの登録者基本情報タブ下部に「パスワードの変更」を新設。現在のパスワードをsupabaseLoginFamilyで検証し、同メール+同パスワードハッシュのリンク全アカウントをまとめて更新(片方だけ変えると複数利用者の切替リンクが壊れるため)。ローカルfamilyAccountsにも反映。英字+数字6文字以上・現在と同一は不可。②api/send-password.js新設(Brevo・send-inviteと同環境変数): 事業所の「PW再設定」確定後、登録メールがあれば確認の上で新しいログインID/パスワード+ログインページボタン+「ログイン後にご自身のパスワードへ変更を」の案内を自動送信。送信失敗時は印刷/口頭案内へフォールバック。運用フロー: PW再設定→メール自動送信→本人ログイン→パスワードの変更。メールリンク式の自己リセットは引き続き実装予定(未来の修正点)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e50aa41</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"アカウント\" data-text=\"家族/本人/ケアマネのパスワード再設定(PW再設定ボタン)・事業所重複時の担当者追加誘導。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">アカウント</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">パスワード再設定(事業所発行)・ケアマネ事業所重複時に担当者追加へスムーズ誘導</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①利用者マスタの「アカウント管理」各行に「PW再設定」ボタンを新設。仮パスワード自動生成(英字4+数字4・編集可・英数6文字以上を検証)→確認→supabaseUpdateFamilyAccountでpassword_hash更新+ローカルfamilyAccountsにも反映(ログイン情報シート再印刷対応)。パスワード欄のツールチップとご利用ガイドFAQの「ログイン画面から再設定できます」という誤案内を実手順(事業所へ連絡→事業所で発行)に修正。メールによる自己リセットは今後の課題として未来の修正点に記載。②ケアマネ事業所の追加で同名が既登録の場合、行き止まりのアラートをやめ「この事業所で担当者を追加しますか？」の確認→担当者追加モーダル(事業所を初期選択)へ誘導。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">59ac797</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"家族向け\" data-text=\"スマホの家族画面で期間ドロップダウンが画面左に半分はみ出して見えない。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">家族向け</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">家族画面(スマホ): 期間の選択メニューが画面左に半分はみ出して見えない</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">期間パネルがボタン基準のposition:absolute right:0で、スマホではボタンが画面左寄りに折り返されるためパネルが左へはみ出していた。</span><span class=\"lb\">対処</span><span class=\"tx\">開いた時にボタンのgetBoundingClientRectから位置を計算し、position:fixedで画面内(左右8px余白・幅190px)に収まる座標に表示するよう変更。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">59ac797</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ケアマネ\" data-text=\"事業所/担当者の追加をポップアップ化・同名事業所と同一事業所内の同姓同名担当者の重複登録防止。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">ケアマネ</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">事業所/担当者の追加をポップアップ化・重複登録防止(同名事業所/同一事業所内の同姓同名)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①常設の追加フォームを撤去し「事業所を追加」「担当者を追加」ボタン→モーダル登録に変更(担当者モーダルは選択中の事業所を初期値・氏名は姓/名分割入力・ふりがな/直通電話/メール欄つき)。一覧の表示領域が広がった。②重複防止: 事業所は同名(空白無視の正規化比較)を登録不可。担当者は「同一事業所内の同姓同名」のみ登録不可とし、別事業所の同姓同名は別人として許容。真の同姓同名はデータ上の識別キーが事業所+氏名のため、名前に区別文字を付けて登録するようアラートで案内(例: 鈴木 一郎(2))。追加経路は_addedAt刻印(墓石復活許可)を維持。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1ba2873</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"ケアマネ\" data-text=\"ケアマネ事業所/担当者の削除がunionマージで復活・登録済みケアマネが閲覧登録なしと誤表示。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ケアマネ</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">ケアマネ事業所/担当者の削除が復活する問題・登録済みケアマネの「閲覧登録なし」誤表示を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">(1)cmOffices/careManagersは両端末の追加を保持する純unionマージのため、片側で削除してもクラウド/他端末の同名項目が必ず復活していた。(2)登録状況バッジが端末ローカルのfamilyAccountsのみ参照しており、別端末・家族側デバイスで登録されたケアマネアカウント(Supabase側)が見えず「閲覧登録なし」になっていた。</span><span class=\"lb\">対処</span><span class=\"tx\">(1)systemSettings.cmTombstones(キー=off|事業所名/cm|事業所|氏名、値=削除時刻)を新設し最大値unionで統合、墓石のある項目はunion結果から除外。再追加時は_addedAtを刻印し墓石より新しければ復活許可。削除・一括削除(事業所+配下担当者)・改名(旧キー墓石+新キー刻印)・追加・CSV取込・ケアマネ登録autoaddの全経路に適用。旧版端末が混在する間は復活が再発しうるため全端末更新が前提。(2)supabaseListFamilyAccountsForStore新設(store_idで一括取得)+氏名の包含一致(2文字以上)許容で照合。表示のみで閲覧権限には影響しない。既登録者の再登録は不要。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4c0aa22</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ケアマネ\" data-text=\"ケアマネ登録の続柄一本化・利用者マスタのCMアカウント欄撤去・ケアマネ画面レイアウト調整。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">ケアマネ</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">ケアマネ登録を担当者招待に一本化(続柄自動確定)・利用者マスタのアカウント欄撤去・画面幅調整</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①家族登録フォームの続柄から「ケアマネージャー」を除外。ケアマネ画面の招待メールから開いた登録フォームは続柄=ケアマネージャーで自動確定(固定表示・変更不可)。スタッフ側の家族メール招待の続柄例からもケアマネを外し案内文を追記。②利用者マスタの「登録されているケアマネ(アカウント)」表示を撤去し、ケアマネ事業所・担当者画面へ一本化(案内文のみ残置)。③ケアマネ画面: コンテンツ幅をmax-w-6xlに拡大・一覧の高さを62vhに・2カラムをitems-start化して右カラムの空白伸びを解消。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4c0aa22</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"ケアマネ\" data-text=\"ケアマネ事業所・担当者のサイドバー移設・担当者メール欄・招待メール・登録状況表示。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">ケアマネ</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">ケアマネ事業所・担当者をサイドバーへ完全移設・担当者ごとの招待メールと登録状況表示</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①サイドバー(利用者マスタ管理の下)に「ケアマネ事業所・担当者」を新設し、各種設定のタブから完全移設。SettingsViewにcmOnlyモードを追加して同一コンポーネントを再利用(「消える問題」対策の同期追従・即保存persistCmを共有するためタブ抽出はしない)。②担当者マスタにメールアドレス欄(追加フォーム/編集モーダル)。③担当者ごとに「招待メール」: 既存のapi/send-invite(Brevo)を流用し、担当利用者(退所済み除く)の1人目に紐付く招待を発行。招待レコードにcmOffice/cmNameを付与して担当者と追跡可能に。メール未登録ならその場で入力→マスタへ保存。④登録状況バッジ: 登録済み(kind=caremanagerのアカウントとメールまたは氏名+事業所一致・最終ログイン表示)/招待済み(未使用・期限内のcm招待あり)/閲覧登録なし+担当利用者N名(氏名3名まで表示)。今後: 担当者単位アカウントで1回登録→担当利用者を自動閲覧・担当変更で自動失効(Supabase側精査後に実装予定)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6e18a65</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"日誌\" data-text=\"日誌シート内のチェック/到着出発セルがタップに反応しない。二重zoomと毎レンダー再マウントの複合。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"tag crit\">重大</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">日誌シート内がタップに反応しない(担当職員/送迎者/記録者のチェック・到着/出発の時間入力)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">複合原因。(1)アプリ全体のzoom(横幅1100px未満でcontentScale)と日誌シート個別のzoom(diaryViewScale)が二重に掛かり、iPad Safariの既知不具合でタップ座標とヒット判定がズレてシート内のonClickが発火しない。マスタ/ホーム/連絡帳はzoom例外指定で無事、日誌だけ例外に入っていなかった。(2)DiarySheet/StaffBox/DriverRow/CBがDailyLogView内で毎レンダー定義され&lt;Comp/&gt;形式で描画されており、再レンダーごとにDOMがアンマウント→再マウント。タップ(touchstart→click合成)の途中でDOMが差し替わるとclickが取りこぼされる。800ms間隔の幅計測や4秒同期が再マウントを常時誘発していた。</span><span class=\"lb\">対処</span><span class=\"tx\">(1)currentView===diary を全体zoomの例外リストに追加(日誌はシート側のdiaryViewScaleが自前で拡縮するため二重zoom不要)。(2)DiarySheet(3箇所)/StaffBox(5箇所)/DriverRow(2箇所)/CB(4箇所)をTimeKeypadModal等と同じ関数呼び出し描画 {Comp({...})} に変更し再マウントを根絶(全て内部hooksなしを確認・CarCellは表示専用のため対象外)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">00e4ff3</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"名簿の並び替え/絞り込みをポップアップ化・基本利用日の曜日×AM/PM絞り込み。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">名簿の並び替え/絞り込みをポップアップ2ボタンに整理・基本利用日(曜日×AM/PM)絞り込みを追加</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">名簿の並び替えチップ8個の列を「並び替え: ◯◯↑」「絞り込み▾」の2ボタンに集約(モニタリング画面と同型のポップアップ)。並び替えは名前順/基本利用日/通所歴/介護度/事業所/誕生月/保険更新/年齢+昇順/降順。絞り込みは月曜起点の曜日×AM/PMを複数選択でき、1日利用の方はAM/PMどちらの選択でも該当。適用中はボタンに「月AM・木PM」等を表示し、各利用者の名前の下にも利用日サブ表示が付く。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">00e4ff3</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"担当職員の自動チェックで送迎者/記録者に他の職員が出ない・時間テンキーがPCキーボードで入力できない。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">日誌: 担当職員の自動チェック廃止(他の職員が選べない問題)・到着/出発時間のPCキーボード入力対応</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">スタッフ切替のアクティブ記録者を担当職員へ自動チェックしていたため、送迎者/記録者候補を「担当職員チェック者のみ」に絞る改善(835bd1f)と組み合わさると候補が自動チェックの1人に固定され、他の職員を選べなくなった。また到着/出発のテンキーモーダルは画面ボタン専用で、PCの物理テンキー入力は無反応(1件目は画面入力で表示され、2件目をキーボードで打つと表示されないように見える)。</span><span class=\"lb\">対処</span><span class=\"tx\">担当職員への自動チェックを廃止(新規ログ読込時・スタッフ切替時とも)。記録者欄のみ従来どおり自動チェックし、切替時も記録者チェックだけ付け替え(手動チェックには触らない)。テンキーモーダル表示中は window keydown で 数字=入力・Backspace/Delete=削除・Enter=決定・Esc=キャンセル を受け付け、モーダル内に案内文を追加。ハンドラは毎render付け替えで最新stateを参照。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">36169a6</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"日誌\" data-text=\"要確認の迎え/送りタップで送迎車割り当てを直接開く・利用者マスタ並び替えに基本利用日。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">要確認の迎え/送りタップで送迎車割り当てを直接開く・利用者マスタ並び替えに「基本利用日」追加</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①日誌の要確認バッジのうち「迎え」「送り」はスクロールではなく送迎車割り当てモーダルを直接開く(送迎時間/記録者/管理者確認は従来どおり該当箇所へスクロール+ハイライト)。②利用者マスタ管理の並び替えに「基本利用日」を追加。月曜起点で最初の利用曜日が早い順(同曜日はAM→1日→PM・未設定は末尾・同順は名前順)に並び、選択中は名前の下に「月AM・木PM」形式のサブ表示。既存のモニタリング画面の曜日並び替えと同じ月曜起点ルールで統一。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">36169a6</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"日誌\" data-text=\"要確認バッジのジャンプ・出勤者のみの送迎者/記録者候補・サイドバー日誌バッジ。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">日誌: 要確認バッジのジャンプ・送迎者/記録者は出勤者のみ・サイドバーに未完了バッジ</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①要確認バッジをボタン化し、迎え/送り→利用者テーブル・送迎時間→送迎テーブル・記録者/管理者確認→各枠へscrollIntoView+1.8秒のオレンジ枠ハイライト(アンカーidは編集画面インスタンスのみに付与し印刷用と重複しない)。②DriverRow/記録者欄の候補をlog.staffでチェック済みの職員に絞る(既チェックの送迎者・記録者は表示維持・担当職員が全員未チェックなら従来どおり全員表示。配列filterのみで負荷なし)。③App側にdiaryTodayBadge(useMemo)を追加し、今日のAM/PMいずれかが未入力または未確認項目ありならサイドバー「日誌」に赤バッジ1(diaryPendingItems共用・休業日/定休日は非表示)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">835bd1f</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"モニタリング\" data-text=\"コンパクト表示(各項目1行・クリック展開)で1画面4〜6人。並び替え基準のサブ表示。ボタン形状統一。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">モニタリング</span><span class=\"date tnum\">2026-08-30</span></div>\n      <p class=\"title\">モニタリング一覧のコンパクト表示(既定)と並び替え基準のサブ表示</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">「1画面2人は少ない」への対応。既定はコンパクト表示=①〜⑤をラベル+プルダウン+本文1行省略で表示(monExpanded Set・本文クリックで展開+編集開始・名前列に▼展開/▲たたむボタン)。展開時は従来の全文+コピー+textarea編集。並び替えが事業所/曜日のときは名前の下にその値を表示。「印刷/PDF(ケアマネ宛)」→「印刷/PDF」改名・選択チップ/一括ボタンを絞り込みボタンと同形状(角丸10)に統一。上限到達alertの「一括作成(既定)」言及も削除。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">edc64ae</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"長時間表示でメモリクラッシュ(コード5)。毎4秒フル取得+全再構築が原因。軽量メタチェック化。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-30</span></div>\n      <p class=\"title\">長時間表示でエラーコード5(メモリ不足クラッシュ)になる問題の対策</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">4秒ポーリング(checkAndPull)が変化チェックの前に毎回app_state全体(5MB超)を取得・JSONパースしていた。さらに「取りこぼし対策の強制反映」の閾値が4秒だったため、updated_atが同じでもほぼ毎回setAppDataで全アプリデータを再構築しており、ヒープの断片化・GC負荷が蓄積して数時間でWebViewがクラッシュしていた(localStorage容量超過の端末=データ大の端末で顕著)。</span><span class=\"lb\">対応</span><span class=\"tx\">①supabaseLoadStateMetaForStore(updated_atのみのselect)を新設し、前回反映と同じなら フル取得もsetAppDataもスキップ(初回ロード/強制pull時は従来どおり)。②強制全再構築の安全網を4秒→60秒に。他端末の変更はupdated_at差分で従来どおり4〜8秒で反映。提供記録テーブルの増分受信(since方式)は別経路で影響なし。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">27f98c3</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"モニタリング\" data-text=\"画面刷新: ポップアップ化・列幅縮小・行操作は確定のみ・既定文の自動表示廃止・AI要約改善(運動の変化優先)。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">モニタリング</span><span class=\"date tnum\">2026-08-30</span></div>\n      <p class=\"title\">モニタリング画面刷新: ヘッダ1行化・列幅最適化・既定文の自動表示廃止・AI要約改善</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①題名行を廃止し、絞り込み(氏名/状態/曜日)と並び替え(基準+昇降順)をポップアップ(monFilterPop/monSortPop)に格納。ヘッダ1行に月選択/プレビュー/保存も統合。②名前列160→96px・操作列150→96px。③行操作は確定トグルのみ(AI/全文コピー/FAXは上部一括)。④getOrInitSheetForを空テンプレ化し、既定文生成はbuildDefaultSheetForへ分離(AI下書き・一括作成(既定)・空のまま確定の明示操作時のみ使用)。「自動で入っていると誰が書いたか分からない」問題の解消。⑤AIプロンプト: 計画目標未設定時の断り書き禁止を明記・運動の量の変化検出(_exVals: 前月→今月の値差「バイク3分→5分」)を追加しデータとして渡し、血圧偏重を避け運動変化を最優先で言及するルールを追加。⑥確定を名前列に統合し操作列廃止。⑦一括ボタンを「AI下書き/印刷・PDF(ケアマネ宛)/自動FAX」に整理(個人ファイルに保存は自動保存化で廃止)・選択チップ同サイズ化。⑧全画面共通: プレビューの自動印刷タブ起動を廃止(画面確認→印刷ボタンで移動)・プレビューのページを影付きで1枚ずつ分離表示。⑨モニタリング表の結果列130px化で語中改行解消。⑩選択チップ+一括ボタン行をヘッダ行へ、確定サマリ/締切とAI残数も1行に統合(3880ca0, 5983eee)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">84bd56e</span> <span class=\"cid\">2f67979</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"個人ファイル\" data-text=\"初回報告バッジが数秒で復活。完了エントリにidが無くmergeByIdで破棄。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">個人ファイル</span><span class=\"date tnum\">2026-08-30</span></div>\n      <p class=\"title\">初回報告を完了してもバッジが数秒で復活する問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">保存ボタン経路のinitialReports完了エントリに<b>idが無かった</b>。クラウドマージ(mergeById)はid無しの行をローカル/クラウド両側で破棄するため、保存直後のpull(4秒)で完了記録が消え、バッジ判定(initialReports未登録)が復活していた。FAX送付経路(initrep_...)はid有りで無事だった。</span><span class=\"lb\">対応</span><span class=\"tx\">完了エントリにid(ir_利用者ID)を付与(_savedAtは保存時の自動刻印で付く)。添付での完了も添付ファイルと完了エントリを1回のonSaveで原子的に保存(2回に分けると後の保存が先の内容を巻き戻すため)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">cb748ac</span> <span class=\"cid\">7a4d0dd</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"個人ファイル\" data-text=\"初回報告の2択フロー・バッジからのジャンプ・完了後表示・フォルダごと添付。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">個人ファイル</span><span class=\"date tnum\">2026-08-30</span></div>\n      <p class=\"title\">初回報告の選択式フロー(手入力/書類添付)・バッジジャンプ・フォルダごと添付</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①名簿の「初回報告」バッジをクリックで個人ファイル(cat_7)を直接オープン(stopPropagationで行クリックと分離)。②タブは状態依存の3画面に再構成: 未完了=「手入力で作成/書類を添付して完了」の2択 → 完了後=手入力なら報告書内容の読み取り表示(保存済みデータで印刷/PDF・編集ボタン)、添付ならファイル一覧への案内+「手入力の報告書も作成する」。③ファイル追加はボタン1つに統合し、ファイル一覧の枠をドラッグ&ドロップ対応に(ファイル/フォルダ両対応・webkitGetAsEntryで再帰収集・画像/PDFのみ登録し非対応形式は件数案内でスキップ。1つのダイアログで両方選べないブラウザ制約の回避)。手入力フォーム中は保存のみ表示・選択画面/フォーム中はファイル欄非表示。あわせて保存時にid無し行を検知するno-id-row警告ログを追加し、全書き込み経路のid総点検を実施(初回報告以外は全id有りを確認)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">cb748ac</span> <span class=\"cid\">7a4d0dd</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"同期\" data-text=\"QuotaExceededのpersist-fail連発を抑制。容量超過検知後は軽量保存へ直行。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-30</span></div>\n      <p class=\"title\">ローカル保存の容量超過(QuotaExceededError)の再試行とログ洪水を抑制</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">appDataがlocalStorage上限(約5MB)を超えた端末では、保存のたびに フル→写真分離→軽量版 と巨大JSONのstringifyを3回行ってから軽量版で成功しており、persist-fail/persist-slimログが保存ごとに出続けていた(クラウド同期・テーブル取得は正常で実害なし。テーブル方式では提供記録はテーブルが正)。</span><span class=\"lb\">対応</span><span class=\"tx\">一度QuotaExceededを検知したらpersistQuotaUntilRefに10分の期限を記録し、その間は軽量版(提供記録・写真除外)へ直行。10分ごとにフル保存を再挑戦して容量が空けば自動復帰。CPU負荷とログ洪水を解消。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5cc1b51</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"気分ボタンが長押しで反応しない問題。pointerup確定のlongPressTapPropsを導入。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">気分入力: 長押しでもタップとして反応するように</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">利用者が気分ボタンを強く長押しすると、ブラウザの長押しメニュー(コンテキストメニュー)や文字選択が働き、clickイベントが発火せず「押したのに反応しない」となっていた(特にAndroid/iPadで発生)。</span><span class=\"lb\">対応</span><span class=\"tx\">共通ヘルパーlongPressTapPropsを新設: pointerup(指を離した時)で確定・contextmenu抑止・touch-callout/user-select無効・12px以上の移動はスクロール扱いで無視・直後のclickは時刻ガード(500ms)で二重実行防止(再レンダー跨ぎでも安全なようモジュール変数で判定)。気分/理由/戻る/決定の4種のボタンに適用。他画面のボタンにも転用可能な汎用実装。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6b1cbc7</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"保存して切替/移動で適用日モーダルが出ない根因(flushLP素通り)を修正。キャンセル追加・幅拡大。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">「保存して切替/移動」で運動メニューの適用日モーダルが出ない根因を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">saveFnRef(保存して切替/移動・バックグラウンド保存が呼ぶ保存関数)にはsaveMasterInfoではなくflushLP(適用日確認を持たない別の保存関数)が代入されており、前revで入れた「戻り値modalで移動を保留する」仕組みが一度も発動していなかった。</span><span class=\"lb\">対応</span><span class=\"tx\">saveFnRefをラッパー化し、運動メニュー/個別運動に未確定の差分がある場合(自動保存済みのpendingに加え、自動保存前1.5秒以内の直近編集も基準値との差分比較で検知)はsaveMasterInfoへ委譲して適用日モーダルを表示。差分が無ければ従来どおりflushLP。あわせてモーダルをmax-w-xlに拡大しボタンの改行を解消、「キャンセル」(反映せず編集を続ける・保留中の移動/切替は取消)を追加。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3245328</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"本日スケジュールに日誌の未入力/未確認表示。休業日はスタッフ自動チェックなし。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">ホームに日誌の未入力/未確認お知らせ・休業日のスタッフ自動チェック抑止</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">日誌の入力・確認忘れ対策。共通ヘルパーdiaryPendingItems(未入力=null/未確認項目=迎え・送り・送迎時間・記録者・管理者確認)を新設し、ホームの本日のスケジュール先頭に黄色バナーで「午前: 未入力」「午後: 送り・管理者確認 未確認」のように表示(タップで日誌へ・休業日/定休日は非表示)。あわせて休業日・定休日の日誌はスタッフ切替選択者の自動チェック(担当職員/記録者)を付けないように(新規読込時とスタッフ切替時の2経路)。今後: モニタリング/実績の確定期限カウントダウン表示をロードマップに追加。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d8183d7</span> <span class=\"cid\">9ac1d66</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"運動メニュー変更時の画面移動は適用日モーダル直行+確定後自動移動。予定ポップアップ拡大。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">運動メニュー変更中の移動は適用日モーダルへ直行(確定後に自動移動)・予定ポップアップ拡大</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">前revで「未保存確認→保存→適用日モーダル」の2段だったのを、反映日未確定(masterExPendingRef)ならnavigateToが「サービス提供内容の変更を反映」モーダルを直接表示する1段に。移動先はmasterNavAfterExRefに保留し、「過去全て/日付指定」どちらで確定しても自動で移動先へ移る(未保存確認・利用者切替の確認経由も同様)。「破棄して切替」は自動保存済みの新値が残る問題があったため、discardPendingExで旧値を書き戻して実際に破棄されるように修正。ホームの日誌お知らせは1行スリム表示(午前・午後のみ・詳細はツールチップ)に変更。カレンダーの予定確認ポップアップは幅400→560・タイトル23px・ボタン15pxに拡大。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d8183d7</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"運動メニュー変更が画面移動で確認なく保存される問題を修正。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">運動メニュー変更が画面移動の自動保存で「いつから適用」の確認なく確定していた問題</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">運動メニューの変更は自動保存(1.5秒)では値だけ静かに保存し、適用日モーダルは「保存」押下時に出す設計だが、自動保存がdirtyフラグを落とすため、サイドバー移動時のナビゲーションガード(未保存確認)が働かず、モーダルを見ないまま確定していた。</span><span class=\"lb\">対応</span><span class=\"tx\">反映日が未確定の間(_pendingExBaseRefあり)は自動保存後もdirtyを維持。画面移動の「保存」選択時、saveMasterInfoがモーダルを開いた場合は移動を中断してモーダルを表示(saveFnの戻り値=modalで判定)。適用日を確定してから改めて移動する。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0455668</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"カレンダー\" data-text=\"色ラベル編集を保存/キャンセル方式に。予定カードのボタン横一列。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">カレンダー</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">色ラベル編集の下書き+保存/キャンセル化・予定カードのボタン整列</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">色ラベル編集は1文字ごとにクラウド保存されていたのを下書き(labelDraft)に変更し、「保存」で確定・「キャンセル/×/背景タップ」は未保存変更があれば確認してから破棄。予定確認カードは「担当者会議を記録」が本文側、削除/編集/閉じるがフッター側で段違いだったため、1行のフッターに統合(左=記録ボタン・右=削除/編集/閉じる)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0455668</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"カレンダー\" data-text=\"色ラベルの担当者会議/契約/見学を固定化。ボタン名を担当者会議を記録に統一。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">カレンダー</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">色ラベルの固定(担当者会議・契約・見学)と「担当者会議を記録」への名称統一</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">色ラベルの正規化処理を追加し、担当者会議(別名「担会」も吸収)・契約・見学を先頭3件に固定(名前入力disabled+「固定」表示・削除ボタン非表示・色は変更可)。既定ラベルの「面談」は「見学」に変更。担会記録へのジャンプボタンは地域による略称差を踏まえ「担当者会議を記録」に統一(カレンダーのカード/日別リスト/ホームの3箇所)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ef2f09b</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"今すぐ更新の更新中表示・カレンダーから利用者マスタ/担会記録ジャンプ・連絡帳ボタン左端へ。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">今すぐ更新の「更新中…」表示・カレンダーからのジャンプ・連絡帳ボタン位置</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①今すぐ更新は保存→キャッシュ/SW削除→再読込で数秒かかり無反応に見えていたため、押下直後にボタンを「更新中…（そのままお待ちください）」+灰色+disabledに(保存失敗時は元に戻す)。②カレンダー(ScheduleView)にnavigateToを配線し、予定確認カードに「担当者会議記録を入力」(利用者が紐付いた予定ならタイトル不問で必ず表示・tsumugiReopenPFで個人ファイルの担会タブを自動オープン。ホーム側も同条件に統一)を追加(ボタン名は「担会を記録」に短縮・ホーム側も同名に統一)。「利用者マスタを開く」ボタンは利用者名タップと重複のため撤去し、カード/日別リストの利用者名を下線リンク化。日別リストにも「担会を記録」ボタンを追加。③提供記録入力の「連絡帳」ボタンを通常/全画面ヘッダとも左端に移動。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5036d82</span> <span class=\"cid\">f472d65</span> <span class=\"cid\">9276d81</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"今すぐ更新後に更新前の画面へ復帰。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">「今すぐ更新」後に更新前の画面へ自動復帰</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">今すぐ更新のリロード直前にcurrentViewと選択中の利用者IDをsessionStorageへ保存し、起動時のcurrentView初期値で使い捨て復元(5分以内のみ有効)。通常起動は従来どおりホーム。作業中の画面から更新してもホームに飛ばされなくなった。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">888323f</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"個人ファイル\" data-text=\"担会小窓v3: 各行1項目・リサイズつまみ・ボタン大型化。表示内容ポップアップ化+他関係者列。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">個人ファイル</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">担会小窓v3(リサイズつまみ等)と分析個人「表示内容」のポップアップ化</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①小窓の開催日/開始/終了を各1行に(iPadのinput最小幅対策の完全版)。②ピンチはOSの画面全体ズームと競合するため廃止し、右下のリサイズつまみ(pointerイベント・touchAction none)ドラッグで小窓のみ0.7〜1.5倍。Ａ−/Ａ＋ボタンも32px高に大型化。小窓の×は誤タップ防止のため撤去(閉じるのは下部の保存/キャンセル)、全画面フォームの×/キャンセルは変更ありの時に保存確認。③分析個人の閲覧範囲一覧はインライン折りたたみをやめ、ヘッダの利用者名横「表示内容」ボタン→ポップアップに変更。「ケアマネ・他関係者」列を追加(関係者アカウントはケアマネと同表示)。事業所画面のみ表示で、家族/ケアマネ/本人側には出ない。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">27ad211</span> <span class=\"cid\">9a4f8ac</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"個人ファイル\" data-text=\"担会小窓v2: 保存/キャンセル明示・全画面から小窓移行・iPad重なり修正・ピンチ拡大縮小。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">個人ファイル</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">担当者会議フロートメモv2: 明示保存・全画面からの移行・iPad修正・拡大縮小</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①1秒自動保存をやめ「保存/キャンセル」の明示保存型に(未保存はdirty表示+閉じる時confirm。「小窓で記録」発の新規はキャンセルで空記録ごと削除=残骸防止)。②全画面フォームのヘッダに「小窓にする」(入力途中の内容を保存して小窓へ移行。カレンダー→担会記録の経路もフォーム経由のため対応)。③iPadでdate/time inputの固有最小幅により開催日と開始/終了が重なっていたため2行に分離。④ピンチ(2本指)とヘッダＡ−/Ａ＋で0.7〜1.5倍(width+fontSize連動のみで軽量)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">082a590</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"分析\" data-text=\"分析個人に本人/家族/ケアマネの閲覧範囲一覧を追加。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">分析個人: 「ご本人・ご家族・ケアマネにはどこまで表示される？」一覧を追加</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">事業所側の分析個人の上部に折りたたみの一覧表を追加。実装の表示ルール(家族=基本情報/今回の記録/簡易通所率/気分/バイタル/体力測定のみ・本人=同+特記非表示・ケアマネ=事業所と同じフルセット、特記は家族非表示設定を除き家族表示/ケアマネ常時/本人非表示)をそのまま表にした。印刷には含まれない(no-print)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">082a590</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"個人ファイル\" data-text=\"担当者会議のフロートメモ。画面切替でも残る小窓で会議記録を入力。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">個人ファイル</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">担当者会議のフロートメモ(小窓): 他画面を見ながら会議記録を入力</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">担当者会議中に分析個人や提供記録を参照しながら記録したいという要望(iPadのクイックメモ風)。MeetingFloatWidgetをAppルートに常駐させ、windowイベント(tsumugi-meeting-float)で起動。開催日/時間/出席者/開催理由/検討内容を編集でき、1秒デバウンスでpersonalFile.meetingsへ自動保存(閉じる/アンマウント時もflush)。下書きは小窓ローカル状態のため4秒同期の再レンダーで入力が消えない。ドラッグ移動(pointerイベント=タッチ対応)・最小化ピル・portal描画。担会一覧に「小窓で記録」(新規作成+起動)と各記録「小窓」ボタンを追加、起動時は個人ファイルを閉じて画面移動を自由に。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7beae3e</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"利用開始日前の利用者が日誌に載る問題。提供記録入力と同じ日付基準に統一。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-27</span></div>\n      <p class=\"title\">日誌: 利用開始日前(9月開始の方が8月に載る等)の表示を修正・提供記録入力と判定統一</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">日誌の「記録がまだ無い予定者」の抽出が今日時点の利用者情報(scheduleAmPm・表示状態)だけで判定しており、提供記録入力が使う日付基準の共通関数(isPatientActiveOnDate=利用開始/終了日、getScheduleOnDate=その日付時点の基本曜日)を通していなかった。そのため9月開始で登録した利用者が8月の日誌に出席として載っていた。</span><span class=\"lb\">対応</span><span class=\"tx\">日誌の入力行・プレビュー行・送迎コピーの対応付けの3箇所を提供記録入力と同じ共通関数に統一。利用開始日前/終了日後は載らず、後から増回した曜日も過去に遡及しない。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">74c4815</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"休業日が日誌で出席表示・送迎コピーされる問題と稼働日数の休業日未反映を修正。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-27</span></div>\n      <p class=\"title\">休業日の連動: 日誌の休業表示・送迎コピー抑止・稼働日数への反映</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">日誌はticketRecordsと基本曜日だけで行を作っており、各種設定の休業日・定休日・月間スケジュールの「休業」を見ていなかった。そのため休業設定した8/12-14でも利用者が「出席」で表示され、先週分の送迎自動コピーまで実行されていた。分析の稼働日数も「月〜金固定」の計算で休業日・定休日設定を無視していた。</span><span class=\"lb\">対応</span><span class=\"tx\">日誌の行構築(入力・プレビュー共通)に_applyKyugyo(休業日/定休日/シフト休業なら出席・振替→休業。欠席・休止は本人事由なので維持)を追加し、休業日は送迎自動コピー自体をスキップ、シフト休業の利用者もコピー対象外に。稼働日数は定休日設定(closedDays)+休業日(holidays)を除いて計算するよう変更。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">08dc770</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"AM/PM入力済みでも緑丸が付かない問題。送迎コピー未確認が保存でも解消されなかった。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-27</span></div>\n      <p class=\"title\">日誌カレンダー: AM/PM入力済みでも緑丸が付かない問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">カレンダーの緑丸は「送迎自動コピーの未確認(_sougeiPending)が残る日は入力済みに数えない」仕様(8/21)だが、コピー内容が正しく編集不要だった日は個別編集による解除が起きず、未確認が永久に残って緑丸が付かなかった。</span><span class=\"lb\">対応</span><span class=\"tx\">手動保存(保存ボタン)=内容を確認して確定した扱いとし、保存時に未確認フラグを解消。既存の付いていない日は開いて保存し直せば緑になる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">08dc770</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"保険証/負担割合証の更新者記録と未更新警告(30日以内/期限切れ)・件数まとめ。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-26</span></div>\n      <p class=\"title\">期限もの(保険証/負担割合証)の見える化: 更新者の記録と未更新警告</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①appendValueHistoryにby(スタッフ切替の選択者名)を自動記録し、変更履歴に「記入: ◯◯」を表示(保険更新モーダルの手動push2箇所にも追加)。②名簿の期限判定を「当月のみ」→「30日以内(expiring)/期限切れ(expired)」に拡張し、負担割合証(costBurdenTo)も対象化。未来の変更予定・新期間が登録済み(updated)なら警告を出さない。③名簿上部に「更新の確認が必要: 保険証◯名・負担割合証◯名」のまとめバーを表示。チェックリストは作らず名簿の表示だけで完結。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">66f349e</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"介護保険証/負担割合証の未来日更新を変更予定として保存し開始日に自動切替。名簿に予定バッジ。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-26</span></div>\n      <p class=\"title\">介護保険証/負担割合証: 未来の認定開始日は「変更予定」として保存し開始日に自動切替</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">個人ファイルの保険証タブ(saveMaster)は未来の認定開始日でも介護度を即時反映しており、9月からの区分変更を登録すると名簿・帳票が先に新介護度になっていた(関口様の要支援1→9月要支援2で実害)。利用者マスタ側の保険更新モーダルには予約機能があったが、入力起点の保険証タブに無かった。</span><span class=\"lb\">対応</span><span class=\"tx\">開始日が未来かつ介護度/負担割合の値が変わる保存は「変更予定」扱い(現在値は維持・履歴に未来日エントリ・トーストで案内)。既存の起動時自動適用が開始日当日に切替える。名簿に「◯月から◯◯」バッジ、保険証/負担割合証タブに変更予定表示を追加。あわせて負担割合の自動適用ロジックを介護度と同じcostBurdenFrom基準に修正(終了日なしの予約エントリが永久に適用されない穴)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">379b192</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"体温テンキーに35./36./37.クイックボタン。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-26</span></div>\n      <p class=\"title\">体温セルのテンキーに「35./36./37.」クイックボタンを追加</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">提供記録入力で体温セル(temp/temp_AM/temp_PM)を選ぶと、テンキー下部に緑の「35.」「36.」「37.」ボタンを表示。押すと値がその値で置き換わり、続けて下1桁を打つだけで入力完了(例: 36.→5で36.5)。DigitalKeypadに汎用のprefixButtons propを追加して実装(他の項目への転用可)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f04b4ee</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"休み連絡\" data-text=\"カレンダーのバッジを編集済(青)と印刷/PDF済(緑)に区別。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">休み連絡</span><span class=\"date tnum\">2026-08-25</span></div>\n      <p class=\"title\">休み連絡カレンダー: バッジを「編集済」と「印刷済/PDF済」で区別</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">これまで編集済も印刷/PDF済もすべて青「編集済」で表示され、出力したかどうかが分からなかった。編集のみ=青「編集済」、出力済み=緑「印刷済」「PDF済」「印刷・PDF済」に区別し、ヘッダの凡例にも緑を追加。個人ファイル連絡タブの「下書き(編集済・未送付)」表示と合わせて、未出力の休み連絡が一目で分かる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7c6f4cc</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"個人ファイル\" data-text=\"体力測定の一覧印刷。休み連絡の下書き(未送付)表示。タブ列スクロールバー常時表示。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">個人ファイル</span><span class=\"date tnum\">2026-08-25</span></div>\n      <p class=\"title\">個人ファイル: 体力測定の一覧印刷・休み連絡の下書き表示・タブ列スクロールバー常時表示</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①体力測定タブに「印刷/PDF保存」ボタンを追加(全測定日×全項目のA4横一覧・ヘッダに氏名/事業所/出力日)。②休み連絡カレンダーで「編集済」なのに連絡タブの休み連絡が0件になる食い違いを解消: 「編集済」はFAX下書き(faxDataStore)の編集のみで、連絡タブは印刷/PDF/送信時に記録される送付履歴(faxHistory)を表示していたため。連絡タブに「下書き(編集済・未送付)」の一覧を追加し、出力すれば送付履歴に載る旨を案内。③タブ列に横スクロールバーを常時表示(タブが隠れていることに気付けるように)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b4c140b</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"振替の色を紫から緑に統一。休業日の特記に休業理由を自動表示。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-25</span></div>\n      <p class=\"title\">提供記録: 振替の色を緑に統一・休業日の特記に休業理由(年末年始等)を自動表示</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">月表示・個人ファイルのサービス提供記録・期間一括出力で「振替」が紫(#7c3aed)で表示されていたのを、他画面(状態ボタン/分析/実績)と同じ緑(#059669)に統一。また休業日の行は特記が空のとき、各種設定の休業日に登録した休業名(例: 年末年始)や「定休日」を特記欄に自動表示するようにした(月行生成generateMonthlyScheduleで補完・記録には書き込まない)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b4c140b</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"印刷設定を明確化。1面はB6手差しを既定に、使い方ガイドを追加。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-08-25</span></div>\n      <p class=\"title\">連絡帳の印刷設定を明確化: 1面はB6(手差し)を既定に+手差しトレイの使い方ガイド</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">「横(B5)/縦(B6)」の表記がパッと見で分かりづらかったため、「B6（手差しトレイ）/B5（中央にB6配置）」に改名し、1面（1人ずつ）を選ぶと用紙を自動でB6に設定。B6選択時は手差しトレイでの印刷手順（用紙セット→複合機でB6/カスタム128×182mm選択→印刷画面でB6・手差し指定）と「最初は1枚テスト印刷」の注意書きを表示。ほとんどの複合機は手差しトレイでB6対応だが機種依存のため未検証の旨をユーザーと共有済み。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e341cd2</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"月間スケジュール\" data-text=\"月間で取り消した振替が再読み込みで復活。テーブルへの削除伝達漏れ。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">月間スケジュール</span><span class=\"date tnum\">2026-08-25</span></div>\n      <p class=\"title\">月間スケジュールで取り消した振替が、保存→再読み込みで復活する問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">月間スケジュールの振替取消/セル取消は墓石(deletedIds)を積むだけで、テーブル(ticket_records)への削除伝達(options.deleteRecordIds)を渡していなかった。テーブルの行が生き残るため、保存→再読み込みや数秒後の受信で取り消したはずの振替記録が必ず復活していた(2026-08-10に提供記録入力側で修正した事象と同型の伝達漏れ)。</span><span class=\"lb\">対応</span><span class=\"tx\">振替取消(cancelFurikaeMaster)・セル取消(applyShiftStatusの取り消し)・残骸記録削除ツールの3経路すべてで、削除した記録idを deleteRecordIds でテーブルにも伝えるようにした。既に復活してしまった記録は、更新後にもう一度取り消せば消える。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e334dc7</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"2端末で別利用者の血圧同時入力で片方が消える穴と、古い下書きが振替取消を巻き戻す穴を閉鎖。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-25</span></div>\n      <p class=\"title\">2端末同時入力の強化: 刻印ゲートを全既存行に拡張+実編集の有効期限30分</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">案A本適用(f7ee007)は「実編集記録がある行」だけをゲートし、記録の無い行は従来の差分刻印のままだった。端末Bが利用者Aを一切触っていなくても自動保存は下書き全行を保存するため、同期で届いたAの新しい血圧と下書きの古い空欄の差分が「新編集」と誤刻印され、Aの入力が消えた(WindowsでA・iPhoneでBを同時入力→Aだけ消える実害)。また実編集記録に有効期限が無く、数日前に振替を設定した端末の古い下書きが、他端末で行った振替取消を何度でも巻き戻せた。</span><span class=\"lb\">対応</span><span class=\"tx\">ゲートを<b>既存行すべて</b>に拡張(記録の無い行の提供記録系フィールドは刻印しない)+実編集の有効期限30分。あわせて提供記録を書き換える全経路(月間スケジュールの振替設定/取消/欠席理由・休止設定・FAX休み連絡の理由差替)に実編集マーキングを追加し、正規の変更がブロックされないようにした。ブロック時はstamp-gateログに記録。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">228aead</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"月間スケジュール\" data-text=\"月間スケジュールの取り消しで対の振替先が残骸として残る問題を修正。日誌の先週コピーは車両のみに。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">月間スケジュール</span><span class=\"date tnum\">2026-08-25</span></div>\n      <p class=\"title\">月間スケジュールの取り消しで対の振替先も一緒に取り消し／日誌コピーは車両紐付けのみ</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">月間スケジュールで振替元の欠席セルを取り消すと、そのセルの記録だけ整理され、対になる振替先の「振替」記録・特記(「◯月◯日へ振替」「◯月◯日PM分振替」)・シフト表示「振(x/x)」が残骸として残り、提供記録入力と表示が食い違っていた(佐々木様 8/26→8/27の振替取消で実害)。</span><span class=\"lb\">対応</span><span class=\"tx\">取り消すセルの特記から対の振替先を検出し、振替先の記録(データがあれば出席として保持・目印は消去/空枠は墓石付き削除)とシフト表示も同時に取り消し。特記事項の振替・欠席の目印も消える。あわせて日誌の先週分自動コピーは利用者と車両の紐付けのみとし、毎回変わる送迎時間・運転者を除外(店舗要望)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">228aead</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌の並び順とプレビューの号車・送迎時間・提供日サイズを修正。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-25</span></div>\n      <p class=\"title\">日誌: 入力画面の並び順とプレビューの号車・送迎時間・提供日サイズを修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①入力画面の利用者一覧は状態ランクのみでソートされ五十音順が効いていなかった。②プレビュー用の行データを別ロジックで再構築しており patientId を持たないため、IDキーで保存される迎え/送りの号車が引けず空白。送迎時間も保存済みログのみ参照で編集中(未保存)の内容が反映されなかった。③印刷用の非表示コンテナでは提供日の自動縮小(AutoFitLine)が幅を測れず文字数フォールバックで縮んでいた。</span><span class=\"lb\">対応</span><span class=\"tx\">入力画面のソートを状態→かな順に統一。プレビューの行データを入力画面と同一構築(重複記録の絞り込み・記録なしの予定者・patientId/kana付与・同ソート)へ差し替え、表示中AM/PMは編集中データをそのままプレビューに反映。提供日は固定12pxのままに。他画面の印刷はDOMキャプチャ方式のため同種の問題なしを確認。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">435deb4</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"モニタリング\" data-text=\"絞り込み・並び替えを統一ツールバーに集約。曜日は月曜起点。AI下書き上限は利用者数×2回。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">モニタリング</span><span class=\"date tnum\">2026-08-24</span></div>\n      <p class=\"title\">モニタリングの絞り込み・並び替えを統一ツールバーに集約、AI下書き上限を利用者数×2回に</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">ヘッダに散在していた氏名検索・並び替えボタンを整理し、ヘッダ直下の1本のバーへ集約。絞り込みは氏名/状態(すべて・未作成・未確認)/曜日(月〜日のマルチ選択チップ)、並び替えは名前/介護度/事業所/曜日+昇順・降順の切り替え。右端に現在の表示人数。利用曜日の表示と並び順は月曜起点に統一(従来は日曜起点の文字列比較のため火曜始まり等でバラバラだった)。AI下書きの月間上限は「利用者数+3回」から<b>「利用者数×2回」</b>に変更し、上限表示・警告文言も更新。あわせて選択バーの「未作成のみ」は絞り込みの「未作成」と重複のため撤去(絞り込み後に「全員」で同じ結果)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e43df04</span> <span class=\"cid\">5b131c0</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"2端末同時編集で血圧等が巻き戻る問題の恒久対策。刻印を実編集ベースに本適用。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-24</span></div>\n      <p class=\"title\">2端末同時編集の巻き戻り恒久対策（実編集ベース刻印の本適用）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">Windowsで気分・スマホで血圧を同時入力すると「血圧153/85→1」のように欠ける実害が発生。8/17に特定した構造(保存時の項目時刻の刻印が「実際に編集した項目」ではなく「差分」で判定され、編集中に他端末の途中値が下書きへ紛れると新編集として誤刻印)そのものだった。</span><span class=\"lb\">対応</span><span class=\"tx\">観察モードで収集してきた実編集記録を<b>本適用</b>: 提供記録の既存行では、提供記録入力が管理する項目(状態/特記/バイタル/運動/気分等)について<b>実際に編集した項目だけに新時刻を刻む</b>。状態モーダル・休業/休止の自動補正・月表示編集・振替取消も実編集として記録。実編集記録の無い行(連絡帳・他画面由来)は従来どおり。誤刻印をブロックした瞬間は同期ログ(stamp-gate)に記録され、巻き戻り防止が働いたことを確認できる。1コミットで即時切り戻し可能な独立変更。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f7ee007</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"スケジュール\" data-text=\"スケジュールをカレンダーに改名。繰り返し絵文字も削除済み。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">スケジュール</span><span class=\"date tnum\">2026-08-24</span></div>\n      <p class=\"title\">「スケジュール」を「カレンダー」に改名</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">行事だけでなく誕生日・認定期限も表示するカレンダー実態に合わせ、サイドバー・画面タイトル・ホームのタイルを<b>「カレンダー」</b>に改名(利用者マスタの「月間スケジュール」との紛らわしさも解消)。繰り返し予定の絵文字表示は[繰]表記へ変更済み。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f7ee007</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌カレンダーの未確認扱い修正と送迎未入力の要確認追加。利用者並びを提供記録と統一。連絡帳のボタン色変更と名称簡略化。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">日誌の要確認・カレンダー表示の見直し／連絡帳のボタン整理</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①日誌のカレンダーで、自動コピーの<b>未確認が残っている時間帯は「入力済み(緑)」に数えない</b>ように修正(未確認が全て消えるまで入力扱いにしない)。②送迎(迎え/送り)が<b>そのまま未記入</b>の場合も要確認バッジに出すように(従来はコピー未確認しか検知せず「管理者確認のみ」表示になっていた)。③日誌シートの利用者の並びを提供記録入力と同じ<b>状態順→かな順</b>に統一。④サイドバー「連絡帳 作成・印刷」を「連絡帳」に簡略化、連絡帳の「連絡事項」ボタンを白、「提供記録」ボタンを緑に変更。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f27cd33</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳に提供記録入力へのジャンプボタンを追加。相互往復できるように。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">連絡帳に「提供記録」ジャンプボタンを追加（相互往復）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">提供記録入力→連絡帳のジャンプは従来からあったが逆方向が無かったため、連絡帳ヘッダに<b>「提供記録」ボタン</b>を追加し相互に行き来できるようにした。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">75bff6b</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"次回予定の日付横の曜日を大きく濃く表示。日曜赤・土曜青。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">次回予定の曜日を大きく濃く表示（日曜=赤・土曜=青）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">次回予定モーダルの日付横の曜日が小さく薄く判別しづらかったため、日付と同等の大きさ・濃い色で表示。日曜は赤・土曜は青で一目で分かる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e2aeb6d</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"スケジュール詳細の時間の二重表示を解消。ジャンプタイルをコンパクト化し管理分析も白カードで統一。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">スケジュール詳細の時間二重表示を解消／ジャンプタイルをコンパクト化</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①本日のスケジュールの詳細で時間が上部と本文の2箇所に出ていたのを、本文の「時間：」1箇所に統一。②ホーム下部のジャンプタイルを縮小(アイコン・余白・文字)し、枠なしで浮いていた「分析(個人)/(稼働)/家族関係者投稿/スケジュール/各種設定」を<b>「管理・分析」白カード</b>にまとめて統一。ホーム全体が1画面に収まりやすくなった。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e1e96f3</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"全て既読にしても未読バッジ1が残る問題を修正。既読の記録先2系統の不一致が原因。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">全て既読にしてもサイドバーの未読バッジ「1」が残る問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">家族・ケアマネからの更新の既読には2系統あり(担当者ごとの既読記録/更新自体の確認フラグ)、ホームの「全て既読」は前者にだけ記録する一方、サイドバーのバッジは後者だけで数えていたため、確認フラグが付かない更新が残っているとバッジが消えなかった。</span><span class=\"lb\">対応</span><span class=\"tx\">バッジの集計を画面と同じ基準(どちらかが既読なら既読)に統一。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">27ac2b9</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"行事予定カレンダーに前月末翌月頭を表示。本日スケジュールの時刻強調と詳細充実。家族更新とお知らせの1行表示化。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">ホーム・行事予定の見やすさ改善（前後月表示・1行リスト化・時刻強調）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①行事予定の月カレンダーの空きマスを<b>前月末・翌月頭の日付(薄表示)</b>で埋め、予定の表示・タップもそのまま可能に。②ホームの本日のスケジュールは<b>時刻を大きく藍色で強調</b>し、タップした詳細に<b>時間・利用者名を明記</b>。カード枠も強調。③<b>家族・ケアマネからの更新</b>を「バッジ+利用者名+更新内容+日時」の1行表示に、<b>お知らせ</b>を「バッジ+日付+題名+写真枚数」の1行表示に変更(タップで従来どおり本文・写真の詳細)。運営お知らせと統一の操作感に。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">27ac2b9</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"スケジュール\" data-text=\"予定編集の日時行が折り返す問題を修正。必ず横一列表示に。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">スケジュール</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">予定編集の「日付・開始〜終了」を必ず横一列に</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">編集画面の日時行が画面幅によって折り返していたのを修正。折り返し禁止+各入力の幅指定(狭い画面では入力側が縮む)で常に1行で表示される。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">45bf09a</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"スケジュール\" data-text=\"今日の予定を削除しホームと重複解消。予定クリックは確認ポップアップ経由に。編集画面をGoogleカレンダー風に刷新。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">スケジュール</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">スケジュール画面の整理（重複解消・確認ポップアップ・Googleカレンダー風の編集）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①「今日の予定」ブロックを削除(ホームで確認でき、選択日=今日の予定とも重複していた)。②カレンダー内の予定をクリックすると<b>確認ポップアップ</b>(色バー・タイトル・日時・繰り返し・対象利用者/担当CM・メモ)が開き、<b>編集/削除/閉じる</b>を選ぶ方式に変更(誤編集防止・Googleカレンダーと同じ操作感)。③編集画面を刷新: <b>最上部の大きな下線タイトル入力+時計アイコンつきの日付・開始〜終了1行</b>のGoogleカレンダー風レイアウトに。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f0248af</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"サイドバー調整。スケジュールをホーム直下へ。実績モニタリンググループ化。お知らせ閲覧管理へ改称。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">サイドバー調整（スケジュール位置・実績とモニタリングの統合・名称変更）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①<b>スケジュールをホームの直下</b>へ移動。②実績グループを<b>「実績・モニタリング」</b>に改め、モニタリングを中に統合(勤務表/利用者実績/モニタリング)。③「家族関係者閲覧 管理」を<b>「お知らせ・閲覧管理」</b>に改称。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c187498</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"サイドバーの並びを業務動線順に変更。連絡帳→日誌→体力測定→連絡FAX→計画書→スケジュール→実績→モニタリング。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">サイドバーの並びを業務動線順に変更</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">上から ホーム/提供記録入力/連絡帳/<b>日誌/体力測定</b>/連絡(FAX)/<b>計画書</b>(毎月使うためFAXの直下へ)/スケジュール/実績/モニタリング の順に整列。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f9d6915</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"サイドバーの勤務表と実績登録を実績グループに集約。実績登録は利用者実績に改称。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">サイドバー: 勤務表・利用者実績を「実績」グループに集約</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">「勤務表」と「実績登録」を開閉グループ<b>「実績」</b>にまとめ、子項目は<b>勤務表/利用者実績</b>(実績登録から改称)とした。連絡(FAX)・分析・計画書と同じ操作感。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">778a25c</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"欠席・休止の特記(休みの理由)には家族非表示ボタンを出さず、家族へ必ず表示する仕様に。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">欠席・休止の特記（休みの理由）は家族へ必ず表示（非表示ボタンを出さない）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">状態が欠席・休止の行の特記は「休みの理由」であり家族と共有すべき情報のため、「家族非表示」ボタンを表示しない(=常に家族・ケアマネへ表示)。出席等の通常の特記は従来どおり非表示を選択できる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">de5481b</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"サイドバーを整理。休み連絡と各種連絡を連絡FAXグループ、分析個人と稼働を分析グループに集約。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">サイドバーを整理（「連絡(FAX)」「分析」の開閉グループに集約）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">項目数を減らすため、<b>休み連絡/各種連絡→「連絡(FAX)」</b>、<b>分析(個人)/(稼働)→「分析」</b>を計画書と同じ開閉グループに集約(子項目名も「個人(バイタル・記録)」「稼働(実績・月次)」と役割が分かる表記に)。毎日使う提供記録入力・連絡帳・日誌はワンタップのまま維持。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2188fa5</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"休み連絡\" data-text=\"休みカレンダーに月間スケジュールで付けた欠席が出ない問題を修正。末週に翌月の日付も表示。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">休み連絡</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">休みカレンダー: 月間スケジュール由来の欠席が表示されない問題を修正・末週に翌月分を表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">カレンダーの欠席集計が提供記録(ticketRecords)の欠席だけを見ており、<b>利用者マスタの月間スケジュールで付けた欠席が表示されなかった</b>(佐々木様の8月・9月の欠席が出ない報告)。また月末の週は空白で埋めており、8/31(月)の週の9/1〜が見えなかった。</span><span class=\"lb\">対応</span><span class=\"tx\">①欠席集計に<b>月間スケジュール(AM/PMセルの欠席)も統合</b>(提供記録と重複しないよう利用者単位で排除・年またぎの誤混入も防止)。②<b>末週を翌月の日付(薄表示・「翌月」ラベル)で埋めて1週間分表示</b>し、翌月分の欠席もそのまま見えて休み連絡も開ける。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e289696</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE\" data-text=\"一括評価に計画書の見直しセクションを追加。前回達成度と新短期目標だけで複製して更新が完了する。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE</span><span class=\"date tnum\">2026-08-20</span></div>\n      <p class=\"title\">一括評価に「⑥ 計画書(3-3)の見直し」を追加（まるっとLIFEのヒアリングシート方式）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">一括評価の末尾に計画書セクションを追加。「この評価日で計画書も更新する」をONにすると、<b>前回計画の達成度(短期/長期)・新しい短期目標(機能/活動/参加)・留意事項・実施による変化/課題</b>だけ入力すれば、保存時に<b>前回計画の「複製して更新」が自動実行</b>される(達成度は前回計画書側に記入)。長期目標は「変更する」を選んだ時のみ編集(通常は引き継ぎ)。プログラム・希望・病名等も前回から引き継がれ、計画書(3-3)画面でいつでも編集可能。同じ評価日で再保存すると同じ計画書を更新(重複しない)。初回の計画書は従来どおり3-3画面から。まるっとLIFEの実ワークブック(加算アセスメントシート)の構成を確認して項目を合わせた。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3d432b9</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"LIFE\" data-text=\"LIFEタブ名を簡潔化し作成予定の各行に一括評価ボタンを追加。対象者選択済みで即起動。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">LIFE</span><span class=\"date tnum\">2026-08-20</span></div>\n      <p class=\"title\">作成予定の各行に「一括評価」ボタン／タブ名を「LIFE」に簡潔化</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①個別機能訓練・LIFEの作成予定で、利用者名の行に<b>「一括評価」ボタン</b>を追加。押すとその利用者が選択済みの状態で一括評価(ADL・生活機能・興味関心の1画面入力)が即開く。②タブ名「LIFE・一括評価」を<b>「LIFE」</b>に簡潔化。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d2c105e</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"計画書\" data-text=\"計画書を2ハブ構成に再編。通所介護計画書と個別機能訓練LIFEを分離し件数バッジと総合事業表題切替を追加。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-08-20</span></div>\n      <p class=\"title\">計画書を「通所介護」と「個別機能訓練・LIFE」の2ハブに再編</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">書類ファミリーで整理: ①サイドバー<b>「通所介護計画書」</b>=作成予定(このファミリー分のみ)+計画書。②サイドバー<b>「個別機能訓練・LIFE」</b>=作成予定(3-3+加算分)+計画書3-3+生活機能3-2+興味関心3-1+<b>LIFE・一括評価</b>をタブで横断(3-1/3-2は3-3の別紙のためこちらへ集約)。<b>加算アドオンが無い店舗はハブごと非表示</b>。③サイドバーのラベルに<b>作成予定件数バッジ</b>(期限内+超過)。④利用者が要支援・事業対象者の場合、通所介護計画書の表題を<b>「個別サービス計画書(介護予防・日常生活支援総合事業)」へ自動切替</b>(フッタの事業種別も連動・3-3も同様)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f58a925</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"計画書\" data-text=\"個別機能訓練計画書に共同作成者欄を追加。多職種共同作成の記録として編集画面と印刷に反映。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-08-19</span></div>\n      <p class=\"title\">個別機能訓練計画書(3-3)に「共同作成者」欄を追加</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">厚労省の別紙様式3-3自体には計画作成者欄しかないが、運営基準では個別機能訓練計画は<b>多職種が共同して作成</b>することが要件のため、その記録として「共同作成者(多職種)」欄を追加(様式への任意項目追加)。編集画面の基本情報に入力欄、印刷では計画作成者セル内に「共同作成者：」行として出力。ケアマネ送付セットの変更点一覧の比較対象にも追加。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0fe8e8d</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE\" data-text=\"LIFE一括評価を追加。1画面でADL・科学的介護推進・生活機能チェック・興味関心を入力し各様式へ同時反映。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE</span><span class=\"date tnum\">2026-08-19</span></div>\n      <p class=\"title\">「LIFE一括評価」を追加（1画面入力→ADL・生活機能・興味関心へ同時反映）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">LIFE・加算画面に<b>「一括評価」</b>を追加。①基本情報 ②ADL(Barthel) ③科学的介護推進(身長体重・口腔・認知症診断) ④生活機能チェック ⑤興味・関心 を1画面で入力でき、保存すると<b>各様式のレコードへ同時反映</b>される(個別画面とデータ共有・二重管理なし)。④の生活機能ADLを選ぶと②のBarthel点数が未入力項目へ自動で入る(1回入力)。必須項目は赤色表示で未完なら一時保存、上部に<b>評価履歴タイムライン</b>(日付タップで過去の評価を開ける=ADLがどこに保存されたか分からない問題も解消)と<b>セクションジャンプ</b>を配置。尺度・Vitality・DBD13等の詳細は従来のLIFE・加算編集で入力。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">531c556</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE\" data-text=\"LIFEデータ移行のCSV取込を追加。まるっとLIFE等の提出用CSVからADL評価と科学的介護推進項目を復元。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE</span><span class=\"date tnum\">2026-08-19</span></div>\n      <p class=\"title\">LIFEデータ移行のCSV取込を追加（まるっとLIFE等からの乗り換え支援）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">LIFE・加算画面に<b>「CSV取込(移行)」</b>を追加。LIFE提出用CSVは全国共通仕様(v0310)のため、まるっとLIFE等の他社ソフトが出力したCSVやLIFE本体からダウンロードした過去データを読み込める。<b>科学的介護推進(TIFI2024・114列)とADL維持等(AINT2024・23列)</b>に対応し、ヘッダ有無・文字コード(UTF-8/Shift_JIS)を自動判定。<b>被保険者番号(10桁)で利用者と突合</b>し、プレビューで確認してから、ADL評価(Barthel)+科学的介護推進の固有項目(身長体重/口腔/認知症評価/DBD13/Vitality/ICF等)を評価レコードとして復元する。同じ評価日の既存レコードは重複として既定でチェックを外し、同日にTIFIとAINTの両方がある場合は1件にマージ。取込後は評価者「LIFE移行取込」として履歴に並び、以後は通常の再評価として続きから運用できる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0e967bd</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"全体\" data-text=\"印刷FAX全画面に氏名マスキングを追加。3-3印刷の右端見切れも縮小で解消。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-08-19</span></div>\n      <p class=\"title\">印刷/FAXの「氏名マスキング」を全画面に追加・3-3印刷の右端見切れ解消</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①印刷プレビューのヘッダーに<b>「氏名マスキング」チェック</b>を追加。ONにすると、その印刷物/FAX内の利用者の氏名・ふりがな(姓名の連続表記も含む)が<b>●●に置換</b>されてプレビュー・印刷・PDF・FAX送付に反映される。計画書(3-3/3-4)・ケアマネ送付セット・連絡帳・実績表・休み連絡/各種連絡など<b>印刷機能のある全画面で共通</b>(開くたび既定OFF)。②個別機能訓練計画書(3-3)のA4印刷で右端が見切れる問題を全体4%縮小で解消。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a06a748</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"各種設定\" data-text=\"日誌タブの編集がタブ切替で破棄され保存しても旧値に戻るバグを修正。全行削除も保存されるように。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-08-19</span></div>\n      <p class=\"title\">日誌タブ(職員・送迎車・1日の流れ)の編集がタブ切替で破棄されるバグを修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">日誌タブのパネルはタブを開くたびに再マウントされ、その初期化が<b>未保存の編集があってもクラウドの旧値で無条件に上書き</b>していた。日誌タブ→他タブ→画面移動の流れで「保存しますか→保存する」を押しても、保存されるのは巻き戻った旧値のため「更新・削除が反映されない」ように見えた。さらに保存時の空ガードが「全行削除(空配列)」を未同期と誤解して旧値に戻していた。</span><span class=\"lb\">対応</span><span class=\"tx\">①この画面で実際に編集したキー(職員/送迎車/AM/PMの流れ)を記録し、<b>未保存の編集がある間はタブ再訪でも初期化しない</b>。②編集済みキーは<b>空配列(全削除)もそのまま保存</b>する(未編集キーは従来どおり空ガードで他端末の登録を保護)。③保存・同期完了で記録をクリア。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ff6d6aa</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"Windowsで文字が細く薄く見づらい問題を改善。メイリオ優先フォント・薄グレー文字の濃色化・印刷フォントも対応。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-08-19</span></div>\n      <p class=\"title\">Windowsで文字が細く・薄く見づらい問題を改善（フォントと薄グレーの調整）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">フォント未指定のためWindowsでは游ゴシック(標準ウェイトが極端に細く描画される)が使われ、特に計画書系の小さな薄グレー文字(「前回評価から3ヶ月」等)が読みづらかった。</span><span class=\"lb\">対応</span><span class=\"tx\">①本文フォントを<b>メイリオ優先</b>に統一(Macは従来どおりヒラギノで見た目不変)。②薄グレー(slate-400・#94a3b8)の説明文・補足を全画面で一段濃い色(slate-500相当)へ(計182箇所+クラス一括)。③計画書・帳票の印刷用フォント(16箇所)も游ゴシックの前にメイリオを追加。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d8a8a04</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"日付と挨拶を1行表示に。すべて既読にするボタンを全て既読へ改称。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-18</span></div>\n      <p class=\"title\">ホームの日付・挨拶を1行表示に／「全て既読」へ改称</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①日付と「〇〇さん、今日もよろしくお願いします。」の2行を横並び1行にして紫のヘッダーの高さを縮小。②「すべて既読にする」ボタン(運営お知らせ/本日のスケジュール等3箇所)を「全て既読」に短縮。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a9791fc</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"運営からのお知らせを既定で閉じたバーに。新着があれば件数バッジ。スケジュールや家族更新が最初に見えるように。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-18</span></div>\n      <p class=\"title\">運営からのお知らせを既定で閉じたバー表示に（新着は件数バッジで通知）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">業務ではスケジュール・家族/ケアマネからの更新が主役のため、運営からのお知らせは<b>既定で閉じた薄いバー</b>にし、新着があれば赤い「新着N件」バッジで知らせる。タップで開くと従来の1行リスト(4件/頁・クリックで全文)が展開。新着が無ければ「新着なし」表示のみ。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6d5d582</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"管理局\" data-text=\"店舗一覧に法人・事業所名の検索を追加。セクションジャンプ。店舗ログイン情報ガイダンスを折りたたみ化。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">管理局</span><span class=\"date tnum\">2026-08-18</span></div>\n      <p class=\"title\">管理局コンソールを整理（店舗検索・セクションジャンプ・ガイダンス折りたたみ）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">店舗が増えた時に備えて3点整理。①店舗一覧に<b>法人名・事業所名・短縮名の検索ボックス</b>を追加。②画面上部に<b>ジャンプボタン(お知らせ管理/店舗一覧/同意ポリシー/傷病名マスタ)</b>を固定表示し、下の方のパネルへワンタップで移動できるように。③常設だった「店舗ログイン情報について」のガイダンスを折りたたみ(既定閉)にし、記載も現状(管理者PWリセットで再発行可)へ更新。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6d5d582</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"運営からのお知らせをコンパクト化。1行表示4件でクリックすると全文モーダル。画面の半分以上の占領を4分の1程度に。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-18</span></div>\n      <p class=\"title\">ホームの「つむぎ運営からのお知らせ」をコンパクト化</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">本文プレビューつきの大きなカード(3件)で画面の半分以上を占領していたのを、<b>バッジ+日付+タイトルの1行表示×4件</b>に変更(約1/4の高さ)。クリックで従来どおり全文モーダルが開く。未読は色つき・既読はグレー、「すべて既読にする」も従来どおり。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5f5a6a9</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"ケアマネ事業所・担当者を手入力で追加してもすぐ消える問題を修正。追加/削除の即保存化と未編集判定の穴の根治。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-08-17</span></div>\n      <p class=\"title\">ケアマネ事業所・担当者の手入力追加が数秒で消える問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">各種設定の未編集判定は、同期や保存の後に基準を「後で取り直す」目印(null)にしていた。4秒ごとの同期で基準がほぼ常にnullのため、その直後の最初の編集(事業所/担当者の追加)が「基準の取り直し」と誤解されて未保存扱いにならず、次の同期がクラウドの古い一覧で画面を上書きして追加が消えていた。ケアマネ以外の設定項目でも同じ穴があった。</span><span class=\"lb\">対応</span><span class=\"tx\">①<b>基準を「その場で計算した署名」で即確定</b>するように変更(同期追従・第2層・保存後の3箇所)。最初の編集が確実に未保存扱いになり、同期に上書きされない。②<b>ケアマネ事業所/担当者の追加・削除(8箇所)は保存ボタンを待たず即クラウド保存</b>に変更(削除は確認ダイアログつき)。編集モーダル・CSV取込は従来どおり(①の修正で保護される)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1f93e31</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"次回お迎え時間が手修正した次回日付ではなく自動候補日の曜日で計算され月曜なのに8時台になる問題を修正。日付連動に。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-08-17</span></div>\n      <p class=\"title\">次回お迎え時間を「表示中の次回日付」の曜日に連動（月曜なのに8時台になる問題の根治）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">次回「日付」を手修正しても、「時間」の自動計算は<b>自動が選んだ候補日</b>(例: 休止期間をスキップした先の水曜AM)の曜日で行われていた。そのため日付=月曜(PM 13:30登録)なのに時間=8時台(AMの施設提供時間から逆算)という不整合が起きていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>時間の自動計算を「表示している次回日付」の曜日で行うよう統一</b>: ①連絡帳の印刷 ②次回予定モーダルの初期表示 ③モーダルで日付を変更した瞬間の自動追従(時間を手入力済みの場合は触らない)、の3箇所。登録済み送迎時間→施設提供時間から逆算→既定値、の優先順は従来どおり。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">05f22b4</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"次回お迎え時間が送迎時間マスタと違う値になる問題。焼き付き残骸のチェック機能追加と休止期間の次回計算連動。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-08-17</span></div>\n      <p class=\"title\">次回お迎え時間の焼き付き残骸チェック機能を追加・休止期間を次回計算に連動</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">連絡帳の次回お迎え時間は、記録に保存済みの値(手入力扱い)があると自動計算より優先される。過去の「次回予定モーダルを開いて保存すると全員分の自動計算値が確定値として焼き付く」不具合(修正済み)の残骸や誤入力(例: 8時)が記録に残っていると、送迎時間マスタ(例: 月曜13:30)を直しても印刷に古い値が出続けた。また次回日の計算は「休止の記録行がある日」しか除外せず、記録行が無い休止中の未来日が次回候補になり得た。</span><span class=\"lb\">対応</span><span class=\"tx\">①次回予定モーダルに<b>「残骸チェック」</b>を追加: 全期間の記録から保存値が自動計算と食い違うものを一覧表示し、選択して一括で自動計算(マスタ連動)に戻せる。分なしの時刻(8時等)は焼き付きの可能性が高いため既定でチェック済み。②<b>次回日の計算に休止期間(pauseHistory)の判定を追加</b>し、記録行が無くても休止中の日は候補から外れるようにした。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">25fab39</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"家族非表示ボタンの表記調整。表示時は家族/非表示の2行、非表示中は非表示中の1行縮小表示。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-17</span></div>\n      <p class=\"title\">「家族非表示」ボタンの表記を調整（2行表示／非表示中は1行縮小）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">通常時は「家族／非表示」の2行表示、押した後は赤地に「非表示中」を1行(縮小)で表示するようにした。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7c1d9b0</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"特記の載せる/非公開を家族非表示トグルへ置換。非表示は利用者家族のみでケアマネには常に表示。ボタンは特記の左側へ。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-17</span></div>\n      <p class=\"title\">特記の公開設定を「家族非表示」トグルに刷新（ケアマネには常に表示）</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">従来の「載せる/✕非公開」は非公開にするとケアマネの閲覧画面からも消える仕様で、運営者の認識(ケアマネには見える)と実装が食い違っていた。また通常運用は「載せる」が基本のため、末尾のトグルは分かりづらかった。</span><span class=\"lb\">対応</span><span class=\"tx\">①ボタンを<b>「家族非表示」トグル</b>に置換し特記欄の左側(前)へ移動。既定は表示で、押すと赤い「家族非表示中」になる。②非表示の効果は<b>利用者家族の閲覧画面のみ</b>に変更し、<b>ケアマネには設定に関わらず常に表示</b>。ご本人アカウントには従来どおり特記自体を表示しない。管理者プレビュー(家族画面)は家族と同じ見え方。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">822e5dd</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"同期\" data-text=\"提供記録同期の観察モードを追加(挙動不変)。差分刻印とユーザー実編集の食い違いをstamp-obsログで収集し、巻き戻り修正の本適用を判断する。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-17</span></div>\n      <p class=\"title\">提供記録同期の観察モードを追加（2端末同時編集の巻き戻り調査・挙動不変）</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">2端末同時編集で「PCの欠席がスマホの古い下書きに巻き戻される」「特記の入力が一瞬消える」報告。調査の結果、保存時の項目時刻(_fieldTs)刻印が「実際に編集した項目」ではなく「ベースラインとの差分」で判定されるため、編集中に他端末の変更が届くと未編集の古値が新編集として刻印される構造を特定。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>まず観察モードのみ導入(動作は一切変えない)。</b>ユーザーが実際に編集した項目を端末内で記録し、保存時の差分刻印と突き合わせて同期ログ(stamp-obs)に出力する。mis=未編集なのに刻印された項目数(巻き戻りの実例)、un=編集記録の無い行(状態モーダル・自動補正など経路の棚卸し)。数日の収集後、ユーザー編集ベース刻印(案A)の本適用を判断する。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0e18b9c</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"計画書\" data-text=\"利用曜日から送迎時間を除外。日誌から反映に改称し空行を反映しない。定型文チップを全画面で廃止。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-08-16</span></div>\n      <p class=\"title\">通所計画書の利用曜日・1日の流れ反映・定型文チップを整理</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①「利用曜日・時間帯」の自動入力から送迎時間を除外し、曜日と時間帯(AM/PM/1日)のみに。②「各種設定の1日の流れから反映」を<b>「日誌から反映」</b>に改称し、日誌設定の余白行(時間も内容も無い行)を反映しないようにした(反映後の上部に空欄プログラムが並ぶ問題の解消)。③目標・留意事項などの下に出ていた<b>クリック追記式の定型文チップを全画面で廃止</b>(ユーザー判断: 画面の情報量を減らす)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">36e62d7</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"計画書\" data-text=\"利用者セレクトをタブ左側へ移動。作成予定を様式別グループ表示にし、行タップで対象者選択済みの編集を即開始。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-08-16</span></div>\n      <p class=\"title\">計画書の利用者セレクトを左側へ・作成予定を様式別表示+タップで即作成開始</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①計画書系4画面(3-3/3-2/3-1/通所)で右端にあった利用者選択をタブの左側へ移動し見やすくした。②「作成予定」タブを様式別のグループ表示に変更: 月ごとの中で<b>通所介護計画書(達成予定日/6ヶ月)・個別機能訓練計画書(3ヶ月ごと)・科学的介護推進体制加算(3ヶ月ごと)・ADL維持等加算(6ヶ月ごと)</b>に分けて周期も明記。③一覧の行をタップすると<b>その利用者が選択済みの状態で該当画面が開き、計画書は前回分の「複製して更新」が自動で始まる</b>(前回が無ければ新規作成)。加算はLIFE・加算画面が対象者選択済みで開く。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e71c1f6</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"家族・ケアマネ閲覧画面の月平均/毎日トグルを非表示に。期間メニューの日別/月平均選択と重複していた。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-08-16</span></div>\n      <p class=\"title\">家族・ケアマネ閲覧画面の「月平均/毎日」トグルを非表示に（期間メニューと重複）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">半年以上の期間を選ぶと通所記録タブに「月平均/毎日」の切替が出ていたが、親ヘッダの期間メニューに「日別・○○／月平均・○○」の選択が組み込み済みで機能が重複していたため、家族・ケアマネ閲覧画面では非表示にした。事業所の分析(個人)では期間ボタンに日別/月平均の区別がないため従来どおり表示。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b556a7d</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"計画書\" data-text=\"前回計画書の評価を新規作成と同時に入力可能に。ケアマネ送付セット印刷(送付状+変更点一覧+今回+前回評価入り)を追加。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-08-13</span></div>\n      <p class=\"title\">前回計画書の評価の同時入力と「ケアマネ送付セット」印刷を追加（3-3・通所介護計画書）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①新しい計画書の編集画面に「前回計画書の評価」カードを追加。前回の目標を見ながら達成度(通所は総括も)を入力でき、保存すると<b>前回の計画書側に記入</b>される。②「ケアマネ送付セット」ボタンを追加: <b>送付状+今回の計画書+前回の計画書(評価入り)</b>をA4でまとめて印刷できる。送付状は宛先(利用者マスタの担当ケアマネ事業所/氏名/FAX)・発信元(事業所情報)・送付書類一覧・前回評価サマリを自動記載し、<b>前回からの変更点一覧(目標/留意事項/プログラム等の差分表)</b>も自動生成する。個別機能訓練計画書(3-3)と通所介護計画書(3-4)の両方に対応。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c3d04d7</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"計画書\" data-text=\"計画書系のカレンダーボタンが見切れる問題を全様式で修正。日付枠の幅も適正化。興味関心のチェックラベルを1行固定。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-08-13</span></div>\n      <p class=\"title\">計画書系のカレンダーボタン見切れを全様式で修正・日付枠の幅と1行ラベルも調整</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">日付欄のカレンダー選択にネイティブのdate入力を幅36px(通所は32px)に押し込んで直接表示していたため、日付文字列の先頭とアイコンだけが見える壊れた表示になっていた(3-3/生活機能/興味関心/通所介護計画書の全日付欄と通所の目標日付5箇所)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>カレンダーアイコンのボタン表示に変え、その上に透明なdate入力を重ねる共通部品(CalendarPickBtn)へ全箇所を置換。</b>クリックで従来どおりカレンダーが開く。あわせて①日付入力枠がグリッド幅いっぱいに広がりすぎていたのを220px上限に、②興味・関心チェックの「してみたい」等のラベルが2行に折り返していたのを1行固定に修正。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">330bdeb</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"LIFE\" data-text=\"病名検索を強化。脳・腰などキーワード検索の並び順改善、読み仮名検索、空欄クリックでよく使う病名を候補表示。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">LIFE</span><span class=\"date tnum\">2026-08-12</span></div>\n      <p class=\"title\">病名検索を強化（キーワード検索・読み仮名対応・よく使う病名の候補表示）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">コードや正式病名を覚えていなくても選べるように3点強化。①「脳」「腰」など一文字のキーワードでも、<b>前方一致→名前が短い順</b>で関連病名が並ぶようにした(従来は部分一致のマスタ順で目的の病名が埋もれた)。②管理局が取り込んだマスタにカナ名称列がある場合は保持し、<b>「のうこうそく」等の読み仮名でも検索可能</b>に。③検索欄を空欄のままクリックすると<b>通所介護でよく使う病名20件(脳梗塞後遺症・変形性膝関節症・腰部脊柱管狭窄症・骨粗鬆症・パーキンソン病等)を候補表示</b>し、選ぶだけで入力できる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9e69926</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"管理局\" data-text=\"傷病マスタCSV取込の名称列検出を厚労省マスタの実形式に合わせて強化。全角の正式名称を半角カナ略称より優先。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">管理局</span><span class=\"date tnum\">2026-08-12</span></div>\n      <p class=\"title\">傷病マスタCSV取込の病名列検出を厚労省マスタの実形式に対応</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">診療報酬情報提供サービス配布の傷病名マスターは40列超で、正式名称(漢字)より前に半角カナの省略名称列がある。名称列の検出で<b>漢字・ひらがな・全角カナを含む列(正式名称)を優先</b>し、無い場合のみ半角カナ等にフォールバックするようにした。取込に必要なのは「傷病名マスター」のみ(旧傷病名管理ファイル・移行対応テーブルは不要=過去入力コードはレコード保存でマスタ照合しない設計のため変換不要)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">616a7f1</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"管理局\" data-text=\"LIFE傷病名マスタを管理局からCSV取込できる機能を追加。全店の病名検索に自動反映。置き換え式で容量は増えない。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">管理局</span><span class=\"date tnum\">2026-08-12</span></div>\n      <p class=\"title\">LIFE傷病名マスタを管理局からCSVで取込→全店へ自動反映</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">管理局コンソールに「LIFE傷病名マスタ管理」を追加。厚労省の傷病名マスタCSV(UTF-8/Shift_JIS自動判別・コード列と病名列を自動検出・重複除去)を取り込むと全店共通の予約キーに保存され、個別機能訓練加算が有効な全店舗の病名検索に自動反映される。未取込の間は同梱マスタ(約2.7万件)を使用。</span><span class=\"lb\">設計</span><span class=\"tx\"><b>置き換え式(常に最新1版のみ保持)のため取込を繰り返しても容量は増えない。</b>読込は病名検索を開いた時に1回だけのオンデマンド取得で、店舗同期(pull/push)からは独立しており同期速度に影響しない。過去に計画書へ入力済みのコード・病名は各計画書レコード側に保存されているため、マスタ入替の影響を受けずエラーにもならない。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0dc6abd</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"LIFE\" data-text=\"LIFE個別機能訓練の傷病名コードが7桁未満で出力される問題を修正。ゼロ埋めで提出エラーを防止。任意→原則入力に表記修正。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">LIFE</span><span class=\"date tnum\">2026-08-12</span></div>\n      <p class=\"title\">LIFE傷病名コードの先頭ゼロ落ちをCSV出力時に7桁ゼロ埋めで補正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">同梱の傷病名マスタ約2.7万件のうち290件(未コード化傷病名999、Ａ型肝炎701001等)は先頭ゼロが落ちた状態で収録されており、LIFE仕様の7桁固定(例: 0000999)と桁が合わないCSVが出力される恐れがあった。あわせて画面の「傷病名(任意)」表記は国仕様の必須区分「○(原則必須・記録不可の場合のみ空欄可)」と不一致だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>CSV出力時に傷病名コードを7桁ゼロ埋めするようにした。</b>表記も「原則入力」に修正し、説明文に空欄可の条件を明記。なお9999999「その他」というコードは国のマスタに実在しない(未コード化は0000999)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">614eda7</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"ホームのボタンが反応しない・PDF添付サムネイルがチカチカする問題を修正。PDFはサムネイル枠にPDFと表示。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-12</span></div>\n      <p class=\"title\">ホームのボタン不発とPDF添付サムネイルのチカチカを修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">ホームのカード/タイル部品がビュー内部で毎描画ごとに定義し直されており、4秒ごとの同期のたびにReactがホームのDOM全体を破棄→再構築していた。タップ中のボタンが押下と離しの間に破棄されてクリックが不発になり、PDF添付は画像として読込→失敗を繰り返して空白がチカチカしていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>部品をモジュールレベルへ移動し、同期の再描画でDOMが再利用されるようにした。</b>あわせてPDF添付は画像に流し込まず、サムネイル枠に「PDF」と表示するようにした(クリックでのプレビューは従来どおり)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">aad5ffa</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"計画書\" data-text=\"個別機能訓練計画書の印刷用シートが画面に常時表示され一覧が隠れる問題を修正。印刷レイアウトも固定行高の自然な組みに変更。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-08-12</span></div>\n      <p class=\"title\">個別機能訓練計画書(3-3)を開くと印刷シートが常時表示され一覧が使えない問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">前回の重なり修正で入れた印刷用CSS(display:flex!important)が、非表示指定(display:none)を打ち消して画面上でも印刷シートを常時表示させていた。シートが画面を占領して既存の一覧(編集/複製して更新/削除)が隠れ、A4固定高に押し込まれて上下が潰れて見えた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>A4をflexで使い切る方式を廃止し、紙の様式らしい固定行高で自然に組むレイアウトへ変更。</b>画面では従来通り非表示に戻り一覧が復活。印刷でも空欄行が不自然に間延びしなくなった(行数が多い時の自動縮小は維持)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9a4e02d</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"計画書\" data-text=\"個別機能訓練計画書でプログラム行が多いと文字が表に重なる問題を修正。行数に応じて自動縮小。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-08-12</span></div>\n      <p class=\"title\">個別機能訓練計画書(3-3)で文字が表に重なる問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">運動メニューの自動読込でプログラム行が8行を超えると、A4に収める伸縮レイアウトから溢れ、下のセクションに文字が重なって表示・印刷されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>行数に応じて文字サイズと余白を自動で縮めて枠内に収めるようにした(番号も⑮まで対応)。</b>各枠にはみ出し防止も追加し、レイアウトが崩れない。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e51057d</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"LIFE評価入力の必須項目を色分け表示。必須未入力は保存不可で一時保存ボタンを新設。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-08-12</span></div>\n      <p class=\"title\">LIFE評価入力の必須項目を色分け+未入力は保存不可(一時保存は可能)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">LIFE提出に必要な項目がどれか分かりにくく、未入力のまま保存されて提出時にエラーになることがあった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>必須項目(評価日・ADL10項目・科学的介護推進の身長/体重/口腔4項目)を薄い赤背景+「必須」バッジで表示。未入力のままの保存は不可(未入力一覧を表示・保存ボタンに残数)。「一時保存」なら途中でも保存でき、後から完成させられる。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7ec8bbf</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"全体\" data-text=\"サイドバーが表示されない問題。開閉状態を端末に記憶し再読み込み後も維持するように修正。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">サイドバー開閉の記憶+提供記録の横スクロールバー常時表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">サイドバーの開閉は毎回「画面幅」で自動判定されており、再読み込みや「今すぐ更新」のたびに初期化されるため、開いていたはずのサイドバーが表示されないことがあった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>①サイドバーは開閉ボタンでの操作を端末に記憶し、再読み込み後も同じ状態を復元。②提供記録入力の上部横スクロールバーを自前描画(レール+つまみ)に変更し、どの環境でも必ず表示。つまみのドラッグやレールのクリックで表を横スクロールできる。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b2e1c24</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"施設の休業日は提供記録入力の利用者の状態が自動で休業になる。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">施設の休業日は利用者の状態が自動で「休業」になるように</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">各種設定で休業日(例: 8/12〜8/14)を設定しても、提供記録入力ではその日の利用者が全員「出席」のまま表示されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>休業日に提供記録入力を開くと、その日の利用者全員の状態が自動で「休業」になり、特記に休業名(例: 夏季休業)が自動記載される。</b>休止中の人は休止のまま。バイタル等を入力済みの記録は変更しない(誤設定の保護)。休業日の追加・削除は画面に即反映。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">bdd54c9</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"利用者マスタ\" data-text=\"休止を再開すると過去の休止期間まで出席表示に戻る問題と終了日を過ぎても提供記録が休止のままの問題を修正。期間ベース判定に。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">休止の表示を「設定した期間の中だけ休止」に統一(再開後も期間表示を維持)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①休止の判定が「現在休止中であること」を前提にしていたため、利用を再開した瞬間に過去の休止期間の表示(月間スケジュール・提供記録)まで全て消えて出席予定に戻っていた。②休止中に自動保存された記録の「休止」が終了日を過ぎた日にも残り、提供記録入力が休止のまま表示され続けていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>終了日つきの休止は現在の状態に関係なく「期間内=休止」で判定するよう変更。月間スケジュールも提供記録も、設定した休止期間の中だけ休止・それ以外は通常表示で一貫。終了日を過ぎた日に残った休止の残骸は出席に自動補正。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">abb1cca</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"利用者マスタ\" data-text=\"アカウント発行管理で登録済みアカウントが点滅したり消えたりする問題を根本修正。取得エラー時の空上書きが原因。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">アカウント発行・管理で登録済みアカウントが点滅・消失する問題を根本修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">家族アカウント/招待一覧の取得が、通信エラー時にも「空の一覧」を正常な結果として返していた。10秒ごとの自動更新で空が画面に上書きされ、登録済みアカウントが消えたり表示/非表示を繰り返していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>取得に失敗した時は画面に触れないようにし、成功した内容が今の表示と同じなら何もしない方式に変更。</b>別の原因で一覧が消えても次の自動更新(10秒)で復元される。あわせて基準値の透かし表示は「開いた時点で既に○が入っていたセル」だけに調整(○を入力した直後は○のみ表示)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">956345c</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"運動セルで○×から数字を打つと記号を自動クリア。記号だけのセルには基準値を薄く並記。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">運動セルの入力改善(記号の自動クリア+基準値の薄表示)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">○が入ったセルに数字を打つと「○3」と連結されてしまい、記号を消してから入力し直す必要があった。また○を押した後に基準値を確認できず、消して確認して再入力する手間があった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>①○/×/－の状態で数字を打つと記号が自動で消えて数値だけになる。②記号だけのセルを選択中は記号が薄くなり基準値が透かし表示され、消さなくても基準値を確認できる(未選択時は記号のみ)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ec31334</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"個人ファイル\" data-text=\"フェイスシートの新規作成を廃止し常に編集追記に。全利用者に最初から用意されている扱い。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">個人ファイル</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">フェイスシートを「新規作成」から「編集・追記」の常設方式に変更</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">フェイスシートは全利用者に必ず用意する運用のため、「新規作成」という入口は実態に合わなかった。基本情報・ご家族登録・家族側の編集内容が自動で反映されるようになったこともあり、常に存在する書式として扱う。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>ボタンを常に「編集・追記」に変更(PDFも常時表示)。</b>未入力の場合はその旨を案内。将来の電子契約書からの自動反映の受け皿にもなる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">476ad3f</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"アカウント発行管理モーダルが上下に揺れて表示非表示を繰り返す問題を修正。10秒ごとの無条件保存が原因。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">アカウント発行・管理の画面が揺れ続ける問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">家族アカウント一覧の自動更新(10秒ごと)が、内容が変わっていなくても毎回全体保存を実行し、モーダルが再構築されて上下に揺れ・点滅していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>サーバーの応答が前回と同じ場合は何もしないようにした。</b>実際に変化があった時だけ画面を更新する。あわせて分析個人の期間指定も家族側と同仕様(年4桁上限・逆転防止・片側未指定の既定)に統一。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">476ad3f</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"分析\" data-text=\"月別通所状況で利用開始前の0%の月を表示しない。注記つき。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">月別通所状況から「利用開始前の月」を除外(0%の羅列をなくす)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">1年表示などで利用開始前の月が0%として並び、実際の通所状況が読み取りにくかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>利用開始日より前の月を表示せず、「※利用開始(日付)前の月は表示していません」と注記。</b>開始日未設定の利用者は先頭から続く記録ゼロの月を省略する。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1a2a75e</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"続柄が本人のアカウントが緊急連絡先に表示される問題を修正。表示と編集経路の両方でガード。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">続柄「本人」が緊急連絡先に表示される問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">新規登録時の除外は実装済みだったが、修正前に登録された旧データと「登録者情報の編集」経由で、ご本人の閲覧用アカウントが代表家族(緊急連絡先)欄に入る経路が残っていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>緊急連絡先の表示処理で続柄「本人」を一括除外(全画面に有効)。登録者情報の編集でも本人なら代表家族欄に書かないようにした。</b>ご家族が登録すれば従来どおり緊急連絡先に反映される。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1a2a75e</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"家族アプリ\" data-text=\"家族や本人が編集したメールかかりつけ医医療機関がフェイスシートと事業所に反映されない問題を修正。送信パッチの欠落。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">家族・本人が編集した利用者情報の一部が事業所に反映されない問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">家族側の利用者情報保存で、クラウドへ送る内容からメールアドレス・かかりつけ医・医療機関名・医療機関の連絡先が漏れており、更新通知には項目名が出るのに実データが事業所・フェイスシートに届いていなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>欠落4項目を送信に追加し、フェイスシートの医療欄(主治医/医療機関/連絡先)へも部分同期する専用処理を新設。</b>フェイスシート全体を上書きしない安全な方式(指定欄のみ更新+同期保護の刻印)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a2e7c67</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"お知らせの見出し日付を投稿日に変更。予定から配信したお知らせが未来日に見えていた。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">お知らせの見出し日付を「投稿日」に変更</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">担当者会議などの予定から配信したお知らせは、見出しの日付が開催日(未来日)になっており、いつ投稿されたのか分かりにくかった。開催日は本文に記載済み。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>見出しの日付は投稿日を優先して表示。</b>開催日は従来どおり本文で確認できる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">53be664</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"期間セレクトを独自ドロップダウンに。日別で表示と月平均で表示の見出しが濃い緑バーではっきり見える。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">期間の選択メニューを見やすい独自デザインに変更</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">端末標準のメニューではグループ見出し(日別で表示/月平均で表示)の色を変えられず、薄いグレーで読みづらかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>独自のドロップダウンに置き換え、見出しを濃い緑のバーとして配置。その下に1ヶ月/3ヶ月/半年/1年/全期間/期間を指定が並び、選択中の項目に✓が付く。</b>どの端末でもはっきり読める。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">53be664</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"スマホタブレットの入力枠に選択中ハイライトを追加。期間セレクトの見やすさ改善も。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">スマホの入力枠に選択中ハイライト+期間セレクトの文言改善</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">スマホ・タブレットのテンキー入力で血圧などを押しても、PC版と違いどの枠を入力中か分からなかった。また閲覧画面の期間セレクトのグループ見出しがネイティブメニューで薄く表示され読みづらかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>①バイタル・運動の入力枠にPC版と同じ青枠リングの選択中ハイライトを追加。②期間の選択肢自体に「日別・」「月平均・」を明記し、どの端末でもはっきり読めるようにした。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">039eff1</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"期間指定の改善。月別通所状況が指定範囲どおりに。逆転入力防止。日別と月平均のグループ分け。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-08-10</span></div>\n      <p class=\"title\">期間指定の改善(範囲どおりの月別表示・逆転防止・日別/月平均のグループ分け)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">期間指定で月別通所状況が常に12ヶ月分出る、開始と終了を逆に選べてしまう、日別と月平均の選択肢が混ざって見づらい、という指摘があった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>①月別通所状況は指定した年月範囲の月だけ表示。②逆転入力は自動で揃う。③開始未指定=終了の1年前から/終了未指定=今月まで。④期間セレクトを「日別で表示」「月平均で表示」のグループに再編成し、期間指定にも日別/月平均を用意。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9e26cd0</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"家族アプリ\" data-text=\"家族ケアマネ閲覧で8月3日以降のバイタル気分記録が表示されずグラフが止まっていた問題を修正。提供記録テーブルを読むように。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-08-10</span></div>\n      <p class=\"title\">家族・ケアマネ閲覧で8/3以降の記録が表示されない問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">閲覧画面は従来のデータ(巨大JSON)しか読んでおらず、提供記録を専用テーブルに切り替えた8/3以降の新しいバイタル・気分・記録が届いていなかった(グラフが8/3で止まる・今回の記録が空・出席数だけ合う)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>提供記録テーブルを起動時+60秒ごとに取得して表示に反映。</b>15秒ごとの受信が古い凍結データで上書きしないよう保持も追加。削除済みの記録は表示されない。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">50a603d</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"閲覧画面の期間に期間を指定を追加。見たい年月の範囲を自由に選べる。ケアマネ要望。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-08-10</span></div>\n      <p class=\"title\">閲覧画面の期間に「期間を指定」を追加(見たい月を自由に選択)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">期間が1ヶ月/3ヶ月/半年/1年/全期間の固定で、「6月の記録だけ見たい」のような指定ができないとケアマネから要望があった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>期間セレクトに「期間を指定」を追加。年月の範囲(例: 2026年6月〜2026年6月)を選ぶと、その期間のグラフ・記録が表示される。</b>ご家族・ケアマネ両方の閲覧画面で利用可能。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">50a603d</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"削除や変更が一瞬元に戻ってから反映されるちらつきの恒久対策。利用者マスタと月間シフトに手元が新しければ保持のマージを追加。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-10</span></div>\n      <p class=\"title\">削除・変更が「一瞬元に戻ってから反映される」ちらつきの恒久対策</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">クラウド受信は利用者マスタ・月間シフトをクラウドの内容で丸ごと置き換えるため、保存がクラウドへ届く前の受信(4秒ごと)で古い内容に一瞬巻き戻り、保存完了後の受信で再び新しい内容に戻っていた(休止履歴を削除すると一瞬復活する等)。記録・設定・既読には保護があったが、この2つには無かった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>受信時に「手元の方が新しい利用者・シフトは保持」するマージを追加。</b>新規追加直後の利用者も消えない。保持が発生した分は自動で再送信され、確実にクラウドへ反映される。一度設定・削除した内容がそのまま画面に残り続けるようになる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">fcae62a</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"休止の終了日を過ぎても現在休止中が消えない問題を修正。利用を再開ボタンは再開日を入力する方式に変更。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-10</span></div>\n      <p class=\"title\">休止の終了日を過ぎても「現在休止中」が消えない問題を修正+再開日入力式に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">「現在休止中」バナーが利用者の状態フラグを直接見ていたため、休止の終了日(例8/9)を過ぎても「利用を再開」を押すまで表示が消えなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>①日付判定つきの表示ステータスで判定するよう修正。終了日を過ぎると自動で休止表示が消える(家族画面も同様)。②再開ボタンは「再開日を設定」に改名し、再開日の入力画面を出す方式に変更。再開日を入れると休止の終了日=前日を自動記録。未来の再開日ならその日まで休止のまま・当日から自動再開。</b>終了日の直接入力でも過ぎれば自動解除される。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3801685</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"休止履歴の日付入力で西暦が6桁入力できてしまう問題を修正。年4桁制限の独自入力に統一。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-10</span></div>\n      <p class=\"title\">休止履歴の日付入力で西暦が6桁入ってしまう問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">休止履歴の一覧行(終了日)と編集画面(開始日/終了日)がOS標準の日付入力のままで、年を「202622」のように6桁まで入力できてしまっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>年4桁制限・自動送り・クリア(✕)つきの独自日付入力(SmartDateInput)に3箇所とも統一。</b>利用開始/終了日と同じ入力方式になった。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d44389f</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"スマホの血圧入力で自動表示のスラッシュを入力済みと誤認し下の値が上に連結される問題を修正。スラッシュは自分で打った時だけ表示。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-10</span></div>\n      <p class=\"title\">スマホ血圧入力の自動スラッシュ表示をやめる(「1264」誤連結の防止)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">上の血圧だけ入力した段階で枠に「126/」と自動表示されるため、スラッシュが入力済みと誤認して下の値を続けると、実際にはスラッシュが入っておらず「1264」と上の値に連結されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>スラッシュは自分で「/」キーを打った(=下の値がある)時だけ表示。テンキーで入力中の枠は、打った内容(スラッシュ含む)をそのまま表示する。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a53d336</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"基準値の指定せず保存が提供記録入力に反映されない問題を修正し過去全ての記録に反映と日付を指定して反映の2択に改名。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-10</span></div>\n      <p class=\"title\">基準値の反映を「過去全ての記録に反映／日付を指定して反映」の2択に(未反映バグ修正)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">「指定せず保存」は現在値だけ更新して変更履歴を触らないため、過去に日付指定の変更をしたことがある利用者では履歴側が優先され、新しい基準値が提供記録入力のグレー数値に反映されなかった。文言も意味が分かりにくかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>「過去全ての記録に反映」(変更した項目だけを全期間にさかのぼって反映・他項目の日付つき履歴は保持)と「日付を指定して反映」(選んだ日から新値・備考に自動記載)の2択に改名・整理。</b>説明文もモーダル内に明記。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c3f27e9</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"すべて既読ボタンを家族ケアマネ更新と本日のスケジュールにも追加。既読を即クラウド送信し同じスタッフのiPadとPCで既読が同期するように。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-10</span></div>\n      <p class=\"title\">「すべて既読」を全セクションに追加+既読が同じスタッフの全端末で同期</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">「すべて既読」が運営からのお知らせにしか無く、家族・ケアマネからの更新等は1件ずつ開く必要があった。また既読が端末内に留まり、次に何かを保存するまでクラウドへ送信されないため、同じスタッフでもiPadとPCで別々に既読操作が必要だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>「家族・ケアマネからの更新」「本日のスケジュール」にも「すべて既読にする」を追加。既読を付けた瞬間にクラウドへ送信するようにし、同じスタッフの他端末でも数秒で既読が反映される。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c3f27e9</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"提供記録\" data-text=\"振替の取り消しが効かず数秒後や再読み込みで復活する問題を修正。テーブル側の削除が呼ばれていなかった根本原因。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-10</span></div>\n      <p class=\"title\">振替の取り消しが効かない(数秒後・再読込で復活)問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">取り消しはアプリ内データと墓石(削除記録)だけを更新し、提供記録テーブル側の削除処理が一度も呼ばれていなかった。テーブルの行が生き残るため、数秒後の受信や再読み込みで必ず復活。さらに受信側は削除を「当面反映しない」実装だったため、削除が他端末に伝わらなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>①取り消し時に該当idだけをテーブルにも論理削除(推測削除はしない=誤爆防止)。②受信側で明示削除を反映(入力済みバイタルがある新しい記録は保護)。③削除済み記録は再読み込み時のキャッシュ統合・他端末の再送からも復活させない(墓石ガード)。</b>取り消しが1回で確実に効き、全端末に伝わる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9ed1535</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"1\" data-area=\"同期\" data-text=\"店舗切替を完全リロード方式に変更。前店舗のメモリ内データの持ち越しを物理的にゼロにし店舗間混入を根絶。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-09</span></div>\n      <p class=\"title\">店舗切替を「完全リロード」方式に変更(持ち越しの物理的根絶)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">店舗間のデータ混入バグは「切替端末のメモリ内に前店舗のデータが残る」ことが共通の温床だった。既知経路は4重のガードで遮断済みだが、未知の持ち越しまで根絶する構造的対策として運営から切替時リロードの要望があった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>店舗切替の全4経路(管理局からの入店・サイドバー直接切替・店舗一覧へ戻る×2)を「切替先をセッションに保存→ページ完全再読み込み」方式に変更。</b>新店舗として起動し直すため、メモリ内の持ち越しが物理的にゼロになる。切替に数秒かかるようになるが安全性を優先。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ab02134</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"1\" data-area=\"同期\" data-text=\"墓石に出所店舗タグを刻印し他店の墓石を構造的に受け付けない最終防壁。事業者間の干渉防止。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-09</span></div>\n      <p class=\"title\">墓石(削除記録)に店舗タグを刻印 — 他店の墓石を構造的に拒否する最終防壁</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">南水元事故は他店の墓石混入が原因だった。経路自体は遮断済みだが、将来未知のバグで同型の混入が起きた場合に備えた構造的防御が求められた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>同期を通る墓石一式に出所店舗タグ(_store)を刻印し、pull・push・初回シードの全経路で「タグが保存先店舗と食い違う墓石」を丸ごと読み捨てる。</b>タグ無しの既存データは従来どおり扱う(後方互換)。これで仮に混入しても削除は発動しない。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3a45c2e</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"店舗切替時に前店舗の家族アカウントと提供記録がメモリに残り新店舗で表示・書き込みされ得た問題を修正。法人間の情報混入防止。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-09</span></div>\n      <p class=\"title\">店舗切替時に前店舗の家族アカウント・提供記録を持ち越さないよう修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">店舗切替の瞬間、前店舗の家族アカウント一覧と(テーブル方式の)提供記録がメモリ内に残る実装だった。家族アカウントは利用者IDで紐づくため、別店舗の同じIDの利用者に他店(他法人)の家族が表示され得た。前店舗の記録が新店舗の画面に残る経路もあった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>切替時(直前データが別店舗と判明している時)は家族アカウント・招待・提供記録を持ち越さず、新店舗のデータ再取得に任せるよう修正。</b>起動直後の保持(消失防止)は従来どおり維持。あわせて家族一覧の未使用APIにも店舗ID必須化を実施。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3a45c2e</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"運用\" data-text=\"復旧手順書のWebページを新設。症状のキーワード検索と手順コードR-xxでデータ消失時の対処法を引ける。運営用。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">運用</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">復旧手順書のWebページを新設(/api/runbook・症状検索/手順コード付き)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">データ消失事故の対処法を運営側の誰でも確認できるようにし、症状から手順を即座に引ける形が必要になった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>台帳と同じ認証のWebページ /api/runbook を新設。「利用者が消えた」等の症状キーワード検索と、R-00(鉄則)〜R-92(スナップショット設定)の手順コードで対処法・SQL・Claudeへの依頼文例まで表示。</b>技術詳細版はリポジトリ docs/incident-recovery-runbook.md に併設。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">02ecc46</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"店舗切替pullで前店舗の墓石が新店舗へ混入する経路を遮断。南水元全利用者消失の根本原因修正。push側にも店舗不一致ブロックの二重防御。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">店舗切替pullの墓石混入を根本修正(南水元事故の原因)+push店舗ゲート</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">pull時の墓石(削除記録)和集合だけ「直前のデータが同じ店舗のものか」の確認が漏れており、店舗切替直後や放置復帰の自動pullで前店舗の墓石が新店舗に混入。idが重なる利用者・記録が全端末で削除された(試作店の墓石193個→南水元47名全削除の直接原因)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>pull墓石和集合に店舗一致ガード(prev._sbStoreId===newStoreId)を追加。さらにpush入口にも店舗不一致ブロックを追加し、別店舗のスナップショットを書き込めない二重防御に。</b>誰も操作していなくても自動同期だけで発生し得た経路を遮断。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1c94e13</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"運動メニュー個別運動メニューの追加削除が1回目だけ一瞬で元に戻る問題を修正。2回目以降は効くのに1回目だけ巻き戻る。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">運動メニューの追加・削除が1回目だけ元に戻る問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">クラウド定期受信の再同期が未保存判定の基準を一旦リセットした直後に項目を追加/削除すると、編集後の内容がそのまま新基準になり「編集済み」フラグが立たず、次の受信(4〜10秒後)でクラウド値に巻き戻っていた。2回目は基準が残るため差分検知が効き成功していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>運動メニュー系のユーザー操作用セッターを分離し、操作した瞬間に「未保存」を立ててから反映する方式に変更。</b>クラウド同期由来の反映は別経路(生セッター)にして誤検知も防止。1回目から確実に追加・削除できる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1c94e13</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"南水元へ混入した他店墓石を無効化するアムネスティ。利用者47名が全端末で削除され続ける事故の恒久対策。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">南水元の全利用者消失: 混入した他店墓石のアムネスティ(3経路)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">試作店で7/17に一括削除された193名分の墓石(削除記録)が8/7 01:25に南水元のキーへ混入し、利用者47名(id31〜77)が墓石の対象になり全端末で削除され続けた。バックアップから書き戻しても端末に残る墓石が和集合マージで再削除するため復元が定着しない。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>南水元に限り、カットオフ(8/7 14:00 JST)より古い墓石を pull・push・初回シードの3経路すべてで読み捨てる。</b>以後の正規削除は新しい時刻が付くため通常運用に影響しない。8/6バックアップからの利用者47名書き戻しSQLとセットで復旧完了。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">164d140</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"利用者の削除・一括削除を変更ログに端末名つきで明示記録。削除操作の追跡を可能に。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">削除・一括削除を変更ログに明示記録(端末名つき)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">利用者の全削除事案で、削除操作が変更ログから追跡できないことが判明した。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>単体削除は【削除】氏名、一括削除は【一括削除】N名(氏名先頭)を、実行端末名つきで必ず変更ログに記録。</b>誰がいつ消したかを後から追跡できる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6b9fe0f</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"利用者マスタ\" data-text=\"基準値の復元を変更履歴ベースに修正。既定フォールバックでは店舗独自の項目idと一致せず未設定のままだった。履歴の直近リストから項目とidを復元し基準値が正しく復活。全削除はフラグで尊重。eb16559\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">基準値の復元を「変更履歴からの復元」に修正(独自項目のidごと復活)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">前回の既定項目フォールバックでは、店舗独自の運動項目id(基準値のキー)と一致せず、基準値が未設定のまま表示されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>空/未設定時は変更履歴(exerciseItemsHistory)に残る直近の項目リストから復元するよう修正。店舗独自の項目名とidが戻り、利用者の基準値も正しく復活する。運動メニューを全削除した場合はフラグで空を尊重(勝手に復活しない)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">eb16559</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"1\" data-area=\"同期\" data-text=\"データ保護ゲート2件: 管理者自動連携の書込をクラウド初回反映後に制限。退所自動削除に不正日付/年数の防護と墓石処理を追加。eb16559\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">データ保護の強化(自動書込ゲート・退所自動削除の防護)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">起動直後の古い/空のローカルスナップショットからの自動書込や、日付入力バグの残骸(不正な終了日)による退所自動削除の誤作動が、データ消失の潜在リスクだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>管理者自動連携の書込は「クラウド初回反映後」のみに制限。退所自動削除は年数2/5のみ有効・終了日が2020年未満/未来年ならスキップし、削除時は墓石まで一括処理して他端末との不整合を防ぐ。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">eb16559</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"利用者マスタ\" data-text=\"サービス提供内容の基準値が全員分消えて見える問題を修正。運動メニュー項目が空配列で上書きされるとフォールバックが効かず全画面から運動列と基準値が消えて見えた。空は既定項目へフォールバックし基準値は自動復活。ee0dfe9\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">基準値(運動メニュー)が全員分消えて見える問題を修正(自動復活)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">運動メニュー項目(exerciseItems)が設定不具合で空([])に上書きされると、空配列は「設定あり」と判定され既定項目に切り替わらず、利用者マスタの基準値・提供記録の運動列が全員分消えて見えていた。利用者側の基準値データ自体は残っていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>空配列を「未設定」とみなして既定の運動項目へフォールバックする処理を全33箇所に適用。既定項目が表示されることで、残っていた基準値も自動的に復活する。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ee0dfe9</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"管理者名の自動連携。スタッフ切替/日誌の管理者を事業所情報へ常時反映し表示のみに。サ責は未設定なら管理者を既定に。ee0dfe9\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">管理者名を自動連携(事業所情報は表示のみ)・サ責の既定値</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">初回に管理者を登録しても事業所情報の管理者名は手入力が必要で、二重管理でズレも起きていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>スタッフ切替/日誌で登録した「管理者」を事業所情報の管理者名へ常に自動反映し、各種設定では表示のみ(編集不可)に。サービス提供責任者は未設定なら管理者を既定にセット(後から変更可)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ee0dfe9</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"実績登録\" data-text=\"実績登録を月間一覧/利用者ごとのタブ構成に。サービスコード複数割当とCSV取込(国/自治体コード表・UTF-8/Shift_JIS)を追加。ee0dfe9\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">実績登録</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">実績登録を改良(利用者ごと表示・複数コード割当・コードCSV取込)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">実績登録が全体一覧のみで使いづらく、サービスコードは複数登録が必要、国/自治体のコード表CSVも取り込みたいとの要望。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>「月間一覧」「利用者ごと」のタブ構成に(氏名クリックで個人詳細)。利用者ごとにサービスコードを複数割当でき、日別実績(状態/時間帯/サービス内容/備考)を一覧表示。コード表CSVは文字コード自動判別で解析しプレビューから選択取込。画面はつむぎ独自仕様。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ee0dfe9</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"サイドバー最下部に利用規約・同意ポリシーの閲覧を追加(全スタッフ・事業所向け/家族向けタブ)。家族・ケアマネ画面は既設を確認。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">サイドバーに「利用規約・同意ポリシー」の閲覧を追加</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">同意ポリシー編集を運営(管理局)専用に集約したため、事業所側でも内容をいつでも確認できる入口が必要になった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>サイドバー最下部(不具合を運営に報告の下)に閲覧ボタンを追加。</b>事業所・スタッフ向け/ご家族・関係者向けをタブで切替表示(版・改定日つき)。ご家族・ケアマネ画面には報告/規約の入口が既設であることを確認。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">51c8402</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"各種設定\" data-text=\"各種設定の事業所情報や項目管理が消える問題の恒久対策。ローカルstateがマウント時のまま古く、保存で古いスナップショットが最新値を上書きしていた。3層対策+facilityInfoサブ項目マージ。ecdf40e\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">各種設定</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">各種設定の登録内容(事業所情報・項目管理等)が消える問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">各種設定のローカル状態はマウント時に1回だけ初期化され、以後クラウドから最新が来ても古いまま。保存すると古いスナップショットが最新時刻で丸ごと書かれ、後から登録した事業所情報・項目管理・ケアマネ等を消していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>3層の恒久対策: ①マウント時基準を記録 ②クラウド同期で未編集の画面を最新へ自動再同期 ③保存は「実際に編集した項目だけ」を最新へ重ねる(事業所情報はサブ項目単位)。同期マージも事業所情報をサブ項目単位(fi:)で刻印・マージ。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ecdf40e</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"実績登録\" data-text=\"サイドバーに実績登録を新設(分析稼働から移設)。サービスコードの登録と利用者割当を追加しCSVにも出力。91472e8\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">実績登録</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">サイドバーに「実績登録」を新設(サービスコード登録・割当つき)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">月次実績表を分析(稼働)内に置いていたが、毎月の請求転記業務として独立した入口が欲しい+サービスコードも必要との要望。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>サイドバーに「実績登録」を新設して月次実績表を移設。サービスコードの登録(コード+名称)と利用者ごとの割当を追加し、表とCSVに出力。割当・台帳とも項目単位保護で同期安全。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">91472e8</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"同意ポリシー編集の案内を各種設定から撤去(管理局専用)。不具合を本部に報告→運営に報告へ名称変更。ecdf40e\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">同意ポリシー編集を各種設定から撤去・「不具合を運営に報告」に名称変更</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">同意ポリシーはアプリ運営(管理局)が全店共通で管理するため、各事業所の設定画面には不要。報告先の名称も実態に合わせる。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>各種設定のサービス提供内容から同意ポリシー編集の案内を撤去(編集は管理局専用のまま)。サイドバーの「不具合を本部に報告」を「不具合を運営に報告」へ変更。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ecdf40e</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"分析\" data-text=\"分析(稼働)に月次実績表を追加。提供記録の実績(出席/振替/臨時)を利用者×日のマトリクスで表示し、実績回数・日別合計・CSV出力・印刷PDFに対応。カイポケ等への実績転記を高速化。分析1d7b862\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">月次実績表を追加(カイポケ等への実績転記用・CSV/印刷対応)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">毎月の請求ソフト(カイポケ等)への実績入力で、つむぎの記録を1件ずつ確認しながら転記する手間がかかっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>分析(稼働)の下部に月次実績表を追加。</b>出席○/振替/臨時/欠席を利用者×日のマトリクスで一覧でき、行末に実績回数・最下行に日別合計。前月/翌月切替・CSV出力・印刷/PDF(A4横)対応。日付整合ゲートで残骸は実績に混ぜない。読み取り専用で同期への影響なし。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1d7b862</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"計画書\" data-text=\"LIFEの傷病名マスタ約2.7万件を同梱し、個別機能訓練計画書のLIFE提出用コードに病名検索を追加。病名で検索して選ぶとコードが自動入力される。ひらがなカタカナ全角半角も吸収。計画書91aba3a\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">LIFE傷病名マスタ同梱+計画書に病名検索(コード自動入力)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">LIFE提出用の傷病名コードは7桁の手入力のみで、コードを調べる手間がかかっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>厚労省の傷病名マスタ約2.7万件を同梱し、個別機能訓練計画書(3-3)のLIFE提出用コードに病名検索を追加。</b>病名で検索して選ぶとコードが自動入力される(ひらがな・カタカナ・全角半角も吸収)。マスタは初回検索時にだけ読み込むためアプリは重くならない。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">91aba3a</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"デザイン\" data-text=\"ブラウザのタブ/ブックマークのアイコンが白背景で見づらいのを、正式マーク無加工のまま淡い緑の角丸チップ土台に載せた合成faviconで解消。ライト/ダーク両テーマで視認可。デザインe1e19a7\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">デザイン</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">タブ/ブックマークのアイコンを見やすく(角丸チップの土台を追加)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ブラウザのライトモードでタブ/ブックマークのアイコンが白背景に溶けて見づらかった(マークが淡く小さい)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>正式マークPNGを無加工のまま、淡い緑グラデの角丸チップ+縁取りに載せた合成faviconに差し替え。</b>ライト/ダークどちらのテーマでもチップの土台で視認できる。ロゴ自体は描き直していない。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e1e19a7</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"マニュアル\" data-text=\"操作マニュアルのヘッダーロゴを中央寄せにし、つむぎとはを機能紹介中心に簡潔化。名前の由来の段落を削除。もくじ表記も統一。マニュアル4a71ec6\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">マニュアル</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">マニュアルのロゴ中央寄せ・「つむぎとは」を機能紹介中心に簡潔化</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">マニュアルのロゴが左寄せで表題と揃わず気になる、「つむぎとは（名前の由来）」は機能の簡単な説明でよい、との指摘。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>ヘッダーロゴを中央寄せ(margin:0 auto)にし、もくじ/見出しを『つむぎとは』に統一。名前の由来の段落を削除し、つむぎで何ができるかの簡単な説明のみにした(3マニュアル共通)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4a71ec6</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"ホームのお知らせ類をもっと見るからページ送り(＜1 2 3＞)に変更し高さを揃えた。更新内容モーダルは起動後に増えた今回分だけ表示。サイドバーの計画書だけ左詰めだったのを中央寄せに統一。ホームc76dc47\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">ホームをページ送り化・更新モーダルを今回分のみ・計画書の左詰め修正</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ホームのお知らせが下に長く伸びて見づらい、事業所お知らせが長いと左カラム下部に空白ができる、更新モーダルが3件全部出て今回分が分かりにくい、計画書サイドバーだけ左詰め、という指摘。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>お知らせ類を『＜ 1 2 3 ＞』のページ送りに変更(運営3件/家族更新5件/お知らせ5件/頁)。更新内容モーダルは起動後に増えた今回分だけ表示。計画書サイドバーのtext-leftを外して他と中央寄せに統一。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c76dc47</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌で振替の重複記録により利用者が二重表示される問題を修正。提供記録入力連絡帳は解消済みだったが日誌はticketRecordsをそのまま行にしていた。出席者テーブルと送迎割り当てで利用者ID単位に重複排除。日誌f3a83d4\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">日誌で振替の重複により利用者が二重表示される問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">日誌は提供記録をそのまま行にしており、同一利用者・同一日の複数記録(振替の重複)で二重に出ていた(提供記録入力・連絡帳は解消済み)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>日誌の出席者テーブルと送迎割り当ての両方で利用者ID単位に重複排除(データの多い方を優先)。</b>連絡帳・提供記録入力と同じ扱いに統一。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f3a83d4</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"スケジュール\" data-text=\"スケジュールの予定作成で対象利用者に休止中の方も選べるようにした。担当者会議等が休止中でもあるため。退所は除外。スケジュールa1674be\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">スケジュール</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">スケジュールの利用者選択に休止中の方も含める</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">予定作成の対象利用者が「利用中」のみで、休止中でも担当者会議等がある方を選べなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>利用中と休止中の両方を選択可にした(退所は除外)。</b>休止中は名前に「（休止中）」を付けて区別。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a1674be</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"連絡帳\" data-text=\"連絡帳の個別連絡事項を消しても復活して削除できない問題を修正+削除ボタン追加。個別連絡事項が項目単位保護の対象外で、同期のキー単位バックフィルにより空にしてもクラウドの旧本文で復活していた。連絡帳86389a8\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">連絡帳の個別連絡事項が削除できない問題を修正(削除ボタンも追加)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">個別連絡事項(contactBookRenraku)が項目単位保護の対象外で、同期マージのキー単位バックフィルにより、本文を空にしてもクラウドの旧本文で補完(復活)され削除できなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>個別連絡事項を項目単位保護(_fieldTs)に追加し、明示的な削除(空)が確実に残るようにした。</b>あわせて連絡事項の各セクション(個別・全体)に「削除」ボタンを追加し、本文と表示期間を空にできるようにした。全体は元々削除可能だが操作を統一。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">86389a8</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"ホームのお知らせ類を上位N件+もっと見るに整理して高さを揃えた。運営からのお知らせは上位3件、家族ケアマネからの更新とお知らせは上位5件、残りはもっと見るで開閉。ホーム17ce8e3\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">ホームのお知らせ類を上位N件+もっと見るに整理(高さを揃える)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ホームのお知らせ/更新カードが件数によって高さがバラバラだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>つむぎ運営からのお知らせは上位3件、家族・ケアマネからの更新とお知らせは上位5件を表示し、残りは「もっと見る」で開閉。</b>既定を上位のみにすることで本日のスケジュール等と並ぶカードの高さが揃う。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">17ce8e3</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"利用者マスタ\" data-text=\"基本利用曜日を変更すると月間スケジュールがその曜日空欄になる問題を修正。適用開始日を未来にすると当月が空欄になり、変更履歴も累積して曜日を空欄へ巻き戻していた。今日からボタン追加+同曜日のapplyFrom以降の古い履歴を除去。利用者マスタ2efbed7\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">基本利用曜日の変更で月間スケジュールが空欄になる問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">適用開始日(applyFrom)を未来日にすると、その日より前(当月)は「まだ利用曜日でない」扱いで空欄になり、さらに変更のたびに変更履歴が累積して古い履歴がその曜日を空欄へ巻き戻していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>適用開始日に『今日から(すぐ反映)』ボタンを追加し、再設定時は同じ曜日のapplyFrom以降の古い履歴を除去。</b>既に空欄になった利用者は、基本利用曜日を無→対象に設定し直せば直る(記録は削除されておらず表示で隠れていただけ)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2efbed7</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"日付入力にクリア(✕)ボタンを追加=利用終了日を確実に空にできる。一部だけ消して外すと元に戻り終了日が消せず、退所扱いのまま提供記録入力に出ない/月間スケジュールが空欄になっていた問題の逃げ道。記録は削除されておらず表示フィルタで隠れていただけ。利用者マスタ74dd12a\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">日付入力にクリア(✕)を追加=利用終了日が確実に消せる</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">独自日付入力で一部だけ消してフォーカスを外すと元の値に戻る挙動があり、年を残したまま消そうとすると利用終了日がクリアできず、退所扱いのまま提供記録入力に出ない/月間スケジュールが空欄になっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>値があるとき✕(クリア)ボタンを表示し、押すと年月日を確実に空にする。</b>利用終了日をクリアすれば退所扱いが解け再表示される。記録データは削除されておらず表示で隠れていただけなので再入力は不要。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">74dd12a</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"提供記録\" data-text=\"利用終了日をクリアしても提供記録入力に利用者が戻ってこない問題を修正2a89490\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">終了日クリア後も提供記録入力に利用者が出ない問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">提供記録入力の一覧シードのdepsが利用者数(length)で、終了日など内容の変更では再シードされず、終了日をクリアしても一覧に戻らなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>開始/終了日・状態・基本利用曜日のシグネチャをdepsに追加し、終了日クリアで即一覧へ戻るようにした。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2a89490</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"月間スケジュールで利用終了日より後を空欄(非利用日)にして終了箇所を明確化2a89490\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">月間スケジュールで利用終了日以降を空欄にして一目で分かるように</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">利用終了しても月間スケジュールに出席等が表示され、どこで終了したか分かりにくかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>利用終了日より後(・開始日より前)の日を空欄(非利用日)にし操作不可に。利用中に戻せば出席等が再表示される。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2a89490</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"年月日の日付入力を独自入力に置換(年4桁・日フル入力・年→月→日自動送り)00a310d\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">日付入力を独自入力にして年4桁制限・日のフル入力・自動送りに対応</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">OS標準の日付入力は年が6桁入る/日を1桁で確定して2桁目が打てない等、ブラウザ依存で入力しづらかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>独自のSmartDateInputを新設し、利用開始日/終了日・休止の開始/終了日を置換。年は4桁まで、月/日の途中1桁は確定せず2桁目やフォーカス移動を待ち、年→月→日へ自動送り。カレンダーピッカーも利用可。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">00a310d</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"利用者マスタ\" data-text=\"利用終了日をクリアしても勝手に元に戻る(退所済みに戻る)問題を修正fed6fa9\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">利用終了日のクリアが元に戻る(退所に戻る)問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">利用開始日/終了日がフィールド単位保護の対象外で、クリアしても『空欄のみ補完』により古い端末の値が復活し、退所済みにも戻っていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>開始日/終了日を項目単位時刻(_fieldTs)保護の対象に追加。明示的なクリアが刻印され新しい方(空)が優先されるため、クリアが確実に残る。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">fed6fa9</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"休止の理由/期間が出席後も特記に残る・取り消し後も特記が残る問題を修正fed6fa9\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">休止/取り消しの特記が残り続ける問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">休止の理由/期間を特記に焼き込んでいたため休止終了後も残り、また振替/欠席の取り消し後も特記が残っていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>休止の理由/期間は表示のみ(保存しない・pauseHistoryが保持)にし、休止終了で特記から消える。過去に焼き付いたラベルも表示時に除去。取り消し時は特記(○へ振替/欠席理由)を完全クリア。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">fed6fa9</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"連絡帳\" data-text=\"提供記録入力の保存で次回予定(次回利用日/お迎え時間)が消える問題を修正f1b51ac\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">提供記録入力を保存すると次回予定(日付・時間)が消える問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">提供記録入力の保存時レコード再構築に次回予定(nextDateOverride/nextTimeOverride)が含まれず、他項目を保存するたびに次回予定が欠落していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>提供記録入力では次回予定を編集しないため既存値を必ず引き継ぐようにし、他項目を保存しても次に変更するまで残るようにした。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f1b51ac</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"提供記録\" data-text=\"振替の人が連絡帳/提供記録入力で二重表示・終了血圧が片方に寄る問題を修正8bee647\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">振替の二重表示・終了血圧/脈が片方で消える問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">振替/欠席の記録IDがランダムだったため、同一利用者・同一日に複数行ができ、findが拾った片方に無い終了血圧/脈が消えて見え、連絡帳では二人表示になっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>振替/欠席の記録IDを決定的ID(tr_患者_年_月_日)に統一して重複を防止。提供記録入力は同一日の複数記録を非空で統合表示、連絡帳は1件に絞って二重表示を解消。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8bee647</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"提供記録\" data-text=\"振替/欠席の取り消し・出席戻しでバイタル等が消える問題を修正2093934\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">振替/欠席の取り消し・出席戻しで記録が消える問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">取り消し系(振替取り消し/状態クリア/出席戻し)が記録を無条件に削除(墓石登録)していたため、入力済みのバイタル・気分・運動・整体ごと消えていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>データのある記録は削除せず出席として保持(振替の目印tokkiは消す)、データの無い空枠だけ削除するように統一。誤って振替/欠席にしても取り消せば元どおり、特記の「○へ振替」も消える。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2093934</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"提供記録\" data-text=\"欠席/休業/振替で既存の記録を消さないよう修正+過去日を欠席等にする時の警告(運動/整体/特記や過去日の血圧/脈が消える)提供記録入力の状態変更で欠席・休業・振替元の記録を既存を無視して全項目空で作り直していた。既存があればバイタル・気分・運動・整体・特記を保持し状態だけ変更するよう統一。さらに提供記録入力と月間スケジュールの両方で過去日を欠席/休業/振替/休止に変更する時に確認警告を表示。提供記録27b765b\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">欠席/休業/振替で記録が消える問題を追加修正+過去日の状態変更に警告</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">前回の振替修正後も、提供記録入力の状態変更で欠席・休業・振替元の記録を既存を無視して全項目空で作り直していたため、運動・整体・特記や、過去日を欠席にした日の血圧・脈などが消えていた(休止だけは既存を保持して正しく動作)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>欠席・休業・振替元も、既存の記録があればバイタル・気分・運動・整体・特記・項目別時刻を保持し状態だけ変更するよう統一。</b>間違えて欠席にしても消えず、出席に戻せば元どおりになる。さらに提供記録入力・月間スケジュールの両方で、過去日を欠席/休業/振替/休止に変更する時に確認警告を表示。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">27b765b</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"提供記録\" data-text=\"振替設定で振替先の入力済みバイタル等が消える問題を修正(状態が振替の人の血圧・気分・脈・運動が消える)振替の設定処理で、振替先の日に既に記録があっても全項目を空で作り直し新しい保存時刻を付けて上書きしていたため、その日に来所して入力済みだったバイタル・気分・運動・整体が振替設定のたびに消えていた。振替先に既存記録がある場合は既存の入力を保持し状態のみ振替に変更するよう修正。提供記録25a2956\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">振替の方の血圧・気分・脈・運動などが消える問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">振替の設定処理で、振替先の日に既に記録があっても全項目を空で作り直し、新しい保存時刻を付けて上書きしていた。その日に来所して入力済みだったバイタル・気分・運動・整体が、振替設定のたびに消えていた(同期でも新しい方が勝つため他端末にも波及)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>振替先に既存の記録がある場合は、体温・血圧・脈・気分・運動・整体・特記・項目別時刻(_fieldTs)を保持したまま、状態だけを振替に変更するよう修正。</b>新規の振替先のみ従来どおり空で作成。データを消さない方向のみの変更で同期の安全性は不変。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">25a2956</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"お知らせ\" data-text=\"更新内容を確認できる仕組みを追加(更新バナー+ホームにライブ反映)「新しいバージョンがあります」と出ても何が変わったか分からず、更新してよいか迷うという声があった。静的ファイル(update-notes.json)を旧バージョンでもライブ取得し、更新バナーに「更新内容を確認」ボタン(モーダル表示)を設置。ホームのつむぎ運営からのお知らせにも再読み込みなしで反映。同期やデータ書き込みは行わない読み取り専用。お知らせ7b57cde\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">お知らせ</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">更新内容を確認できる仕組みを追加(更新バナー+ホームにライブ反映)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">「新しいバージョンがあります」と表示されても何が変わったか分からず、更新してよいか迷うという声があった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>更新バナーに「更新内容を確認」ボタンを設置し、押すと今回の更新内容をモーダルで表示。</b>静的ファイル(update-notes.json)を旧バージョンでもライブ取得(60秒ごと)するため、ホームの「つむぎ運営からのお知らせ」にも再読み込みなしで反映される。同期・データ書き込みは行わない読み取り専用。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7b57cde</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"デザイン\" data-text=\"アプリロゴを新デザイン(握手マーク)に刷新従来の四つ葉クローバーから、支え合い・つながり・未来を紡ぐ想いを込めた握手マークの正式ロゴへ刷新。ログイン画面・サイドバー上部・favicon・3種マニュアル(事業所/関係者/家族)の表紙ロゴを新デザインに統一し、サイドバーのマークを拡大。ロゴの意味の解説はマニュアルからは外し今後のLPへ掲載予定。ロゴは正式PNGをそのまま画像として使用(描き直しなし)。デザイン994be51\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">デザイン</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">アプリロゴを新デザイン(握手マーク)に刷新</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">従来の四つ葉クローバーから、支え合い・つながり・未来を紡ぐ想いを込めた握手マークの正式ロゴへ刷新することにした。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>ログイン画面・サイドバー上部・favicon・3種マニュアルの表紙ロゴを新デザインに統一。</b>ロゴの意味の解説はマニュアルには載せず今後のLPへ掲載予定。サイドバーのマークを拡大し、ロゴは正式PNGをそのまま画像として使用(SVG等で描き直さない)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">487041d</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"連絡帳\" data-text=\"入力済みの次回お迎え時間が時間経過で全て消える次回時間の欄に触れて閉じただけでも毎回保存が走り、空値や自動計算値が新しい時刻付きで記録され、同期(新しい方が勝つ)が他端末で入力済みの時間を次々と上書きしていた。「実際に値が変わった時だけ」書き込むガードを追加。現在値と同じ・実質未設定欄への空や自動計算値と同内容の書き込みは行わない。値のある欄の意図的クリアは従来どおり反映。連絡帳8b52d13\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">入力済みの次回お迎え時間が時間経過で全て消える</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">次回時間の欄に触れて閉じただけでも毎回保存が走り、空値や自動計算値が新しい時刻付きで記録され、同期(新しい方が勝つ)が他端末で入力済みの時間を次々と上書きしていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>「実際に値が変わった時だけ」書き込むガードを追加。現在値と同じ・実質未設定欄への空や自動計算値と同内容の書き込みは行わない。値のある欄の意図的クリアは従来どおり反映。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8b52d13</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"バイタル範囲外入力の警告バナー(体温7・血圧1257等の桁違い検知)体温「7」血圧「1257」のような桁違い入力がそのまま記録され、後から気付けなかった。体温30〜43/血圧上50〜250/血圧下30〜150/脈拍30〜200の範囲外を入力すると画面上部に赤い警告を8秒表示。入力自体は止めず記録の自由は保つ。tab移動時とテンキーを閉じる時に判定。提供記録58babdf\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">バイタル範囲外入力の警告バナー(体温7・血圧1257等の桁違い検知)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">体温「7」血圧「1257」のような桁違い入力がそのまま記録され、後から気付けなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>体温30〜43/血圧上50〜250/血圧下30〜150/脈拍30〜200の範囲外を入力すると画面上部に赤い警告を8秒表示。入力自体は止めず記録の自由は保つ。Tab移動時とテンキーを閉じる時に判定。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">58babdf</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"同期\" data-text=\"提供記録だけを編集中に「同期停止」の誤警告が出る問題を解消テーブル方式では提供記録の保存が巨大jsonのpush-okを発生させず、同期停止検知(stall)が誤作動していた。テーブル書き込み(rows-upsert)成功を同期成功として記録するように変更。同期58babdf\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">提供記録だけを編集中に「同期停止」の誤警告が出る問題を解消</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">テーブル方式では提供記録の保存が巨大JSONのpush-okを発生させず、同期停止検知(stall)が誤作動していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>テーブル書き込み(rows-upsert)成功を同期成功として記録するように変更。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">58babdf</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"連絡\" data-text=\"各種連絡: 保存ボタン・本文の書式(文字サイズ/下線)・入力内容からの定型文作成保存ボタンが無く休み連絡と操作感が不統一。fax向けに文字を大きく/下線を引きたい。作成済みの本文を定型文として使い回したい(店舗要望)。右上に保存ボタン(押すと✓保存しました表示)。本文と定型文に文字サイズ(標準/大/特大)と下線の書式を追加(faxのため色は無し)。「今の入力内容から定型文を作成」で件名→タイトル・本文→内容の編集画面を開けるように。連絡11fdfb4\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">連絡</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">各種連絡: 保存ボタン・本文の書式(文字サイズ/下線)・入力内容からの定型文作成</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">保存ボタンが無く休み連絡と操作感が不統一。FAX向けに文字を大きく/下線を引きたい。作成済みの本文を定型文として使い回したい(店舗要望)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>右上に保存ボタン(押すと✓保存しました表示)。本文と定型文に文字サイズ(標準/大/特大)と下線の書式を追加(FAXのため色は無し)。「今の入力内容から定型文を作成」で件名→タイトル・本文→内容の編集画面を開けるように。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">11fdfb4</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"端末名設定: 保存済みの名前を常時表示・ブラウザ自動入力の混入を抑止保存した端末名がどこにも確定表示されず、ブラウザが保存済みログインid等を端末名欄へ自動入力してしまう事象があった(店舗報告)。「現在の端末名: ◯◯(保存済み/未設定)」を常時表示。入力欄に自動入力抑止属性を付与。各種設定8b54f1c\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">端末名設定: 保存済みの名前を常時表示・ブラウザ自動入力の混入を抑止</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">保存した端末名がどこにも確定表示されず、ブラウザが保存済みログインID等を端末名欄へ自動入力してしまう事象があった(店舗報告)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>「現在の端末名: ◯◯(保存済み/未設定)」を常時表示。入力欄に自動入力抑止属性を付与。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8b54f1c</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"休業日は選択・閲覧可能に/定休日に開いたら次の営業日を初期表示休業日は日付選択で強制的に別日へずらされ、記録確認や事後入力ができなかった。定休日(土日)に開くと定休日自身が表示されていた(店舗要望)。日付選択は定休日だけ営業日へずらし、休業日は選択・閲覧可能に。起動時に今日が定休日なら前方の次の営業日を初期表示(休業日もスキップ)。提供記録698e48e\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">休業日は選択・閲覧可能に/定休日に開いたら次の営業日を初期表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">休業日は日付選択で強制的に別日へずらされ、記録確認や事後入力ができなかった。定休日(土日)に開くと定休日自身が表示されていた(店舗要望)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>日付選択は定休日だけ営業日へずらし、休業日は選択・閲覧可能に。起動時に今日が定休日なら前方の次の営業日を初期表示(休業日もスキップ)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">698e48e</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"休止の入力ロックが休止期間外の日まで効いていたマスタの現在ステータス(休止)だけで判定しており、休止期間前の日や終了日以降まで提供記録の入力欄がロックされていた(店舗報告)。期間判定(getpausereasonondate)に差し替え、休止期間内の日だけ入力不可に。期間情報の無い休止のみ従来どおり常時ロック。提供記録b2762fe\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">休止の入力ロックが休止期間外の日まで効いていた</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">マスタの現在ステータス(休止)だけで判定しており、休止期間前の日や終了日以降まで提供記録の入力欄がロックされていた(店舗報告)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>期間判定(getPauseReasonOnDate)に差し替え、休止期間内の日だけ入力不可に。期間情報の無い休止のみ従来どおり常時ロック。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b2762fe</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"更新バナーを「必ず再読み込みしてください」と強い表示に更新バナーが弱く再読み込みされないまま古いビルドで使い続けられ、同期不具合の原因になっていた(店舗要望)。「⚠ 新しいバージョンがあります。必ず再読み込みしてください」に文言・配色を強化。各種設定ec26967\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">更新バナーを「必ず再読み込みしてください」と強い表示に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">更新バナーが弱く再読み込みされないまま古いビルドで使い続けられ、同期不具合の原因になっていた(店舗要望)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>「⚠ 新しいバージョンがあります。必ず再読み込みしてください」に文言・配色を強化。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ec26967</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"右上「詳細設定」を「印刷設定」に名称変更内容が印刷(面数/用紙/補助線)の設定であり名称が実態と合っていなかった(店舗要望)。ボタンとパネルの名称を「印刷設定」に統一。連絡帳ec26967\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">右上「詳細設定」を「印刷設定」に名称変更</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">内容が印刷(面数/用紙/補助線)の設定であり名称が実態と合っていなかった(店舗要望)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>ボタンとパネルの名称を「印刷設定」に統一。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ec26967</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"次回予定の「変更済」判定をマスタ自動計算値との差分に変更値の有無だけで判定していたため、欄に触れただけの人まで「変更済」表示になっていた。サービス提供内容(マスタ)由来の自動計算値から実際に変わっている時だけ表示。意図的な「未定」は変更として扱う。連絡帳ec26967\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">次回予定の「変更済」判定をマスタ自動計算値との差分に変更</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">値の有無だけで判定していたため、欄に触れただけの人まで「変更済」表示になっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>サービス提供内容(マスタ)由来の自動計算値から実際に変わっている時だけ表示。意図的な「未定」は変更として扱う。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ec26967</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"次回お迎え時間が「分から入力すると消える」・空白の見えない値で変更済み扱いになる空入力時に「　時　分」(空白文字入り)を記録へ書き込み、①触っただけで変更済 ②モーダルで数字が取り出せず空白表示 ③同期で実際の入力時間を打ち負かす毒データになっていた。時刻分解も時が無いと分を読めなかった。空は空のまま返す(毒データを書かない)。数字の無い残骸は自動計算値で表示し編集可能に。分単独の入力も保持する時刻分解に修正。連絡帳9aab5c6\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">次回お迎え時間が「分から入力すると消える」・空白の見えない値で変更済み扱いになる</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">空入力時に「　時　分」(空白文字入り)を記録へ書き込み、①触っただけで変更済 ②モーダルで数字が取り出せず空白表示 ③同期で実際の入力時間を打ち負かす毒データになっていた。時刻分解も時が無いと分を読めなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>空は空のまま返す(毒データを書かない)。数字の無い残骸は自動計算値で表示し編集可能に。分単独の入力も保持する時刻分解に修正。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9aab5c6</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"提供記録\" data-text=\"「元に戻す」が完全に無反応(復元機能が全く効かない)recordviewにdevicenameが渡されないまま復元処理が参照しており、「戻す」を押すと未定義エラーで処理が即死していた。さらに確認ダイアログが2連続でブラウザに抑止される問題も重なっていた。devicenameをpropsに追加。確認はブラウザ依存のconfirmをやめアプリ内ダイアログ(1回だけ)に変更。復元履歴に「戻した後の内容」サマリ(体温/血圧/気分/運動/整体の件数)も追加。提供記録5f89404\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-03</span></div>\n      <p class=\"title\">「元に戻す」が完全に無反応(復元機能が全く効かない)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">RecordViewにdeviceNameが渡されないまま復元処理が参照しており、「戻す」を押すと未定義エラーで処理が即死していた。さらに確認ダイアログが2連続でブラウザに抑止される問題も重なっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>deviceNameをpropsに追加。確認はブラウザ依存のconfirmをやめアプリ内ダイアログ(1回だけ)に変更。復元履歴に「戻した後の内容」サマリ(体温/血圧/気分/運動/整体の件数)も追加。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5f89404</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"1\" data-area=\"同期\" data-text=\"提供記録を「1記録=1行」のテーブル方式へ移行(カットオーバー)巨大json方式は全記録を1行に保存するため、多端末の同時入力で衝突・上書き消失が構造的に発生していた(7/30の保存全滅事故もこの構造が原因)。ticket_recordsテーブルへ移行。プレビュー3日間の検証で、受信マージの項目時刻対応(明示クリアが伝わる/事故は守る)・運動○のキー単位同期(1タップで他端末の○が全滅するバグ修正)・空欄増幅ガード・起動時取込の一本化・書込失敗の自動再送キュー・容量超過時の軽量保存・復元のフル書込など9件を修正した上で、営業前に全店再シードして切替。稼働初日を無事完走。同期62f5fe0\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">提供記録を「1記録=1行」のテーブル方式へ移行(カットオーバー)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">巨大JSON方式は全記録を1行に保存するため、多端末の同時入力で衝突・上書き消失が構造的に発生していた(7/30の保存全滅事故もこの構造が原因)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>ticket_recordsテーブルへ移行。プレビュー3日間の検証で、受信マージの項目時刻対応(明示クリアが伝わる/事故は守る)・運動○のキー単位同期(1タップで他端末の○が全滅するバグ修正)・空欄増幅ガード・起動時取込の一本化・書込失敗の自動再送キュー・容量超過時の軽量保存・復元のフル書込など9件を修正した上で、営業前に全店再シードして切替。稼働初日を無事完走。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">62f5fe0</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌の過去日の編集ロックを廃止過去分の記入漏れを追記しにくかった(店舗要望)。過去日付も常時編集可能に変更。日誌00e83ac\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-01</span></div>\n      <p class=\"title\">日誌の過去日の編集ロックを廃止</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">過去分の記入漏れを追記しにくかった(店舗要望)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>過去日付も常時編集可能に変更。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">00e83ac</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"復元履歴に「(状態)他17名」など触っていない人まで表示される直前スナップショットに存在しない人は既定の「状態=出席」だけでも変更扱いになり、初回保存で全員が差分表示されていた。初出の人は実際に触った項目や既定以外の状態だけを表示。最古の履歴は差分を出さず「この日の最初の保存」とだけ表示。提供記録00e83ac\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-01</span></div>\n      <p class=\"title\">復元履歴に「(状態)他17名」など触っていない人まで表示される</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">直前スナップショットに存在しない人は既定の「状態=出席」だけでも変更扱いになり、初回保存で全員が差分表示されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>初出の人は実際に触った項目や既定以外の状態だけを表示。最古の履歴は差分を出さず「この日の最初の保存」とだけ表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">00e83ac</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"2台同時編集で保存が全滅する(変更が保存されず変更ログが凍結)1台の端末が全記録の保存(cas書き込み)を同時に複数本並行実行し、自分同士で衝突→リトライ上限超過(conflict-retries-exhausted)で保存が失敗し続けていた。店舗単位でcas書き込みを直列化(同時に1本だけ)。各書き込みは実行時に最新versionを取り直すため内容は正しいまま。同期5787ed3\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-30</span></div>\n      <p class=\"title\">2台同時編集で保存が全滅する(変更が保存されず変更ログが凍結)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">1台の端末が全記録の保存(CAS書き込み)を同時に複数本並行実行し、自分同士で衝突→リトライ上限超過(conflict-retries-exhausted)で保存が失敗し続けていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>店舗単位でCAS書き込みを直列化(同時に1本だけ)。各書き込みは実行時に最新versionを取り直すため内容は正しいまま。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5787ed3</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"新規登録の基本利用日を半日型に合わせam/pmのみに新規登録に付けた基本利用日の切替に「1日(全日)」が含まれていたが、この事業所は基本的に半日型デイのためam/pmだけでよいとの指摘。新規登録モーダルの基本利用日切替を 空→am→pm の2区分に変更(1日を廃止)。既存データの「1日」は各判定ロジックで従来どおり認識するので影響なし。利用者マスタec76d6d\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-29</span></div>\n      <p class=\"title\">新規登録の基本利用日を半日型に合わせAM/PMのみに</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">新規登録に付けた基本利用日の切替に「1日(全日)」が含まれていたが、この事業所は基本的に半日型デイのためAM/PMだけでよいとの指摘。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>新規登録モーダルの基本利用日切替を 空→AM→PM の2区分に変更(1日を廃止)。既存データの「1日」は各判定ロジックで従来どおり認識するので影響なし。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ec76d6d</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"新規登録に利用開始日・基本利用日＋登録後の遷移先選択を追加新規登録で氏名だけ入れて詳細画面へ行く流れだったが、名前・振り仮名・利用開始日・基本利用日を最初の画面で入れてサービス提供内容に反映したい/開始日が不明なこともある、との要望。必須を氏名(姓名)のみにし、フリガナ・利用開始日・基本利用日は任意に。基本利用日は曜日ごとにタップ入力→サービス提供内容へ反映。登録後の遷移先を『フェイスシート(手書き)』『サービス提供内容(マスタ編集)』『追加のみ』から選べるようにした。利用者マスタ021e67e\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-29</span></div>\n      <p class=\"title\">新規登録に利用開始日・基本利用日＋登録後の遷移先選択を追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">新規登録で氏名だけ入れて詳細画面へ行く流れだったが、名前・振り仮名・利用開始日・基本利用日を最初の画面で入れてサービス提供内容に反映したい/開始日が不明なこともある、との要望。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>必須を氏名(姓名)のみにし、フリガナ・利用開始日・基本利用日は任意に。基本利用日は曜日ごとにタップ入力→サービス提供内容へ反映。登録後の遷移先を『フェイスシート(手書き)』『サービス提供内容(マスタ編集)』『追加のみ』から選べるようにした。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">021e67e</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"新規登録に『完了して詳細情報入力』『追加のみ』の2ボタンを追加登録後に詳細入力へ進むかどうかを選べると便利、との以前の要望。『完了して詳細情報入力』(追加してそのまま編集画面へ)と『追加のみ(あとで入力)』の2択に。※後続コミット021e67eでさらに拡張。利用者マスタ706ad5e\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-29</span></div>\n      <p class=\"title\">新規登録に『完了して詳細情報入力』『追加のみ』の2ボタンを追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">登録後に詳細入力へ進むかどうかを選べると便利、との以前の要望。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>『完了して詳細情報入力』(追加してそのまま編集画面へ)と『追加のみ(あとで入力)』の2択に。※後続コミット021e67eでさらに拡張。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">706ad5e</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"送迎者チェックの氏名(5文字以上)が見切れる問題を修正日誌の送迎者チェックが4列固定グリッド＋氏名がnowrap+ellipsisのため、5文字以上の氏名が末尾で切れていた。氏名の文字数に応じてフォントを自動縮小(5=9.5/6=8.5/7以上=7.5px)し、4列固定はそのままで見切れを解消。日誌f37677e\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-07-29</span></div>\n      <p class=\"title\">送迎者チェックの氏名(5文字以上)が見切れる問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">日誌の送迎者チェックが4列固定グリッド＋氏名がnowrap+ellipsisのため、5文字以上の氏名が末尾で切れていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>氏名の文字数に応じてフォントを自動縮小(5=9.5/6=8.5/7以上=7.5px)し、4列固定はそのままで見切れを解消。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f37677e</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"変更ログ\" data-text=\"変更ログの絵文字を削除し文字のみに業務画面では装飾的な絵文字は不要との方針。変更ログのボタン・見出しから絵文字(📋)を除去。今後も必要な箇所以外は絵文字を使わない方針に。変更ログ2fcdb08\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">変更ログ</span><span class=\"date tnum\">2026-07-29</span></div>\n      <p class=\"title\">変更ログの絵文字を削除し文字のみに</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">業務画面では装飾的な絵文字は不要との方針。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>変更ログのボタン・見出しから絵文字(📋)を除去。今後も必要な箇所以外は絵文字を使わない方針に。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2fcdb08</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"変更ログ\" data-text=\"カテゴリ別の変更ログ(端末名・内容・時刻)を記録＋閲覧ビューアを追加「いつ・どの端末で・何を変更したか」を後から追える仕組みが欲しい(同期トラブルの切り分けにも有用)との要望。保存時に変わったカテゴリ(提供記録/連絡/体力測定/利用者マスタ/各種設定 等)を端末名・軽い要約・時刻で最新300件記録(auditlog)。ヘッダーの『変更ログ』ボタンからカテゴリ絞り込み付きで閲覧。読み取り専用でマージには非干渉、店舗ごとに保存(他店は見えない)。空白上書きの検知(マージ計器)は高リスクのため見送り。変更ログd9cbb3d\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">変更ログ</span><span class=\"date tnum\">2026-07-29</span></div>\n      <p class=\"title\">カテゴリ別の変更ログ(端末名・内容・時刻)を記録＋閲覧ビューアを追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">「いつ・どの端末で・何を変更したか」を後から追える仕組みが欲しい(同期トラブルの切り分けにも有用)との要望。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>保存時に変わったカテゴリ(提供記録/連絡/体力測定/利用者マスタ/各種設定 等)を端末名・軽い要約・時刻で最新300件記録(auditLog)。ヘッダーの『変更ログ』ボタンからカテゴリ絞り込み付きで閲覧。読み取り専用でマージには非干渉、店舗ごとに保存(他店は見えない)。空白上書きの検知(マージ計器)は高リスクのため見送り。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d9cbb3d</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"振替/臨時の次回お迎え時間は常に自動計算(過去の手入力を無視)先週8時と手入力した後に同じ記録をpmへ振替し直しても8時のまま残る恐れがあった。getnextvisitinfoがisfurikaeを返すようにし、次回が振替/臨時なら手入力を使わず区分(am/pm)に合った自動値を表示。通常の次回は従来どおり手入力優先。連絡帳84c1ad5\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-29</span></div>\n      <p class=\"title\">振替/臨時の次回お迎え時間は常に自動計算(過去の手入力を無視)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">先週8時と手入力した後に同じ記録をPMへ振替し直しても8時のまま残る恐れがあった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>getNextVisitInfoがisFurikaeを返すようにし、次回が振替/臨時なら手入力を使わず区分(AM/PM)に合った自動値を表示。通常の次回は従来どおり手入力優先。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">84c1ad5</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"振替の次回お迎え時間を『時だけ』表示＋未入力既定を8時/13時に自動値は時だけでよい/施設提供時間が未入力なら既定値が欲しい、との指摘。施設提供時間からの自動値を時だけ(8:50→8時 / 13:15→13時)にし、提供時間も未入力ならam=8時/pm=13時を既定に。連絡帳9028a45\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-29</span></div>\n      <p class=\"title\">振替の次回お迎え時間を『時だけ』表示＋未入力既定を8時/13時に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">自動値は時だけでよい/施設提供時間が未入力なら既定値が欲しい、との指摘。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>施設提供時間からの自動値を時だけ(8:50→8時 / 13:15→13時)にし、提供時間も未入力ならAM=8時/PM=13時を既定に。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9028a45</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"振替/送迎時間未設定日の次回お迎え時間を施設のサービス提供時間から自動計算週1日だけ等の利用者は他曜日の送迎時間を設定しないため、振替で別曜日に移ると次回時間が空欄/不定になっていた。登録済みのpickuptimesを最優先、未設定の曜日はam=am開始の10分前/pm=pm開始の10分前で自動計算(am↔pmで自動切替)。表示計算のみでマスタは書き換えない。連絡帳bbef167\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-29</span></div>\n      <p class=\"title\">振替/送迎時間未設定日の次回お迎え時間を施設のサービス提供時間から自動計算</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">週1日だけ等の利用者は他曜日の送迎時間を設定しないため、振替で別曜日に移ると次回時間が空欄/不定になっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>登録済みのpickupTimesを最優先、未設定の曜日はAM=AM開始の10分前/PM=PM開始の10分前で自動計算(AM↔PMで自動切替)。表示計算のみでマスタは書き換えない。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">bbef167</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"基本利用日が保存直後に一瞬で戻る競合を修正＋モーダルを『指定せず保存』化基本利用日(曜日)を保存した直後に、push反映前の古いクラウド値でlocalpatientが再シードされ、入力が一瞬消える(再入力で反映)競合があった。保存直後6秒は再シードしないガードを追加。あわせて運動メニューの反映日モーダルの『キャンセル』を『指定せず保存』に(値は保存・反映日のみ未指定)。利用者マスタ3b872f2\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-28</span></div>\n      <p class=\"title\">基本利用日が保存直後に一瞬で戻る競合を修正＋モーダルを『指定せず保存』化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">基本利用日(曜日)を保存した直後に、push反映前の古いクラウド値でlocalPatientが再シードされ、入力が一瞬消える(再入力で反映)競合があった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>保存直後6秒は再シードしないガードを追加。あわせて運動メニューの反映日モーダルの『キャンセル』を『指定せず保存』に(値は保存・反映日のみ未指定)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3b872f2</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"運動メニュー変更の反映日確認を『保存時に1回まとめて』＋『分けない』廃止運動メニューを項目ごとに変えるたび、自動保存で反映日モーダルが時差で出て煩わしかった。『分けない』は基本使わない。自動保存では値だけ静かに保存し、反映日モーダルは『保存』時に全変更まとめて1回だけ出す(編集開始前の基準値と比較)。モーダルの『分けない』を『指定せず保存』に置換。利用者マスタ0022120\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-28</span></div>\n      <p class=\"title\">運動メニュー変更の反映日確認を『保存時に1回まとめて』＋『分けない』廃止</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">運動メニューを項目ごとに変えるたび、自動保存で反映日モーダルが時差で出て煩わしかった。『分けない』は基本使わない。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>自動保存では値だけ静かに保存し、反映日モーダルは『保存』時に全変更まとめて1回だけ出す(編集開始前の基準値と比較)。モーダルの『分けない』を『指定せず保存』に置換。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0022120</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳の穴あけマークを◀に変更＋自動同期停止時の控えめ未同期バナー穴あけ目印の見た目調整と、スリープ/通信断で最新が反映されていないのに気づけない懸念への対応。2面の穴あけ目印を●→◀に。app_stateの自動pullが30秒以上走っていない時だけヘッダーに『未同期・タップで再読み込み』を控えめ表示(読み取り専用でマージ非干渉)。連絡帳534c53d\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳の穴あけマークを◀に変更＋自動同期停止時の控えめ未同期バナー</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">穴あけ目印の見た目調整と、スリープ/通信断で最新が反映されていないのに気づけない懸念への対応。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>2面の穴あけ目印を●→◀に。app_stateの自動pullが30秒以上走っていない時だけヘッダーに『未同期・タップで再読み込み』を控えめ表示(読み取り専用でマージ非干渉)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">534c53d</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"1\" data-area=\"同期\" data-text=\"バイタルの明示クリアを許可しつつ事故的な空欄上書きは防止バイタルを空で消せない多重防御を入れた結果、意図的なクリアもできなくなっていた。一方で事故的な空欄上書きは防ぎたい。バイタルの空↔非空マージを『空側の_fieldtsが非空側より厳密に新しい=はっきり消した時だけ』クリア反映に。空欄への_fieldtsは値→空の明示クリア時のみ付くため、意図的削除と事故的空を安全に区別できる。同期688b5ae\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">バイタルの明示クリアを許可しつつ事故的な空欄上書きは防止</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">バイタルを空で消せない多重防御を入れた結果、意図的なクリアもできなくなっていた。一方で事故的な空欄上書きは防ぎたい。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>バイタルの空↔非空マージを『空側の_fieldTsが非空側より厳密に新しい=はっきり消した時だけ』クリア反映に。空欄への_fieldTsは値→空の明示クリア時のみ付くため、意図的削除と事故的空を安全に区別できる。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">688b5ae</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"1\" data-area=\"同期\" data-text=\"バイタルは空が新しくても非空を絶対優先(多重防御)空バイタル誤削除の再発を構造的に防ぎたい。万一どこかで空欄に新しい削除フラグが付いても入力済みを消させない。mergerecordfieldsの_fieldts短絡でも、体温/血圧/脈(*_am/*_pm)は片方だけ空なら非空を採用する多重防御を追加(後に688b5aeで明示クリアのみ許可に調整)。同期cdc4f28\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">バイタルは空が新しくても非空を絶対優先(多重防御)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">空バイタル誤削除の再発を構造的に防ぎたい。万一どこかで空欄に新しい削除フラグが付いても入力済みを消させない。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>mergeRecordFieldsの_fieldTs短絡でも、体温/血圧/脈(*_AM/*_PM)は片方だけ空なら非空を採用する多重防御を追加(後に688b5aeで明示クリアのみ許可に調整)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">cdc4f28</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"『元に戻す』が_fieldtsを更新せず削除フラグに負けて戻らない不具合を修正提供記録の元に戻す(スナップショット復元)が_savedatだけ更新し_fieldtsを据え置きだったため、クラウド側の空欄削除フラグ(新しい_fieldts)がフィールド単位マージで勝ち、復元しても血圧/体温が空のままだった。復元時に対象記録の全項目へ_fieldts=nowを刻むよう修正。消える前のスナップショットを選べば値が戻るようにした。同期9a0b345\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">『元に戻す』が_fieldTsを更新せず削除フラグに負けて戻らない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">提供記録の元に戻す(スナップショット復元)が_savedAtだけ更新し_fieldTsを据え置きだったため、クラウド側の空欄削除フラグ(新しい_fieldTs)がフィールド単位マージで勝ち、復元しても血圧/体温が空のままだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>復元時に対象記録の全項目へ_fieldTs=nowを刻むよう修正。消える前のスナップショットを選べば値が戻るようにした。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9a0b345</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"提供記録の空バイタルに削除フラグが付き他端末の血圧/体温を消す不具合を修正保存時のフィールド差分判定で、フォームがバイタルを空文字で正規化(undefined→&#x27;&#x27;)しただけの項目にも_fieldtsを刻んでいた。マージ側がこれを『意図的な削除』と誤判定し、他端末で入力済みの血圧/体温(am/pm)を空で上書き消去していた(運動はキー単位マージで生存)。特定店舗で血圧・体温だけが午前午後とも消える症状。差分判定で空↔未入力(undefined↔&#x27;&#x27;)を『変更なし』とみなすよう修正(値→&#x27;&#x27;の明示削除は従来どおり反映)。あわせて多重防御(cdc4f28/688b5ae)・元に戻す修正(9a0b345)も実施。同期0c02dee\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">提供記録の空バイタルに削除フラグが付き他端末の血圧/体温を消す不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">保存時のフィールド差分判定で、フォームがバイタルを空文字で正規化(undefined→&#x27;&#x27;)しただけの項目にも_fieldTsを刻んでいた。マージ側がこれを『意図的な削除』と誤判定し、他端末で入力済みの血圧/体温(AM/PM)を空で上書き消去していた(運動はキー単位マージで生存)。特定店舗で血圧・体温だけが午前午後とも消える症状。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>差分判定で空↔未入力(undefined↔&#x27;&#x27;)を『変更なし』とみなすよう修正(値→&#x27;&#x27;の明示削除は従来どおり反映)。あわせて多重防御(cdc4f28/688b5ae)・元に戻す修正(9a0b345)も実施。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0c02dee</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"連絡\" data-text=\"休み連絡/各種連絡の送付履歴を個人ファイル一覧から直接削除できるボタンを追加重複や誤登録の送付履歴を、個人ファイルの連絡タブから直接消したいとの要望。個人ファイル(連絡タブ)の休み連絡・各種連絡・モニタリング履歴の各行に確認ダイアログ付き削除(✕)を追加。連絡696ddef\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">連絡</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">休み連絡/各種連絡の送付履歴を個人ファイル一覧から直接削除できるボタンを追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">重複や誤登録の送付履歴を、個人ファイルの連絡タブから直接消したいとの要望。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>個人ファイル(連絡タブ)の休み連絡・各種連絡・モニタリング履歴の各行に確認ダイアログ付き削除(✕)を追加。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">696ddef</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳2面のドットを左端へ＋休み連絡・各種連絡の重複自動追加を防止プレビューを開くたびに休み連絡/各種連絡の送付履歴が自動追加され重複していた。穴あけドットも内側寄りだった。休み連絡は同一利用者×同一欠席日は1件のみ、各種連絡は同一宛先×件名×本文が同じなら追加しないよう重複防止。2面の穴あけドットを左端(5mm)へ。連絡帳414ad24\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳2面のドットを左端へ＋休み連絡・各種連絡の重複自動追加を防止</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">プレビューを開くたびに休み連絡/各種連絡の送付履歴が自動追加され重複していた。穴あけドットも内側寄りだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>休み連絡は同一利用者×同一欠席日は1件のみ、各種連絡は同一宛先×件名×本文が同じなら追加しないよう重複防止。2面の穴あけドットを左端(5mm)へ。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">414ad24</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳2面が真っ白になる不具合を修正(縮小実寸ラッパー枠方式)2面を絶対配置+transformにしたところ、印刷プレビューのクリップ処理で中身ごと消えて真っ白になった(ドットと点線だけ残る)。カード(182×257固定)を縮小後の実寸(約116.5×164.5mm)のラッパー枠に入れて確実に描画する方式へ変更。両面共通配置(重ねてピッタリ)・ドット一致は維持。連絡帳c9e583c\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳2面が真っ白になる不具合を修正(縮小実寸ラッパー枠方式)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">2面を絶対配置+transformにしたところ、印刷プレビューのクリップ処理で中身ごと消えて真っ白になった(ドットと点線だけ残る)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>カード(182×257固定)を縮小後の実寸(約116.5×164.5mm)のラッパー枠に入れて確実に描画する方式へ変更。両面共通配置(重ねてピッタリ)・ドット一致は維持。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c9e583c</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳2面を両面同一の絶対配置に(重ねてピッタリ)＋左綴じ代ドット＋右詰め2面の左右余白が対称にならず、重ねたときに揃わない/右面の外側余白が広すぎるとの指摘。カード内蔵の左19mm綴じ代を活かし、両面共通のmarginで絶対配置に統一(中央でカット→2枚のb6を重ねると中身も穴も一致)。穴あけドットを左綴じ代の縦中央に、右端余白を詰めた。連絡帳c999f08\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳2面を両面同一の絶対配置に(重ねてピッタリ)＋左綴じ代ドット＋右詰め</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">2面の左右余白が対称にならず、重ねたときに揃わない/右面の外側余白が広すぎるとの指摘。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>カード内蔵の左19mm綴じ代を活かし、両面共通のmarginで絶対配置に統一(中央でカット→2枚のB6を重ねると中身も穴も一致)。穴あけドットを左綴じ代の縦中央に、右端余白を詰めた。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c999f08</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳2面をミラー配置に(中央のりしろを広く/外側を狭く)＋倍率0.64中身が中央線寄りで、切り取り線まわりののりしろが狭かった。左面は中身を左寄せ・右面は右寄せにし、空いた余白を中央に集約(のりしろを広く・外側を狭く)。倍率0.64で余白確保(後にc999f08で両面同一配置へ再調整)。連絡帳5e4b8cf\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳2面をミラー配置に(中央のりしろを広く/外側を狭く)＋倍率0.64</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">中身が中央線寄りで、切り取り線まわりののりしろが狭かった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>左面は中身を左寄せ・右面は右寄せにし、空いた余白を中央に集約(のりしろを広く・外側を狭く)。倍率0.64で余白確保(後にc999f08で両面同一配置へ再調整)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5e4b8cf</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳2面印刷のサイズ崩れを修正(flex+0.70に戻す)＋既定b5-2面＋印刷ヘッダー抑制2面を絶対配置に変えた際に中身が拡大してはみ出した。既定の面数・用紙も整えたい。サイズが正しく出るflex中央+0.70倍方式に戻し、面数の既定をb5横2面に。印刷プレビューに@page{margin:0}を効かせブラウザのヘッダー/フッターを抑制。連絡帳7a42921\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳2面印刷のサイズ崩れを修正(flex+0.70に戻す)＋既定B5-2面＋印刷ヘッダー抑制</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">2面を絶対配置に変えた際に中身が拡大してはみ出した。既定の面数・用紙も整えたい。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>サイズが正しく出るflex中央+0.70倍方式に戻し、面数の既定をB5横2面に。印刷プレビューに@page{margin:0}を効かせブラウザのヘッダー/フッターを抑制。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7a42921</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳2面の左右偏りを絶対配置で解消＋右上日付は空面のみ空欄に2面印刷で左右の面の余白が対称にならず(両方が中央のカット線寄り)残っていた。flexの「はみ出し中央寄せ」が効かないため。また右上日付を常に空欄にしていたが、利用者がいる面は実際の日付が欲しいとの指摘。2面の各面を絶対配置(left:0/半分)にし、中身をtranslate(-50%,-50%)+scaleでface中央に固定して両面まったく同じ配置に。右上日付は2面印刷で余った空面(手書き用・id=__blank__)だけ「令和8年　月　日（　）」の空欄にし、利用者がいる面は従来どおり実際の日付(令和8年m月d日（曜）)を表示。連絡帳5fef4d9\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳2面の左右偏りを絶対配置で解消＋右上日付は空面のみ空欄に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">2面印刷で左右の面の余白が対称にならず(両方が中央のカット線寄り)残っていた。flexの「はみ出し中央寄せ」が効かないため。また右上日付を常に空欄にしていたが、利用者がいる面は実際の日付が欲しいとの指摘。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>2面の各面を絶対配置(left:0/半分)にし、中身をtranslate(-50%,-50%)+scaleでface中央に固定して両面まったく同じ配置に。右上日付は2面印刷で余った空面(手書き用・id=__blank__)だけ「令和8年　月　日（　）」の空欄にし、利用者がいる面は従来どおり実際の日付(令和8年M月D日（曜）)を表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5fef4d9</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳b5横2面の左右余白を両面で完全一致に2面印刷で、左面は中身が右寄り(左余白広い)・右面は左寄り(右余白広い)＝両方が中央のカット線寄りになり、左右の面で余白がバラついていた。原因は182mm幅の中身を128.5mmの枠にはみ出したまま中央寄せしていたため。各面の中身を「縮小後の実寸ピッタリの箱(transform-origin:top left)」にしてから中央寄せする方式に変更。これで左右の余白が両面で完全に一致する。連絡帳2c852dd\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳B5横2面の左右余白を両面で完全一致に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">2面印刷で、左面は中身が右寄り(左余白広い)・右面は左寄り(右余白広い)＝両方が中央のカット線寄りになり、左右の面で余白がバラついていた。原因は182mm幅の中身を128.5mmの枠にはみ出したまま中央寄せしていたため。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>各面の中身を「縮小後の実寸ピッタリの箱(transform-origin:top left)」にしてから中央寄せする方式に変更。これで左右の余白が両面で完全に一致する。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2c852dd</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳右上の日付を「令和8年　月　日（　）」表記に修正(年は表示・月日曜は手書き用の空欄)前回、右上の日付から令和・年数字ごと削除してしまったが、正しくは「令和8年」は残し、月・日・曜日を空欄(手書き)にしたいという指摘。右上の日付を「令和(和暦年)年　月　日（　）」形式に変更。令和と年(例:令和8年)は表示し、月・日・曜日は全角スペースの空欄にして手書きで記入できるようにした。連絡帳4d2c587\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳右上の日付を「令和8年　月　日（　）」表記に修正(年は表示・月日曜は手書き用の空欄)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">前回、右上の日付から令和・年数字ごと削除してしまったが、正しくは「令和8年」は残し、月・日・曜日を空欄(手書き)にしたいという指摘。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>右上の日付を「令和(和暦年)年　月　日（　）」形式に変更。令和と年(例:令和8年)は表示し、月・日・曜日は全角スペースの空欄にして手書きで記入できるようにした。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4d2c587</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳b5横2面印刷の位置ズレ・見切れ・穴あけ点・日付表記を調整実機で2面印刷したところ、内容が左に寄る/連絡欄や次回欄が見切れる/1枚目と2枚目で位置が違う、穴あけ点が右面にしか出ず上下2点だった、次回未設定が「未定」、右上が「令和8年…」表記、等の指摘があった。各面を1面(b6)と同じ「flexで中央＋0.70倍」配置に統一し、左寄り・見切れ・1/2枚目の差を解消。b5を左右いっぱいに使い中央のカット点線が真ん中に来るように。穴あけ点は各面の左・縦ど真ん中に1つずつ(左右両面)に変更。次回お迎え日付が未設定なら「未定」でなく「　月　日（　）」の手書き用空欄に。連絡帳右上の日付は令和・年数字を外し「m月d日（曜）」表記に。連絡帳5381ad5\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳B5横2面印刷の位置ズレ・見切れ・穴あけ点・日付表記を調整</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">実機で2面印刷したところ、内容が左に寄る/連絡欄や次回欄が見切れる/1枚目と2枚目で位置が違う、穴あけ点が右面にしか出ず上下2点だった、次回未設定が「未定」、右上が「令和8年…」表記、等の指摘があった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>各面を1面(B6)と同じ「flexで中央＋0.70倍」配置に統一し、左寄り・見切れ・1/2枚目の差を解消。B5を左右いっぱいに使い中央のカット点線が真ん中に来るように。穴あけ点は各面の左・縦ど真ん中に1つずつ(左右両面)に変更。次回お迎え日付が未設定なら「未定」でなく「　月　日（　）」の手書き用空欄に。連絡帳右上の日付は令和・年数字を外し「M月D日（曜）」表記に。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5381ad5</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳をb5横に2面印刷(後で中央カット)できるように＋補助線＋右上を「詳細設定」化b6非対応/b6トレイのセットでエラーになる複合機があり、b5に1枚(b6位置)印刷が使えない事業所があった。普通にb5印刷して後でカットしたい要望。連絡帳画面右上の「用紙」を「詳細設定」に変更し、面数(1面/2面)・用紙(横b5/縦b6)・補助線をパネルで選択可能に。2面モードはb5横(257×182)に連絡帳を左右2面配置し、中央でカットするとb6×2枚になる。人数が奇数のときは最後の1面を空欄(氏名・次回日付/時間・運動の連動・自由入力が空＝手書き用)にして偶数化。補助線=中央の縦点線(カット線)＋各面の左側に上下2つの点(穴あけ目印)で、それぞれ印刷時にon/off選択可。印刷対象は従来の利用者選択で決めるため午前/午後/1日まとめもそのまま対応。1面モードは従来通り。連絡帳231e78b\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳をB5横に2面印刷(後で中央カット)できるように＋補助線＋右上を「詳細設定」化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">B6非対応/B6トレイのセットでエラーになる複合機があり、B5に1枚(B6位置)印刷が使えない事業所があった。普通にB5印刷して後でカットしたい要望。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>連絡帳画面右上の「用紙」を「詳細設定」に変更し、面数(1面/2面)・用紙(横B5/縦B6)・補助線をパネルで選択可能に。2面モードはB5横(257×182)に連絡帳を左右2面配置し、中央でカットするとB6×2枚になる。人数が奇数のときは最後の1面を空欄(氏名・次回日付/時間・運動の連動・自由入力が空＝手書き用)にして偶数化。補助線=中央の縦点線(カット線)＋各面の左側に上下2つの点(穴あけ目印)で、それぞれ印刷時にON/OFF選択可。印刷対象は従来の利用者選択で決めるため午前/午後/1日まとめもそのまま対応。1面モードは従来通り。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">231e78b</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"運動メニュー/個別運動メニューの削除が、保存しても消えない不具合を修正各種設定の運動メニューはマウント時のスナップショットで保持し、保存時の安全ガード(ローカルが空ならクラウド側に戻す)により、削除して短く/空になった配列が古いクラウド値へ戻ることがあった(特に個別運動を全部消した時等)。加えて削除時の履歴の重複判定が effectivefrom(常にundefined)で、毎回不要なスナップショットを追加していた。マウント時の内容と比較して「ユーザーが実際に編集した配列」は、削除を含めローカルを必ず保存する(空でもクラウドへ戻さない)。未編集の配列は現行データを優先し、同期で増えた分の巻き戻りは防ぐ。運動メニュー・個別運動メニュー・その時系列履歴・クイックボタンに適用し、通常の保存ボタンと「未保存です」ポップアップ保存の両方で有効。削除時の履歴スナップショット重複判定を effectiveto 基準に統一。各種設定81ab60a\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">運動メニュー/個別運動メニューの削除が、保存しても消えない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">各種設定の運動メニューはマウント時のスナップショットで保持し、保存時の安全ガード(ローカルが空ならクラウド側に戻す)により、削除して短く/空になった配列が古いクラウド値へ戻ることがあった(特に個別運動を全部消した時等)。加えて削除時の履歴の重複判定が effectiveFrom(常にundefined)で、毎回不要なスナップショットを追加していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>マウント時の内容と比較して「ユーザーが実際に編集した配列」は、削除を含めローカルを必ず保存する(空でもクラウドへ戻さない)。未編集の配列は現行データを優先し、同期で増えた分の巻き戻りは防ぐ。運動メニュー・個別運動メニュー・その時系列履歴・クイックボタンに適用し、通常の保存ボタンと「未保存です」ポップアップ保存の両方で有効。削除時の履歴スナップショット重複判定を effectiveTo 基準に統一。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">81ab60a</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"保険証・負担割合証・フェイスシート等が他店の更新で反映されない/巻き戻る不具合を修正介護保険証/負担割合証のメタ・フェイスシート・担当者会議・アセスメント等が入るpersonalfile(入れ子)と、負担割合の有効期間(costburdenfrom/to)・被保険者番号が、同期の項目単位保護(_fieldts)の対象外だった。そのため別の項目を触った“少し古いデータの端末”が保存すると、他店で更新した保険証・フェイスシートが「新しいスナップショット」の名目でまるごと巻き戻っていた(保険証以外も同じ弱点)。同期の項目単位保護を拡張。①保護対象に costburdenfrom/costburdento/被保険者番号 を追加。②personalfile をサブキー単位の時刻(pf:キー)でマージ(各書類・フェイスシート・会議記録ごとに新しい方を採用。アセスメントは従来の和集合を維持)。③介護度・負担割合の変更履歴を和集合で保持し、両端末の追記=過去記録を失わないように。既存クラウドは項目時刻を持たないため当面は従来挙動にフォールバックし、以降の保存で段階的に保護が付く(後方互換)。同期7c18dfb\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-26</span></div>\n      <p class=\"title\">保険証・負担割合証・フェイスシート等が他店の更新で反映されない/巻き戻る不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">介護保険証/負担割合証のメタ・フェイスシート・担当者会議・アセスメント等が入るpersonalFile(入れ子)と、負担割合の有効期間(costBurdenFrom/To)・被保険者番号が、同期の項目単位保護(_fieldTs)の対象外だった。そのため別の項目を触った“少し古いデータの端末”が保存すると、他店で更新した保険証・フェイスシートが「新しいスナップショット」の名目でまるごと巻き戻っていた(保険証以外も同じ弱点)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>同期の項目単位保護を拡張。①保護対象に costBurdenFrom/costBurdenTo/被保険者番号 を追加。②personalFile をサブキー単位の時刻(pf:キー)でマージ(各書類・フェイスシート・会議記録ごとに新しい方を採用。アセスメントは従来の和集合を維持)。③介護度・負担割合の変更履歴を和集合で保持し、両端末の追記=過去記録を失わないように。既存クラウドは項目時刻を持たないため当面は従来挙動にフォールバックし、以降の保存で段階的に保護が付く(後方互換)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7c18dfb</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"テンキー日本語ラベルを大きく表示＋言い回しを変更（bs→1字消す／tab→次へ）日本語化したテンキーのラベルが小さく見づらかった。bs・tabは別の言い回しの方が直感的との要望。bs=1字消す(2行)／tab=次へ に変更。日本語ラベルのフォントを拡大（全削除=0.66倍、1字消す/次へ/確定=0.82倍）。キー値は英語のままで動作は不変。提供記録f4da324\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-26</span></div>\n      <p class=\"title\">テンキー日本語ラベルを大きく表示＋言い回しを変更（BS→1字消す／TAB→次へ）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">日本語化したテンキーのラベルが小さく見づらかった。BS・TABは別の言い回しの方が直感的との要望。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>BS=1字消す(2行)／TAB=次へ に変更。日本語ラベルのフォントを拡大（全削除=0.66倍、1字消す/次へ/確定=0.82倍）。キー値は英語のままで動作は不変。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f4da324</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"テンキーの特殊キーを日本語表示に（del→全削除／bs→1文字削除／tab→右へ／enter→確定）テンキーのdel/bs/tab/enterが英語表記で、意味が分からない職員がいた。表示ラベルを日本語化（del=全削除／bs=1文字削除〔2行〕／tab=右へ／enter=確定）。キー値は英語のままロジックで使用するため動作は不変。日本語ラベルはボタン内に収まるようフォントサイズを調整。提供記録cf98527\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-26</span></div>\n      <p class=\"title\">テンキーの特殊キーを日本語表示に（DEL→全削除／BS→1文字削除／TAB→右へ／ENTER→確定）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">テンキーのDEL/BS/TAB/ENTERが英語表記で、意味が分からない職員がいた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>表示ラベルを日本語化（DEL=全削除／BS=1文字削除〔2行〕／TAB=右へ／ENTER=確定）。キー値は英語のままロジックで使用するため動作は不変。日本語ラベルはボタン内に収まるようフォントサイズを調整。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">cf98527</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析/提供記録\" data-text=\"気分列幅を状態列と同じに＋日々の詳細記録の気分理由ツールチップをipad対応にサービス提供記録の気分列が状態列より広かった。日々の詳細記録の気分絵文字はnative title頼りで、ipad等タッチ端末ではカーソルを合わせても理由が表示されなかった。サービス提供記録の気分列ヘッダ幅を60→34(状態列と同じ)にしセルのminwidthも撤去。日々の詳細記録の気分絵文字に、ホバー(onpointerenter)とタップ(onclick)の両方で理由を表示する浮動ツールチップを実装(タップ時は2.6秒で自動クローズ、理由なしは「（理由なし）」)。分析/提供記録c18172e\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析/提供記録</span><span class=\"date tnum\">2026-07-24</span></div>\n      <p class=\"title\">気分列幅を状態列と同じに＋日々の詳細記録の気分理由ツールチップをiPad対応に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">サービス提供記録の気分列が状態列より広かった。日々の詳細記録の気分絵文字はnative title頼りで、iPad等タッチ端末ではカーソルを合わせても理由が表示されなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>サービス提供記録の気分列ヘッダ幅を60→34(状態列と同じ)にしセルのminWidthも撤去。日々の詳細記録の気分絵文字に、ホバー(onPointerEnter)とタップ(onClick)の両方で理由を表示する浮動ツールチップを実装(タップ時は2.6秒で自動クローズ、理由なしは「（理由なし）」)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c18172e</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"分析/提供記録\" data-text=\"気分表示を絵文字のみに整理＋日々の詳細記録の見やすさ改善サービス提供記録の気分に💬コメント絵文字が付いて列幅を取っていた。分析個人『日々の詳細記録』は気分の理由テキストが括弧書きで表示され横に広がっていた。特記列が狭く、行のストライプが薄くて見分けにくかった。サービス提供記録(検索一覧)の気分から💬を削除し気分列幅を縮小(minwidth 52→36)、理由はホバー(title)で従来通り。日々の詳細記録の気分(通)/(帰)は絵文字のみ表示にし理由テキストを廃止、絵文字ホバーで気分理由を表示。特記列の幅を拡大(minwidth 220→340)。奇数行のストライプ背景グレーを濃く(#fafbfc→#eef2f6)。分析/提供記録d7a9976\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">分析/提供記録</span><span class=\"date tnum\">2026-07-24</span></div>\n      <p class=\"title\">気分表示を絵文字のみに整理＋日々の詳細記録の見やすさ改善</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">サービス提供記録の気分に💬コメント絵文字が付いて列幅を取っていた。分析個人『日々の詳細記録』は気分の理由テキストが括弧書きで表示され横に広がっていた。特記列が狭く、行のストライプが薄くて見分けにくかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>サービス提供記録(検索一覧)の気分から💬を削除し気分列幅を縮小(minWidth 52→36)、理由はホバー(title)で従来通り。日々の詳細記録の気分(通)/(帰)は絵文字のみ表示にし理由テキストを廃止、絵文字ホバーで気分理由を表示。特記列の幅を拡大(minWidth 220→340)。奇数行のストライプ背景グレーを濃く(#fafbfc→#eef2f6)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d7a9976</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"連絡\" data-text=\"休み連絡・各種連絡の送付先fax番号を表示(マスタ補完)＋ワンクリックコピー送付状の送付先faxが利用者のcmfaxのみ参照で、利用者にfax未設定だと表示されなかった(各種設定のケアマネ事業所情報にはfaxがある)。各種設定のケアマネ事業所情報(cmoffices)から事業所名一致でfax番号を補完して表示。fax番号の右にコピーボタン(copyfaxbutton)を新設し、複合機にそのまま貼り付けられるようクリップボードへコピー(navigator.clipboard、非対応時はexeccommandでフォールバック)。コピーボタンはno-printクラスで印刷/pdf時は非表示。連絡684adcb\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">連絡</span><span class=\"date tnum\">2026-07-24</span></div>\n      <p class=\"title\">休み連絡・各種連絡の送付先FAX番号を表示(マスタ補完)＋ワンクリックコピー</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">送付状の送付先FAXが利用者のcmFaxのみ参照で、利用者にFAX未設定だと表示されなかった(各種設定のケアマネ事業所情報にはFAXがある)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>各種設定のケアマネ事業所情報(cmOffices)から事業所名一致でFAX番号を補完して表示。FAX番号の右にコピーボタン(CopyFaxButton)を新設し、複合機にそのまま貼り付けられるようクリップボードへコピー(navigator.clipboard、非対応時はexecCommandでフォールバック)。コピーボタンはno-printクラスで印刷/PDF時は非表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">684adcb</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"科学的介護推進・adl維持等の帳票(印刷/pdf)を追加lifeの科学的介護推進(tifi2024)・adl維持等(aint2024)は評価内容を紙様式で出す帳票が無く、csvのみだった。lifehubviewに印刷機能(onshowprintpreview)を渡し、両様式カードに「帳票印刷」ボタンを追加。科学的介護推進に関する評価=事業所/利用者/評価日/介護度/自立度・barthel一覧・身長体重・口腔(義歯/むせ/歯の汚れ/歯肉)・認知症診断・生活認知機能尺度7設問(点数+選択肢)・vitalityをa4紙様式で出力。adl維持等=ヘッダ+対象月区分+barthel一覧。元データ=選択中利用者の最新adl評価+固有項目。生活機能チェック(3-2)/個別機能訓練(3-3)の帳票は各計画書画面の印刷/pdfから。life加算a7119db\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-24</span></div>\n      <p class=\"title\">科学的介護推進・ADL維持等の帳票(印刷/PDF)を追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">LIFEの科学的介護推進(TIFI2024)・ADL維持等(AINT2024)は評価内容を紙様式で出す帳票が無く、CSVのみだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>LifeHubViewに印刷機能(onShowPrintPreview)を渡し、両様式カードに「帳票印刷」ボタンを追加。科学的介護推進に関する評価=事業所/利用者/評価日/介護度/自立度・Barthel一覧・身長体重・口腔(義歯/むせ/歯の汚れ/歯肉)・認知症診断・生活認知機能尺度7設問(点数+選択肢)・VitalityをA4紙様式で出力。ADL維持等=ヘッダ+対象月区分+Barthel一覧。元データ=選択中利用者の最新ADL評価+固有項目。生活機能チェック(3-2)/個別機能訓練(3-3)の帳票は各計画書画面の印刷/PDFから。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a7119db</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"個別機能訓練 idua2024(103列)のlife提出csvを実装(v1)＋計画書にコード入力uilifeの4様式のうち個別機能訓練(idua2024・最大の103列)が未対応だった。目標や訓練内容はコード(icf/プログラム/職種/合併症/傷病名)での提出が必要。life_idua2024_columns(103)/buildidua2024row/validateidua2024を実装しlife_formsにsource=kinouで登録(addon=個別機能訓練加算ii)。元データ=個別機能訓練計画書(3-3)。マスタ同梱=icf目標55(§9.2)/訓練プログラム18(§9.3)/合併症23分類/職種名(准看護師=050のみ確定・他要確認)。本人家族希望・社会参加・居宅環境・治療経過・目標文→内容列、発症/入退院日→年月日分割、訓練内容→プログラムコード自動推定、達成度文→コード、自立度/介護度/管理番号/versionを自動生成。3-3計画書に「life提出用コード」入力(傷病名/合併症/目標icf/プログラム/職種/達成度=editing.life)を新設。提出ダッシュボード・単票出力もkinou元データに対応。傷病名27388件は任意入力扱い。life加算34f64f8 / a69388f\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-24</span></div>\n      <p class=\"title\">個別機能訓練 IDUA2024(103列)のLIFE提出CSVを実装(v1)＋計画書にコード入力UI</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">LIFEの4様式のうち個別機能訓練(IDUA2024・最大の103列)が未対応だった。目標や訓練内容はコード(ICF/プログラム/職種/合併症/傷病名)での提出が必要。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>LIFE_IDUA2024_COLUMNS(103)/buildIdua2024Row/validateIdua2024を実装しLIFE_FORMSにsource=kinouで登録(addon=個別機能訓練加算II)。元データ=個別機能訓練計画書(3-3)。マスタ同梱=ICF目標55(§9.2)/訓練プログラム18(§9.3)/合併症23分類/職種名(准看護師=050のみ確定・他要確認)。本人家族希望・社会参加・居宅環境・治療経過・目標文→内容列、発症/入退院日→年月日分割、訓練内容→プログラムコード自動推定、達成度文→コード、自立度/介護度/管理番号/versionを自動生成。3-3計画書に「LIFE提出用コード」入力(傷病名/合併症/目標ICF/プログラム/職種/達成度=editing.life)を新設。提出ダッシュボード・単票出力もkinou元データに対応。傷病名27388件は任意入力扱い。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">34f64f8 / a69388f</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析\" data-text=\"月別稼働率グラフで7月時点に8月の稼働率が出てしまう不具合を修正月別グラフは年度12ヶ月を常に表示。当月は今日までにcapする処理はあったが、未来月を除外する処理が無く、稼働率の照合が「記録に年がある時だけ年フィルタ」だったため、年情報のない同月番号の記録(前年8月分等)を未来月が拾い、売上¥0なのに稼働率91%等と表示されていた。_isfuturemonth(当月より後)を判定し、未来月は稼働率rate=null(グラフ・表で非表示)に。年なし記録の混入を防ぎ、稼働率の線は当月までで止まる。売上の年付き照合は元々正しいため¥0表示は不変。分析9011a1f\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-24</span></div>\n      <p class=\"title\">月別稼働率グラフで7月時点に8月の稼働率が出てしまう不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">月別グラフは年度12ヶ月を常に表示。当月は今日までにcapする処理はあったが、未来月を除外する処理が無く、稼働率の照合が「記録に年がある時だけ年フィルタ」だったため、年情報のない同月番号の記録(前年8月分等)を未来月が拾い、売上¥0なのに稼働率91%等と表示されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>_isFutureMonth(当月より後)を判定し、未来月は稼働率rate=null(グラフ・表で非表示)に。年なし記録の混入を防ぎ、稼働率の線は当月までで止まる。売上の年付き照合は元々正しいため¥0表示は不変。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9011a1f</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"生活機能チェック(func2024・52列)のlife提出csvを追加＋様式横断にsource導入lifeはtifi2024/aint2024のみで生活機能チェック(様式3-2)のfunc2024が未対応。ダッシュボード/出力もbarthel(adlrecords)固定で別データ元の様式を扱えなかった。life_func2024_columns(52列)/buildfunc2024row/validatefunc2024を新設しlife_formsにfunc2024を登録(addon=個別機能訓練加算ⅱ)。元データ=生活機能チェック(seikatsukinourecords)。adl10項目はseikatsuadltobarthel→lifebicode(§6.4 bi段階コード)、iadl3/起居動作5は自立=3/見守り=2/一部介助=1/全介助=0。課題の有無は自動判定(自立=無/他=有)。作成日の和暦→yyyymmdd変換(reiwatoymd)追加。life_formsにsource(adl/seikatsu)を追加し提出ダッシュボード・単票を元データで分岐(tifi/aintは従来通り)。func2024はマスタ不要。life加算692f5a2\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">生活機能チェック(FUNC2024・52列)のLIFE提出CSVを追加＋様式横断にsource導入</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">LIFEはTIFI2024/AINT2024のみで生活機能チェック(様式3-2)のFUNC2024が未対応。ダッシュボード/出力もBarthel(adlRecords)固定で別データ元の様式を扱えなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>LIFE_FUNC2024_COLUMNS(52列)/buildFunc2024Row/validateFunc2024を新設しLIFE_FORMSにFUNC2024を登録(addon=個別機能訓練加算Ⅱ)。元データ=生活機能チェック(seikatsuKinouRecords)。ADL10項目はseikatsuAdlToBarthel→lifeBiCode(§6.4 BI段階コード)、IADL3/起居動作5は自立=3/見守り=2/一部介助=1/全介助=0。課題の有無は自動判定(自立=無/他=有)。作成日の和暦→YYYYMMDD変換(reiwaToYmd)追加。LIFE_FORMSにsource(adl/seikatsu)を追加し提出ダッシュボード・単票を元データで分岐(TIFI/AINTは従来通り)。FUNC2024はマスタ不要。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">692f5a2</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"adl維持等加算(aint2024)のcsv出力を追加・ダッシュボード/出力を様式横断化lifeは科学的介護推進(tifi2024)のみ対応で、adl維持等加算のcsvが無かった。aint2024全23列(既存barthel評価を流用・first_month/sixth_monthフラグ対応)を実装。adl評価編集に対象月区分(初月/6か月後/どちらでもない)を追加し利用開始日から目安月を表示。提出ダッシュボード・単票/まとめcsv出力を様式横断(life_forms)に一般化し、加算が複数onなら様式プルダウンでtifi2024/aint2024を切替。life加算4c8ef63\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">ADL維持等加算(AINT2024)のCSV出力を追加・ダッシュボード/出力を様式横断化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">LIFEは科学的介護推進(TIFI2024)のみ対応で、ADL維持等加算のCSVが無かった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>AINT2024全23列(既存Barthel評価を流用・first_month/sixth_monthフラグ対応)を実装。ADL評価編集に対象月区分(初月/6か月後/どちらでもない)を追加し利用開始日から目安月を表示。提出ダッシュボード・単票/まとめCSV出力を様式横断(LIFE_FORMS)に一般化し、加算が複数ONなら様式プルダウンでTIFI2024/AINT2024を切替。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4c8ef63</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"科学的介護推進: 提出ダッシュボード＋複数利用者まとめcsv出力csv出力が利用者1名ずつだった。提出月に複数利用者をまとめて出力できず、誰が提出可/未評価/エラーかの一覧も無かった。life・加算画面に提出ダッシュボード(利用者×状態=提出可/エラー/未評価・確認事項)を追加。行クリックでその利用者に切替。『まとめてcsv出力』で提出可の全利用者を1つのtifi2024_yyyymm.csvに出力(未評価・エラーは自動除外し確認一覧に表示)。各行の管理番号は利用者ごとの評価年月で採番。提出年月セレクタでファイル名整理。life加算74b1da2\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">科学的介護推進: 提出ダッシュボード＋複数利用者まとめCSV出力</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">CSV出力が利用者1名ずつだった。提出月に複数利用者をまとめて出力できず、誰が提出可/未評価/エラーかの一覧も無かった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>LIFE・加算画面に提出ダッシュボード(利用者×状態=提出可/エラー/未評価・確認事項)を追加。行クリックでその利用者に切替。『まとめてCSV出力』で提出可の全利用者を1つのTIFI2024_YYYYMM.csvに出力(未評価・エラーは自動除外し確認一覧に表示)。各行の管理番号は利用者ごとの評価年月で採番。提出年月セレクタでファイル名整理。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">74b1da2</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"分析個人/LIFE加算\" data-text=\"気分表示を絵文字＋ホバーにコンパクト化／life事業所情報は各種設定に一元化①分析個人『日々の詳細記録』で気分の理由テキストが長いと行が縦に伸びて見づらかった。②lifeの事業所番号・保険者番号がlife画面専用カードにあり、事業所情報と二重管理気味だった。①気分列を絵文字だけの一定行高さ表示に変更し、理由はホバー(title)で表示(理由ありは💬)。②事業所番号・保険者番号(既定)・サービス種類コード・csvバージョンを『各種設定→事業所情報』に入力項目として設置し、life・加算のcsvはそこから読込(専用カードは表示のみに)。分析個人/life加算55305ca\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">分析個人/LIFE加算</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">気分表示を絵文字＋ホバーにコンパクト化／LIFE事業所情報は各種設定に一元化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①分析個人『日々の詳細記録』で気分の理由テキストが長いと行が縦に伸びて見づらかった。②LIFEの事業所番号・保険者番号がLIFE画面専用カードにあり、事業所情報と二重管理気味だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>①気分列を絵文字だけの一定行高さ表示に変更し、理由はホバー(title)で表示(理由ありは💬)。②事業所番号・保険者番号(既定)・サービス種類コード・CSVバージョンを『各種設定→事業所情報』に入力項目として設置し、LIFE・加算のCSVはそこから読込(専用カードは表示のみに)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">55305ca</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"life設定(事業所/保険者番号/サービスコード/version)＋利用者ごと保険者番号＋生活認知機能尺度の正式文言科学的介護推進csvで事業所番号・保険者番号が空欄(&#x27;要確認&#x27;警告)だった。また生活・認知機能尺度の7設問が仮ラベルのままだった。life・加算画面に『life設定』(事業所番号・保険者番号既定・サービス種類コード・施設通所区分・csvバージョン=systemsettings.life)を追加。利用者基本情報に被保険者番号表示＋利用者ごとの保険者番号入力を追加(csvは利用者→無ければ事業所既定)。生活・認知機能尺度7設問を別紙様式3の正式文言に差し替え、各点数の選択肢説明も表示。life加算424891d\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">LIFE設定(事業所/保険者番号/サービスコード/version)＋利用者ごと保険者番号＋生活認知機能尺度の正式文言</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">科学的介護推進CSVで事業所番号・保険者番号が空欄(&#x27;要確認&#x27;警告)だった。また生活・認知機能尺度の7設問が仮ラベルのままだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>LIFE・加算画面に『LIFE設定』(事業所番号・保険者番号既定・サービス種類コード・施設通所区分・CSVバージョン=systemSettings.life)を追加。利用者基本情報に被保険者番号表示＋利用者ごとの保険者番号入力を追加(CSVは利用者→無ければ事業所既定)。生活・認知機能尺度7設問を別紙様式3の正式文言に差し替え、各点数の選択肢説明も表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">424891d</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"スケジュール/提供記録\" data-text=\"担当者会議のスケジュール→記録入力ショートカット／提供記録の全画面に連絡帳ボタン①本日のスケジュールで担当者会議(利用者紐付き)を設定していても、記録入力までの導線が無かった。②サービス提供記録入力を全画面にすると連絡帳ボタンが消えていた。①本日のスケジュールの担当者会議イベントの詳細に『担当者会議記録を入力』ボタンを追加し、押すとその利用者の個人ファイル(ケアマネジメント)で会議記録の新規入力を即開くように。②全画面ヘッダにも『連絡帳』ボタンを追加。スケジュール/提供記録9c435e7\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">スケジュール/提供記録</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">担当者会議のスケジュール→記録入力ショートカット／提供記録の全画面に連絡帳ボタン</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①本日のスケジュールで担当者会議(利用者紐付き)を設定していても、記録入力までの導線が無かった。②サービス提供記録入力を全画面にすると連絡帳ボタンが消えていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>①本日のスケジュールの担当者会議イベントの詳細に『担当者会議記録を入力』ボタンを追加し、押すとその利用者の個人ファイル(ケアマネジメント)で会議記録の新規入力を即開くように。②全画面ヘッダにも『連絡帳』ボタンを追加。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9c435e7</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"科学的介護推進体制加算(tifi2024)のlife提出用csv出力を実装(第1弾)life(科学的介護情報システム)へ提出する加算データを一元入力→取込用csvを生成する仕組みが未実装だった(まるっとlifeはexcel運用)。まず科学的介護推進体制加算から着手。life・加算画面に、科学的介護推進の固有入力(身長体重/口腔/認知症診断/生活認知機能尺度7設問/vitality)を追加し、既存のadl評価(barthel)・フェイスシートの自立度を流用して全114列のcsv(tifi2024)を出力。§6.4コード変換(bi段階・自立度・要介護度)、管理番号採番、utf-8/cr-lf、提出前チェック(必須/未来日付/整合)を実装。提出頻度は令和6年度改定に合わせ3ヶ月に修正。次段: 事業所/保険者番号のlife設定・複数まとめ出力・帳票印刷・adl維持等/個別機能訓練の様式。life加算17f432e\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">科学的介護推進体制加算(TIFI2024)のLIFE提出用CSV出力を実装(第1弾)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">LIFE(科学的介護情報システム)へ提出する加算データを一元入力→取込用CSVを生成する仕組みが未実装だった(まるっとLIFEはExcel運用)。まず科学的介護推進体制加算から着手。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>LIFE・加算画面に、科学的介護推進の固有入力(身長体重/口腔/認知症診断/生活認知機能尺度7設問/Vitality)を追加し、既存のADL評価(Barthel)・フェイスシートの自立度を流用して全114列のCSV(TIFI2024)を出力。§6.4コード変換(BI段階・自立度・要介護度)、管理番号採番、UTF-8/CR-LF、提出前チェック(必須/未来日付/整合)を実装。提出頻度は令和6年度改定に合わせ3ヶ月に修正。次段: 事業所/保険者番号のLIFE設定・複数まとめ出力・帳票印刷・ADL維持等/個別機能訓練の様式。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">17f432e</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"利用者マスタ\" data-text=\"運動メニュー規定値をハイフン(ー)/クリアにすると過去の記録まで遡って変わる不具合を修正テンキーの ○/×/ー ボタンは押下で即確定(自動クローズ)するため、数値変更のように『別セルへ移動→保存で&quot;いつから反映&quot;を確認』の流れに乗らず、自動保存で当日付のまま(場合により履歴無しで)確定され、提供記録入力で過去日を遡ると規定値が全てハイフンになっていた。運動メニュー・個別運動の規定値変更は、数値・ハイフン・クリアを問わず必ず『いつから反映しますか』モーダルを表示。自動保存でも当日付で勝手に確定せず、適用開始日を選んで日付単位で履歴管理(過去は旧値のまま保持)。全期間へ適用したい場合はモーダルの『分けない』を選択。利用者マスタ8d48609\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">運動メニュー規定値をハイフン(ー)/クリアにすると過去の記録まで遡って変わる不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">テンキーの ○/×/ー ボタンは押下で即確定(自動クローズ)するため、数値変更のように『別セルへ移動→保存で&quot;いつから反映&quot;を確認』の流れに乗らず、自動保存で当日付のまま(場合により履歴無しで)確定され、提供記録入力で過去日を遡ると規定値が全てハイフンになっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>運動メニュー・個別運動の規定値変更は、数値・ハイフン・クリアを問わず必ず『いつから反映しますか』モーダルを表示。自動保存でも当日付で勝手に確定せず、適用開始日を選んで日付単位で履歴管理(過去は旧値のまま保持)。全期間へ適用したい場合はモーダルの『分けない』を選択。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8d48609</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ケアマネ連携\" data-text=\"フェイスシート編集の更新通知にも項目名(本人情報・留意点・被保険者番号等)を表示フェイスシートに追加した項目(氏名・住所・電話・被保険者番号・留意点・その他関係者)が差分表(fs_field_labels)に無く、フェイスシートで編集しても『フェイスシートの編集』に項目名が出なかった。fs_field_labels にこれらを追加し、フェイスシート経由の編集でも『フェイスシートの編集（○○）』と項目名が出るように(既往歴は登録済み)。ケアマネ連携fe04080\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">フェイスシート編集の更新通知にも項目名(本人情報・留意点・被保険者番号等)を表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">フェイスシートに追加した項目(氏名・住所・電話・被保険者番号・留意点・その他関係者)が差分表(FS_FIELD_LABELS)に無く、フェイスシートで編集しても『フェイスシートの編集』に項目名が出なかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>FS_FIELD_LABELS にこれらを追加し、フェイスシート経由の編集でも『フェイスシートの編集（○○）』と項目名が出るように(既往歴は登録済み)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">fe04080</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"家族・ケアマネの『利用者情報の編集』通知に変更項目名を全項目分表示変更項目名を出す差分表に生年月日・性別・介護度・被保険者番号が含まれておらず、これらだけを編集した場合は項目名が出ず『利用者情報の編集』とだけ表示されていた。差分表にこの4項目を追加し、どの項目を編集しても『利用者情報の編集（○○・○○）』のように具体名が出るように。※既存の古い通知は文言が固定のため変わりません(以後の編集から反映)。ホームb7ac04d\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">家族・ケアマネの『利用者情報の編集』通知に変更項目名を全項目分表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">変更項目名を出す差分表に生年月日・性別・介護度・被保険者番号が含まれておらず、これらだけを編集した場合は項目名が出ず『利用者情報の編集』とだけ表示されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>差分表にこの4項目を追加し、どの項目を編集しても『利用者情報の編集（○○・○○）』のように具体名が出るように。※既存の古い通知は文言が固定のため変わりません(以後の編集から反映)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b7ac04d</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"支援経過表に負担割合変更・各種更新通知・アカウント発行を自動記録支援経過表(利用者に関わる経過の記録)に、負担割合の変更やフェイスシート・利用者情報・保険証写真・アセスメントの更新、アカウント発行が載っていなかった。支援経過表は各データから毎回再生成する導出型のため、生成元(spautoevents)に『負担割合履歴・docupdates(各種更新通知)・家族/関係者アカウント』を追加。介護度/ケアマネ/サービス変更/休止/休み連絡/各種連絡/モニタリング/体力測定/担当者会議/初回報告/基本情報変更は従来どおり自動記録。利用者マスタ41deb07\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">支援経過表に負担割合変更・各種更新通知・アカウント発行を自動記録</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">支援経過表(利用者に関わる経過の記録)に、負担割合の変更やフェイスシート・利用者情報・保険証写真・アセスメントの更新、アカウント発行が載っていなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>支援経過表は各データから毎回再生成する導出型のため、生成元(spAutoEvents)に『負担割合履歴・docUpdates(各種更新通知)・家族/関係者アカウント』を追加。介護度/ケアマネ/サービス変更/休止/休み連絡/各種連絡/モニタリング/体力測定/担当者会議/初回報告/基本情報変更は従来どおり自動記録。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">41deb07</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"削除したログインidが再利用できない不具合を修正招待セルフ登録の最終id重複チェックが古いローカルデータを参照し、他端末で削除済みのidが残っていると『事前は使える→登録でng』の矛盾になっていた。supabase有効時はsupabaseの判定を正とし、ローカルのみの重複拒否はsupabase無効時に限定。削除したidを再利用できるように。家族アプリcd60129\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">削除したログインIDが再利用できない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">招待セルフ登録の最終ID重複チェックが古いローカルデータを参照し、他端末で削除済みのIDが残っていると『事前は使える→登録でNG』の矛盾になっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>Supabase有効時はSupabaseの判定を正とし、ローカルのみの重複拒否はSupabase無効時に限定。削除したIDを再利用できるように。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">cd60129</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"担当ケアマネ欄に登録ケアマネ(アカウント)一覧を表示(複数対応)ケアマネのアカウントを追加しても基本情報・フェイスシートに現れず、どこにも反映されないように見えた(先の緊急連絡先非表示化とも整合させる必要)。利用者に紐づくケアマネアカウント(kind=caremanager等)を担当ケアマネ欄に一覧表示。複数のケアマネも表示され、追加登録が反映される。担当(事業所/担当者)の変更は従来どおり『担当を変更』。利用者マスタc73942d\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">担当ケアマネ欄に登録ケアマネ(アカウント)一覧を表示(複数対応)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">ケアマネのアカウントを追加しても基本情報・フェイスシートに現れず、どこにも反映されないように見えた(先の緊急連絡先非表示化とも整合させる必要)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>利用者に紐づくケアマネアカウント(kind=caremanager等)を担当ケアマネ欄に一覧表示。複数のケアマネも表示され、追加登録が反映される。担当(事業所/担当者)の変更は従来どおり『担当を変更』。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c73942d</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"ケアマネ連携\" data-text=\"ケアマネ/家族画面の保険証等で『表示中に問題が発生しました』(familystoreid未定義)を修正子コンポーネント familypatientview が familystoreid(親familyviewで定義)を受け取っておらず、保険証(cmdocsmodal)の描画やケアマネのフェイスシート保存で familystoreid を参照した瞬間に referenceerror となり、家族/ケアマネ画面全体がエラー画面に落ちていた。pc/端末やキャッシュにより発生タイミングが違って見えた。familyview から familystoreid を prop として familypatientview へ渡すよう修正。保険証・アセスメント表示やcm保存が落ちなくなる。ケアマネ連携b2fa3d9\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ケアマネ連携</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">ケアマネ/家族画面の保険証等で『表示中に問題が発生しました』(familyStoreId未定義)を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">子コンポーネント FamilyPatientView が familyStoreId(親FamilyViewで定義)を受け取っておらず、保険証(CmDocsModal)の描画やケアマネのフェイスシート保存で familyStoreId を参照した瞬間に ReferenceError となり、家族/ケアマネ画面全体がエラー画面に落ちていた。PC/端末やキャッシュにより発生タイミングが違って見えた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>FamilyView から familyStoreId を prop として FamilyPatientView へ渡すよう修正。保険証・アセスメント表示やCM保存が落ちなくなる。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b2fa3d9</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"家族・ケアマネのログインux改善(利用規約1回化・ホーム追加案内・q&amp;a・規約リンク)利用規約が毎回表示され煩わしかった。高齢者がホーム画面追加やログイン失敗時に迷いやすい。ログイン後に規約を見返す導線も無かった。利用規約の再同意を端末×ポリシー版で記録し同じ版なら二度と出さない(1回)。ログイン画面に『ホーム画面に追加する方法』(ios/android手順)と『ログインできない時(q&amp;a)』を追加。ログイン後フッターに『利用規約・プライバシーポリシー』閲覧リンクを追加。家族アプリ8cdbaab\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">家族・ケアマネのログインUX改善(利用規約1回化・ホーム追加案内・Q&amp;A・規約リンク)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">利用規約が毎回表示され煩わしかった。高齢者がホーム画面追加やログイン失敗時に迷いやすい。ログイン後に規約を見返す導線も無かった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>利用規約の再同意を端末×ポリシー版で記録し同じ版なら二度と出さない(1回)。ログイン画面に『ホーム画面に追加する方法』(iOS/Android手順)と『ログインできない時(Q&amp;A)』を追加。ログイン後フッターに『利用規約・プライバシーポリシー』閲覧リンクを追加。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8cdbaab</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"アカウント管理の操作ボタン潰れを修正＋エラー画面に原因表示アカウント一覧の操作ボタンが col-span-1(約8%幅)に押し込まれ、スマホで潰れて見切れていた。また画面エラー時に原因が極薄色で読めなかった。操作ボタンにラベル(id編集/印刷/削除)を付け、スマホでは縦積みに(grid 4+3+2+3)。エラー画面は原因(スタック)を読める色で表示。家族アプリa4f60c9\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">アカウント管理の操作ボタン潰れを修正＋エラー画面に原因表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">アカウント一覧の操作ボタンが col-span-1(約8%幅)に押し込まれ、スマホで潰れて見切れていた。また画面エラー時に原因が極薄色で読めなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>操作ボタンにラベル(ID編集/印刷/削除)を付け、スマホでは縦積みに(grid 4+3+2+3)。エラー画面は原因(スタック)を読める色で表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a4f60c9</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"緊急連絡先: ケアマネを非表示化＋フェイスシートでの削除が反映されない不具合を修正①主要連絡先がケアマネ(続柄=ケアマネ等)でも緊急連絡先に表示されていた。②フェイスシートで連絡先を削除して保存しても、既存へのupsert(追加更新)のみで削除されず、墓石も無いため同期で復活していた。①主要連絡先がケアマネ由来なら緊急連絡先に出さない。②家族連絡先はフェイスシートの編集結果で置き換え(削除を反映)、ケアマネ連絡先は保持。削除分は墓石(_deletedec)に記録し同期でも復活させない。利用者マスタ725a3fd\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">緊急連絡先: ケアマネを非表示化＋フェイスシートでの削除が反映されない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①主要連絡先がケアマネ(続柄=ケアマネ等)でも緊急連絡先に表示されていた。②フェイスシートで連絡先を削除して保存しても、既存へのupsert(追加更新)のみで削除されず、墓石も無いため同期で復活していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>①主要連絡先がケアマネ由来なら緊急連絡先に出さない。②家族連絡先はフェイスシートの編集結果で置き換え(削除を反映)、ケアマネ連絡先は保持。削除分は墓石(_deletedEC)に記録し同期でも復活させない。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">725a3fd</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ケアマネ連携\" data-text=\"pdf/画像プレビューの×ボタンを見やすく＋pdfのボタン重複を解消×閉じるボタンが半透明の白で、白いpdf面の上だと見えなかった。またpdf時に『ダウンロード』と『別タブで開く』が重複していた。×ボタンを赤・白枠・影で明確化(最前面)。pdfは『別タブで開く』のみ、画像は『ダウンロード』のみ表示に整理。ケアマネ連携fb510e8\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">PDF/画像プレビューの×ボタンを見やすく＋PDFのボタン重複を解消</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">×閉じるボタンが半透明の白で、白いPDF面の上だと見えなかった。またPDF時に『ダウンロード』と『別タブで開く』が重複していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>×ボタンを赤・白枠・影で明確化(最前面)。PDFは『別タブで開く』のみ、画像は『ダウンロード』のみ表示に整理。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">fb510e8</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"その他関係者(訪問看護等)もフェイスシートへ一本化その他関係者だけ利用者マスタで編集する形が残り、他項目(氏名・連絡先・介護保険)をフェイスシートへ一本化した方針と不揃いだった。フェイスシートに『その他関係者』の編集枠(追加/削除・氏名/種別/事業所/電話/fax)を新設し、保存で利用者本体へ反映(事業所・ケアマネ両経路)。利用者マスタ基本情報のその他関係者は表形式(表示のみ)＋『フェイスシートで編集』に。利用者マスタ8f0483a\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">その他関係者(訪問看護等)もフェイスシートへ一本化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">その他関係者だけ利用者マスタで編集する形が残り、他項目(氏名・連絡先・介護保険)をフェイスシートへ一本化した方針と不揃いだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>フェイスシートに『その他関係者』の編集枠(追加/削除・氏名/種別/事業所/電話/FAX)を新設し、保存で利用者本体へ反映(事業所・ケアマネ両経路)。利用者マスタ基本情報のその他関係者は表形式(表示のみ)＋『フェイスシートで編集』に。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8f0483a</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"ケアマネ連携\" data-text=\"ケアマネ側で事業所が添付したpdf(保険証・負担割合証)が見れない不具合を修正事業所がアップロードしたpdfは type=&#x27;application/pdf&#x27; で保存されるが、ケアマネ画面のファイル表示は type===&#x27;pdf&#x27;(完全一致)で判定していたため、事業所pdfが画像扱いになり壊れて表示されていた(ケアマネ自身がアップした分は type=&#x27;pdf&#x27; のため見れていた)。加えて data uri のpdfはブラウザがiframe/別タブでブロックする。ファイル表示・プレビューのpdf判定を『type部分一致 または .pdf名』に堅牢化。data uri のpdfは blob url に変換して表示し、『別タブで開く』ボタンも追加。事業所・ケアマネのどちらが添付したpdfも双方で閲覧可能に。ケアマネ連携52590d4\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">ケアマネ側で事業所が添付したPDF(保険証・負担割合証)が見れない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">事業所がアップロードしたPDFは type=&#x27;application/pdf&#x27; で保存されるが、ケアマネ画面のファイル表示は type===&#x27;pdf&#x27;(完全一致)で判定していたため、事業所PDFが画像扱いになり壊れて表示されていた(ケアマネ自身がアップした分は type=&#x27;pdf&#x27; のため見れていた)。加えて data URI のPDFはブラウザがiframe/別タブでブロックする。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>ファイル表示・プレビューのPDF判定を『type部分一致 または .pdf名』に堅牢化。data URI のPDFは Blob URL に変換して表示し、『別タブで開く』ボタンも追加。事業所・ケアマネのどちらが添付したPDFも双方で閲覧可能に。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">52590d4</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"基本情報の並び調整＋担当ケアマネ・緊急連絡先も表形式に統一介護保険の期間が値と離れて分かりにくく、担当ケアマネ・緊急連絡先だけ従来の入力欄形式で見た目が不揃いだった。介護度の直下に認定有効期間、負担割合の直下に負担割合の有効期間を配置。担当ケアマネは表形式(表示のみ)＋『担当を変更』ボタン(履歴付きモーダル)、緊急連絡先は表形式(主要＋追加をまとめて表示)＋『フェイスシートで編集』に統一。利用者マスタ5177da2\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">基本情報の並び調整＋担当ケアマネ・緊急連絡先も表形式に統一</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">介護保険の期間が値と離れて分かりにくく、担当ケアマネ・緊急連絡先だけ従来の入力欄形式で見た目が不揃いだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>介護度の直下に認定有効期間、負担割合の直下に負担割合の有効期間を配置。担当ケアマネは表形式(表示のみ)＋『担当を変更』ボタン(履歴付きモーダル)、緊急連絡先は表形式(主要＋追加をまとめて表示)＋『フェイスシートで編集』に統一。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5177da2</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"利用者マスタ基本情報(表示のみ)を表形式に変更し見やすく表示のみ化した基本情報が「ラベル 値／ラベル 値」の2列詰めで、項目が追いづらく見づらかった。ラベル＝左(薄い背景)／値＝右の行(表)形式に統一(氏名・介護保険・住所連絡先の各カード)。罫線区切りで一覧性を向上。利用者マスタa191a33\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">利用者マスタ基本情報(表示のみ)を表形式に変更し見やすく</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">表示のみ化した基本情報が「ラベル 値／ラベル 値」の2列詰めで、項目が追いづらく見づらかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>ラベル＝左(薄い背景)／値＝右の行(表)形式に統一(氏名・介護保険・住所連絡先の各カード)。罫線区切りで一覧性を向上。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a191a33</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"利用者マスタ基本情報を表示のみ化し、編集をフェイスシート／個人ファイルへ一本化(仕上げ)氏名・住所・連絡先・被保険者番号・介護保険が複数画面で編集でき『どこで入力するか』が分かりにくかった。編集場所が一本化されれば、慣れない人でも迷わず、二重編集の巻き戻りも防げる。利用者マスタ基本情報の 氏名/フリガナ/性別/生年月日・住所/電話/メール・被保険者番号 を表示のみに。各ブロックの『フェイスシートで編集』で個人ファイルのフェイスシートを自動オープン、介護度・負担割合・認定期間は『個人ファイルで編集』で保険証/負担割合証へジャンプ。運用項目(利用状態・利用開始/終了日・担当ケアマネ)はマスタで編集可のまま。利用者マスタd8e377f\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">利用者マスタ基本情報を表示のみ化し、編集をフェイスシート／個人ファイルへ一本化(仕上げ)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">氏名・住所・連絡先・被保険者番号・介護保険が複数画面で編集でき『どこで入力するか』が分かりにくかった。編集場所が一本化されれば、慣れない人でも迷わず、二重編集の巻き戻りも防げる。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>利用者マスタ基本情報の 氏名/フリガナ/性別/生年月日・住所/電話/メール・被保険者番号 を表示のみに。各ブロックの『フェイスシートで編集』で個人ファイルのフェイスシートを自動オープン、介護度・負担割合・認定期間は『個人ファイルで編集』で保険証/負担割合証へジャンプ。運用項目(利用状態・利用開始/終了日・担当ケアマネ)はマスタで編集可のまま。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d8e377f</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"フェイスシートを利用者情報の編集ハブ化(本人情報・被保険者番号・留意点を編集可＋誰が編集しても1箇所に反映)氏名・住所・電話・被保険者番号等が利用者マスタでしか編集できず、フェイスシート・個人ファイルとの役割が曖昧だった。事業所・ケアマネ・家族が別々の画面で編集し、どこが正か分かりにくい。フェイスシートで氏名/フリガナ/生年月日/性別/住所/電話/メール/被保険者番号/留意点を編集可能にし、保存時に利用者本体へ書き戻す(事業所・ケアマネ両経路)。誰が編集しても最終反映先は利用者本体の1箇所に統一。あわせて保険証・負担割合証の期間入力を和暦のみ(西暦カレンダー廃止)に。※マスタ側の該当項目を表示のみにする対応は次段階。利用者マスタ02ecdb6\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">フェイスシートを利用者情報の編集ハブ化(本人情報・被保険者番号・留意点を編集可＋誰が編集しても1箇所に反映)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">氏名・住所・電話・被保険者番号等が利用者マスタでしか編集できず、フェイスシート・個人ファイルとの役割が曖昧だった。事業所・ケアマネ・家族が別々の画面で編集し、どこが正か分かりにくい。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>フェイスシートで氏名/フリガナ/生年月日/性別/住所/電話/メール/被保険者番号/留意点を編集可能にし、保存時に利用者本体へ書き戻す(事業所・ケアマネ両経路)。誰が編集しても最終反映先は利用者本体の1箇所に統一。あわせて保険証・負担割合証の期間入力を和暦のみ(西暦カレンダー廃止)に。※マスタ側の該当項目を表示のみにする対応は次段階。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">02ecdb6</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"介護保険・負担割合の適用期間の表示を和暦に統一適用期間・変更履歴が西暦(2026/4/1等)表示で、介護保険証・負担割合証の実物(和暦)と突き合わせづらかった。マスタ基本情報の認定有効期間・負担割合の有効期間の表示、および変更履歴(valuehistorylist)の期間表示を和暦(令和8年4月1日等)に変更。利用者マスタc146458\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">介護保険・負担割合の適用期間の表示を和暦に統一</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">適用期間・変更履歴が西暦(2026/4/1等)表示で、介護保険証・負担割合証の実物(和暦)と突き合わせづらかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>マスタ基本情報の認定有効期間・負担割合の有効期間の表示、および変更履歴(ValueHistoryList)の期間表示を和暦(令和8年4月1日等)に変更。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c146458</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"介護保険(介護度・負担割合・認定期間)の編集を個人ファイルへ一本化(マスタ基本情報は表示のみ＋ジャンプ)同じ介護度・負担割合・認定期間が『利用者マスタの基本情報』と『個人ファイル』の両方で編集でき、どちらで入力するか分かりにくく、二重編集による巻き戻りの温床でもあった。証の写真は個人ファイルにしか貼れない。マスタ基本情報では介護度・負担割合・認定有効期間を表示のみにし、『個人ファイルで編集』ボタンで個人ファイル(保険証・負担割合証)へジャンプ＋該当セクションへ自動スクロール。編集場所を個人ファイルに一本化(写真と同じ場所で管理)。被保険者番号は個人ファイルに編集欄が無いためマスタ編集のまま残置。氏名・住所・電話等の個人ファイルへの移設は編集ui新設が必要なため次段階。利用者マスタ2f6fcac\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">介護保険(介護度・負担割合・認定期間)の編集を個人ファイルへ一本化(マスタ基本情報は表示のみ＋ジャンプ)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">同じ介護度・負担割合・認定期間が『利用者マスタの基本情報』と『個人ファイル』の両方で編集でき、どちらで入力するか分かりにくく、二重編集による巻き戻りの温床でもあった。証の写真は個人ファイルにしか貼れない。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>マスタ基本情報では介護度・負担割合・認定有効期間を表示のみにし、『個人ファイルで編集』ボタンで個人ファイル(保険証・負担割合証)へジャンプ＋該当セクションへ自動スクロール。編集場所を個人ファイルに一本化(写真と同じ場所で管理)。被保険者番号は個人ファイルに編集欄が無いためマスタ編集のまま残置。氏名・住所・電話等の個人ファイルへの移設は編集UI新設が必要なため次段階。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2f6fcac</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"個人ファイルの介護保険証・負担割合証を「選択即保存」から「保存ボタンで確定」に個人ファイル(利用者を開いた詳細画面)の保険証(介護度・認定有効期間)/負担割合証(負担割合・有効期間)は、プルダウンや日付を選んだ瞬間に利用者マスタへ自動保存・履歴記録されていた。期間を決める前の暫定選択がそのまま確定してしまう。選択・期間変更は下書きに溜め、『保存』ボタンを押したときだけ確定(取消可)する方式に変更。従来のインライン自動保存を廃止。※前回の対応は利用者マスタ管理の別レイアウト側で、実際に使う個人ファイル側に未反映だったのを修正。利用者マスタa1dd0d3\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">個人ファイルの介護保険証・負担割合証を「選択即保存」から「保存ボタンで確定」に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">個人ファイル(利用者を開いた詳細画面)の保険証(介護度・認定有効期間)/負担割合証(負担割合・有効期間)は、プルダウンや日付を選んだ瞬間に利用者マスタへ自動保存・履歴記録されていた。期間を決める前の暫定選択がそのまま確定してしまう。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>選択・期間変更は下書きに溜め、『保存』ボタンを押したときだけ確定(取消可)する方式に変更。従来のインライン自動保存を廃止。※前回の対応は利用者マスタ管理の別レイアウト側で、実際に使う個人ファイル側に未反映だったのを修正。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a1dd0d3</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"一括削除の「重複候補」に統合機能を追加（記録を残す1人へ引き継ぐ）利用者マスタの「重複」ボタン(統合)を各種設定へ集約するにあたり、各種設定側は削除しかできなかった。両方に記録がある重複を安全に1人へまとめる手段が必要だった。重複候補を同名でグループ化し、グループごとに『残す1人』をラジオで選んで統合できるように。統合すると他の重複の記録(提供記録・シフト・写真等)を残す人へ付け替え、空欄も補完してから重複を削除する(記録は失われない)。記録件数を各行に表示し、既定は記録が最も多い人を残す。各種設定188b16e\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">一括削除の「重複候補」に統合機能を追加（記録を残す1人へ引き継ぐ）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">利用者マスタの「重複」ボタン(統合)を各種設定へ集約するにあたり、各種設定側は削除しかできなかった。両方に記録がある重複を安全に1人へまとめる手段が必要だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>重複候補を同名でグループ化し、グループごとに『残す1人』をラジオで選んで統合できるように。統合すると他の重複の記録(提供記録・シフト・写真等)を残す人へ付け替え、空欄も補完してから重複を削除する(記録は失われない)。記録件数を各行に表示し、既定は記録が最も多い人を残す。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">188b16e</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"介護度の適用期間を「変更ボタン→ポップアップ→保存」方式に変更（重複ボタンは各種設定へ集約し削除）直前の対応(下書き＋小さな保存ボタン)は、編集→保存の手数が多く分かりやすくなかった。また利用者マスタの「重複」統合は各種設定の一括削除(重複候補)へ機能を集約した。介護度の適用期間は、現在の期間を表示し「適用期間を変更」ボタンでポップアップを開き、介護度・開始日/終了日を選んで保存する方式に統一(負担割合・介護度変更と同じ操作感。期間の訂正では履歴を増やさない)。利用者マスタの「重複」ボタンは削除。利用者マスタ3002443\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">介護度の適用期間を「変更ボタン→ポップアップ→保存」方式に変更（重複ボタンは各種設定へ集約し削除）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">直前の対応(下書き＋小さな保存ボタン)は、編集→保存の手数が多く分かりやすくなかった。また利用者マスタの「重複」統合は各種設定の一括削除(重複候補)へ機能を集約した。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>介護度の適用期間は、現在の期間を表示し「適用期間を変更」ボタンでポップアップを開き、介護度・開始日/終了日を選んで保存する方式に統一(負担割合・介護度変更と同じ操作感。期間の訂正では履歴を増やさない)。利用者マスタの「重複」ボタンは削除。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3002443</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"各種設定\" data-text=\"利用者・ケアマネ事業所の一括削除が管理者以外でも操作できた問題を修正「管理者用」と表示しつつ、実際の表示条件が isadmin(=管理者に加えmanager職も含む)だったため、管理者以外のログインでも一括削除が使えてしまっていた。介護記録に紐づく重要データを消せる画面のため危険だった。ログイン情報カード等と同じ canadmin(管理者パスワード認証済み / super_admin / 管理者未設定時のみ)に統一。管理者以外には操作させず、未認証時は『管理者のみ』ゲート＋認証ボタンを表示する。各種設定0cb6b26\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">各種設定</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">利用者・ケアマネ事業所の一括削除が管理者以外でも操作できた問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">「管理者用」と表示しつつ、実際の表示条件が isAdmin(=管理者に加えmanager職も含む)だったため、管理者以外のログインでも一括削除が使えてしまっていた。介護記録に紐づく重要データを消せる画面のため危険だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>ログイン情報カード等と同じ canAdmin(管理者パスワード認証済み / super_admin / 管理者未設定時のみ)に統一。管理者以外には操作させず、未認証時は『管理者のみ』ゲート＋認証ボタンを表示する。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0cb6b26</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"一括削除に「重複候補」フィルタを追加(重複利用者の削除)氏名が同じ重複利用者(csv取込の二重登録等)を、利用者マスタの統合とは別に、まとめて確認・削除する手段が各種設定側に無かった。一括削除の利用者一覧に『重複候補』フィルタ(同名2件以上)を追加。各行に記録件数と重複バッジを表示し、記録0件の重複を選んで削除できるようにした。両方に記録がある場合は記録が消えるため、利用者マスタの『重複』統合(記録引き継ぎ)を案内。各種設定0cb6b26\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">一括削除に「重複候補」フィルタを追加(重複利用者の削除)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">氏名が同じ重複利用者(CSV取込の二重登録等)を、利用者マスタの統合とは別に、まとめて確認・削除する手段が各種設定側に無かった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>一括削除の利用者一覧に『重複候補』フィルタ(同名2件以上)を追加。各行に記録件数と重複バッジを表示し、記録0件の重複を選んで削除できるようにした。両方に記録がある場合は記録が消えるため、利用者マスタの『重複』統合(記録引き継ぎ)を案内。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0cb6b26</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"介護度の適用期間も選択即保存をやめ、確定ボタン方式に介護度の適用期間(カレンダー)を編集すると、確定前でも1.5秒後に自動保存され、暫定の期間がそのまま全端末へ反映されていた。期間は下書きに溜め、『この期間で保存』を押したときだけ保存する方式に変更(負担割合と同じ考え方)。取消もできる。利用者マスタ88ee804\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">介護度の適用期間も選択即保存をやめ、確定ボタン方式に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">介護度の適用期間(カレンダー)を編集すると、確定前でも1.5秒後に自動保存され、暫定の期間がそのまま全端末へ反映されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>期間は下書きに溜め、『この期間で保存』を押したときだけ保存する方式に変更(負担割合と同じ考え方)。取消もできる。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">88ee804</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"「元に戻す」でokしても記録が画面に反映されない不具合を修正復元は onsave で提供記録を更新するが、提供記録入力(recordview)の画面用データを作り直すエフェクトに「同じ日付で編集中(dirty)なら作り直さない」ガードがあり、復元が編集中フラグを落とさないため、データは復元されているのに画面が復元前のまま(=戻したのに変わらない)になっていた。復元の適用後に編集中フラグ(dirtyref)を落とし、必ず画面を作り直すようにした。これで選んだ時点の内容が即座に画面へ反映される。提供記録2ce8504\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">「元に戻す」でOKしても記録が画面に反映されない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">復元は onSave で提供記録を更新するが、提供記録入力(RecordView)の画面用データを作り直すエフェクトに「同じ日付で編集中(dirty)なら作り直さない」ガードがあり、復元が編集中フラグを落とさないため、データは復元されているのに画面が復元前のまま(=戻したのに変わらない)になっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>復元の適用後に編集中フラグ(dirtyRef)を落とし、必ず画面を作り直すようにした。これで選んだ時点の内容が即座に画面へ反映される。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2ce8504</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"ipad等で利用者マスタの右端が見切れる問題を修正画面は横1100px設計を前提にzoom縮小して各端末に合わせているが、利用者マスタは最大1800px・340px固定リスト＋多列で、ipad(縦810/横1080px)では実画面幅で多列レイアウトが発火して1100pxの枠をはみ出し、下までスクロールすると右端が切れていた。利用者マスタをzoom縮小の対象から外し、実際の画面幅で素直に折り返す方式に変更(pcは従来どおり)。端末ごとに画面領域へ収まるようにした。利用者マスタ2ce8504\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">iPad等で利用者マスタの右端が見切れる問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">画面は横1100px設計を前提にzoom縮小して各端末に合わせているが、利用者マスタは最大1800px・340px固定リスト＋多列で、iPad(縦810/横1080px)では実画面幅で多列レイアウトが発火して1100pxの枠をはみ出し、下までスクロールすると右端が切れていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>利用者マスタをzoom縮小の対象から外し、実際の画面幅で素直に折り返す方式に変更(PCは従来どおり)。端末ごとに画面領域へ収まるようにした。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2ce8504</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"負担割合をプルダウン選択した瞬間に保存されるのをやめ、確定ボタン方式に負担割合を選ぶと(適用期間を決める前でも)1.5秒後に自動でクラウド保存され、暫定選択がそのまま確定・全端末へ反映されてしまっていた。介護度と同じく、選択したら確認モーダルを開き、適用開始日/終了日を指定して「確定」を押したときだけ保存する方式に統一。誤選択がそのまま保存されないようにした。利用者マスタ2ce8504\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">負担割合をプルダウン選択した瞬間に保存されるのをやめ、確定ボタン方式に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">負担割合を選ぶと(適用期間を決める前でも)1.5秒後に自動でクラウド保存され、暫定選択がそのまま確定・全端末へ反映されてしまっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>介護度と同じく、選択したら確認モーダルを開き、適用開始日/終了日を指定して「確定」を押したときだけ保存する方式に統一。誤選択がそのまま保存されないようにした。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2ce8504</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"ホームの「家族・ケアマネからの更新」に、変更した項目名を表示家族・ケアマネが利用者情報を編集した通知が『利用者情報の編集』としか出ず、どこを直したのか分からなかった。編集前後を項目単位で比較し『利用者情報の編集（電話番号・住所 ほか）』のように変更項目名を表示(最大8件＋ほかn項目)。ホーム2ce8504\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">ホームの「家族・ケアマネからの更新」に、変更した項目名を表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">家族・ケアマネが利用者情報を編集した通知が『利用者情報の編集』としか出ず、どこを直したのか分からなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>編集前後を項目単位で比較し『利用者情報の編集（電話番号・住所 ほか）』のように変更項目名を表示(最大8件＋ほかN項目)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2ce8504</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"「元に戻す」の確認に、現在クラウド上の最新の端末・時刻を表示復元(元に戻す)は全端末へ「最新」として反映され、他端末の新しい入力を上書きしうる。従来の確認文は一般的な注意のみで、いま実際に誰が最新なのかが分からず、上書きの判断がしづらかった。確認ダイアログに _lastsync から「現在の最新: 『端末名』が 〇時 に更新」を常時表示。さらに、この復元スナップショットより後に別の端末が更新している場合のみ『⚠ この履歴より新しい更新が別端末にあります。復元すると上書きされます』を追加表示(自分が最新なら余計な警告は出さない)。提供記録a4f3d28\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">「元に戻す」の確認に、現在クラウド上の最新の端末・時刻を表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">復元(元に戻す)は全端末へ「最新」として反映され、他端末の新しい入力を上書きしうる。従来の確認文は一般的な注意のみで、いま実際に誰が最新なのかが分からず、上書きの判断がしづらかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>確認ダイアログに _lastSync から「現在の最新: 『端末名』が 〇時 に更新」を常時表示。さらに、この復元スナップショットより後に別の端末が更新している場合のみ『⚠ この履歴より新しい更新が別端末にあります。復元すると上書きされます』を追加表示(自分が最新なら余計な警告は出さない)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a4f3d28</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"端末名の設定と「最終更新した端末」の表示を追加複数の端末(pc・ipad等)で使うと、今どの端末の入力が最新か分からず、古い端末で上書きしていないか不安があった。以前検討した「入力ロック」は現場運用の妨げになるため見送り、代わりに『誰が最後に更新したか』を可視化する方針にした。各種設定＞システムに「この端末の名前」欄を追加(端末ごとにlocalstorageへ保存。他端末には送信しない)。記録の保存時に「最終更新した端末名・時刻」を全端末共有の _lastsync に記録し、画面上部ヘッダーと設定画面に常時表示。最終更新が自端末なら緑「この端末の内容が最新です」、別端末なら青「最新の更新は〇〇で行われました(この端末にも反映済み)」を表示。ヘッダーの表示をタップすると設定の端末名欄へジャンプ。各種設定c44b757\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">端末名の設定と「最終更新した端末」の表示を追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">複数の端末(PC・iPad等)で使うと、今どの端末の入力が最新か分からず、古い端末で上書きしていないか不安があった。以前検討した「入力ロック」は現場運用の妨げになるため見送り、代わりに『誰が最後に更新したか』を可視化する方針にした。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>各種設定＞システムに「この端末の名前」欄を追加(端末ごとにlocalStorageへ保存。他端末には送信しない)。記録の保存時に「最終更新した端末名・時刻」を全端末共有の _lastSync に記録し、画面上部ヘッダーと設定画面に常時表示。最終更新が自端末なら緑「この端末の内容が最新です」、別端末なら青「最新の更新は〇〇で行われました(この端末にも反映済み)」を表示。ヘッダーの表示をタップすると設定の端末名欄へジャンプ。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c44b757</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"操作ログ同期の切替で提供記録の保存先が一時的に失われた不具合を修正し、段階導入へ変更差分を作る処理が参照していた変数 prev がスコープ外にあり referenceerror となって、操作が1件も作られていなかった(診断ログ ops-diff-error &quot;prev is not defined&quot; で判明)。にもかかわらず巨大json側の ticketrecords を先に凍結していたため、「新方式は動かない×旧方式も止めてある」という状態になり、その間の提供記録の保存がクラウドのどこにも書かれなかった。切替を一度に行ったこと自体が設計判断の誤り。差分の直前状態を appdata から取得するよう修正。oplog_frozen_keys を空に戻して巨大json方式を再有効化し、新方式が動かなくても必ず保存される二重の保険とした。さらに oplog_apply フラグを追加し、第1段は「操作ログへの送信のみ」を本番で走らせる方式に変更。受信適用と旧方式の凍結は、送信の安定をログで確認してから第2段でまとめて有効化する。同期703dd4c\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-20</span></div>\n      <p class=\"title\">操作ログ同期の切替で提供記録の保存先が一時的に失われた不具合を修正し、段階導入へ変更</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">差分を作る処理が参照していた変数 prev がスコープ外にあり ReferenceError となって、操作が1件も作られていなかった(診断ログ ops-diff-error &quot;prev is not defined&quot; で判明)。にもかかわらず巨大JSON側の ticketRecords を先に凍結していたため、「新方式は動かない×旧方式も止めてある」という状態になり、その間の提供記録の保存がクラウドのどこにも書かれなかった。切替を一度に行ったこと自体が設計判断の誤り。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>差分の直前状態を appData から取得するよう修正。OPLOG_FROZEN_KEYS を空に戻して巨大JSON方式を再有効化し、新方式が動かなくても必ず保存される二重の保険とした。さらに OPLOG_APPLY フラグを追加し、第1段は「操作ログへの送信のみ」を本番で走らせる方式に変更。受信適用と旧方式の凍結は、送信の安定をログで確認してから第2段でまとめて有効化する。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">703dd4c</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"同期\" data-text=\"提供記録を操作ログ同期へ接続（送信・受信・リベース・凍結の実装）巨大jsonの往復方式では、2端末での編集時にマージの勝ち負けで入力が消える問題が構造的に解消できないため。保存時に変わった項目だけを差分化してindexeddbへ永続化し sync_ops へ送信、ackが返った分だけキューから削除。受信はrealtime＋5秒ポーリングで差分取得。適用は必ず「受信分＋自分の未送信分」の順で畳み込み(リベース)、他端末の更新を受けた瞬間に入力途中が消えないようにした。初回取得はページングで全件取得。差分化と適用の純関数を28ケースで検証。同期ec97394\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-07-20</span></div>\n      <p class=\"title\">提供記録を操作ログ同期へ接続（送信・受信・リベース・凍結の実装）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">巨大JSONの往復方式では、2端末での編集時にマージの勝ち負けで入力が消える問題が構造的に解消できないため。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>保存時に変わった項目だけを差分化してIndexedDBへ永続化し sync_ops へ送信、ACKが返った分だけキューから削除。受信はRealtime＋5秒ポーリングで差分取得。適用は必ず「受信分＋自分の未送信分」の順で畳み込み(リベース)、他端末の更新を受けた瞬間に入力途中が消えないようにした。初回取得はページングで全件取得。差分化と適用の純関数を28ケースで検証。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ec97394</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"同期\" data-text=\"同期方式の刷新に着手（操作ログ方式）：基盤モジュールとdbマイグレーションを用意時計補正・押し戻し遮断の修正後も同期停止が再発。根本原因は「アプリ全体の巨大jsonを1.2秒ごとに丸ごと送り合い、端末の時計でマージの勝敗を決めている」という構造そのものにある。加えて送信キューもackも無いため、iosの通信サスペンドで失われた送信は永久に失われる。「変更した項目だけを送る」操作ログ方式へ移行する。src/lib/syncops.js を新設（送信未確定キューをindexeddbに永続化／push_sync_ops rpcへの送信とackによるキュー削除／revision差分取得とrealtime購読／操作を状態へ畳み込む純関数applyops）。順序はpostgresのbigserial採番が決めるため端末の時計に一切依存しない。純関数部分を18ケース（項目更新・入れ子・新規作成・深い階層・二次元マップ・空文字・レコード削除・set→deleteの順序・リベース・後勝ち・参照維持）で検証済み。dbマイグレーションsql（sync_opsテーブル／push_sync_ops rpc／rls／realtime有効化。追加のみ・非破壊）を sql/2026-07-20_sync_ops_phase1.sql に用意。現時点ではアプリ本体から未接続のため動作に影響なし。外部レビュー（gemini提案書）のうち「クライアント代表がスナップショットを上書きする」案は今回の事故と同じ構造のため不採用とし、db側で畳み込む方式に変更した。同期a041567 / f08a148\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-07-20</span></div>\n      <p class=\"title\">同期方式の刷新に着手（操作ログ方式）：基盤モジュールとDBマイグレーションを用意</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">時計補正・押し戻し遮断の修正後も同期停止が再発。根本原因は「アプリ全体の巨大JSONを1.2秒ごとに丸ごと送り合い、端末の時計でマージの勝敗を決めている」という構造そのものにある。加えて送信キューもACKも無いため、iOSの通信サスペンドで失われた送信は永久に失われる。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>「変更した項目だけを送る」操作ログ方式へ移行する。src/lib/syncOps.js を新設（送信未確定キューをIndexedDBに永続化／push_sync_ops RPCへの送信とACKによるキュー削除／revision差分取得とRealtime購読／操作を状態へ畳み込む純関数applyOps）。順序はPostgresのbigserial採番が決めるため端末の時計に一切依存しない。純関数部分を18ケース（項目更新・入れ子・新規作成・深い階層・二次元マップ・空文字・レコード削除・SET→DELETEの順序・リベース・後勝ち・参照維持）で検証済み。DBマイグレーションSQL（sync_opsテーブル／push_sync_ops RPC／RLS／Realtime有効化。追加のみ・非破壊）を sql/2026-07-20_sync_ops_phase1.sql に用意。現時点ではアプリ本体から未接続のため動作に影響なし。外部レビュー（Gemini提案書）のうち「クライアント代表がスナップショットを上書きする」案は今回の事故と同じ構造のため不採用とし、DB側で畳み込む方式に変更した。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a041567 / f08a148</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"同期\" data-text=\"未同期バナーを撤去し、原因特定用の同期診断ログを追加未同期警告バナーが誤検知で常時表示され作業の邪魔になっていた。また、時計補正と押し戻しループの修正後も同期が止まる事象が再発したが、ipadではブラウザのコンソールが見られず原因を特定する手段が無かった。バナーの画面表示を廃止(検知自体は継続しログにのみ記録)。localstorageに直近120件の同期イベント(save/pull/pull-preserve/push-ok/push-fail/cas-conflict/clock-adjust/stall)を記録し、urlに ?syncdebug=1 を付けて開くと右下に同期ログパネルを表示できるようにした。再現時のログから、保存が発火しているか・クラウドへ届いているか・競合で失敗しているかを切り分ける。同期edbe195\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-07-20</span></div>\n      <p class=\"title\">未同期バナーを撤去し、原因特定用の同期診断ログを追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">未同期警告バナーが誤検知で常時表示され作業の邪魔になっていた。また、時計補正と押し戻しループの修正後も同期が止まる事象が再発したが、iPadではブラウザのコンソールが見られず原因を特定する手段が無かった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>バナーの画面表示を廃止(検知自体は継続しログにのみ記録)。localStorageに直近120件の同期イベント(save/pull/pull-preserve/push-ok/push-fail/cas-conflict/clock-adjust/stall)を記録し、URLに ?syncdebug=1 を付けて開くと右下に同期ログパネルを表示できるようにした。再現時のログから、保存が発火しているか・クラウドへ届いているか・競合で失敗しているかを切り分ける。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">edbe195</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"他端末の入力をクラウドから消し戻し続けるループを遮断pull(4秒ごと)の「端末内の記録を保持する」処理が、『端末内の_savedatがクラウドより新しい』というだけで記録を丸ごとクラウドへ押し戻していた。時計が進んだ端末ではこの条件が常に成立するため、他端末が入力するたびに4秒後に古い内容で上書きし直すループになり、同期が止まったように見えていた。さらに双方が押し合うことで楽観ロック(cas)の競合が増え、既定5回の再試行を使い切って保存自体が失敗することもあった。再送(push)するのは「クラウドに存在しない記録があるとき」＝pushが本当に届いていない場合だけに限定。クラウドにも存在する記録の新旧判定は、項目単位でマージする通常の保存経路に任せる。あわせて通常保存のcas再試行を5→8回に増強。保持・墓石・クラウド優先の各挙動は6ケースで回帰検証済み。同期1118876\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-20</span></div>\n      <p class=\"title\">他端末の入力をクラウドから消し戻し続けるループを遮断</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">pull(4秒ごと)の「端末内の記録を保持する」処理が、『端末内の_savedAtがクラウドより新しい』というだけで記録を丸ごとクラウドへ押し戻していた。時計が進んだ端末ではこの条件が常に成立するため、他端末が入力するたびに4秒後に古い内容で上書きし直すループになり、同期が止まったように見えていた。さらに双方が押し合うことで楽観ロック(CAS)の競合が増え、既定5回の再試行を使い切って保存自体が失敗することもあった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>再送(push)するのは「クラウドに存在しない記録があるとき」＝pushが本当に届いていない場合だけに限定。クラウドにも存在する記録の新旧判定は、項目単位でマージする通常の保存経路に任せる。あわせて通常保存のCAS再試行を5→8回に増強。保持・墓石・クラウド優先の各挙動は6ケースで回帰検証済み。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1118876</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"端末間の時計ズレで同期が止まり、入力が消える不具合を恒久修正同期のマージは記録の _savedat / _fieldts（保存時刻）が新しい方を採用する方式だが、この時刻は各端末の date.now()＝端末の時計そのものだった。pcの時計がipadより進んでいると、ipadで入力した内容は常に「古い」と判定されてマージで捨てられる。画面上はエラーも出ないため同期が止まったように見え、再読み込みするとクラウドの古い内容に戻って入力が消える。長文入力ほど同一項目を上書きし続けるため発症しやすかった。同期専用の単調時計(lamport clock)を導入。app_state に __clock（そのデータの最大同期時刻）を持たせ、クラウドを読むたびに自端末のオフセットを引き上げて「クラウドで見た最新より必ず新しい時刻」を刻むようにした。これで端末の時計がずれていても後から行った入力が必ず勝つ。__clock を持たない既存データは記録の _savedat 最大値から初期化。400日以上先の異常な時刻は取り込まない安全弁つき。あわせて _savedat/_fieldts/_updatedat の刻印を全26箇所で新方式に統一。さらに、ローカル編集から20秒以上クラウド保存が成功していない場合は画面上部に「⚠ クラウドに保存できていません（n秒未同期）」＋「今すぐ再送」を常時表示し、同期停止が無表示のまま続かないようにした。同期18fda72\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-20</span></div>\n      <p class=\"title\">端末間の時計ズレで同期が止まり、入力が消える不具合を恒久修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">同期のマージは記録の _savedAt / _fieldTs（保存時刻）が新しい方を採用する方式だが、この時刻は各端末の Date.now()＝端末の時計そのものだった。PCの時計がiPadより進んでいると、iPadで入力した内容は常に「古い」と判定されてマージで捨てられる。画面上はエラーも出ないため同期が止まったように見え、再読み込みするとクラウドの古い内容に戻って入力が消える。長文入力ほど同一項目を上書きし続けるため発症しやすかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>同期専用の単調時計(Lamport clock)を導入。app_state に __clock（そのデータの最大同期時刻）を持たせ、クラウドを読むたびに自端末のオフセットを引き上げて「クラウドで見た最新より必ず新しい時刻」を刻むようにした。これで端末の時計がずれていても後から行った入力が必ず勝つ。__clock を持たない既存データは記録の _savedAt 最大値から初期化。400日以上先の異常な時刻は取り込まない安全弁つき。あわせて _savedAt/_fieldTs/_updatedAt の刻印を全26箇所で新方式に統一。さらに、ローカル編集から20秒以上クラウド保存が成功していない場合は画面上部に「⚠ クラウドに保存できていません（N秒未同期）」＋「今すぐ再送」を常時表示し、同期停止が無表示のまま続かないようにした。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">18fda72</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"ケアマネ連携\" data-text=\"事業所の更新をケアマネへ通知：変更項目名の明示と保険証内容変更の追加フェイスシート更新の通知が「フェイスシート」としか出ず、どこを変えたか分からなかった。また介護保険証・負担割合証は「添付ファイルの更新」しか通知されず、要介護度や負担割合の内容変更はケアマネに届かなかった。新旧フェイスシートを項目単位で差分比較する difffacesheetfields を追加し「フェイスシート（服薬状況・通所の経緯）」のように変更項目名を表示（最大8件＋ほかn項目）。利用者マスタで要介護度／認定有効期間／負担割合を変更した際も、ケアマネにのみ未読通知（by=office / readcm=false）を発行。逆方向（ケアマネの編集→事業所ホーム「家族・ケアマネからの更新」）も項目名を表示。ケアマネ連携cdecfc6\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-07-20</span></div>\n      <p class=\"title\">事業所の更新をケアマネへ通知：変更項目名の明示と保険証内容変更の追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">フェイスシート更新の通知が「フェイスシート」としか出ず、どこを変えたか分からなかった。また介護保険証・負担割合証は「添付ファイルの更新」しか通知されず、要介護度や負担割合の内容変更はケアマネに届かなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>新旧フェイスシートを項目単位で差分比較する diffFaceSheetFields を追加し「フェイスシート（服薬状況・通所の経緯）」のように変更項目名を表示（最大8件＋ほかN項目）。利用者マスタで要介護度／認定有効期間／負担割合を変更した際も、ケアマネにのみ未読通知（by=office / readCm=false）を発行。逆方向（ケアマネの編集→事業所ホーム「家族・ケアマネからの更新」）も項目名を表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">cdecfc6</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"計画書\" data-text=\"計画書4様式に一時保存を統一・残りの日付欄もカレンダー化一時保存が通所計画書のみで、個別機能訓練・生活機能チェック・興味関心は途中保存できず、一部の日付が手入力のままだった。4様式すべてに「一時保存／保存して閉じる」を追加。発症日・入院日・退院日・作成日等もカレンダー選択に統一。計画書98add01\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-18</span></div>\n      <p class=\"title\">計画書4様式に一時保存を統一・残りの日付欄もカレンダー化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">一時保存が通所計画書のみで、個別機能訓練・生活機能チェック・興味関心は途中保存できず、一部の日付が手入力のままだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>4様式すべてに「一時保存／保存して閉じる」を追加。発症日・入院日・退院日・作成日等もカレンダー選択に統一。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">98add01</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"負担割合証：開始日を選び直したら常に1年後を終了日に設定「終了日が空のときだけ」1年後を計算していたため、開始日を選び直しても既存の終了日が更新されず、今日基準の古い値が残っていた。開始日を変えたら常に 終了日＝開始日＋1年−1日 を再設定。うるう年含め検証。利用者マスタe8cb276\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-18</span></div>\n      <p class=\"title\">負担割合証：開始日を選び直したら常に1年後を終了日に設定</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">「終了日が空のときだけ」1年後を計算していたため、開始日を選び直しても既存の終了日が更新されず、今日基準の古い値が残っていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>開始日を変えたら常に 終了日＝開始日＋1年−1日 を再設定。うるう年含め検証。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e8cb276</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"計画書\" data-text=\"通所介護計画書：日付のカレンダー選択・一時保存・目標期間の逆コピー日付が手入力のみ、途中保存ができず、期間コピーの向きが実務と逆だった。作成日・目標・提供内容①〜⑤等をカレンダー選択に。一時保存を追加。長期目標の期間を①〜⑤へ下ろすコピーに変更。計画書86d5926\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-18</span></div>\n      <p class=\"title\">通所介護計画書：日付のカレンダー選択・一時保存・目標期間の逆コピー</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">日付が手入力のみ、途中保存ができず、期間コピーの向きが実務と逆だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>作成日・目標・提供内容①〜⑤等をカレンダー選択に。一時保存を追加。長期目標の期間を①〜⑤へ下ろすコピーに変更。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">86d5926</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"生活機能チェックのadlからbarthel点数を提案同じ10項目を生活機能チェックとbarthelで二度入力していた。生活機能チェックのadl→barthel点数の対応表を作り、取り込みボタンで自動提案（最終確認は職員）。life加算c1c5f93\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">生活機能チェックのADLからBarthel点数を提案</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">同じ10項目を生活機能チェックとBarthelで二度入力していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>生活機能チェックのADL→Barthel点数の対応表を作り、取り込みボタンで自動提案（最終確認は職員）。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c1c5f93</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"計画書\" data-text=\"生活機能チェック：項目名とプルダウンの間隔・幅を調整ラベルが固定幅でプルダウンが伸び、隣の項目とくっついて読みにくかった。項目名にプルダウンを寄せ、幅を縮小し、列間を広げた。計画書193774f\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">生活機能チェック：項目名とプルダウンの間隔・幅を調整</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">ラベルが固定幅でプルダウンが伸び、隣の項目とくっついて読みにくかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>項目名にプルダウンを寄せ、幅を縮小し、列間を広げた。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">193774f</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"計画書\" data-text=\"計画書：フェイスシート連携の参照先を修正・自動作成を廃止・1日の流れ/提供区分を自動化フェイスシートの保存先を取り違え、連携が丸ごと不動だった（自立度が入らない等）。利用者追加時に空の計画書が自動作成されていた。正しい保存先を参照。自動作成を廃止。1日の流れ（am/pm両方）と提供時間区分を自動算出。計画書700fe4a\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">計画書</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">計画書：フェイスシート連携の参照先を修正・自動作成を廃止・1日の流れ/提供区分を自動化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">フェイスシートの保存先を取り違え、連携が丸ごと不動だった（自立度が入らない等）。利用者追加時に空の計画書が自動作成されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>正しい保存先を参照。自動作成を廃止。1日の流れ（AM/PM両方）と提供時間区分を自動算出。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">700fe4a</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳：反映元の「未選択」を廃止し、無効なら先頭項目に連動連動を選んでも未選択では自由記述と変わらず無意味だった。未選択という状態をなくし、無効なら先頭の運動項目に自動連動。表示と実挙動を一致させた。連絡帳7344829\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">連絡帳：反映元の「未選択」を廃止し、無効なら先頭項目に連動</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">連動を選んでも未選択では自由記述と変わらず無意味だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>未選択という状態をなくし、無効なら先頭の運動項目に自動連動。表示と実挙動を一致させた。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7344829</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳：反映元が未設定でも設定済みに見える問題を修正選択肢に空欄が無く、連動先が無効でもブラウザが先頭項目を表示。設定済みに見えて実際は連動しなかった。無効な連動先を検知し、名前一致でも値を拾えるよう解決規則を統一。連絡帳45c32c8\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">連絡帳：反映元が未設定でも設定済みに見える問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">選択肢に空欄が無く、連動先が無効でもブラウザが先頭項目を表示。設定済みに見えて実際は連動しなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>無効な連動先を検知し、名前一致でも値を拾えるよう解決規則を統一。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">45c32c8</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析\" data-text=\"分析個人：○の規定値を「月初」でなく記録の実日付で引く規定値を月の1日時点で引いていたため、月途中に設定した規定値が反映されず、店舗差になっていた。記録の実日付で規定値を引くよう修正。設定タイミングに関わらず反映。分析c5df252\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">分析個人：○の規定値を「月初」でなく記録の実日付で引く</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">規定値を月の1日時点で引いていたため、月途中に設定した規定値が反映されず、店舗差になっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>記録の実日付で規定値を引くよう修正。設定タイミングに関わらず反映。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c5df252</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析\" data-text=\"分析個人：○で規定値をグラフに反映・個別運動は選択した種目名で表示規定値の取得がid直接一致のみで、項目を作り直した店舗で取れなかった。個別運動が「個別運動①」表示だった。id一致→同名で解決。個別運動は選択した種目名（屋外歩行訓練等）で表示。分析c300df8\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">分析個人：○で規定値をグラフに反映・個別運動は選択した種目名で表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">規定値の取得がid直接一致のみで、項目を作り直した店舗で取れなかった。個別運動が「個別運動①」表示だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>id一致→同名で解決。個別運動は選択した種目名（屋外歩行訓練等）で表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c300df8</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"提供記録入力：規定値がセルに収まるようフォントを縮小文字サイズを入力値の長さだけで決め、規定値だけ表示の空セルで長い値がはみ出していた。規定値の長さも考慮してフォントサイズを決定。提供記録ac31e0d\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">提供記録入力：規定値がセルに収まるようフォントを縮小</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">文字サイズを入力値の長さだけで決め、規定値だけ表示の空セルで長い値がはみ出していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>規定値の長さも考慮してフォントサイズを決定。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ac31e0d</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析\" data-text=\"分析個人：○は規定値を反映・個別運動の規定値ルックアップを修正○に単位が付き「○分」と表示。個別運動の規定値を持たない側を先に見て常に空だった。記号に単位を付けない。個別運動は利用者側の規定値を優先（3箇所修正）。分析9526174\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">分析個人：○は規定値を反映・個別運動の規定値ルックアップを修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">○に単位が付き「○分」と表示。個別運動の規定値を持たない側を先に見て常に空だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>記号に単位を付けない。個別運動は利用者側の規定値を優先（3箇所修正）。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9526174</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析\" data-text=\"店舗によって運動の○が分析個人に反映されない不具合を修正分析個人がid直接一致でしか値を引かず、項目を作り直した店舗だけ「記録なし」になっていた。idが変わっても同名で拾う解決関数に統一。分析add9d88\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">店舗によって運動の○が分析個人に反映されない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">分析個人がid直接一致でしか値を引かず、項目を作り直した店舗だけ「記録なし」になっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>idが変わっても同名で拾う解決関数に統一。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">add9d88</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析\" data-text=\"分析個人：○(実施)の記録が規定値未設定の月に消える不具合を修正○を規定値に置換する際、規定値が未設定の月は空を返し、実施記録が「記録なし」扱いになっていた。規定値が無くても○のまま残す。分析ffcf5d6\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">分析個人：○(実施)の記録が規定値未設定の月に消える不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">○を規定値に置換する際、規定値が未設定の月は空を返し、実施記録が「記録なし」扱いになっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>規定値が無くても○のまま残す。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ffcf5d6</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析\" data-text=\"体力測定グラフ：最低のフォントを揃え、開始位置の右寄りを直す最低のラベルだけ極端に小さく、1件時にグラフ開始点が大きく右へずれていた。体温グラフと同じ体裁に統一し、固定ステップ＋左パディング方式に。分析9b76c39\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">体力測定グラフ：最低のフォントを揃え、開始位置の右寄りを直す</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">最低のラベルだけ極端に小さく、1件時にグラフ開始点が大きく右へずれていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>体温グラフと同じ体裁に統一し、固定ステップ＋左パディング方式に。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9b76c39</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"体力測定\" data-text=\"体力測定：タップでテンキー表示・全角入力を半角へ自動変換身長体重等の数値入力でテンキーが出ず、全角入力すると値が消えることがあった。提供記録と同じテンキーを表示。全角数字・句読点を半角へ自動変換。体力測定41549bc\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">体力測定</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">体力測定：タップでテンキー表示・全角入力を半角へ自動変換</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">身長体重等の数値入力でテンキーが出ず、全角入力すると値が消えることがあった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>提供記録と同じテンキーを表示。全角数字・句読点を半角へ自動変換。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">41549bc</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"利用者マスタの電話番号（固定/携帯）に自動でハイフンを付与既存フォーマッタから漏れ、全角入力で番号が消える不具合もあった。共通フォーマッタに統一し、全角対応も追加。12ケースで検証。利用者マスタ50aa40b\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">利用者マスタの電話番号（固定/携帯）に自動でハイフンを付与</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">既存フォーマッタから漏れ、全角入力で番号が消える不具合もあった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>共通フォーマッタに統一し、全角対応も追加。12ケースで検証。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">50aa40b</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"計画書\" data-text=\"作成予定をホームからサイドバー「計画書 &gt; 作成予定」へ移動導入直後は全員が未作成で件数が膨らみ、ホームで実用にならなかった。専用画面に移動。未作成は既定で隠し、必要時に表示できるように。計画書b6ec8b9\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">作成予定をホームからサイドバー「計画書 &gt; 作成予定」へ移動</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">導入直後は全員が未作成で件数が膨らみ、ホームで実用にならなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>専用画面に移動。未作成は既定で隠し、必要時に表示できるように。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b6ec8b9</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"計画書\" data-text=\"計画書・加算の作成時期を通知作成期限の把握手段がなく、作成漏れが起きやすかった。期限の1ヶ月前から、誰の・何を・いつまでにを月ごとに表示。計画書f86b363\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">計画書・加算の作成時期を通知</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">作成期限の把握手段がなく、作成漏れが起きやすかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>期限の1ヶ月前から、誰の・何を・いつまでにを月ごとに表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f86b363</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"計画書\" data-text=\"共通項目の連携：自立度をフェイスシート起点に統一自立度が3画面で別名保存され、半角/全角の違いで○が付かなかった。表記ゆれを吸収し、フェイスシートを正として各計画書へ取り込み。計画書67e213a\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">共通項目の連携：自立度をフェイスシート起点に統一</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">自立度が3画面で別名保存され、半角/全角の違いで○が付かなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>表記ゆれを吸収し、フェイスシートを正として各計画書へ取り込み。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">67e213a</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"計画書\" data-text=\"個別機能訓練計画書（様式3-3）をa4 1枚で使い切る高さ指定がなく下部に余白が残っていた。a4実寸の縦フレックスにし、各記入欄を比率配分。計画書eb4f153\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">個別機能訓練計画書（様式3-3）をA4 1枚で使い切る</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">高さ指定がなく下部に余白が残っていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>A4実寸の縦フレックスにし、各記入欄を比率配分。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">eb4f153</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"提供記録\" data-text=\"月モードの保存で他の月の記録が全て消えるバグを修正選択月のみ保持する配列で全記録を置換しており、保存で他月が失われる構造だった（未使用画面／予防）。id単位のマージに変更し、選択月以外を必ず温存。提供記録dc4a6c0\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">月モードの保存で他の月の記録が全て消えるバグを修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">選択月のみ保持する配列で全記録を置換しており、保存で他月が失われる構造だった（未使用画面／予防）。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>id単位のマージに変更し、選択月以外を必ず温存。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">dc4a6c0</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"検索一覧の表示を提供記録入力に完全に合わせる色・脈表記・介護整体列が入力画面と揃っていなかった。状態色・脈（）表記・介護整体列を入力画面と統一。提供記録61bb967\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">検索一覧の表示を提供記録入力に完全に合わせる</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">色・脈表記・介護整体列が入力画面と揃っていなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>状態色・脈（）表記・介護整体列を入力画面と統一。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">61bb967</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"氏名検索の月一覧を提供記録入力と同じ表形式に検索結果がテキスト一覧で入力画面と見え方が違った。同じ列構成の表にし、行タップで当日入力へジャンプ。提供記録02e699d\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">氏名検索の月一覧を提供記録入力と同じ表形式に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">検索結果がテキスト一覧で入力画面と見え方が違った。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>同じ列構成の表にし、行タップで当日入力へジャンプ。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">02e699d</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"分析個人の公開範囲：モニタリングはケアマネのみ・特記は本人に非表示ナイーブな臨床所見が本人・家族に見えていた。モニタリングはケアマネ限定、今回の様子・特記は本人に非表示（家族は可）。家族アプリ9b642fa\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">分析個人の公開範囲：モニタリングはケアマネのみ・特記は本人に非表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">ナイーブな臨床所見が本人・家族に見えていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>モニタリングはケアマネ限定、今回の様子・特記は本人に非表示（家族は可）。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9b642fa</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"氏名検索一覧に運動の数値も表示状態・バイタルのみで運動が確認できなかった。各運動項目の記録値を一覧に追加。提供記録35874fe\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">氏名検索一覧に運動の数値も表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">状態・バイタルのみで運動が確認できなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>各運動項目の記録値を一覧に追加。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">35874fe</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"提供記録入力：氏名検索でその月の利用日を全て表示検索しても当日のロスターしか出ず、来所しない人は表示されなかった。その月の利用日を一覧化し、行タップで当日入力へ。提供記録34725e7\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">提供記録入力：氏名検索でその月の利用日を全て表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">検索しても当日のロスターしか出ず、来所しない人は表示されなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>その月の利用日を一覧化し、行タップで当日入力へ。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">34725e7</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析\" data-text=\"欠席理由ランキング：振替側に後から書いた理由も拾う欠席側にしか理由を見に行かず、振替側に追記した理由が集計に反映されなかった。対の振替側レコードの理由も拾って集計。分析10e2b70\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">欠席理由ランキング：振替側に後から書いた理由も拾う</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">欠席側にしか理由を見に行かず、振替側に追記した理由が集計に反映されなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>対の振替側レコードの理由も拾って集計。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">10e2b70</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析\" data-text=\"欠席理由ランキング：振替の日付表記でなく実際の理由で集計振替の欠席理由が「○月○日へ振替」の文字列丸ごとで集計され、日付が理由として並んでいた。括弧内の実際の理由で集計し、語尾ゆらぎもまとめた。分析bb991c2\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">欠席理由ランキング：振替の日付表記でなく実際の理由で集計</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">振替の欠席理由が「○月○日へ振替」の文字列丸ごとで集計され、日付が理由として並んでいた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>括弧内の実際の理由で集計し、語尾ゆらぎもまとめた。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">bb991c2</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"管理局\" data-text=\"管理局から設定したアドオンが巻き戻る不具合を修正読んでから書く構造で連続操作が消え、項目単位の時刻更新も無く店舗端末の保存で巻き戻っていた。cas（楽観ロック）内で完結させ、時刻も更新。管理局a1792d3\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">管理局</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">管理局から設定したアドオンが巻き戻る不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">読んでから書く構造で連続操作が消え、項目単位の時刻更新も無く店舗端末の保存で巻き戻っていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>CAS（楽観ロック）内で完結させ、時刻も更新。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a1792d3</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"単位欄の既定値を廃止し、例示が見切れないよう幅を拡大個別運動の追加行に既定値『回』が入り、単位の違う種目でも残っていた。例示も見切れていた。既定値を廃止して例示表示に。入力欄の幅を拡大。各種設定99bc709\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">単位欄の既定値を廃止し、例示が見切れないよう幅を拡大</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">個別運動の追加行に既定値『回』が入り、単位の違う種目でも残っていた。例示も見切れていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>既定値を廃止して例示表示に。入力欄の幅を拡大。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">99bc709</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"提供記録は空欄なのに連絡帳に古いバイタルが出る不具合を修正派生値（プレーンのバイタル）を独立にマージし、非空優先のため一度入った値が消せなかった。マージ後にam/pmから射影し直し、空欄なら空欄に。同期5f906e8\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">提供記録は空欄なのに連絡帳に古いバイタルが出る不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">派生値（プレーンのバイタル）を独立にマージし、非空優先のため一度入った値が消せなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>マージ後にAM/PMから射影し直し、空欄なら空欄に。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5f906e8</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"認定有効期間だけの更新も変更履歴に残す値が同じで期間だけ更新した場合が履歴に残らなかった。開始日が変われば「認定更新」として履歴に記録（3経路統一）。利用者マスタeea97e5\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">認定有効期間だけの更新も変更履歴に残す</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">値が同じで期間だけ更新した場合が履歴に残らなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>開始日が変われば「認定更新」として履歴に記録（3経路統一）。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">eea97e5</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"同期\" data-text=\"書類削除を1回で確定・次回予定は編集した項目だけ保存書類削除がpullで復活。次回予定は全員分の計算値が書き込まれ全員が変更済みになっていた。個人ファイル表示中はpull停止＋墓石尊重。次回予定は変更項目のみ保存。同期b4a3a62\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">書類削除を1回で確定・次回予定は編集した項目だけ保存</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">書類削除がpullで復活。次回予定は全員分の計算値が書き込まれ全員が変更済みになっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>個人ファイル表示中はpull停止＋墓石尊重。次回予定は変更項目のみ保存。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b4a3a62</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳の次回予定：欠席の日を飛ばし振替を優先月間シフトのみ見て提供記録の欠席を見ておらず、欠席日のまま表示されていた。提供記録を優先し、欠席は飛ばし振替を優先。連絡帳bffc945\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">連絡帳の次回予定：欠席の日を飛ばし振替を優先</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">月間シフトのみ見て提供記録の欠席を見ておらず、欠席日のまま表示されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>提供記録を優先し、欠席は飛ばし振替を優先。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">bffc945</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"各種設定の変更が4秒後に巻き戻る不具合を修正クラウド取得（pull）が丸ごと置換で、保存完了前の4秒ポーリングが古い値で上書きしていた。設定を項目単位の時刻で保持し、他端末の変更は潰さない。同期b907b77\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">各種設定の変更が4秒後に巻き戻る不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">クラウド取得（pull）が丸ごと置換で、保存完了前の4秒ポーリングが古い値で上書きしていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>設定を項目単位の時刻で保持し、他端末の変更は潰さない。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b907b77</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"変更履歴タブが開けないエラーを修正（info is not defined）アイコンを未importで使用し、タブを開くと画面全体がエラーになった。import済みアイコンに差し替え。全jsxの未importを機械検査。利用者マスタ5f48438\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">変更履歴タブが開けないエラーを修正（Info is not defined）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">アイコンを未importで使用し、タブを開くと画面全体がエラーになった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>import済みアイコンに差し替え。全JSXの未importを機械検査。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5f48438</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"介護度/負担割合/ケアマネの変更履歴を入力1か所から自動記録直接編集しても変更履歴・支援経過表に反映されず、二重入力が同期漏れの温床だった。入力起点を基本情報に統一し、履歴と支援経過表へ自動記録。利用者マスタe8fe1de\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">介護度/負担割合/ケアマネの変更履歴を入力1か所から自動記録</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">直接編集しても変更履歴・支援経過表に反映されず、二重入力が同期漏れの温床だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>入力起点を基本情報に統一し、履歴と支援経過表へ自動記録。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e8fe1de</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"書類（保険証/負担割合証）の削除が復活する不具合を修正id単位の和集合マージで削除が表現できず、クラウドの残存で必ず復活していた。墓石（削除記録）を導入し、両端末で合算して復活を防止。同期3843f08\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">書類（保険証/負担割合証）の削除が復活する不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">id単位の和集合マージで削除が表現できず、クラウドの残存で必ず復活していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>墓石（削除記録）を導入し、両端末で合算して復活を防止。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3843f08</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"計画書\" data-text=\"通所介護計画書：印刷の行高さ・列幅を修正、入力を自動化セル書式のpre-wrapで改行が余白として描画され行が異常に高く、列幅指定も効いていなかった。書式を分離し、colgroupで列幅を効かせ、入力の自動化を追加。計画書75dbd58\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">通所介護計画書：印刷の行高さ・列幅を修正、入力を自動化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">セル書式のpre-wrapで改行が余白として描画され行が異常に高く、列幅指定も効いていなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>書式を分離し、colgroupで列幅を効かせ、入力の自動化を追加。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">75dbd58</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"計画書\" data-text=\"通所介護計画書を厚労省 別紙様式3-4 準拠に刷新独自レイアウトで公的様式と構造が違い、a4に収まっていなかった。別紙様式3-4準拠に作り直し、a4 1枚で使い切る構成に。計画書e60fc54\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">通所介護計画書を厚労省 別紙様式3-4 準拠に刷新</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">独自レイアウトで公的様式と構造が違い、A4に収まっていなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>別紙様式3-4準拠に作り直し、A4 1枚で使い切る構成に。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e60fc54</span></span></div>\n    </article>\n  </div>\n  <section class=\"block\"><h2>未対応・今後の予定</h2><p class=\"lead\">まだ着手していない、または継続中の項目です。優先度は事業インパクト順。</p><div class=\"todo\" id=\"todo\">\n  <div class=\"titem\"><span class=\"st plan\">予定</span><div class=\"body\"><b>操作ログ同期の第2段（受信適用と旧方式の凍結）</b><span>現在は第1段＝「送信のみ」。診断ログで ops-queued→ops-acked が安定して出ることを確認できたら、OPLOG_APPLY と OPLOG_FROZEN_KEYS を有効にして切替を完了する。その後フェーズ5（DB側での操作ログ畳み込みと刈り取り）を追加する。</span></div><span class=\"prio\">優先度：最優先</span></div>\n  <div class=\"titem\"><span class=\"st hold\">構想</span><div class=\"body\"><b>認証基盤の是正（Supabase Auth 未使用）</b><span>職員ログインが staff テーブルへのSELECT照合のみでJWTを発行しておらず、全アクセスがanonロール。anon keyはJSバンドルから誰でも取得できるため、RLSを書いても店舗ごとの分離をDB側で強制できない。介護記録は要配慮個人情報にあたるため、同期刷新の完了後に着手する（放置ではなく延期）。</span></div><span class=\"prio\">優先度：高（同期刷新の次）</span></div>\n  <div class=\"titem\"><span class=\"st plan\">予定</span><div class=\"body\"><b>実績記録票のCSV出力 → 格安/無料の請求ソフトへ連携</b><span>収益に最短で効く本命。連携先ソフトのCSV形式が分かれば着手可能。</span></div><span class=\"prio\">優先度：最優先</span></div>\n  <div class=\"titem\"><span class=\"st plan\">予定</span><div class=\"body\"><b>国保連請求データのCSV生成</b><span>介護給付費請求書等インターフェース仕様書（最新版）に準拠して生成。テスト伝送での検証が必須。</span></div><span class=\"prio\">優先度：高</span></div>\n  <div class=\"titem\"><span class=\"st plan\">予定</span><div class=\"body\"><b>LIFE加算のCSV出力・提出</b><span>LIFEの公式CSV連携仕様に沿って出力。実データでのアップロード検証が必要。</span></div><span class=\"prio\">優先度：高</span></div>\n  <div class=\"titem\"><span class=\"st hold\">構想</span><div class=\"body\"><b>モニタリング自動FAX（丸投げ君 代替）の仕上げ</b><span>FAX API・モニタリング表は実装済み。運用の詰めを残す。</span></div><span class=\"prio\">優先度：中</span></div>\n  <div class=\"titem\"><span class=\"st hold\">構想</span><div class=\"body\"><b>ケアプラン写真/PDFの取り込み → 計画書へ転記</b><span>OCR/貼り付けで目標以外の転記を省力化する構想。</span></div><span class=\"prio\">優先度：中</span></div>\n  <div class=\"titem\"><span class=\"st hold\">構想</span><div class=\"body\"><b>勤務表を日誌データから自動作成</b><span>手入力に加え、日誌の出勤・送迎・記録者から実績を自動生成。</span></div><span class=\"prio\">優先度：低</span></div>\n  <div class=\"titem\"><span class=\"st plan\">予定</span><div class=\"body\"><b>計画書の残作業（個別3-3のカレンダー化 等）</b><span>通所で入れた一時保存・カレンダーを個別機能訓練計画書にも展開。</span></div><span class=\"prio\">優先度：中</span></div>\n    </div></section>\n  <section class=\"block\"><h2>請求・LIFE実装に必要な資料</h2><p class=\"lead\">実績→請求／LIFE加算の実装を正確に進めるために、そろえていただきたい資料です。</p><div class=\"docs\" id=\"docs\">\n  <div class=\"doc\"><p class=\"h\"><span class=\"n\">1</span>介護給付費請求 CSVインターフェース仕様書</p><ul><li>国保中央会が定める請求データの公式仕様（最新版）</li><li>明細書・給付管理票のレコード様式</li><li>エラーコード一覧</li></ul><p class=\"note\">これがあれば「つむぎのどのデータをどう並べるか」を具体設計できます。</p></div>\n  <div class=\"doc\"><p class=\"h\"><span class=\"n\">2</span>LIFE CSV連携仕様書</p><ul><li>厚労省/LIFEが公開するCSVレイアウト</li><li>科学的介護推進・個別機能訓練加算 の項目定義</li><li>コード表（評価区分・選択肢の数値）</li></ul><p class=\"note\">LIFEは細部が厳格。実データでのアップロード検証を前提に。</p></div>\n  <div class=\"doc\"><p class=\"h\"><span class=\"n\">3</span>現行ソフトの出力サンプル</p><ul><li>カイポケ：実績記録票・請求明細書・給付管理票のPDF</li><li>マルットライフ：LIFE提出用CSV/PDF</li><li>丸投げ君：モニタリングFAXの送信様式</li></ul><p class=\"note\">項目を合わせる基準になります。個人情報は伏せた見本で十分です。</p></div>\n  <div class=\"doc\"><p class=\"h\"><span class=\"n\">4</span>連携先の請求ソフト情報</p><ul><li>採用予定の格安/無料 請求ソフト名</li><li>そのソフトが取り込めるCSVの形式・項目</li><li>（あれば）取り込みマニュアル</li></ul><p class=\"note\">連携先が決まればCSVをその形式に合わせて出力します。</p></div>\n    </div></section>\n  <footer>この台帳は開発時のコミット記録（Git）から生成しています。各行末尾の英数字はコミットIDで、変更内容の実体と1対1で対応します。「重大」はデータの消失・巻き戻りに関わる不具合です。</footer>\n</div>\n<script>\n(function(){try{\n  var rows=[].slice.call(document.querySelectorAll('#ledger .row')),cl=document.getElementById('count-line');\n  var st={mode:'all',area:'all',q:''};\n  function match(r){var m=st.mode;var okM=(m==='all')?true:(m==='crit'?r.getAttribute('data-crit')==='1':r.getAttribute('data-kind')===m);return okM&&(st.area==='all'||r.getAttribute('data-area')===st.area)&&(st.q===''||(r.getAttribute('data-text')||'').indexOf(st.q)>=0);}\n  function apply(){var n=0;rows.forEach(function(r){var ok=match(r);r.style.display=ok?'':'none';if(ok)n++;});if(cl)cl.textContent='表示 '+n+' 件 ／ 全 '+rows.length+' 件';[].forEach.call(document.querySelectorAll('[data-mode]'),function(el){el.setAttribute('aria-pressed',el.getAttribute('data-mode')===st.mode?'true':'false');});}\n  function setMode(m){st.mode=(st.mode===m&&m!=='all')?'all':m;apply();}\n  [].forEach.call(document.querySelectorAll('[data-mode]'),function(el){el.addEventListener('click',function(){setMode(el.getAttribute('data-mode'));});});\n  var ac=document.getElementById('area-chips');ac&&ac.addEventListener('click',function(e){var b=e.target.closest&&e.target.closest('[data-area]');if(!b)return;st.area=b.getAttribute('data-area');[].forEach.call(ac.children,function(c){c.setAttribute('aria-pressed',c===b?'true':'false');});apply();});\n  var q=document.getElementById('q');q&&q.addEventListener('input',function(e){st.q=(e.target.value||'').toLowerCase();apply();});\n  apply();\n}catch(err){}})();\n</script>\n\n</body>\n</html>\n";
export default function handler(req, res) {
  const USER = process.env.CHANGELOG_USER || 'tsumugi';
  const PASS = process.env.CHANGELOG_PASS || 'hennkoukiroku';
  const h = req.headers.authorization || '';
  let ok = false;
  if (h.startsWith('Basic ')) { try { const dec = Buffer.from(h.slice(6),'base64').toString('utf8'); const i = dec.indexOf(':'); if (i!==-1 && dec.slice(0,i)===USER && dec.slice(i+1)===PASS) ok=true; } catch(e){} }
  if (!ok) { res.setHeader('WWW-Authenticate','Basic realm="tsumugi", charset="UTF-8"'); res.setHeader('content-type','text/plain; charset=utf-8'); res.status(401).send('認証が必要です / Authentication required'); return; }
  res.setHeader('content-type','text/html; charset=utf-8'); res.setHeader('cache-control','no-store'); res.setHeader('x-robots-tag','noindex, nofollow, noarchive'); res.status(200).send(HTML);
}
